The analytic properties of the class $\mathcal{S}$ are provided in \cite[Proposition 2.2]{hachem2007deterministic}. The following proposition demonstrates the existence and uniqueness of the solutions to the aforementioned fixed-point equations in $\mathcal{S}$.
\begin{proposition}
\label{Prop_exists_unique}
    There exist unique solutions $(\delta_1, \ldots, \delta_n, \widetilde{\delta}_1, \ldots, \widetilde{\delta}_n)$ for \eqref{Eq_DE} with $\delta_j \in \mathcal{S}$ and $\widetilde{\delta}_j \in \mathcal{S}$, $\forall j \in [n]$.
\end{proposition}
\textit{Proof:} The proof of Proposition \ref{Prop_exists_unique} follows the same logic as that in \cite[Lemma 2.4]{hachem2007deterministic}. Here, we provide a proof sketch. The existence of the solution is established by using Picard’s approximation method. More specifically, we rewrite \eqref{Eq_DE} as $(\Bdelta, \widetilde{\Bdelta})$ = $f(\Bdelta, \widetilde{\Bdelta})$, where $\Bdelta = (\delta_1, ..., \delta_n)$ and $\widetilde{\Bdelta} = (\widetilde{\delta}_1, ..., \widetilde{\delta}_n)$. Then, we construct the initial point $(\Bdelta^0, \widetilde{\Bdelta}^0) \in \mathcal{S}^{2n}$, and then proceed inductively to show $(\Bdelta^{k+1}, \widetilde{\Bdelta}^{k+1}) = f(\Bdelta^{k}, \widetilde{\Bdelta}^{k}) \in \mathcal{S}^{2n}$ for each $k$. Furthermore, it can be shown that each element of $(\Bdelta^k, \widetilde{\Bdelta}^k)$ over a certain unbounded domain $\mathbb{D} \subset \mathbb{C}^+$ forms a Cauchy sequence for the sup norm, i.e., $\norm{f}_{\infty} = \sup_{z \in \mathbb{D}} |f(z)|$. Consequently, we denote  $(\Bdelta, \widetilde{\Bdelta}) = \lim_{k \to \infty}(\Bdelta^k, \widetilde{\Bdelta}^k)$ as the corresponding limit over $\mathbb{D}$. Since each element of $\Bdelta^k$ and $\widetilde{\Bdelta}^k$ is bounded on any compact subset of $\mathbb{C}^+$, the normal family theorem \cite{rudin1987real} and the properties of the Stieltjes transform \cite[Proposition 2.2]{hachem2007deterministic} imply that $(\Bdelta, \widetilde{\Bdelta}) \in \mathcal{S}^{2n}$. This establishes the existence of the solutions. The uniqueness assertion follows by assuming the existence of two distinct solutions, taking their difference, and deriving a contradiction. \qed
\begin{remark}
\label{Rem_iteration}
The proof demonstrates that the numerical solution for 
$\delta_j(z), \widetilde{\delta}_j(z)$ with a given $z \in \mathbb{C}^+$ can be obtained by using the classical fixed-point iteration algorithm. We note that for any $m \in \mathcal{S}$, the corresponding measure $\mu$ is supported on $\mathbb{R}^+$. Therefore, the Stieltjes transform $m(z)$ can be analytically extended to $z \in (-\infty, 0)$. Given the solutions $(\Bdelta, \widetilde{\Bdelta}) \in \mathcal{S}^{2n}$, the same iterative algorithm can be used to evaluate the values of $(\Bdelta(z), \widetilde{\Bdelta}(z))$ over $z \in (-\infty, 0)$.
\end{remark}
In the following, when we refer to the fixed-point system of equations \eqref{Eq_DE} and \eqref{Eq_DE_1}, we assume the unique solution described in Proposition \ref{Prop_exists_unique} without further distinction.
\par
\subsection{Weak Convergence of $F^{\BS, n}$}
It is well established that the vague convergence \cite{bai2010spectral} of a family of measures is equivalent to the pointwise convergence of their corresponding Stieltjes transforms on $\mathbb{C}^+$. The following theorem demonstrates the deterministic approximations for the trace and bilinear forms of $\BQ(z)$.
\begin{theorem}
\label{Thm_conver_ESD}
Assume Assumptions \ref{Assumpt_1}-\ref{Assumpt_4} hold. Then, for given $z \in \mathbb{C^+}$, we have, as $n \to \infty$, 
\begin{equation}
    \frac{1}{p} \Tr\BC\left[\BQ(z) - \BTheta(z)\right]\xrightarrow{a.s.} 0, ~~  \Bu^H \left[\BQ(z) - \BTheta(z)\right] \Bv \xrightarrow{a.s.} 0, \label{Eq_Thm1_Conv_Resolvent}
\end{equation}
where $\BC \in \mathbb{C}^{p \times p}$ is a deterministic matrix with bounded spectral norm, i.e., $\limsup_n \norm{\BC} < \infty$, and $\Bu \in \mathbb{C}^p$ and $\Bv \in \mathbb{C}^p$  are deterministic vectors with bounded Euclidean norm, i.e., $\limsup_n\max\{ \norm{\Bu}, \norm{\Bv} \}  < \infty$.
\end{theorem}
\textit{Proof:} The proof of Theorem \ref{Thm_conver_ESD} is given in Appendix \ref{App_Converge_resolvent}. \qed
\par
Denote $m_n(z) = \Tr \BTheta(z) / p$. It can be verified that $m_n(z) \in \mathcal{S}$ with the integration representation $m_n(z) = \int_{\mathbb{R}^+} \frac{F^n(\dd \lambda)}{\lambda - z}$. By letting $\BC = \BI_p$ in Theorem \ref{Thm_conver_ESD}, we have $m_{\BS, n}(z) - m_n(z) \to 0$ almost surely. Due to the complex correlation structure and the existence of the mean, the Stieltjes transform $m_n(z)$ may not converge as $n \to \infty$. As a result, the limiting distribution may not exist. However, we have the following ``convergence in distribution" property. Specifically, following Lemma \ref{Lemm_Bound_on_qterms} and the same method as in the proof of \cite[Corollary 2.7]{hachem2007deterministic}, we have 
\begin{equation}
    \int_{0}^{\infty} f(\lambda) F^{\BS, n}(\dd \lambda)- \int_{0}^{\infty} f(\lambda) F^n(\dd \lambda)\xrightarrow{a.s.} 0, \label{Eq_ESD_LSD_convergence}
\end{equation}
for any bounded continuous function $f: \mathbb{R}^+ \to \mathbb{R}$.  Without causing any ambiguity, we call $F^n$ the LSD in this work. 
\begin{remark}
To prove the convergence of \eqref{Eq_ESD_LSD_convergence}, only the convergence of the trace form for the resolvent is needed. Write the eigen-decomposition of $\BS$ as $\BU_S \diag({\lambda_i ; 1 \leq i \leq p}) \BU_S^H$ and denote $ f(\BS) = \BU_S \diag({f(\lambda_i) ;1 \leq  i \leq p}) \BU_S^H$. \eqref{Eq_ESD_LSD_convergence} implies that
$
   \Tr f(\BS) / p = \sum_{j=1}^p [f(\BS)]_{j, j} / p
$
, i.e., the average of the diagonal elements of $f(\BS)$, will converge. However, this result does not imply the convergence of the specific elements $[f(\BS)]_{i, j}$, which requires the convergence of the bilinear form of the resolvent \cite{nagel2021functional}. The bilinear forms of the resolvent are also useful for the study of the eigenvectors for the covariance matrix $\BS$ \cite{hachem2013bilinear, BAIK2006spiked, couillet_liao_2022, Xia2013AoS}. 
\end{remark}
\begin{remark}
    The convergence in \eqref{Eq_Thm1_Conv_Resolvent} also holds for $z \in (-\infty, 0)$.
\end{remark}
 Next, we show that under specific conditions on the statistics of $\BA$ and ${\BOmega_j}$, the limit of $F^n$ exists. The details are provided in the following corollary.
\begin{corollary}
\label{Coro_variance profile}
 Assume $\lim_{n \to \infty} p / n = c \in (0, + \infty)$ and Assumption \ref{Assumpt_2} holds. Assume that $\{ \BOmega_j\}_{j \leq n}$ are simultaneously diagonalizable with the eigen-decomposition $\BOmega_j = \BU \mathrm{diag}(\lambda_{jl}(n); l \leq p) \BU^H$, and $\BA$ has the same left singular vectors as $\BOmega_j$ with $\BA = \BU \mathrm{rect}\text{-}\mathrm{diag}(\sigma_j(n); j\leq \min(p, n)) \BI_n$. Further, assume the eigenvalues $\{ \lambda_{jl}(n)\}_{l \leq p, j \leq n}$ and the singular values $\{ \sigma_j(n)\}_{j \leq \min(p, n)}$ can be parameterized by 
 \begin{equation}
    \lambda_{jl}(n) = f_{\Omega}(l / p, j / n), ~~ \sigma_j(n) = f_A(j / p)  = \widetilde{f}_A(j / p) \Ind_{\{ j / p \leq \min(1, c^{-1}) \}},
\end{equation}
where $f_{\Omega} > 0$ and $\widetilde{f}_A$ are  bounded continuous functions. Then, the functional system of equations
\begin{align}
    \tau(a, z) &= \left[ {-z\left(1 +  \int_{0}^1 f_{\Omega}(a, u) \widetilde{\tau}(u, z) \dd u \right) + \frac{f^2_A(a)}{1 + c\int_{0}^1 f_{\Omega}(x, a)\tau(x, z) \dd x}} \right]^{-1} , \\
    \widetilde{\tau}(b, z) &= \left[ -z\left(1 + c\int_{0}^1f_{\Omega}(y, b) \tau(y, z) \dd y\right) + \frac{f^2_A(b / c)}{1 +   \int_{0}^1 f_{\Omega}(b, v) \widetilde{\tau}(v, z) \dd v} \right]^{-1},
\end{align}
admits unique function solutions $\Lambda: [0, 1] \times \mathbb{C}^+ \to \C^+$  such that $u \mapsto \Lambda(u, z)$ is continuous and $z \mapsto \Lambda(u, z) \in \mathcal{S}$, where $\Lambda$ is any of $\tau$ and $\widetilde{\tau}$. The function $m_{\infty}(z) = \int_{0}^1 \tau(x, z) \dd x$ is the Stieltjes transform of a probability distribution $F^{\infty}$ and there holds
\begin{equation}
    \PP \left( F^{\BS, n} \Rightarrow F^{\infty} \right) = 1.
\end{equation}
\end{corollary}
\textit{Proof:} The proof is a direct application of Theorem \ref{Thm_conver_ESD} and is omitted here for brevity. \qed
\begin{remark}
    When $\{ \BOmega_j \}_{j \leq n}$ are diagonal and $\BA$ is rectangular diagonal, i.e., $\BU = \BI_p$, Corollary \ref{Coro_variance profile} degenerates to \cite[Theorem 2.3]{hachem2006varianceprofile} and \cite[Theorem 2.5]{hachem2008varianceProfile}. The degeneration indicates that the ESD and the LSD are rotation-invariant.
\end{remark}
