\subsection{No Eigenvalues outside the Support}
The weak convergence in \eqref{Eq_ESD_LSD_convergence} shows that for any interval $[a, b]$, the empirical measure $F^{\BS, n}([a, b])$ converges almost surely to $ F^n([a, b])$. By the definition in \eqref{EQ_ESD_F_S_n}, we have $F^{\BS, n}([a, b]) = (\text{the number of eigenvalues of $\BS$ in } [a, b]) / p$. If we take $[a, b]$ such that $F^n([a, b]) = 0$, Theorem \ref{Thm_conver_ESD} indicates that $F^{\BS, n}([a, b]) = o_{a.s.}(1)$. Intuitively, the weak convergence of $F^{\BS, n}$ will not be affected if finite empirical eigenvalues appear in $[a, b]$. In this section, we will prove that such appearance will not happen, i.e., the order of $F^{\BS, n}([a, b])$ is $o_{a.s.}(1/n)$.  To this end, we need more analytical properties of the solutions $\{ \delta_j \}, \{ \widetilde{\delta}_j \}$, which are given in the following assumption.
\begin{assumption}
\label{Assumpt_5}
    For all $x \in \mathbb{R}_*$, the limits $\lim_{z \in \mathbb{C}^+ \to x} m_n(z)$, $\lim_{z \in \mathbb{C}^+ \to x} \delta_j(z)$, and $\lim_{z \in \mathbb{C}^+ \to x} \widetilde{\delta}_j(z)$ exist for each $j \in [n]$.
\end{assumption}
% \begin{assumption}
% \label{Assumpt_5}
%     For all $x \in \mathbb{R} - \{0\}$, the limits $\lim_{z \in \mathbb{C}^+ \to x} m(z)$, $\lim_{z \in \mathbb{C}^+ \to x} \delta_j(z)$ and $\lim_{z \in \mathbb{C}^+ \to x} \widetilde{\delta}_j(z)$ exist for each $j \in [n]$.
% \end{assumption}
\begin{remark}
    This assumption holds in many cases. For instance, in \cite{silverstein1995analysis}, Silverstein \textit{et al.} proved the existence of these limits when $\BA = \Bzero_{p \times n}$ and $\BB_j = \BT^{1/2}$, $\forall j \in [n]$. In \cite{couillet2014analysis}, Couillet et al. performed the same study for the separable correlated random matrix model with $\BA = \Bzero_{p \times n}$, and $\BB_j = \sqrt{{\tau}_j} \BT^{1/2} $ in \eqref{Eq_DE}.   In \cite{Dozier2007analysis}, Dozier et al. established the case for the information-plus-noise model with $\BOmega_j = \sigma^2 \BI_p$. In \cite{zhou2024analysis}, Zhou \textit{et al.} proved the existence of the limits for the information-plus-noise model with $\BB_j = \BT^{1/2}$, $\forall j \in [n]$, under the assumption
    that matrices $\BT$ and $\BA\BA^H$ are commutative. We make this assumption here for technical convenience. We note that this assumption is possibly provable and leave the proof as a future study.
\end{remark}
For notational simplicity, we define the limits in Assumption \ref{Assumpt_5} as $m_n(x)$, $\delta_j(x)$, and $\widetilde{\delta}_j(x)$, respectively.
Denote the underline measure of $\delta_j(z)$ and $\widetilde{\delta}_j(z)$ as $\mu_j$ and $\widetilde{\mu}_j$, $j \in [n]$, respectively. By \cite[Lemma B.10]{bai2010spectral}, the distribution function $\mu_j([0, x])$, $\widetilde{\mu}_j([0, x])$, and $F^n(x)$ are differentiable at $x$ when Assumption \ref{Assumpt_5} holds, and their derivatives are given by $\frac{1}{\pi} \Im (m_n(x))$, $\frac{1}{\pi} \Im (\delta_j(x))$, and $\frac{1}{\pi}\Im(\widetilde{\delta}_j(x))$, respectively.  The following proposition reveals the relationship between the supports of $\mu_j$, $\widetilde{\mu}_j$, and $F^n$, which are necessary for the proof of Theorem \ref{Thm_No_Eigenvalues}.
\begin{proposition}
\label{Prop_same_support}
    Assume Assumptions \ref{Assumpt_1}, \ref{Assumpt_3}-\ref{Assumpt_5} hold. Then, the supports of the measures $\{ \mu_j \}_{1 \leq j \leq n}$ and $\{ \widetilde{\mu}_j \}_{1 \leq j\leq n}$ are subsets of the support of $F^n$ on $\R_*$, that is
    \begin{equation}
        \left( \mathsf{Supp}(\mu_j ) \cap \R_* \right) \subset \left( \mathsf{Supp}(F^n)   \cap \R_*\right), ~~ \left( \mathsf{Supp}(\widetilde{\mu}_j) \cap \R_* \right) \subset \left( \mathsf{Supp}(F^n)   \cap \R_* \right), ~~ \forall j \in [n].
    \end{equation}
\end{proposition}
\textit{Proof:} The proof is given in Appendix \ref{App_Proof_Prop_same_support}. \qed

\begin{remark} 
    An interesting case is when the supports of these measures are identical. In fact, we can release the left hand side (LHS) of the inequality \eqref{Eq_Assumpt_3} in Assumption \ref{Assumpt_3} to
      \begin{equation}
    0 < \liminf_{n \to \infty} \min_{1 \leq j \leq n} \lambda_{\min}(\BOmega_j), \label{Eq_Enhanced_Eq_3}
    \end{equation}  
    where $\lambda_{\min}(\BOmega)$ denotes the minimal eigenvalue of $\BOmega$. With the above condition, it holds that
    \begin{equation}
         \left( \mathsf{Supp}(F^n)   \cap \R_*\right) = \left( \mathsf{Supp}(\mu_j ) \cap \R_* \right) = \left( \mathsf{Supp}(\widetilde{\mu}_j)   \cap \R_* \right), ~~ \forall j \in [n].
    \end{equation}
\end{remark}
The following theorem shows the no-eigenvalue property for the generally correlated and noncentral covariance matrices. 
\begin{theorem}
\label{Thm_No_Eigenvalues}
    Assume Assumptions \ref{Assumpt_1}-\ref{Assumpt_5} hold. Let $[a, b]$ with $a > 0$ lie in an open interval outside $ \mathsf{Supp}(F^n)$ for all large $n$ and satisfy the condition $\liminf_{n \to \infty} \inf_{x \in [a, b]} \min_{1 \leq j \leq n} \big\{ |\widetilde{\delta}_j(x)|, |1 + \delta_j(x)| \big\} > 0$.  Then, we have 
    \begin{equation}
    \label{Eq_P_no_eigens}
        \PP \left[ \text{no eigenvalues of $\mathbf{S}$ appears in $[a, b]$ for all large $n$}  \right] = 1.
    \end{equation}
\end{theorem}
Theorem \ref{Thm_No_Eigenvalues} demonstrates that there exists a sufficiently large positive integer $N$ such that for any $n > N$, the eigenvalues of  $\BS$ cannot be located in the interval $[a, b]$.
\par
\textit{Proof:} Since the proof of Theorem \ref{Thm_No_Eigenvalues} is quite lengthy and involves many steps, we provide the main flow of the proof as follows:
\begin{itemize}
    \item []\textit{Step 1:}  Simplifying Assumption \ref{Assumpt_2} to get the equivalent model. In particular, without changing the asymptotic locations of the eigenvalues of $\BS$, it suffices to truncate the random variables $\{X_{ij}\}$. The details of this step are given in Appendix \ref{App_Trunc}.
    \item []\textit{Step 2:} With the simplified model, we evaluate the convergence of the resolvent. Specifically, we will show that for $z = x + j v$ with $v = n^{-\alpha / 912}$, and $\alpha = \frac{\varepsilon}{8 + 2\varepsilon}$ (The coefficient 912 comes from the constraints on the speed at which $z$ approaches the real axis in the proof, which may not be minimal), the following holds 
    % \begin{equation}
    % \label{Eq_sup_diff_resolvent}
    %     \sup_{x \in [a, b]} v \abs{\Tr \BQ(z) - \Tr \BTheta(z)} \xrightarrow[n \to \infty]{a.s.} 0, 
    % \end{equation}
    \begin{equation}
    \label{Eq_sup_diff_resolvent}
        \sup_{x \in [a, b]} vp \abs{m_{\BS, n}(z) - m_n(z)} \xrightarrow[n \to \infty]{a.s.} 0. 
    \end{equation}
     The details of the proof are given in Appendix \ref{App_Proof_Thm_noeigen}.
    \item []\textit{Step 3:} In the last step, we will prove \eqref{Eq_P_no_eigens}  by \eqref{Eq_sup_diff_resolvent}.
\end{itemize}
Next, we show \textit{Step 3}, which is similar to the procedure in \cite[Section 6]{bai1998no}. Denote $\beta = \alpha / 912$. Since $p = \frac{p}{n} n = \frac{p}{n} v^{-\frac{1}{\beta}}$ and $\liminf \frac{p}{n} > 0$, equation \eqref{Eq_sup_diff_resolvent} implies 
\begin{equation}
    \max_{k \in [N_0]}v^{1 - \frac{1}{\beta}} \sup_{x \in [a, b]} \abs{m_{\BS, n}(x + \jmath \sqrt{k}v) - m_{n}(x + \jmath \sqrt{k}v)} \xrightarrow[n \to \infty]{a.s.} 0,
\end{equation}
where $N_0$ is an integer such that $N_0 \geq 1/{(2\beta)}$. Taking the imaginary part of $m_{\BS, n}(x + \jmath \sqrt{k}v) - m_{n}(x + \jmath \sqrt{k}v)$, we have 
\begin{equation}
    \max_{k \in [N_0]}v^{2 - \frac{1}{\beta}} \sup_{x \in [a, b]} \abs{\int\frac{ (F^{\BS, n} - F^n)(\dd \lambda)}{(x - \lambda)^2 + kv^2}} \xrightarrow[n \to \infty]{a.s.} 0.
\end{equation}
Denote $L(k) = \int\frac{ (F^{\BS, n} - F^n)(\dd \lambda)}{(x - \lambda)^2 + kv^2}$. By taking the difference $L(k_1) - L(k_2)$, we can get
\begin{equation}
    \max_{k_1 \neq k_2 }v^{4 - \frac{1}{\beta}} \sup_{x \in [a, b]} \abs{\int\frac{ (F^{\BS, n}- F^n)(\dd \lambda)}{\left[(x - \lambda)^2 + k_1v^2\right]\left[(x - \lambda)^2 + k_2v^2\right]}} \xrightarrow[n \to \infty]{a.s.} 0.
\end{equation}
 By repeating the differencing process, we can obtain
 \begin{equation}
    v^{{2N_0} - \frac{1}{\beta}} \sup_{x \in [a, b]} \abs{\int\frac{ (F^{\BS, n}- F^n)(\dd \lambda)}{\prod_{k=1}^{N_0}\left[(x - \lambda)^2 + kv^2\right]}} \xrightarrow[n \to \infty]{a.s.} 0.
\end{equation}
Since $[a, b]$ lies in an open interval outside $\mathsf{Supp}(F^n)$, there exist $a' < a$ and $b' > b$ such that $[a', b']$ is outside $\mathsf{Supp}(F^n)$ for all large $n$. Splitting the integration interval and using $p = v^{-1/\beta}$, we have 
 \begin{equation}
     \sup_{x \in [a, b]} \abs{\int\frac{ v^{{2N_0} - \frac{1}{\beta}}\Ind_{[a', b']^c} (F^{\BS, n}- F^n)(\dd \lambda)}{\prod_{k=1}^{N_0}\left[(x - \lambda)^2 + kv^2\right]} + \sum_{\lambda_j \in [a', b']} \frac{v^{2N_0}}{\prod_{k=1}^{N_0}\left[(x - \lambda_j)^2 + kv^2\right]}} \xrightarrow[n \to \infty]{a.s.} 0. \label{Eq_sup_ab_Diff_FS_Fn}
\end{equation}
We write the LHS of \eqref{Eq_sup_ab_Diff_FS_Fn} as $\sup_{x \in [a, b]}\abs{A(x) + B(x)}$. By the weak convergence in \eqref{Eq_ESD_LSD_convergence}, we have $\sup_{x \in [a, b]} |A(x)| \to 0$ almost surely. If there is at least one eigenvalue in the interval $[a, b]$, then $B(x)$ is uniformly bounded away from 0, which leads to a contradiction. Therefore, \eqref{Eq_P_no_eigens} is proved. \qed
