\begin{remark}
The condition $\liminf_{n \to \infty} \inf_{x \in [a, b]} \min_{j \leq n} \big\{ |\widetilde{\delta}_j(x)|, |1 + \delta_j(x)| \big\} > 0$ is not necessary in many cases. In \cite{Bai2025noeigen}, Bai \textit{et al.} proved that this condition holds uniformly for $x > 0$ for the noncentral model with $\BOmega_j = \BT$, where matrices $\BT$ and $\BA\BA^H$ are commutative. Additionally, if $\BA = \mathbf{0}_{p \times n}$, it can also be shown that this condition is satisfied uniformly.  Intuitively, $\{ \delta_j(z) \}_{j \leq n}$ and $\{ \widetilde{\delta}_j(z) \}_{j \leq n}$ are continuous functions. When $x$ is larger than the right endpoint of $\mathsf{Supp}(F^n)$, we have $\Re(\delta_j(z)), \Re(\widetilde{\delta}_j(z)) < 0$, $\lim_{x \to \infty} \Re(\delta_j(z)) = 0$, and $\lim_{x \to \infty} \Re(\widetilde{\delta}_j(z)) = 0$. Similarly, when $x$ is smaller than the left endpoint of $\mathsf{Supp}(F^n)$, we have $|\Re (\delta_j(z))|, |\Re(\widetilde{\delta}_j(z))| > 0$. Therefore, the number of zeros for $|1 + \delta_j(z)| = 0$ and $\widetilde{\delta}_j(z) = 0$ is limited. Furthermore, this condition can be verified numerically by Remark \ref{Rem_iteration}. 
\end{remark}
\begin{remark}
    In the fields of signal detection and statistical inference, many subspace-based algorithms involve integrals of the resolvent in the following form  \cite{couillet_liao_2022, hachem2013bilinear}
    \begin{equation}
        \int_{\mathcal{C}^+} f(z) \digamma[\BQ(z)] \dd z, \label{Eq_integral_Resolvent}
    \end{equation}
    where $\digamma(\cdot)$ is a linear operator that can have the form of $ \frac{1}{p} \Tr \BC (\cdot) $ or $ \Bu^H(\cdot) \Bv $, and $\mathcal{C}^{+}$ is typically the pre-selected positive contour that includes the eigenvalues corresponding to the signal subspace. Theorem \ref{Thm_No_Eigenvalues} provides theoretical guarantees for these algorithms that the contour is almost surely valid. Moreover, a surprising phenomenon in random matrix theory is that the central limit theorem (CLT) for LSS holds \cite{Bai2004CLTaop}. In the key step of the proof in \cite{Bai2004CLTaop}, \eqref{Eq_integral_Resolvent} was used, where $\mathcal{C}^+$ was chosen as the contour that includes the entire support. Theorem \ref{Thm_No_Eigenvalues} also provides a theoretical foundation for the analysis of the LSS for generally correlated and noncentral random matrices.
\end{remark}
A direct application of Theorem \ref{Thm_No_Eigenvalues} is bounding the spectral norm of the sample covariance $\BS$, which is stated in the following corollary.
\begin{corollary}
\label{Coro_largest_eigenvalue}
    Denote the right endpoint of $\mathsf{Supp}(F^n) \cap \R_* $ as $e_n^+$. If 
    $
     \limsup_{n \to \infty} e_n^+ < \infty, 
    $
    there exists $E^+ <\infty$ such that
    \begin{equation}
        \PP \left( \limsup_{n \to \infty} \lambda_{\max}(\BS) \leq E^+\right) = 1. \label{Eq_Bound_on_Sp_Norm}
    \end{equation}
    % If $\liminf_{n \to \infty} e_n^- > \infty$, the following holds
    % \begin{equation}
    %     \PP \left( \liminf_{n \to \infty} \lambda_{\min}(\BS) \geq E^- \right) = 1. \label{Eq_Bound_on_Min_eigenvalue}
    % \end{equation}
\end{corollary}
\textit{Proof:} Choose $[a, b]$ such that $a$ is large enough with  $a - e_n^+ \geq  2 \sup_{n, j} \frac{p}{n} \norm{\BOmega_j}$. Then, for $x \in [a, b]$, we have 
\begin{equation}
    \delta_j(x) \overset{(a)}{=} \int_{\R^+}\frac{\mu_j(\dd\lambda)}{\lambda - x} \geq - \frac{\mu_j(\R^+)}{2 \sup_{n, j}\frac{p}{n} \norm{\BOmega_j}}, ~~~ \widetilde{\delta_j}(x) = \int_{\R^+}\frac{\widetilde{\mu}_j(\dd \lambda)}{\lambda - x} \leq  -\frac{\widetilde{\mu}_j(\R^+)}{b}.
\end{equation}
 Here, step $(a)$ follows from the analytic continuation argument and the fact $ \delta_j(z) $ is analytic over $ \mathbb{C}^+$. By the properties of the Stieltjes transform \cite[Proposition 2.2]{hachem2007deterministic}, we have $\mu_j(\R^+) = \frac{1}{n} \Tr \BOmega_j$ and $\widetilde{\mu}_j(\R^+) = 1$, which validate the condition  $\liminf_{n \to \infty} \inf_{x \in [a, b]} \min_{j \leq n} \big\{ |\widetilde{\delta}_j(x)|, |1 + \delta_j(x)| \big\} > 0$.  Due to the arbitrariness of $b$, \eqref{Eq_Bound_on_Sp_Norm} is proved.  \qed
 % The a.s. lower boundedness of $\lambda_{\min}(\BS)$ can be shown in a similar manner. \qed
\begin{remark}
     In \cite{yin1988limit}, it was demonstrated that when $\BA = \Bzero_{p \times n}$, $ \BOmega_j = \BI_p$, and $ \E |X_{11}|^4 < \infty $, the largest eigenvalue of $\BS$ converges to  $(1 + \sqrt{y})^2$ almost surely as $p/n \to y $. The proof in \cite{yin1988limit} first identified the statistical equivalent model, followed by employing the combinatorial method to evaluate the largest eigenvalue by the inequality $ \E \lambda_{\max}^k(\BS)\leq \E\Tr(\BS^k)$. In \cite{BAI19884th}, it was shown that the $4$-th moment condition is the weakest that ensures the largest eigenvalue to be bounded almost surely. However, to prove the boundedness of the largest eigenvalue of the model in \eqref{Eq_random_matrix_Model}, the combinatorial method is not applicable since $\BOmega_j$s can be non-diagonal, leading to a significantly more complex expansion of $ \Tr(\BS^k)$.
\end{remark}
\begin{remark}
In \cite{WagnerMISO2012}, the authors assumed the almost sure boundedness for the spectral norm of $\BS$ to prove the convergence of the resolvent for the covariance of the generally correlated and centered random matrix (refer to Assumption 3 in \cite{WagnerMISO2012}). Corollary \ref{Coro_largest_eigenvalue} specifies the conditions under which this boundedness is valid.
\end{remark}
