\section{Applications}
\label{Sec_applications}
In this section, we apply the main theoretical results to two communication scenarios.
\subsection{SINR Analysis of LMMSE Detection}
\label{Sec_LMMSE_dec}
% \subsection{Multi-User MIMO Detection with Rician Channels}
 Consider a multi-user uplink MIMO system with a base station (BS) equipped with $p$ antennas and $n + 1$ single-antenna users. Denote $x_j \sim \mathcal{CN}(0, 1)$ as the symbol transmitted by the $j$-th user. Then, the received signal $\By \in \mathbb{C}^p$ at the BS is given by
 \begin{equation}
     \By = \sum_{j=0}^n \Bh_j x_j + \Bn,
 \end{equation}
where $\mathbf{n} \sim \mathcal{CN}(0, \sigma^2 \mathbf{I}_p)$ represents the additive white Gaussian noise (AWGN) at the BS and $\Bh_j \in \mathbb{C}^p $ denotes the channel between the $j$-th user and the BS. Consider the Rician channel model \cite{Kammoun2019RZF}
\begin{equation}
    \Bh_j = \sqrt{\frac{1}{1 + \tau}} \BC_j^{1/2} \Bz_j + \sqrt{\frac{\tau}{1 + \tau}} \overline{\Bz}_j, ~~ j \in [n] \cup \{0 \},
    \label{Eq_Rician_model}
\end{equation}
where $\Bz_j \sim \mathcal{CN}(\mathbf{0}_p, \BI_p / n)$ and $\BC_j \in \mathbb{C}^{p \times p}$ is a Hermitian non-negative matrix that models the spatial correlation of the BS antennas with respective to the $j$-th user. $\overline{\Bz}_j \in \mathbb{C}^p$ is a deterministic vector that represents the line-of-sight (LoS) component. The scalar $\tau \geq 0$ is the Rician factor. With perfect channel state information at the receiver, the classical LMMSE estimator for symbol $x_0$ is given by
\begin{equation}
    \widehat{x}_0 = \Bh_0^H\left(\BH\BH^H+ \sigma^2 \BI_p \right)^{-1} \By,
\end{equation}
where $\BH = [\Bh_0, \ldots, \Bh_n]$. Rewrite the received vector as $\By =\Bh_0 x_0 + \By_{0}$ where $\By_{0} = \sum_{i \neq 0} \Bh_i x_i + \Bn$ represents the interference-plus-noise term. Thus, the SINR of the $0$-th user with the LMMSE receiver is given by
\begin{equation}
    \gamma_0 = \frac{ \E_{\Bx, \Bn}|\Bg^H\Bh_0 x_0|^2}{\E_{\Bx, \Bn}|\Bg^H \By_{0} |} = \Bh_0^H\left(\BH_{[0]} \BH_{[0]}^H + \sigma^2 \BI_p \right)^{-1} \Bh_0, \label{Eq_SINR_LMMSE}
\end{equation}
where $\Bg = \left(\BH\BH^H+ \sigma^2 \BI_p \right)^{-1}\Bh_0$  and $\BH_{[0]} = [\Bh_1, \ldots,  \Bh_n]$ is the rank-one perturbation of $\BH$ by removing the first column. As the number of antennas $p$ and the number of users $n$ approach infinity with the same speed, the asymptotic behavior of $\gamma_0$ is interesting, and many results over different channel conditions have been obtained in the literature \cite{Abla2009Ber, Kammoun2009clt, Zhuang2025Decentralized}. However, the asymptotic behavior of $\gamma_0$ over Rician fading channels with heterogeneous spatial correlation is not yet available. The following corollary elucidates this asymptotic behavior.
\begin{corollary} 
\label{Coro_SINR}
Denote $\overline{\BZ} = [\overline{\Bz}_1, \ldots. \overline{\Bz}_n]$. Assume the dimensions $p$ and $n$ grow to infinity with
\begin{itemize}
    \item [1)]  $0 < \liminf_n p / n \leq  \limsup_n p / n < \infty$. 
    \item [2)] $ 0 < \liminf_n \min_{0 \leq j \leq n} \frac{1}{p} \Tr \BC_j \leq \limsup_n \max_{0 \leq j \leq n} \norm{\BC_j} < \infty$.
    \item [3)] $\limsup_n \norm{\left[\overline{\Bz}_0, \overline{\BZ}\right]} < \infty$.
\end{itemize}
Then, we have 
\begin{equation}
    \gamma_0 - \left( \frac{\Tr \BC_0 \BTheta }{n(1 + \tau)} +  \frac{ \tau \overline{\Bz}_0^H \BTheta \overline{\Bz}_0}{1 + \tau}\right) \xrightarrow[n \to \infty]{a.s.} 0,
\end{equation}
where $\BTheta$ is obtained by setting $\BOmega_j = p_j\BC_j / (1 + \tau)$ and $\BA = \overline{\BZ}  \sqrt{\tau}/ \sqrt{1 + \tau}$ in \eqref{Eq_DE}.
\end{corollary}
\textit{Proof:} The proof can be derived from Theorem \ref{Thm_conver_ESD} and follows a similar approach as in \cite{Zhuang2025Decentralized}. Therefore, we omit it here. \qed 
\subsection{The Invertibility of the ZF Precoding Matrix}
Consider a multi-user downlink MIMO system where a BS with $p$ antennas serves $n$ single-antenna users. Denote $\Bg_i \in \mathbb{C}^p$ as the precoding vector associated with the $i$-th user. Then, the received signal $y_j$ of the $j$-th user is given by
\begin{equation}
    y_j = \Bh_j^H \sum_{i=1}^n \Bg_i x_i + n_j, ~~ j \in [n],
\end{equation}
where $x_j \sim \mathcal{CN}(0, 1)$ and $n_j \sim \mathcal{CN}(0 , \sigma^2)$ denote the data symbol intended to the $j$-th user and the AWGN, respectively. $\Bh_j \in\mathbb{C}^p$ denotes the random channel vector from the BS to the $j$-th user and is modeled as \cite{WagnerMISO2012}
\begin{equation}
    \Bh_j = \BC^{1/2}_j \Bz_j ,~~ j \in [n], 
    \label{Eq_Channel_model_rayleigh}
\end{equation}
where $\BC_j \in \mathbb{C}^{p \times p}$ is Hermitian non-negative and $\Bz_j$ is a random vector (not necessarily Gaussian distributed), whose elements are i.i.d. with $\mathbb{E}[\Bz_j]_i = 0$ and $\mathbb{E}|\sqrt{n}[\Bz_j]_i|^2 = 1 $. Furthermore, assume there exists a constant $e > 0 $ such that $\mathbb{E}|\sqrt{n}[\Bz_j]_{i}|^{4+e} < \infty$. To mitigate the inter-user interference, a classic design for the precoding matrix $ \BG = [\Bg_1, \ldots, \Bg_n] $ is ZF.  To this end, we utilize the same precoding matrix as  \cite{AblaNoEigen}, which is given by
\begin{equation}
    \BG = \left( \BH \BH^H\right)^{-1} \BH,
\end{equation}
with $\BH = [\Bh_1, \ldots, \Bh_n]$.
The performance of the ZF precoding has been extensively studied as the numbers of antennas and users increase simultaneously \cite{Hoydis2013MIMO}. However, to analyze the performance of the ZF precoder, it is essential to determine whether the Gram matrix $\BH\BH^H$ is singular. The following corollary provides a sufficient condition for the well-definedness of the precoding matrix $\BG$.
\begin{corollary}
\label{Coro_min_eig_zero_forcing}
Assume the dimensions $p$ and $n$ grow to infinity with 
\begin{itemize}
\item [1)]  $0 < \liminf_n p / n \leq  \limsup_n p / n < 1$. 
\item [2)] $ 0 < \liminf_n \min_{1 \leq j \leq n} \lambda_{\min}(\BC_j) \leq \limsup_n \max_{1 \leq j \leq n} \norm{\BC_j} < \infty$.
\end{itemize}
Then, there exists a  constant $E_-> 0$ such that
\begin{equation}
    \PP \left( \liminf_{n \to \infty} \lambda_{\min}(\BH\BH^H) \geq E_- \right) = 1.
\end{equation}
\end{corollary}
\textit{Proof:} The proof can be obtained by applying Theorem \ref{Thm_No_Eigenvalues}. For that purpose, we first extend the result to the case with $a = 0$, and the details are given in Appendix \ref{App_prof_of_coro_min_eig_zero_forcing}. \qed
\begin{remark}
In \cite{AblaNoEigen}, it was proved that when $\{ \Bz_j \}_{j \leq n}$ defined in \eqref{Eq_Channel_model_rayleigh} are complex Gaussian random vectors, the minimal eigenvalues of $\BH\BH^H$ are bounded away from 0 with probability 1. In contrast,  the small scale fading component $\Bz_j$ in this work can follow any distribution, as long as the $4 + \varepsilon$ moment exists. Similarly, in \cite{JWsilverstein1985wishartsmall}, the authors showed that when $\BOmega_j = \BI_p$, $\forall j \in [n]$ and $\BA = \Bzero_{p \times n}$, the minimal eigenvalue of $\BS$ is bounded for the Gaussian ensemble. This result was extended to the non-Gaussian matrices in \cite{Bai1993smalleig}. It is important to note that the proofs in \cite{AblaNoEigen} and \cite{JWsilverstein1985wishartsmall} rely on the Gaussianity. It is very challenging to generalize the boundedness of the smallest eigenvalue to non-Gaussian matrices.
\end{remark}

