\label{App_mathmatical_tools}
In this section, we present the mathematical tools that will be frequently used in the proofs throughout this paper.
\begin{lemma}(\cite[Lemma 2.8]{bai1998no})\label{Lemm_norm_mat} For $p$-by-$n$ matrices $\BA$ and $\BB$ with respective singular values $\sigma_1 \geq \sigma_2 \geq \ldots \geq \sigma_q$ and $\tau_1 \geq \tau_2 \geq \ldots \geq \tau_q$, where $q = \min(p, n)$, we have
\begin{equation}
  \max_{1 \leq k \leq q}|\sigma_k - \tau_k| \leq \norm{\BA - \BB}.
\end{equation}  
\end{lemma}
\begin{lemma}(\cite[Lemma 2.7]{bai1998no})\label{Lemm_trace_pre}
    Let $\Bx = [X_1, X_2, \ldots, X_p]^T$ be a vector whose entries $X_i$s are i.i.d. (complex) random variables with $\E X_1 = 0$ and $\E|X_1|^2 = 1$. Let $\BM$ be a $p \times p$ deterministic (complex) matrix. Then, for any $t \geq 2$, we have
    \begin{equation}
        \E \abs{\Bx^H \BM \Bx - \Tr \BM}^t \leq K_t \left\{ \left[\E|X_1|^4 \Tr (\BM\BM^H)\right]^{\frac{t}{2}} + \E |X_1|^{2t} \Tr (\BM\BM^H)^{\frac{t}{2}} \right\},
    \end{equation}
    where $K_t> 0$ is a constant only dependent on $t$. 
\end{lemma}
\begin{lemma}
  \label{Lemm_trace}
  Let $\Bx = [X_1, X_2, \ldots, X_p]^T$ be a vector with i.i.d. (complex) entries where $\E X_1 = 0$, 
  $\E |X_1|^2 = 1$, $\E |X_1|^{4 + \varepsilon} < \infty$, and $|X_1| \leq n^{\frac{1}{2} - \alpha}$, with 
  $\varepsilon > 0$ and $\alpha = \frac{\varepsilon}{8 + 2 \varepsilon}$. Let $\BM$ be a $p$-by-$p$ deterministic (complex) matrix. Then, we have, for any $t \geq 2$,
  \begin{equation}
    \E \abs{\Bx^H \BM \Bx - \Tr \BM}^t \leq  K_t \norm{\BM}^t R_t(p, n),
  \end{equation}
where $K_t > 0$ is a constant only dependent on $t$. Here, we have $R_{t}(p, n) = p^{\frac{t}{2}} + pn^{t - 2\alpha t - 2}$ when $t \geq 2 + \frac{\varepsilon}{2}$, and $R_t(p, n) = p^{\frac{t}{2}}$, otherwise. Moreover, for a deterministic vector $\Bv$, we have
\begin{align}
  &\E \abs{\Bx^H\Bv}^{2t} \leq K_t \norm{\Bv}^{2t} T_t(p, n), \\
  & \E \abs{\Bx^H\Bv\Bv^H \Bx -\Bv^H\Bv}^{t} \leq K_t \norm{\Bv}^{2t} T_t(p, n),
\end{align}
where $T_t(p, n) = 1$ for $1 \leq t \leq 2 + \frac{\varepsilon}{2}$ and $T_t(p, n) = n^{t - 2\alpha t - 2}$ when $t \geq 2 + \frac{\varepsilon}{2}$.
\end{lemma}
\textit{Proof:} The proof of Lemma \ref{Lemm_trace} is a direct application of Lemma \ref{Lemm_trace_pre} and omitted here. \qed
