\begin{lemma} \label{Lemm_Mat_Ber}
(Matrix Bernstein, \cite[Theorem 1.4]{tropp2012user}, \cite[Theorem 5.29]{vershynin2010introduction}) Consider a finite sequence $\{ \BX_i\}_{1 \leq i \leq n}$ of independent Hermitian random $p$-by-$p$ matrices. Assume that $\E \BX_i = 0$, $\norm{\BX_i} \leq G$ almost surely, and $\norm{\sum_{i=1}^n \E \BX_i^2} \leq \sigma^2$. Then, for all $t > 0$, we have 
\begin{equation}
\PP \left\{ \norm{\sum_{i=1}^n\BX_i} \geq t  \right\} \leq  2p \exp \left[-c \min\left( \frac{t^2}{\sigma^2}, \frac{t}{G}\right) \right],
\end{equation}
where $c > 0$ is a absolute constant that does not depend on $p, \sigma$, and $G$.
\end{lemma}
\begin{lemma}
  \label{Lemm_Mat_norm_Pbound}
  Let $\BX = [\Bx_1, \ldots, \Bx_n] \in \mathbb{C}^{p \times n}$ be a random matrix with independent columns. Assume that $\E [\Bx_j] = \mathbf{0}_p$, $\PP(\norm{\Bx_j} \leq \sqrt{m}) = 1$, and $\E [\Bx_j\Bx_j^H] = \BOmega_j$  for $j \in [n]$. Define $u = \max_{1 \leq j \leq n} \norm{\BOmega_j}$. Then, for any $\delta \geq  0$ and deterministic matrix $\BT$, we have
  \begin{equation}
    \PP \left( \norm{n^{-\frac{1}{2}}\BX + \BT} \geq \norm{\BT} + \sqrt{u} + \delta \right) \leq 2p \exp \left(-\frac{cn \delta^2}{2m} \right),
  \end{equation}
  where $c > 0$ is a absolute constant.  
\end{lemma}
\textit{Proof:} The proof is an application of Lemma \ref{Lemm_Mat_Ber} and given in Appendix \ref{App_Prof_Mat_norm_Pbound}. \qed
\begin{lemma} 
\label{Lemm_Burk_Ineq}
(Burkholder Inequality, \cite[Lemma 2.1]{bai1998no}) Let $\{ X_k \}$ be a complex martingale difference sequence with respect to the filtration $\{\mathscr{F}_k\}$. Then, for $t \geq 1$, there exists constant $K_t > 0$ such that 
\begin{equation}
    \E \abs{\sum_{k=1}^n X_k}^{2t} \leq K_t \left[ \E\left[\sum_{k=1}^n \E(|X_k|^2| \mathscr{F}_{k-1}) \right]^t + \sum_{k=1}^n\E|X_k|^{2t} \right].
\end{equation} 
\end{lemma}
