\begin{lemma}(\cite[Lemma 5.2]{hachem2008varianceProfile})
  \label{Lemm_Spr_pMat}
  Let $\BA \in \mathbb{R}^{n \times n}$, $\Bu \in \mathbb{R}^n$, and $\Bv \in \mathbb{R}^{n}$. Assume that $[\BA]_{i, j} \geq 0$, $[\Bu]_j > 0$, and $[\Bv]_j > 0$, for any $i, j \in [n]$, and the following holds
  \begin{equation}
    \Bu = \BA \Bu + \Bv.
  \end{equation} 
  Then, the spectral radius of $\BA$ can be given by $\rho(\BA) \leq 1 - \frac{\min_{1 \leq i \leq n}([\Bv]_i)}{\max_{1 \leq i \leq n}([\Bu]_i)}$. Moreover, the matrix $\BI_n - \BA$ is invertible with $\min_{i, j} [(\BI_n - \BA)^{-1}]_{i, j} \geq 0$ and $\| (\BI_n - \BA)^{-1} \|_{\infty} \leq \frac{\max_{1 \leq i \leq n}([\Bu]_i)}{\min_{1 \leq i \leq n}([\Bv]_i)}$.
\end{lemma}
\begin{lemma} \label{Lemm_matrix_Spr_maxrow_Norm}
Let $\{\BA_l\}_{1 \leq l\leq N}$ be a collection of $n$-by-$n$ complex matrices, and $\{\BB_{l}\}_{1 \leq l\leq N}$ and $\{\BC_{l}\}_{1 \leq l\leq N}$ be collections of $n$-by-$n$ non-negative matrices. Assume that for each $l$, $
      \abs{[\BA_l]_{i,j}} \leq \sqrt{[\BB_l]_{i, j} [\BC_{l}]_{i, j}}
$ and denote $\BA = \prod_{l=1}^N \BA_{l}$, $\BB = \prod_{l=1}^N \BB_{l}$, and $\BC = \prod_{l=1}^N \BC_{l}$. Then, we have
\begin{equation}
    \abs{[\BA]_{i, j}} \leq \sqrt{[\BB]_{i, j}[\BC]_{i, j}}, \text{ and } \rho\left( \BA \right) \leq \sqrt{\rho\left(\BB\right)\rho( \BC )}.
\end{equation}
Moreover, if $\max(\rho(\BB), \rho(\BC)) < 1$, we have
\begin{align}
&\norm{(\BI_n - \BA)^{-1}}_{\infty} \leq \sqrt{\norm{(\BI_n - \BB)^{-1}}_{\infty}\norm{(\BI_n - \BC)^{-1}}_{\infty} }, \\
&\norm{(\BI_n - \BA)^{-1}}_{1} \leq \sqrt{\norm{(\BI_n - \BB)^{-1}}_{1}\norm{(\BI_n - \BC)^{-1}}_{1} }.
\end{align}
\textit{Proof: } This lemma is a generalization of \cite[Lemma 13]{AblaNoEigen} whose proof follows a similar logic and thus is omitted. \qed
\end{lemma}
\begin{lemma}
\label{Lemm_Spnorm_Bound_of_sum_semidef_matrices}
    Let  $\{ \BA_l\}_{1 \leq l\leq N}$ be a collection of $n$-by-$n$ Hermitian non-negative matrices and $\{a_l\}_{1 \leq l\leq N}$ be a sequence of complex numbers with $|a_l| \leq b_l$, for any $ l \in [N]$. Then, we have
    \begin{equation}
        \norm{\sum_{l=1}^N a_l\BA_l} \leq \norm{\sum_{l=1}^N b_l\BA_l}.
    \end{equation}
\end{lemma}
\textit{Proof:} By definition of the operator norm, we have
\begin{align*}
    &\norm{\sum_{l=1}^N a_l\BA_l} = \sup_{\norm{\Bx} = 1, \norm{\By} = 1} \abs{ \sum_{l=1}^N a_l \Bx^H \BA_l \By} \leq \sup_{\norm{\Bx} = 1, \norm{\By} = 1}\sum_{l=1}^N b_l \abs{\Bx^H \BA_l^{1/2} \BA_l^{1/2}  \By}  \\
    & \leq \sup_{\norm{\Bx} = 1, \norm{\By} = 1}  \sum_{l=1}^N b_l \sqrt{\Bx^H \BA_l \Bx \By^H \BA_l \By} \leq \sup_{\norm{\Bx} = 1, \norm{\By} = 1} \left(\sum_{l=1}^N b_l \Bx^H \BA_l \Bx \right)^{1/2} \left(\sum_{l=1}^N b_l\By^H \BA_l \By\right)^{1/2} \leq \norm{\sum_{l=1}^N b_l \BA_l}, \numberthis
\end{align*}
which completes the proof. \qed
\section{Proof of Lemma \ref{Lemm_Mat_norm_Pbound}}
\label{App_Prof_Mat_norm_Pbound}
Denote $\BX_j = \frac{1}{n} (\Bx_j\Bx_j^H - \BOmega_j)$ for $1 \leq j \leq n$. Next, we verify the conditions of Lemma \ref{Lemm_Mat_Ber}. The norm of ${\BX_j}$ can be bounded as
\begin{equation}
  \norm {\BX_j} = \frac{\norm{\Bx_j\Bx_j^H - \BOmega_j}}{n}  \leq \frac{\norm{\Bx_j}^2 + \norm{\BOmega_j}}{n}  \leq \frac{m + u}{n} \leq \frac{2m}{n} := G.
\end{equation}
Furthermore, the following holds
\begin{equation}
  \norm{\sum_{j=1}^n \E \BX_j^2} \leq \sum_{j=1}^n\norm{ \E \BX_j^2} \leq \sum_{j=1}^n\frac{\norm{ \E\norm{\Bx_j}^2 \Bx_j\Bx_j^H} + \norm{\BOmega_j}^2}{n^2} \leq \frac{mu + u^2}{n} \leq \frac{2mu}{n} := \sigma^2.
\end{equation}
By applying Lemma \ref{Lemm_Mat_Ber} and taking $t = \max{(\sqrt{u}\delta, \delta^2)}$ with $\delta \geq  0$, we have 
\begin{equation}
  \PP\left(n^{-1}\norm{\BX\BX^H - \overline{\BOmega}} \geq \max{(\sqrt{u}\delta, \delta^2)}\right) \overset{(a)}{\leq} 2p \exp \left(-\frac{cn \delta^2}{2m}  \right),
\end{equation}
with $c > 0$ being a absolute constant and $\overline{\BOmega} = \sum_{j=1}^n \BOmega_j$. Here step $(a)$ is due to the following identity 
\begin{equation}
  \min \left(u^{-1} \max(u\delta^2, \delta^4), \max(\sqrt{u}\delta, \delta^2) \right) = \delta^2, ~~ \delta \geq 0.
\end{equation}
For the event $\{ n^{-1}\norm{\BX\BX^H - \overline{\BOmega}} \leq \max{(\sqrt{u}\delta, \delta^2)}\}$, the following holds
\begin{equation}
  \norm{n^{-\frac{1}{2}}{\BX}}^2  = \norm{n^{-1}\BX\BX^H} \leq n^{-1}\norm{{\BX\BX^H - \overline{\BOmega}}} + n^{-1}\norm{\overline{\BOmega}} \leq \max{(\sqrt{u}\delta, \delta^2)} + u \leq (\sqrt{u} + \delta)^2,
\end{equation}
which implies $\Vert n^{-\frac{1}{2}}\BX + \BT \Vert \leq \sqrt{u} + \delta + \norm{\BT}$. Therefore, we complete the proof. \qed
\section{Truncation, Centralization, and Normalization}
\label{App_Trunc}
To study the asymptotic behavior for the eigenvalues of $\BS$, we first simplify Assumption \ref{Assumpt_2}. 
In particular, in the truncation step, we restrict the range of the random variables $X_{ij}$ such that $|X_{ij}|$ is bounded by a suitable polynomial in $n$. In the centralization and normalization step, we subtract the mean from the truncated random variables and divide the results by the standard deviation to ensure that the transformed random variables are standardized.
% In particular, we will truncate the double array of random variables $X_{ij}$ to make them bounded by suitable polynomials in $n$, such that the moments are also polynomially bounded. 
This process will not affect the asymptotic locations of the random eigenvalues of $\BS$.
\par
Define the parameter $\alpha = \frac{\varepsilon}{8 + 2\varepsilon}$. Since $\E |X_{11}|^{4 + \varepsilon} < \infty$, we have $(4 + \varepsilon)\int_{0}^{\infty} t^{3 + \varepsilon} \PP(|X_{11}| \geq t) \dd t = \E|X_{11}|^{4 + \varepsilon} < \infty$, which implies
\begin{equation}
    \sum_{m=1}^{\infty} 2^{2m} \PP\left( |X_{11}| \geq 2^{(\frac{1}{2}-\alpha)m} \right) < \infty.
\end{equation}
Define the truncated random variables $X_{ij, n} = X_{ij} \Ind\{|X_{ij}| \leq n^{\frac{1}{2} - \alpha}\}$, and construct the random matrix $\widehat{\BSigma} = \BA + \widehat{\BY}$ such that $\widehat{\BY}$ has the same structure as $\BY$ by replacing $X_{ij}$ with $X_{ij, n}$ (note that we omit the index $n$ in $\BSigma_n$ for simplicity). Let $\ell^+ = \max(\limsup_n \max_j {d_j} / n, \limsup_n p / n)$.  Then, as $n \to \infty$, the probability of the event $\{\BSigma \neq \widehat{\BSigma} ~~ \mathrm{i.o.}\}$ can be bounded by
\begin{align*}
    &\PP\left(\BSigma \neq \widehat{\BSigma} ~~ \mathrm{i.o.} \right) =  \PP\left( \bigcap_{k\geq 1} \bigcup_{n \geq 2^k} \left\{\BSigma \neq \widehat{\BSigma}\right\} \right) = \lim_{k \to \infty} \PP\left( \bigcup_{n \geq 2^k} \left\{\BSigma \neq \widehat{\BSigma}\right\} \right) \\
    & \leq \lim_{k \to \infty} \sum_{m=k}^{\infty}\PP\left( \bigcup_{2^m \leq n \leq 2^{m+1}}\bigcup_{j \leq n} \bigcup_{i \leq d_j} \left\{ |X_{ij}|\geq n^{0.5 - \alpha}  \right\} \right) \\
    &\overset{(a)}{\leq} \lim_{k \to \infty} \sum_{m=k}^{\infty}\PP\left( \bigcup_{2^m \leq n \leq 2^{m+1}}\bigcup_{j \leq n, i\leq 2\ell^+n}  \left\{ |X_{ij}| \geq 2^{(0.5 - \alpha)m} \right\} \right) \\
    & = \lim_{k \to \infty} \sum_{m=k}^{\infty}\PP\left( \bigcup_{j \leq 2^{m+1}, i \leq \ell^+2^{m+2}} \left\{ |X_{ij}| \geq 2^{(0.5 - \alpha)m} \right\} \right) \\
    & \leq \lim_{k \to \infty} \sum_{m=k}^{\infty} \ell^+ 2^{2m+3}\PP\left(  |X_{11}| \geq 2^{(0.5 - \alpha)m}  \right) = 0, \numberthis
\end{align*}
where step $(a)$ follows from $d_j \leq 2 \ell^+ n$ for sufficiently large $n$. The above derivation shows that truncation does not affect the limits for the extreme eigenvalues of $\BS = \BSigma\BSigma^H$. 
Next, we perform the centralization. Denote the centralized random variables $\widetilde{X}_{ij, n} = {X}_{ij, n} - \E {X}_{ij, n}$ and construct the matrix $\widetilde{\BSigma} = \BA + \widetilde{\BY}$ with the same structure as $\BSigma$ by replacing $X_{ij}$ with $\widetilde{X}_{ij, n}$. By Lemma \ref{Lemm_norm_mat}, we have 
\begin{align*}
    &\max_{1 \leq k \leq p} \abs{\lambda_k^{\frac{1}{2}}(\widehat{\BS}) - \lambda_k^{\frac{1}{2}}(\widetilde{\BS}) } \leq \norm{\widehat{\BSigma} - \widetilde{\BSigma}} = \frac{1}{\sqrt{n}} \sup_{\norm{\Ba} = 1} \norm{\sum_{j=1}^n a_j \BB_j(\widehat{\Bx}_j - \widetilde{\Bx}_j)} \\
    &\leq \frac{1}{\sqrt{n}} \sup_{\norm{\Ba} = 1} \sum_{j=1}^n |a_j| \norm{\BB_j}d_j^{\frac{1}{2}}\sup_{i \leq d_j} \abs{ {X}_{ij, n} - \widetilde{X}_{ij, n}} \leq K n^{\frac{1}{2}} \sup_{i, j \geq 1} \E \abs{ {X}_{ij} - {X}_{ij, n}} \overset{(a)}{\leq}  \frac{K_1}{n^{1 + \alpha}}, \numberthis
\end{align*}
where $K$ and $K_1$ are constants independent of $n$ and step $(a)$ is obtained by setting $\beta = 1$ in the following inequality
\begin{align*}
\label{Eq_central_moment_X}
    &\E |X_{ij} - X_{ij, n}|^{\beta} \leq \beta \int_{0}^{\infty} \PP\left(|X_{ij}| \geq \max(n^{(\frac{1}{2} - \alpha)}, t) \right) t^{\beta - 1} \dd t  \\
    &\leq n^{(\frac{1}{2} - \alpha)\beta}   \PP(|X_{ij}| \geq n^{\frac{1}{2} - \alpha}) + \beta \int_{n^{\frac{1}{2} - \alpha}}^{\infty} t^{\beta - 1}\PP(|X_{ij}| \geq t) \dd t \\
    &\leq  \frac{\E|X_{ij}|^{4 + \varepsilon} + \beta\int_{n^{\frac{1}{2} - \alpha}}^{\infty} t^{3 + \varepsilon}\PP(|X_{ij}| \geq t) \dd t }{n^{(\frac{1}{2} - \alpha)(4 + \varepsilon - \beta)}} \leq \frac{(4 + \varepsilon + \beta)\E |X_{ij}|^{4 + \varepsilon}}{(4 + \varepsilon)n^{2 - (\frac{1}{2} - \alpha)\beta}}, ~~ \beta \in [1, 4 + \varepsilon]. \numberthis
\end{align*}
The above analysis shows that $\limsup_{n \to \infty}\max_{1 \leq k \leq p} |\lambda_k(\widehat{\BS}) - \lambda_k(\widetilde{\BS}) | = 0$.
\par
In the following, we normalize the random variables. Denote $\sigma_n^2 = \E |\widetilde{X}_{11, n}|^2$ and $\overline{X}_{ij, n} = \widetilde{X}_{ij, n} / \sigma_n$. Similar to the above derivation, we define $\overline{\BSigma} = \BA + \overline{\BY}$. Then, we can obtain
\begin{equation}
    1 - \sigma_n^2 = 1 - \E \abs{{X}_{11, n}}^2 + \abs{\E \widehat{X}_{11, n}}^2 = \E|X_{11}|^2 \Ind{\{|X_{11}| \geq n^{\frac{1}{2} - \alpha} \}} + \abs{\E|X_{11}| \Ind{\{|X_{11}| \geq n^{\frac{1}{2} - \alpha} \}} }^2 \overset{(a)}{ \leq } \frac{K}{n^{1 + 2\alpha}},
\end{equation}
where step $(a)$ follows by setting $\beta = 2$ in \eqref{Eq_central_moment_X}. Hence, we have 
\begin{align*}
 \label{Eq_Max_lambda_k_SS}
    \max_{1 \leq k \leq p} \abs{\lambda_k^{\frac{1}{2}}(\overline{\BS}) - \lambda_k^{\frac{1}{2}}(\widetilde{\BS}) } \leq \norm{\overline{\BSigma} - \widehat{\BSigma}} \leq \frac{|1 - \sigma_n|}{\sqrt{n}|\sigma_n|} \sup_{\norm{\Ba} = 1}  \sum_{j=1}^n |a_j| \norm{\BB_j} \norm{\widetilde{\Bx}_j} \leq \frac{\sqrt{n}|1 - \sigma_n^2| K}{|\sigma_n(1 + \sigma_n)|} \sup_{i, j \geq 1} |\widetilde{X}_{ij, n}| \overset{(a)}{\leq} \frac{K_1}{n^{3 \alpha}}, \numberthis
\end{align*}
where $K$ and $K_1$ are non-negative constants and step $(a)$ in \eqref{Eq_Max_lambda_k_SS} follows from $|\widetilde{X}_{ij, n}| \leq |X_{ij, n}| + |\E (X_{ij} - X_{ij, n})| \leq 2n^{1-\alpha}$ for large $n$. By \eqref{Eq_central_moment_X}, it is straightforward to prove $\E |\overline{X}_{ij, n}|^{4 + \varepsilon} < \infty$.
\par
Based on the above discussion, we know that the asymptotic locations of the eigenvalues for $\BS$ and $\overline{\BS}$ are identical. Therefore, we can make the following simplified and stronger assumptions on the distribution of $X_{ij}$.
\begin{itemize}
    \item[1)] $\{ X_{ij} \}_{i, j \geq 1}$ is a double array whose entries are i.i.d. complex random variables.
    \item [2)] $\E X_{ij} = 0$, $\E|X_{ij}|^2 = 1$, and $\E |X_{ij}|^{4 + \varepsilon} < \infty$. 
    \item [3)] $|X_{ij}| \leq n^{\frac{1}{2} - \alpha}$.
\end{itemize}
\section{A Bound on the Spectral Norm}
In this section, we provide a loose bound on the largest eigenvalue of S. This bound will be necessary for investigating tighter results. Next, we first prove the following lemma.
\begin{lemma} 
  \label{Lemm_P_bound_Sn}
Assume Assumptions \ref{Assumpt_1}-\ref{Assumpt_4} hold and $X_{ij}$ follows the distribution as described in Appendix \ref{App_Trunc}. 
For sufficiently large $n$, the following inequality holds
\begin{equation}
  \label{Eq_P_norm_Sn}
  \PP\left[ \norm{\BSigma} \geq \log(n)\right] \leq  K_l n^{-l}, ~~ \forall l > 0,
\end{equation}
where $K_l$ is a constant that only depends on $l$. Furthermore, given $r \geq 1$, there exists a positive integer $N = N(r)$ such that the following holds
\begin{equation}
  \E \norm{\BSigma}^r \leq  2\log^r(n)
\end{equation}
for all $n \geq N(r)$.
\end{lemma}
\textit{Proof:} We first give a bound on $\PP(\norm{\BB_j\Bx_j} \geq \sqrt{Kn})$, where $K$ is a sufficiently large constant. According to Lemma \ref{Lemm_trace}, we have 
\begin{align*}
    \PP \left(\norm{\BB_j\Bx_j} \geq \sqrt{Kn} \right) \leq \PP \left(\abs{\Bx_j^H\BB_j^H\BB_j\Bx_j - \Tr \BOmega_j} \geq Kn/2 \right) \leq \frac{2^t\E\abs{\Bx_j^H\BB_j^H\BB_j\Bx_j - \Tr \BOmega_j}^t}{(Kn)^t} \leq \frac{K'_t}{n^{2\alpha t + 1}}, \numberthis
\end{align*}
where $t \geq 4$ is arbitrarily large and $K'_t$ is a constant dependent on $t$. Denote the set $A_n = \cap_{j \leq n} \left\{ \norm{\BB_j\Bx_j} \leq (Kn)^{1/2} \right\}$. Then, for any $a> 0$, we have 
\begin{equation}
\label{Eq_Norm_Bd_Sigma}
    \PP\left(\norm{\BSigma} \geq a \right) \leq \PP \left( \{\norm{\BSigma} \geq a\} \cap A_n \right) + \sum_{j=1}^n \PP\left(\norm{\BB_j\Bx_j} \geq \sqrt{Kn} \right) \leq \PP(\norm{\underline{\BSigma}} \geq a) + \frac{K_t'}{n^{2\alpha t}}.
\end{equation}
Define the truncated matrix $\underline{\BSigma} = \underline{\BY} + \BA$, where the $j$-th column of $\underline{\BY}$ is given by $n^{-\frac{1}{2}} \BB_j \Bx_j \Ind\left\{ \norm{\BB_j\Bx_j} \leq (Kn)^{1/2} \right\}$. According to Lemma \ref{Lemm_Mat_norm_Pbound},
there exist positive constants $K_1$ and $K_2$ such that for any $u \geq 0$, 
\begin{align*}
\label{Eq_Pbound_on_USigma}
    \PP\left( \norm{\underline{\BSigma}} \geq K_1 + u \right) \leq 2p \exp\left(-K_2 u^2\right). \numberthis
\end{align*}
Taking $u = \log(n) - K_1$ in \eqref{Eq_Pbound_on_USigma}, \eqref{Eq_Norm_Bd_Sigma} implies
\begin{equation}
    \PP( \norm{\BSigma} \geq \log(n)) \leq \frac{K'_t}{n^{2 \alpha t + 1}} + \frac{2p}{n^{K_2' \log(n)}},
\end{equation}
for sufficiently large $n$ and constant $K_2' > 0$. Since $t$ is arbitrary, \eqref{Eq_P_norm_Sn} is proved.
\par
Next, we prove the bound on the moment of $\norm{\BSigma}$. By $|X_{ij}| \leq n^{1/2 - \alpha}$, we can obtain
\begin{equation}
    \norm{\BSigma} \leq \norm{\BA} + \frac{1}{\sqrt{n}} \sup_{\norm{\Ba} = 1}\sum_{j=1}^n |a_j| \norm{\BB_j} \norm{\Bx_j} \leq \widetilde{K} n^{1 - \alpha}
\end{equation}
for some constant $\widetilde{K}$ and large $n$. As a result, we have 
\begin{align*}
    \E \norm{\BSigma}^r  &= \E \norm{\BSigma}^r \{ \Ind_{A_n} + \Ind_{A_n^c}\} \leq r \int_{0}^{\widetilde{K}n^{1-\alpha}} u^{r-1} \PP(\norm{\underline{\BSigma}} \geq u) \dd u +\E \norm{\BSigma}^r \Ind_{A_n^c} \\
    & \leq r \int_{0}^{\log(n)} u^{r-1} \dd u + 2pr \int_{\log(n)}^{\widetilde{K}n^{1-\alpha}} u^{r-1} e^{-K_2u^2/4} \dd u + \PP (A_n^c) (\widetilde{K}n^{1-\alpha})^r := W_1 + W_2 + W_3, \numberthis
\end{align*}
by applying \eqref{Eq_Pbound_on_USigma}. By straight calculation, we have $W_1 = \log^r(n)$. $W_2$ can be bounded by
\begin{equation}
    W_2 \leq 2p r (\widetilde{K}n^{1-\alpha})^{(r - 1)} \int_{\log(n)}^{\infty} e^{-K_2u^2 / 4} \dd u \leq \frac{K_r n^r}{n^{ \widetilde{K}_2 \log(n)}} \leq \frac{\log^r(n)}{2},
\end{equation}
for any $n$ larger than a positive $r$-related integer $N = N(r)$. Here, $\widetilde{K}_2$ is a constant and $K_r$ is a constant that depends on $r$. It follows from \eqref{Eq_Norm_Bd_Sigma} that $W_3 \leq \log^r(n) / 2$. Therefore, we complete the proof of Lemma \ref{Lemm_P_bound_Sn}. \qed
\section{Proof of Theorem \ref{Thm_conver_ESD}}
\label{App_Converge_resolvent}
As the proofs for the trace form and the bilinear form of the resolvent are similar, and the latter is more technically challenging, we will only provide the convergence proof for the bilinear form $\Bu^H (\BQ(z) - \BTheta(z)) \Bv$. Using the polarization identity
\begin{equation}
    \Bu^H \BT \Bv = \frac{1}{4} \left[ (\Bu + \Bv)^H\BT(\Bu + \Bv) - (\Bu - \Bv)^H \BT (\Bu - \Bv) +  \jmath(\Bu - \jmath\Bv)^H \BT (\Bu - \jmath \Bv) - \jmath (\Bu + \jmath \Bv)^H \BT (\Bu - \jmath \Bv) \right],
\end{equation}
it is sufficient to establish the convergence of the quadratic form $\Bu^H (\BQ(z) - \BTheta(z)) \Bu$ with $\norm{\Bu} = 1$. Here, we will prove a stronger result that not only gives the order of convergence but is also useful for demonstrating the no-eigenvalue property. To this end, we will use the simplified model presented in Appendix \ref{App_Trunc}. As discussed in Appendix \ref{App_Trunc}, the simplified process will not change the asymptotic positions of any eigenvalues of $\BS$.
\begin{lemma}
\label{Lemm_bilinear}
    Assume Assumptions \ref{Assumpt_1}-\ref{Assumpt_4} hold and $X_{ij}$ follows the distribution as described in Appendix \ref{App_Trunc}. Then, for $z = x + \jmath v \in \mathbb{C}^+$ where $v$ is less or equal to a small positive constant $K_{\mathrm{im}}$, the following holds for $t \geq 2 + \varepsilon / 2$
    \begin{equation}
        \sup_{\norm{\Bu} = 1} \E \abs{\Bu^H \left[\BQ(z) - \BTheta(z)\right] \Bu }^{2t} \lesssim_t \frac{[\mathcal{U}(z)]^{2t}}{n^{2\alpha t}}, \label{Eq_bilinear_U_t}
    \end{equation}
    where $\mathcal{U}(z) = (K_2 + x^2 + v^2)^{9} / v^{29}$ with $K_2$ being a positive constant independent of $n$.
\end{lemma}
\textit{Proof:} The main techniques follow from \cite{hachem2013bilinear}, which rely on the martingale difference argument and Burkholder inequality (Lemma \ref{Lemm_Burk_Ineq}). For simplicity of notation, we will omit the variable $z$ when there is no ambiguity. 
\par
Next, we introduce the related intermediate variables. Define $\widetilde{\BQ}(z) = (\BSigma^H\BSigma - z\BI_n)^{-1}$. Let $\BSigma_j$ be the $p$-by-$(n-1)$ matrix by deleting the $j$-th column of $\BSigma$ and denote $\BQ_j(z) = (\BSigma_j \BSigma_j^H - z \BI_p)^{-1}$. Write $\Bxi_j = \Ba_j + \By_j$, where vectors $\Bxi_j$ and $\Ba_j$ are the $j$-th column of $\BSigma$ and $\BA$, respectively, and $\By_j = n^{-1/2} \BB_j \Bx_j$. Further define
% \begin{align*}
% &\kappa_j = \frac{1}{n} \Tr \BOmega_j \E \BQ, ~~~ \eta_j =  \frac{1}{1 + \frac{1}{n}\Tr \BOmega_j\BQ_j + \Ba_j^H\BQ_j\Ba_j}, ~~~ \widetilde{q}_j = \frac{1}{-z(1 + \Bxi_j^H\BQ_j\Bxi_j)}, ~~ \widetilde{\kappa}_j = \E \widetilde{q}_j  \\
% &\alpha_{j, j} = \frac{1}{n} \Tr \BOmega_j \BQ_j, ~~ \Delta_j = \Bxi_j^H \BQ_j \Bxi_j - \frac{1}{n} \Tr \BOmega_j \BQ_j - \Ba_j^H \BQ_j\Ba_j, ~~ \BD_{\kappa} = \diag(\kappa_1, \ldots, \kappa_n)\\
% &\BR(z) = \left[-z\left(\BI_p + \sum_{j=1}^n\frac{\BOmega_j}{n} \widetilde{\kappa}_j(z)\right) + \BA \left(\BI_n + \BD_{\kappa}(z)\right)^{-1}\BA^H \right]^{-1}, \\
% &\widetilde{\BR}(z) = \left[ -z(\BI_n + \BD_{\kappa}(z)) + \BA^H \left( \BI_p +  \sum_{j=1}^n\frac{\BOmega_j}{n} \widetilde{\kappa}_j(z) \right) \BA \right]^{-1}.
% \end{align*}
\begin{align*}
&\kappa_j = \frac{1}{n} \Tr \BOmega_j \E \BQ, ~~~ \eta_j =  \frac{1}{1 + \frac{1}{n}\Tr \BOmega_j\BQ_j + \Ba_j^H\BQ_j\Ba_j}, ~~~ \widetilde{q}_j = \frac{1}{-z(1 + \Bxi_j^H\BQ_j\Bxi_j)},  \\
&\widetilde{\kappa}_j = \E \widetilde{q}_j, ~~ \alpha_{j, j} = \frac{1}{n} \Tr \BOmega_j \BQ_j, ~~ \Delta_j = \Bxi_j^H \BQ_j \Bxi_j - \frac{1}{n} \Tr \BOmega_j \BQ_j - \Ba_j^H \BQ_j\Ba_j, \\
&\BG = \left[-z\left( \BI_p + \sum_{j=1}^n \frac{{\BOmega_j \widetilde{\kappa}_j}}{n}\right) \right]^{-1}, ~~ \widetilde{\BG} = \diag\left(\frac{-1}{z(1 + \kappa_j)}; 1 \leq j \leq n \right), \\
& \BR = \left( \BG^{-1} -z\BA\widetilde{\BG}\BA^H \right)^{-1}, ~~ \widetilde{\BR} = \left( \widetilde{\BG}^{-1} -z\BA^H \BG \BA \right)^{-1}. \label{Label_Def_of_terms_bilinear}\numberthis
\end{align*}
Similar to \cite{hachem2013bilinear}, the random quantity $\Bu^H[\BQ - \BTheta]\Bu$ is divided into three parts as
\begin{equation}
    \Bu^H[\BQ- \BTheta]\Bu = \Bu^H[\BQ - \E \BQ]\Bu + \Bu^H[\E \BQ - \BR]\Bu + \Bu^H[ \BR -  \BTheta]\Bu,
\end{equation}
and we will handle them separately.  We use $\E_j[\cdot]$ to denote the conditional expectation $\E[\cdot | \mathscr{F}_j]$, where $\mathscr{F}_j$ is the $\sigma$-algebra generated by $\{ X_{ij'}, 1 \leq j' \leq j, 1 \leq i \leq m_{j'} \}$, and $\E_0 \equiv \E $. Some useful transforms and estimations are given in Appendix \ref{App_Useful_Estimations}. In the following, we will frequently use the asymptotic notation ``$\lesssim$'', and the asymptotic regime is stated in Assumption \ref{Assumpt_1} with $n \to \infty$.
\paragraph*{Part I} In this part, we will prove
\begin{equation}
\label{Eq_Part_I}
    \E \abs{\Bu^H[\BQ - \E \BQ]\Bu}^{2t}\lesssim_t \frac{\log^{6t}(n)}{v^{12t}n^{2 \alpha t + 0.5}},
\end{equation}
for $t \geq 2 + \varepsilon / 2$. First, write $\Bu^H (\BQ - \E \BQ) \Bu$ as the sum of martingale difference sequence, 
\begin{align*}
    &\Bu^H (\E_n \BQ - \E_0 \BQ) \Bu = \sum_{j=1}^n \Bu^H (\E_{j}\BQ - \E_{j-1} \BQ) \Bu \overset{(a)}{=}  \sum_{j=1}^n  [\E_{j}- \E_{j-1}]\Bu^H(\BQ - \BQ_j) \Bu \overset{(b)}{=}  \sum_{j=1}^n  [\E_{j}- \E_{j-1}]\frac{-\Bu^H\BQ_j\Bxi_j \Bxi_j^H\BQ_j \Bu}{1 + \Bxi_j^H \BQ_j \Bxi_j}  \\
    & \overset{(c)}{=} \sum_{j=1}^n  [\E_{j}- \E_{j-1}]\left( -\eta_j\Bu^H\BQ_j\Bxi_j \Bxi_j^H\BQ_j \Bu + \frac{\eta_j \Delta_j \Bu^H\BQ_j\Bxi_j \Bxi_j^H\BQ_j \Bu}{1 + \Bxi_j^H \BQ_j \Bxi_j} \right) = \sum_{j=1}^n \Gamma_{1j} + \Gamma_{2j}, \numberthis
\end{align*}
where step $(a)$ follows from $\E_{j}\BQ_j = \E_{j-1} \BQ_{j}$, step $(b)$ is due to the identity in \eqref{Eq_Wood_resolvent_Id}, and step $(c)$ follows by writing $z\widetilde{q}_j = -\eta_j - z\widetilde{q}_j \eta_j \Delta_j$.
One can check that both $\{\Gamma_{1j}\}_{j \leq n}$ and $\{ \Gamma_{2j} \}_{j \leq n}$ are martingale difference sequences with respective to the filtration $\{\mathscr{F}_j\}_{j \leq n}$. Next, we handle $\E |{\sum_j} \Gamma_{1j}|^{2t}$.  Express $\Gamma_{1j}$ as
\begin{align*}
    -\Gamma_{1j} &= [\E_{j} - \E_{j-1}]\eta_j\Bu^H\BQ_j\Ba_j \By_j^H\BQ_j \Bu + \eta_j\Bu^H\BQ_j\By_j \Ba_j^H\BQ_j \Bu + \eta_j\Bu^H\BQ_j\Ba_j \Ba_j^H\BQ_j \Bu + \eta_j\Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu \\
    & = Z_{1j} + Z_{2j} + Z_{3j} + Z_{4j}. \numberthis
\end{align*}
By  Lemma \ref{Lemm_Burk_Ineq}, we have
\begin{align*}
\label{Eq_Bound_Gamma_1}
    \E \abs{\sum_{j=1}^n \Gamma_{1j}}^{2t} \leq \sum_{i = 1}^4 K_t  \left[ \E \left(\sum_{j=1}^n\E_{j-1}|Z_{ij}|^2 \right)^t + \sum_{j=1}^n \E|Z_{ij}|^{2t} \right]. \numberthis 
\end{align*}
In the following, we will evaluate the right hand side (RHS) of \eqref{Eq_Bound_Gamma_1} for different $i \in \{1, 2, 3, 4\}$. Since $\By_j$ is independent of $\mathscr{F}_{j-1}$, we can obtain
\begin{equation}
    Z_{4j} = \E_j \eta_j\Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu  - \frac{1}{n}\eta_j\Bu^H\BQ_j\BOmega_j\BQ_j \Bu. 
\end{equation}
It follows from Lemma \ref{Lemm_Bound_on_qterms} and Lemma \ref{Lemm_trace} that
\begin{equation}
    \sum_{j=1}^n \E_{j-1} |Z_{4j}|^2  \lesssim v^{-2}\sum_{j=1}^n\E_{j-1} \abs{ \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu  - \frac{1}{n}\Bu^H\BQ_j\BOmega_j\BQ_j \Bu }^2 \lesssim \frac{1}{nv^6}, \label{Eq_Burk_bound_Z4j}
\end{equation}
where we have used the fact that $|\eta_j| \leq K_0 / v$ since $v$ is small and the bound $\|\BQ_j \| \leq 1/v$. By Lemma \ref{Lemm_trace}, we have 
\begin{align*}
    \sum_{j=1}^n \E |Z_{4j}|^{2t} \lesssim_t v^{-2t} \sum_{j=1}^n \E\abs{ \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu  - \frac{1}{n}\Bu^H\BQ_j\BOmega_j\BQ_j \Bu }^{2t} \lesssim_t \frac{1}{v^{6t} n^{4 \alpha t + 1}}. \numberthis \label{Eq_trace_2t_Z4j}
\end{align*}
Obviously, $Z_{3j}$ will not contribute to the RHS of \eqref{Eq_Bound_Gamma_1} since $Z_{3j} = 0$. Using $Z_{2j} = \E_{j}\eta_j\Bu^H\BQ_j\By_j \Ba_j^H\BQ_j \Bu $ and Lemma \ref{Lemm_Usedul_est}, we have 
\begin{align*}
    \E\left( \sum_{j=1}^n \E_{j-1}|Z_{2j}|^2 \right)^t &\leq \E\left(\sum_{j=1}^n \E_{j-1}\abs{\eta_j\Bu^H\BQ_j\By_j \Ba_j^H\BQ_j \Bu}^2 \right)^t \\
    &\lesssim_t \frac{1}{n^tv^{4t}}\E\left(\sum_{j=1}^n\E_{j-1}(\Bu^H\BQ_j^H \Ba_j\Ba_j^H\BQ_j \Bu) \right)^t \overset{(a)}{\lesssim_t} \frac{\log^{2t}(n)}{n^tv^{8t}}, \numberthis
\end{align*}
where step $(a)$ follows by the estimation in \eqref{Eq_useful_est_4}.
Similar to \eqref{Eq_trace_2t_Z4j}, we can get 
\begin{align*}
    \sum_{j=1}^n \E|Z_{2j}|^{2t}  & \lesssim_t \frac{1}{v^{2t}} \sum_{j=1}^n\E\abs{\Bu^H\BQ_j\By_j \Ba_j^H\BQ_j \Bu}^{2t} \lesssim_t \frac{1}{v^{4t} n^{2\alpha t + 2}} \sum_{j=1}^n\E\abs{ \Ba_j^H\BQ_j \Bu}^{2t} \\
    & \lesssim_t \frac{1}{v^{6t - 2} n^{2\alpha t + 2}} \sum_{j=1}^n\E\abs{ \Ba_j^H\BQ_j \Bu}^{2} \lesssim \frac{\log^2(n)}{v^{6t + 2} n^{2\alpha t + 2}}. \numberthis \label{Eq_Burk_Bound_2t_Z2j}
\end{align*}
The evaluation of the term related to $Z_{1j}$ is quite similar to that related to $Z_{2j}$, and is thus omitted. The following is obtained by gathering the bounds \eqref{Eq_Burk_bound_Z4j}-\eqref{Eq_Burk_Bound_2t_Z2j}
\begin{equation}
    \E \abs{\sum_{j=1}^n \Gamma_{1j}}^{2t} \lesssim_t \frac{1}{n^tv^{6t}} + \frac{1}{v^{6t} n^{4 \alpha t + 1}} +\frac{\log^{2t}(n)}{n^tv^{8t}} + \frac{\log^2(n)}{v^{6t + 2} n^{2\alpha t + 2}}.
\end{equation}
\par
Next, we handle $\mathbb{E}|\sum_j \Gamma_{2j}|^{2t}$. To this end, we decompose $\Gamma_{2j}$ as
\begin{align*}
    -\Gamma_{2j} &= [\E_j - \E_{j-1}](z \widetilde{q}_j\eta_j \Delta_j \Bu^H\BQ_j\Ba_j \By_j^H\BQ_j \Bu + z \widetilde{q}_j\eta_j \Delta_j \Bu^H\BQ_j\By_j \Ba_j^H\BQ_j \Bu + z \widetilde{q}_j\eta_j \Delta_j \Bu^H\BQ_j\Ba_j \Ba_j^H\BQ_j \Bu \\
    &+ z \widetilde{q}_j\eta_j \Delta_j \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu) = \chi_{1j} + \chi_{2j} + \chi_{3j} + \chi_{4j}. \numberthis
\end{align*}
Define the set $A = \{\norm{\BSigma} \leq \log(n)\}$. Using $\E_{j-1}|(\E_j - \E_{j-1})a|^2 \leq 2\E_{j-1}|a|^2$, and the inequalities $|z\widetilde{q}_j| \lesssim  \norm{\BSigma}^2 / v$ and $|\eta_j| \lesssim v^{-1}$ in Lemma \ref{Lemm_Bound_on_qterms}, we have 
\begin{equation}
    \sum_{j=1}^n \E_{j-1} |\chi_{4j}|^2 = \sum_{j=1}^n \E_{j-1} \left[ |\chi_{4j}|^2 (\Ind_{A} + \Ind_{A^c}) \right] \lesssim \frac{\log^4(n)}{v^4}\sum_{j=1}^n \E_{j-1}\abs{\Delta_j}^2\abs{ \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu}^2  + \sum_{j=1}^n  \E_{j-1} \left[|\chi_{4j}|^2 \Ind_{A^c} \right]. 
\end{equation}
According to the truncation $|X_{ij}| \leq n^{1/2 - \alpha} < \sqrt{n}$, we know that $\|\By_j\|^2 \lesssim n$,  $\norm{\BSigma} \lesssim n$, and $|\Delta_j| \lesssim (\norm{\Bxi_j}^2 + 1)  / v \lesssim n^2 / v$, which further give $|\chi_{4j}| \leq n^6/v^5$. As a result, the following is obtained by Hölder's inequality and Lemma \ref{Lemm_bound_Delta}
\begin{align*}
\label{Eq_bound_X4j}
    &\E \left[ \sum_{j=1}^n \E_{j-1} |\chi_{4j}|^2 \right]^t \lesssim_t \E \left[ \frac{\log^4(n)}{v^4}\sum_{j=1}^n \E_{j-1}\abs{\Delta_j}^2\abs{ \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu}^2  + \frac{n^{12}}{v^{10}}\sum_{j=1}^n  \E_{j-1}  \Ind_{A^c}\right]^t \\
    &\lesssim_t \frac{\log^{4t}(n)}{v^{4t}} \E \left[ \sum_{j=1}^n \E_{j-1}^{4 / (4 + \varepsilon)}\abs{\Delta_j}^{2 + \varepsilon/2} \E_{j-1}^{\varepsilon / (4 + \varepsilon)}\abs{ \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu}^{(8 + 2 \varepsilon) / \varepsilon} \right]^t  + \frac{n^{13t}\PP(A^c)}{v^{10t}} \\
    &\lesssim_t \frac{\log^{4t}(n)}{v^{10t}n^{8 \alpha t}} + \frac{n^{13t}\PP(A^c)}{v^{10t}} \lesssim_t \frac{\log^{4t}(n)}{v^{10t}n^{8 \alpha t}}. \numberthis
\end{align*}
By Lemma \ref{Lemm_P_bound_Sn}, the probability of $A^c$ is smaller than any polynomial of $n^{-1}$. From the above derivation, we can observe that if $|a| \leq \mathcal{P}$, where $\mathcal{P}$ is a polynomial in $n$, then we have $\mathbb{E} |a| \leq \mathbb{E} |a|\Ind_A + \mathcal{P} \PP(A^c) = \mathbb{E} |a|\Ind_A + o(K_l n^{-l})$ by splitting $1 = \Ind_A + \Ind_{A^c}$. Therefore, in the following discussion, if the evaluated term is upper bounded by a polynomial in $n$,  we always assume $\norm{\BSigma} \leq \log(n)$ for simplicity. The evaluation for $\sum_j \E |\chi_{4j}|^{2t}$ is given by
\begin{align*}
    \sum_{j=1}^n \E |\chi_{4j}|^{2t} & \lesssim_t \sum_{j=1}^n \E |z\widetilde{q}_j\eta_j \Delta_j \Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu|^{2t} \lesssim_t \frac{\log^{4t}(n)}{v^{4t}} \sum_{j=1}^n\E^{1/2} |\Delta_j|^{4t} \E^{1/2}|\Bu^H\BQ_j\By_j \By_j^H\BQ_j \Bu|^{4t} \\
    & \lesssim_t\frac{\log^{4t}(n) n}{v^{4t}} \sqrt{\frac{1}{v^{4t}}\left(\frac{1}{n^{8\alpha t + 1}} + \frac{1}{n^{4\alpha t + 2}} \right) \cdot \frac{1}{v^{8t}n^{8\alpha t + 2}}} \lesssim \frac{\log^{4t}(n)}{v^{10 t}} \left(\frac{1}{n^{8 \alpha t + 0.5}}+\frac{1}{n^{6\alpha t + 1}} \right). \numberthis \label{Eq_chi_4j_2t}
\end{align*}
% By using the same method, we can get
% \begin{align*}
%     &\E \left[ \sum_{j=1}^n \E_{j-1} |\chi_{3j}|^2 \right]^t \lesssim_t \frac{\log^{6t}(n)}{ v^{12 t} n^t}, ~~\sum_{j=1}^n \E |\chi_{3j}|^{2t} \lesssim_t \frac{\log^{4t + 2}(n)}{v^{10 t + 2} }\left(\frac{1}{n^{4\alpha t + 0.5}}+ \frac{1}{n^{2\alpha t + 1}} \right), \\
%     &\E \left[ \sum_{j=1}^n \E_{j-1} |\chi_{ij}|^2 \right]^t \lesssim_t \frac{\log^{4t}(n)}{v^{10 t} n^{6\alpha t} }, ~~ \sum_{j=1}^n \E |\chi_{ij}|^{2t} \lesssim_t \frac{\log^{4t}(n)}{v^{10 t}  }\left(\frac{1}{n^{6\alpha t + 0.5}} + \frac{1}{n^{4\alpha t + 1}}\right), i = 1, 2. \numberthis
% \end{align*}
Next, we evaluate the $\chi_{3j}$-related terms. By Lemma \ref{Lemm_Usedul_est}, we have 
\begin{align*}
    \E \left[\sum_{j=1}^n \E_{j-1} |\chi_{3j}|^2 \right]^t \lesssim_t \frac{\log^{4t}(n)}{v^{4t}} \E \left[\sum_{j=1}^n \E_{j-1}|\Delta_j|^2 \abs{\Bu^H\BQ_j\Ba_j\Ba_j^H\BQ_j\Bu}^2 \right]^t  \lesssim_t \frac{\log^{6t}(n)}{ v^{12 t} n^t}. \numberthis
\end{align*}
Define $\E_{-\Bx_j}(\cdot) = \E(\cdot | \mathscr{F}_{-\Bx_j})$ with $\mathscr{F}_{-\Bx_j}$ being the $\sigma$-algebra generated by $\{\Bx_{j'} : j' \leq n, j' \neq j\}$. The evaluation for $\sum_{j} \E |\chi_{3j}|^{2t}$ can be given by
\begin{equation}
    \sum_{j=1}^n \E |\chi_{3j}|^{2t} \lesssim_t \frac{\log^{4t}(n)}{v^{4t}} \sum_{j=1}^n \E\left[ \left(\E_{-\Bx_j}|\Delta_j|^{2t} \right) \abs{\Bu^H\BQ_j\Ba_j\Ba_j^H\BQ_j\Bu}^{2t}\right] \lesssim_t \frac{\log^{4t+2}(n)}{v^{10t+2}} \left(\frac{1}{n^{4\alpha t + 1}} + \frac{1}{n^{2\alpha t + 2}}\right).
\end{equation}
We then handle the $\chi_{2j}$-related terms. By the independence between $\By_j$ and $\BQ_j$, Lemma \ref{Lemm_bound_Delta}, and Lemma \ref{Lemm_trace}, we have 
\begin{align*}
    &\E_{j-1}\abs{\chi_{2j}}^2  \lesssim \frac{\log^{4}(n)}{v^{4}} \E_{j-1}  \abs{\Delta_j}^2 |\Bu^H\BQ_j \By_j|^2 \abs{\Ba_j^H \BQ_j \Bu}^2  = \frac{\log^{4}(n)}{v^{4}} \E_{j-1} \left\{ \E_{-\Bx_j}\left[\abs{\Delta_j}^2 |\Bu^H\BQ_j \By_j|^2\right] \abs{\Ba_j^H \BQ_j \Bu}^2 \right\} \\
    & \leq \frac{\log^{4}(n)}{v^{4}} \E_{j-1} \left[ \left(\E_{-\Bx_j}^{4 / (4 + \varepsilon)}\abs{\Delta_j}^{2 + \varepsilon/2} \right) \left( \E_{-\Bx_j}^{\varepsilon / (4 + \varepsilon)}|\Bu^H\BQ_j \By_j|^{(8 + 2 \varepsilon) / \varepsilon} \right) \abs{\Ba_j^H \BQ_j \Bu}^2 \right] \lesssim \frac{\log^{4}(n)}{v^{8}n^{6 \alpha + 1}} \E_{j-1} \abs{\Ba_j^H \BQ_j \Bu}^2, \numberthis
\end{align*}
which implies
\begin{align*}
    \E \left[ \sum_{j=1}^n \E_{j-1}\abs{\chi_{2j}}^2 \right]^t \lesssim_t \frac{\log^{4t}(n)}{v^{8t} n^{(6\alpha + 1)t}} \E\left[ \sum_{j=1}^n \E_{j-1}  \Bu^H \BQ_j^H \Ba_j \Ba_j^H \BQ_j \Bu \right]^t \lesssim_t \frac{\log^{6t}(n)}{v^{12t}n^{(6\alpha + 1)t}}. \numberthis
\end{align*}
Similar to \eqref{Eq_chi_4j_2t}, the evaluation for $\sum_j \E |\chi_{2j}|^{2t}$ is given by
\begin{align*}
    &\sum_{j=1}^n \E|\chi_{2j}|^{2t} \lesssim_t \frac{\log^{4t}(n)}{v^{4t}} \sum_{j=1}^n \E \left\{ \left(\E^{1/2}_{-\Bx_j}|\Delta_j|^{4t}\right) \left(\E^{1/2}_{-\Bx_j}|\Bu^H\BQ_j\By_j|^{4t} \right) \abs{\Ba_j^H\BQ_j\Bu}^{2t} \right\} \\
    &\lesssim_t \frac{\log^{4t}(n)}{v^{8t}} \left(n^{-(6\alpha t + 1.5)} + n^{-(4\alpha t + 2)} \right) \sum_{j=1}^n \E |\Ba_j^H\BQ_j \Bu|^{2t} \lesssim_t \frac{\log^{4t + 2}(n)}{v^{10t + 2}} \left(n^{-(6\alpha t + 1.5)} + n^{-(4\alpha t + 2)} \right). \numberthis
\end{align*}
The evaluation for the $\chi_{1j}$-related terms is quite similar to that for $\chi_{2j}$. With the above analysis, it can be verified that when $v$ is close to the real axis, the bound of $\E|\Bu^H[\BQ - \E \BQ]\Bu|^{2t}$ is dominated by $\log^{6t}(n)/(v^{12t}n^{2 \alpha t + 0.5})$, which completes the proof of \eqref{Eq_Part_I}.
\paragraph*{Part II} \label{Para_Part_II}
In this part, we prove that 
\begin{equation}
\label{Eq_Part_II}
    \abs{\Bu^H (\E \BQ - \BR) \Bu} \lesssim \frac{1}{n^{\alpha}v^7}.
\end{equation}
We note that the terms $\Bu$, $\E \BQ$, and $\BR$ are deterministic. By using the resolvent identity $\BA - \BB = \BA(\BB^{-1} - \BA^{-1})\BB$, we have 
\begin{align*}
\Bu^H(\BQ - \BR)\Bu &= \Bu^H\BQ\left(\sum_{j=1}^n \frac{\BOmega_j}{n}(-z\widetilde{\kappa}_j) -z \BA\widetilde{\BG}\BA^H - \sum_{j=1}^n \Bxi_j\Bxi_j^H \right) \BR \Bu \\
&= \sum_{j=1}^n  -z\widetilde{\kappa}_j \frac{\Bu^H\BQ\BOmega_j\BR\Bu}{n} + \frac{\Bu^H\BQ\Ba_j\Ba_j^H\BR\Bu}{1 + \kappa_j} - \frac{\Bu^H\BQ_j\Bxi_j\Bxi_j^H\BR\Bu}{1 + \Bxi_j^H\BQ_j\Bxi_j} \\
&= \sum_{j=1}^n  -z\widetilde{\kappa}_j \frac{\Bu^H\BQ\BOmega_j\BR\Bu}{n} + \frac{\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{1 + \kappa_j} - \frac{\Bu^H\BQ_j\Bxi_j\Bxi_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)} - \frac{\Bu^H\BQ_j\Bxi_j\Bxi_j^H\BR\Bu}{1 + \Bxi_j^H\BQ_j\Bxi_j} \\
&= \sum_{j=1}^n W_{1j} + W_{2j} + W_{3j} + W_{4j}, \numberthis
\end{align*}
where
\begin{align*}
  W_{1j} &= -z\widetilde{\kappa}_j \frac{\Bu^H\BQ\BOmega_j\BR\Bu}{n} - \frac{\Bu^H\BQ_j\By_j\By_j^H\BR\Bu}{1 + \Bxi_j^H\BQ_j\Bxi_j}, ~~ W_{2j} = \frac{(\By_j^H\BQ_j\By_j - \kappa_j)\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)}, \\
  W_{3j} &= - \frac{\Bu^H\BQ_j\By_j\By_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)}, \\
  W_{4j} &= - \frac{\Bu^H\BQ_j\Ba_j\By_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu + \Bu^H\BQ_j\By_j\Ba_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)} \\
  &+ \frac{\Ba_j^H\BQ_j\By_j \Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu + \By_j^H\BQ_j\Ba_j \Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)} \\
  &- \frac{\Bu^H\BQ_j\By_j\Ba_j^H\BR\Bu + \Bu^H\BQ_j\Ba_j\By_j^H\BR\Bu}{1 + \Bxi_j^H\BQ_j\Bxi_j}. \numberthis
\end{align*}
First, we evaluate $\sum_j \E W_{1j}$. Express $\E W_{1j}$ as
\begin{align*}
\E W_{1j} &=\E \left[ (-z \widetilde{q}_j - \eta_j) \left(\frac{\Bu^H\BQ_j\BOmega_j\BR\Bu}{n} - \Bu^H\BQ_j\By_j\By_j^H\BR\Bu\right) \right] + \E\left[ (z\widetilde{q}_j -z\widetilde{\kappa}_j) \frac{\Bu^H\BQ_j\BOmega_j\BR\Bu}{n} \right] \\
&-z\widetilde{\kappa}_j \E \frac{\Bu^H(\BQ - \BQ_j)\BOmega_j\BR\Bu}{n} = \zeta_{1j} + \zeta_{2j} + \zeta_{3j}. \numberthis
\end{align*}
By the Cauchy-Schwarz inequality and Lemma \ref{Lemm_trace}, we have 
\begin{align*}
   \sum_{j=1}^n|\zeta_{1j}| &\leq \sum_{j=1}^n\E^{\frac{1}{2}}\abs{z\widetilde{q}_j \eta_j{\Delta_j}}^2 \E^{\frac{1}{2}}\abs{\frac{1}{n}\Bu^H\BQ_j\BOmega_j\BR\Bu - \By_j^H\BR\Bu\Bu^H\BQ_j\By_j }^2  \lesssim n \cdot \frac{\log^2(n)}{v^3n^{1/2}} \frac{1}{v^2 n} = \frac{\log^2(n)}{v^5 n^{1/2}}. \numberthis
\end{align*}
Here, we have utilized the result $\norm{\BR} \leq 1 / v$, which can be obtained by the properties of the matrix-valued Stieltjes transform \cite[Proposition 2.2]{hachem2007deterministic}. By identity $\E(a - \E a)b = \E a(b - \E b)$ and Hölder’s inequality, the term $|\zeta_{2j}|$ can be bounded as 
\begin{align*}
    \sum_{j=1}^n |\zeta_{2j}| &\leq \sum_{j=1}^n\frac{1}{n}\E |z\widetilde{q}_j|\abs{\Bu^H (\BQ_j - \E \BQ_j) \BOmega_j \BR \Bu}  \lesssim \sum_{j=1}^n\frac{\log^2(n)}{nv} \E^{1/2q} \abs{\Bu^H (\BQ_j - \E \BQ_j) \BOmega_j \BR \Bu}^{2q} \overset{(a)}{\lesssim} \frac{\log^5(n)}{v^{7}n^{\alpha  + 1/4q}} \lesssim \frac{1}{v^{7}n^{ \alpha}}, \numberthis
\end{align*}
where step $(a)$ follows from \eqref{Eq_Part_I} and $q$ is a large enough given number. By using the resolvent decomposition in \eqref{Eq_Wood_resolvent_Id}, $|\zeta_{3j}|$ can be bounded as
\begin{align*}
|\zeta_{3j}| \leq \frac{|z\widetilde{\kappa}_j|}{n} \E \abs{z\widetilde{q}_j \Bu^H\BQ_j\Bxi_j\Bxi_j^H\BQ_j\BOmega_j\BR\Bu} \lesssim \frac{\log^4(n)}{nv^2}\E^{\frac{1}{2}}|\Bu^H\BQ_j\Bxi_j|^2 \E^{\frac{1}{2}}|\Bxi_j^H\BQ_j\BOmega_j\BR\Bu|^2. \numberthis
\end{align*}
By summing over the subscript $j$ and utilizing Lemma \ref{Lemm_Usedul_est}, we can get
\begin{align*}
\sum_{j=1}^n|\zeta_{3j}| \lesssim \frac{\log^4(n)}{nv^2}\left( \sum_{j=1}^n\E|\Bu^H\BQ_j\Bxi_j|^2 \right)^{1/2} \left( \sum_{j=1}^n\E|\Bxi_j^H\BQ_j\BOmega_j\BR\Bu|^2 \right)^{1/2} \lesssim \frac{\log^6(n)}{v^7 n}. \numberthis
\end{align*}
Hence, we have 
\begin{equation}
\label{Eq_Part_II_W1j}
    \abs{\sum_{j=1}^n \E W_{1j}} \lesssim \frac{\log^2(n)}{v^5n^{1/2}} + \frac{1}{v^7n^{\alpha}} + \frac{\log^6(n)}{v^7n}.
\end{equation}
\par
Next, we handle $|\sum_{j=1}^n \E W_{2j}|$. By inequality $|1 + \kappa_j| \lesssim 1 / v$ in Lemma \ref{Lemm_Bound_on_qterms} and the Cauchy-Schwarz inequality, we get
\begin{align*}
\sum_{j=1}^n |\E W_{2j}| &\leq \sum_{j=1}^n  \E \abs{ \frac{(\By_j^H\BQ_j\By_j - \kappa_j)\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)}} \lesssim \sum_{j=1}^n \frac{\log^2(n)}{v^2} |\Ba_j^H\BR\Bu|\E^{1/2}|\Bu^H\BQ_j\Ba_j|^2 \E^{1/2}\abs{\By_j^H\BQ_j\By_j - \kappa_j}^2 \\
&\lesssim \sum_{j=1}^n \frac{\log^2(n)}{v^2} \left( |\Bu^H\BR^H\Ba_j\Ba_j^H\BR\Bu +  \E \Bu^H\BQ_j\Ba_j\Ba_j^H\BQ_j^H\Bu \right) \E^{1/2}\abs{\By_j^H\BQ_j\By_j - \kappa_j}^2. \numberthis
\end{align*}
To evaluate $\E\abs{\By_j^H\BQ_j\By_j - \kappa_j}^2$, we write 
\begin{equation}
  \By_j^H\BQ_j\By_j - \kappa_j = \By_j^H\BQ_j\By_j - \frac{\Tr \BOmega_j \BQ_j}{n} + \frac{\Tr \BOmega_j (\BQ_j - \BQ) }{n}+ \frac{\Tr \BOmega_j (\BQ - \E \BQ)}{n}. \label{Eq_Diff_yQy_to_kappa}
\end{equation}
The third term on the RHS of \eqref{Eq_Diff_yQy_to_kappa} can be written as the sum of a martingale difference sequence 
\begin{equation}
  \frac{1}{n} \Tr \BOmega_j (\BQ - \E \BQ) = \sum_{j=1}^n \frac{1}{n} \Tr \BOmega_j [\E_j - \E_{j-1}] (\BQ - \BQ_j) = \sum_{j=1}^n [\E_j - \E_{j-1}] \frac{1}{n} z\widetilde{q}_j{\Bxi_j^H\BQ_j\BOmega_j\BQ_j\Bxi_j}.
\end{equation}
Using the fact $|z\widetilde{q}_j{\Bxi_j^H\BQ_j\BOmega_j\BQ_j\Bxi_j}| \leq \norm{\BOmega_j}/v$ and Lemma \ref{Lemm_Burk_Ineq}, we can obtain $
  \E \abs{\frac{1}{n} \Tr \BOmega_j (\BQ - \E \BQ)}^2 \lesssim n^{-1}v^{-2}
$. Thus, we get the bound $\E\abs{\By_j^H\BQ_j\By_j - \kappa_j}^2 \lesssim n^{-1}v^{-2}$, which implies 
\begin{align*}
\sum_{j=1}^n |\E W_{2j}| &\lesssim  \frac{\log^2(n)}{v^3n^{1/2}} \sum_{j=1}^n\left( |\Bu^H\BR^H\Ba_j\Ba_j^H\BR\Bu +  \E \Bu^H\BQ_j\Ba_j\Ba_j^H\BQ_j^H\Bu \right)  \lesssim \frac{\log^2(n)}{v^3 n^{1/2}} \left( \frac{1}{v^2} + \frac{\log^{2}(n)}{v^4} \right) \lesssim \frac{\log^4(n)}{n^{1/2}v^7}. \numberthis \label{Eq_Part_II_W2j}
\end{align*}
The evaluation for $\sum_j |\E W_{3j}|$ is given by
\begin{align*}
\sum_{j=1}^n |\E W_{3j}| &\leq \sum_{j=1}^n\E \abs{ \frac{\Bu^H\BQ_j\By_j\By_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu}{(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)}} \lesssim \frac{\log^2(n)}{v^2} \sum_{j=1}^n |\Ba_j^H\BR\Bu| \E^{1/2}|\Bu^H\BQ_j\By_j|^2 \E^{1/2} |\By_j^H\BQ_j\Ba_j|^2 \\
& \lesssim    \frac{\log^2(n)}{nv^4} \sum_{j=1}^n|\Ba_j^H\BR\Bu| \leq \frac{\log^2(n)}{nv^4} \cdot \sqrt{n} \cdot \left(\sum_{j=1}^n \Bu^H\BR^H \Ba_j\Ba_j^H\BR\Bu \right)^{1/2}\lesssim  
 \frac{\log^2(n)}{n^{1/2}v^5}. \numberthis \label{Eq_Part_II_W3j}
\end{align*}
\par
To estimate $|\sum_j\E W_{4j}|$, we write $W_{4j} = P_{j}/[(1 + \kappa_j)(1 + \Bxi_j^H\BQ_j\Bxi_j)] + z\widetilde{q}_jQ_j$, where 
\begin{align*}
    P_j &= - \Bu^H\BQ_j\Ba_j\By_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu - \Bu^H\BQ_j\By_j\Ba_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu  + \Ba_j^H\BQ_j\By_j \Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu \\
    &+ \By_j^H\BQ_j\Ba_j \Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu,  \\
    Q_j &= \Bu^H\BQ_j\By_j\Ba_j^H\BR\Bu +\Bu^H\BQ_j\Ba_j\By_j^H\BR\Bu. \numberthis
\end{align*}
It can be verified that $\E P_j =\E Q_j = 0$ and 
% \begin{align*}
%    \sum_{j=1}^n \E|P_j|^2 &\lesssim \sum_{j=1}^n  \frac{1}{n} \Big[v^{-2}\E|\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2 + v^{-2} \E|\Ba_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2 + v^{-2}\E|\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2 \\
%     &+ v^{-2} \E |\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2  + \left(v^{-2} + 1\right)^2 \left( v^{-2}\E |\Ba_j^H\BQ_j\BR\Bu|^2 + v^{-4} \E |\Bu^H\BQ_j\Ba_j|^2  \right) \Big] \\
%     & \lesssim \frac{1}{nv^6} + \frac{\log^2(n)}{nv^{10}}. \numberthis \\
%     \sum_{j=1}^n \E|Q_j|^2 &\lesssim \left( v^{-2}\E |\Ba_j^H\BQ_j\BR\Bu|^2 + v^{-4} \E |\Bu^H\BQ_j\Ba_j|^2  \right) 
% \end{align*}
\begin{align*}
   \sum_{j=1}^n \E|P_j|^2 &\lesssim \sum_{j=1}^n  \frac{1}{n} \Big[v^{-2}\E|\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2 + v^{-2} \E|\Ba_j^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2 + v^{-2}\E|\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2 \\
    &+ v^{-2} \E |\Bu^H\BQ_j\Ba_j\Ba_j^H\BR\Bu|^2  \Big]  \lesssim \frac{1}{nv^6}. \numberthis \\
    \sum_{j=1}^n \E|Q_j|^2 &\lesssim \frac{1}{n}\sum_{j=1}^n \left( v^{-2}\E |\Ba_j^H\BR\Bu|^2 + v^{-2} \E |\Bu^H\BQ_j\Ba_j|^2  \right)  \lesssim \frac{\log^2(n)}{n v^6}.
\end{align*}
By writing $-z \widetilde{q}_j = \eta_j + z\widetilde{q}_j\eta_j \Delta_j$, we can obtain
\begin{align*}
\abs{ \sum_{j=1}^n \E W_{4j}} &\leq \sum_{j=1}^n \E \abs{\frac{P_j\Delta_j\eta_j z\widetilde{q}_j}{1 + \kappa_j}} + \E \abs{Q_j\Delta_j\eta_j z\widetilde{q}_j} \lesssim \frac{\log^2(n)}{v^3} \sum_{j=1}^n \E^{\frac{1}{2}}|\Delta_j|^2 \E^{\frac{1}{2}} |P_j|^2 + \frac{\log^2(n)}{v^2} \sum_{j=1}^n \E^{\frac{1}{2}}|\Delta_j|^2 \E^{\frac{1}{2}} |Q_j|^2 \\
&\lesssim \frac{\log^2(n)}{v^4}\left( \sum_{j=1}^n \E|P_j|^2 \right)^{\frac{1}{2}} + \frac{\log^2(n)}{v^3}\left( \sum_{j=1}^n \E|Q_j|^2 \right)^{\frac{1}{2}} \lesssim\frac{\log^3(n)}{n^{\frac{1}{2}}v^7}. \numberthis \label{Eq_Part_II_W4j}
\end{align*}
Combining the results from \eqref{Eq_Part_II_W1j}, \eqref{Eq_Part_II_W2j}, \eqref{Eq_Part_II_W3j}, and \eqref{Eq_Part_II_W4j}, we can prove \eqref{Eq_Part_II}.
\paragraph*{Part III} In this part, we will prove
\begin{equation}
\label{Eq_Part_III}
  \abs{\Bu^H [\BR - \BTheta] \Bu} \lesssim \frac{\mathcal{U}(z)}{n^{\alpha}},
\end{equation}
where $\mathcal{U}(z) = (K_2 + x^2 + v^2)^{9} / v^{29}$.
Before devoting to the detail of the proof, we first evaluate two differences $-z \widetilde{\kappa}_j - z [\widetilde{\BR}]_{j, j}$, and $\kappa_j - \Tr \BOmega_j \BR / n$, which are given in the following proposition
\begin{proposition}
\label{Prop_Co_Res_trace}
    For $z = x + \jmath v$ with $v \leq K_{\mathrm{im}}$, we have
    \begin{align*}
        \abs{-z\widetilde{\kappa}_j - (-z[\widetilde{\BR}]_{j, j})} \lesssim \frac{1}{n^{\alpha}v^9}, ~~ \abs{\kappa_j - \frac{1}{n}\Tr \BOmega_j \BR} \lesssim \frac{1}{n^{\alpha}v^7}. \numberthis
    \end{align*}
\end{proposition}
\textit{Proof: } We first handle the first inequality. By the Woodbury matrix identity, we have 
\begin{equation}
[\widetilde{\BR}]_{j, j} =-\frac{1}{z(1 + \kappa_j)} + \frac{\Ba_j^H\BR\Ba_j}{z(1 + \kappa_j)^2}. \numberthis
\end{equation}
Then, the difference $-z \widetilde{\kappa}_j - (-z [\widetilde{\BR}]_{j, j})$ can be evaluated as
\begin{align*}
&-z \widetilde{\kappa}_j - (-z [\widetilde{\BR}]_{j, j}) = \E \left[\frac{1}{1 + \Bxi_j^H\BQ_j\Bxi_j} - \eta_j \right] + \E \left[\eta_j - \frac{1}{1 + \alpha_{j,j}} + \frac{\Ba_j^H\BQ\Ba_j}{(1 + \alpha_{j, j})^2} \right] + \E \left[ \frac{1}{1 + \alpha_{j,j}} - \frac{1}{1 + \kappa_j} \right] \\
&+ \frac{\Ba_j^H(\BR - \E \BQ)\Ba_j }{(1 + \kappa_j)^2} + \E \left[ \Ba_j^H \BQ \Ba_j\left( \frac{1 }{(1 + \kappa_j)^2} - \frac{1}{(1 + \alpha_{j,j})^2} \right)\right] = X_{1j} + X_{2j} + X_{3j} + X_{4j} + X_{5j}. \numberthis \label{Eq_kappa_j_wR_jj}
\end{align*}
Next, we evaluate the term $ X_{ij}$ for $i \in \{1, \ldots, 5\}$. For $X_{1j}$,  it is straightforward to show that $|X_{1j}| \leq \mathbb{E} |z\widetilde{q}_j \eta_j \Delta_j| \lesssim \log^2(n)v^{-3}n^{-1/2}$. Using \eqref{Eq_Wood_resolvent_Id} and $-z\widetilde{q}_j = \eta_j + z\widetilde{q}_j \Delta_j \eta_j $, we have 
\begin{align*}
    X_{2j} &= \E \left[\eta_j - \frac{1}{1 + \alpha_{j,j}} + \frac{\Ba_j^H\BQ_j\Ba_j - (\eta_j + z\widetilde{q}_j \Delta_j \eta_j) \Ba_j^H \BQ_j \Bxi_j \Bxi_j^H \BQ_j\Ba_j }{(1 + \alpha_{j, j})^2} \right] \\
    & = \E \left[ \eta_j - \frac{1}{1 + \alpha_{j,j}} + \frac{\Ba_j^H\BQ_j\Ba_j - \eta_j \Ba_j^H \BQ_j \Ba_j \Ba_j^H \BQ_j\Ba_j }{(1 + \alpha_{j, j})^2} \right] \\
    &- \E \left[\frac{\eta_j(\Ba_j^H\BQ_j\Ba_j\By_j^H\BQ_j\Ba_j + \Ba_j^H\BQ_j\By_j\Ba_j^H\BQ_j\Ba_j + \Ba_j^H\BQ_j\By_j\By_j^H\BQ_j\Ba_j)}{(1 + \alpha_{j,j})^2} \right] \\
    & -\E \left[\frac{ z\widetilde{q}_j \Delta_j \eta_j \Ba_j^H \BQ_j \Bxi_j \Bxi_j^H \BQ_j\Ba_j }{(1 + \alpha_{j, j})^2} \right] = X_{2j, 1} + X_{2j, 2} + X_{2j, 3}. \numberthis \label{Eq_kappa_j_wR_jj_X_2j}
\end{align*}
It can be shown that $X_{2j, 1} = 0$. As $\By_j$ is independent of $\eta_j$, $\alpha_j$, and $\BQ_j$, we have $|X_{2j, 2}| \lesssim n^{-1}v^{-5}$. By the same method as in \cite[Lemma 2.6]{SILVERSTEIN1995Empirical}, we have $|z\widetilde{q}_j\Ba_j^H \BQ_j \Bxi_j \Bxi_j^H \BQ_j\Ba_j| \leq \norm{\Ba_j}^2 / v \leq \norm{\BA}^2 / v$ and 
\begin{align*}
    |X_{2j, 3}| \lesssim \frac{1}{v^4} \E^{1/2} |\Delta_j|^2 \lesssim \frac{1}{v^5 n^{1/2}}. \numberthis
\end{align*}
Hence, we get $|X_{2j}| \lesssim v^{-5}n^{-1/2}$. The bounds $|X_{3j}| \lesssim v^{-3}n^{-1}$ and $|X_{5j}| \lesssim v^{-7}n^{-1}$ can be obtained by Lemma \ref{Lemm_Bound_on_qterms}. According to \eqref{Eq_Part_II} and  Lemma \ref{Lemm_Bound_on_qterms}, we have $|X_{4j}| \lesssim n^{-\alpha}v^{-9}$. Therefore, it can be concluded that
$
    |-z \widetilde{\kappa}_j - (-z [\widetilde{\BR}]_{j, j})|\lesssim {v^{-9} n^{-\alpha}},
$
which proves the first inequality.
\par
For the second inequality, we write the eigen-decomposition of $\BOmega_j$ as $\BOmega_j = \sum_{i = 1}^p \lambda^j_i\Bu^j_i(\Bu^j_i)^H  $. Then, the following holds by \eqref{Eq_Part_II}
\begin{align*}
    \abs{\kappa_j - \frac{1}{n} \Tr \BOmega_j \BR} \leq \frac{1}{n}\sum_{i=1}^p \lambda^j_i\abs{ (\Bu^j_i)^H[\E \BQ - \BR] \Bu^j_i} \lesssim \frac{1}{v^{7}n^{\alpha}}. \numberthis
\end{align*}
Therefore, we have completed the proof. \qed
\par
Denote $\Bkappa = [\kappa_1, \ldots, \kappa_n]^T$, $\widetilde{\Bkappa} = [\widetilde{\kappa}_1, \ldots, \widetilde{\kappa}_n]^T$, $\Bdelta = [\delta_1, \ldots, \delta_n]^T$, and $\widetilde{\delta}_j = [\widetilde{\delta}_1, \ldots, \widetilde{\delta}_n]^T$. Given $\BR$ is a function of $(\Bkappa, \widetilde{\Bkappa})$, and $\BTheta $ is a function of $(\Bdelta, \widetilde{\Bdelta})$, it is essential to evaluate $\|\Bkappa - \Bdelta\|_{\infty}$ and $\| \widetilde{\Bkappa} - \widetilde{\Bdelta} \|_{\infty}$ in order to analyze $\Bu^H[\BR - \BTheta]\Bu $. By writing $\kappa_j - \delta_j = \kappa_j - \frac{1}{n} \Tr \BOmega_j \BR + \frac{1}{n} \Tr \BOmega_j \BR - \delta_j$, and then applying the resolvent identity $ \BR - \BTheta = \BR(\BTheta^{-1}- \BR^{-1})\BTheta $, we can obtain the following system of equations
\begin{equation}
  \begin{bmatrix}
   \Bkappa - \Bdelta \\
   z\widetilde{\Bkappa} - z\widetilde{\Bdelta}  
  \end{bmatrix} = \begin{bmatrix}
    \Bd \\
    z\widetilde{\Bd}  
   \end{bmatrix} + \begin{bmatrix}
    z^2 \BPsi_{\kappa, \delta} & \BGamma_{\kappa, \delta} \\
    z^2\widetilde{\BGamma}_{\kappa, \delta} & z^2 \BPhi_{\kappa, \delta}
   \end{bmatrix} \begin{bmatrix}
    \Bkappa - \Bdelta \\
    z\widetilde{\Bkappa} - z\widetilde{\Bdelta}  
   \end{bmatrix}, \label{Eq_Maitrx_kappa_delta}
\end{equation} 
where $[\Bd]_j = \frac{1}{n} \Tr \BOmega_j (\E \BQ - \BR), ~~ [\widetilde{\Bd}]_j = \widetilde{\kappa}_{j} - [\widetilde{\BR}]_{j,j}$, and the matrix blocks are defined as
\begin{align*}
&[\BPsi_{\kappa, \delta}]_{j, l} = \frac{1}{n}[\widetilde{\BF} \BA^H \BTheta \BOmega_{j} \BR \BA \widetilde{\BG}]_{l, l},  ~~ [\BGamma_{\kappa, \delta}]_{j, l} = \frac{1}{n^2}\Tr \BOmega_{j}\BR \BOmega_l \BTheta, \\
&[\widetilde{\BGamma}_{\kappa, \delta}]_{j, l} = [\widetilde{\BR}]_{j, l} [\widetilde{\BTheta}]_{l, j}, ~~[\BPhi_{\kappa, \delta}]_{j, l} = \frac{1}{n} [\widetilde{\BR}\BA^H \BG\BOmega_l \BF \BA \widetilde{\BTheta}]_{j, j}. \numberthis \label{Eq_Def_of_Gamma_Phi_Psi_delta_kappa}
% & \BF = \left[-z \left( \BI_p + \textstyle\sum_{j=1}^n {\BOmega_j \widetilde{\delta}_j}\big/{n} \right) \right]^{-1}, ~~ \widetilde{\BF} = \left[ -z(\BI_n + \BD_{\delta}) \right]^{-1}, \\
% &\BG = \left[-z\left( \BI_p + \textstyle\sum_{j=1}^n {\BOmega_j \widetilde{\kappa}_j}\big/{n} \right) \right]^{-1}, ~~ \widetilde{\BG} = \left[ -z(\BI_n + \BD_{\kappa}) \right]^{-1}. 
\end{align*}
According to Proposition \ref{Prop_Co_Res_trace}, we know $\|\Bd\|_{\infty} \leq K v^{-9}n^{-\alpha}$ and $\|z\widetilde{\Bd}\|_{\infty} \leq K v^{-7}n^{-\alpha}$ for some constant $K$. To control the difference vector $(\Bkappa - \Bdelta, \widetilde{\Bkappa} - \widetilde{\Bdelta})$, we need to solve the above system of equations. By the Cauchy-Schwarz inequality, we have 
\begin{align*}
    \abs{[\BPi_{\kappa, \delta}]_{j, l}} \leq \sqrt{[\BPi_{ \kappa}]_{j, l} [\BPi_{ \delta}]_{j, l}}, \numberthis
\end{align*}
where $\BPi$ can be any of $\{ \BPsi, \BGamma, \widetilde{\BGamma}, \BPhi\}$, which are given by
\begin{align*}
&[\BPsi_{\kappa}]_{j, l} = \frac{1}{n}[\widetilde{\BG}^H \BA^H \BR^H \BOmega_{j} \BR \BA \widetilde{\BG}]_{l, l},  ~~ [\BGamma_{\kappa}]_{j, l} = \frac{1}{n^2}\Tr \BOmega_{j}\BR \BOmega_l \BR^H, \\
&[\widetilde{\BGamma}_{\kappa}]_{j, l} = [\widetilde{\BR}]_{j, l} [\widetilde{\BR}^H]_{l, j}, ~~[\BPhi_{\kappa}]_{j, l} = \frac{1}{n} [\widetilde{\BR}\BA^H \BG\BOmega_l \BG^H \BA \widetilde{\BR}^H]_{j, j},\\
&[\BPsi_{\delta}]_{j, l} = \frac{1}{n}[\widetilde{\BF} \BA^H \BTheta \BOmega_{j} \BTheta^H \BA \widetilde{\BF}^H]_{l, l},  ~~ [\BGamma_{\delta}]_{j, l} = \frac{1}{n^2}\Tr \BOmega_{j}\BTheta^H \BOmega_l \BTheta, \\
&[\widetilde{\BGamma}_{\delta}]_{j, l} = [\widetilde{\BTheta}^H]_{j, l} [\widetilde{\BTheta}]_{l, j}, ~~[\BPhi_{\delta}]_{j, l} = \frac{1}{n} [\widetilde{\BTheta}^H\BA^H \BF^H \BOmega_l \BF \BA \widetilde{\BTheta}]_{j, j}. \numberthis \label{Eq_Def_of_Gamma_Phi_Psi_delta_kappa_split}
\end{align*}
We note that $\BT^H = \BT(z^*)$ for $\BT \in \{\BF, \BTheta, \widetilde{\BF}, \widetilde{\BTheta},\BG, \BR, \widetilde{\BG}, \widetilde{\BR} \}$. Intuitively, by Lemma \ref{Lemm_matrix_Spr_maxrow_Norm}, to control the error, it is sufficient to study the properties of $\BPi_\kappa$ and $\BPi_\delta$, which are more tractable since each term of $\BPi_\kappa$ and $\BPi_{\delta}$ only involves the terms with respect to $(\Bkappa, \widetilde{\Bkappa})$ and $(\Bdelta, \widetilde{\Bdelta})$.
% Similar to \eqref{Eq_Maitrx_kappa_delta}, we define $\BC_{\Bdelta}$ and $\BC_{\kappa}$ as 
% \begin{equation}
%     \BC_{\kappa} = \begin{bmatrix}
%     |z|^2 \BPsi_{\kappa} & \BGamma_{\kappa} \\
%     |z|^2\widetilde{\BGamma}_{\kappa} & |z|^2 \BPhi_{\kappa}
%    \end{bmatrix}, ~~~ \BC_{\delta} = \begin{bmatrix}
%     |z|^2 \BPsi_{\delta} & \BGamma_{\delta} \\
%     |z|^2\widetilde{\BGamma}_{\delta} & |z|^2 \BPhi_{\delta}
%    \end{bmatrix}.
% \end{equation}
% By \cite[Lemma 13]{AblaNoEigen}, we know that the spectral radius $\rho(\BC_{\kappa, \delta}) \leq \sqrt{\rho(\BC_{\kappa}) \rho(\BC_{\delta})}$ and the max-row norm $ \| (\BI_{2n} - \BC_{\kappa, \delta})^{-1}\|_{\infty} \leq \sqrt{\| (\BI_{2n} - \BC_{\kappa})^{-1}\|_{\infty}\| (\BI_{2n} - \BC_{\delta})^{-1}\|_{\infty}} $. Therefore, it suffices to study the properties of $\BC_\kappa$ and $\BC_\delta$. 
In fact, by the identity $\Im a = (a - a^*) / 2 \jmath$ and using the same method to get \eqref{Eq_Maitrx_kappa_delta}, we can obtain the following system of equations
\begin{align*}
&\begin{bmatrix}
      \Im \Bkappa \\
      \Im z \widetilde{\Bkappa} 
  \end{bmatrix} = \begin{bmatrix}
    \Im \Bd \\
   \Im z\widetilde{\Bd}
\end{bmatrix}  + v \begin{bmatrix}
       \Bv_{\kappa}\\
      |z|^2 \Bu_{\kappa}
  \end{bmatrix} + \begin{bmatrix}
      |z|^2\BPsi_{\kappa} &  \BGamma_{\kappa} \\
      |z|^2\widetilde{\BGamma}_{\kappa} & |z|^2 \BPhi_{\kappa}
  \end{bmatrix}\begin{bmatrix}
      \Im \Bkappa \\
      \Im z \widetilde{\Bkappa} 
  \end{bmatrix}, \numberthis \label{Eq_Im_kappa_Im_wkappa}\\
  &\begin{bmatrix}
      \Im \Bdelta \\
      \Im z \widetilde{\Bdelta} 
  \end{bmatrix} = v \begin{bmatrix}
       \Bv_{\delta}\\
      |z|^2 \Bu_\delta
  \end{bmatrix} + \begin{bmatrix}
      |z|^2\BPsi_{\delta}&  \BGamma_{\delta} \\
      |z|^2\widetilde{\BGamma}_{\delta} & |z|^2 \BPhi_{\delta}
  \end{bmatrix}\begin{bmatrix}
      \Im \Bdelta \\
      \Im z \widetilde{\Bdelta} 
  \end{bmatrix}, \numberthis \label{Eq_Im_delta_Im_wdelta}
\end{align*}
with $[\Bv_\delta]_j = \frac{1}{n} \Tr \BOmega_j \BTheta^H \BTheta$, $[\Bu_\delta]_j = [\widetilde{\BTheta}^H \BA^H\BF^H\BF\BA\widetilde{\BTheta}]_{j, j}$, $[\Bv_\kappa]_j = \frac{1}{n} \Tr \BOmega_j \BR \BR^H$, and $[\Bu_\kappa]_j = [\widetilde{\BR} \BA^H \BG\BG^H \BA\widetilde{\BR}^H]_{j, j}$. By Lemma \ref{Lemm_Spr_pMat}, we can obtain $\rho(|z|^2 \BPhi_{\delta}) < 1$ for $z \in \mathbb{C}^+$ and 
\begin{align*}
    \norm{(\BI_{n} - |z|^2\BPhi_{\delta})^{-1}}_{\infty} &\leq \frac{\max_j(\Im (z \widetilde{\delta}_j))}{\min_j(v|z|^2 [\Bu_{\delta}]_j + \sum_{l} |z|^2 [\widetilde{\BGamma}_{\delta}]_{j, l} \Im(\delta_l))} \leq \frac{\max_j(\Im (z \widetilde{\delta}_j))}{\min_j (|z|^2 |\widetilde{\delta}_{j}|^2 \Im(\delta_j) )} \\
    & \overset{(a)}{\leq} \frac{\frac{K_0}{v}}{v^2 \cdot \frac{v^3K_1^3}{(K_2 + x^2+ v^2)^3}} = \frac{K_0(K_2 + x^2+ v^2)^3}{K_1^3 v^6}, \numberthis \label{Eq_I_minus_z_Phi_delta}
\end{align*}
where step $(a)$ follows by $|z| \geq v$, $|\widetilde{\delta}_j| \geq |\Im \widetilde{\delta}_j|$, and Lemma \ref{Lemm_Bound_on_qterms}. Here, the constants $K_j$, $j =0, 1, 2$ are the same as those in Lemma \ref{Lemm_Bound_on_qterms}. Without loss of generality, we assume $K_2 > 1$ in the following. Solving $\Im z\widetilde{\Bdelta}$ in \eqref{Eq_Im_delta_Im_wdelta}, we can get
\begin{align*}
\Im \Bdelta &= \BJ_{\delta} \Im\Bdelta  + v \Bv_{\delta} + v|z|^2\BGamma_{\delta}\left(\BI_n - |z|^2 \BPhi_{\delta}\right)^{-1} \Bu_{\delta}, \numberthis \label{Eq_J_delta}
\end{align*}
where $\BJ_\delta = |z|^2 \BPsi_{\delta} + |z|^2 \BGamma_{\delta} \left(\BI_n - |z|^2 \BPhi_{\delta}\right)^{-1}\widetilde{\BGamma}_\delta $. Using Lemma \ref{Lemm_Spr_pMat}, we have 
\begin{equation}
    \norm{(\BI_n - \BJ_\delta)^{-1}}_{\infty} \leq \frac{\max_j(\Im\delta_j)}{\min_j(v[\Bv_{\delta}]_j)} \leq \frac{K_0 (K_2 + x^2 + v^2)^2}{v^4 {K}_1^2}. \label{Eq_I_minus_J_delta_inv}
\end{equation}
\par
Next, we derive a similar norm bound for the matrices in \eqref{Eq_Im_kappa_Im_wkappa}. It can be observed that the RHS of \eqref{Eq_Im_kappa_Im_wkappa} involves $\Im \Bd$ and $\Im z \Bd$, whose elements are not always positive. To apply Theorem \ref{Lemm_Spr_pMat}, we need to determine the range of $z$. To that end, we define the following sets
\begin{equation}
 \mathfrak{A} = \left\{z: \frac{K(K_2 + x^2 + v^2)^3}{n^{\alpha}K_1^3v^{12}} \leq \frac{1}{2} \right\}, ~~ \mathfrak{E} = \{z: v \leq K_{\mathrm{im}}\}. \label{Eq_Def_of_range_z_A_E}
\end{equation}
Here, the constant $K$ is from the bounds $\|\Bd \|_{\infty} \leq K v^{-9}n^{-\alpha}$ and $\| z \widetilde{\Bd} \|_{\infty} \leq K v^{-7}n^{-\alpha}$. Then, for $z \in \mathfrak{A} \cap \mathfrak{E}$, we have $\rho(|z|^2 \BPhi_{\kappa}) < 1$ and 
\begin{align*}
  \norm{(\BI_n - |z|^2 \BPhi_{\kappa})^{-1}}_{\infty} &\leq \frac{\max_j (\Im(z\widetilde{\kappa_j}))}{\min_j(|z|^2|\widetilde{\kappa}_j|^2\Im(\kappa_j)) - \norm{z\Bd}_{\infty}}  \leq \frac{\frac{K_0}{v}}{\frac{v^5K_1^3}{(K_2 + x^2 + v^2)^3} - \frac{K}{n^\alpha v^7}}  \leq \frac{2K_0(K_2 + x^2 + v^2)^3}{K^3_1v^6}.  \numberthis \label{Eq_norm_I_minus_Phi}
\end{align*}
Solving \eqref{Eq_Im_kappa_Im_wkappa} with respective to $\Im (z\widetilde{\Bkappa})$, we can obtain
\begin{equation}
    (\BI_n - \BJ_{\kappa})\Im(\Bkappa) = \Im(\Bd) + v\Bv_{\kappa} + \BGamma_\kappa (\BI_n - |z|^2\BPhi_\kappa)^{-1} \Im(z\widetilde{\Bd})
     + |z|^2\BGamma_{\kappa} (\BI_n - |z|^2 \BPhi_\kappa)^{-1} \Bu_{\kappa},
\end{equation}
with $\BJ_\kappa = |z|^2 \BPsi_{\kappa} + |z|^2 \BGamma_{\kappa} \left(\BI_n - |z|^2 \BPhi_{\kappa}\right)^{-1}\widetilde{\BGamma}_\kappa$.
To evaluate $\| (\BI - \BJ_\kappa)^{-1} \|_{\infty}$,  we define another set $\mathfrak{B} \subset \mathbb{C}^+$ as
\begin{equation}
  \mathfrak{B} = \left\{ z: \frac{K(2K_0^3 + K_1^3)(K_2 + x^2 + v^2)^5}{K_1^5 v^{18}n^{\alpha}} \leq \frac{1}{2}\right\}. \label{Eq_Def_of_range_z_B}
\end{equation}
Hence, for $z \in \mathfrak{A} \cap \mathfrak{B} \cap \mathfrak{E}$, we have 
\begin{align*}
  \norm{(\BI_n - \BJ_{\kappa})^{-1}}_{\infty} & \leq \frac{\max_j(\Im(\kappa_j))}{\min_j(v [\Bv_{\kappa}]_j)- \norm{\Im(\Bd)}_{\infty} - \|\BGamma_\kappa (\BI_n-  |z|^2\BPhi_\kappa)^{-1} \Im(z\widetilde{\Bd})\|_{\infty}} \\
  &\leq \frac{\frac{K_0}{v}}{\frac{v^3{K}_1^2}{(K_2 + x^2 + v^2)^2} - \frac{K}{n^{\alpha}v^9} - \frac{2K_0^3(K_2 + x^2 + v^2)^3}{K_1^3v^8} \frac{K}{n^{\alpha }v^7}} \\
  & \leq \frac{\frac{K_0}{v}}{\frac{v^3{K}_1^2}{(K_2 + x^2 + v^2)^2} - \frac{K(2K_0^3 + K_1^3)(K_2 + x^2 + v^2)^3}{K_1^3v^{15}n^{\alpha}} } \leq \frac{2K_0 (K_2 + x^2 + v^2)^2}{v^4 {K}_1^2}, \numberthis
\end{align*}
given $\norm{\BGamma_{\kappa}}_{\infty} \norm{(\BI_n - |z|^2 \BPhi_{\kappa})^{-1}}_{\infty} \leq {2K_0^3(K_2 + x^2 + v^2)^3}/{(K_1^3v^8)}$ by \eqref{Eq_norm_I_minus_Phi} and Lemma \ref{Lemm_Bound_on_qterms}. Thus, by \eqref{Eq_Maitrx_kappa_delta}, the error can be controlled as
\begin{align*}
    \norm{\Bkappa - \Bdelta}_{\infty} &\leq  \norm{(\BI_n - \BJ_{\kappa, \delta})^{-1}}_{\infty}\left( \norm{\Bd}_{\infty} + \norm{\BGamma_{\kappa, \delta}}_{\infty} \norm{(\BI_n - z^2\BPhi_{\kappa, \delta})^{-1}}_{\infty} \norm{z\widetilde{\Bd}}_{\infty} \right) \\
    &\overset{(a)}{\leq} \frac{\sqrt{2}K_0 (K_2 + x^2 + v^2)^2}{v^4 {K}_1^2}\left(\frac{K}{v^9n^{\alpha} } + \frac{\sqrt{2}K_0^3(K_2 + x^2 + v^2)^3}{K_1^3v^8} \cdot \frac{K}{v^7n^{\alpha}}\right),\\
    & \leq  \frac{K'_0 (K_2 + x^2 + v^2)^5}{n^{\alpha}v^{19}}, ~~~ z \in \mathfrak{A} \cap \mathfrak{B} \cap \mathfrak{E}, \numberthis
\end{align*}
where $K'_0 > 0$ is a constant independent of $n$ and step $(a)$ follows from
$ \|(\BI_{n} - \BJ_{\kappa, \delta})^{-1} \|_{\infty} \leq \sqrt{\|(\BI_{n} - \BJ_{\kappa})^{-1} \|_{\infty}\|(\BI_{n} - \BJ_{ \delta} )^{-1}\|_{\infty}}$ and $\|(\BI_n - z^2 \BPhi_{\kappa, \delta})^{-1}\|_{\infty} \leq \sqrt{\|(\BI_n - |z|^2 \BPhi_{\kappa})^{-1}\|_{\infty}\|(\BI_n - |z|^2 \BPhi_{ \delta})^{-1}\|_{\infty} } $, which can be obtained by
Lemma \ref{Lemm_matrix_Spr_maxrow_Norm}. When $z \in (\mathfrak{A} \cap \mathfrak{B})^{c} \cap \mathfrak{E}$ and by definition of the three sets defined in \eqref{Eq_Def_of_range_z_A_E} and \eqref{Eq_Def_of_range_z_B}, we have
\begin{equation}
\label{Eq_Bound_on_Diff_kappa_delta}
  \norm{\Bkappa - \Bdelta}_{\infty} \leq \frac{4K_0}{v} \cdot \frac{1}{2} \leq \frac{K''_0}{n^{\alpha}}\max\left\{ \frac{(K_2 + x^2 + v^2)^5}{v^{19}}, \frac{(K_2 + x^2 + v^2)^3}{v^{13}} \right\} \overset{(a)}{\leq} \frac{K_0''(K_2 + x^2 + v^2)^5}{v^{19}n^{\alpha}},
\end{equation}
where constant $K_0'' > 0$ and step $(a)$ follows from $K_2 > 1$ and $v \leq K_{\mathrm{im}}$. By \eqref{Eq_Maitrx_kappa_delta} and \eqref{Eq_Bound_on_Diff_kappa_delta}, we get 
\begin{align*}
    \norm{\widetilde{\Bkappa} - \widetilde{\Bdelta}}_{\infty} &= \norm{(\BI_n - z^2\BPhi_{\kappa, \delta})^{-1} \left( \widetilde{\Bd} + z \widetilde{\BGamma}_{\kappa, \delta}(\Bkappa - \Bdelta)\right)}_{\infty} \leq 
    % \frac{K_0'''(K_2 + x^2+ v^2)^3}{K_1^3 v^6 n^{\alpha}}\left(\frac{1}{v^8} + \frac{(K_2 + x^2 + v^2)^{5.5}}{v^{21}} \right) \\
    % &\leq 
    \frac{K_0'''(K_2 + x^2+ v^2)^{8.5}}{ v^{27} n^{\alpha}}, ~~ z \in \mathfrak{E}, \numberthis \label{Eq_Bound_on_Diff_wkappa_wdelta}
\end{align*}
where we have used $1/|z| \leq 1 / v$ and $|z| \leq (K_2 + x^2 + v^2)^{1/2}$. 
% Thus, combining the bounds in \eqref{Eq_Bound_on_Diff_kappa_delta} and \eqref{Eq_Bound_on_Diff_wkappa_wdelta}, we have
% \begin{equation}
%   \max\left\{ \norm{\widetilde{\Bkappa} - \widetilde{\Bdelta}}_{\infty}, \norm{\Bkappa - \Bdelta}_{\infty} \right\} \leq \frac{\widetilde{K}_0(K_2 + x^2+ v^2)^{10}}{v^{27} n^{\alpha}},
% \end{equation}
% with $\widetilde{K}_0 > 0$ an absolute constant.  
Now we can give the bound on $|\Bu^H(\BR - \BTheta)\Bu|$ for any deterministic vector $\Bu$. In fact, we can bound the spectral norm of the difference $\BR - \BTheta$.
By the resolvent identity $\BR - \BTheta = \BR (\BTheta^{-1} - \BR^{-1})\BTheta$ and $\norm{\BF}$, $\norm{\BG} \leq 1 / v$, the following holds
\begin{align*}
  &\norm{\BR - \BTheta} \leq  \sum_{j=1}^n\frac{ \norm{\BR\BOmega_j\BTheta}}{n} \abs{z\widetilde{\kappa}_j - z\widetilde{\delta}_j} + |z|^2\norm{\BR\BA\BG(\BD_{\kappa} - \BD_{\delta})\BF\BA^H\BTheta} \\
  &\leq \widetilde{K}_0 \left( v^{-2}|z|\norm{\widetilde{\Bkappa} - \widetilde{\Bdelta}}_{\infty} +  v^{-4} |z|^2\norm{\Bkappa - \Bdelta}_{\infty}\right) 
  % \leq \widetilde{K}_0 \left( \frac{(K_2 + x^2+ v^2)^{9}}{ v^{29} n^{\alpha}} + \frac{(K_2 + x^2 + v^2)^6}{v^{23}n^{\alpha}} \right) 
  \leq  \frac{\widetilde{K}_0(K_2 + x^2+ v^2)^{9}}{ v^{29} n^{\alpha}}, ~~ v \leq K_{\mathrm{im}}, \numberthis \label{Eq_Boud_norm_diff_R_Theta}
\end{align*}
where $\BD_{\delta} = \diag(\delta_j; 1 \leq j \leq n)$ and $\BD_{\kappa} = \diag(\kappa_j; 1 \leq j \leq n)$. Then, \eqref{Eq_Part_III} follows by $|\Bu^H(\BR - \BTheta) \Bu| \leq \norm{\Bu}^2 \norm{\BR - \BTheta}$. Gathering the results in \eqref{Eq_Part_I}, \eqref{Eq_Part_II}, and \eqref{Eq_Part_III}, Lemma \ref{Lemm_bilinear} is proved. \qed
\par
We remark that in Lemma \ref{Lemm_bilinear}, we require $z$ to be close to the real axis such that $ \Im z \leq K_{\mathrm{im}} $. However, the convergence in Lemma \ref{Lemm_bilinear} still holds with a slightly different polynomial $\mathcal{U}(z)$ when $\Im z > K_{\mathrm{im}}$. Furthermore, the behavior of the resolvent near the real axis is more essential for investigating the local behavior of the ESD \cite{erdHos2017dynamical}. We will also use Lemma \ref{Lemm_bilinear} to prove the no-eigenvalue property. 
\par
Given $z \in \mathbb{C}^+$ and choosing $t$ to be large enough, the RHS of \eqref{Eq_bilinear_U_t} is summable. By the Borel-Cantelli lemma, we have $\Bu^H(\BQ - \BTheta) \Bu$  converges to 0 almost surely. The convergence proof for the trace form is similar, and we omit it for simplicity. Therefore, we have completed the proof of Theorem \ref{Thm_conver_ESD}.

