\section{Useful Results for the Proof of Lemma \ref{Lemm_bilinear}}
\label{App_Useful_Estimations}
In this section, we first provide some useful transformations and equations regarding the resolvent, and then give the estimation for certain terms that will be used to prove Lemma \ref{Lemm_bilinear}.
\subsection{Useful Identities}
The following identities can be proved using the Woodbury matrix identity
\begin{align*}
    & \widetilde{q}_j(z) = \frac{1}{-z(1 + \Bxi_j^H \BQ(z) \Bxi_j)} = [\widetilde{\BQ}(z)]_{j, j}, ~~ \BQ(z) = \BQ_j(z) +z \widetilde{q}_j(z)\BQ(z)_j \Bxi_j\Bxi_j^H \BQ_j(z), \\
    &\BQ_j(z) = \BQ(z) + \frac{\BQ(z)\Bxi_j\Bxi_j^H\BQ(z)}{1 - \Bxi_j^H\BQ(z)\Bxi_j}, ~~ \BQ(z)\Bxi_j = -z\widetilde{q}_j(z)\BQ_j(z)\Bxi_j, ~~~ 1 + \Bxi_j^H\BQ_j(z)\Bxi_j = \frac{1}{1 - \Bxi_j^H\BQ(z)\Bxi_j}. \numberthis \label{Eq_Wood_resolvent_Id}
\end{align*}
\subsection{Useful Bounds}
\begin{lemma}
\label{Lemm_Bound_on_qterms}
    For $z = x + \jmath v \in \mathbb{C}^+$, there exists constant $K_0$ (independent of $n$) such that the following holds
    \begin{align}
        & \max_{j, l \leq n} \left\{ |\kappa_j|, |\widetilde{\kappa}_j|, |\delta_j|, |\widetilde{\delta}_j|, |[\widetilde{\BTheta}]_{j, l}|, |[\widetilde{\BR}]_{j, l}| \right\} \leq \frac{K_0}{v}, \label{Eq_Upper_bounds_terms_1}\\
        &\max_{j, l \leq n} \left\{ \frac{1}{n} \Tr \BOmega_j \BTheta \BOmega_l \BTheta^H, \frac{1}{n} \Tr \BOmega_j \BR \BOmega_l \BR^H,\frac{1}{n} \abs{\Tr \BOmega_j \BR \BOmega_l \BTheta^H} \right\} \leq \frac{K_0^2}{v^2}, \label{Eq_Upper_bounds_terms_1_5}\\
        &\max_{j \leq n} \left\{ |\Im(z \kappa_j)|, |\Im(z \widetilde{\kappa}_j)|, |\Im(z \delta_j)|, |\Im(z \widetilde{\delta}_j)| \right\}  \leq \frac{K_0}{v},  \label{Eq_Upper_bounds_terms_2}\\
        &\max_{j \leq n} |z\widetilde{q}_j| \leq \max\left\{K_0 \norm{\BSigma}^2 / v, 2\right\}, ~~ \max_{j \leq n} \left\{ |\eta_j|,\frac{1}{\abs{1 + \kappa_j}}, \frac{1}{\abs{1 + \delta_j}}, \frac{1}{\abs{1 + \E \alpha_{j, j}}} \right\} \leq \max\left\{K_0 / v, 2\right\}. \label{Eq_Upper_bounds_terms_3}
        % &\frac{1}{\abs{1 + \kappa_j}}, \frac{1}{\abs{1 + \delta_j}}, \frac{1}{\abs{1 + \E \alpha_{j, j}}} \leq \max\left\{K_0 / v, 2\right\}. \label{Eq_Upper_bounds_tersm}
    \end{align}
    Moreover, there exist constants $K_1$ and $K_2$ (independent of $n$) such that
    \begin{align}
  &\min_{j \leq n} \left\{ |\Im \kappa_j|, |\Im \widetilde{\kappa}_j|, |\Im\frac{1}{n}\Tr\BOmega_j \BR|, |\Im[\widetilde{\BR}]_{j, j}|, |\Im \delta_j|, |\Im \widetilde{\delta}_j| \right\} \geq \frac{v K_1}{(K_2 + x^2 + v^2)}, \label{Eq_Lower_bounds_terms_1} \\
  &\min_{j \leq n} \left\{\frac{1}{n} \Tr \BOmega_j \BTheta \BTheta^H, \frac{1}{n} \Tr \BOmega_j \BR\BR^H \right\} \geq \frac{v^2 {{K}_1^2}}{(K_2 + x^2 + v^2)^2}. \label{Eq_Lower_bounds_terms_2} 
\end{align}
\end{lemma}
\textit{Proof:}  We will prove the upper bounds and the lower bounds separately.
\subsubsection{Proof of the Upper Bounds} 
The proof of the first inequality in \eqref{Eq_Upper_bounds_terms_1} follows from $\|\BQ\|, \|\widetilde{\BQ}\|, \|\BR\|, \|\BTheta\|,  \|\widetilde{\BR}\|, \|\widetilde{\BTheta}\| \leq 1 / v$, and the property that if $m$ is a Stieltjes transform, then $|m| \leq  \int \frac{\dd \mu}{|\lambda - z|} \leq \mu(\R) / v$. The second inequality \eqref{Eq_Upper_bounds_terms_1_5} follows from $\norm{\BTheta}, \norm{\BR} \leq 1 / v$.
\par
For simplicity, we will only prove the inequality for $\widetilde{\delta}_j$ and $\kappa_j$ in \eqref{Eq_Upper_bounds_terms_2}. The proof mainly relies on the following identity \cite[Lemma C1]{hachem2007deterministic}.
\begin{equation}
    \int_{\R^+} \lambda \mu(\dd \lambda) = \lim_{y \uparrow \infty} \Re\left\{ - \jmath y \left[\jmath y m(\jmath y) + \mu(\R^+) \right] \right\}. \label{Eq_int_lambda_dmu}
\end{equation}
By the properties of the matrix-valued Stieltjes transform \cite[Proposition 2.2]{hachem2007deterministic}, we have
\begin{equation}
    \BTheta(z) = \int_{\R^+} \frac{\Bmu(\dd \lambda)}{\lambda - z}, \label{Eq_representation_Theta}
\end{equation}
where $\Bmu = ([\Bmu]_{i, j})_{1 \leq i, j \leq p}$ is a matrix-valued (complex) measure such that $\Bmu(A)$ is Hermitian non-negative for any Borel set $A$ and  $\Bmu(\R^+) = \BI_p$. Thus, we have
\begin{equation}
    \lim_{y \uparrow \infty } -\jmath y \BTheta(\jmath y) = \BI_p, ~~ \lim_{y \uparrow \infty} - \jmath y \delta_j(\jmath y) = \frac{1}{n} \Tr \BOmega_j.
\end{equation}
By the resolvent identity, we can obtain 
\begin{equation}
    \widetilde{\delta}_j(z) = -\frac{1}{z(1 + \delta_j(z))} + \frac{\Ba_j^H \BTheta(z) \Ba_j}{z(1 + \delta_j(z))^2}. \label{Eq_Res_identity_wdeltaj}
\end{equation}
Hence, it holds that $\lim_{y \uparrow \infty} -\jmath y \widetilde{\delta}_j(\jmath y) = 1$, which implies $\widetilde{\mu}_j (\R^+) = 1$. Thus, by \eqref{Eq_int_lambda_dmu}, we have  
\begin{align*}
    \int_{\R^+} \lambda \widetilde{\mu}_j(\dd \lambda) &= \lim_{y \uparrow \infty} \Re\left\{ - \jmath y \left[\jmath y \widetilde{\delta}_j(\jmath y) + \widetilde{\mu}_j(\R^+) \right] \right\} = \lim_{y \uparrow \infty} \Re\left\{ \left[\frac{- \jmath y {\delta}_j(\jmath y)}{1 + \delta_j(\jmath y) } + \frac{\Ba_j^H (-\jmath y \BTheta(\jmath y)) \Ba_j}{[1 + \delta_j(\jmath y)]^2} \right] \right\} \\
    &= \frac{1}{n} \Tr \BOmega_j + \norm{\Ba_j}^2 < \infty, \numberthis \label{Eq_Bound_of_wmu_j}
\end{align*}
which implies 
\begin{equation}
    \Im(z \widetilde{\delta}_j) = \int_{\R^+} \frac{\lambda v\widetilde{\mu}_j(\dd \lambda)}{(x - \lambda)^2 + v^2} \leq \frac{\frac{1}{n} \Tr \BOmega_j + \norm{\Ba_j}^2}{v}.
\end{equation}
\par
Denote the eigen-decomposition of $\BS$ as $\BS = \sum_{j=1}^p \lambda_j \Bu_j^H\Bu_j$ and the underline measure of ${\kappa}_j$ as $\mu_{\kappa, j}$. Then, we can obtain 
\begin{align*}
    \kappa_j = \frac{1}{n} \Tr \BOmega_j \E \BQ = \sum_{j=1}^p \E 
 \frac{\Bu_j^H \BOmega_j \Bu_j}{n(\lambda_j - z)} = \E \int_{\R^+} \frac{F^{\kappa, j}(\dd \lambda)}{\lambda - z}, \numberthis
\end{align*}
where $F^{\kappa, j} = \frac{1}{n}\sum_j \Bu_j^H \BOmega_j \Bu_j \Ind\{\lambda \leq \lambda_j\}$. Hence, we have $\mu_{\kappa, j} = \E F^{\kappa, j}$ and 
\begin{align*}
    &\int_{\R^+}\lambda \mu_{\kappa, j}(\dd \lambda) = \frac{1}{n}\E \left( \sum_{j=1}^n \lambda_j\Bu_j^H \BOmega_j \Bu_j\right) = \frac{1}{n} \Tr \BOmega_j \E \BSigma \BSigma^H \\
    &= \frac{1}{n} \Tr \BOmega_j \left(\sum_{l=1}^n \frac{1}{n} \BOmega_l + \Ba_l\Ba_l^H \right) = \frac{1}{n^2} \sum_{l=1}^n \Tr (\BOmega_j \BOmega_l) + \frac{1}{n}\Tr \BOmega_j \BA\BA^H, \numberthis
\end{align*}
which also implies $\Im(z \kappa_j) \leq K_0 / v$.
\par
The proof for \eqref{Eq_Upper_bounds_terms_3} follows from the property in \cite[Lemma 2.3]{SILVERSTEIN1995strong} which states that for positive $x$ and Stieltjes transform $m(z)$ with underline measure $\mu$, it holds that $|m(z)| \leq \mu(\mathbb{R}) / v$ and $|1 + m(z)x|^{-1} \leq \max(4\mu(\mathbb{R})x /v, 2)$.
\subsubsection{Proof of the Lower Bounds} For \eqref{Eq_Lower_bounds_terms_1}, we only show the proof for the inequality of $\widetilde{\delta}_j$ as proofs for the other terms are quite similar.  Denote $\widetilde{\mu}_j = \widetilde{\mu}_j^n$. By the bound \eqref{Eq_Bound_of_wmu_j}, we know that  $\sup_{j, n} \int \lambda \widetilde{\mu}^n_j(\dd \lambda) < \infty$. This implies that for each $j$, the positive measure sequence  $\{\widetilde{\mu}_j^n\}_{n \geq j}$ is tight and thus there exists a constant $K_\mu$ (independent of $n$) such that $\widetilde{\mu}_j([0, K_\mu]) = \widetilde{\mu}_j^n([0, K_\mu]) \geq 1 / 2$ for each $n$. Then, we have
\begin{align*}
    \Im (\widetilde{\delta}_j(z)) = \int_{0}^{\infty} \frac{v \widetilde{\mu}_j(\dd \lambda)}{(x - \lambda)^2 + v^2} \geq \int_{0}^{K_\mu}\frac{v \widetilde{\mu}_j(\dd \lambda)}{(x - \lambda)^2 + v^2} \geq \frac{\widetilde{\mu}_j([0, K_\mu])v}{2(x^2 + K_\mu^2) + v^2} \geq \frac{v}{4(x^2 + K_\mu^2 + v^2)}, \numberthis
\end{align*}
which gives the lower bound for $|\Im \widetilde{\delta}_j|$. The lower bounds for $\frac{1}{n} \Tr \BOmega_j \BTheta\BTheta^H$ in \eqref{Eq_Lower_bounds_terms_2} follows  by the lower bound for $|\Im \delta_j|$ in \eqref{Eq_Lower_bounds_terms_1} and the Cauchy-Schwarz inequality
\begin{equation}
    |\Im(\delta_j)| \leq |\delta_j| = \abs{ \frac{1}{n}\Tr \BOmega_j^{1/2} \BOmega_j^{1/2}\BTheta  } \leq \sqrt{\left( \frac{1}{n}\Tr \BOmega_j \right) \left(  \frac{1}{n}\Tr\BOmega_j\BTheta \BTheta^H \right)}.
\end{equation}
The evaluation for $\frac{1}{n} \Tr \BOmega_j \BR\BR^H$ is similar. Therefore, we have completed the proof of Lemma \ref{Lemm_Bound_on_qterms}. \qed
\subsection{Useful Estimations}
\begin{lemma}
\label{Lemm_bound_Delta}
    For $t \geq 2$, we have 
    \begin{equation}
        \E\left[\abs{\Delta_j}^t | \widetilde{\mathscr{F}}_{j} \right] \lesssim_t \left\{\begin{aligned}
        &\frac{1}{n^{t/2} v^{t}} & \text{if } 2 \leq t \leq 2 + \varepsilon/2, \\
        &\frac{1}{v^t} \left(\frac{1}{n^{2\alpha t + 1}} + \frac{1}{n^{t/2}} \right) & \text{if } 2 + \varepsilon/2 < t \leq 4 + \varepsilon, \\
        &\frac{1}{v^t}\left(\frac{1}{n^{2\alpha t + 1}} + \frac{1}{n^{\alpha t + 2}} \right) & \text{if } t > 4 + \varepsilon,
    \end{aligned}\right. 
    \end{equation}
    where $\widetilde{\mathscr{F}}_{j}$ is a  $\sigma$-algebra independent of $\sigma(X_{ij}, 1 \leq i \leq d_j)$.
\end{lemma}
\textit{Proof:} By Lemma \ref{Lemm_trace} , $\norm{\BQ_j} \leq 1/v$, and inequality $(\sum_{i=1}^L a_i)^t \leq L^{t-1} \sum_{i=1}^L|a_i|^t$, we have 
\begin{align*}
\E\left[|\Delta_j|^t|\widetilde{\mathscr{F}}_{j}\right]  \leq 3^{t-1} \E\left[\abs{\By_j^H \BQ_j \By_j - \frac{1}{n} \Tr \BOmega_j \BQ_j}^t + \abs{\By_j^H \BQ_j \Ba_j}^t + \abs{\Ba_j^H \BQ_j \By_j}^t \Big|\widetilde{\mathscr{F}}_{j}\right]\lesssim_t\frac{R_t}{v^tn^t} + \frac{T_{t/2}}{n^{t/2}v^t}, \numberthis
\end{align*}
which yields the desired result. \qed
\begin{lemma}
\label{Lemm_Usedul_est}
For deterministic vector $\Bu \in \mathbb{C}^H$ with $\norm{\Bu} = 1$ and $z = x + \jmath v \in \mathbb{C}^+$ with $v$ small ($v \leq K_{\mathrm{im}}$), we have 
\begin{align}
&\E \left[ \sum_{j=1}^n \E_{j-1} \left( \Bu^H \BQ\Ba_j\Ba_j^H\BQ^H\Bu \right) \right]^t \lesssim_t \frac{1}{v^{2t}}, \label{Eq_useful_est_1}\\
&\E \left[ \sum_{j=1}^n \E_{j-1} \left( \Bu^H \BQ\Bxi_j\Bxi_j^H\BQ^H\Bu \right) \right]^t \lesssim_t  \frac{\log^{2t}(n)}{v^{2t}}, \label{Eq_useful_est_2}\\
&\sum_{j=1}^n \E (\Bu^H \BQ_j \Ba_j\Ba_j^H\BQ_j^H\Bu)^2 \lesssim \frac{\log^4(n)}{v^8},\label{Eq_useful_est_3}  \\
&\E \left[ \sum_{j=1}^n \E_{j-1}(\Bu^H\BQ_j\Ba_j\Ba_j^H\BQ^H_j\Bu) \right]^t \lesssim_t \frac{\log^{2t}(n)}{v^{4t}}. \label{Eq_useful_est_4}
\end{align}
\end{lemma}
\textit{Proof:} The proof of \eqref{Eq_useful_est_1} is similar to that of \cite[Lemma 3.5]{hachem2013bilinear} and omitted. Next we prove \eqref{Eq_useful_est_2}.
When $t = 1$, we have
\begin{equation}
     \E \sum_{j=1}^n \E_{j-1} \Bu^H\BQ\Bxi_{j}\Bxi_j^H\BQ^H\Bu  = \E \Bu^H\BQ\BSigma\BSigma^H\BQ^H\Bu \overset{(a)}{\leq} \frac{\E \norm{\BSigma}^2}{v^2} \overset{(b)}{\lesssim} \frac{\log^2(n)}{v^2},
\end{equation}
where step $(a)$ follows from $\norm{\BQ} \leq 1 / \Im z$ and step $(b)$ is due to Lemma \ref{Lemm_P_bound_Sn}. Denote the set $A = \{ \norm{\BSigma} \leq \log(n) \}$. If $t \geq 2$, we have 
\begin{align*}
    & \E \left[ \sum_{j=1}^n \E_{j-1} \Bu^H\BQ\Bxi_j\Bxi_j^H\BQ^H\Bu \right]^t (\Ind_A + \Ind_{A^c}) = \sum_{j_{1}, \ldots j_t} \E \left[ \prod_{i=1}^t\E_{j_i-1} \Bu^H\BQ\Bxi_{j_i}\Bxi_{j_i}^H\BQ^H\Bu \right](\Ind_A + \Ind_{A^c}) \\
    &\overset{(a)}{\leq} t! \sum_{j_{1}\leq \ldots \leq j_t} \E \left[ \left(\prod_{i=1}^{t-1}\E_{j_i-1}  \Bu^H\BQ\Bxi_{j_i}\Bxi_{j_i}^H\BQ^H\Bu \right) \left( \Bu^H\BQ\Bxi_{j_t}\Bxi_{j_t}^H\BQ^H\Bu \right)\right]\Ind_A + \PP(A^c)n^{3t}v^{-2t} \\
    &\leq t! \sum_{j_{1}\leq \ldots \leq j_{t-1}} \E \left[ \left(\prod_{i=1}^{t-1}\E_{j_i-1} \Bu^H\BQ\Bxi_{j_i}\Bxi_{j_i}^H\BQ^H\Bu \right) \sum_{j_t = j_{t-1}}^n \left( \Bu^H\BQ\Bxi_{j_t}\Bxi_{j_t}^H\BQ^H\Bu \right)\right] + \PP(A^c)n^{3t}v^{-2t} \\
    &\overset{(b)}{\leq} t! \E \left[ \sum_{j=1}^n \Bu^H\BQ\Bxi_{j}\Bxi_{j}^H\BQ^H\Bu \right]^{t-1}\frac{\log^2(n)}{v^2} + o(K_ln^{-l}), ~~ \forall l. \numberthis
\end{align*}
where step $(a)$ follows from $\norm{\Bxi_j} \leq \sqrt{d_j} + \norm{\BA} \leq n$ (for large $n$) and $\Bu^H\BQ \Bxi_j \Bxi_j^H\BQ^H \Bu \leq v^{-2}n^2$, and step $(b)$ is due to the inequality
\begin{equation}
    \sum_{j_t = j_{t-1}}^n \left( \Bu^H\BQ\Bxi_{j_t}\Bxi_{j_t}^H\BQ^H\Bu \right) \leq \Bu^H\BQ\BSigma\BSigma^H\BQ^H\Bu \leq v^{-2} \norm{\BSigma}^2
\end{equation}
and Lemma \ref{Lemm_P_bound_Sn}. As a result, \eqref{Eq_useful_est_2} is proved.
\par
To prove \eqref{Eq_useful_est_3}, we write $\Bu^H\BQ_j\Ba_j\Ba_j^H\BQ_j^H\Bu$ as 
\begin{align*}
    \Bu^H\BQ_j\Ba_j\Ba_j^H\BQ_j^H\Bu &= \Bu^H(\BQ_j - \BQ)\Ba_j\Ba_j^H\BQ^H\Bu + \Bu^H\BQ\Ba_j\Ba_j^H(\BQ_j - \BQ)^H\Bu + \Bu^H(\BQ - \BQ_j)\Ba_j\Ba_j^H(\BQ - \BQ_j)^H\Bu \\
    &+ \Bu^H\BQ\Ba_j\Ba_j^H\BQ^H\Bu = X_{1j} + X_{2j} + X_{3j} + X_{4j}. \numberthis \label{Eq_Decomp_of_uQaaQu}
\end{align*}
By $\E |X_{1j}|^2 \leq \frac{1}{2}(\E X_{3j}^2 + \E X_{4j}^2 )$ and $\E |X_{2j}|^2 \leq \frac{1}{2}(\E X_{3j}^2 + \E X_{4j}^2 )$, we have 
\begin{equation}
    \sum_{j=1}^n \E (\Bu^H \BQ_j \Ba_j\Ba_j^H\BQ_j^H\Bu)^2 \leq 8 \sum_{j=1}^n \left(\E X_{3j}^2 + \E X_{4j}^2\right).
\end{equation}
By $\Bu^H\BQ\Ba_j\Ba_j^H\BQ^H\Bu \leq \sum_i \Bu^H\BQ\Ba_i\Ba_i^H\BQ^H\Bu = \Bu^H\BQ\BA\BA^H\BQ^H\Bu$, we can obtain $\sum_j \E X_{4j}^2 \leq \E(\Bu^H\BQ\BA\BA^H\BQ^H\Bu)^2 \leq \norm{\BA}^4 / v^4$. According to \eqref{Eq_Wood_resolvent_Id}, we have 
\begin{align*}
    \sum_{j=1}^n \E X_{3j}^2 &= \sum_{j=1}^n \E \left( \Bu^H\BQ\Bxi_j\Bxi_j^H\BQ\Ba_j\Ba_j^H \BQ^H \Bxi_j \Bxi_j^H \BQ^H\Bu\abs{\frac{1 + \Bxi_j^H\BQ_j\Bxi_j}{1 - \Bxi_j^H \BQ \Bxi_j}} \right)^2 \\
    &= \sum_{j=1}^n\E \abs{\frac{\Bxi_j^H\BQ\Ba_j\Ba_j^H \BQ^H \Bxi_j}{1 - \Bxi_j^H \BQ \Bxi_j} }^2  \abs{\Bu^H\BQ\Bxi_j \Bxi_j^H \BQ^H\Bu}^2\abs{1 + \Delta_j + \frac{1}{n} \Tr \BOmega_j\BQ_j + \Ba_j \BQ_j \Ba_j}^2. \numberthis
\end{align*}
Write the eigen-decomposition of $\BQ$ as $\BQ = \BU \diag{(\lambda_i - z; 1 \leq i \leq p) \BU^H}$, and denote $\overline{\Bxi}_j = \BU^H \Bxi_j = [\overline{\xi}^j_1, \ldots \overline{\xi}^j_p]^T$. Then, we have 
\begin{align*}
\label{Eq_Resol_Im_Bound}
\abs{\frac{\Bxi_j^H\BQ\Ba_j\Ba_j^H \BQ^H \Bxi_j}{1 - \Bxi_j^H \BQ \Bxi_j}} \leq \norm{\Ba_j}^2\abs{\frac{\Bxi_j^H\BQ \BQ^H \Bxi_j}{\Im (1 - \Bxi_j^H \BQ \Bxi_j)}} \leq \norm{\Ba_j}^2\abs{\frac{\sum_i \frac{|\overline{\xi}^j_i|^2}{|\lambda_i - z|^2}}{\Im\left(\sum_i \frac{|\overline{\xi}^j_i|^2}{\lambda_i - z}\right)}} \leq \frac{\norm{\Ba_j}^2}{v}. \numberthis
\end{align*}
Therefore, by $\abs{\frac{1}{n} \Tr \BOmega_j \BQ_j} \leq \frac{p}{n}\norm{\BQ_j} \norm{\BOmega_j}\lesssim v^{-1}$, $\abs{\Ba_j^H \BQ_j \Ba_j} \leq \norm{\Ba_j}^2 \norm{\BQ_j} \lesssim v^{-1}$ and Lemma \ref{Lemm_bound_Delta}, we can obtain  
\begin{align*}
    \sum_{j=1}^n \E X_{3j}^2 &\lesssim v^{-2} \sum_{j=1}^n\E  \abs{\Bu^H\BQ\Bxi_j \Bxi_j^H \BQ^H\Bu}^2(|\Delta_j|^2 + 1 + v^{-1} +  v^{-2}) \\
    &\leq v^{-2}(1 + v^{-1} +  v^{-2})\E(\Bu^H\BQ\BSigma\BSigma^H\BQ^H\Bu)^2 + \frac{1}{v^6}\sum_{j=1}^n \E \norm{\BSigma}^4 |\Delta_j|^2 \lesssim \frac{\log^4(n)}{v^8}. \numberthis
\end{align*}
Here, we note that $v$ is small enough by assumption, which implies $v^{-b} \leq v^{-a}$ for $0 < a \leq b$. 
\par
In the following, we prove the last inequality in \eqref{Eq_useful_est_4}. With the decomposition in \eqref{Eq_Decomp_of_uQaaQu}, we have
\begin{align*}
    \E \left[ \sum_{j=1}^n \E_{j-1}(\Bu^H\BQ_j\Ba_j\Ba_j^H\BQ^H_j\Bu) \right]^t \lesssim_t \sum_{i=1}^4 \E \abs{ \sum_{j=1}^n \E_{j-1}X_{ij} }^t. \numberthis
\end{align*}
By \eqref{Eq_useful_est_1}, we can obtain $\E | \sum_{j} \E_{j-1}X_{4j} |^t \lesssim_t v^{-2t}$. Similar to the derivation of \eqref{Eq_useful_est_3}, we have
\begin{align}
    \E_{j-1} X_{3j} \lesssim (v^{-1} + v^{-2}) \E_{j-1} \abs{\Bu^H\BQ\Bxi_j\Bxi_j^H\BQ^H\Bu} + v^{-1} \E_{j-1} |\Delta_j|\abs{\Bu^H\BQ\Bxi_j\Bxi_j^H\BQ^H\Bu}.
\end{align}
According to the Cauchy-Schwarz inequality $|\E[ab|\mathscr{F}]| \leq \E^{1/2}[|a|^2|\mathscr{F}]\E^{1/2}[|b|^2|\mathscr{F}]$ and \eqref{Eq_useful_est_2}, we have 
\begin{align*}
    &\E\abs{\sum_{j=1}^n  \E_{j-1} |\Delta_j|\abs{\Bu^H\BQ\Bxi_j\Bxi_j^H\BQ^H\Bu}}^t \leq \E\left( \sum_{j=1}^n  \E_{j-1} |\Delta_j|^2 \right)^{t/2} \E\left( \sum_{j=1}^n  \E_{j-1} |\Bu^H\BQ\Bxi_j\Bxi_j^H\BQ^H\Bu|^2 \right)^{t/2} \\
    &\lesssim_t v^{-t} \cdot v^{-t} \E\left( \sum_{j=1}^n  \E_{j-1} \norm{\BSigma}^2(\Bu^H\BQ\Bxi_j\Bxi_j^H\BQ^H\Bu) \right)^{t/2} \lesssim_t  \frac{\log^{2t}(n)}{v^{3t}}. \numberthis
\end{align*}
Hence, we get $\E | \sum_{j} \E_{j-1}X_{3j}|^t \lesssim_t \log^{2t}(n) v^{-4t}$. 
Using Cauchy-Schwarz again, we can obtain $|\E_{j-1}X_{ij}| \leq \sqrt{\E_{j-1}X_{3j}\E_{j-1}X_{4j}} $ for $i=1,2$, and
\begin{align}
    \E \abs{\sum_{j=1}^n \E_{j-1}X_{ij}}^t \leq  \E \left( \sum_{j=1}^n \E_{j-1}X_{3j} \right)^{t/2}\E \left(\sum_{j=1}^n \E_{j-1}X_{4j}\right)^{t/2}\lesssim_t \frac{\log^t(n)}{v^{3t}}, ~~ i = 1, 2.
\end{align}
Therefore, \eqref{Eq_useful_est_4} is proved, which completes the proof of Lemma \ref{Lemm_Usedul_est}. \qed
\section{Proof of Proposition \ref{Prop_same_support}}
\label{App_Proof_Prop_same_support}
Fix $x_0 \in \R_*$, and since $\mathsf{Supp}(F^n) \subset \mathbb{R}^+$, we can assume $x_0 > 0$ without loss of generality. We then define $\Bdelta(z) = [\delta_1(z), \ldots, \delta_n(z)]^T$ and $\widetilde{\Bdelta}(z) = [\delta_1(z), \ldots, \delta_n(z)]^T $, and denote three limits $\Bdelta_0 = \lim_{z \in \mathbb{C}^+ \to x_0} \Bdelta(z)$, $\widetilde{\Bdelta}_0 = \lim_{z \in \mathbb{C}^+ \to x_0} \widetilde{\Bdelta}(z)$, and $m_{ n, 0} = \lim_{z \in \mathbb{C}^+ \to x_0} m_n(z)$. 
According to \cite[Theorem B.10]{bai2010spectral}, it is enough to show the following holds
\begin{equation}
    \Im(m_{ n, 0}) = 0 \Rightarrow \Im[\Bdelta_0] = \Bzero_{n} \Rightarrow  \Im[\widetilde{\Bdelta}_0] = \Bzero_{n}. \label{Eq_Support_arrows}
\end{equation} 
To this end, we choose sequence $\{z_k\} \subset \mathbb{C}^+ \to x_0$. By the integration representation \eqref{Eq_representation_Theta}, we have 
\begin{equation}
    \Im(\BTheta(z_k)) = [\BTheta(z_k) - \BTheta^H(z_k)] / 2\jmath = \int_{\R^+} \frac{v\Bmu(\dd\lambda)}{|\lambda - z|^2}  > \mathbf{0}_{p \times p}. \label{Eq_Tm_Theta_geq_0}
\end{equation}
Then, by the inequality $ |\Tr \BC\BD| \leq \norm{\BC} \Tr \BD$ for Hermitian non-negative $\BD$, we can obtain 
\begin{equation}
    0 \leq \Im (\delta_j(z_k)) = \frac{1}{2\jmath n} \Tr \BOmega_j (\BTheta(z_k) - \BTheta^H(z_k)) \leq \frac{\norm{\BOmega_j}}{n } \Tr\Im (\BTheta(z_k)) \leq \frac{p \norm{\BOmega_j}\Im(m(z_k))}{n }.
\end{equation}
Letting $z_k \to x_0$ in the above inequality, we have $\Im \Bdelta_0 = \Bzero_n$. 
\par
To prove the second arrow in \eqref{Eq_Support_arrows}, we will use \eqref{Eq_Im_delta_Im_wdelta} and prove by contradiction. Assume that there exists an index $m$ such that $\Im[\widetilde{\Bdelta}_0]_m > 0$. By \eqref{Eq_Im_delta_Im_wdelta}, we can write the equation regarding $\Im\delta_m$ as
\begin{equation}
    \Im(\delta_m) = v_k[\Bv_{\delta}]_m + |z_k|^2 [\BPsi_{\delta} \Im(\Bdelta)]_m + [\BGamma_\delta \Im(z_k\widetilde{\Bdelta})]_m,
\end{equation}
which implies
$
    \Im(\delta_m(z_k)) \geq [\BGamma_{\delta}]_{m, m} \Im (z_k\widetilde{\delta}_m(z_k))
$. Letting $z_k \to x_0$, we have 
$
    [\BGamma_{\delta}]_{m, m} \to 0.
$
By the Cauchy-Schwarz inequality, the following holds 
\begin{equation}
    [\BGamma_{\delta}]_{m, m} = \frac{1}{n}\Tr \BOmega_m^{1/2} \BTheta(z_k) \BOmega_m \BTheta^H(z_k)\BOmega_m^{1/2} \geq \frac{1}{np}\abs{\Tr \BOmega_m \BTheta(z_k)} ^2 \geq \frac{n|\delta_m(z_k)|^2}{p}.
\end{equation}
Hence, we have $\delta_m(z_k) \to 0$, as $z_k \to x_0$. By resolvent identity \eqref{Eq_Res_identity_wdeltaj}, we can obtain
\begin{equation}
    \Ba_m^H \BTheta(z_k) \Ba_m = z_k(1 + \delta_m(z_k))^2 \widetilde{\delta}_m(z_k) + (1 + \delta_m(z_k)).
\end{equation}
By taking the imaginary part of the above identity, we have
\begin{equation}
    \lim_{k \to \infty} \Im(\Ba_m^H \BTheta(z_k) \Ba_m ) = \lim_{k \to \infty} \Ba_m^H \Im(\BTheta(z_k)) \Ba_m = x_0 \Im([\widetilde{\Bdelta}_0]_m) + 1 > 0.
\end{equation}
However, this cannot happen. In particular, because $\Im[\BTheta(z_k)] > \mathbf{0}_{p \times p}$ according to \eqref{Eq_Tm_Theta_geq_0}, we have  $\Im(m_n(z_k)) = \Im(\Tr\BTheta(z_k)) / p \to 0$, which yields $\Im[\BTheta(z_k)] \to \mathbf{0}_{p \times p}$. Therefore, we have completed the proof. \qed


