\section{Proof of \eqref{Eq_sup_diff_resolvent}}
\label{App_Proof_Thm_noeigen}
 In this section, we use the same notations as defined in Appendix \ref{App_Converge_resolvent}. Since $[a, b]$ is a subset of a open interval outside the limiting support, we assume that there exists $\underline{\epsilon} > 0$ such that $[a - 2\underline{\epsilon}, b + 2\underline{\epsilon}]$ is outside the limiting support, and denote $a' = a - \underline{\epsilon}$ and $b' = b + \underline{\epsilon}$.
\subsection{A Rate on $F^{\BS, n}([a, b])$}
\label{Sec_A_rate_one_F}
 In this section, we provide a preliminary order for $F^{\BS, n}([a, b]) = (\text{number of eigenvalues of $\BS$ appears in $[a, b]$}) / p$. To this end, the following proposition is useful. 
\begin{proposition}
\label{Prop_bilinear_of_resolvent_uniform_x}
Assume $r \geq 1$ and $z = x + jv$ with $v = n^{-{\alpha}/(48 + 20 r)}$. Let $\BT \in \mathbb{C}^{p \times p}$ be a Hermitian non-negative matrix with bound spectral norm and $\Bu$ be a deterministic vector with bounded Euclidean norm. For any $l > 0$, the following holds.
\begin{align}
\max_{0 \leq j \leq n} \E_{j} \left\{ v^{-rl}p^{-l}\sup_{x \in \mathbb{R}}\abs{\Tr \BT [\BQ(z) -\BTheta(z)] }^l\right\} \xrightarrow{a.s.} 0, \\
\max_{0 \leq j \leq n} \E_{j} \left\{ v^{-{rl}}\sup_{x \in \mathbb{R}}{\abs{\Bu^H[\BQ(z) - \BTheta(z)]\Bu}^l}\right\} \xrightarrow{a.s.} 0. \label{Eq_Bilinear_martingale_conv}
\end{align}
\end{proposition}
\textit{Proof: } We first evaluate $\sup_{x \in S_n}{\left\{ v^{-{rl}}\sup_{x \in \mathbb{R}}{\abs{\Bu^H[\BQ(z) - \BTheta(z)]\Bu}^l}\right\}}$, where $S_n \subset \mathbb{R}$ contains at most $n$ elements. Denote  $m_{\Bu,\BS, n}(z) = \Bu^H\BQ(z)\Bu$ and $m_{\Bu, n}(z) =  \Bu^H\BTheta(z)\Bu$. We have the following decomposition
\begin{align*}
  \sup_{x\in S_n} v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)} &= \sup_{x\in S_n} v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)}\Ind\{|x| \leq {\varsigma}^rv^{-(r+1)}, \norm{\BSigma} \leq \log(n)\} \\
  &+ \sup_{x\in S_n} v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)}\Ind{\{|x| > {\varsigma^r}v^{-(r+1)}, \norm{\BSigma} \leq \log(n)\}}\\
  &+ \sup_{x\in S_n} v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)} \Ind{\{\norm{\BSigma} > \log(n)\}} := X_1 + X_2 + X_3, \numberthis
\end{align*}
where $\varsigma = n^{\alpha / (864 + 360r)}$. By inequalities $|m_{\Bu, \BS, n}(z)|, |m_{\Bu, n}(z)| \leq \norm{\Bu}^2 / v$, we have  $X_3 \leq {2 \norm{\Bu}^2}v^{-{(r+1)}}\Ind\{\norm{\BSigma} > \log(n)\}$. Write the eigen-decomposition for $\BS$ as $\BS = \BU \diag(\lambda_i; 1\leq i \leq p )\BU^H$.  When $|x| > \varsigma^r v^{-(r+1)}$ and $\norm{\BSigma} \leq \log(n)$,  we can obtain 
\begin{equation}
    \frac{1}{|\lambda_i - z|} \leq \frac{1}{|\log(n) - \varsigma^r v^{-(r+1)}|} \leq \frac{2v^{r+1}}{\varsigma^r}
\end{equation}
for sufficiently large $n$. Thus, it holds that 
\begin{equation}
|m_{\Bu, \BS, n}(z)| \leq \abs{\Bu^H \BU \diag \left( 1/|\lambda_i - z| ; 1 \leq i\leq p \right)\BU^H\Bu}  \leq \frac{2 \norm{\Bu}^2 v^{r+1}}{\varsigma^r}.
\end{equation} 
Denote the underline measure of $m_{\Bu, n}$ as $F^{\Bu, n}$. Using the same method as in the proof of Lemma \ref{Lemm_Bound_on_qterms}, it can be shown that $\int_{\mathbb{R}^+} \lambda F^{\Bu, n}(\dd \lambda) < \infty$. Then, we have 
\begin{equation}
    |m_{\Bu, n}(z)| \leq \int_{\R^+} {v^{-1}}{ \Ind_{\{\lambda \geq \varsigma^r / (2v^{r+1}) \}}}F^{\Bu, n}(\dd \lambda) + \int_{\R^+} \frac{\Ind_{\{\lambda < \varsigma^r / (2v^{r+1}) \}}F^{\Bu, n}(\dd \lambda)}{|\lambda - \varsigma^rv^{-(r+1)}|} \leq \frac{2\int_{\mathbb{R}^+} \lambda F^{\Bu, n}(\dd \lambda) v^r + 2\norm{\Bu}^2 v^{r+1}}{\varsigma^r}.
\end{equation}
As a result, we have $X_2 \leq {K_{\Bu, 2}}/ \varsigma^r$ for some constant $K_{\Bu, 2}$. Next, we evaluate $X_1$. When $|x| \leq \varsigma^r v^{-(r+1)}$, the following holds according to \eqref{Eq_Part_II} and \eqref{Eq_Part_III}
\begin{align*}
  X_1 &\leq  v^{-r}\sup_{x \in S_n} \abs{\Bu^H[\BQ - \E\BQ]\Bu + \Bu^H[\E\BQ - \BR]\Bu + \Bu^H [\BR - \BTheta]\Bu } \\
  & \leq  v^{-r}\sup_{x \in S_n}\abs{\Bu^H[\BQ - \E\BQ]\Bu} + \frac{K \norm{\Bu}^2}{v^rn^{\alpha}}\left[ \frac{1}{v^7} + \frac{(K_2 + x^2 + v^2)^{9}}{v^{29}}\right] \\
  & \leq  v^{-r}\sup_{x \in S_n}\abs{\Bu^H[\BQ - \E\BQ]\Bu} + \frac{K \norm{\Bu}^2 \varsigma^{18r}}{n^{\alpha}v^{47 + 19r}} \leq  v^{-r}\sup_{x \in S_n}\abs{\Bu^H[\BQ - \E\BQ]\Bu}+ \frac{K \norm{\Bu}^2}{n^{{\alpha/(48 + 20r)}}}, \numberthis
\end{align*}
where $K$ is a constant independent of $n$ and $K_2$ is defined in Lemma \ref{Lemm_bilinear}. We note that, unlike Lemma \ref{Lemm_bilinear}, the imaginary part of $z$ approaches 0 as  $n \to \infty$. Fortunately, the bound in Lemma \ref{Lemm_bilinear} still holds. As a result, for any $\epsilon > 0$ and sufficiently large $n$,  the following holds by Lemma \ref{Lemm_P_bound_Sn} and \eqref{Eq_Part_I}
\begin{equation}
  \begin{split}
  &\PP \left( \sup_{x \in S_n}v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)} \geq \epsilon \right) \leq \sum_{x \in S_n} \PP\left(v^{-r}\abs{\Bu^H[\BQ - \E\BQ]\Bu} \geq \epsilon' \right) \\
  &+ \PP\left(2{\norm{\Bu}^2v^{-(r+1)}\Ind\{\norm{\BSigma} > \log(n)\}} \geq \epsilon' \right) \leq \sum_{x \in S_n} \frac{\E\abs{\Bu^H[\BQ - \E\BQ]\Bu}^{2d}}{v^{2rd}(\epsilon')^{2d}} + o(K_{d'}n^{-d'})  \leq \frac{K_d\log^{6d}(n)n^{0.5}}{\epsilon^{2d}v^{(12 + 2r)d }n^{2\alpha d}},
\end{split}
\end{equation}
where $\epsilon' = (\epsilon - {K\norm{\Bu}^2}n^{-\alpha /(48 + 20r)} - K_{\Bu, 2} n^{-r\alpha / (864 + 360r)} ) \big/ 2 > \epsilon / 4 $, $d \geq 2 + \varepsilon / 2$, and $d' > 0$ are arbitrary.
Hence, for any positive $\epsilon$ and $l$, we have
\begin{equation}
\label{Eq_Prob_bound_on_m}
  \PP \left( \max_{x \in S_n}v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)} \geq \epsilon \right) \leq K_{d} \epsilon^{-d} n^{-l},
\end{equation}
for any large $d$. Next we assume that the $n$ elements of $S_n$ are equally spaced in the interval $[-\sqrt{n}, \sqrt{n}]$. Since $|x_1 - x_2| \leq 2n^{-1/2}$, it holds 
\begin{equation}
\label{Eq_max_m_1}
  \max \left\{\abs{m_{\Bu, \BS, n}(x_1 + \jmath v) - m_{\Bu, \BS, n}(x_2 + \jmath v)}, \abs{m_{\Bu, n}(x_1 + \jmath v) - m_{\Bu, n}(x_2 + \jmath v)} \right\} \leq \frac{2 \norm{\Bu}^2}{n^{1/2}v^2}, 
\end{equation}
and when $|x| > \sqrt{n}$, for $n$ large, we have 
\begin{equation}
\label{Eq_max_m_2}
  |m_{\Bu, \BS, n}(x + \jmath v)| \leq \frac{2 \norm{\Bu}^2}{n^{1/2}} + \frac{\norm{\Bu}^2 \Ind\{\norm{\BSigma} > \log(n)\}}{v} , ~~ |m_{\Bu, n}(x + \jmath v)| \leq \frac{2 \norm{\Bu}^2}{n^{1/2}} + \frac{2 \int \lambda F^{\Bu, n}(\dd \lambda )}{n^{1/2}v}.
\end{equation}
Combining \eqref{Eq_Prob_bound_on_m}, \eqref{Eq_max_m_1}, and \eqref{Eq_max_m_2}, we can obtain 
\begin{equation}
\label{Eq_Prob_bound_on_all_x}
\PP \left( \max_{x \in \mathbb{R}}v^{-r}\abs{m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)} \geq \epsilon \right) \leq K_{d} \epsilon^{-d} n^{-l}.
\end{equation}
Assume $l'$ and $l > 0$. We know $\E_j v^{-{rl'}} \sup_{x\in \mathbb{R}} |m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)|^{l'}$, $j = 0, 1, \ldots, n$, forms a discrete martingale. By letting $h = \frac{ld}{\underline{l}l'}$ with $\underline{l} > l$, we have 
\begin{equation}
  \PP\left( \max_{j \leq n} \E_j v^{-{rl'}} \sup_{x\in \mathbb{R}} |m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)|^{l'} \geq \epsilon \right) \overset{(a)}{\leq} \epsilon^{-h} \E\left[v^{-rhl'}\sup_{x\in \mathbb{R}} |m_{\Bu, \BS, n}(z) - m_{\Bu, n}(z)|^{l'h} \right] \overset{(b)}{\leq}   \frac{\epsilon^{-h}  K_d^{\frac{l}{\underline{l}}}\underline{l}}{\underline{l} - l}n^{-l},
\end{equation} 
where step $(a)$ follows from Jensen's inequality and the Maximal inequality. Step $(b)$ is due to \eqref{Eq_Prob_bound_on_all_x}. Therefore, we have completed the proof of \eqref{Eq_Bilinear_martingale_conv}. The proof for the second equation (the trace form) is quite similar and omitted here. \qed
\par
By the properties of the Stieltjes transform, the quadratic forms $\Bu^H \BQ(z)\Bu$ and $\Bu^H\BTheta(z)\Bu$ are also Stieltjes transforms and their underline positive measures are denoted by $F^{\Bu, \BS, n}$ and $F^{\Bu, n}$, respectively. In particular, denoting $\BS = \BU \diag(\lambda_i; 1 \leq i\leq p)\BU^H$ and $\BU^H\Bu = \overline{\Bu}$, the distribution $F^{\Bu, \BS, n}(x)$ is given by
\begin{equation}
  F^{\Bu, \BS, n}(x) = \sum_{j=1}^n \abs{[\overline{\Bu}]_j}^2\Ind_{\{\lambda_j \leq x\}}.
\end{equation}
Next, we use Proposition \ref{Prop_bilinear_of_resolvent_uniform_x} to give a preliminary estimate on $F^{\Bu, \BS, n}([a, b])$ and $F^{\BS, n}([a, b])$ (defined in \eqref{EQ_ESD_F_S_n}), respectively. These estimates are important for proving the no-eigenvalue property.
%%%%%%%%%%%%%%%%%%%%
\par
We evaluate $F^{\Bu, \BS, n}([a, b])$ first and keep the notations defined in the Proof of Proposition \ref{Prop_bilinear_of_resolvent_uniform_x}.
Denote $\Im m_{\Bu, \BS, n}(z) = \Im m_{\Bu, \BS, n}^{\text{out}}(z) + \Im m_{\Bu, \BS, n}^{\text{in}}(z)$, where 
\begin{align}
    \Im m_{\Bu, \BS, n}^{\text{in}}(z) = \int_{[a', b']^c} \frac{v F^{\Bu, \BS, n}(\dd \lambda)}{(\lambda - x)^2 + v^2} = \sum_{\lambda_j \in [a', b']^c} \frac{v |[\overline{\Bu}]_j|^2}{(x - \lambda_j)^2 + v^2}.
\end{align}
 Similar to $\Im m_{\Bu, \BS, n}$, denote $\Im m_{\Bu, n}(z) = \Im m_{\Bu, n}^{\text{out}}(z) + \Im m^{\text{in}}_{\Bu, n}(z) $, 
where 
\begin{equation}
    \Im m^{\text{in}}_{\Bu, n}(z) = \int_{[a', b']^c} \frac{v F^{\Bu, n}(\dd \lambda)}{(\lambda - x)^2 + v^2}.
\end{equation}
We evaluate $v^{-1}|\Im m^{\text{in}}_{\Bu, n}(z) - \Im m^{\text{in}}_{\Bu,\BS, n}(z)|$ to control the order of $F^{\Bu,\BS, n}([a, b])$. To this end, we first show that $F^{\Bu, n}([a', b']) = 0$. In fact, according to the integration representation $\BTheta(z) = \int_{\R^+} \frac{\Bmu(\dd \lambda)}{\lambda - z}$ in \eqref{Eq_representation_Theta}, we have the measure $F^n =  \Tr \Bmu / p$. Hence the interval $[a', b']$ is outside the support of the $[\Bmu]_{j, j}$ for each $j$, which implies $\Bmu([a', b']) = \mathbf{0}_{p \times p}$. As a result, it holds true that $F^{\Bu, n}([a', b']) = \Bu^H\Bmu\Bu([a', b']) = 0$ and 
$
     \Im m_{\Bu, n}^{\text{out}}(z) = 0.
$
\par
Let $l$ be a positive integer and define the sequence $\{G_q\}_{q \geq 0}$ of positive measures over $\R^l$ by
\begin{equation}
    G_{n(n+1)/2 + j}(\lambda_1, \ldots, \lambda_l) = \E_j \left(\prod_{i=1}^l F^{\Bu, \BS, n}(\lambda_i) \right), ~~ j \in [n] \cup \{0\}.
\end{equation}
Then, for $q = n(n+1)/2 + j$, the $l$-dimensional Stieltjes transform of $G_q$ is given by
$
    m_{G_q}(z_1, \ldots, z_l) = \E_j \prod_{i \leq l} m_{\Bu, \BS, n}(z_i)
$. By the normal family theorem \cite{hachem2007deterministic, bai2010spectral}, it can be verified that $G_q(\dd \lambda_1,\ldots, \dd \lambda_l) \Rightarrow \prod_{i \leq l} F^{\Bu, n}(\dd \lambda_i)$ almost surely, as $q \to \infty$. 
Notice that on $(-\infty, a'] \cup [b' + \infty)$ the set of functions in $\lambda$,
$
    S_i = \left\{ (\lambda - x)^{-i}: ~~  x \in [a, b] \right\}
$,
forms a uniformly bounded and equicontinuous family for given $i$. By \cite[Problem 8, p. 17]{billingsley2013convergence}, the following holds
\begin{align}
    \sup_{x \in [a, b]} \abs{\int_{ \left[ [a', b']^c \right]^l } \frac{G_q(\dd \lambda_1, \ldots, \dd \lambda_l) - \prod_{i=1}^l F^{\Bu, n}(\dd \lambda_i)}{\prod_{i=1}^l[(\lambda_i - x)^2 + v^2]}} \xrightarrow[q \to \infty]{a.s.} 0,  \label{Eq_G_F_Convg}
    % &\sup_{x \in [a, b]} \abs{\int_{[a', b']^c} \frac{\E_{j} F^{\Bu, \BS, n}(\dd \lambda) - F^{\Bu, n}(\dd \lambda)}{(\lambda - x)^2 + v^2} }\xrightarrow[q \to \infty]{a.s.} 0,
\end{align}
% \begin{align}
%     \sup_{x \in [a, b]} \abs{\int_{[a', b']^c \times [a', b']^c} \frac{G_q(\dd \lambda_1, \ldots, \dd \lambda_l)}{\prod_{i=1}^l[(\lambda_i - x)^2 + v^2]} - v^{-2l}\prod_{i=1}^l \Im m^{\text{in}}_{\Bu, n}(x + \jmath v) } \xrightarrow[q \to \infty]{a.s.} 0,  \label{Eq_G_F_Convg}
%     % &\sup_{x \in [a, b]} \abs{\int_{[a', b']^c} \frac{\E_{j} F^{\Bu, \BS, n}(\dd \lambda) - F^{\Bu, n}(\dd \lambda)}{(\lambda - x)^2 + v^2} }\xrightarrow[q \to \infty]{a.s.} 0,
% \end{align}
for any $v \to 0$. Since \eqref{Eq_G_F_Convg} holds for arbitrary given $l$, we can obtain
\begin{align*}
    & v^{-{2s}}\E_j \abs{\Im m^{\text{in}}_{\Bu, \BS, n}(z)- \Im m_{\Bu, n}(z)}^{2s} =  \sum_{i=0}^{2s} \binom{2s}{i}(-1)^{2s - i}\frac{\E_j[\Im m^{\text{in}}_{\Bu, \BS, n}(z)]^i}{v^i} \frac{[\Im m^{\text{in}}_{\Bu, n}(z)]^{2s-i}}{v^{2s-i}} \to 0 \numberthis
    % \to & \frac{[\Im m^{\text{in}}_{\Bu, n}(z)]^{2a}}{v^{2a}}\sum_{i=0}^{2a} \binom{2a}{i}(-1)^{2a - i} = 0,
\end{align*}
almost surely as $q \to \infty$ for any given positive integer $s$. Using the definition of the index $q$, Hölder's inequality $\E_j|xy| \leq  \E_j^{1/c}|x|^c \E_j^{1/d}|y|^d $ for positive $c, d$ with $c + d = 1$, and letting $r = 1$ in \eqref{Eq_Bilinear_martingale_conv}, we can obtain
\begin{equation}
    \sup_{x \in [a, b]}\max_{0 \leq j \leq n} v^{-l}\E_j\abs{\Im m^{\text{out}}_{\Bu, \BS, n}(z)}^l \xrightarrow[n \to \infty]{a.s.} 0,
\end{equation}
for $v = n^{-\alpha / 68}$.
Observe that for any $x \in [a, b]$, we have 
\begin{equation}
    v^{-1}\Im m^{\text{out}}_{\Bu, \BS, n}(x + \jmath v) = \int_{[a', b']} \frac{F^{\Bu, \BS, n}(\dd \lambda)}{(\lambda - x)^2 + v^2} \geq \int_{[a, b] \cap [x - v, x + v]} \frac{F^{\Bu, \BS, n}(\dd \lambda)}{(\lambda - x)^2 + v^2} \geq \frac{ F^{\Bu, \BS, n}([a, b] \cap [x - v, x + v])}{2v^2}.
\end{equation}
Select points $\{x_k\}_{k \leq L}$ such that the intervals $I_k = [x_k - v, x_k + v]$ cover $[a, b]$ and $x_{k} - x_{k-1} > v$. Hence, we have $L \leq (b - a) / v$ and
\begin{align*}
    &v^{-l} \max_{0 \leq j \leq n} \E_j \left\{ F^{\BS, n}([a, b]) \right\}^l \leq v^{-l} \max_{0 \leq j \leq n} \E_j \left\{ \sum_{k=1}^L F^{\BS, n}([a, b] \cap I_k) \right\}^l \leq 2^l \max_{0 \leq j \leq n} \E_j \left\{ \sum_{k=1}^L \Im m^{\text{out}}_{\Bu, \BS, n}(x_k + \jmath v) \right\}^l
    \\
    &\overset{(a)}{\leq} 2^l L^{l-1} \max_{0 \leq j \leq n} \sum_{k=1}^L \E_j  \left[ \Im m^{\text{out}}_{\Bu, \BS, n}(x_k + \jmath v) \right]^l \leq 2^l(b-a)^l v^{-l} \sup_{x \in [a, b]}\max_{0 \leq j \leq n}\left[ \Im m^{\text{out}}_{\Bu, \BS, n}(x + \jmath v) \right]^l \xrightarrow[n \to \infty]{a.s.} 0, \numberthis
\end{align*}
where step $(a)$ follows by Hölder's inequality. Therefore, we have proved that
\begin{align}
  \max_{0 \leq j \leq n} \E_j \left\{ F^{\Bu, \BS, n}([a, b])\right\}^l = o_{a.s.}\left(v^l\right) = o_{a.s.}\left(n^{-l\alpha / 68}\right),  ~~ \forall l \geq 1, \label{Eq_ESD_u_S_rate}
\end{align}
which give the rate for $F^{\Bu, \BS, n}([a, b])$. By using the same method, the rate for $F^{ \BS, n}([a, b])$ can be also given by
\begin{align}
  \max_{0 \leq j \leq n} \E_j \left\{ F^{\BS, n}([a, b])\right\}^l = o_{a.s.}\left(v^l\right) = o_{a.s.}\left(n^{-l\alpha / 68}\right),  ~~ \forall l \geq 1. \label{Eq_ESD_S_rate}
\end{align}
More generally, the estimation of the rate $n^{-l\alpha / 68}$ in  \eqref{Eq_ESD_u_S_rate} and \eqref{Eq_ESD_S_rate} also holds for the interval $[a', b']$.
