\subsection{A Rate on $F^{\Bu, \BS_j, n}([a, b])$}
Besides estimating $F^{\BS, n}([a, b])$, the evaluation for the number of eigenvalues of $\BS_j = \BSigma_j \BSigma_j^H$ is also important, where $\BSigma_j$ is the rank-one perturbation of $\BSigma$. To this end, we need the following proposition.
\begin{proposition}
\label{Prop_uniform_x_ajQjaj}
Assume the same conditions as in Proposition \ref{Prop_bilinear_of_resolvent_uniform_x}. Let $v = n^{-\alpha / 228}$ and $\Bu \in \mathbb{C}^{p}$ be a deterministic vector with uniformly bounded Euclidean norm. Then, we have
\begin{align}
  \max_{0 \leq i \leq n} \E_i \left\{ v^{-l} \sup_{x \in \mathbb{R}} \abs{ \Bu^H\left[\BQ_j(z) -  \BTheta_j(z)\right] \Bu}^l  \right\} = o_{a.s.}(1), 
\end{align}
where $\BTheta_j(z)$ is defined as
\begin{equation}
  \BTheta_j = \left[-z \left(\BI_p + \sum_{l=1}^n \frac{\BOmega_l \widetilde{\delta}_l}{n} \right) + \BA_j(\BI_{n-1} + \BD_{\delta, j})^{-1} \BA_j^H \right]^{-1},
\end{equation}
with $\BD_{\delta, j} = \diag(\delta_1, \ldots, \delta_{j-1}, \delta_{j+1}, \ldots, \delta_n)$ and $\BA_j = [\Ba_1, \ldots, \Ba_{j-1}, \Ba_{j+1}, \ldots, \Ba_n]$.
\end{proposition}
\textit{Proof: }According to the identity $\BQ = \BQ_j + z\widetilde{q}_j \BQ_j \Bxi_j\Bxi_j^H\BQ_j$ and $-z\widetilde{q}_j = \eta_j + z \widetilde{q}_j \eta_j \Delta_j$, we have 
\begin{align*}
  \Ba_j^H\BQ\Ba_j &= \frac{(1 + \alpha_{j,j}) \Ba_j^H\BQ_j\Ba_j}{1 + \alpha_{j,j} + \Ba_j^H\BQ_j\Ba_j} + \varPi_j, 
\end{align*}
where 
\begin{equation}
    \varPi_j = - z\widetilde{q}_j\eta_j\Delta_j \Ba_j^H\BQ_j \Ba_j\Ba_j^H\BQ_j\Ba_j  + z\widetilde{q}_j \Ba_j^H\BQ_j \By_j\By_j^H\BQ_j\Ba_j + z \widetilde{q}_j \Ba_j^H\BQ_j \By_j\Ba_j^H\BQ_j\Ba_j + z\widetilde{q}_j\Ba_j^H\BQ_j \Ba_j\By_j^H\BQ_j\Ba_j.
\end{equation}
Hence, we can obtain 
\begin{align*}
  \Ba_j^H\BQ\Ba_j + \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j}{1 + \alpha_{j,j}}  =  \Ba_j^H\BQ_j\Ba_j+ \frac{\varPi_j(1 + \alpha_{j,j} + \Ba_j^H\BQ_j\Ba_j)}{1 + \alpha_{j,j}} = \Ba_j^H\BQ_j\Ba_j + \overline{\varPi}_j. \numberthis \label{Eq_a_j_Q_a_j}
\end{align*}
By the Woodbury matrix identity, we can get a similar identity related to $\Ba_j^H \BTheta \Ba_j$
\begin{align*}
  % &\Ba_j^H \BTheta \Ba_j = \frac{(1 + \delta_j)\Ba_j^H\BTheta_j \Ba_j}{1 + \delta_j + \Ba_j^H \BTheta_j \Ba_j} \\
  \Ba_j^H \BTheta \Ba_j + \frac{\Ba_j^H \BTheta_j \Ba_j\Ba_j^H \BTheta \Ba_j}{1 + \delta_j} = \Ba_j^H\BTheta_j \Ba_j. \numberthis \label{Eq_a_j_Theta_a_j}
\end{align*}
By subtracting \eqref{Eq_a_j_Q_a_j} and \eqref{Eq_a_j_Theta_a_j}, we obtain
\begin{align}
  \Ba_j^H(\BQ - \BTheta)\Ba_j + \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j}{1 + \alpha_{j,j}} - \frac{\Ba_j^H \BTheta_j \Ba_j\Ba_j^H \BTheta \Ba_j}{1 + \delta_j}  = \Ba_j^H(\BQ_j - \BTheta_j)\Ba_j + \overline{\varPi}_j
\end{align}
As a result, it holds that 
\begin{align*}
  % &-\overline{\varPi}_j + a_j^H(Q - \Theta)a_j + \frac{a_j^HQa_ja_j^HQ_ja_j}{1 + \alpha_{j,j}} - \frac{a_j^HQa_ja_j^HQ_ja_j}{1 + \delta_j} + \frac{a_j^HQa_ja_j^HQ_ja_j - a_j^H \Theta_j a_ja_j^H \Theta a_j}{1 + \delta_j}  = a_j^H(Q_j - \Theta_j)a_j \\
  & -\overline{\varPi}_j + \Ba_j^H(\BQ - \BTheta)\Ba_j + \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j}{1 + \alpha_{j,j}} - \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j}{1 + \delta_j} \\
  & + \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j - \Ba_j^H\BTheta \Ba_j \Ba_j^H\BQ_j\Ba_j +\Ba_j^H \BTheta \Ba_j\Ba_j^H\BQ_j\Ba_j - \Ba_j^H \BTheta_j \Ba_j\Ba_j^H \BTheta \Ba_j}{1 + \delta_j}  = \Ba_j^H(\BQ_j - \BTheta_j)\Ba_j, \numberthis
\end{align*}
which yields
\begin{align*}
  \left(1 - \frac{\Ba_j^H \BTheta \Ba_j}{1 + \delta_j}\right)
  \Ba_j^H(\BQ_j - \BTheta_j)\Ba_j &=  -\overline{\varPi}_j + \Ba_j^H(\BQ - \BTheta)\Ba_j + \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j}{1 + \alpha_{j,j}} \\
  &- \frac{\Ba_j^H\BQ\Ba_j\Ba_j^H\BQ_j\Ba_j}{1 + \delta_j} + \frac{\Ba_j^H(\BQ - \BTheta)\Ba_j\Ba_j^H\BQ_j\Ba_j }{1 + \delta_j}  = \underline{\varPi}_j. \numberthis
\end{align*}
Using \eqref{Eq_a_j_Theta_a_j}, the following is obtained 
\begin{align*}
    \abs{\Ba_j^H(\BQ_j - \BTheta_j)\Ba_j}   &= \abs{ \frac{\underline{\varPi}_j (1 + \delta_j + \Ba_j^H\BTheta_j \Ba_j)}{1 + \delta_j}} \leq K{v^{-1}(1 + v^{-1}) |\underline{\varPi}_j|} \\
    & \leq K \left(v^{-4}|{\varPi}_j| +  v^{-4}|\Ba_j^H (\BQ - \BTheta) \Ba_j| + v^{-6} |\alpha_{j, j} - \delta_j| \right). \numberthis
\end{align*}
Similarly, we have 
\begin{align*}
\abs{\Ba_j^H (\BQ_j - \BTheta_j) \Bu} &\leq K\left( v^{-2}\abs{\Ba_j^H (\BQ - \BTheta) \Bu} + v^{-4} |\alpha_{j, j} - \delta_j| + v^{-2}\abs{\Ba_j^H (\BQ_j - \BTheta_j) \Ba_j} + v^{-2} |\varPi_j^{u, 1}| \right), \numberthis \\
\abs{\Bu_j^H (\BQ_j - \BTheta_j) \Ba_j} &\leq K\left( v^{-2}\abs{\Bu_j^H (\BQ - \BTheta) \Ba_j} + v^{-4} |\alpha_{j, j} - \delta_j| + v^{-2}\abs{\Ba_j^H (\BQ_j - \BTheta_j) \Ba_j} + v^{-2} |\varPi_j^{u, 2}| \right), \numberthis \\
\abs{\Bu^H (\BQ_j - \BTheta_j) \Bu} &\leq K \Big( \abs{\Bu^H( \BQ - \BTheta) \Bu} + v^{-4} |\alpha_{j,j} - \delta_j| + v^{-4}|\Ba_j^H(\BTheta_j - \BQ_j) \Ba_j| \\
&+ v^{-2}\abs{\Ba_j^H(\BTheta_j - \BQ_j) \Bu} + v^{-2}\abs{\Bu^H(\BTheta_j - \BQ_j) \Ba_j}+ \abs{\varPi_j^{u, u}} \Big), \numberthis
\end{align*}
where $\varPi^{u,1}_j$, $\varPi^{u,2}_j$, and $\varPi^{u,u}_j$ have similar forms as $\varPi_j$.
Letting $r = 9$ in Proposition \ref{Prop_bilinear_of_resolvent_uniform_x}, we can get the probabilistic bound $\PP(\max_{x \in S_n} v^{-1}\abs{\Bu^H(\BQ_j - \BTheta_j)\Bu} \geq \epsilon) \leq K_d \epsilon^{-d} n^{-l}$, which implies 
\begin{align}
  \max_{0 \leq i \leq n} \E_i \left\{ v^{-l} \sup_{x \in \mathbb{R}} \abs{ \Bu^H\left[\BQ_j -  \BTheta_j\right] \Bu}^l  \right\} = o_{a.s.}(1).
\end{align}
Therefore, Proposition \ref{Prop_uniform_x_ajQjaj} is proved. \qed
\par
By the properties of the Stieltjes transform, it can be verified that $\BTheta_j$ is a matrix-valued Stieltjes transform and  $\Bu^H \BTheta_j(z) \Bu$ is the Stieltjes transform of a non-negative measure denoted by $F^{\Bu, nj}$. 
By Proposition \ref{Prop_same_support}, $[a', b']$ is outside the support of the underline measure of $\delta_j$.
As a result, for any $x_1, x_2 \in [a', b']$, we have 
\begin{equation}
   \sup_{x_1, x_2 \in [a', b']}\frac{\abs{ \delta_j(x_1) - \delta_j(x_2)}}{|x_1 - x_2|} \leq \sup_{x_1, x_2 \in [a', b']}\int_{\R^+} \frac{\mu_j(\dd \lambda)}{\abs{x_1 - \lambda}{\abs{x_2 - \lambda}}} \leq \frac{ \mu_j(\R^+)}{\dist^2([a', b'], \mathsf{Supp}(\mu_j))} \leq K,
\end{equation}
where $K$ is a constant that is independent of $j$ and $n$.
Similarly, we can also get $\sup_{x_1, x_2 \in [a', b']}|\widetilde{\delta}_j(x_1) - \widetilde{\delta}_j(x_2)| / |x_1 - x_2| \leq K$.
Therefore, we can assume $\liminf_n \inf_{x \in [a', b']} \min_{j \leq n} \{|\widetilde{\delta}_j(x)|, |1 + \delta_j(x)|\} > 0$ without loss of generality. Letting $z \in \mathbb{C}^+ \to x \in [a', b']$ and by the relation 
\begin{align*}
    \Bu^H \BTheta \Bu = \Bu^H \BTheta_j \Bu + z\widetilde{\delta}_j \Bu^H \BTheta_j \Ba_j \Ba_j^H \BTheta_j \Bu = \Bu^H \BTheta_j \Bu + \frac{\Bu^H \BTheta \Ba_j \Ba_j^H \BTheta \Bu}{z\widetilde{\delta}_j(1 + \delta_j)^2}, \numberthis
\end{align*}
% \begin{equation}
%     \Ba_j^H \BTheta_j(z) \Ba_j = \frac{-\Ba_j^H \BTheta(z) \Ba_j}{(1 + \delta_j(z))z\widetilde{\delta}_j(z)},
% \end{equation}
we have $\lim_{z \in \mathbb{C}^+ \to x} \Im(\Bu^H\BTheta_j(z)\Bu) = 0$ since $|1 + \delta_j(x)|, |\widetilde{\delta}_j(x)| > 0$, $\lim_{z \in \mathbb{C}^+ \to x} \BTheta(z) = \BTheta_0$ exists, and $\BTheta_0$ is Hermitian. In the above derivation, we also used the result that $x$ is outside the support of the underlying matrix-valued measure of $\BTheta(z)$, which is proved in Section \ref{Sec_A_rate_one_F}. As a result, it holds that $F^{\Bu, nj}([a', b']) = 0$.
Recalling that $F^{\Bu ,\BS_j ,n}$ is the underline measure of the Stieltjes transform $\Bu^H \BQ_j \Bu$,
Proposition \ref{Prop_uniform_x_ajQjaj} together with $F^{\Bu, nj}([a', b']) = 0$ implies
\begin{align}
  &\max_{ 0\leq i \leq n, 1 \leq j \leq n} \E_i \left\{ F^{\Bu, \BS_j, n}([a', b'])\right\}^l = o_{a.s.}\left(n^{-l\alpha  / 228}\right), ~~ \forall l \geq 1. \label{Eq_ESD_aj_Sj_rate}
\end{align}
\subsection{Convergence of $|m_{\BS_n} - \E m_{\BS, n}|$}
\label{Sec_Conv_random_part}
 In this section, we take $v = n^{-\alpha / 912}$ and prove that
\begin{equation}
  \sup_{x \in [a, b]} pv\abs{m_{\BS, n} - \E m_{\BS, n}} \xrightarrow{a.s.} 0. \label{Eq_pv_Diff_m_as_0}
\end{equation}
Following the same argument as Proposition \ref{Prop_bilinear_of_resolvent_uniform_x}, we note that it is sufficient to prove
\begin{equation}
  \sup_{x \in S_n} pv\abs{m_{\BS, n} - \E m_{\BS, n}} \xrightarrow{a.s.} 0,
\end{equation}
where $S_n = \{a + t(b - a) / (n^2 - 1), t = 0, \ldots, n^2-1\}$.
To proceed, we define the following quantities
\begin{align*}
  &\gamma_j = \frac{1}{1 + \frac{1}{n} \Tr \BOmega_j \E \BQ_j + \Ba_j^H \E \BQ_j \Ba_j}, ~~ \Xi_j = \frac{1}{n}\Tr \BOmega_j(\BQ_j - \E \BQ_j) + \Ba_j^H (\BQ_j - \E \BQ_j) \Ba_j \\
  & \underline{\Delta}_j = \Bxi_j^H\BQ_j^2 \Bxi_j - \frac{1}{n} \Tr \BOmega_j \BQ_j^2 - \Ba_j^H \BQ_j^2 \Ba_j. \numberthis \label{Eq_Def_2_gamma_Delta_xi}
\end{align*}
The following proposition shows the bound for the terms defined in \eqref{Label_Def_of_terms_bilinear} and \eqref{Eq_Def_2_gamma_Delta_xi} with $x \in [a, b]$. These bounds will be frequently used in the proof.
\begin{proposition}
\label{Prop_bound_ab_K_o}
For $z = x + \jmath v = x + \jmath n^{-\alpha / 912}$, there exists constant $K^o > 0$ such that for any $x \in [a, b]$ and sufficiently large $n$, the following holds.
\begin{equation}
  \max_{j \leq n}\left\{ |\delta_j|, | z\widetilde{\delta}_j|, |\kappa_j|,  |z\widetilde{\kappa}_j|, |\E\eta_j| , |\gamma_j|, \frac{1}{|1 + \delta_j|}, \frac{1}{|1 + \kappa_j|}, \frac{1}{|1 + \E \alpha_{j, j}|} \right\} \leq K^o.
\end{equation}
\end{proposition}
\textit{Proof:} By Proposition \ref{Prop_same_support}, we know the interval $[a', b']$ is outside the support of $\mu_j$, $\widetilde{\mu}_j$. Hence, we have
\begin{equation}
    |\delta_j(z)| \leq \int_{\R^+} \frac{\mu_j(\dd \lambda)}{|\lambda - z|} \leq \frac{\mu_j(\R)}{\underline{\epsilon}^2} \leq \frac{\Tr \BOmega_j}{n\underline{\epsilon}^2},
\end{equation}
where we recall that $\underline{\epsilon} = |a - a'| = |b - b'|$.
The inequality $|\widetilde{\delta}_j| \leq \underline{\epsilon}^{-2}$ can be shown similarly. By Lemma \ref{Lemm_bilinear}, we know 
$|\delta_j - \kappa_j |$, $|z\widetilde{\delta}_j - z\widetilde{\kappa}_j|$, $|z\widetilde{\delta}_j + \E \eta_j|$, and $|z\widetilde{\delta}_j + \gamma_j|$ are of order $o(1)$ uniformly for $x \in [a, b]$, which proves the bounds for these terms.
The bound for $1 / |1 + \delta_j|$ is due to the assumption that $\liminf_n \inf_j |1 + \delta_j| > 0$ for $x \in [a, b]$. Since $|\delta_j - \kappa_j|, |\kappa_j - \E\alpha_{j, j}| = o(1)$, $1 / |1 + \kappa_j|, 1 / |1 + \E \alpha_{j, j}| < \infty$ are proved.  \qed
\par
Writing $p\E m_{\BS, n} - pm_{\BS, n}$ as the sum of the martingale difference sequence and using $-z\widetilde{q}_j = \eta_j + z\widetilde{q}_j \Delta_j  \eta_j$, we have 
\begin{align*}
&p \E m_{\BS, n} - p m_{\BS, n}  = \sum_{j=1}^n [\E_{j} - \E_{j-1}] -z\widetilde{q}_j \Bxi_j^H \BQ_j^2 \Bxi_j \\
&= \sum_{j=1}^n [\E_{j} - \E_{j-1}] \eta_j \Bxi_j^H \BQ_j^2 \Bxi_j + [\E_{j} - \E_{j-1}] z\widetilde{q}_j \eta_j \Delta_j \Bxi_j^H \BQ_j^2 \Bxi_j \\
& = \sum_{j=1}^n [\E_{j} - \E_{j-1}] \eta_j \Bxi_j^H \BQ_j^2 \Bxi_j + [\E_{j} - \E_{j-1}] z\widetilde{q}_j \eta_j \Delta_j \left(\Bxi_j^H \BQ_j^2 \Bxi_j - \frac{1}{n} \Tr \BOmega_j \BQ_j^2 - \Ba_j^H\BQ_j^2 \Ba_j\right) \\
&+ [\E_{j} - \E_{j-1}]z\widetilde{q}_j \eta_j \Delta_j \left(\frac{1}{n}\Tr \BOmega_j \BQ_j^2 + \Ba_j^H\BQ_j^2\Ba_j\right)  = \sum_{j=1}^n \varGamma_{1j} + \varGamma_{2j} + \varGamma_{3j}. \numberthis
\end{align*}
Let $F^{\BS_j, n}$ be the ESD of $\BS_j = \BSigma_j \BSigma_j^H$. 
% By \eqref{Eq_ESD_aj_Sj_rate}, \eqref{Eq_ESD_S_rate} and \cite[Lemma 2.12]{bai1998no}, we get 
% $
%     \max_{i, j \leq n} \E_i\left\{ F^{\BS_j, n}([a', b'])\right\}^2 = o(v^8)
% $ and $$.
Define the indicator function 
\begin{equation}
  \mathscr{I}_j = \Ind_{\left\{\E_{j-1} \left[F^{\BS_j, n}([a', b']) + F^{\Ba_j, \BS_j, n}([a', b'])\right] \leq v^4\right\} \cap \left\{\E_{j-1} \left[F^{\BS_j, n}([a', b']) + F^{\Ba_j, \BS_j, n}([a', b'])\right]^2 \leq v^8\right\}}.
\end{equation}
Then, by \eqref{Eq_ESD_u_S_rate}, \eqref{Eq_ESD_S_rate}, \eqref{Eq_ESD_aj_Sj_rate}, and \cite[Lemma 2.12]{bai1998no}, we can obtain $\PP(\cup_{j=1}^n \{\mathscr{I}_j = 0\} \mathrm{~~ i.o.}) = 0$. As a result, we have, for any $\epsilon > 0$,
\begin{align*}
    \PP \left( v \max_{x \in S_n} \abs{\sum_{j=1}^n \varGamma_{1j}} > \epsilon \mathrm{~~ i.o.} \right) &\leq \PP \left( \left(\left[\max_{x \in S_n} v\abs{\sum_{j=1}^n \varGamma_{1j}}> \epsilon \right]\right) \bigcap_{j=1}^n [\mathscr{I}_j = 1]  \bigcup\left(\bigcup_{j=1}^n[\mathscr{I}_j = 0] \right)\mathrm{~~ i.o.} \right) \\
    &\leq \PP  \left(\max_{x \in S_n} v\abs{\sum_{j=1}^n \varGamma_{1j} \mathscr{I}_j}> \epsilon \mathrm{~~ i.o.}\right). \numberthis \label{Eq_Probabilistic_io_varGamma1}
\end{align*}
By the independence between $\By_j$ and $\mathscr{F}_{j-1}$, we can obtain 
\begin{equation}
  \varGamma_{1j}\mathscr{I}_j = \E_{j}\mathscr{I}_j\eta_j \left(\By_j^H \BQ_j^2 \By_j - \frac{1}{n}\Tr \BOmega_j \BQ_j^2\right) + \E_j \mathscr{I}_j\eta_j \Ba_j^H \BQ_j^2 \By_j + \E_j\mathscr{I}_j \eta_j \By_j^H \BQ_j^2 \Ba_j = \chi_{1j} + \chi_{2j} + \chi_{3j}.
\end{equation}
Since $\mathscr{I}_j \in\mathscr{F}_{j-1}$, $\{ \chi_{ij} \}_{1 \leq j\leq n}$ forms martingale difference sequences for $i=1, 2, 3$, Lemma \ref{Lemm_Burk_Ineq} shows
\begin{align*}
  \E \abs{\sum_{j=1}^nv\varGamma_{1j}\SI_j}^{2t}  \lesssim_t \sum_{i=1}^3\left[  \E \left( \sum_{j=1}^n \E_{j-1}|v\chi_{ij}|^2 \right)^{t} + \sum_{j=1}^n \E \abs{v\chi_{ij}}^{2t} \right], t \geq 3. \numberthis \label{Eq_Burk_varGamma1j_chi}
\end{align*}
Next, we evaluate the terms on the RHS of \eqref{Eq_Burk_varGamma1j_chi} that are related to $\chi_{1j}$. By writing $1 = \Ind_{\{|\eta_j| > 2K^o \}} + \Ind_{\{|\eta_j| \leq  2K^o \}}$, we have
\begin{align*}
  &v^2\sum_j \E_{j-1} |\chi_{1j}|^2 \leq v^2\sum_j \E_{j-1} \SI_j|\eta_j|^2 \abs{\By_j^H \BQ_j^2 \By_j - \frac{1}{n}\Tr \BOmega_j \BQ_j^2}^2 \lesssim \sum_j\frac{v^2}{n^2} \E_{j-1} \SI_j|\eta_j|^2 \Tr \BOmega_j \BQ_j^2 \BOmega_j \BQ_j^{H, 2} \\
  & \lesssim \sum_j\frac{v^2}{n^2} \E_{j-1} \SI_j \Tr \BOmega_j \BQ_j^2 \BOmega_j \BQ_j^{H, 2} + \frac{1}{nv^4} \E_{j-1} \Ind_{\{|\eta_j| > 2K^o \}}. \numberthis \label{Eq_I_chi_1j}
\end{align*}
Denoting $\lambda_{jl}$ as the $l$-th smallest eigenvalue of $\BS_j$, we have, on the set $\{ \SI_j = 1 \}$,
\begin{align*}
  &\E_{j-1}\Tr \BOmega_j \BQ_j^2 \BOmega_j \BQ_j^{H, 2} \leq (\omega^+)^2 \Tr \BQ_j^2\BQ_j^{H, 2} = (\omega^+)^2 \E_{j-1}\sum_{l=1}^p \frac{1}{((\lambda_{jl} - x)^2 + v^2)^2} \\
  &= (\omega^+)^2 \E_{j-1}\left[ \sum_{\lambda_{jl} \in [a', b']} \frac{1}{((\lambda_{jl} - x)^2 + v^2)^2} +  \sum_{\lambda_{jl} \notin [a', b']} \frac{1}{((\lambda_{jl} - x)^2 + v^2)^2} \right] \\
  &\leq  (\omega^+)^2 \left[p v^{-4} \E_{j-1}F^{\BS_{j}, n}([a', b']) + p \underline{\epsilon}^{-4} \right]  \leq Kn, \numberthis \label{Eq_I_j_TrQQ}
\end{align*}
for some constant $K$ and $\omega^+ := \sup_{j, n} \norm{\BOmega_j}$. Moreover, $|\eta_j| > 2K^o$ implies that $|\gamma_j^{-1} + \Xi_j| < 1 / (2K^o)$ and  thus the following holds by $|\gamma_j| \leq K^o$
\begin{equation}
    \Ind_{\{ |\eta_j| > 2K^o\}} \leq  \Ind_{\{ |\gamma_j^{-1} + \Xi_j| < 1 / (2K^o)\}} \leq \Ind_{\{|\Xi_j| \geq 1/(2K^o)\}}.
\end{equation}
As a result, by $(\sum_{j=1}^n |a_j|)^t \leq (\sum_{j=1}^n |a_j|^t)n^{t-1}$, we get
\begin{align*}
  &\E \left( v^2\sum_{j=1}^n \E_{j-1} |\chi_{1j}|^2 \right)^{t}  \lesssim v^{2t} + \frac{1}{n^{t}v^{4t}} \E \left(\sum_{j=1}^n \E_{j-1} \Ind_{\{|\Xi_j| \geq 1/(2K^o) \}} \right)^t \\
  & \leq v^{2t} + \frac{\sum_{j=1}^n \PP (|\Xi_j| \geq  1 / (2K^o))}{nv^{4t}} \leq  v^{2t} + \frac{(2K^o)^m\sum_{j=1}^n \E|\Xi_j|^m}{nv^{4t}} \overset{(a)}{\lesssim_t} v^{2t}, \numberthis \label{Eq_E_v2_E_j_x_1j2}
\end{align*}
where step $(a)$ follows by choosing a large $m$ and applying \eqref{Eq_Part_I}. By Lemma \ref{Lemm_trace}, we can obtain 
\begin{align*}
  \sum_{j=1}^n \E |\chi_{1j}|^{2t} \leq \sum_{j=1}^n \E \abs{\eta_j}^{2t}\abs{\By_j^H \BQ_j^2 \By_j - \frac{1}{n}\Tr \BOmega_j \BQ_j^2}^{2t} \lesssim_t \frac{1}{v^{2t}}\sum_{j=1}^n \frac{1}{n^{4\alpha t + 1} v^{4t}} = \frac{1}{n^{4\alpha t} v^{6t}}. \numberthis
\end{align*}
Next, we estimate the terms related to $\chi_{2j}$ on the RHS of \eqref{Eq_Burk_varGamma1j_chi}. Similar to \eqref{Eq_I_chi_1j} and using $\Ba^H \BC \Ba \leq \Ba^H \Ba \norm{\BC}$, we have
\begin{align*}
  &v^2 \sum_{j=1}^n \E_{j-1} |\chi_{2j}|^2 \leq \sum_{j=1}^n  v^2\E_{j-1} \mathscr{I}_j|\eta_j \Ba_j^H \BQ_j^2 \By_j|^2 \leq \sum_{j=1}^n \frac{v^2}{n}\E_{j-1} \mathscr{I}_j |\eta_j|^2 \Ba_j^H\BQ_j^2\BOmega_j\BQ_j^{2, H}\Ba_j \\
  &\lesssim \sum_{j=1}^n\frac{v^2}{n}\E_{j-1} \mathscr{I}_j |\eta_j|^2 {\Ba_j^H\BQ_j^2\BQ_j^{2, H}\Ba_j} \lesssim \sum_{j=1}^n \frac{v^2}{n} \E_{j-1} \mathscr{I}_j \Ba_j^H\BQ_j\BQ_j^{2, H} \Ba_j + \frac{1}{nv^4} \E_{j-1 } \Ind_{\{|\Xi_j| > 1/(2K_o)\}}. \numberthis \label{Eq_v2_E_j_chi2j2}
\end{align*}
Write the singular value decomposition of $\BS_j$ as $\BU_j \diag(\lambda_{jl}; 1 \leq l \leq p) \BU_j^H$ and  denote $\overline{\Ba}_j = \BU_j^H\Ba_j$. Here, on the set $\SI_j$, the following estimation holds by \eqref{Eq_ESD_aj_Sj_rate} 
\begin{align*}
  & \E_{j-1} \Ba_j^H\BQ_j\BQ_j^{2, H} \Ba_j = \E_{j-1} \left[ \sum_{\lambda_{jl} \in [a', b']} \frac{|[\overline{\Ba}_j]_l|^2}{((x - \lambda_{jl})^2 + v^2)^2} + \sum_{\lambda_{jl} \notin [a', b']} \frac{|[\overline{\Ba}_j]_l|^2}{((x - \lambda_{jl})^2 + v^2)^2}  \right]  \\
  & \leq  \underline{\epsilon}^{-4}{\norm{\Ba_j}^2} + v^{-4}\E_{j-1}F^{\Ba_j, \BS_j, n}([a', b']) \leq K, \numberthis \label{Eq_E_j_ajQjQjaj}
\end{align*}
with some constant $K$.  Therefore,  substituting \eqref{Eq_E_j_ajQjQjaj} into equation \eqref{Eq_v2_E_j_chi2j2}, and using the same method as in \eqref{Eq_E_v2_E_j_x_1j2}, we obtain
\begin{equation}
    \E \left( v^2 \sum_{j=1}^n \E_{j-1} |\chi_{2j}|^2 \right)^{2t} \lesssim_t v^{2t}. \label{Eq_burk_chi_2j_bound_1}
\end{equation}
The following can be derived by Lemma \ref{Lemm_trace}
\begin{equation}
    \sum_{j=1}^n \E |\chi_{2j}|^{2t} \lesssim_t \frac{1}{n^{2 \alpha t + 1} v^{6t}}. \label{Eq_burk_chi_2j_bound_2}
\end{equation}
The evaluation of the terms related to $\chi_{3j}$ is similar to \eqref{Eq_burk_chi_2j_bound_1} and \eqref{Eq_burk_chi_2j_bound_2}. Therefore, we get 
\begin{equation}
    \PP \left(\max_{x \in S_n}\abs{\sum_{j=1}^nv\varGamma_{1j}\SI_j} \geq \epsilon \right) \leq \frac{1}{\epsilon^{2t}}\sum_{x \in S_n}\E \abs{\sum_{j=1}^nv\varGamma_{1j}\SI_j}^{2t} \leq K_{t, \epsilon}n^{2-2t\alpha/912}, ~~ t \geq 3.
\end{equation}
By Borel-Cantelli Lemma and \eqref{Eq_Probabilistic_io_varGamma1}, we know  $\max_{x \in S_n}|\sum_{j}v\varGamma_{1j}| \to 0$ almost surely.
\par 
Next, we handle $\sum_j \varGamma_{2j}$. We first give the following probabilistic bound
\begin{equation}
  \PP \left( |z\widetilde{q}_j \eta_j \Delta_j| > n^{-\alpha / 3} \right) \leq \frac{\E\left[|z\widetilde{q}_j| |\eta_j| |\Delta_j|\right]^r}{n^{-\frac{ \alpha r}{3}}} \lesssim \frac{ \E^{\frac{1}{2}}{\norm{\BSigma}}^{4r} \E^\frac{1}{2} |\Delta_j|^{2r} }{v^{2r}n^{-\frac{ \alpha {r}}{3}}} \lesssim_r \frac{1}{n^{2 \alpha r / 3}v^{3r}},
\end{equation}
for large $r$. Hence, we have
\begin{align*}
  \sum_{j=1}^n \E_{j-1} \abs{v\varGamma_{2j}}^2 &\lesssim  v^2\sum_{j=1}^n \E_{j-1}\abs{z \widetilde{q}_j \eta_j \Delta_j \underline{\Delta}_j}^2 \lesssim n^{-{2\alpha}/3}\sum_{j=1}^n v^2\E_{j-1}\abs{ \underline{\Delta}_j}^2 + \sum_{j=1}^n \frac{n^8}{v^8}\E_{j-1} \Ind{\{|z\widetilde{q}_j \eta_j \Delta_j| > n^{-\alpha / 3}\}} \\
  & \lesssim \frac{1}{n^{{2\alpha}/3}v^{2}} + \frac{n^8}{v^8} \sum_{j=1}^n \E_{j-1}\Ind{\{|z\widetilde{q}_j \eta_j \Delta_j| > n^{- \alpha/3}\}}, \numberthis
\end{align*}
since $\norm{\Bxi_j} \leq \sqrt{n}$, $\norm{\BSigma} \leq n$, $|z \widetilde{q}_j| \lesssim n^2 / v$, $|\Delta_j| \lesssim n / v$, and $|\underline{\Delta}_j| \lesssim n / v^2$. As a result, we can obtain
\begin{align*}
  \E \abs{ \sum_{j=1}^n v \varGamma_{2j} }^{2t} \lesssim_t \sum_{j=1}^n  \E \left[\sum_{j=1}^n\E_{j-1}\abs{v\varGamma_{2j}}^2 \right]^t + \sum_{j=1}^n \E|v \varGamma_{2j}|^{2t} \lesssim \frac{1}{n^{2\alpha t / 3}v^{2t}} + \frac{n^{9t}}{v^{8t}v^{3r}n^{2\alpha r / 3}} + \frac{1}{v^{8t} n^{2 \alpha t}}. \numberthis \label{Eq_varGamma_2_bound}
\end{align*}
 By choosing sufficiently large $t$ and $r$ in the above inequality, we have $\max_{x \in S_n}|\sum_{j}\varGamma_{2j}|  = o_{a.s.}(v^{-1})$.
 \par
 In the following, we handle $\sum_j \varGamma_{3j}$. By the similar argument as in \eqref{Eq_Probabilistic_io_varGamma1}, it is sufficient to handle $\sum_j \varGamma_{3j} \SI_j$. Using the same method as in \eqref{Eq_I_chi_1j}, we get 
\begin{align*}
  \sum_{j=1}^n \E_{j-1}\abs{v\SI_j \varGamma_{3j}}^2 &\lesssim v^2\sum_{j=1}^n \SI_j \E_{j-1} \abs{z \widetilde{q}_j \eta_j}^2\abs{ \frac{1}{n} \Tr \BOmega_j \BQ_j^2 + \Ba_j^H\BQ_j^2\Ba_j}^2 |\Delta_j|^2 \\
  &\lesssim v^2 \sum_{j=1}^n \SI_j \E_{j-1}\abs{ \frac{1}{n} \Tr \BOmega_j \BQ_j^2 + \Ba_j^H\BQ_j^2\Ba_j}^2 |\Delta_j|^2 + \frac{n^6}{v^8}\E_{j-1} \Ind_{\{|\eta_j| \geq 2K^o\} \cup \{|z\widetilde{q}_j| \geq 2K^o\}}. \numberthis \label{Eq_varGamma_3j_split}
\end{align*}
By using Cauchy-Schwarz inequality $|\Tr \BC\BD^H|^2 \leq \Tr\BC\BC^H \Tr \BD \BD^H $ and $\Ba^H\Bb \leq \norm{\Ba}^2 \norm{\Bb}^2$, we have 
% \begin{align*}
%     \abs{ \frac{1}{n} \Tr \BOmega_j \BQ_j^2 + \Ba_j^H\BQ_j^2\Ba_j}^2 &\leq 2 \left(\frac{1}{n} \Tr \BOmega_j^{1/2} \BQ_j\BOmega_j^{1/2} \BQ_j^H\right)^2 + 2\left(\Ba_j^H \BQ_j \BQ_j^H \Ba_j \right)^2. \\
%     &\leq  2 (\omega^+)^2 \left(\frac{1}{n} \Tr \BQ_j \BQ_j^H\right)^2 + 2\left(\Ba_j^H \BQ_j \BQ_j^H \Ba_j \right)^2
% \end{align*}
\begin{align*}
    \abs{ \frac{1}{n} \Tr \BOmega_j \BQ_j^2 + \Ba_j^H\BQ_j^2\Ba_j}^2 &\leq 2 \abs{\frac{1}{n} \Tr \BOmega_j \BQ_j^2}^2 + 2\Ba_j^H \BQ_j^2 \Ba_j \Ba_j^H \BQ_j^{H, 2} \Ba_j  \\
    &\leq  2 \frac{\Tr \BOmega_j^2}{n^2} \Tr \BQ_j^2 \BQ_j^{H, 2} + 2\norm{\Ba_j}^2 \Ba_j^H \BQ_j^2 \BQ_j^{H, 2} \Ba_j. \numberthis
\end{align*}
Then, we can obtain, for $x \in [a, b]$,
\begin{align*}
    &v^2 \sum_{j=1}^n \SI_j \E_{j-1}\abs{ \frac{1}{n} \Tr \BOmega_j \BQ_j^2 + \Ba_j^H\BQ_j^2\Ba_j}^2 |\Delta_j|^2 \\
    &\lesssim \frac{v^2}{n} \sum_{j=1}^n \SI_j \E_{j-1}\left[ \frac{1}{p} \Tr \BQ_j^2\BQ_j^{H,2} + \Ba_j^H \BQ_j^2 \BQ_j^{H, 2} \Ba_j  \right] \left[\frac{1}{p} \Tr \BQ_j\BQ_j^H + \Ba_j^H \BQ_j\BQ_j^H \Ba_j \right] \\
    &\leq \frac{v^2}{n} \sum_{j=1}^n \E_{j-1} \SI_j \Big\{  \left[\left(1 + \norm{\Ba_j}^2 \right)\underline{\epsilon}^{-4} + v^{-4}F^{\BS_j, n}([a', b']) + v^{-4} F^{\Ba_j, \BS_j, n}([a', b']) \right] \\
   &~~~  \times \left[\left(1 + \norm{\Ba_j}^2 \right) \underline{\epsilon}^{-2} + v^{-2} F^{\BS_j, n}([a', b']) + v^{-2} F^{\Ba_j, \BS_j, n}([a', b']) \right] \Big\}  \lesssim v^2. \numberthis \label{Eq_F_aj_Sj_F_Sj_2}
\end{align*}
As a result, we have 
\begin{equation}
    \E\left( \sum_{j=1}^n \E_{j-1}\abs{v\SI_j \varGamma_{3j}}^2\right)^t \lesssim_t v^{2t} + {v^{-8t}n^{7t-1} \sum_{j=1}^n \left[ \PP(|\Xi_j| > 1/(2K^o)) + \PP(|\Delta_j + \Xi_j| > 1/(2K^o)) \right] } \lesssim_t v^{2t}.
\end{equation}
Therefore, the following bound holds
\begin{align*}
    \E\abs{\sum_{j=1}^n v \SI_j \varGamma_{3j}}^{2t} \lesssim_t v^{2t} + \sum_{j=1}^n \E |v\varGamma_{3j}|^{2t} \lesssim_t v^{2t} + \frac{\log^{4t}(n)}{v^{8t}n^{2 \alpha t}}, \numberthis
\end{align*}
which implies $\max_{x \in S_n} |\sum_j \varGamma_{3j}| = o_{a.s.}(v^{-1})$. Gathering the above analysis, we can prove that 
\begin{equation}
    \sup_{x \in S_n} \abs{ \sum_{j=1}^n \varGamma_{1j} + \varGamma_{2j} + \varGamma_{3j} } = o_{a.s.}(v^{-1}), 
\end{equation}
which completes the proof of \eqref{Eq_pv_Diff_m_as_0}.
\subsection{Convergence of $\E m_{\BS, n} - m_n$} In this section, for $z = x + \jmath v = x + \jmath n^{-\alpha / 912}$, we prove 
\begin{align*}
  \sup_{x \in [a, b]} p \abs{\E m_{\BS, n}(z) - m_n(z)}  \lesssim 1. \numberthis \label{Eq_Mean_Part}
\end{align*}
We begin by proving the following bound
\begin{equation}
    \sup_{x \in [a, b]} \norm{\BR(z)} \lesssim 1. \label{Eq_sup_ab_norm_R}
\end{equation}
According to discussion in Section \ref{Sec_A_rate_one_F}, we know $\Bmu([a, b]) = \mathbf{0}_{p \times p}$.  To get the bound for $\norm{\BTheta(z)}$, we choose a sequence of simple functions  \cite{rudin1987real} $\{f_k\}_{k \geq 1}$, where $f_k$ is a piece-wise constant function with $f_{k}(\lambda) = \sum_{l=1}^{N_k} a_{k, l} \Ind\{\lambda \in A_{k, l}\}$, $|f_k(\lambda)| \leq  |1 / (\lambda - z)|$, and $f_k(\lambda) \to 1 / (\lambda - z)$ as $k \to \infty$ for any $\lambda \in \R^+$. By the dominant convergence theorem, we have
\begin{align*}
    &\norm{\BTheta(z)} = \norm{\int_{\R^+}\frac{\Bmu(\dd \lambda)}{\lambda - z}} =\norm{\int_{\R^+}\lim_{k \to \infty} f_k \Bmu(\dd \lambda)}  = \norm{\lim_{k \to \infty} \sum_{l=1}^{N_k} a_{k, l}{\Bmu(A_{k, l})}} \\
    &\overset{(a)}{\leq} \norm{\lim_{k \to \infty} \sum_{l=1}^{N_k} |a_{k, l}|{\Bmu(A_{k, l})} } = \norm{\lim_{k \to \infty}\int_{\R^+} |f_k|{\Bmu(\dd \lambda)}} = \norm{\int_{\R^+} \frac{\Bmu(\dd \lambda)}{|\lambda - z|}} \leq \frac{1}{\underline{\epsilon}}, \numberthis \label{Eq_sup_ab_norm_Theta}
\end{align*}
where step $(a)$ follows by Lemma \ref{Lemm_Spnorm_Bound_of_sum_semidef_matrices}. Here, we used the fact that $\sup_{x \in [a, b]} |1 / (\lambda - z)| \leq 1 / \underline{\epsilon}$ since $[a, b] \subset [a', b']$.
By \eqref{Eq_Boud_norm_diff_R_Theta}, we can get $\sup_{x \in [a, b]} \norm{\BR - \BTheta} = o(1)$. Hence, \eqref{Eq_sup_ab_norm_R} holds. 
\begin{proposition}
\label{Prop_EQ_ER_EwQ_EwR}
    Let $\BD_T \in \mathbb{C}^{p \times p}$ be a diagonal matrix and $\BT \in \mathbb{C}^{p \times p}$ be a Hermitian non-negative matrix such that $\norm{\BD_T}, \norm{\BT} \leq T < \infty$. Then, we have  
\begin{align*}
  &\sup_{x \in [a, b]} \abs{ \Tr \BT \left( \E \BQ - \BR \right) } \lesssim 1, \numberthis \label{Eq_EQ_R}\\
  &\sup_{x \in [a, b]} \abs{z\Tr \BD_T(\E\widetilde{\BQ} - \widetilde{\BR}) } \lesssim 1. \numberthis \label{Eq_EwQ_wR}
\end{align*}
\end{proposition}
\textit{Proof: } The bound in \eqref{Eq_EQ_R} can be obtained by following the similar approach as in Section \ref{Para_Part_II}, i.e., by using the resolvent identity to break the target into a sum of terms with means close to 0 and finite moments. The difference here is that we need to bound the spectral norm of $\BR$ by \eqref{Eq_sup_ab_norm_R} for $x \in [a, b]$, as well as the following bound which can be obtained by the same argument as in \eqref{Eq_I_j_TrQQ}, \eqref{Eq_E_j_ajQjQjaj}, and \eqref{Eq_F_aj_Sj_F_Sj_2}
\begin{equation}
    \sup_{x \in [a, b]}\E \left[ \frac{1}{p} \Tr \BQ_j^{t_1} \BQ_j^{t_1, H} + \Ba_j^H \BQ_j^{t_1} \BQ_j^{t_1, H} \Ba_j \right]^{a_1}\left[ \frac{1}{p} \Tr \BQ_j^{t_2} \BQ_j^{t_2, H} + \Ba_j^H \BQ_j^{t_2} \BQ_j^{t_2, H} \Ba_j \right]^{a_2} \leq K, \forall a_i,  t_j \in \{0, 1, 2\}, \label{Eq_Trace_bilinear_Q_sup_ab_bound}
\end{equation}
where $K$ is a constant independent of $n$. By utilizing these bounds, we can eliminate the polynomial in the denominator of \eqref{Eq_Part_II}. The details are omitted for simplicity.
\par
Since the probabilities of $\{|z\widetilde{q}_j| > 2K^o\}, \{|\eta_j| > 2K^o\}$, and $\{|1 + \alpha_{j, j}|^{-1} > 2K^o\}$ are less than any polynomial of $n^{-1}$ for $x \in [a, b]$ by Proposition \ref{Prop_bound_ab_K_o}, we may assume $|z\widetilde{q}_j|, |\eta_j|, |1 + \alpha_{j, j}|^{-1} \leq K^o$. We write $\BD_T = \diag(t_1, \ldots, t_n)$ and $-z\widetilde{\kappa}_j - (-z[\widetilde{\BR}]_{j,j}) = \sum_{i = 1}^5 X_{ij}$ as in \eqref{Eq_kappa_j_wR_jj}. Using $-z \widetilde{q}_j = \eta_j + z\widetilde{q}_j \eta_j \Delta_j$, we have 
\begin{align*}
  & \sum_{j=1}^n t_j X_{1j} = \sum_{j=1}^n t_j \E z\widetilde{q}_j \eta_j \Delta_j = \sum_{j=1}^n t_j \E (-\eta_j - z\widetilde{q}_j \eta_j \Delta_j) \eta_j \Delta_j  \\
  &= \sum_{j=1}^n -t_j \E  \eta_j^2 \Delta_j - t_j \E z\widetilde{q}_j\eta_j^2 \Delta_j^2 = \sum_{j=1}^n t_j \E z\widetilde{q}_j\eta_j^2  \Delta_j^2. \numberthis
\end{align*}
Therefore, we can obtain 
\begin{align*}
    & \sup_{x \in [a, b]}\abs{\sum_{j=1}^n t_j X_{1j} } \leq T\sup_{x \in [a, b]} \sum_{j=1}^n  \E \abs{z\widetilde{q}_j\eta_j^2  \Delta_j^2}  \lesssim \sup_{x \in [a, b]} \sum_{j=1}^n \E |\Delta_j|^2 \\
    & \lesssim \sup_{x \in [a, b]} \frac{1}{n}\sum_{j=1}^n \E \left[ \frac{1}{p} \Tr \BQ_j \BQ_j^H + \Ba_j^H\BQ_j\BQ_j^H\Ba_j \right] \overset{(a)}{\lesssim} 1, \numberthis \label{Eq_sup_ab_tX1j}
\end{align*}
where step $(a)$ follows from the same argument as in \eqref{Eq_I_j_TrQQ} and \eqref{Eq_E_j_ajQjQjaj}. Next, we evaluate $\sup_{x \in [a, b]}| \sum_{j} t_j X_{2j}|$. By using $\BQ = \BQ_j + z\widetilde{q}_j \BQ_j \Bxi_j \Bxi_j^H \BQ_j$, the following holds by the similar argument as in \eqref{Eq_sup_ab_tX1j}
\begin{align*}
  &\sup_{x \in [a, b]}\abs{ \sum_{j=1}^n t_j X_{2j}} = \sup_{x \in [a, b]}\abs{- \sum_{j=1}^n t_j \E\left( \frac{\eta_j \Ba_j^H\BQ_j\BOmega_j\BQ_j
  \Ba_j}{n (1 + \alpha_{j,j})^2} \right) + \sum_{j=1}^n t_j X_{2j, 3}} \\
  &\lesssim \sup_{x \in [a, b]}\abs{\sum_{j=1}^n \frac{1}{n}\E{ \Ba_j^H\BQ_j\BOmega_j\BQ_j
  \Ba_j}} + \sup_{x \in [a, b]}  \sum_{j=1}^n \E |\Delta_j| \abs{\Ba_j^H\BQ_j\Bxi_j\Bxi_j^H\BQ_j
  \Ba_j - \frac{1}{n}\Ba_j^H \BQ_j \BOmega_j \BQ_j \Ba_j - \Ba_j^H \BQ_j \Ba_j\Ba_j^H \BQ_j \Ba_j} \\
  &+ \sup_{x \in [a, b]} \sum_{j=1}^n \E |\Delta_j|  \left(\frac{1}{n}\Ba_j^H \BQ_j \BOmega_j \BQ_j \Ba_j + \Ba_j^H \BQ_j \Ba_j\Ba_j^H \BQ_j \Ba_j\right) \lesssim 1. \numberthis
\end{align*}
The evaluation for $\sup_{x \in [a, b]} |\sum_j t_j X_{3j}|$ is given by
\begin{align*}
  &\sup_{x \in [a, b]} \abs{\sum_{j=1}^n t_j X_{3j}} = \sup_{x \in [a, b]}\abs{\sum_{j=1}^n \E \frac{t_j (\frac{1}{n} \Tr \BQ_j - \frac{1}{n} \Tr \BQ)}{(1 + \alpha_{j,j})(1 + \kappa_j)}} \\
  &= \sup_{x \in [a, b]} \abs{\sum_{j=1}^n \frac{1}{n} \E \frac{-zt_j\widetilde{q}_j \Bxi_j^H\BQ_j^2\Bxi_j}{(1 + \alpha_{j,j})(1 + \kappa_j)}} \lesssim \sup_{x \in [a, b]} \abs{\sum_{j=1}^n \frac{1}{n} \E \Bxi_j^H \BQ_j \BQ_j^H \Bxi_j}  \lesssim 1. \numberthis \\
\end{align*}
By writing $\BD_{\kappa} = \diag(1 / (1 + \kappa_j); j \leq n)$ and using \eqref{Eq_EQ_R}, we have 
\begin{align*}
  \sup_{x \in [a, b]} \abs{ \sum_{j=1}^n t_j X_{4j} } = \sup_{x \in [a, b]} \abs{ \sum_{j=1}^n \frac{t_j \Ba_j^H (\BR - \E \BQ) \Ba_j}{(1 + \kappa_j)^2}} = \sup_{x \in [a, b]} \abs{ \Tr (\BR - \E \BQ)\BA \BD_T \BD_{\kappa}^2 \BA^H} \lesssim 1. \numberthis
\end{align*}
The evaluation of $\sup_{x \in [a, b]}|\sum_j t_j X_{5j}|$ is quite similar to that of $\sup_{x \in [a, b]}|\sum_j t_j X_{3j}|$  and is omitted here. Therefore, we have completed the proof. \qed
\par
Next, we give a more tight evaluation for \eqref{Eq_I_minus_z_Phi_delta} and \eqref{Eq_I_minus_J_delta_inv} with $x \in [a, b]$. By the integration representation of $\delta_j$, we have 
\begin{equation}
    \sup_{x \in [a, b]} v^{-1}\Im(\delta_j(z)) = \sup_{x \in [a, b]} \int_{\mathbb{R}^+} \frac{\mu_j(\dd \lambda)}{(x - \lambda)^2 + v^2} \leq \underline{\epsilon}^{-2} \mu_j(\R^+) \lesssim 1. \numberthis
\end{equation}
% and 
% \begin{equation}
%     \sup_{x \in [a, b]} v^{-1}\Im(z\delta_j(z)) = \sup_{x \in [a, b]} \int_{\mathbb{R}^+} \frac{\lambda \mu_j(\dd \lambda)}{(x - \lambda)^2 + v^2} \leq \underline{\epsilon}^{-2} \int \lambda_{\mathbb{R}^+} \mu_j (\dd \lambda) \overset{(a)}{\lesssim} 1,
% \end{equation}
% where step $(a)$ follows form the tightness of the measure $\mu_j$. The same conclusion also holds for $v^{-1}\Im(\widetilde{\delta}_j)$ and $v^{-1}\Im(z\widetilde{\delta}_j)$. By \eqref{Eq_I_minus_z_Phi_delta}, we have 
% \begin{equation}
%    \sup_{x \in [a, b]} \norm{(\BI_n - |z|^2 \BPhi_{\delta})^{-1}}_{\infty} \leq \sup_{x \in [a, b]}\frac{\max_j \Im(z \widetilde{\delta}_j)}{v|z|^2} \frac{1}{\inf_{x \in [a, b]}\min_j |\widetilde{\delta}_j|} \lesssim 1,
% \end{equation}
% since $\liminf_n \min_j |\widetilde{\delta}_j| \geq K > 0$ for $x \in [a, b]$ according to the assumption. 
We then show that $\inf_{x \in [a, b], j \leq n} [\Bv_{\delta}]_j$ is bounded away from 0. By the definition of $\BTheta(z)$, we have 
\begin{equation}
    \BI_p = -z \BTheta - \sum_{l=1}^n \frac{\BTheta\BOmega_l }{n} z \widetilde{\delta}_l - z\BTheta\BA\BF \BA^H . \label{Eq_Theta_I_Identity}
\end{equation}
Taking the norm $\norm{\cdot}_{\Omega, j} := \sqrt{\Tr(\cdot)^H \BOmega_j (\cdot)}$ at both sides of \eqref{Eq_Theta_I_Identity} and using $|\Tr\BC\BD| \leq \norm{\BC} \Tr \BD$ for Hermitian non-negative matrix $\BD$ yields
\begin{align*}
  \sqrt{\Tr \BOmega_j} &\leq  |z|^2 (\Tr \BTheta^H \BOmega_j \BTheta)^{1/2} + \sum_{l=1}^n \frac{|z \widetilde{\delta}_l|}{n} (\Tr \BOmega_l \BTheta^H \BOmega_j\BTheta \BOmega_l)^{1/2} \\
  &+ |z|^2( \Tr \BA\BF^H\BA^H \BTheta^H \BOmega_j \BTheta \BA \BF\BA^H )^{1/2} \\
  &\leq (\Tr \BTheta^H\BOmega_j\BTheta)^{1/2} \left[|z|^2 + \sum_{l=1}^n \frac{|z\widetilde{\delta}_l| \norm{\BOmega_l}}{n} + \frac{\norm{\BA}^2}{\min_{l \leq n} |1 + \delta_l|} \right]. \numberthis
\end{align*}
Since $\liminf_n \min_j |1 + \delta_j| > 0$ for $x \in [a, b]$, we have $\inf_{x \in [a, b]} \frac{1}{n} \Tr \BOmega_j\BTheta\BTheta^H \geq K > 0$ for some constant $K$ independent of $n$.  By \eqref{Eq_I_minus_J_delta_inv}, we get
\begin{equation}
    \sup_{x \in [a, b]} \norm{(\BI_n - \BJ_{\delta} )^{-1}}_{\infty} \leq \frac{\sup_{x \in [a, b]}\max_j(\delta_j)}{v} \frac{1}{\inf_{x \in [a, b]} \min_j[\Bv_{\delta}]_j} \lesssim 1.
\end{equation}
Similarly, we know the max-row norms $\| (\BI_n - \BJ_{\kappa})^{-1} \|_{\infty}$, $\| (\BI_n - |z|^2\BPsi_{\delta})^{-1} \|_{\infty}$, and $\| (\BI_n - |z|^2\BPsi_{\kappa})^{-1} \|_{\infty}$ are of order $O(1)$ uniformly for $x \in [a, b]$. Rewrite the matrices as $\BPsi_{\delta} = \BPsi_{\delta}(z, z^*)$ and  $\BPsi_{\kappa} = \BPsi_{\kappa}(z, z^*)$ with 
\begin{equation}
    [\BPsi_{\delta}(z, z^*)]_{j, l} = \frac{1}{n} [\widetilde{\BF}(z)\BA^H\BTheta(z)\BOmega\BTheta(z^*) \BA \widetilde{\BF}(z^*)]_{l, l}, ~~ [\BPsi_{\kappa}(z, z^*)]_{j, l} = \frac{1}{n} [\widetilde{\BG}(z^*)\BA^H\BR(z^*)\BOmega\BR(z) \BA \widetilde{\BG}(z)]_{l, l}.
\end{equation}
By swapping the roles of $z$ and $z^*$, we can similarly prove that
\begin{equation}
    \sup_{x \in [a, b]} \norm{(\BI_n - |z|^2\BPsi_{\delta}(z^*, z))^{-1}}_{\infty
    }, \sup_{x \in [a, b]}\norm{(\BI_n - |z|^2\BPsi_{\kappa}(z^*, z))^{-1}}_{\infty
    } \lesssim 1.
\end{equation}
As a result, there holds
\begin{equation}
    \sup_{x \in [a, b]} \norm{(\BI_n - |z|^2\BPhi_{\delta})^{-1}}_{1
    }, \sup_{x \in [a, b]}\norm{(\BI_n - |z|^2\BPhi_{\kappa})^{-1}}_{1
    } \lesssim 1,
\end{equation}
due to the identities $\BF(z) \BA \widetilde{\BTheta}(z) = \BTheta(z) \BA \widetilde{\BF}(z)$, $\BG(z) \BA \widetilde{\BR}(z) = \BR(z) \BA \widetilde{\BG}(z)$, and $\BPhi_{\delta} = [\BPsi_{\delta}(z^*, z)]^T$, $\BPhi_{\kappa} = [\BPsi_{\kappa}(z^*, z)]^T$.
\par
In the following, we give a tight bound on $\norm{\Bkappa - \Bdelta}_{\infty}$. To this end, the following estimation is needed 
\begin{equation}
    \sup_{x \in [a, b]}\max_{i, j \leq n} \abs{[\BGamma_{\kappa, \delta} (\BI_n - z^2 \BPhi_{\kappa, \delta})^{-1}]_{i, j}} \lesssim n^{-1}. \label{Eq_max_ij_Gamma_Phi}
\end{equation}
In fact, we have 
\begin{align*}
    &\max_{i, j \leq n} \abs{[\BGamma_{\kappa, \delta} (\BI_n - z^2 \BPhi_{\kappa, \delta})^{-1}]_{i, j}} \leq \max_{i, j \leq n} \abs{ \frac{1}{n^2}\Tr \BOmega_i \BR \BOmega_j \BTheta } \norm{(\BI_n - z^2 \BPhi_{\kappa, \delta})^{-1}}_1 \\
    &\overset{(a)}{\leq} \frac{p(\max_j\norm{\BOmega_{j}})^2}{n^2} \norm{\BR}\norm{\BTheta} \sqrt{\norm{(\BI_n - |z|^2 \BPhi_{\kappa})^{-1}}_1\norm{(\BI_n - |z|^2 \BPhi_{\delta})^{-1}}_1}, \numberthis
\end{align*}
where step $(a)$ follows from Lemma \ref{Lemm_matrix_Spr_maxrow_Norm}. Taking $\sup_{x \in [a, b]}$ on both sides of the above inequality, \eqref{Eq_max_ij_Gamma_Phi} holds.
Hence, by Proposition \ref{Prop_EQ_ER_EwQ_EwR}, we have 
\begin{align*}
    \sup_{x \in [a, b]}\norm{\BGamma_{\kappa, \delta}(\BI_n - z^2\BPhi_{\kappa, \delta})^{-1} \left(z \widetilde{\Bd}\right) }_{\infty} = \sup_{x \in [a, b]} \max_{i \leq n} \abs{\sum_{j = 1}^n [\BGamma_{\kappa, \delta}(\BI_n - z^2\BPhi_{\kappa, \delta})^{-1}]_{i, j}\left(z\widetilde{\kappa}_j - z[\widetilde{\BR}]_{j, j}\right)} \lesssim n^{-1}. \numberthis
\end{align*}
Again, by Lemma \ref{Lemm_matrix_Spr_maxrow_Norm} and Proposition \ref{Prop_EQ_ER_EwQ_EwR}, we can obtain
\begin{align*}
    \sup_{x \in [a, b]}\norm{\Bkappa - \Bdelta}_{\infty} &= \sup_{x \in [a, b]}\norm{(\BI_n - \BJ_{\kappa, \delta})^{-1} \left[\Bd + \BGamma_{\kappa, \delta}(\BI_n - z^2\BPhi_{\kappa, \delta})^{-1} \left(z \widetilde{\Bd}\right) \right]}_{\infty}. \\
    &\leq \sup_{x \in [a, b]}\norm{(\BI_n - \BJ_{\kappa, \delta})^{-1}}_{\infty} \norm{\Bd}_{\infty} + \norm{(\BI_n - \BJ_{\kappa, \delta})^{-1}}_{\infty} \norm{\BGamma_{\kappa, \delta}(\BI_n - z^2\BPhi_{\kappa, \delta})^{-1} \left(z \widetilde{\Bd}\right) }_{\infty} \\
    & \lesssim \sup_{x \in [a, b]}\sqrt{\norm{(\BI_n - \BJ_{ \delta})^{-1}}_{\infty}\norm{(\BI_n - \BJ_{\kappa})^{-1}}_{\infty}} n^{-1} \lesssim \frac{1}{n}. \numberthis
\end{align*}
By \eqref{Eq_Bound_on_Diff_wkappa_wdelta} and the above estimation, we have $\sup_{x \in [a, b]}|\sum_{j=1}^n t_j (\widetilde{\kappa}_j - \widetilde{\delta}_j)| \lesssim 1$ with $\sup_{x \in [a, b], j \leq n} |t_j|$ uniformly bounded in $n$. By the resolvent identity, we have 
\begin{align}
   \Tr \BR - \Tr \BTheta = \sum_{j=1}^n \frac{\Tr \BR \BOmega_j \BTheta}{n}(z\widetilde{\kappa}_j - z\widetilde{\delta}_j) + \sum_{j=1}^n z^2 [\widetilde{\BF} \BA^H\BTheta \BR\BA \widetilde{\BG}]_{j, j}(\kappa_j - \delta_j).
\end{align}
Denoting $\frac{1}{n} \Tr \BR \BOmega_j \BTheta = t_j$, we have $\sup_{x \in [a, b]}\sup_j |zt_j| \lesssim 1$ and  
\begin{equation}
    \sup_{x \in [a, b]}\abs{\Tr (\BR - \BTheta)} \leq \sup_{x\in [a, b]} \abs{\sum_{j}t_j(\widetilde{\kappa}_j - \widetilde{\delta}_j)} +  \sup_{x \in [a, b]} \sup_{j \leq n} \frac{n \norm{\BA}^2 \norm{\BTheta} \norm{\BR}}{|1 + \delta_j||1 + \kappa_j|} \norm{\Bkappa - \Bdelta}_{\infty} \lesssim 1.
\end{equation}
By Proposition \ref{Prop_EQ_ER_EwQ_EwR} and the above inequality, \eqref{Eq_Mean_Part} holds. Therefore, we have completed the proof of 
\eqref{Eq_sup_diff_resolvent} \qed
\section{Proof of Corrolary \ref{Coro_min_eig_zero_forcing}}
\label{App_prof_of_coro_min_eig_zero_forcing}

The crucial step of the proof is to show that the boundedness of the terms listed in Proposition \ref{Prop_bound_ab_K_o} holds when $x = 0$. To that end, we need Theorem 1 from \cite{AblaNoEigen}, which we list below as a proposition. 
\begin{proposition}(\cite[Theorem 1]{AblaNoEigen})
\label{Prop_abla_noeigen}
    Assume the following holds
    \begin{itemize}
    \item [1)]  $0 < \liminf_n p / n \leq  \limsup_n p / n < 1$. 
    \item [2)] $ 0 < \liminf_n \min_j \lambda_{\min}(\BOmega_j) \leq \limsup_n \max_j \norm{\BOmega_j} < \infty$.
    \end{itemize}
    Then, there exists $\epsilon > 0$ suth that 
    \begin{equation}
        [0, \epsilon] \cap \mathsf{Supp}(F^n) = \emptyset
    \end{equation}
    for all large $n$.
\end{proposition}
\textit{Proof:} Following the same argument as in Proposition \ref{Prop_bound_ab_K_o}, it suffices to show that the following holds for $z = x+ \jmath v$, $v \to 0$ as $n \to \infty$
\begin{equation}
    \sup_{x \in [0, \epsilon']} \max_{j \leq n} \left\{ |z\widetilde{\delta}_j(z)|, |\delta_j(z)|, \frac{1}{|1 + \delta_j(z)|} \right\} \leq K, \label{ER_bounde_0e_qterms}
\end{equation}
for some $\epsilon' > 0$. Here, we choose $\epsilon' = \epsilon / 2$. By Proposition \ref{Prop_abla_noeigen} and the matrix valued integration representation \eqref{Eq_representation_Theta}, we can obtain that $[0, \epsilon]$ is outside the support of $F^n = \frac{1}{p} \Tr \Bmu$ and $[\Bmu]_{i, i}([0, \epsilon]) = 0$, for $i = 1, \ldots, p$. Since $\Bmu([0, \epsilon])$ is non-negative definite, $\Bmu([0, \epsilon]) = \Bzero_{p \times p}$ must holds, which implies $[0, \epsilon]$ is outside the support of the measures $\{\mu_j\}_{j \leq n}$. In particular, $\epsilon$ is less than or equal to the left endpoint of $\cup_j \mathsf{Supp}(\mu_j)$, which implies 
\begin{equation}
    \sup_{x \in [0, \epsilon']} |\delta_j(z)| \leq \int_{\R^+} \frac{\mu_j(\dd \lambda)}{|\lambda - z|} \leq \frac{2\Tr \BOmega_j}{n \epsilon},
\end{equation}
and 
\begin{equation}
    \inf_{x \in [0, \epsilon']} \delta_j(x) = \int_{\R^+} \frac{\mu_j(\dd \lambda)}{\lambda - x} \geq 0.
\end{equation}
Hence, for large $n$, it holds that 
\begin{equation}
    \frac{1}{|1 + \delta_j(z)|} \leq \frac{1}{|1 + \delta_j(x)| - |\delta_j(z) - \delta_j(x)|} \leq \frac{1}{1 - v \frac{4 \Tr \BOmega_j}{\epsilon^2n}} \leq 1 / 2.
\end{equation}
\par
Since $\BTheta(z)$ admits the representation $\int_{\R^+} \frac{\Bmu(\dd \lambda)}{\lambda - z}$ and $\Bmu([0, \epsilon]) = 0$, by the same argument as in \eqref{Eq_sup_ab_norm_Theta}, we have 
\begin{equation}
    \sup_{x \in [0, \epsilon']} \norm{\BTheta(z)} \leq \sup_{x \in [0, \epsilon']} \norm{\int_{\R^+} \frac{\Bmu(\dd \lambda)}{|\lambda - z|}} \leq \frac{2}{\epsilon}.
\end{equation}
Therefor, by the identity in \eqref{Eq_Res_identity_wdeltaj}, we can obtain
\begin{equation}
    \abs{z\widetilde{\delta}(z)} \leq \frac{1}{|1 + \delta_j(z)|} + \frac{\norm{\Ba_j}^2 \norm{\BTheta(z)}}{|1 + \delta_j(z)|^2},
\end{equation}
which is also uniformly upper bounded for $x \in [0, \epsilon']$.
\par
Hence, we have proved \eqref{ER_bounde_0e_qterms}. To prove that there are no eigenvalues of $\BS$ in the interval $[0, \epsilon']$, we only need to follow the same logic as in Appendix \ref{App_Proof_Thm_noeigen} by replacing the interval $[a, b]$ with $[0, \epsilon']$, and $[a', b']$ with $[- \epsilon'/2, 3\epsilon'/2]$. \qed




