\subsubsection{Logistic cell size growth rate}
When cell sizes follow a logistic growth pattern, the growth rate is given by
\begin{equation}
\label{eq:lograte}
v(s) = v_1 s(1-\frac{s}{v_0}),
\end{equation}
where $v_1 > 0$, and $v_0 > 1$ represents the cell size capacity. Using this growth rate, we derive the following expressions:
\begin{eqnarray*}
u(s, a) &=& \log \dfrac{s}{v_0 - s} - a v_1,\\
w(\varphi_2, a) &=& \dfrac{v_0 e^{\varphi_2 + a v_1}}{1 + e^{\varphi_2 + a v_1}},\\
\gamma_0(s, a) &=& \dfrac{s e^{-a v_1}}{1 - \frac{s}{v_0}(1 - e^{- a v_1})},\\
\gamma_{a-t}(s, a) &=& \dfrac{s e^{-t v_1}}{1 - \frac{s}{v_0}(1 - e^{-t v_1})},\\
\psi(a; \varphi_1, \varphi_2) &=& \alpha (a + \varphi_1) + v_1 \dfrac{1 - e^{\varphi_2 + a v_1}}{1 + e^{\varphi_2 + a v_1}},\\
\psi(a'; t-a, u(s, a)) &=& \alpha (a' + t - a) + v_1 (1 - \frac{2s}{v_0}),\\
\psi(a - t'; t-a, u(s, a)) &=& \alpha(t - t') + v_1 (1 - \frac{2s}{v_0}).
\end{eqnarray*}
Thus, using these expressions, the solution of the governing equation from \eqref{eq:schara} is given by:  
\begin{equation}
f(s, a, t) = 
\begin{cases}
2 p(\gamma_0(s, a)) \alpha(t - a) e^{-\int_{t-a}^t  (\alpha (t') + v_1 (1 - \frac{2s}{v_0})) \mathrm{d} t'}
& a < t,0<s \leq 1 \vspace{1mm}\\
g(\gamma_{a-t}(s, a), a-t) e^{-\int_0^t (\alpha(t') + v_1 (1 - \frac{2s}{v_0}))\mathrm{d} t'} &a \geq t, 0< s\leq 1\vspace{1mm}\\
0&\text{otherwise}.
\end{cases}
\end{equation}
Here, the population growth rate $\alpha(t)$ is defined as:
$$
\alpha(t) = \int_0^{+\infty} v(1) f(1, a, t) \mathrm{d} a.
$$

Let $t\to+\infty$, and consider the steady-state distribution:
\begin{equation}
\label{eq:s61}
\hat{f}(s, a) = 2\alpha e^{-(\alpha + v_1 (1 - \frac{2 s}{v_0}))a}p(\gamma_0(s, a)),\quad (0\leq s \leq 1, a \geq 0)
\end{equation} 
where the population growth rate is given by:
\begin{equation}
\label{eq:s62}
\alpha = v(1) \int_0^{+\infty} \hat{f}(1, a)\mathrm{d} a.
\end{equation}

To facilitate further analysis, we introduce the function $K_1(\alpha, s, u)$:
\begin{equation}
K_1(\alpha, s, u) = \left(\frac{u}{s}\right)^{(\frac{\alpha}{v_1} - \frac{2 s}{v_0})}  \left(\frac{1 - u/v_0}{1 - s/v_0}\right)^{-(\frac{\alpha}{v_1} + 2 (1 - \frac{s}{v_0}))}.
\end{equation}

Substituting \eqref{eq:s61} into \eqref{eq:s62}, we obtain:
$$
\alpha = 2 \alpha v(1)\int_0^{+\infty} e^{-(\alpha + v_1 (1 - \frac{2}{v_0}))a}p(\gamma_0(1, a)) \mathrm{d} a. 
$$
Letting $u = \gamma_0(1, a)$ and applying the function $K_1(\alpha, s, u)$, the population growth rate $\alpha$ satisfies the implicit equation:
\begin{equation}
\label{eq:s63}
1 = 2 \int_0^1 K_1(\alpha, 1, u) p(u) \mathrm{d} u.
\end{equation}

Thus, the growth rate $\alpha$ is determined by solving \eqref{eq:s63}. Once $\alpha$ is known, the steady-state distribution is given by \eqref{eq:s61}. 

Next, we compute the marginal steady-state distribution $\tilde{f}(s)$ by integrating \eqref{eq:s61} over $a$:
$$
\tilde{f}(s) = 2\alpha \int_0^{+\infty} e^{-(\alpha  + v_1 (1 - \frac{2 s}{v_0}))a} p(\gamma_0(s, a)) \mathrm{d} a.
$$
After simplifying, the steady-state distribution becomes:
\begin{equation}
\tilde{f}(s) = \dfrac{2\alpha}{v(s)}\int_0^s K_1(\alpha, s, u) p(u) \mathrm{d} u.
\end{equation}
where $v(s) = v_1 s (1 - s/v_0)$ is the logistic growth rate.

In summary, we present the following theorem for the case where cell sizes follow logistic growth.
\begin{theorem}
Consider the sizer mechanisms described by \eqref{eq:size3}. When the cell growth rate is $v(s)= v_1 (1 - s/v_0)$, where $v_1 > 0$ and $v_0 > 1$, the following conclusions hold:
\begin{enumerate}
\item[\rm{(1)}] The cell size distribution $f(s, a,t )$ is expressed as:
\begin{equation}
f(s, a, t) = 
\begin{cases}
2 p(\gamma_0(s, a)) \alpha(t - a) e^{-\int_0^a \psi(a; t-a, u(s, a)) \mathrm{d} a'}
& a < t,0<s\leq 1 \vspace{1mm}\\
g(\gamma_{a-t}(s, a), a-t) e^{-\int_0^t \psi(a - t'; t - a, u(s, a))\mathrm{d} t'} &a \geq t, 0< s\leq 1\\
0&\text{otherwise}.
\end{cases}
\end{equation}
where
$$
\alpha(t) = \int_0^{+\infty} v(1) f(1, a, t) \mathrm{d} a.
$$
\item[\rm{(2)}] The steady-state solution $\hat{f}(s, a)$ is given by
\begin{equation}
\hat{f}(s, a) = 2\alpha e^{-(\alpha + v_1 (1 - \frac{2 s}{v_0}))a}p(\gamma_0(s, a)),\quad (0\leq s \leq 1, a \geq 0).
\end{equation} 
Define the function $K_1(\alpha, s, u)$ as:
\begin{equation}
K_1(\alpha, s, u) = \left(\frac{u}{s}\right)^{(\frac{\alpha}{v_1} - \frac{2 s}{v_0})}  \left(\frac{1 - u/v_0}{1 - s/v_0}\right)^{-(\frac{\alpha}{v_1} + 2 (1 - \frac{s}{v_0}))}.
\end{equation}
The population growth rate $\alpha$ is determined by the implicit equation:
\begin{equation}
1 = 2 \int_0^1 K_1(\alpha, 1, u) p(u) \mathrm{d} u.
\end{equation}
\item[\rm{(3)}] The steady-state size distribution $\tilde{f}(s)$ is expressed as:
\begin{equation}
\tilde{f}(s) = \dfrac{2\alpha}{s v(s)}\int_0^s K_1(\alpha, s, u) p(u) \mathrm{d} u.
\end{equation}
\end{enumerate} 
\end{theorem}

Fig. \ref{fig:4} illustrates the steady-state size distributions obtained from stochastic simulations. The results reveal a size distribution shape resembling that of linear growth: the frequency increases from $s =0.4$ to $s = 0.6$, then decreases toward the division size. Additionally, varying $v_1$ (Fig. \ref{fig:4}a) or $v_0$ (Fig. \ref{fig:4}b) alone does not significantly alter the overall shape of the distribution, while changes in both $v_0$ and $v_1$ may affect the size distribution (Fig. \ref{fig:4}c).

