\section*{Supplementary Material}

Here we provide details to the results of the main text. 

\begin{lemma}\label{lem:sharing}
Consider a copy system $C$, flag systems $R_{\mathbf{x}}$ and $R_{\mathbf{y}_i}$ with flag spins $f_{\mathbf{x}}$ and $f_{\mathbf{y}_i}$
and fields on flag spins equal to $2\mathrm{d}(\mathbf{x},\mathbf{0})+1$ and $2\mathrm{d}(\mathbf{y}_i,\mathbf{0})+1$, and an interaction $E$ between the two flag spins with coupling equal to $-3$.
Let $\lambda_i\leq 1$ and define 
\begin{equation}
    S_{\mathbf{y}_i,\mathbf{x}} = 2C + \bigl(2\mathrm{d}(\mathbf{y}_i,\mathbf{x})-\lambda_i\bigr) (R_{\mathbf{y}_i}+R_{\mathbf{x}}+E).
\end{equation}
Then, for arbitrary $a_i,b_i$ and $\Delta$, there exists $\delta_i\geq 0$ and $\lambda_i \leq 1$ such that 
$\delta_i S_{\mathbf{y}_i,\mathbf{x}}$ simulates  \cref{eq:sharing Ham}, i.e.\ yields a sharing system.
\end{lemma}
\begin{proof}
By definition
\begin{widetext}
    \begin{equation}\label{eq:sharing spin system}
    H_{\delta_iS_{\mathbf{y}_i,\mathbf{x}}}(\mathbf{v},\mathbf{h},f_{\mathbf{x}},f_{\mathbf{y}_i}) = 
    \begin{cases}
        \delta_i\lambda_i \ &\text{if} \ \mathbf{v} = \mathbf{y}_i \ \text{and} \ \mathbf{h}=\mathbf{x} \ \text{and} \  f_{\mathbf{x}}=f_{\mathbf{y}_i}=1 \\
        0 \ &\text{if} \ \mathbf{v}=\mathbf{h} \ \text{and} \ f_{\mathbf{x}}=f_{\mathbf{y}_i}=0 \\
        \geq \delta_i \ &\text{else}.
    \end{cases}
\end{equation}
\end{widetext}

We now choose 
$\delta_i = \Delta -b_i$ and $\lambda_i = \tfrac{a_i-b_i}{\Delta - b_i}$.
Without loss of generality we assume that $\Delta$ is large enough such that $\delta_i\geq 0$ and $\lambda_i \leq 1$.
Inserting this into \cref{eq:sharing spin system} proves that $\delta_i S_{\mathbf{y}_i,\mathbf{x}}$ simulates \cref{eq:sharing Ham} with shift $b_i$ and cut-off $\Delta$.
\end{proof}

\begin{lemma}\label{lem:sim approx density}
    Let $S\to T$ with cut-off $\Delta \geq  \max(H_T)$, 
     then for any target configuration $\mathbf{t}$
    \begin{equation}
        p_{V_T}[S](\mathbf{t}) = p[T](\mathbf{t}) + \mc{O}(e^{-\Delta}).\label{eq:probdistr-error}
    \end{equation}
\end{lemma}
\begin{proof}
    Since energy shifts do not change Boltzmann distributions, without loss of generality we assume that the shift between $S$ and $T$ is zero. 
Since $S$ simulates $T$ with cut-off $\Delta\geq \max(H_T)$, for each target configuration $\mathbf{t}$ there exists a unique source configuration $(\mathbf{t},\mathbf{h}_{\mathbf{t}})$ with matching energy. Thus,
\begin{equation}\label{eq:split part fun}
        Z_S = \sum_{\mathbf{t}, \mathbf{h}}e^{-H_S(\mathbf{t},\mathbf{h})} = \sum_{\mathbf{t}}e^{-H_T(\mathbf{t})} + \sum_{(\mathbf{t},\mathbf{h}), \mathbf{h}\neq \mathbf{h}_{\mathbf{t}}}e^{-H_S(\mathbf{t},\mathbf{h})}.
\end{equation}
The first term equals $Z_T$ while the second is upper bounded by $e^{-\Delta}$, 
\begin{equation}
    Z_S = Z_T + \mathcal{O}(e^{-\Delta}).
\end{equation}
Next, we split the sum involved in the definition of the marginal $p_{V_T}[S](\mathbf{t})$ into $(\mathbf{t},\mathbf{h}_{\mathbf{t}})$ and configurations with $\mathbf{h}\neq \mathbf{h}_{\mathbf{t}}$, yielding
\begin{equation}
p_{V_T}[S](\mathbf{t}) = \frac{1}{Z_S} \Bigl( e^{-H_T(\mathbf{t})}+ \mathcal{O}(e^{-\Delta})  \Bigr).
\end{equation}
This results in \eqref{eq:probdistr-error}.
\end{proof}

\begin{lemma}\label{lem:sim prob canonical}
    Let $p$ be any probability distribution on $\{0,1\}^V$ and $T$ be a spin system with Hamiltonian
    \begin{equation}\label{eq:ham prob 2}
        H_T(\mathbf{t}) = \begin{cases}
            -\log(p(\mathbf{t})) 
            & \text{if } p(\mathbf{t})>0 \\
            \Delta             & \text{if }  p(\mathbf{t})=0 .
        \end{cases}
\end{equation}
Then $T$ simulates $p$ with cut-off $\Delta$, i.e.\ for any configuration $\mathbf{t}$,
\begin{equation}
    p[T](\mathbf{t}) = p(\mathbf{t}) + \mathcal{O}(e^{-\Delta}).
\end{equation}
\end{lemma}
\begin{proof}
First, we express the partition function of $T$ as   
\begin{equation}
\begin{split}
    Z_T & 
    = \sum_{\mathbf{t},  p(\mathbf{t})>0} p(\mathbf{t}) + \sum_{\mathbf{t},  p(\mathbf{t})=0}e^{-\Delta} \\
    &= 1 + \mathcal{O}(e^{-\Delta}),
\end{split}
\end{equation}
where the first equality follows by the definition of $H_T$ and the second from the normalization of $p$.
Inserting it in the definition of the Boltzmann distribution of $T$, $p[T]$, proves the claim.
\end{proof}


\begin{lemma}\label{lem:DBN DBM 2}
    Let $S=R_0+R_1$ such that the top-level marginal of $R_0$ is approximately spiked. 
    Then there exists 
    a spin system $S'=R_0+R_1'$ such that 
    \begin{equation}\label{eq:claim DBN DBM}
         q_{V_0}[S'](\mathbf{h}_0) = p_{V_0}[S](\mathbf{h}_0)  + \mathcal{O}(e^{-\Delta}).
    \end{equation}
\end{lemma}
\begin{proof}
By assumption the top-level marginal of $R_0$ satisfies \cref{eq:top level marg assumption} for some configuration $\mathbf{x}$ and real numbers $a,b$, up to $\mathcal{O}(e^{-\Delta})$.
We construct $R_1'$ by changing couplings of $R_1$ such that below $\Delta$ 
\begin{equation}\label{eq:change top RBM}
        H_{R_1'}(\mathbf{h}_1,\mathbf{h}_2) = 
        \begin{cases}
            H_{R_1}(\mathbf{h}_1,\mathbf{h}_2)- c \ &\text{if} \ \mathbf{h}_1 = \mathbf{x} \\ 
             H_{R_1}(\mathbf{h}_1,\mathbf{h}_2) \ &\text{else}.
        \end{cases}
\end{equation}
We now prove that an appropriate choice of $c$ (see \cref{eq:choice f}) leads to 
\begin{equation}\label{eq:what to prove}
        p_{V_1}[R_1'](\mathbf{h}_1) = (p_{V_1}[R_0]\ast p_{V_1}[R_1])(\mathbf{h}_1) + \mathcal{O}(e^{-\Delta}).
\end{equation}
This proves the claim via \cref{eq:2 DBN} and \cref{eq:2 DBM}.

First, by definition of $R_1'$, up to $\mathcal{O}(e^{-\Delta})$, 
    \begin{equation}\label{eq:change top level}
        p_{V_1}[R_1'](\mathbf{h}_1) = \begin{cases}
           d  p_{V_1}[R_1](\mathbf{h}_1) \ & \text{if} \ \mathbf{h}_1=\mathbf{x} \\ 
            d' p_{V_1}[R_1](\mathbf{h}_1)   \ & \text {else}
    \end{cases}
\end{equation}
where 
$d=\tfrac{Z}{Z'}e^c$ and $d'=\tfrac{Z}{Z'}$, with $Z$ and $Z'$ the partition functions of $R_1$ and $R_1'$ respectively. 
We obtain
\begin{equation}
    Z' = Z + (e^c-1) Z p_{V_1}[R_1](\mathbf{x}).
\end{equation}

Crucially, as long as
\begin{equation}
    0\leq d p_{V_1}[R_1](\mathbf{x})<1,
\end{equation}
any value of $d$ can be achieved by an appropriate choice of $c$, namely 
\begin{equation}
    c = \log \left( \frac{d-dp_{V_1}[R_1](\mathbf{x})}{1-dp_{V_1}[R_1](\mathbf{x})}\right).
\end{equation}
We choose $c$ such that 
\begin{equation}\label{eq:choice f}
    d = \frac{a}{b(1-p_{V_1}[R_1](\mathbf{x}))+a p_{V_1}[R_1](\mathbf{x})}.
\end{equation}

We first rewrite the normalization constant of $p_{V_1}[R_0]\ast p_{V_1}[R_1]$ as 
\begin{equation}
\begin{split}
        N &= \sum_{\mathbf{h}_1}p_{V_1}[R_0](\mathbf{h}_1) p_{V_1}[R_1](\mathbf{h}_1) \\
        &= b\sum_{\mathbf{h}_1\neq \mathbf{x}} p_{V_1}[R_1](\mathbf{h}_1) + a p_{V_1}[R_1](\mathbf{x}) + \mathcal{O}(e^{-\Delta}) \\
        &= \frac{a}{d} + \mathcal{O}(e^{-\Delta}),
\end{split}
\end{equation}
where the second equality holds since the top-level marginal of $R_0$ is approximately spiked, and the third because  $p_{V_1}[R_1]$ is normalized.
It follows that 
\begin{equation}
    (p_{V_1}[R_0]\ast p_{V_1}[R_1])(\mathbf{x}) = d p_{V_1}[R_1](\mathbf{x}) + \mathcal{O}(e^{-\Delta})
\end{equation}
which proves \cref{eq:what to prove} for the case $\mathbf{h}_1=\mathbf{x}$.

Finally, normalization of $p_{V_1}[R_1']$ implies
\begin{equation}
    1 = d p_{V_1}[R_1](\mathbf{x}) + d'\sum_{\mathbf{h}_1 \neq \mathbf{x}}p_{V_1}[R_1](\mathbf{h}_1).
\end{equation}
Normalization of $p_{V_1}[R_0]\ast p_{V_1}[R_1]$ yields 
\begin{equation}
    1 = d p_{V_1}[R_1](\mathbf{x}) + \frac{d}{a} b \sum_{\mathbf{h}_1 \neq \mathbf{x}}p_{V_1}[R_1](\mathbf{h}_1) + \mathcal{O}(e^{-\Delta}).
\end{equation}
Thus, up to $\mathcal{O}(e^{-\Delta})$, 
$d'=\frac{d}{a}b$. This proves \cref{eq:what to prove} for the case $\mathbf{h}_1\neq\mathbf{x}$.
\end{proof}

