As an application of the above results, we can also deduce a useful result concerning the property of stability.
A semigroup $S$ is said to be \emph{stable} if 
\begin{equation}\label{eq:stable}
a \J ab \iff a\R ab \AND a\J ba \iff a\L ba \qquad\text{for all $a,b\in S$.}
\end{equation}
Stable semigroups have many important and useful properties, as explained in \cite{EH2020}.  It is known that all finite semigroups are stable, and that ${\D}={\J}$ in any stable semigroup; see for example \cite[Section A.2]{RS2009}.  Any commutative semigroup is stable because for such a semigroup we have ${\J}={\R}={\L}$.

\begin{prop}\label{prop:stability}
A tight twisted product $T = M\times_\Phi^qS$ is stable if and only if $S$ is stable.
\end{prop}

\pf
Throughout the proof we use Theorem \ref{thm:GR} extensively, without explicit mention.  
%
Suppose first that $S$ is stable.  To demonstrate stability of $T$, it suffices by symmetry to establish the first equivalence in \eqref{eq:stable}, and since ${\R}\sub{\J}$, only the forward implication is required.  So suppose
\[
(i,a) \J^T (i,a)(j,b) = (i+j+\Phi(a,b)q,ab) \qquad\text{for some $i,j\in M$ and $a,b\in S$.}
\]
We then have $i\J^Mi+j+\Phi(a,b)q$ and $a\J^Sab$.  But $M$ and $S$ are both stable (by assumption for $S$, and by commutativity for $M$), so it follows that $i\R^Mi+j+\Phi(a,b)q$ and $a\R^Sab$.  But this then gives
\[
(i,a) \R^T (i+j+\Phi(a,b)q,ab) = (i,a)(j,b).
\]

Conversely, suppose $T$ is stable.  Again aiming to prove the forward implication in the first equivalence in \eqref{eq:stable}, suppose $a\J^Sab$ for some $a,b\in S$.  By \ref{T2}\ref{T2b}, we can assume that~${\Phi(a,b)=0}$.  We then have
\[
(0,a) \J^T (0,ab) = (0,a)(0,b),
\]
so it follows from stability of $T$ that $(0,a) \R^T (0,a)(0,b) = (0,ab)$, and hence that $a\R^Sab$.
\epf

In \cite[Corollary 3]{KV2023} it is proved that the twisted Brauer monoid $\Z\times_\Phi^1\B_n$ is stable when $\Phi$ is the canonical twisting.  This also follows from Proposition \ref{prop:stability} because~$\B_n$ is finite and hence stable.






\section{Idempotents, Sch\"utzenberger groups and biordered sets}\label{sect:ET}


We continue to fix a tight twisted product $T = M\times_\Phi^qS$, where $M$, $S$, $\Phi$ and $q$ have their usual meanings.
%
In this section we describe the set $E(T)$ of idempotents of $T$ (Section \ref{subsect:E}), and its structure as a biordered set (Section \ref{subsect:ET}).  
%
In between, we show how the Sch\"utzenberger groups of $T$ are related to those of $M$ and $S$ (Section \ref{subsect:Ga}).


\subsection{The idempotents}\label{subsect:E}


Before we look at the idempotents of the tight twisted product $T=M\times_\Phi^qS$ directly, it is convenient to describe the group $\H^T$-classes.  We begin with a technical lemma concerning the additive monoid $(M,+)$, whose simple proof is omitted; for similar results see \cite[Section~I.4]{Grillet2001}.

\begin{lemma}\label{lem:Hk}
If $H$ is a group $\H^M$-class of $M$, and if $k\in M$, then the following are equivalent:
\ben
\item \label{Hki} $H = H+k$,
\item \label{Hkii} $i\leqJ^M k$ for some $i\in H$,
\item \label{Hkiii} $i\leqJ^M k$ for all $i\in H$.  \epfres
\een
\end{lemma}



If $H$ is an $\H^S$-class (of $S$), then it quickly follows from \ref{T3} and \ref{T4} that $\Phi(a,b) = \Phi(c,d)$ for all $a,b,c,d\in H$.  We write $\Phi(H)$ for this common value (so $\Phi(H) = \Phi(a,b)$ for any $a,b\in H$).

In the following proof, we will make use of the fact that an $\H$-class $H$ of a semigroup is a group if and only if $xy\in H$ for some $x,y\in H$; see for example \cite[Theorem 2.2.5]{Howie1995}.


\begin{thm}\label{thm:H}
Let $T = M\times_\Phi^qS$ be a tight twisted product.  If $H$ is an $\H^M$-class, and $H'$ an $\H^S$-class, then the following are equivalent:
\ben
\item \label{Hi} the $\H^T$-class $H\times H'$ is a group,
\item \label{Hii} $H$ and $H'$ are groups, and $H=H+\Phi(H')q$,
\item \label{Hiii} $H$ and $H'$ are groups, and $i\leqJ^M\Phi(H')q$ for some (equivalently all) $i\in H$,
\item \label{Hiv} $H$ and $H'$ are groups, and either $\Phi(H')=0$ or else $i\leqJ^Mq$ for some (equivalently all)~${i\in H}$.
\een
When the above conditions hold, the group $\H^T$-class $H\times H'$ is isomorphic to the direct product $(H,+)\times(H',\cdot)$.
\end{thm}

\pf
\firstpfitem{\ref{Hi}$\implies$\ref{Hiii}}  Suppose $H\times H'$ is a group, say with identity $(i,a)$.  Since
\[
(i,a) = (i,a)^2 = (2i+\Phi(a,a)q,a^2),
\]
it follows that $a=a^2$ and $i = 2i+\Phi(a,a)q = 2i+\Phi(H')q$.  The former tells us that $H_a^S = H'$ is a group.  The latter tells us that $i \leqJ^M\Phi(H')q$, and also that $i\R^M2i$.  Since ${\R^M}={\H^M}$, this gives $i\H^M2i$, which implies that $H_i^M=H$ is a group (as mentioned before the proof).

\pfitem{\ref{Hiii}$\implies$\ref{Hii}}  This follows from Lemma \ref{lem:Hk}.

\pfitem{\ref{Hii}$\implies$\ref{Hi}}  
Suppose $H$ and $H'$ are groups, with $H=H+\Phi(H')q$.  Let the identities of these groups be $i\in H$ and $e\in H'$, and let $p\in H$ be such that $i = p + \Phi(H')q = p + \Phi(e,e)q$.  Since $i$ is the identity of $H$, we have
\[
(p,e)(p,e) = (2p+\Phi(e,e)q,e^2) = (p+i,e) = (p,e),
\]
and hence $(p,e)\in H\times H'$ is an idempotent.

\pfitem{\ref{Hiii}$\implies $\ref{Hiv}}  This is clear.

\pfitem{\ref{Hiv}$\implies $\ref{Hiii}}
We only need to check that $i\leqJ^M \Phi(H')q$. If $\Phi(H')=0$ this is obvious.
When $\Phi(H')\neq 0$ we have $\Phi(H')i\H^M i$ because $H$ is a group, and hence
$i\leqJ^M \Phi(H')i\leqJ^M\Phi(H')q$, as requied.


\aftercases For the final assertion, suppose $H\times H'$ is a group.  Let~$i$ and $e$ be the identities of the groups~$H$ and $H'$, respectively, and write $m = \Phi(H')$, so that
\[
i \leqJ^M mq
\COMMA
H = H+mq
\AND
\Phi(a,b) = m \text{ for all $a,b\in H'$.}
\]
Also let $t = i + mq$; since $H=H+mq$ we have $t\in H$.  For any $j,k\in H$ and $a,b\in H'$ we have
\[
(j,a)(k,b) = (j+k+\Phi(a,b)q,ab) = (j+k+i+mq,ab) = (j+t+k,ab).
\]
It follows that the $\H^T$-class $H\times H'$ is isomorphic to the direct product $(H,\oplus)\times(H',\cdot)$, where~$\oplus$ is the \emph{variant} operation \cite{Hickey1983} given by $j\oplus k = j+t+k$.  Since the map $j\mt j+t$ is easily seen to be an isomorphism $(H,\oplus) \to (H,+)$, the proof is complete.
\epf


We now define the set 
\begin{equation}\label{eq:Lam}
\begin{split}
 \Om &= \bigset{(i,e)\in E(M)\times E(S)}{H_i^M\times H_e^S \text{ is a group}} \\
 &= \bigset{(i,e)\in E(M)\times E(S)}{i \leqJ^M\Phi(e,e)q},
\end{split}
\end{equation}
where the second equality follows from Theorem \ref{thm:H}.  For $(i,e)\in\Om$, we write $\ve(i,e)$ for the unique idempotent in $H_i^M\times H_e^S$, which is of course the identity element of this group $\H^T$-class.  The next result follows from Theorem \ref{thm:H} and its proof.

\begin{prop}\label{prop:ET}
We have $E(T) = E(M\times_\Phi^qS) = \set{\ve(i,e)}{(i,e)\in\Om}$, where $\Om$ is as in \eqref{eq:Lam}.  For any $(i,e)\in\Om$, we have
\[
\ve(i,e) = (p,e), \WHERE p = p(i,e) \in H_i^M\text{ is such that $i = p + \Phi(e,e)q$.}  \epfreseq
\]
\end{prop}

\begin{rem}\label{rem:ETunit}
If $q$ is a unit, then so too is $\Phi(e,e)q$ for any $e\in E(S)$.  In this case it follows that $\Om = E(M)\times E(S)$, and that
\[
\ve(i,e) = (i-\Phi(e,e)q,e) \qquad\text{for all $i\in E(M)$ and $e\in E(S)$.}
\]
In particular, if $M$ is a group, so that $E(M)=\{0\}$, the idempotents of $T$ all have the form $\ve(0,e) = (-\Phi(e,e)q,e)$ for $e\in E(S)$.

On the other hand, if $e\in E(S)$ is such that $\Phi(e,e)=0$, then $(i,e)\in\Om$ for all $i\in E(M)$.  In this case we have $p(i,e)=i$, and so $\ve(i,e)=(i,e)$.

If $M$ is unipotent, i.e.~$E(M)=\{0\}$, but $q$ is not a unit, then $0\not\leqJ^Mq$, and so
\[
\Om = \set{(0,e)}{e\in E(S),\ \Phi(e,e) = 0} = E(T).
\]
\end{rem}





