\subsection{Proofs}\label{sec:proofs}

\textbf{Proof of Lemma \ref{prop1}}. By combining conditions \eqref{eq:eq5} and \eqref{eq:eq6}, there is $e_i = \dfrac{1}{2}\sum\limits_{h=1}^n(\lambda_{hi}-\lambda_{ih})$. By summing over all $n$ observations, we can confirm that $\sum\limits_{h=1}^n e_i=0$. \qed
\newline

\noindent\textbf{Proof of Theorem \ref{theo1}}. By combining \eqref{eq:eq5} and \eqref{eq:eq7} and summing over all $n$ observations, there is 
	\begin{equation}
		\sum\limits_{i=1}^ne_{i}x_{ik}=\sum\limits_{i=1}^n{\sum\limits_{h=1}^n{\lambda _{ih}x_{ik}}}-\sum\limits_{i=1}^n{\sum\limits_{h=1}^n{\lambda_{hi}x_{hk}}}
		\label{eq:a1}
	\end{equation} 
	By utilizing the properties of the sum operator to substitute indices $i$ and $h$ we know that $\sum\limits_{i=1}^n{\sum\limits_{h=1}^n{\lambda _{ih}x_{ik}}}=\sum\limits_{i=1}^n{\sum\limits_{h=1}^n{\lambda _{hi}x_{hk}}}$ and hence $\sum\limits_{i=1}^ne_ix_{ik}=0$.\qed
\newline

\noindent\textbf{Proof of Lemma \ref{prop2}}. Combining conditions \eqref{eq:eq5} and \eqref{eq:eq16}, we have $e_i=\hat{y}_{i}\left[ \sum\limits_{h=1}^n\lambda_{ih}-\sum\limits_{h=1}^n\lambda_{hi} \right]$. We then move $\hat{y}_{i}$ to the left-hand side and sum over all $n$ observations. Since $\sum\limits_{i=1}^n \sum\limits_{h=1}^n\lambda_{ih}-\sum\limits_{i=1}^n\sum\limits_{h=1}^n\lambda_{hi} = 0$, we can obtain $\sum\limits_{i=1}^n \dfrac{e_i}{\hat{y}_{i}} = 0$. \qed
\newline

\noindent\textbf{Proof of Theorem \ref{theo2}}. 
Summing over all $n$ observations in both~\eqref{eq:eq5} and \eqref{eq:eq17}, we have 
\begin{align}
	& \sum\limits_{i=1}^n e_i - \sum\limits_{i=1}^n\mu_i=0 \label{eq:a2}\\
	& -\sum\limits_{i=1}^n\mu_i\dfrac{x_{ik}}{\hat{y}_i}+\sum\limits_{i=1}^n\sum\limits_{h=1}^n \lambda_{ih} x_{ik} - \sum\limits_{i=1}^n\sum\limits_{h=1}^n \lambda_{hi}x_{hk} = 0 \label{eq:a3}
\end{align}
After combining Eqs.~\eqref{eq:a2} and \eqref{eq:a3}, the sample orthogonality condition becomes $\sum\limits_{i=1}^n e_i\dfrac{x_{ik}}{\hat{y}_i} =0$. \qed
\newline

\noindent\textbf{Proof of Theorem \ref{theo3}}. Summing Eq.~\eqref{eq:eq13} (or Eq.~\eqref{eq:eq22}) over all observations, and applying Theorem~\ref{theo1} (or Theorem~\ref{theo2}), we have $\sum\limits_{i=1}^n \eta_{ik} > 0$ and hence $\sum\limits_{i=1}^n e_i x_{ik} < 0$ (or $\sum\limits_{i=1}^n e_i \dfrac{x_{ik}}{\hat{y}_i} < 0$). \qed
\newline

\noindent\textbf{Proof of Theorem \ref{theo4}}. After considering the additive model with linear homogeneity constraints, we can eliminate the $\alpha_i$ variables from the problem as $\alpha_i = 0 (i=i, \ldots, n)$. The Lagrangian function is 
\begin{align*}
    \Ls(\blambda,\bbeta,\bmu)=&\dfrac{1}{2}\sum\limits_{i=1}^n \varepsilon_i^2+\sum\limits_{i=1}^n\mu_i(y_i-\bbeta_i^\prime\bx_i-\varepsilon_i) + \sum\limits_{i=1}^n{\sum\limits_{h=1}^n\lambda_{ih}(\bbeta _i-\bbeta_h)^\prime\bx_i}
\end{align*}

The corresponding first-order conditions are the following equations 
\begin{align}
& \dfrac{\partial \Ls}{\partial \varepsilon_i}=e_i - \mu_i=0, \forall I \label{eq:a4} \\
& \dfrac{\partial \Ls}{\partial \beta_{ik}}=-\mu_i x_{ik}+\sum\limits_{h=1}^n \lambda_{ih} x_{ik} - \sum\limits_{h=1}^n\lambda_{hi} x_{hk}=0, \forall i, k.  \label{eq:a5}
\end{align}

The result demonstrated in Theorem \ref{theo2} is still valid as it is dependent on the equations \eqref{eq:a4} and \eqref{eq:a5}, which are still active. Therefore, the additive model subject to concavity and linear homogeneity holds the orthogonality condition. However, after introducing monotonicity to this convex regression problem, the orthogonality condition will not be held (see Theorem \ref{theo3} for the proof). Similarly, this conclusion can be directly applied to the multiplicative models. \qed
\newline

\noindent\textbf{Proof of Theorem \ref{theo5}}. The regressor $\hat{\zeta}_i$ in the semi-nonparametric convex regression model \eqref{eq:eq4.2} is derived from the residuals of an auxiliary OLS regression defined in \eqref{eq:eq4.1}. Under standard assumptions for OLS estimation---specifically, independence and identical distribution of observations, full rank condition of the regressors, zero conditional expectation, and finite variance of the random error term---the estimator $\hat{\omega}$ is known to be consistent:
\begin{equation}
    \hat{\omega} \overset{p}{\rightarrow} \omega.
\end{equation}

It then follows directly from Slutsky's theorem that the residual estimates $\hat{\zeta}_i = x_{1i}-\hat{\omega}z_i$ consistently estimate $\zeta_i$, specifically:
\begin{equation}
    \hat{\zeta}_i \overset{p}{\rightarrow} \zeta_i.
\end{equation}

Consequently, the consistency proof of the semi-nonparametric convex regression estimator \eqref{eq:eq4.3} can be rigorously established by adapting and extending the empirical process-based uniform convergence results, identification conditions, and consistency presented in \citet{Seijo2011} or \citet{Lim2012}. This extension explicitly accounts for the consistent estimation of the auxiliary residual term $\hat{\zeta}_i$, thus maintaining the theoretical rigor and validity of the consistency of convex regression.

