        0 & - \diver(\rho \cdot) & 0 &0\\
        - \rho \grad & -G(\bm{\omega}) & - \curl &\grad \\
        0 & \curl & 0 & 0\\
        0 & \diver & 0& 0
    \end{bmatrix} \begin{pmatrix}
        e_\rho \\
        \bm{e_{u}} \\
