\section{Proofs} \label{apx:proofs}


\subsection{Proof of Lemma~\ref{def:latent-state-ph}} \label{proof:latent-state-ph}

\begin{proof}
    Recall that $P$ and $S \in \mathcal{M}_{n+n_L}(\mathbb{R})$ are such that $P^\top S$ is symmetric and $\begin{bmatrix}
        P \\ S
    \end{bmatrix}$ is of full rank, and from~\eqref{eqn:discr-linear-phs:LAGRANGE}, that $\alpha, e \in \mathbb{R}^n$ and $u_L,y_L \in \mathbb{R}^{n_L}$ are such that:
    $$P^\top \begin{pmatrix}
        e \\ y_L
    \end{pmatrix}= S^\top\begin{pmatrix}
        \alpha \\ u_L
    \end{pmatrix}.$$
    It follows that $\begin{pmatrix}
        \alpha \\ u_L \\ e \\ y_L 
    \end{pmatrix} \in \ker( \begin{bmatrix}
        S^\top & - P^\top
    \end{bmatrix}.$

    Moreover, from $P^\top S - S^\top P=0$, it comes: $\text{Ran}\begin{bmatrix}
        P \\ S
    \end{bmatrix} \subset \ker( \begin{bmatrix}
        S^\top & - P^\top
    \end{bmatrix}).$

    Furthermore, we have from the size of $P$ and $S$: $\text{dim}(\ker( \begin{bmatrix}
        S^\top & - P^\top
    \end{bmatrix}) \leq n + n_L$, and the rank condition gives $\text{dim}(\text{Ran}\begin{bmatrix}
        P \\ S
    \end{bmatrix}) = n + n_L$ . Hence,
    \begin{equation} \label{eqn:ker-ran-equality-discrete}
        \ker(\begin{bmatrix}
        S^\top & - P^\top
    \end{bmatrix}) = \text{Ran}\begin{bmatrix}
        P \\ S
    \end{bmatrix},
    \end{equation} 
    which proves the existence of $(\lambda, \tilde u_L ) \in \mathbb{R}^{n + n_L}$ such that \eqref{eqn:latent-state-control-def} holds.

    Finally, the rank condition ensures the injectivity of $\begin{bmatrix}
        P \\S
    \end{bmatrix}$, which proves the uniqueness.
\end{proof}
\subsection{Proof of Lemma~\ref{lemma:latent-state-hamiltonian-definition} } \label{proof:latent-state-hamiltonian-definition}
\begin{proof}
    Let us compute $\frac{\d}{\d t} H(\lambda, \tilde u)$:
    \begin{equation*}
        \begin{aligned}
            \frac{\d}{\d t} H(\lambda, \tilde u) & = \frac{\d}{\d t}\left(\frac{1}{2} \begin{pmatrix}
        \lambda \\ \tilde u_L
    \end{pmatrix}^\top P^\top S \begin{pmatrix}
        \lambda \\ \tilde u_L
    \end{pmatrix}\right) \\ & =  \left(\frac{\d }{\d t}\begin{pmatrix}
        \lambda \\ \tilde u_L
    \end{pmatrix} ^\top P^\top \right) S \begin{pmatrix}
        \lambda \\ \tilde u_L
    \end{pmatrix} & (P^\top S = S^\top P) \\
    & = \frac{\d}{\d t} \begin{pmatrix}
        \alpha \\ u_L
    \end{pmatrix}^\top \begin{pmatrix}
        e \\y_L
    \end{pmatrix} & \text{(Lemma~\ref{def:latent-state-ph})} \\
    & = e^\top \dot \alpha + y_L^\top \dot u_L. 
        \end{aligned} 
    \end{equation*}
    Hence, using solely the Lagrange structure, and in particular Eq.~\eqref{def:latent-state-ph}, leads to the first equality of \eqref{eqn:latent-state-ph-power-balance}.
    Now, using the Dirac structure, we have:
    \begin{equation*}
        \begin{aligned}
            0 & = \begin{pmatrix}
                e \\ e_R \\ u_D
            \end{pmatrix}^\top J \begin{pmatrix}
                e \\e_R \\ u_D
            \end{pmatrix} & (J = - J^\top) \\
            &= \begin{pmatrix}
                e \\e_R \\ u_D
            \end{pmatrix}^\top \begin{pmatrix}
                \frac{\d}{\d t} (P_{1,1} \lambda + P_{1,2} \tilde u_L) \\ f_R \\ -y_D
            \end{pmatrix} \\
            &= e^\top \dot \alpha + e_R^\top f_R - y_D^\top u_D \\
            &= \frac{\d}{\d t} H(\lambda,\tilde u_L) - y_L^\top \dot u_L + e_R^\top f_R - y_D^\top u_D.
        \end{aligned}
    \end{equation*}
    Rearranging the terms gives the desired result.%:
%    $$  \frac{\d}{\d t} H(\lambda,\tilde u_L) = - f_R^\top R \, f_R + y_L^\top \dot u_L  + y_D^\top u_D. $$
\end{proof}

\subsection{Proof of Lemma~\ref{lemma:nanorod-hamiltonian-definition}}\label{proof:nanorod-hamiltonian-definition}

\begin{proof}
    See \cite[Example 31]{maschke2023linear} for~\eqref{eqn:hamiltonian-nonlocal-nanorod}.

    Let us compute $\frac{\d}{\d t}H(\lambda,p):$
    \begin{equation*}
        \begin{aligned}
            \frac{\d}{\d t} H(\lambda,p) &= \frac{\d}{\d t} \left(\frac{1}{2} \int_a^b E\, (\lambda^2 + \ell^2 \, (\partial_x \lambda)^2) + \frac{1}{\rho}p^2 \, \,  \d x \right), \\
            &= \int_a^b E \, \lambda  \, \, (1 - \ell^2 \, \partial_{x^2}^2) \partial_t \lambda + \frac{p}{\rho} \, \partial_t p \, \d x  + [ \partial_t \lambda \, \,   E \ell^2 \,  \partial_x \lambda ]_a^b \,, \\
            &= \int_a^b \sigma \,  \partial_x v + v \, \partial_x \sigma \, \d x+ [ \partial_t \lambda \, \,   E \ell^2 \,  \partial_x \lambda ]_a^b \, , \\
            &= [ \sigma \, v ]_a^b + [ \partial_t \lambda \, \,   E \ell^2 \,  \partial_x \lambda ]_a^b.
        \end{aligned}
    \end{equation*}
    This gives us the first part of the result. Let us now consider the Robin boundary conditions~\eqref{eqn:compatible-boundary-conditions}. In particular, using $\sigma = E\, \lambda$, we get:
    $$ \begin{array}{rcl} \sigma(a) + n_a \, \ell \partial_x \sigma(a) = 0, &\qquad& \sigma(b) + n_b \,\ell \partial_x \sigma(b) = 0, \\ 
    \lambda(a) + n_a\, \ell \partial_x \lambda(a) = 0, &\qquad& \lambda(b) + n_b\, \ell \partial_x \lambda(b) = 0.\end{array}   $$
    Then:
    \begin{equation*}
        \begin{aligned}
             \frac{\d}{\d t} H(\lambda,p) &= [ \sigma \, v ]_a^b + [ \partial_t \lambda \, \,   E \ell^2 \,  \partial_x \lambda ]_a^b, \\
             &= \sigma(a) \,v(a)\, n_a + \sigma(b)  \, v(b)\, n_b  + \partial_t \lambda(a) \, E \ell^2 \, \partial_x \lambda(a) \, n_a +  \partial_t \lambda(b) \, E \ell^2 \, \partial_x \lambda(b) \, n_b,\\
             &= - \ell \,  \partial_x\sigma(a) \, v(a) \, n_a^2 - \ell \,  \partial_x \sigma(b) \, v(b) \, n_b^2 
              - \ell \,  \partial_t \lambda(a) \, E \, \lambda(a) \, n_a^2 -  \ell \,  \partial_t \lambda(b) \, E \, \lambda(b) \, n_b^2. \\
        \end{aligned}
    \end{equation*}
    Now, using the Dirac structure~\eqref{eqn:nanorod-equation-implicit-latent:DIRAC} which imposes $\partial_x \sigma = \partial_t p$, and the Lagrange structure~\eqref{eqn:nanorod-equation-implicit-latent:LAGRANGE} which implies $v = p/\rho$, we obtain:
    \begin{equation*}
        \begin{aligned}
        \frac{\d}{\d t} H(\lambda,p) &= - \ell \,  \partial_x\sigma(a) \, v(a) \,  - \ell \,  \partial_x \sigma(b) \, v(b) \,  - \ell \,  \partial_t \lambda(a) \, E \, \lambda(a) \, -  \ell \,  \partial_t \lambda(b) \, E \, \lambda(b) \, , \\
             &= -\ell \left[ \frac{1}{\rho} \left(\partial_t p(a)\, p(a) +   \partial_t p(b) \, p(b) \right) + E\, \left( \partial_t \lambda(a)\lambda(a) + \partial_t \lambda(b) \lambda(b)\right) \right].
        \end{aligned}
    \end{equation*}
\end{proof}


\subsection{Proof of Lemma~\ref{lemma:nanorod-hamiltonian-robin-definition}}\label{proof:nanorod-hamiltonian-robin-definition}

\begin{proof}
    Shifting the right-hand side of the power balance \eqref{eqn:nanorod-power-balance-with-robin-boundary-conditions} to the left yields:
    \begin{equation*} 
        \frac{\d}{\d t} H(\lambda, p) +\ell \left[ \frac{1}{\rho} \left(\partial_t p(a)\, p(a) +   \partial_t p(b) \, p(b) \right) + E\, \left( \partial_t \lambda(a)\lambda(a) + \partial_t \lambda(b) \lambda(b)\right) \right] = 0.
    \end{equation*}
    Then, using the identity $ f'f = \frac{1}{2}(f^2)'$ gives us:
     \begin{equation*} 
       0 = \frac{\d}{\d t} H(\lambda, p) + \frac{\ell}{2} \, \frac{\d}{\d t} \left[ \frac{1}{\rho}( p(a)^2 +   p(b)^2 ) + E\, (\lambda(a)^2 + \lambda(b)^2) \right] = \frac{\d}{\d t} H_{\text{Rob}}(\lambda,p),
    \end{equation*}
    which proves the result.
\end{proof}


\subsection{Proof of Lemma~\ref{lemma:nanorod-discrete-robin}}\label{proof:nanorod-discrete-robin}

\begin{proof}
    Writing the Robin Boundary conditions \eqref{eqn:compatible-boundary-conditions} using the energy control port $u_L$ gives us:
    $$\sigma^d(a) + \ell\, (u_L)_1 = 0 =\sigma^d(b) + \ell\, (u_L)_2.$$
    Which, written using the previously defined matrices gives \eqref{eqn:discr-robin-boundary-conditions-lagrange}.

    Similarly, writing \eqref{eqn:compatible-boundary-conditions} using the power control port $u_D$ yields:
    $$ (u_D)_1  + \ell \,  \partial_x \sigma(a) =  0 = (u_D)_2 + \ell \,  \partial_x \sigma(b), $$
    where using the fact that $(u_D)_1 = \sigma(a)n_a$ and $(u_D)_2 = \sigma(b)n_b$ allowed us to remove the outer normals $n_a,n_b$ from the expression.
 Now, using Dirac structure \eqref{eqn:nanorod-equation-implicit-coenergy}, we have that $\partial_x \sigma = \partial_t p = \rho \, \partial_t v,$ which gives us:
    $$ (u_D)_1  + \ell \, \rho(a) \, \partial_t v^d(a) =  0 = (u_D)_2 + \ell \,  \rho(b) \, \partial_t v^d(b). $$
Writing the obtained equation using the previously defined matrices gives \eqref{eqn:discr-robin-boundary-conditions-dirac}.
\end{proof} 

\subsection{Proof of Lemma~\ref{lemma:navier-stokes-skew-symmetry}} \label{proof:navier-stokes-skew-symmetry}

\begin{proof} 
    Let $\psi, \omega, \phi_1,\phi_2 \in H^1$ then we have:
    \begin{equation*}
        \begin{aligned}
            \int_\Omega \phi_1 \, \diver(\omega \, \grad^\perp(\phi_2)) \, \d x& = - \int_\Omega \omega \, \grad(\phi_1) \cdot \grad^\perp(\phi_2) \, \d x + \int_{\partial \Omega} \omega \, \phi_1 \,  \bm{n} \cdot \grad^\perp(\phi_2) \, \d s, \\
            &= \int_\Omega \omega \, \grad^\perp(\phi_1) \cdot \grad(\phi_2) \, \d x + \int_{\partial \Omega} \omega \, \phi_1 \,  \bm{n} \cdot \grad^\perp(\phi_2) \, \d s,\\
            &= - \int_\Omega \phi_2 \, \diver(\omega \, \grad^\perp(\phi_1)) \, \d x + \int_{\partial \Omega} \omega \, \phi_1 \,  \bm{n} \cdot \grad^\perp(\phi_2) \, \d s \\ & \quad  \quad + \int_{\partial \Omega} \omega \, \phi_2 \,  \bm{n} \cdot \grad^\perp(\phi_1) \, \d s.
        \end{aligned}
    \end{equation*}
Which proves the first equality, then:
    \begin{equation*}
        \begin{aligned}
            \int_\Omega \phi_1 \, \diver(\grad^\perp(\psi) \, \, \phi_2) \, \d x& = - \int_{\Omega} \phi_2 \, \grad(\phi_1) \cdot \grad^\perp(\psi) \, \d x + \int_{\partial \Omega} \phi_1 \, \phi_2 \,  \bm{n} \cdot \grad^\perp(\psi) \, \d s, \\
            &= - \int_\Omega \phi_2 \, \diver( \grad^\perp(\psi) \, \phi_1 )\, \d x+ \int_{\partial \Omega} \phi_1 \, \phi_2 \,  \bm{n} \cdot \grad^\perp(\psi) \, \d s.
        \end{aligned}
    \end{equation*}
Where the last equality is obtained from the fact that $\diver(\grad^\perp(\psi)) = 0.$
\end{proof}




\section{Useful identities} \label{apx:vector-identities}

\begin{lemma}
Given $\bm{\phi} \in H^\curl(\Omega)$ and $\psi \in H^1(\Omega)$, we have:
\begin{equation} \label{ipp:gradperp-curl}
	\int_\Omega  \bm{\phi} \cdot \grad^\perp(\psi) \, \d x = \int_\Omega \curldeuxD(\bm{\phi}) \,  \psi \, \d x + \int_{\partial \Omega} \psi \, \, \bm{\phi} \cdot \bm{t} \,\d s.
\end{equation}

\end{lemma}

\begin{lemma}
\begin{equation} \label{eqn:gradperpcurldeuxd-laplacian}
    \curldeuxD \,\grad^\perp = - \Delta.
\end{equation}
\end{lemma}
\begin{proof}
    $\curldeuxD \,\grad^\perp = \begin{bmatrix}
        - \partial_y & \partial_x
    \end{bmatrix} \begin{bmatrix}
         \partial_y \\ -\partial_x
    \end{bmatrix} = - \partial_{y^2}^2 - \partial_{x^2}^2 = - \Delta.$
\end{proof}


