\paragraph{Incoherence-Coherence transition.}
Initial conditions for the simulations described in Sec.~\ref{sec:subgraph_incoherence_coherence} (Fig.~\ref{fig:subgraph_constraint_example_1}) are $\phi_k(0)\sim\pi/2 + 0.5 \cdot \mathcal{N}(0)$; and 
\begin{align*}
\w(0) = 
        \left(
        \begin{array}{cc}
         \boldsymbol{\Db_1} & \boldsymbol{\Bb}\\
         \boldsymbol{\Bb}^T & \boldsymbol{\Db_2}
        \end{array}
        \right) \in \R^{N\times N}, 
\end{align*}
where 
$\Db_1\in\R^{N_1\times N_1} \sim  \mathcal{N}(1,0.05)$,
$\Db_2\in\R^{N_2\times N_2} \sim  \mathcal{N}(2,0.05)$, 
$\Bb \in\R^{N_2\times N_1} \sim  \mathcal{N}(1,0.05)$,
with
$N_1 = \lceil 0.8 \cdot N \rceil$
and 
$N_2 = N - N_2$.

\paragraph{Adaptive Chimeras.}
Initial conditions for the simulations described in Sec.~\ref{sec:subgraph_adaptive_chimera} (Fig.~\ref{fig:subgraph_constraint_example_2}) are 
$\phi_k(0)\sim \mathcal{N}(-0.5,0.05)$ for $ k=1,\ldots, Q$ and  
$\phi_k(0)\sim \mathcal{N}(0,0.05)$ for $k = Q+1,\ldots, N$; and 
\begin{align*}
\w(0) = 
        \left(
        \begin{array}{cc}
         \boldsymbol{\Ab} & \boldsymbol{\Bb}\\
         \boldsymbol{\Bb}^T & \boldsymbol{\Ab}
        \end{array}
        \right) \in \R^{N\times N}, 
\end{align*}
where 
$\Ab = (a_{kl}) \in \R^{Q\times Q}, a_{kl} \sim \mathcal{N}(1+a,0.1)$;
$\Bb = (b_{kl}) \in \R^{Q\times Q}, b_{kl} \sim \mathcal{N}(1-a,0.1)$.



