\title{Measurement of the Differential Static Scalar Polarizability of the \texorpdfstring{$^\mathbf{88}$Sr$^{+}$}{88Sr+} Clock Transition}

\author{T.~Lindvall}
\email[]{thomas.lindvall@vtt.fi}
\author{K.~J.~Hanhijärvi}
\author{T.~Fordell}
\author{A.~E.~Wallin}
\affiliation{VTT Technical Research Centre of Finland Ltd, National Metrology Institute VTT MIKES, P.O.\ Box 1000, FI-02044 VTT, Finland
