\section{Preliminaries}\label{sec:preliminaries}

%In this section, we prove some intermediate results, and provide our main proofs. For, some definitions are in order. 

Given an ideal $\mathcal{I}$ on $\omega$ and a bounded real sequence $x \in \ell_\infty$, a point $\eta \in \mathbf{R}$ is said to be a $\mathcal{I}$\emph{-cluster point} of $x$  if $\{n \in \omega: |x_n-\eta|\le \varepsilon\} \notin \mathcal{I}$ for all $\varepsilon>0$ (note that they have been termed \emph{statistical cluster point} if $\mathcal{I}=\mathcal{Z}$, see e.g. \cite{MR1181163, MR1416085}). 
%The set of $\mathcal{I}$-cluster points of $x$ is denoted by $\Gamma_x(\mathcal{I})$; 
For each $x \in \ell_\infty$, we denote by $\Gamma_x(\mathcal{I})$ the set of its of $\mathcal{I}$-cluster points; in addition, $\mathcal{I}\text{-}\liminf x:=\min \Gamma_x(\mathcal{I})$ and $\mathcal{I}\text{-}\limsup x:=\max \Gamma_x(\mathcal{I})$, which are well defined since $\Gamma_x(\mathcal{I})$ is nonempty compact; 
see e.g. \cite{MR3920799} and references therein for basic properties and characterization of $\mathcal{I}$-cluster points. Interestingly, the map $x\mapsto \mathcal{I}\text{-}\limsup x$ provides a complete pseudonorm on $\ell_\infty$, see \cite{MR2735533, MR4610955}. 

Recall also that each sequence $x\in \ell_\infty$ can be extended uniquely to a continuous function $\hat{x}: \beta\omega \to \mathbf{R}$ defined by 
$$
\forall \mathcal{F} \in \beta\omega, \quad 
\hat{x}(\mathcal{F}):=\mathcal{F}\text{-}\lim x.
$$
In particular, if $\mathcal{F}$ is the principal ultrafilter associated with an integer $n \in \omega$, then $\hat{x}(\mathcal{F})=x_n$. Hereafter, for each $A\subseteq \omega$, we write 
$$
\tilde{A}:=\{\mathcal{F} \in \beta\omega: A \in \mathcal{F} \text{ and }\mathcal{F}\text{ free ultrafilter }\}.
$$

%%%%%%%%%%%%%%%%%%%%
\begin{lem}\label{lem:bndensityzero}
Let $\mathcal{I}$ be an ideal on $\omega$. Then, for each $A\subseteq \omega$, we have 
$A \in \mathcal{I}$ if and only if $\tilde{A} \cap \mathrm{Ult}(\mathcal{I})=\emptyset$. 
%$\textsc{K}_{\mathcal{I}} \cap S^\star=\emptyset$.
\end{lem}
\begin{proof}
Fix $A\subseteq \omega$ and define the dual filter $\mathcal{G}:=\{B \subseteq \omega: \omega\setminus B \in \mathcal{I}\}$. First, suppose that $A \in \mathcal{I}$ and let $\mathcal{F}$ be a free ultrafilter containing $A$, i.e., $\mathcal{F} \in \tilde{A}$. Then $\omega\setminus A \notin \mathcal{F}$ while, on the other hand, it belongs to $\mathcal{G}$. Hence $\tilde{A} \cap \mathrm{Ult}(\mathcal{I})=\emptyset$. %$\textsc{K}_{\mathcal{I}} \cap S^\star=\emptyset$. 
%
%http://www.mi.fu-berlin.de/math/groups/ag-logik/Lehre/UST-chapter02.pdf

Conversely, suppose that $A \notin \mathcal{I}$. Considering that every finite subfamily of $\{A\} \cup \mathcal{G}$ has intersection not in $\mathcal{I}$ (hence, infinite intersection), there exists a free ultrafilter $\mathcal{F}$ containing $A$ and $\mathcal{G}$, hence $\tilde{A} \cap \mathrm{Ult}(\mathcal{I})\neq \emptyset$.
\end{proof}

\begin{lem}\label{lem:bnsubseqconvergence}
Let $\mathcal{I}$ be an ideal on $\omega$ and fix an infinite set $A\subseteq \omega$ with increasing enumeration $(a_n: n \in \omega)$. Then, for each $x \in \ell_\infty$ and $\eta \in \mathbf{R}$, we have $\lim_n x_{a_n}=\eta$ if and only if $\hat{x}[\,\tilde{A}\,]=\{\eta\}$.
\end{lem}
\begin{proof}
Suppose that $\lim_n x_{a_n}=\eta$ and fix a free ultrafilter $\mathcal{F}$ containing $A$, i.e., $\mathcal{F} \in \tilde{A}$. Then for each neighborhood $U$ of $\eta$ there exists $F \in \mathrm{Fin}$ such that $\{n\in \omega: x_n \in U\}\supseteq A\setminus F$, hence it belongs to $\mathcal{F}$. Therefore $\hat{x}(\mathcal{F})=\mathcal{F}\text{-}\lim x=\eta$. 

Conversely, suppose that $\hat{x}[\,\tilde{A}\,]=\{\eta\}$ and let $U$ be a neighborhood of $\eta$. Then $\{n\in \omega: x_{n} \in U\} \in \mathcal{F}$ for each $F \in \tilde{A}$. Hence $\{n\in \omega: x_{n} \in U\}$ belongs to $\bigcap \tilde{A}$, which is known to be the filter $\{B \subseteq \omega: A\setminus B\in \mathrm{Fin}\}$. We conclude that the subsequence $(x_{a_n}:n \in \omega)$ converges to $\eta$. 
\end{proof}

As a consequence, we provide a characterization of $\mathcal{I}$-cluster points, which generalizes \cite[Theorem 2(3)]{MR1372186}. 
\begin{thm}\label{thm:Iclusterpoints}
Let $\mathcal{I}$ be an ideal on $\omega$. Then $\Gamma_x(\mathcal{I})=\hat{x}[ \mathrm{Ult}(\mathcal{I})]$ for each $x \in \ell_\infty$. 
\end{thm}
\begin{proof}
Fix $x \in \ell_\infty$. First, suppose that there exists a free ultrafilter $\mathcal{F} \in \mathrm{Ult}(\mathcal{I})$ such that $\hat{x}(\mathcal{F})=\eta$, that is, $\mathcal{F}\text{-}\lim x=\eta$. Hence, for each neighborhood $U$ of $\eta$, it holds $\{n\in\omega: x_n \in U\} \in \mathcal{F}$. Considering that $\mathcal{F} \cap \mathcal{I}=\emptyset$, we obtain that $\eta$ is an $\mathcal{I}$-cluster point of $x$. Hence $\hat{x}[ \mathrm{Ult}(\mathcal{I})]\subseteq \Gamma_x(\mathcal{I})$. 

Conversely, suppose that $\eta \in \Gamma_x(\mathcal{I})$ and let $(U_k)$ be a decreasing local base of neighborhoods at $\eta$. Then $A_k:=\{n\in \omega: x_n \in U_k\} \notin \mathcal{I}$ for each $k\in \omega$. Thanks to Lemma \ref{lem:bndensityzero}, for each $k\in \omega$ there exists a free ultrafilter $\mathcal{F}_k$ containing $A_k$ and the dual filter of $\mathcal{I}$. In particular, $\hat{x}(\mathcal{F}_k)=\eta$ for each $k\in \omega$. Since $(\mathcal{F}_k: k \in \omega)$ is a sequence in the compact space $\mathrm{Ult}(\mathcal{I})$, there is a subsequence of ultrafilters converging to some $\mathcal{F} \in \mathrm{Ult}(\mathcal{I})$. By the continuity of $\hat{x}$, we conclude that $\hat{x}(\mathcal{F})=\eta$. Therefore $\Gamma_x(\mathcal{I})\subseteq \hat{x}[ \mathrm{Ult}(\mathcal{I})]$. 
\end{proof}

As a consequence, we recover an intermediate result of Freedman \cite[p. 226]{MR614658}: 
\begin{cor}
Let $\mathcal{I}$ be an ideal on $\omega$ and fix $A\subseteq \omega$ with $A\notin \mathcal{I}$. Then there exists $f \in \mathrm{SL}(\mathcal{I})$ such that $f(\bm{1}_A)=1$. 
\end{cor}
\begin{proof}
    Since $A\notin \mathcal{I}$ then $1$ is an $\mathcal{I}$-cluster of the sequence $\bm{1}_A$. We obtain by Theorem \ref{thm:Iclusterpoints} that there exists $\mathcal{F} \in \mathrm{Ult}(\mathcal{I})$ such that $f_{\mathcal{F}}(\bm{1}_A)=\mathcal{F}\text{-}\lim \bm{1}_A=1$. The claim follows by the fact that $f_{\mathcal{F}} \in \mathrm{SL}(\mathcal{I})$, as anticipated in Section \ref{sec:intro}.  
\end{proof}

As another consequence, we generalize a claim contained in \cite[Theorem 3.2(i)]{MR3513160} and \cite[Theorem 2.4(i)]{CihanMustafa25}:
\begin{cor}\label{cor:liminflimsup}
Let $\mathcal{I}$ be an ideal on $\omega$. Then % and pick $x \in \ell_\infty$. Then 
$$
\forall x \in \ell_\infty, \quad 
\{f(x): f \in \mathrm{SL}(\mathcal{I})\}=\mathrm{co}(\Gamma_x(\mathcal{I})).
$$
In particular, $\mathcal{I}\text{-}\liminf x\le f(x)\le \mathcal{I}\text{-}\limsup x$ for all $f \in \mathrm{SL}(\mathcal{I})$ and $x \in \ell_\infty$. 
\end{cor}
\begin{proof}
    It follows by Theorem \ref{thm:secondrepresenation} and Theorem \ref{thm:Iclusterpoints}. 
\end{proof}


