We conclude with a computation of the norm of $f \in \ell_\infty^{\,\prime}$ such that $f(e)=0$. 
\begin{lem}\label{lem:abramoich}
    Fix $f \in \ell_\infty^{\,\prime}$ with $f(e)=0$. Then 
    $$
    \|f\|=2\sup\{f(x): 0\le x\le e\}=2\sup\{f(\bm{1}_A): A\subseteq \omega\}
    .$$ 
\end{lem}
\begin{proof}
Set $s:=\sup\{f(x): 0\le x\le e\}$. On the one hand, we have 
\begin{displaymath}
    \begin{split}
        \|f\|&=\sup\{f(x): -e\le x\le e\}\\
        &=\sup\{f(a-b): 0\le a,b\le e, a\wedge b=0\}\\
        &\le \sup\{f(a)+f(-b): 0\le a,b\le e\}\\
        &= \sup\{f(a)+f(e-b): 0\le a,b\le e\}\\
        &= \sup\{f(a)+f(b): 0\le a,b\le e\}\le 2s.
    \end{split}
\end{displaymath}
On the other hand, we have that
\begin{displaymath}
    \begin{split}
         \|f\|&\ge \sup\{f(\bm{1}_A-\bm{1}_{\omega\setminus A}): A\subseteq \omega\}\\
         &=\sup \{f(\bm{1}_A)+f(e-\bm{1}_{\omega\setminus A}): A\subseteq \omega\}\\
         &=2\sup \{f(\bm{1}_A): A\subseteq \omega\}. %=2s,
    \end{split}
\end{displaymath}
To conclude, it is enough to observe that the equality $\sup \{f(\bm{1}_A): A\subseteq \omega\}=s$ follows from a result of Abramovich, see \cite[Theorem 1.50]{MR2262133} and \cite[p. 541]{MR2378491}.
\end{proof}


