\section{Proofs of Main results}\label{sec:proofs}

In this section, we provide the proofs of our main results. 
\begin{lem}\label{lem:Iinvariant}
    Let $\mathcal{I}$ be an ideal on $\omega$ and fix $f \in \mathrm{SL}(\mathcal{I})$ and $A,B \subseteq \omega$ with $A\bigtriangleup B \in \mathcal{I}$. Then $f(\bm{1}_A)=f(\bm{1}_B)$. 
\end{lem}
\begin{proof}
    This follows by $0\le |f(\bm{1}_A)-f(\bm{1}_B)|\le f(\bm{1}_{A\bigtriangleup B})=0$.
\end{proof}

Hereafter, we denote by $ba$ the space of signed finitely additive measures $\mu :\mathcal{P}(\omega)\to \mathbf{R}$ with finite total variation, that is, such that 
$$
\sup \left\{ \sum\nolimits_{i=0}^{n}|\mu (A_{i})|:\{A_{0},A_1,\ldots ,A_{n}\}%
\text{ is a partition of }\omega\right\} <\infty,
$$
see e.g. \cite[Section 10.10]{MR2378491}. 
Recall that the norm dual $\ell _{\infty}^{\,\prime}$ can be identified with $ba$ via the lattice isomorphism $T:\ell _{\infty}^{\,\prime}\to ba$ defined by%
\begin{equation}\label{eq:latticeisomorphism}
\forall f \in \ell _{\infty}^{\,\prime},\forall A\subseteq \omega,\quad
T(f)(A):=f(\bm{1}_{A}),
\end{equation}
see e.g. \cite[Theorem 14.4]{MR2378491}. 
We endow both $ba$ and the norm dual $\ell _{\infty }^{\,\prime}$ with the weak%
$^{\star }$ topology. Note that $T$ is continuous and its inverse is given by%
\begin{equation}\label{eq:Tinverserecall}
\forall \mu \in ba,\forall x\in \ell _{\infty },\quad 
T^{-1}(\mu)(x)=\int_{\mathbf{\omega}}x\,\mathrm{d}\mu . 
\end{equation}

%https://math.stackexchange.com/questions/175553/every-multiplicative-linear-functional-on-ell-infty-is-the-limit-along-an
%multiplicative iff U-limit

\begin{rmk}\label{rmk:equivalentdefi}
   By the above premises, it is easy to check that a linear continuous functional $f \in \ell_\infty^{\,\prime}$ belongs to $\mathrm{SL}(\mathcal{I})$ if and only if the associated finitely additive measure $\mu:=T(f)$ is nonnegative, normalized, and assigns $0$ to all sets in $\mathcal{I}$ (or, equivalently, it is $\mathcal{I}$-invariant). 

   This implies that 
   %, if $f \in \ell_\infty^{\,\prime}$, then 
   item \ref{item:2SI} in Definition \ref{defi:SLI} can be replaced by $f(e)=1$ (in fact, the continuity of $f$ follows by item \ref{item:1SI}). In addition, item \ref{item:3SI} can be replaced by the equivalent (formally stronger) $f(x)=0$ for all 
   $x \in c_{00}(\mathcal{I})\cap \ell_\infty$. 
   %bounded sequences $x$ which are supported on $\mathcal{I}$. 
%
   Lastly, it is easy to see that $\mathrm{SL}(\mathcal{I})$ coincides also with the set of positive linear functionals $f$ such that $f(x)=\mathcal{I}\text{-}\lim x$ for all $x \in c(\mathcal{I})\cap \ell_\infty$, cf. also Corollary \ref{cor:liminflimsup} below. 
\end{rmk}

\begin{proof}[Proof of Theorem \ref{thm:firstrepresenation}]
Fix $f \in \mathrm{SL}(\mathcal{I})$ and recall that $f$ is continuous since it satisfies \ref{item:1SIprime}. Using the lattice isomorphism $T$ defined in \eqref{eq:latticeisomorphism}, let $\mu:=T(f)$ be the nonnegative finitely additive normalized measure $\mathcal{P}(\omega)\to \mathbf{R}$ associated with $f$. 
Note that $\mu$ is $\mathcal{I}$-invariant, thanks to Lemma \ref{lem:Iinvariant}. 
It follows by \eqref{eq:Tinverserecall} that $f(x)=\int_{\omega}x\,\mathrm{d}\mu$ for all $x \in \ell_\infty$. 
Also, for each ultrafilter $\mathcal{F}$ on $\omega$, let $\mu_{\mathcal{F}}$ be the $\{0,1\}$-valued finitely additive probability measure defined by $\mu_{\mathcal{F}}(A)=1$ if and only if $A \in \mathcal{F}$. 
Taking again into account \eqref{eq:Tinverserecall}, we obtain by \cite[Theorem 1.1]{MR4693672} that there exists a normalized capacity $\rho: \mathscr{B}(\mathrm{Ult}(\mathcal{I}))\to \mathbf{R}$ such that 
$$
f(x)=\int_{\mathbf{\omega}}x\,\mathrm{d}\mu
=\int_{\mathrm{Ult}(\mathcal{I})} \left(\int_{\omega}x\,\mathrm{d}\mu_{\mathcal{F}}\right) \, \mathrm{d}\rho(\mathcal{F})
=\int_{\mathrm{Ult}(\mathcal{I})} {\mathcal{F}}\text{-}\lim x \, \mathrm{d}\rho(\mathcal{F})
$$
for each $x \in \ell_\infty$. This completes the proof. 
\end{proof}

\medskip

\begin{proof}[Proof of Theorem \ref{thm:secondrepresenation}]
%dual separates points, independently of weak star top
%https://math.stackexchange.com/questions/2579456/dual-space-x-separates-points-of-x 
    It is clear that $\mathrm{SL}(\mathcal{I})$ is a weak$^{\star}$ closed convex subset of $\ell_{\infty }^{\,\prime}$. In addition, since it is included in the closed unit ball of $\ell_\infty^{\,\prime}$, it is weak$^\star$ compact by Alaoglu's theorem, see e.g. \cite[Theorem 5.105]{MR2378491}. By the lattice isomorphism $T$ defined in \eqref{eq:latticeisomorphism}, we have that 
    $$
    \mathrm{ext}(\mathrm{SL}(\mathcal{I}))
    =T^{-1}\left[\,\mathrm{ext}\left(T[\mathrm{SL}(\mathcal{I})]\right)\right]
    =T^{-1}\left[\{\mu_{\mathcal{F}}: \mathcal{F} \in \mathrm{Ult}(\mathcal{I})\}\right],
    $$
    see \cite[Claim 4]{MR4693672} and cf. \cite[p. 544]{MR2378491} (here, as usual, $\mathrm{ext}(S)$ stands for the set of extreme points of a nonempty $S\subseteq \ell_\infty^{\,\prime}$).  
    Hence by the inverse $T^{-1}$ in \eqref{eq:Tinverserecall} we obtain $\mathrm{ext}(\mathrm{SL}(\mathcal{I}))=\{f_{{\mathcal{F}}}: \mathcal{F} \in \mathrm{Ult}(\mathcal{I})\}$. The conclusion follows by applying Krein--Milman's theorem, see e.g. \cite[Theorem 7.68]{MR2378491}.
\end{proof}

\medskip

\begin{proof}[Proof of Theorem \ref{thm:weakdiameter}]
    If $\mathcal{I}$ is maximal then it follows by Theorem \ref{thm:secondrepresenation} that $\mathrm{SL}(\mathcal{I})=\{f_{\mathcal{I}}\}$, hence $\mathrm{diam}(\mathrm{SL}(\mathcal{I}))=0$. Conversely, if $\mathcal{I}$ is not maximal, there exists a set $A\subseteq \omega$ such that $A\notin \mathcal{I}$ and $\omega\setminus A\notin \mathcal{I}$. Define $x:=\bm{1}_A-\bm{1}_{\omega\setminus A}$, so that $\Gamma_x(\mathcal{I})=\{-1,1\}$. It follows by Theorem \ref{thm:secondrepresenation} and Theorem \ref{thm:Iclusterpoints} that there exist $f,g \in \mathrm{SL}(\mathcal{I})$ such that $f(x)=1$ and $g(x)=-1$. Therefore $\mathrm{diam}(\mathrm{SL}(\mathcal{I}))\ge \|f-g\|\ge |f(x)-g(x)|=2$. 
\end{proof}

\medskip

\begin{proof}
[Proof of Theorem \ref{thm:strongdiameter}]
    Since $f \in \mathrm{SL}(\mathcal{I})$, it follows by definition that $\mathcal{I}\subseteq \{A\subseteq \omega: f(\bm{1}_A)=0\}$. On the other hand, thanks to \cite[Corollary 2.10]{MR4358610}, the latter inclusion has to be strict, hence there exists $A\subseteq \omega$ such that $A\notin \mathcal{I}$ and $f(\bm{1}_A)=0$. Since $f(\bm{1}_\omega)=1$, we get by Lemma \ref{lem:Iinvariant} that also $\omega\setminus A\notin \mathcal{I}$. At this point, define the sequence 
    $
    x:=\bm{1}_A-\bm{1}_{\omega\setminus A}.
    $ 
    Then $\Gamma_{x}(\mathcal{I})=\{1,-1\}$ and $f(x)=f(\bm{1}_A)-f(\bm{1}_{\omega\setminus A})=-1$. It also follows by Theorem \ref{thm:secondrepresenation} that there exists $g \in \mathrm{SL}(\mathcal{I})$ such that $g(x)=1$. Therefore $\|f-g\|\ge |f(x)-g(x)|=2$. 
\end{proof}

\begin{rmk}\label{rmk:kadets}
As it follows by \cite[Proposition 2.11]{MR4358610} and the proof above, there exists an ideal $\mathcal{I}$ on $\omega$ which is \emph{not} meager and, on the other hand, satisfies the claim of Theorem \ref{thm:strongdiameter}. 
\end{rmk}

