        \begin{split}
0\le (g\wedge h)(\bm{1}_A)&=\inf\{g(u)+h(v):\bm{1}_A=u+v,u,v\ge 0\}\\
&\le \inf\{g(\bm{1}_B)+h(\bm{1}_{A\setminus B}):B\subseteq A\}\\
&\le \inf\{g(\bm{1}_{(\omega\setminus A_n) \cap A})+h(\bm{1}_{A\setminus (\omega\setminus A_n)}):n \in \omega\}\\
&\le \inf\{g(\bm{1}_{\omega\setminus A_n})+h(\bm{1}_{A_n}):n \in \omega\}=0. 
\end{split}
    \end{displaymath}    
It follows, again by Lemma \ref{lem:abramoich}, that 
