The following corollary is immediate: 
\begin{cor}
    Let $\mathcal{I}$ be an ideal on $\omega$ and fix $f \in \ell_\infty^{\,\prime}$ such that $f(e)=f(\bm{1}_A)=0$ for all $A\in \mathcal{I}$. Then for every real $k \ge \|f\|/2$ there exist $g,h \in \mathrm{SL}(\mathcal{I})$ such that $f=k(g-h)$. 
\end{cor}
\begin{proof}
    If $f=0$ the claim is clear. Otherwise, fix $k\ge \|f\|/2$ (which is positive) and define $f_0:=f/k$. The claim follows applying Theorem \ref{thm:differenceSIlimits} to $f_0$. % since $\|f_0\|\le 2$. 
\end{proof}

\medskip

We conclude with the proof of Theorem \ref{thm:freedman}.
\begin{proof}[Proof of Theorem \ref{thm:freedman}] 
    The equality $\overline{c(\mathcal{I}^\star) \cap \ell_\infty}=c(\mathcal{I}) \cap \ell_\infty$ is well known, see e.g. \cite[Theorem 2.4]{MR2181783}. Hence, it is enough to show that $\mathscr{V}(\mathcal{I})=c(\mathcal{I}) \cap \ell_\infty$. 
    %The first equality has been shown by Freedman \cite{MR614658}. For the second equality, see \cite[Theorem 2.4]{MR2181783}. 
    For, suppose that $x \in \mathscr{V}(\mathcal{I})$. Since $x \in \ell_\infty$, then $\Gamma_x(\mathcal{I})\neq \emptyset$, see e.g. \cite[Lemma 3.1(vi)]{MR3920799}. Suppose that $\eta_1,\eta_2 \in \Gamma_x(\mathcal{I})$. Thanks to Theorem \ref{thm:Iclusterpoints}, there exists maximal ideals $\mathcal{J}_1, \mathcal{J}_2$ containing $\mathcal{I}$ such that $\mathcal{J}_1\text{-}\lim x=\eta_1$ and $\mathcal{J}_2\text{-}\lim x=\eta_2$. It follows by 
    %Lemma \ref{lem:fJallideals} 
    Theorem \ref{thm:secondrepresenation} 
    that $\eta_1=\eta_2$, hence $|\Gamma_x(\mathcal{I})|=1$. This implies that $x$ is $\mathcal{I}$-convergent, see e.g. \cite[Corollary 3.4]{MR3920799}, therefore $\mathscr{V}(\mathcal{I})\subseteq c(\mathcal{I}) \cap \ell_\infty$. 

    Viceversa, pick a sequence $x \in c(\mathcal{I}) \cap \ell_\infty$ and define $\eta:=\mathcal{I}\text{-}\lim x$. Of course, ${\mathcal{F}}\text{-}\lim x=\eta$ for every ultrafilter $\mathcal{F} \in \mathrm{Ult}(\mathcal{I})$. Pick also a $S_{\mathcal{I}}$-limit $f$. Thanks to Theorem \ref{thm:firstrepresenation}, there exists a normalized capacity $\rho: \mathscr{B}(\mathrm{Ult}(\mathcal{I}))\to \mathbf{R}$ which satisfies \eqref{eq:firstrepresetnation}. This implies that 
    $$
    f(x)=\int_{\mathrm{Ult}(\mathcal{I})} {\mathcal{F}}\text{-}\lim x \, \mathrm{d}\rho(\mathcal{F})
    =\int_{\mathrm{Ult}(\mathcal{I})} \eta \, \mathrm{d}\rho(\mathcal{F})=\eta, 
    $$
    so that $x \in \mathscr{V}(\mathcal{I})$. Hence $c(\mathcal{I}) \cap \ell_\infty\subseteq \mathscr{V}(\mathcal{I})$. 

    \smallskip

    For the second part, suppose that $\mathcal{I}$ is a $P$-ideal. Then $c(\mathcal{I})=c+c_{00}(\mathcal{I})$ (the case $\mathcal{I}=\mathcal{Z}$ can be found in \cite[Theorem 2.3]{MR954458}, the general case goes analogously). We conclude that $\mathscr{V}(\mathcal{I})=c(\mathcal{I})\cap \ell_\infty=(c+c_{00}(\mathcal{I}))\cap \ell_\infty=c+(c_{00}(\mathcal{I})\cap \ell_\infty)$. 
\end{proof}

\section{Further results}\label{sec:furtherresults}

As an application of Theorem \ref{thm:differenceSIlimits}, we can compute the distance of sequences in $\ell_\infty$ from the space of bounded $\mathcal{I}$-convergent sequences. To this aim, for each nonempty $Y\subseteq \ell_\infty$ and $x \in \ell_\infty$, define 
$$
\mathrm{dist}(x,Y):=\inf\{\|x-y\|: y \in Y\}.
$$
(The case $\mathcal{I}=\mathrm{Fin}$ of the next result can be found, e.g., in \cite[Proposition 1.18]{MR1727673}.)
\begin{prop}\label{prop:distance}
Let $\mathcal{I}$ be an ideal on $\omega$. Then 
\begin{equation}\label{eq:claimed}
\forall x \in \ell_\infty, \quad \mathrm{dist}(x,c(\mathcal{I}) \cap \ell_\infty)=\frac{1}{2}\left(\mathcal{I}\text{-}\limsup x-\mathcal{I}\text{-}\liminf x\right).
\end{equation}
\end{prop}
\begin{proof}
    Fix $x \in \ell_\infty$ and define $\eta_0:=\frac{1}{2}(\eta_++\eta_-)$ and $\delta_0:=\frac{1}{2}(\eta_+-\eta_-)$, where $\eta_+:=\mathcal{I}\text{-}\limsup x$ and $\eta_-:=\mathcal{I}\text{-}\liminf x$. Set also $Y:=c(\mathcal{I})\cap \ell_\infty$ and recall that $Y$ is closed, see e.g. Theorem \ref{thm:freedman}. If $x$ is a bounded $\mathcal{I}$-convergent sequence then both sides of \eqref{eq:claimed} are zero. Hence, we suppose hereafter that $x\notin Y$. 
    % (note that every is well defined since $\Gamma_x(\mathcal{I})$ is nonempty compact). %$y:=x-\eta_0e$

    On the one hand, it is known (and easy to check) that, if $y \in Y$ is $\mathcal{I}$-convergent to $\kappa$, then $\Gamma_{x-y}(\mathcal{I})=\Gamma_{x-\kappa e}(\mathcal{I})=\Gamma_x(\mathcal{I})-\kappa$, cf. also \cite[Proposition 3.2]{MR4428911} for a more general result in this direction. Hence 
    \begin{displaymath}
        \begin{split}
            \mathrm{dist}(x,Y) &\ge \inf\left\{ \max \{|\eta|:\eta \in \Gamma_{x-y}(\mathcal{I})\}: y \in Y \right\} \\
    &=\inf\{\max \{|\eta|:\eta \in \Gamma_{x}(\mathcal{I})-\kappa\}: \kappa \in \mathbf{R}\}\\
    &\ge \inf\{\max\{|\eta_+-\kappa|,|\eta_--\kappa|\}:\kappa\in \mathbf{R}\}\ge \delta_0.
        \end{split}
    \end{displaymath}

    On the other hand, it follows by a consequence of Hahn--Banach theorem that there exists $f \in \ell_{\infty}^{\,\prime}$ such that 
    $$
    \|f\|=1,\,\, f(x)=\mathrm{dist}(x,Y),\,\,\text{and}\,\, f[Y]=\{0\},
    $$
    see e.g. \cite[Theorem 2.3.22]{MR3823238}. 
    In particular, since $e \in Y$, we have $f(e)=0$. It follows by Theorem \ref{thm:differenceSIlimits} that there exists (unique) $g,h \in \mathrm{SL}(\mathcal{I})$ such that $2f=g-h$. Considering that $\eta_- \le w(x)\le \eta_+$ for every $w \in \mathrm{SL}(\mathcal{I})$, see Corollary \ref{cor:liminflimsup}, we obtain that 
    $\mathrm{dist}(x,Y)=f(x)=(g(x)-h(x))/2 \le (\eta_+-\eta_-)/2=\delta_0$. %This concludes the proof.  
    %
    %$$
    %\mathrm{dist}(x,Y)=f(x)=\frac{g(x)-h(x)}{2}\le 
    %\frac{\eta_+-\eta_-}{2}=\delta_0.
    %$$
    %On the other hand, for each $k \in \omega$, define $A_k:=\{n \in \omega: |x_n-\eta_0|\ge \delta_0(1+2^{-k})\}$, and note that $A_k \in \mathcal{I}$. For each $k \in \omega$, define the sequence $y^k\in Y$ by $y^k_n:=x_n$ if $n \in A_k$ and $y^k_n:=\eta_0$ otherwise. It follows that 
    %\begin{displaymath}
    %    \begin{split}
    %        \mathrm{dist}(x,Y) &\le \inf\{\|x-y^k\|: k \in \omega\}\\
    %        &=\inf\{\sup\{|x_n-\eta_0|: n \in \omega\setminus A_k\}: k \in \omega\}\\
    %        &\le \inf\{\delta_0(1+2^{-k}): k\in \omega\}=\delta_0.
    %\end{split}
