\begin{document}

\title{On Lower Bounds for the $F$-Pure Thresholds of Equigenerated Ideals}
\author{Benjamin Baily}
\thanks{The author was supported by NSF grant DMS-2101075 and NSF RTG grant DMS-1840234.}
\begin{abstract}
    Let $k$ be a field of characteristic $p > 0$ and $R = k[x_0,\dots, x_n]$. We consider ideals $I\subseteq R$ generated by homogeneous polynomials of degree $d$. Takagi and Watanabe proved that $\fpt(I)\geq \hgt(I)/d$; we classify ideals $I$ for which equality is attained. Additionally, we describe a new relationship between $\fpt(I)$ and $\fpt(I|_H)$, where $H$ is a general hyperplane through the origin. As an application, for degree-$d$ homogeneous polynomials $f\in R$ when $p \geq n-1$, we show that either $p$ divides the denominator of $\fpt(f)$ or $\fpt(f)\geq r/d$, where $r$ is the codimension of the singular locus of $f$.
    \end{abstract}
\maketitle
\section{Introduction}
The $F$-pure threshold, introduced by Takagi and Watanabe \cite{takagi_f-pure_2004}, is a numerical singularity invariant of pairs in positive characteristic. The $F$-pure threshold was proposed as a positive-characteristic analog of the log canonical threshold; whereas the log canonical threshold is widely studied in birational and complex-analytic geometry, the $F$-pure threshold better reflects the subtleties of singularities in prime characteristic.

We consider a pair $(R,I)$, where $R$ is a polynomial ring over a field and $I$ is generated by forms of degree $d$. In this setting, Takagi and Watanabe proved the following sharp lower bound on the $F$-pure threshold $\fpt(I)$:
\begin{prop}[\cite{takagi_f-pure_2004}, Proposition 4.2]\label{prop:tw-fpt-equigen}
    Let $k$ be a field of positive characteristic and set $R = k[x_0,\dots, x_n]$. Suppose $I\subseteq R$ is generated by forms of degree $d$. If $h$ is the height of $I$, then $\fpt(I)\geq h/d$.
\end{prop}
If we instead consider a field of characteristic $0$ and the log canonical threshold (lct), much more is known. We refer the reader to \cite{pragacz_impanga_2012} for background on log canonical singularities and the lct.
\begin{theorem}[\cite{de_fernex_bounds_2003}, Theorem 3.5]\label{thm:equigen-lct}
    Let $k$ be an algebraically closed field of characteristic zero and set $R = k[x_0,\dots, x_n]$. Suppose $I = (f_1,\dots, f_r)\subseteq R$ is generated by forms of degree $d$. Let $e$ denote the codimension of $Z$, where $Z$ is the non-klt locus of $(R, I^{\lct(I)})$. Then we have $\lct(I) \geq e/d$ with equality if and only if there exist independent linear forms $\ell_1,\dots, \ell_e\in R$ such that $Z = (\ell_1,\dots, \ell_e)$ and $f_i\in k[\ell_1,\dots, \ell_e]$ for all $1\leq i\leq r$. 
\end{theorem}
Our goal is to bridge the gap between \Cref{prop:tw-fpt-equigen} and \Cref{thm:equigen-lct}. As we show in \Cref{ex:naive-analog-failure}, a naive translation of \Cref{thm:equigen-lct} into characteristic $p$ is not true without an additional hypothesis. Towards the goal of bridging this gap, we contribute two results. The first is a classification of ideals for which the lower bound in \Cref{prop:tw-fpt-equigen} is sharp.
\begin{Theoremx}\label{thm:equigen-fpt}
    Let $k$ be an algebraically-closed field of characteristic $p>0$. Let $I$ be a homogeneous ideal in $k[x_0,\dots, x_n]$ generated by $d$-forms. If $h$ is the height of $I$, then $\fpt(I) = h/d$ if and only if $\overline{I} = (x_0,\dots, x_{h-1})^d$ up to change of coordinates.
\end{Theoremx}
The proof of \Cref{thm:equigen-fpt} goes as follows. First, we prove the claim in the case that $I$ is complete intersection of height $n$ (\Cref{lem:min-fpt-char-CI-height-n}). In this case, let $\pf$ be a minimal prime over $I$. Since $\pf$ is the ideal of a point in $\P^n$, we may change coordinates so that $\pf = (x_1,\dots, x_n)$. We then transform \Cref{lem:min-fpt-char-CI-height-n} to a statement about the graded system of monomial ideals $\{\ini_{>_{\text{lex}}}(I^m)\}_{m>0}$, which we solve using convex geometry. After applying estimates for the Hilbert series of powers of $I$ (\Cref{lem:hilb-fn-power-of-CI}), the result is a consequence of a 1960 result of Gr\"unbaum (\Cref{thm:grunbaum-ineq}).

To generalize beyond the case of a complete intersection, we note that $h := \hgt I$, then any general $d$-forms in $I$ generate a complete intersection $J\subseteq I$, and we show that $J$ is a reduction of $I$. To generalize beyond the case that $\hgt I = n$, we consider $I|_H$, where $H$ is a general hyperplane through the origin. By \Cref{prop:tw-fpt-equigen}, we have $h/d\leq \fpt(I|_H) \leq \fpt(I) = h/d$, so $\overline{I|_H} = (x_0,\dots, x_{h-1})^d$. By \Cref{prop:ess-dim-general-linear-space}, we deduce that $I$ has the same form.

Our second contribution is a lower bound on $\fpt(R,f)$ in terms of the codimension of the singular locus of $f$. Compare with \cite[Theorem 1.1]{ein_log_2001}, a preprint which was later superseded by \cite{de_fernex_bounds_2003}.
\begin{Theoremx}\label{thm:smooth-lowbound}
    Suppose $\char k = p>0$ and $R = k[x_0,\dots, x_n]$. Suppose that $f\in R$ is homogeneous of degree $d$, that $f$ is smooth in codimension $c$, and that $p$ does not divide the denominator of $\fpt(f)$. Further suppose that $c\geq n$ or $p\geq c$. Then $\fpt(f)\geq \min(c/d,1)$.
\end{Theoremx}
In the case that $h\geq n$, we observe that $(R, f^{\fpt(f)})$ has an $F$-pure center which is a monomial ideal and apply a Fedder-type criterion from \cite{schwede_centers_2010} (\Cref{lem:sharp-at-threshold}). When $h < n$, we reduce to the case $h = n$ by intersecting with a general hyperplane through the origin and applying the following Bertini theorem for $F$-purity:
\begin{Theoremx}\label{thm:F-bertini}
    Let $k$ be an infinite field of characteristic $p > 0$. Let $R = k[x_0,\dots, x_n]$. Let $I\subseteq R$ be an ideal generated by forms of degree at most $d$. Let $H\in \PNV$ be a general hyperplane through the origin. Then for all $0\leq t < \frac{n}{d} - \frac{n-1}{pd}$, the pair $(R, I^t)$ is sharply $F$-split if and only if $(H, I^t|_H)$ is sharply $F$-split. 
\end{Theoremx}
A Bertini theorem for $F$-purity of pairs is already known \cite[Theorem 6.1]{schwede_bertini_2013}. Schwede and Zhang's result, however, considers a general member of a free linear system, whereas \Cref{thm:F-bertini} considers a general member of a linear system with $0\in \A^{n+1}$ as a base point. To ensure that neither \cite[Theorem 6.1]{schwede_bertini_2013} nor \Cref{thm:F-bertini} implies the other, we demonstrate in \Cref{ex:exponent-optimality} that the exponent $\frac{n}{d} - \frac{n-1}{pd}$ is optimal. 
\section{Preliminaries}
\subsection{The \texorpdfstring{$F$}{F}-Pure Threshold}
For detailed background on the $F$-pure threshold, we direct the reader to \cite{schwede_sharp_2008,takagi_f-pure_2004}. In this subsection, we summarize several key definitions and results.
\begin{defn}
    Let $R$ be a ring of characteristic $p>0$. We let $F_*R$ denote the $R$-module structure on $R$ given by restriction of scalars along the Frobenius map $F:R\to R$. We say $R$ is $F$-finite if $F_*R$ is module-finite over $R$. 
\end{defn}
\begin{defn}[\cite{schwede_sharp_2008}]
    Let $R$ be an $F$-finite ring, $I\subseteq R$ an ideal, and $t\in\R^+$. The pair $(R, I^t)$ is \textit{sharply $F$-split} if for some (equivalently, infinitely many) $e>0$, the map
    \[
    I^{\ceil{t(p^e-1)}}\cdot \Hom(F^e_*R, R)\to R
    \]
    is surjective. 
\end{defn}
\begin{defn}[\cite{takagi_f-pure_2004}]
    The \textit{$F$-pure threshold} of the pair $(R,I)$ is the supremum of all $t$ such that $(R, I^t)$ is sharply $F$-split. We denote this quantity by $\fpt(R, I)$, or $\fpt(I)$ when the ambient ring is clear. 
\end{defn}
In practice, the following proposition is a more useful characterization of the $F$-pure threshold.
\begin{prop}
    Let $(R,\mf)$ be an $F$-finite regular local ring. Then the $F$-pure threshold of the pair $(R, I^t)$ is equal to
    \[
    \sup\left\{\frac{\nu}{p^e}: I^\nu\notin \mf^{[p^e]}\right\}.
    \]
    In fact, let $\nu_I(p^e) = \max\{r: I^r\notin \mf^{[p^e]}\}$. Then the $F$-pure threshold of $(R, \af)$ is equal to the limit $\lim_{e\to\infty}\nu_I(p^e)/p^e$. If instead $R$ is a polynomial ring over an $F$-finite field and $I\subseteq R$ a homogeneous ideal, then the same results hold when we let $\mf$ denote the homogeneous maximal ideal of $R$.
\end{prop}
\begin{proof}
    The first claim follows from \cite[Lemma 3.9]{takagi_f-pure_2004}. The existence of the limit is \cite[Lemma 1.1]{mustata_f-thresholds_2004}. For the graded setting, see \cite[Proposition 3.10]{de-stefani_graded_2018}.
\end{proof}
\begin{prop}[Properties of the $F$-pure threshold]\label{prop:fpt-properties}
    Let $R$ be a reduced, $F$-finite, $F$-pure ring of characteristic $p>0$. Then for all ideals $I\subseteq R$ such that $I$ contains a nonzerodivisor, we have
    \begin{enumerate}[(i)]
        \item If $I\subseteq J$, then $\fpt(I)\leq \fpt(J)$.
        \item For all $m > 0$, we have $\fpt(I^m) = m^{-1}\fpt(I)$.
        \item We have $\fpt(I) = \fpt(\bar{I})$, where $\bar{I}$ denotes the integral closure of $I$. 
    \end{enumerate}
\end{prop}
\begin{proof}
    See \cite[Proposition 2.2]{takagi_f-pure_2004} (1), (2), (6).
\end{proof}
\begin{prop}\label{prop:semicont}
    Let $R = k[x_0,\dots, x_n]$. Let $>$ be a monomial order. Let $I\subseteq R$ be an ideal, and $\ini_>(I)$ the initial ideal of $I$ with respect to $>$. Then $\fpt(\ini_>(I))\leq \fpt(I).$
\end{prop}
\begin{proof}
    See \cite{takagi_f-pure_2004}, the claim preceding Remark 4.6.
\end{proof}
\subsection{Newton Polytopes of Monomial Ideals}
When working with monomial ideals, one often identifies a monomial $x_0^{a_0}\cdots x_n^{a_n}$ with the point $(a_0,\dots, a_n)\in \Z_{\geq 0}^{n+1}$. For future reference, it will help to give a name to this identification.
\begin{defn}
    Let $k$ be a field. We define the map 
    \[\log: \{\text{monomials in }k[x_0,\dots, x_n]\}\to \Z_{\geq 0}^{n+1},\qquad\log(x_0^{a_0}\cdots x_n^{a_n}) = (a_0,\dots, a_n).\]
\end{defn}
\begin{defn}
    Let $\af\subseteq k[x_0,\dots, x_n]$ be a monomial ideal. Then the \textit{Newton Polytope} of $I$, denoted $\Gamma(\af)$, is the convex hull in $\R^{n+1}$ of $\log(\af)$. Later on, we will let $\conv(-)$ denote the convex hull of a set.
\end{defn}
\begin{remark}
    We record several properties of $\Gamma(\af)$.
    \begin{enumerate}[(i)]
        \item $\Gamma(\af)$ is a closed, convex, unbounded subset of the first orthant of $\R^{n+1}$.
        \item When $\af$ is an $\mf$-primary ideal, the complement of $\Gamma(\af)$ inside the first orthant is an open, bounded polyhedron.
        \item For two ideals $\af, \bfr$, the Minkowski sum of $\Gamma(\af)$ and $\Gamma(\bfr)$ is equal to $\Gamma(\af\bfr)$. In particular, $\Gamma(\af^n) = n\Gamma(\af)$.
    \end{enumerate}
\end{remark}
For the proof of \Cref{thm:equigen-fpt}, we will also require the following.
\begin{defn}\label{defn:simplex}
    We define the standard $n$-simplex $\Delta_n\subseteq \R^{n+1}$ as follows:
    \[
    \Delta_n = \{(a_0,\dots, a_n): 0\leq a_i, a_0 +\dots + a_n = 1.\}
    \]
\end{defn}
\begin{defn}
    Let $I\subseteq k[x_0,\dots, x_n]$ be a homogeneous ideal and $t\in \Z^+$. We let $[I]_t$ denote the vector space of $t$-forms in $I$.
\end{defn}
\begin{defn}\label{defn:gamma-a-t}
    Let $\af\subseteq k[x_0,\dots, x_n]$ be a monomial ideal and $t\in \Z^+$. We define $\Gamma(\af, t)$ as the convex hull of $\log([\af]_t)$, and we let $\gamma(\af, t)$ denote the relative interior of $\Gamma(\af, t)$ inside $t\Delta_n$. 
\end{defn}
\begin{remark}
    It is sometimes the case that $\Gamma(\af,t)\subsetneq \Gamma(\af)\cap t\Delta_n$, even if $\af$ is integrally closed. Consider $\af = (x_0,x_1^3)$ as an ideal of $k[x_0,x_1]$; we have $(0.5, 1.5)\in (\Gamma(\af)\cap 2\Delta_1)\setminus \Gamma(\af, 2)$.
\end{remark}
The following proposition shows that Newton polytope of a monomial ideal determines the $F$-pure threshold.
\begin{prop}[\cite{hernandez_f-purity_2016}, Proposition 36]\label{prop:monomial-fpt}
     Let $\af\subseteq  k[x_0,\dots, x_n]$ be a monomial ideal. Then 
     \[
     \fpt(\af) = \frac{1}{\mu}\text{, where }\mu = \inf\{t: t\vec{1}\in \Gamma(\af)\}.
     \]
\end{prop}
Following the proof of \cite{de_fernex_multiplicities_2004}, Theorem 1.4 and the terminology of \cite{mayes_limiting_2014}, we also define the \textit{limiting polytope} of a graded system of monomial ideals.
\begin{defn}
    Let $\af_\bullet$ be a graded system of monomial ideals. That is, suppose $\af_r\af_s\subseteq \af_{r+s}$ for all $r,s\in \Z^+$. We define $\Gamma(\af_\bullet)$ as the closure in $\R^{n+1}$ of the ascending union $\{\frac{1}{2^m}\Gamma(\af_{2^m})\}_{m>0}$. 
\end{defn}
\begin{defn}
    Let $>$ be a monomial order on $R$. We set $\Gamma_>(I) = \Gamma(\af_\bullet)$, where $\af_n = \ini_>(I^n)$. 
\end{defn}

\subsection{Essential Codimension}
    \begin{defn}[Essential Codimension]\label{defn:ess-dim}
        Let $J\subseteq R = k[x_0,\dots, x_n]$ be a homogeneous ideal. The essential codimension $\ess(J)$ is equal to the minimal $r$ for which there exist linear forms $\ell_1,\dots, \ell_r$ such that $J$ is extended from $I\subseteq k[\ell_1,\dots, \ell_r]$. 
    \end{defn}
    \begin{lemma}\label{lem:ess-dim-sanity-check}
        Let $I, J, \ell_1,\dots, \ell_r$ be as in \Cref{defn:ess-dim}. Then $\ess(I) = r$.
    \end{lemma}
    \begin{proof}The bound $\ess(I)\leq r$ is immediate. Conversely, if $I$ is extended from an ideal $I'\subseteq k[\ell'_1,\dots, \ell'_s]\subseteq k[\ell_1,\dots, \ell_r]$, then $J$ is extended from the same ideal, so $\ess(J)\leq \ess(I)$.
    \end{proof}
\section{Classification of Minimal \texorpdfstring{$F$}{F}-Pure Thresholds}
\subsection{A Bertini Theorem for Essential Codimension}
\begin{convention}
    We identify $\PNV$ with the space of hyperplanes passing through $0\in \A^{n+1}$, as opposed to the usual convention of identifying $\PNV$ with the space of hyperplanes in $\P^n$.
\end{convention}
The following standard lemma relates the condition $\ess(J) < n+1$ to a more familiar condition. 
\begin{lemma}\label{lem:cone-condition}
    Let $k$ be an algebraically-closed field, $R = k[x_0,\dots, x_n]$, and $J \subseteq R$ an ideal generated by $d$-forms $f_1,\dots, f_r$. Then $\ess(J)\leq n$ if and only if there exists $p\in \mathbb P^n$ such that $J \subseteq \mf_p^d$.
\end{lemma}
\begin{proof}
    If $\ess(J) \leq n$, then there exist $\ell_1,\dots, \ell_n\in R_1$ such that $J$ is extended from $k[\ell_1,\dots, \ell_n]$. Setting $p = [(\ell_1,\dots, \ell_n)]$, we have $J\subseteq \mf_p^d$. Conversely, suppose $p\in \P^n$ such that $J\subseteq \mf_p^d$ and change coordinates so that $\mf_p = (x_1,\dots, x_n)$. In this case, no monomial summand of the $f_i$ involves $x_0$, so $J$ is extended from $k[x_1,\dots, x_n]$.
\end{proof}
\begin{lemma}\label{lem:maximal-ess-dim-section}
    Let $k$ be an algebraically-closed field, $R = k[x_0,\dots, x_n]$, and $J \subseteq R$ a nonzero ideal generated by $d$-forms $f_1,\dots, f_r$. Suppose $\ess(J) = n+1$. Then for general $H\in \PNV$, we have $\ess(J|_H) = n$.
\end{lemma}
\begin{proof}
    Set $Z = \text{Proj}(R/J)\subseteq \P^n$. We define an incidence correspondence as follows:
    \[
    B = \{(z, H)\in Z\times \PNV: z\in H, f_i|_H \in \mf_z^d\text{ for all }1\leq i\leq r\}.
    \]
    Let $p: B\to Z, q: B\to \PNV$ be the projections. Fix $z\in Z$ and change coordinates so that $z = [0:\dots :0:1]$. Write $f_i =: g_i + x_nh_i$ for $g_i\in \mf_z^d, h_i\in \mf^{d - 1}$. Let $(z,H)\in B_z$ where $H = V(\ell)$. Then there exist $g'_i\in \mf_z^{d}, h'_i\in \mf^{d-1}$ such that $g_i + x_nh_i = g'_i + \ell h'_i$. Write $h'_i =: g''_i + x_nh''_i$, where $g_i''\in \mf_z^{d-1}$. Then $x_n(h_i - \ell h''_i) = g'_i + \ell g''_i - g_i \in \mf_z^d$, so $h_i - \ell h''_i = 0$. In particular, $\ell\mid h_i$. It follows that $B_z = \{(z, V(\ell): \ell\mid h_i \text{ for all }1\leq i\leq r\}$. By assumption, $\ess(J) = n+1$. Since $\ess(J) = n+1$, by \Cref{lem:cone-condition} we have $h_i\neq 0$ for some $i$. As each $h_i$ has at most $d-1$ linear factors, we must have $|B_z| \leq d-1 < \infty$.

By the previous paragraph, every closed fiber $B_z$ is zero-dimensional, so $\dim B\leq \dim Z$. Consequently, $\dim q(B)\leq \dim B \leq \dim Z < n$, so $q(B)$ is a proper closed subset of $\PNV$, and so for general $H\in \PNV$, there is no $z\in Z$ such that $(z,H)\in B$. Consequently, there is no $z\in Z\cap H$ such that $f_i \in \mf_z^d|_H$ for all $i$, so another application of \Cref{lem:cone-condition} gives $\ess(J|_H) = n$.
\end{proof}
The following proposition describes the behavior of essential codimension under restriction to a general linear subspace through the origin.
\begin{prop}\label{prop:ess-dim-general-linear-space}
    Let $k$ be an algebraically-closed field, $R = k[x_0,\dots, x_n]$, and $J \subseteq R$ a homogeneous ideal. Set $r = \hgt(J)$. Let $L = (\ell_{r+1},\dots, \ell_n)$, where the $\ell_i$ are chosen generally. For $r\leq t\leq n$, set $L_t = (\ell_{t+1}, \dots, \ell_n)$ and $J_t= \frac{J+L_t}{L_t}$. Then for all $r\leq t\leq n$, we have $\ess(J_t) = \max(t+1, \ess(J))$.
\end{prop}
\begin{proof}
By induction, it suffices to consider the case $t = n-1$. The case $\ess(J) = n+1$ is covered by \Cref{lem:maximal-ess-dim-section}; it remains to show that $\ess(J_{n-1}) = \ess(J)$ provided $\ess(J)\leq n$. Set $s = \ess(J)$ and change coordinates so that $J$ is extended from an ideal $I\subseteq k[x_0,\dots, x_{s-1}]$. Suppose $s \leq n$. Let $I' = Ik[x_0,\dots, x_{n-1}]$. By \Cref{lem:ess-dim-sanity-check}, we have $\ess(I') = \ess(I) = \ess(J)$. The isomorphism $k[x_0,\dots, x_n]/(\ell_n) \cong k[x_0,\dots, x_{n-1}]$ identifies $J_{n-1}$ with $I'$, so $\ess(J_{n-1}) = \ess(I') = \ess(J)$. 
\end{proof}
\subsection{An Application of Gr\"unbaum's Inequality}
\begin{defn}
    Let $K\subseteq \R^n$ be a compact set with $\vol(K) > 0$. The \textit{centroid} $c$ of $K$ is the arithmetic mean of the points of $K$.
    \[
    c = \left(\int_{y\in K}dy\right)^{-1}\int_{y\in K}ydy.
    \]
\end{defn}
We first recall Gr\"unbaum's inequality, for which we state an equivalent version below. 
\begin{theorem}[\cite{grunbaum_partitions_1960}, Theorem 2]\label{thm:grunbaum-ineq}
    Let $K\subseteq \R^n$ be a convex body and let $c$ denote the centroid of $K$. Let $H^+$ be a half-space whose boundary hyperplane $H$ contains $c$. Then \[\vol(H^+\cap K) \leq \left(1 - \left(\frac{n}{n+1}\right)^n\right)\vol(K).\]
\end{theorem}
\begin{defn}
    We let $\Mmc_n$ denote the quantity $\left(1 - \left(\frac{n}{n+1}\right)^n\right)$ from the theorem.
\end{defn}
For our purposes, we must characterize the equality case of \Cref{thm:grunbaum-ineq}. 
\begin{prop}\label{prop:grunbaum-eq-classification}
    Suppose $H^+,H, K$ are as in \Cref{thm:grunbaum-ineq}, with $\vol(K) > 0$ and $\vol(H^+\cap K) = \Mmc_n\vol(K)$. Let $H$ denote the boundary hyperplane of $H^+$. Then there exists a convex body $K'\subseteq H^+\cap K$ and a point $q\in K\setminus H^+$ such that $K'$ is contained in a hyperplane parallel to $H$ and $K = \conv(K'\cup \{q\})$.  
\end{prop}
\begin{proof}
    Follows from \cite{myroshnychenko_grunbaums_2018}, Corollary 8.
\end{proof}
\begin{defn}\label{defn:pi_n-and-T_n}
    Let $\pi_n: \R^{n+1}\to \R^n$ denote the projection onto the first $n$ coordinates and let $T_n:= \pi_n(\Delta_n)$.
\end{defn}
\begin{lemma}\label{lem:grunbaum-eq-for-simplices}
    Let $T_n:= \pi_n(\Delta_n)$. Let $z_n = (\frac{1}{n+1},\dots, \frac{1}{n+1})$ denote the centroid of $T_n$. Let $H^+$ be a half-space whose boundary hyperplane $H$ contains $z_n$. Then \[\vol(H^+\cap T_n) \leq \frac{\Mmc_n}{n!}\] with equality if and only if $H$ is parallel to a facet $F$ of $T_n$ with $F\subseteq H^+$.
\end{lemma}
\begin{proof}
    If $K'$ is an $n-1$-dimensional convex set and $q$ a point not contained in the hyperplane supporting $K'$ such that $\conv(K'\cup \{q\})$ is a polytope, then $K'$ is a facet of $\conv(K'\cup \{q\})$. The result therefore follows from \Cref{prop:grunbaum-eq-classification}.
\end{proof}
We recall the following standard fact from convex analysis:
\begin{lemma}[\cite{Rockafellar_1970}, Corollary 11.6.1]\label{lem:supporting-hyperplane}
    Let $K\subseteq \R^n$ be a convex set and $x\in \del K$. Then there exists a half-space $H^+$ such that $K\subseteq H^+$ and such that $x\in \del H^+$.
\end{lemma}
\begin{lemma}\label{lem:vol-upper-bound}
    Let $P\subseteq T_n$ be a closed convex set with $z_n\notin \text{int} P$. Then $\vol(P) \leq \Mmc_n/n!$ with equality if and only if $P$ is the intersection of $T_n$ with a half-space satisfying the conditions of \Cref{lem:grunbaum-eq-for-simplices}.
\end{lemma}
\begin{proof}
    If $z_n\notin \del P$, then for $0 < \varepsilon \leq \text{dist}(P, z_n)$, the set $\{x\in T_n: \text{dist}(x,P) < \varepsilon\}$ is a strictly larger convex set which does not contain $z_n$ in its interior. We may therefore assume $z_n\in \del P$. By \Cref{lem:supporting-hyperplane}, we may replace $P$ by $H^+\cap T_n$, where $H^+$ is the half-space containing $P$ with $z_n\in \del H^+$. In this case, the result is immediate from \Cref{lem:grunbaum-eq-for-simplices}.
\end{proof}
\subsection{Proof of Theorem \texorpdfstring{\ref{thm:equigen-fpt}}{A}}
To start, we recall a theorem of Rees.
\begin{theorem}[\cite{huneke_integral}, Proposition 11.2.1, Theorem 11.3.1]\label{thm:Rees}
    Let $(R,\mf)$ be a formally equidimensional local ring and $I\subseteq J$ two $\mf$-primary ideals. Then $e(I) = I(J)$ if and only if $\bar{I} = \bar{J}$. 
\end{theorem}
The conclusion of \Cref{thm:Rees} also holds when $R$ is a polynomial ring, $\mf\subseteq R$ a maximal ideal, and $I,J$ two $\mf$-primary ideals. As a consequence, we may restate the conclusion of \Cref{thm:equigen-fpt} in terms of essential dimension.
\begin{lemma}\label{lem:ess-dim-equals-height}
    Let $R = k[x_0,\dots, x_n]$ and $I\subseteq R$ an ideal generated by $d$-forms. If $\hgt(I) = h$, then the following are equivalent:
    \begin{enumerate}[(i)]
        \item  $\ess(I) = h$.
        \item $\overline{I} = (x_0,\dots, x_{h-1})^d$ up to change of coordinates. 
        \item $I\subseteq (x_0,\dots, x_{h-1})^d$ up to change of coordinates. 
    \end{enumerate}
\end{lemma}
\begin{proof}\mbox{}
\begin{itemize}
    \item[(i)$\implies$(ii):] Up to change of coordinates, $I$ is extended from an ideal $I'\subseteq k[x_0,\dots, x_{h-1}]=:R'$. By flatness of $R'\hookrightarrow R$, we have $\hgt(I') = h$. Let $\mf'$ denote the homogeneous maximal ideal of $R'$. Let $S' = \overline{k}[x_0,\dots, x_{h-1}]$. If $J'\subseteq I'S'$ is generated by $h$ general $d$-forms in $I'S'$, then $J'$ is a $(d,\dots, d)$-complete intersection of height $h$. We have $e(J') = d^h = e((\mf')^d)$, so $\overline{J'} = \overline{(\mf'S')^d}$ by \Cref{thm:Rees}. As $I\subseteq (\mf'S')^d\subseteq \overline{I}$ and $(\mf'S')^d$ is integrally closed, we have $\overline{I'} = (\mf'S')^d$. By faithful flatness of $R'\to S'$, we have $\overline{I'} = \overline{I'S'}\cap R' = (\mf')^d$. Passing back to the ring $R$, the ideal $(\mf')^dR$ is integrally closed and $I\subseteq (\mf')^dR = \overline{I'}R \subseteq \overline{I}$, hence $\overline{I} = (\mf')^dR$.
    \item[(ii)$\implies$(iii):] This follows from the containment $I\subseteq \overline{I}$.
    \item[(iii)$\implies$(i):] This follows from the argument of \Cref{lem:cone-condition}.
\end{itemize}
\end{proof}
We state the main technical lemma of this section.
\begin{lemma}\label{lem:min-fpt-char-CI-height-n}
    Let $k$ be an algebraically-closed field of characteristic $p>0$ and let $R = k[x_0,\dots, x_n]$. Let $I = (f_1,\dots, f_n)\subseteq R$ denote a complete intersection ideal generated by $d$-forms. Then $\fpt(I) = n/d$ if and only if $\ess(I) = n$.
\end{lemma}
We begin with a computation of the Hilbert series of $R/I^s$.
\begin{lemma}\label{lem:hilb-fn-power-of-CI}
    Let $I,R$ be as in \Cref{lem:min-fpt-char-CI-height-n}. For $t \geq (d-1)n + d(s-1)$, we have $H_R(R/I^s, t) = \binom{n+s-1}{n}d^n$. In particular, this holds for $t\geq d(s+n)$.
\end{lemma}
\begin{proof}
    We define 
    \[\Lc_{n,s}:= \{(a_1,\dots, a_n): a_i\geq 0, a_1 + \dots + a_n \leq s-1\}.\]
    By \cite{guardo_powers_2005}, Corollary 2.3, we have 
    \begin{equation}\label{eqn:hilb-fn-formula}
    H_R(R/I^s, t) = \sum_{(a_1,\dots, a_r)\in \Lc_{n,s}}H_R(R/I, t - d(a_1+\dots +a_n)).\end{equation}
    The Hilbert series of $R/I$ is given by 
    \begin{equation}\label{eqn:hilb-series-of-CI}
    \sum_{i\geq 0}H_R(R/I,i)t^i =\frac{(1-t^d)^n}{(1-t)^{n+1}} = (1+t+\dots + t^{d-1})^n(1+t+t^2+t^3 + \dots),
    \end{equation}
    hence $H_R(R/I, t) = d^n$ for $t\geq (d-1)n$. By \Cref{eqn:hilb-fn-formula,eqn:hilb-series-of-CI}, for $t \geq (d-1)n + d(s-1)$ we have 
    \[H_R(R/I^s, t) = |\Lc_{n,s}|d^n = \binom{n + s - 1}{n}d^n.\]
\end{proof}
\begin{lemma}\label{lem:fpt-relint-bound}
    Let $\af\subseteq R$ be a monomial ideal containing a monomial $m$ of degree $t$. For any $t'>t$, if $\frac{t'}{n+1}\vec 1\in \gamma(\af, t')$, then $\fpt(\af) > \frac{n+1}{t'}$.
\end{lemma}
\begin{proof}
    Set $y = \log(m)$. By convexity of $\Gamma(\af)$, we have $\l y + (1-\l)\gamma(\af, t')\subseteq \Gamma(\af)$ for all $\l \in [0,1]$. Taking $0 < \l \ll 1$, we obtain $\frac{\l t + (1-\l)t'}{n+1}\vec{1}\in \Gamma(\af)$, which implies $\fpt(\af)\geq \frac{n+1}{\l t + (1-\l)t'} > \frac{n+1}{t'}$ by \Cref{prop:monomial-fpt}.
\end{proof}
Lastly, we need a result relating volume and integer point counts for convex bodies.
\begin{lemma}\label{lem:vol-lower-bound}
    Let $\Delta_n, T_n, \pi_n$ be as in \Cref{defn:simplex,defn:pi_n-and-T_n}. For $t\in \Z^+$ and $P\subseteq t\Delta_n$ a convex set, we have 
    \begin{equation}\label{eqn:lattice-pt-vol}
    |\vol_n(\pi_n(P)) -  \#(P\cap \Z^{n+1})| \leq \sum_{i=1}^{n-1}\frac{t^i}{i!}.\end{equation}
\end{lemma}
\begin{proof} 
Since $t\Delta_n$ is contained in the affine space $x_0 + \dots + x_n = t$ and $t\in \Z^+$, $\pi_n$ induces a bijection between $t\Delta_n\cap \Z^{n+1}$ and $T_n\cap \Z^n$, so \Cref{eqn:lattice-pt-vol} can be interpreted as a statement relating the volume and integer point count of $\pi_n(P)$. For each $P'$ occurring as an $i$-dimensional projection of $\pi_n(P)$ onto an $i$-dimensional coordinate axis, $\frac{1}{t}P'$ is contained in an $i$-dimensional simplex, so we have $\vol_i(P')\leq \frac{t^i}{i!}$. The result then follows from \cite{davenport_principle_1951}.\end{proof}

We now prove \Cref{lem:min-fpt-char-CI-height-n}.
\begin{proof}
    Let $\pf$ be a minimal prime over $I$. Since $k = \bar{k}$ and $I$ is homogeneous, we may change coordinates so that $\pf = (x_1,\dots, x_n)$. Let $>$ denote the lexicographic order and define the graded system of ideals $\af_\bullet = \{\ini_>(I^{nm})\}_m$. Since $\pf^r$ is a monomial ideal for all $r\geq 0$ and $I^r\subseteq \pf^r$, we have $\af_m\subseteq \pf^{nm}$ for all $m\geq 0$. Since $\af_\bullet$ is graded, we have for any $t\in \Z^+$
    \[
    [\af_{2^m}]_{2^mt}[\af_{2^m}]_{2^mt} \subseteq [\af_{2^m} \af_{2^m}]_{2^{m+1}t} \subseteq  [\af_{2^{m+1}}]_{2^{m+1}t}.
    \]
    It follows that $\{\frac{1}{2^m}\gamma(\af_{2^m}, 2^mt)\}_m$ is an ascending chain of convex subsets of $H_t$. We then set $t = d(n+1)$ and let $\Pc$ denote the ascending union $\bigcup_{m\geq 1}\gamma(\af_{2^m}, 2^md(n+1))$. If $d\vec 1\in \Pc$, there exists some $m$ such that $d\vec 1\in \gamma(\af_{2^m}, 2^md(n+1))$. By \Cref{lem:fpt-relint-bound}, we have $\fpt(\af_{2^m}) > \frac{n+1}{2^md(n+1)} = \frac{1}{2^md}$, so $\fpt(I) > n/d$ by \Cref{prop:fpt-properties}.

    Conversely, suppose $d\vec 1\notin \Pc$. Then for all $m$, we have $d\vec 1\notin \frac{1}{2^m}\gamma(\af_{2^m}, 2^md(n+1))$. By \Cref{lem:vol-upper-bound}, we have 
    \begin{equation}
        \vol(\Pc) = \lim_{m\to\infty}\vol\left(\frac{1}{2^m}\gamma(\af_{2^m}, 2^md(n+1))\right) \leq (d(n+1))^n \frac{\Mmc_n}{n!}.
    \end{equation}
    We now derive a lower bound for $\vol(\Pc)$. First, by \Cref{lem:hilb-fn-power-of-CI}, we have
    \begin{align*}
        \#\Z^{n+1}\cap (\gamma(\af_{2^m}, 2^md(n+1))) & \geq H_R(\af_{2^m}, 2^md(n+1)) 
        \\&= H_R(I^{2^mn}, 2^md(n+1)) 
        \\ &= \binom{n + 2^md(n+1)}{n} - \binom{n + 2^mn - 1}{n}d^n
    \end{align*}
    provided $2^md(n+1) \geq d(2^mn + n)$, which is satisfied for all $m\geq \log_2 n$. Using the approximation $\binom{a + b}{b} = \frac{a^b}{b!} + O_b(a^{b-1})$, we have
    \begin{equation}\label{eqn:lattice-pt-est}
    \#\Z^{n+1}\cap (\gamma(\af_{2^m}, 2^md(n+1))) \geq \frac{(2^md)^n}{n!}\left((n+1)^n - n^n\right) + O_n(2^{m(n-1)})
    \end{equation}
    Combining the bounds \Cref{lem:vol-lower-bound,eqn:lattice-pt-est}, we have
    \begin{align*}
        \vol(\Pc) &= \lim_{m\to\infty}\vol\left(\frac{1}{2^m}\gamma(\af_{2^m}, 2^md(n+1))\right) = \lim_{m\to\infty}\frac{1}{2^{mn}}\vol(\gamma(\af_{2^m}, 2^md(n+1)))\\
        &\geq \lim_{m\to\infty} \frac{1}{2^{mn}}\left(\#(\Z^{n+1}\cap \gamma(\af_{2^m},2^md(n+1)) - \sum_{i=1}^{n-1}\frac{(2^md(n+1))^i}{i!} \right)
        \\& \geq \lim_{m\to\infty} \frac{1}{2^{mn}}\left(\frac{(2^md)^n}{n!}\left((n+1)^n - n^n\right) + O_n(2^{m(n-1)})\right)\\&= (d(n+1))^n\frac{\Mmc_n}{n!}.
    \end{align*}
    It follows that $\vol(\Pc) = \vol(\overline{\Pc})= (d(n+1))^n\frac{\Mmc_n}{n!}$, so by \Cref{lem:grunbaum-eq-for-simplices}, we have $\overline{\Pc}=H^+\cap (d(n+1))\Delta_n$. Moreover, the boundary hyperplane $H$ of $H^+$ is parallel to a facet $F$ of $(d(n+1))\Delta_n$ with $F\subseteq H^+$ and $d(n+1)\eta_n\in H$. 

    For $\a\in \R$, define $D_{t,\b} = \{(a_0,\dots, a_n)\in t\Delta_n: a_0 \leq \b\}$. Since $\af_m\subseteq \pf^{mn}$, for any monomial $x_0^{a_0}\dots x_n^{a_n}\in (\af_m)_t$, we have $a_1+\dots+a_n \geq mn$ and hence $a_0\leq t - mn$. In particular, for all $m\geq 0$ we have
    \[
    \gamma(\af_{2^m}, 2^md(n+1))\subseteq D_{2^md(n+1), 2^mn(d+1) - 2^mn}.
    \]
    As a consequence, we conclude $\Pc\subseteq D_{d(n+1), d(n+1) - n}$. As $F\subseteq \Pc$, the only possible choice for $F$ is the facet $\{a_0 = 0\}\subseteq d(n+1)\Delta_n$. We conclude that $\overline{\Pc} = D_{d(n+1), d}$. We then have \[\Gamma(\af_1, d(n+1))\subseteq \overline{\Pc} = D_{d(n+1),d} = \Gamma(\pf^{nd}, d(n+1)),\] so $[\af_1]_{d(n+1)}\subseteq [\pf^{nd}]_{n(d+1)}.$ For each generator $f_i$ of $I$, we have $x_0^d\ini_>(f_i^n)\in [\af_1]_{d(n+1)}\subseteq [\pf^{nd}]_{n(d+1)}$, so $x_0\nmid \ini_>(f_i^n)$ for all $i$. As $\ini_>(f_i^n) = \ini_>(f_i)^n$, we deduce that $I\subseteq \pf^d$. By \Cref{lem:ess-dim-equals-height}, we have $\ess(I) = n$.
\end{proof}
We are now able to prove \Cref{thm:equigen-fpt}. By \Cref{lem:ess-dim-equals-height}, it suffices to prove the following.
\begin{theorem*}[\ref{thm:equigen-fpt}]
    Let $k$ be an algebraically-closed field of characteristic $p>0$. Let $I$ be a homogeneous ideal in $k[x_0,\dots, x_n]$ generated by $d$-forms and set $h = \hgt(I)$. Then $\fpt(I) = h/d$ if and only if $\ess(I) = h$.
\end{theorem*}
\begin{proof}
    Let $k$ be an algebraically-closed field and $R = k[x_0,\dots, x_n]$. Let $I\subseteq R$ be an ideal generated by $d$-forms, and suppose that $\hgt(I) = n, \fpt(I) = n/d$. If $f_1,\dots, f_n$ are $n$ general $d$-forms in $I$, then $J = (f_1,\dots, f_n)$ is a complete intersection. By \Cref{prop:tw-fpt-equigen} and \Cref{prop:fpt-properties} (i), we have
    \[
    n/d \leq \fpt(J)\leq \fpt(I) = n/d.
    \]
    By \Cref{lem:min-fpt-char-CI-height-n,lem:ess-dim-equals-height}, we may change coordinates on $R$ such that $\bar{J} = (x_1,\dots, x_n)^d$. Then we have $(x_1,\dots, x_n)^d\subseteq \bar{I}$. Let $>$ denote the lexicographic order, and let $g$ be a $d$-form in $\bar{I}$. Write $\ini_>(g) = x_0^{a_0}\cdots x_n^{a_n}$, and note that $(x_1,\dots, x_n)^d\subseteq \ini_>(\overline{I})$. Set $a = \max_i a_i$. Then
    \[
    \ini_>(g)^{\floor{(p^e-1)/a}}\prod_{i=1}^{n}(x_i^d)^{\floor{\left((p^e-1) - a_i\floor{(p^e-1)/a}\right)/d}}\notin \mf^{[p^e]},
    \]
    so we have
    \begin{align*}
\lim_{e\to\infty}\frac{\nu_{\ini_>(\bar{I})}}{p^e}\geq \lim_{e\to\infty}\frac{1}{p^e}\left(\floor{\frac{p^e-1}{a}} + \sum_{i=1}^n\floor{\frac{p^e-1}{d} - \frac{a_i\floor{(p^e-1)/a}}{d}}\right)=\frac{1}{a} + \sum_{i=1}^{n} \left(\frac{1}{d} - \frac{a_i}{ad}\right) = \frac{n}{d} + \frac{a_0}{ad}.
    \end{align*}
    Consequently, by \Cref{prop:fpt-properties,prop:semicont} we have
    \[
    \frac{n}{d} = \fpt(I) = \fpt(\bar{I}) \geq \fpt(\ini_>(\bar{I})) \geq \fpt((x_1,\dots,x_n)^d + (x_0^{a_1}\cdots x_n^{a_n})) = \frac{n}{d} + \frac{a_0}{ad},
    \]
    so we have $a_0 = 0$, hence $\ini_>(g)\in (x_1,\dots, x_n)^d$. As $>$ is the lexicographic order, it follows that $g\in (x_1,\dots, x_n)^d$. As $g$ was arbitrary, we conclude that $I \subseteq (x_1,\dots, x_n)^d$, hence $\overline{I} = (x_1,\dots, x_n)^d$ by \Cref{lem:ess-dim-equals-height}.

    Next, we consider the case that $\hgt I\neq n$. If $\hgt I = n+1$, then $\overline{I} = (x_0,\dots, x_n)^{n+1}$ by \Cref{thm:Rees}. Otherwise, suppose $\hgt I = h \leq n-1$. Let $L$ be an ideal generated by $n-h$ linear forms. Then $\frac{h}{d}\leq \fpt(\frac{I + L}{L})\leq \frac{h}{d}$, so by \Cref{lem:min-fpt-char-CI-height-n}, we have $\ess(\frac{I+L}{L}) = h$. By \Cref{prop:ess-dim-general-linear-space}, the same holds for $I$. 
\end{proof}
\section{A Bertini Theorem for \texorpdfstring{$F$}{F}-Purity of Pairs}
In this section, we prove \Cref{thm:F-bertini}. 
\begin{lemma}[\cite{bhatt_f_2015}, Lemma 3.2]\label{lem:colon}
    Let $R := k[x_0,\dots, x_n], \mf := (x_0,\dots, x_n)$. For $e,t\in \Z^+$, we have
\[
(\mf^{[p^e]}: \mf^t) = \begin{cases}
    R & t \geq (n+1)p^e - n\\
    \mf^{[p^e]} + \mf^{(n+1)p^e-n-t} & t < np^e-n+1
\end{cases}
\]
\end{lemma}
\begin{lemma}
    Let $k$ be a field of characteristic $p>0$, let $R = k[x_1,\dots, x_n]$, and $I\subseteq \mf$ a homogeneous ideal. For $H = V(\ell)\in \PNV$, we let $I|_H$ denote the image of $I$ in $R/\ell R$. In this case, we have
    \begin{equation}\label{eqn:nu-section-upper-bound}
    \nu_{I|_H}(p^e) \leq \max \{r: I^r\not\subseteq \mf^{[p^e]} + \mf^{n(p^e-1)+1}\},
    \end{equation}
    Conversely, if $|k| \geq p^e$, then there exists $H\in \PNV(k)$ such that
    \begin{equation}\label{eqn:nu-section-lower-bound}
    \nu_{I|_H}(p^e) \geq \max\{r: I^r\not\subseteq \mf^{[p^e]} + \mf^{n(p^e-1)-(n-1)(p^{e-1})+1}\}.
    \end{equation}
    If $k$ is infinite, then \Cref{eqn:nu-section-lower-bound} holds for general $H\in \PNV$.
\end{lemma}
\begin{proof}
Let $\af_e:= \mf^{[p^e]}+\mf^{n(p^e-1)+1}, d_e = n(p^e-1)-(n-1)(p^{e-1})$,  and $\bfr_e:= \mf^{[p^e]} + \mf^{d_e+1}$. We have $\af_e |_H = \mf^{[p^e]}|_H$, which proves the bound \ref{eqn:nu-section-upper-bound}. For \Cref{eqn:nu-section-lower-bound}, suppose $f\in I^r\setminus \bfr_e$ is a homogeneous element which necessarily has degree at most $d_e$. By \Cref{lem:colon}, we have $f\notin (\mf^{[p^e]}: \mf^{d_e-\deg(f)})$. Multiplying $f$ by a generator of $\mf^{d_e - \deg(f)}$, we may assume $f\notin \bfr_e\text{ and }\deg f = d_e$. Write
\[
f = \sum_{a_0 + \dots + a_n = d_e}c_{a_0,\dots,a_n}x_0^{a_0}\cdots x_n^{a_n}.
\]
For $\l\in k^n$, let $H_\l$ denote the hyperplane cut out by $x_0 = \l_1x_1 + \dots + \l_nx_n$. For $b_1,\dots, b_n\in \Z^{\geq 0}$ such that $b_1 +\dots + b_n = d_e$, define 
\[
P^f_{b_1,\dots, b_n}(\l) := \sum_{a_0=0}^{d_e}\left(\sum_{\substack{
    a_i \leq b_i \ \forall\, 1 \leq i \leq n \\
    a_1+\dots+a_n = d_e - a_0
    }}
    c_{a_0,\dots, a_n}\binom{a_0}{b_1-a_1,\dots, b_n-a_n}\l_1^{b_1-a_1}\cdots \l_{n}^{b_n-a_{n}}\right).
\]
Then we have
\begin{align*}
f|_{H_\l} &= \sum_{a_0 + \dots + a_n = d_e}c_{a_0,\dots,a_n}x_1^{a_1}\cdots x_n^{a_n}(\l_1x_1+\dots\l_nx_n)^{a_0}\\
&= \sum_{b_1 + \dots + b_n = d_e}x_1^{b_1}\dots x_{n}^{b_{n}} P^f_{b_1,\dots, b_{n}}(\l).\end{align*}
    For any $H_\l$, we have that $f|_{H_\l}\notin \mf^{[p^e]}$ if and only if there exist $b_1,\dots, b_n\leq p^e-1$ for which $P^f_{b_1,\dots, b_n}(\l)\neq 0$. We first prove that there exist $b_1,\dots, b_n\leq p^e-1$ for which $P^f_{b_1,\dots, b_n}(\l)$ is a non-constant polynomial in $\l$. To this end, it suffices to produce $a_0,\dots, a_n, b_1,\dots, b_n$ such that 
    \begin{enumerate}[(i)]
        \item $a_0 + \dots + a_n = d_e$;
        \item $c_{a_0,\dots, a_n}\neq 0$;
        \item $b_1+\dots+b_n = d_e$;
        \item $a_i\leq b_i\leq p^e-1$ for all $1\leq i\leq n$; 
        \item We have \[
    \binom{a_0}{b_1-a_1,\dots, b_{n}-a_{n}}\not\equiv 0\mod p.
\]
    \end{enumerate}
By assumption that $f\notin \mf^{[p^e]}$, it is possible to choose $a_0,\dots, a_n$ such that $a_0+\dots+a_n = d_e, a_0,\dots, a_n\leq p^e-1,$ and $c_{a_0,\dots, a_n}\neq 0$. We will prove, by induction on the $p$-ary digits of $a_0$, that there exist $b_1,\dots, b_n$ satisfying (iii)-(v). The base case, when $a_0 = 0$, is obvious. Write $a_0= \a_0 + \a_1p + \dots + \a_{e-1}p^{e-1}$ and suppose $\a_j\neq 0$. 

As $a_1 + \dots + a_n = d_e - a_0$, we have $\min_i a_i\leq \frac{d_e-a_0}{n}$. As a consequence, we have
\[\max_{1\leq i\leq n} (p^e-1) - a_i\geq (p^e-1) - \frac{d_e - a_0}{n} \geq (p^e-1) - \frac{d_e-p^j}{n} = \frac{(n-1)(p^{e-1})}{n} + \frac{p^j}{n} 
\geq p^j.\]
It follows that there exists some $1\leq i\leq n$ with $a_i + p^j\leq p^e-1$. We apply the induction hypothesis to produce integers $b_1,\dots, b_n$ satisfying (iii)-(v) with respect to $(a_0-p^j,a_1,\dots, a_i+p^j, \dots, a_n)$. Since
\[
\binom{a_0 - p_j}{b_1 - a_1,\dots, b_i - a_i - p_j,\dots, b_n - a_n}\not\equiv 0\mod p,
\]
it follows by Lucas's theorem that we can perform the addition 
\[(b_1-a_1) + \dots + (b_i - a_i - p^j) + \dots + (b_n - a_n) = a_0 - p^j\]
in base $p$ without having to carry a digit. Consequently, the same is true for the addition
\[
(b_1-a_1) + \dots + (b_i - a_i) + \dots + (b_n - a_n) = a_0,
\]
so $b_1,\dots, b_n$ satisfy conditions (iii)-(v) for the original tuple $(a_1,\dots, a_n)$.

For $b_1,\dots, b_n$ as above, $P^f_{b_1,\dots, b_n}(\lambda)$ is a nonzero polynomial of total degree $a_03\leq p^e-1$ in the variables $\l_1,\dots, \l_n$. By the Schwartz-Zippel lemma (\cite{schwartz_fast_1980}, Corollary 1), there exist $\l_1,\dots, \l_n\in k$ for which $P^f_{b_1,\dots, b_n}(\lambda_1,\dots, \lambda_n)\neq 0$. If $k$ is infinite, then $P^f_{b_1,\dots, b_n}(\l)\neq 0$ for general $\l\in k^n$.
\end{proof}
As a consequence, we have the following.
\begin{theorem*}[\ref{thm:F-bertini}]
    Let $k$ be an infinite field of characteristic $p > 0$. Let $R = k[x_0,\dots, x_n]$. Let $I\subseteq R$ be an ideal generated by forms of degree at most $d$. Let $H\in \PNV$ be a general hyperplane through the origin. Then for all $0\leq t < \frac{n}{d} - \frac{n-1}{pd}$, the pair $(R, I^t)$ is sharply $F$-split if and only if $(H, (I|_H)^t)$ is sharply $F$-split. 
\end{theorem*}
\begin{proof}
    The implication $(H, (I|_H)^t)$ sharply $F$-split $\implies (R, I^t)$ sharply $F$-split is well-known and additionally is immediate from \Cref{eqn:nu-section-upper-bound}. Conversely, suppose $(R, I^t)$ is sharply $F$-split and $t < \frac{n}{d} - \frac{n-1}{pd}$. Then there exist infinitely many $e\in \Z^+$ such that $I^{\ceil{t(p^e-1)}}\not\subseteq \mf^{[p^e]}$. Since $t < \frac{n}{d} - \frac{n-1}{pd}$, we may choose such $e\gg0$ such that 
    \begin{equation}\label{eqn:gen-degree-bound}
    \ceil{t(p^e-1)}d \leq n(p^e-1) - (n-1)(p^{e-1}).
    \end{equation}
    By assumption we have $I^{\ceil{t(p^e-1)}}\not\subseteq \mf^{[p^e]}$, and by \Cref{eqn:gen-degree-bound} none of the generators of $I^{\ceil{t(p^e-1)}}$ are contained in $\mf^{n(p^e-1)-(n-1)(p^{e-1}) + 1}$. By \Cref{eqn:nu-section-lower-bound}, we conclude $I|_H^{\ceil{t(p^e-1)}}\not\subseteq \mf^{[p^e]}|_H$, so $(H, (I|_H)^t)$ is sharply $F$-split.
\end{proof}
In terms of the $F$-pure threshold, \Cref{thm:F-bertini} says the following.
\begin{cor}\label{cor:fpt-general-section}
    Let $R, I, H$ be as in \Cref{thm:F-bertini}. Then 
    \[
    \min\left(\frac{n}{d} - \frac{n-1}{pd}, \fpt(I)\right)\leq \fpt(I|_H).
    \]
\end{cor}
\begin{proof}
   By \Cref{eqn:nu-section-lower-bound}, we have
    \begin{align*}
    \fpt(I|_H) &\geq \lim_{e\to\infty}p^{-e}\sup\{r:I^r\not\subseteq \mf^{[p^e]} + \mf^{n(p^e-1) - (n-1)p^{e-1}+ 1}\} \\&= \lim_{e\to\infty} p^{-e}\min\left(\nu_{I}(p^e), \floor{\frac{n(p^e-1)-(n-1)p^{e-1}+1}{d}}\right) = \min\left(\fpt(I), \frac{n}{d} - \frac{n-1}{pd}\right).
    \end{align*}
\end{proof}
\begin{example}\label{ex:exponent-optimality}
    In \Cref{thm:F-bertini}, our bound on $t$ is optimal. If $\char k = p$ and $R = k[x_0,\dots, x_n]$, then we may take $f = x_0(x_1\cdots x_n)^{p-1}$ and $t = \frac{n}{n(p-1) + 1} - \frac{n-1}{p(n(p-1)+1)}= \frac{1}{p}$. Then $\fpt(R,f) = \frac{1}{p-1}$, so $(R, f^t)$ is sharply $F$-split. For any hyperplane $H\subseteq R$ we have $f|_H\in \mf|_H^{[p]}$, so $\fpt(f|_H) \leq t$. Since $p$ divides the denominator of $t$, we have by \cite[Corollary 5.4]{schwede_sharp_2008} that $(H, f^t|_H)$ is not sharply $F$-split. 
\end{example}
Finally, we note that an analog of \Cref{cor:fpt-general-section} holds for the log canonical threshold. 
\begin{cor}
    Let $k$ be a characteristic zero field and let $R, I, H$ be as in \Cref{thm:F-bertini}. Then 
    \[
    \min\left(\frac{n}{d}, \lct(I)\right)\leq \lct(I|_H).
    \]
    In particular, if $I$ is generated by $d$-forms, then the above inequality is an equality.
\end{cor}
\begin{proof}
    Let $\{I_p\}_p$ be a family of positive-characteristic models for $I$. Using \cite{mustata_f-thresholds_2004}, one may prove approximate $\fpt(I_p)$ by $\nu_{I_p}(p)$ to prove a quantitative version of \Cref{cor:fpt-general-section} for finite fields. More precisely, one obtains that for each $p$, there exists $H_p\in \PNV(k_p)$ such that
    \[
    \min\left(\fpt(I), \frac{n(p-1)-(n-1)+1}{pd}\right) + O\left(\frac{1}{p}\right) \leq \fpt(I_p|_{H_p}),
    \]
    where the implicit constant depends on the number of generators of $I$. By the ACC for log canonical thresholds \cite{de_fernex_ACC}, there exists a hyperplane $H\in \PNV(k)$ such that $\lct(I|_H) \geq \min(\lct(I), \frac{n}{d})$. By semicontinuity of the log canonical threshold \cite{demailly_semi-continuity_2001}, the desired bound holds for general $H\in \PNV(k)$.
\end{proof}
\section{The Test Ideal at the Threshold}
In the introduction, we claimed that the best-known result in characteristic zero (\Cref{thm:equigen-lct}) is stronger than the previous best-known result in positive characteristic (\Cref{prop:tw-fpt-equigen}). Indeed, \Cref{thm:equigen-lct} shows that analogs of \Cref{prop:tw-fpt-equigen} and \Cref{thm:equigen-fpt} hold in characteristic zero. 
\begin{prop}
Let $k$ be an algebraically-closed field of characteristic zero. Let $I$ be a homogeneous ideal in $k[x_0,\dots, x_n]$ generated by $d$-forms. If $h$ is the height of $I$, then $\fpt(I) \geq h/d$ with equality if and only if $\overline{I} = (x_0,\dots, x_{h-1})^d$ up to change of coordinates.
\end{prop}
\begin{proof}
    Since $(R, (1)^t)$ is klt for all $t > 0$, the non-klt locus $Z$ of $(R, I^{\lct(I)})$ is contained in $V(I)$. Consequently, by \Cref{thm:equigen-lct} we have
    \[
    \lct(I) \geq \frac{\codim Z}{d} \geq \frac{\hgt I}{d} = \frac{h}{d}.
    \]
    Write $I = (f_1,\dots, f_r)$.
    If $\lct(I) = \frac{h}{d}$, then $\codim(Z) = h$ and $\lct(I) = \frac{\codim(Z)}{d}$, so there exist independent linear forms $\ell_1,\dots, \ell_h \in R$ such that $f_i\in k[\ell_1,\dots, \ell_h]$. Changing coordinates, we may assume $\ell_i = x_{i-1}$ for $1\leq i\leq h$. The result then follows from \Cref{lem:ess-dim-equals-height}.
\end{proof}
By \cite{hara_generalization_2003}, the correct positive-characteristic analog of \Cref{thm:equigen-lct} considers strong $F$-regularity and the $F$-pure threshold. We direct the reader to \cite{hara_on_a_2004} for background on the test ideal $\tau(R,\af^t)$, which cuts out the non-strongly $F$-regular locus of the pair $(R, \af^t)$. With this in mind, we are now able to give an example of the failure of \Cref{thm:equigen-lct} in positive characteristic.
\begin{example}\label{ex:naive-analog-failure}
    Suppose $p\equiv 2\mod 3$. Let $R = \F_p[x,y,z]$ and $f = (x^3 + y^3 + z^3)$. By \cite[Theorems 3.1 and 3.3]{hernandez-diagonal-2015}, we have $\fpt(f) = 1 - \frac{1}{p}$ and $\tau(R, f^{1-1/p}) = (x,y,z)$. A naive translation of \Cref{thm:equigen-lct} predicts that $\fpt(f)\geq \frac{\hgt((x,y,z))}{3}$, but this is not the case.
\end{example}
Motivated by the failure of the positive-characteristic analog of \Cref{thm:equigen-lct} in the case that $p$ divides the denominator of $\fpt(f)$, we impose the additional condition that the pair $(R, I^{\fpt(I)})$ is sharply $F$-split.
\begin{lemma}\label{lem:sharp-at-threshold}
    Let $k$ be a field of characteristic $p>0$. Let $R = k[x_0,\dots, x_n]$. Suppose $I\subseteq R$ is generated by forms of degree $d$. Suppose $(R, I^{\fpt(I)})$ is sharply $F$-split and let $h = \hgt(\tau(R, I^{\fpt(I)}))$. Suppose further that $h \geq n$. Then $\fpt(I)\geq h/d$.
\end{lemma}
\begin{proof}
    Define the graded system of ideals $\af_\bullet$ by $\af_m = I^{\ceil{m\fpt(I)}}$. The strongly $F$-regular loci of $(R, I^{\fpt(I)})$ and $(R, \af_\bullet)$ coincide according to \cite[Definition 2.11]{schwede_centers_2010}. Let $\pf$ be a minimal prime over $\tau(R, I^{\fpt(I)})$. As $\pf$ is a homogeneous prime ideal of height $n$ or $n+1$, we may change coordinates so that $\pf = (x_0,\dots, x_{h-1})$. By \cite[Propositions 4.5 and 4.7]{schwede_centers_2010}, we have that $\pf$ is uniformly $(\af_\bullet, F)$-compatible, so for all $e\geq 0$ we have $\af_{p^e-1}\subseteq (\pf^{[p^e]}:\pf) = \pf^{[p^e]} + (x_0\cdots x_{h-1})^{p^e-1}$. By assumption that $(R, I^{\fpt(I)})$ is sharply $F$-split, there exist infinitely many $e\in \Z^+$ such that $\af_{p^e-1}\not\subseteq \mf^{[p^e]}$. Choose such an $e$ and let $f$ be a generator of $\af_{p^e-1}$ such that $f\in \pf^{[p^e]} + (x_0\cdots x_{h-1})^{p^e-1}\setminus \mf^{[p^e]}$. Then $\ceil{\fpt(I)(p^e-1)}d = \deg f \geq h(p^e-1)$. Taking $e\to\infty$, we conclude $\fpt(I)\geq \frac{h}{d}$.
\end{proof}
In particular, by \cite[Remark 5.5]{schwede_sharp_2008}, the hypothesis that $(R, I^{\fpt(I)})$ is sharply $F$-split is satisfied whenever $I$ is principal and $p$ does not divide the denominator of $\fpt(I)$.
\begin{theorem*}[\ref{thm:smooth-lowbound}]
    Suppose $\char k = p>0$ and $R = k[x_0,\dots, x_n]$. Suppose that $f\in R$ is homogeneous of degree $d$, that $f$ is smooth in codimension $c$, and that $p$ does not divide the denominator of $\fpt(f)$. Further suppose that $c\geq n$ or $p\geq c$. Then $\fpt(f)\geq \min(c/d,1)$.
\end{theorem*}
\begin{proof}
    We first base change to the algebraic closure of $k$; this changes neither the hypotheses nor the conclusion. Assume $\fpt(f) < 1$. We will first demonstrate that $V(\tau(R, f^{\fpt(f)}))\subseteq \text{Sing}(f)$. To see this, suppose $\pf$ is a nonsingular point of $R/fR$. Then in particular, $R_\pf/f R_\pf$ is $F$-split, so $\fpt(R_\pf, fR_\pf) = 1$ and $\tau(R_\pf, f^{\fpt(f)}R_\pf) = R_\pf$. It follows that $\pf\notin V(\tau(R, f^{\fpt(f)}))$. If $c\in \{n, n+1\}$, by \Cref{lem:sharp-at-threshold} we have $\fpt(f)\geq \hgt(\tau(R, f^{\fpt(f)}))/d\geq c/d$. 

    Suppose instead $c\leq n-1$ and $p\geq c$; we'll prove the claim by induction on $n+1-c$. Suppose for the sake of contradiction $\fpt(f) < c/d$. Let $H$ be a general element of $\PNV$. Then $\codim(H, \text{Sing}(f|_H)) = \codim(\Spec R, \text{Sing}(f)) = c$ by Bertini's theorem. As 
    \[\fpt(f) < \frac{c}{d} = \frac{c+1}{d} - \frac{1}{d}\leq \frac{c+1}{d} - \frac{c}{pd} \leq \frac{n}{d} - \frac{n-1}{pd},\] we have by \Cref{cor:fpt-general-section} that $\fpt(f) = \fpt(f|_H)$. In particular, $p$ does not divide the denominator of $\fpt(f)$. By induction, we conclude that $\fpt(f) < c/d \leq \fpt(f|_H) \leq \fpt(f)$, a contradiction.
\end{proof}
We close this paper with a conjecture.
\begin{conj}
    Let $k$ be an algebraically-closed field of characteristic $p>0$ and set $R = k[x_1,\dots, x_n]$. Let $I\subseteq R$ be an ideal generated by $d$-forms. Further suppose that $(R, I^{\fpt(I)})$ is sharply $F$-split. Letting $e = \hgt(\tau(R, I^{\fpt(I)}))$, we have
    \[
    \fpt(R, I) \geq \frac{e}{d}
    \]
    with equality if and only if $\ess(I) = e$.
\end{conj}

