\subsection{Sublinear convergence for $\alpha\in (\frac{1}{2},1)$}\label{ssec:sublinear}

The following theorem is the main result of this section. 
Its proof is given in Appendix~\ref{app:proof-frechet}. 

\begin{thm}[Sublinear convergence of objective function values]\label{thm:sublinear}
Let $\alpha\in (\frac{1}{2},1)$, 
$\rho_{AB}\in \mathcal{S}(AB)$, 
$\sigma_A^{(0)}\in \mathcal{S}_{\rho_A\ll}(A)$, and let $(x_n)_{n\in \mathbb{N}}$ be given by Definition~\ref{def:am-quantum}. 
Moreover, let
\begin{subequations} \label{eq:def-sublinear-c0}
\begin{align}
\lambda_A&\coloneqq \min(\spec(\tr_B[\rho_{AB}^\alpha])\setminus\{0\}),
\label{eq:def-lam_a}\\
\lambda_B&\coloneqq \min(\spec(\tr_A[\rho_{AB}^\alpha])\setminus\{0\}),
\\
\lambda_{A,0}&\coloneqq \min (\spec(\tilde{\sigma}_A^{(0)} )\setminus \{0\}) 
\quad \text{where}\quad 
\tilde{\sigma}_A^{(0)}\coloneqq \rho_A^0\sigma_A^{(0)}\rho_A^0/\tr[\rho_A^0\sigma_A^{(0)}],
\\
c_0
&\coloneqq 2\sqrt{5} \max(\lambda_B^{-1}, \lambda_A^{\frac{\alpha(1-\alpha)}{1-2\alpha}}\lambda_B^{\frac{\alpha^2}{1-2\alpha}} ) \lambda_{A,0}^{\alpha-1}.
\end{align}
\end{subequations} 
Then, for all $n\in \mathbb{N}_{>0}$ 
\begin{align}
\lvert x_{n}-I_\alpha^{\downarrow\downarrow}(A:B)_\rho\rvert
&\leq c_0 \sqrt{x_{n-1}-x_{n}},
\label{eq:thm-n1}
\end{align}
and as a consequence,
\begin{align}
\lvert x_{n}-I_\alpha^{\downarrow\downarrow}(A:B)_\rho\rvert
&\leq \max\left(\frac{3}{2} c_0^{2},2x_0\right) \frac{1}{n}.
\label{eq:thm-n2}
\end{align}
\end{thm}

\begin{rem}[Asymptotic convergence, uniqueness of minimizer]\label{rem:sublinear-asymptotic}
We can conclude from Theorem~\ref{thm:sublinear} that alternating minimization converges to the doubly minimized PRMI of order $\alpha$ for any $\alpha\in (\frac{1}{2},1)$. 
The underlying minimizer has been shown to be unique and to be contained in $\mathcal{S}_{\sim\rho_A}(A)\times \mathcal{S}_{\sim \rho_B}(B)$ in previous work~\cite{burri2024properties}, see~\eqref{eq:unique}. 
More formally, 
let $\alpha\in (\frac{1}{2},1)$, 
$\rho_{AB}\in \mathcal{S}(AB)$, 
$\sigma_A^{(0)}\in \mathcal{S}_{\rho_A\ll}(A)$, 
and let $\tau_B^{(n)},\sigma_A^{(n+1)},x_n$ be given by Definition~\ref{def:am-quantum} for all $n\in \mathbb{N}$. 
Then, $(x_n)_{n\in \mathbb{N}}$ is monotonically decreasing and 
$\lim_{n\rightarrow \infty}x_n=I_\alpha^{\downarrow\downarrow}(A:B)_\rho$, 
the limits $\sigma_A^{(\infty)}\coloneqq \lim_{n\rightarrow\infty}\sigma_A^{(n)}$ and 
$\tau_B^{(\infty)}\coloneqq \lim_{n\rightarrow\infty}\tau_B^{(n)}$ exist, and
\begin{equation}
\argmin_{(\sigma_A,\tau_B)\in \mathcal{S}(A)\times\mathcal{S}(B)}D_\alpha (\rho_{AB}\| \sigma_A\otimes \tau_B)=\{(\sigma_A^{(\infty)},\tau_B^{(\infty)})\} 
\subseteq \mathcal{S}_{\sim \rho_A}(A)\times \mathcal{S}_{\sim \rho_B}(B).
\end{equation}
\end{rem}

\begin{rem}[Alternating minimization algorithm for $\alpha\in (\frac{1}{2},1)$]
Based on Theorem~\ref{thm:sublinear}, we propose an alternating minimization algorithm for computing the doubly minimized PRMI of order $\alpha\in (\frac{1}{2},1)$: Algorithm~2. 
For any given inputs 
$\alpha\in (\frac{1}{2},1)$, $\rho_{AB}\in \mathcal{S}(AB)$, $\varepsilon_0\in (0,\infty)$, $\sigma_A^{(0)}\in \mathcal{S}_{\rho_A\ll}(A)$, 
Theorem~\ref{thm:sublinear} implies that 
Algorithm~2 terminates after a finite number of steps, with the output $x$ satisfying 
$\lvert x-I_\alpha^{\downarrow\downarrow}(A:B)_\rho\rvert \leq \varepsilon_0$.
The input $\sigma_A^{(0)}\in \mathcal{S}_{\rho_A\ll}(A)$ can be chosen arbitrarily, but a particularly natural choice is $\sigma_A^{(0)}\coloneqq \rho_A$ (cf. Remark~\ref{rem:am}).
\end{rem}

