\appendix
\section{Classical setting}\label{app:cc}
In this appendix, we review the results on alternating minimization for computing the doubly minimized RMI in~\cite{tsai2024linearconvergencehilbertsprojective}. 
We then show how these results imply linear convergence of the objective function values to the doubly minimized RMI (Corollary~\ref{cor:cc-linear2}). 
To this end, we first explain our notation for the classical setting (\ref{ssec:notation-cc}). 
Then, we review the findings of~\cite{tsai2024linearconvergencehilbertsprojective} and extend them by the aforementioned corollary (\ref{ssec:linear-cc}).

\subsection{Notation for classical setting}\label{ssec:notation-cc}
\subsubsection{Probability mass functions}

Let $\mathcal{X}$ be a finite set.
The support of a function $P:\mathcal{X}\rightarrow\mathbb{R}$ is denoted as $\supp (P)\coloneqq\{x\in \mathcal{X}:P(x)\neq 0\}$.
For two functions $P,Q:\mathcal{X}\rightarrow\mathbb{R}$, 
$P\ll Q$ is true iff $\supp(P)\subseteq \supp(Q)$. 
$P\sim Q$ is true iff $\supp(P)=\supp(Q)$. 
$P\perp Q$ is true iff $\supp(P)\cap \supp(Q)=\emptyset$.

The set of PMFs over $\mathcal{X}$ is 
$\mathcal{P}(\mathcal{X})\coloneqq \{P:\mathcal{X}\rightarrow [0,\infty) \text{ such that } \sum_{x\in \mathcal{X}}P(x)=1\}$. 
The set of PMFs that have the same support as $P:\mathcal{X}\rightarrow\mathbb{R}$ is denoted as 
$\mathcal{P}_{\sim P}(\mathcal{X})\coloneqq \{Q\in \mathcal{P}(\mathcal{X}):Q\sim P\}$.

\subsubsection{R\'enyi divergence}
The \emph{R\'enyi divergence} of order $\alpha\in [0,1)\cup (1,\infty)$ is defined for 
$P,Q\in \mathcal{P}(\mathcal{X})$ as
\begin{align}
D_\alpha (P\| Q) \coloneqq \frac{1}{\alpha-1}\log \sum_{x\in \supp(P)} 
P(x)^\alpha Q(x)^{1-\alpha}
\end{align}
where for $\alpha > 1$, we read $P(x)^\alpha Q(x)^{1-\alpha}$ as $P(x)^\alpha /Q(x)^{\alpha-1}$ and we adopt the convention $y/0 = \infty$ for $y > 0$. 
Moreover, $D_1$ is defined as the limit of $D_\alpha$ for $\alpha\rightarrow 1$. 

The \emph{doubly minimized RMI} of order $\alpha\in [0,\infty)$ is defined for $P_{XY}\in \mathcal{P}(\mathcal{X}\times \mathcal{Y})$ as
\begin{align}
I_\alpha^{\downarrow\downarrow}(X:Y)_P \coloneqq 
\inf_{(Q_X,R_Y)\in \mathcal{P}(\mathcal{X})\times \mathcal{P}(\mathcal{Y})} D_\alpha (P_{XY}\| Q_X R_Y).
\label{eq:cc-2prmi}
\end{align}
Properties of the doubly minimized RMI have been studied in~\cite{lapidoth2019two}. 

Partial minimizers of the optimization problem in~\eqref{eq:cc-2prmi} can be characterized as follows. 
For any $P_{XY}\in \mathcal{P}(\mathcal{X}\times \mathcal{Y}),Q_X\in \mathcal{P}(\mathcal{X}),\alpha\in (0,\infty)$ holds that if 
$(\alpha\in (0,1)\land P_X\not\perp R_X)\lor P_X\ll R_X$, then~\cite{lapidoth2019two}
\begin{align}\label{eq:qx-optimal}
\hat{R}_Y(\cdot)
&\coloneqq \frac{(\sum_{x\in \mathcal{X}}P_{XY}(x,\cdot)^\alpha Q_X(x)^{1-\alpha} )^{\frac{1}{\alpha}}}{\sum_{y\in \mathcal{Y}}(\sum_{x\in \mathcal{X}}P_{XY}(x,y)^\alpha Q_X(x)^{1-\alpha} )^{\frac{1}{\alpha}}}
\end{align}
is such that $\argmin_{R_Y\in \mathcal{P}(\mathcal{Y})} D_\alpha (P_{XY}\| Q_X R_Y)
=\{\hat{R}_Y\}$.

For $\alpha\in (\frac{1}{2},\infty)$, the optimization problem in~\eqref{eq:cc-2prmi} has a unique minimizer: 
For any given $\alpha\in (\frac{1}{2},\infty)$, there exists $(\hat{Q}_X,\hat{R}_Y)\in \mathcal{P}_{\sim P_X}(X)\times \mathcal{P}_{\sim P_Y}(Y)$ such that~\cite{lapidoth2019two,burri2024properties}
\begin{align}\label{eq:cc-unique}
\argmin_{(Q_X,R_Y)\in\mathcal{P}(X)\times \mathcal{P}(Y)} D_\alpha (P_{XY}\| Q_X R_Y)
=\{(\hat{Q}_X,\hat{R}_Y)\}.
\end{align}

\subsubsection{Hilbert's projective metric}
Recall the notation associated with Hilbert's projective metric from Section~\ref{ssec:hilbert}.

\emph{Classical setting.} 
In the classical setting, the relevant real vector space $V$ is given by the set of all functions from a finite set $\mathcal{X}$ to $\mathbb{R}$. 
The cone $C$ is given by the subset of all functions from $\mathcal{X}$ to $[0,\infty)$. 
The dominance relation $P\ll_C Q$ is given by $P\ll Q$ for all $P,Q\in C$. 
The equivalence relation $P\sim_C Q$ is given by $P\sim Q$ for all $P,Q\in C$. 
Moreover, for all $P,Q\in C\setminus \{0\}$ such that $P\ll Q$
\begin{align}\label{eq:m-xy-classical}
M(P/Q)=\max_{x\in \supp(Q)}\frac{P(x)}{Q(x)}.
\end{align}

\subsection{Linear convergence for $\alpha\in (\frac{1}{2},\infty)$ for classical setting}\label{ssec:linear-cc}
Alternating minimization of $D_\alpha (P_{XY}\| Q_XR_Y)$ over PMFs $Q_X$ and $R_Y$ proceeds as described in the following definition, see~\eqref{eq:qx-optimal}.

\begin{defn}[Alternating minimization: Iteration rule]\label{def:am-classical}
For any given $\alpha\in (0,\infty)$, $P_{XY}\in \mathcal{P}(\mathcal{X}\times \mathcal{Y})$, we define the functions
\begin{subequations}\label{eq:def-N-cc}
\begin{align}
\mathcal{N}_{X\rightarrow Y}: \mathcal{P}_{P_X\ll }(\mathcal{X}) \rightarrow \mathcal{P}_{\sim P_Y}(\mathcal{Y}),
\quad
&Q_X\mapsto \frac{(\sum_{x\in \mathcal{X}}P_{XY}(x,\cdot)^\alpha Q_X(x)^{1-\alpha} )^{\frac{1}{\alpha}}}{\sum_{y\in \mathcal{Y}}(\sum_{x\in \mathcal{X}}P_{XY}(x,y)^\alpha Q_X(x)^{1-\alpha} )^{\frac{1}{\alpha}}},
\\
\mathcal{N}_{Y\rightarrow X}: \mathcal{P}_{P_Y\ll }(\mathcal{Y}) \rightarrow \mathcal{P}_{\sim P_X}(\mathcal{X}),
\quad
&R_Y\mapsto \frac{(\sum_{y\in \mathcal{Y}}P_{XY}(\cdot,y)^\alpha R_Y(y)^{1-\alpha} )^{\frac{1}{\alpha}}}{\sum_{x\in \mathcal{X}}(\sum_{y\in \mathcal{Y}}P_{XY}(x,y)^\alpha R_Y(y)^{1-\alpha} )^{\frac{1}{\alpha}}},
\end{align}
\end{subequations}
and for any given $Q_X^{(0)}\in \mathcal{P}_{P_X\ll }(\mathcal{X})$, we define for all $n\in \mathbb{N}$
\begin{align}
R_Y^{(n)} &\coloneqq \mathcal{N}_{X\rightarrow Y}(Q_X^{(n)}),
\\
Q_X^{(n+1)} &\coloneqq \mathcal{N}_{Y\rightarrow X}(R_Y^{(n)}),
\\
x_n &\coloneqq D_\alpha (P_{XY}\| Q_X^{(n)}R_Y^{(n)}).
\end{align}
\end{defn}

The following theorem provides sufficient conditions for $\mathcal{N}_{X\rightarrow Y}$ and $\mathcal{N}_{Y\rightarrow X}$ to be contractions with respect to Hilbert’s projective metric. 
\begin{thm}[Contraction]\label{thm:cc-linear}
\cite[Theorem~13]{tsai2024linearconvergencehilbertsprojective}
Let $\alpha\in [\frac{1}{2},1)\cup (1,\infty)$, 
$P_{XY}\in \mathcal{P}(\mathcal{X}\times \mathcal{Y})$, and 
let $\mathcal{N}_{X\rightarrow Y},\mathcal{N}_{Y\rightarrow X}$ be given by Definition~\ref{def:am-classical}. 
Let $\gamma \coloneqq \lvert 1-\frac{1}{\alpha}\rvert$.
\begin{enumerate}[label=(\alph*)]
\item 
If $\alpha >\frac{1}{2}$: 
For all $Q_X,\tilde{Q}_X\in \mathcal{P}(\mathcal{X}),R_Y,\tilde{R}_Y\in \mathcal{P}(\mathcal{Y})$
\begin{align}
d_H(\mathcal{N}_{X\rightarrow Y}(Q_X),\mathcal{N}_{X\rightarrow Y}(\tilde{Q}_X))
&\leq \gamma d_H(Q_X,\tilde{Q}_X) ,
\\
d_H(\mathcal{N}_{Y\rightarrow X}(R_Y),\mathcal{N}_{Y\rightarrow X}(\tilde{R}_Y))
&\leq \gamma d_H(R_Y,\tilde{R}_Y).
\end{align}
\item 
If $P_{XY}(x,y)>0$ for all $x\in \mathcal{X},y\in \mathcal{Y}:$ 
For all $Q_X,\tilde{Q}_X\in \mathcal{P}(\mathcal{X}),R_Y,\tilde{R}_Y\in \mathcal{P}(\mathcal{Y})$
\begin{align}
d_H(\mathcal{N}_{X\rightarrow Y}(Q_X),\mathcal{N}_{X\rightarrow Y}(\tilde{Q}_X))
&\leq \gamma\kappa d_H(Q_X,\tilde{Q}_X),
\\
d_H(\mathcal{N}_{Y\rightarrow X}(R_Y),\mathcal{N}_{Y\rightarrow X}(\tilde{R}_Y))
&\leq \gamma\kappa d_H(R_Y,\tilde{R}_Y),
\end{align}
where $\kappa\coloneqq \tanh(\delta /4)\in [0,1)$ and 
\begin{align}
\delta \coloneqq \log \max_{\substack{x,x'\in \mathcal{X},\\ y,y'\in \mathcal{Y}}} \frac{P_{XY}(x,y)^\alpha P_{XY}(x',y')^\alpha}{P_{XY}(x',y)^\alpha P_{XY}(x,y')^\alpha}.
\end{align}
\end{enumerate}
\end{thm}
\begin{rem}[Subdivision of Theorem~\ref{thm:cc-linear}]
Note that the assertion in~(a) holds in general and guarantees a contraction coefficient of $\gamma \in [0, 1)$. 
In contrast,~(b) only holds under the assumption that $P_{XY}$ is strictly positive, but guarantees an improved contraction coefficient of $\gamma\kappa \in [0,\gamma) \subseteq [0, 1)$. 
This possibility of an improved coefficient will also appear analogously in subsequent results.
\end{rem}

The following result is a corollary of Theorem~\ref{thm:cc-linear}. 
It implies linear convergence of the PMFs obtained by alternating minimization with respect to Hilbert's projective metric. 
More specifically, (a) implies that the corresponding error rate is $\mathcal{O}(\lvert 1-\frac{1}{\alpha}\rvert^{2n})$.
\begin{cor}[Linear convergence of PMFs]\label{cor:cc-linear1}
\cite[Corollary~14]{tsai2024linearconvergencehilbertsprojective}
\sloppy
Let $\alpha\in [\frac{1}{2},1)\cup (1,\infty)$, 
$P_{XY}\in \mathcal{P}(\mathcal{X}\times \mathcal{Y})$, and 
let $(\hat{Q}_X,\hat{R}_Y)\in \argmin_{(Q_X,R_Y)\in \mathcal{P}(\mathcal{X})\times \mathcal{P}(\mathcal{Y})} D_\alpha (P_{XY}\| Q_XR_Y)$. 
Let $Q_X^{(0)}\in \mathcal{P}_{\sim P_X}(\mathcal{X})$ and let $R_Y^{(n)},Q_X^{(n+1)}$ be given by Definition~\ref{def:am-classical} for all $n\in \mathbb{N}$. 
Let $\gamma \coloneqq \lvert 1-\frac{1}{\alpha}\rvert$. 
\begin{enumerate}[label=(\alph*)]
\item 
If $\alpha >\frac{1}{2}$: 
For all $n\in \mathbb{N}$
\begin{align}
d_H(Q_X^{(n)},\hat{Q}_X) &\leq \gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X),
\\
d_H(R_Y^{(n)},\hat{R}_Y) &\leq \gamma^{2n+1} d_H(Q_X^{(0)},\hat{Q}_X).
\end{align}
\item 
If $P_{XY}(x,y)>0$ for all $x\in \mathcal{X},y\in \mathcal{Y}:$ 
For all $n\in \mathbb{N}$
\begin{align}
d_H(Q_X^{(n)},\hat{Q}_X) &\leq (\gamma\kappa)^{2n} d_H(Q_X^{(0)},\hat{Q}_X),
\\
d_H(R_Y^{(n)},\hat{R}_Y) &\leq (\gamma\kappa)^{2n+1} d_H(Q_X^{(0)},\hat{Q}_X)
\end{align}
where $\kappa$ is defined as in Theorem~\ref{thm:cc-linear}~(b).
\end{enumerate}
\end{cor}

The following result follows from Corollary~\ref{cor:cc-linear1}, as shown in Appendix~\ref{app:cc-linear2}. 
It implies linear convergence of the objective function values obtained by alternating minimization.
More specifically, (a) implies that 
$\lvert x_{n}-I_\alpha^{\downarrow\downarrow}(X:Y)_P \rvert$ is 
$\mathcal{O}(\lvert 1-\frac{1}{\alpha}\rvert^{2n})$ for any $\alpha\in (\frac{1}{2},\infty)$.
\begin{cor}[Linear convergence of objective function values]\label{cor:cc-linear2}
\sloppy
Let $\alpha\in [\frac{1}{2},1)\cup (1,\infty)$, 
$P_{XY}\in \mathcal{P}(\mathcal{X}\times \mathcal{Y})$, and 
let $(\hat{Q}_X,\hat{R}_Y)\in \argmin_{(Q_X,R_Y)\in \mathcal{P}(\mathcal{X})\times \mathcal{P}(\mathcal{Y})} D_\alpha (P_{XY}\| Q_XR_Y)$. 
Let $Q_X^{(0)}\in \mathcal{P}_{\sim P_X}(\mathcal{X})$ and let $(x_n)_{n\in \mathbb{N}}$ be given by Definition~\ref{def:am-classical}. 
Let $\gamma \coloneqq \lvert 1-\frac{1}{\alpha}\rvert$. 
\begin{enumerate}[label=(\alph*)]
\item 
If $\alpha >\frac{1}{2}$: 
For all $n\in \mathbb{N}$
\begin{align}
\lvert x_{n}-I_\alpha^{\downarrow\downarrow}(X:Y)_P \rvert 
&\leq \frac{1}{\lvert \alpha-1\rvert} \left(
\exp\left(\lvert \alpha-1\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right)
-1\right).
\end{align}
\item 
If $P_{XY}(x,y)>0$ for all $x\in \mathcal{X},y\in \mathcal{Y}:$ 
For all $n\in \mathbb{N}$
\begin{align}
\lvert x_{n}-I_\alpha^{\downarrow\downarrow}(X:Y)_P \rvert 
&\leq \frac{1}{\lvert \alpha-1\rvert} \left(
\exp\left(\lvert \alpha-1\rvert (1+\gamma\kappa)(\gamma\kappa)^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right)
-1\right)
\end{align}
where $\kappa$ is defined as in Theorem~\ref{thm:cc-linear}~(b).
\end{enumerate}
\end{cor}



\subsection{Proof of Corollary~\ref{cor:cc-linear2}}\label{app:cc-linear2}
\begin{lem}\label{lem:cc-m1}
Let $\alpha\in (0,1)\cup (1,\infty)$ and let $Q,R\in \mathcal{P}(\mathcal{X})$ be such that $Q\sim R$. 
Then, $M(Q^{1-\alpha}/R^{1-\alpha})\geq 1$.
\end{lem}
\begin{proof}
\emph{Case 1: $\alpha>1$.} 
\begin{align}
M(Q^{1-\alpha}/R^{1-\alpha})
&= \max_{x\in \supp(R)} \frac{Q(x)^{1-\alpha}}{R(x)^{1-\alpha}}
\label{eq:proof-cc-m1}\\
&\geq \sum_{x\in \supp(R)} R(x) \frac{Q(x)^{1-\alpha}}{R(x)^{1-\alpha}}
=\sum_{x\in \supp(R)} R(x)^{\alpha} Q(x)^{1-\alpha}
\\
&\geq \left(\sum_{x\in \supp(R)} (R(x)^\alpha )^{1/\alpha}\right)^\alpha
\left(\sum_{x\in \supp(R)} (Q(x)^{\alpha-1})^{1/(\alpha-1)}\right)^{1-\alpha}
\label{eq:proof-cc-m3}\\
&= \left(\sum_{x\in \supp(R)} R(x)\right)^\alpha
\left(\sum_{x\in \supp(R)} Q(x)\right)^{1-\alpha}
= 1
\label{eq:proof-cc-m4}
\end{align}
\eqref{eq:proof-cc-m1} follows from~\eqref{eq:m-xy-classical}. 
\eqref{eq:proof-cc-m3} follows from the reverse H\"older inequality~\cite[Lemma~3.1]{tomamichel2016quantum}.
The last equality in~\eqref{eq:proof-cc-m4} follows from $\sum_{x\in \mathcal{X}}R(x)=1=\sum_{x\in \mathcal{X}}Q(x)$.

\emph{Case 2: $\alpha<1$.} 
\begin{align}
M(Q^{1-\alpha}/R^{1-\alpha})
&= \max_{x\in \supp(R)} \frac{Q(x)^{1-\alpha}}{R(x)^{1-\alpha}}
\label{eq:proof-ccm1}\\
&\geq \sum_{x\in \supp(R)} Q(x) \frac{Q(x)^{1-\alpha}}{R(x)^{1-\alpha}}
=\sum_{x\in \supp(R)} Q(x)^{2-\alpha} R(x)^{\alpha-1}
\\
&\geq \left(\sum_{x\in \supp(R)} (Q(x)^{2-\alpha} )^{1/(2-\alpha)}\right)^{2-\alpha}
\left(\sum_{x\in \supp(R)} (R(x)^{1-\alpha})^{1/(1-\alpha)}\right)^{\alpha-1}
\label{eq:proof-ccm3}\\
&= \left(\sum_{x\in \supp(R)} Q(x)\right)^{2-\alpha}
\left(\sum_{x\in \supp(R)} R(x)\right)^{\alpha-1}
= 1
\label{eq:proof-ccm4}
\end{align}
\eqref{eq:proof-ccm1} follows from~\eqref{eq:m-xy-classical}. 
\eqref{eq:proof-ccm3} follows from the reverse H\"older inequality~\cite[Lemma~3.1]{tomamichel2016quantum}.
The last equality in~\eqref{eq:proof-ccm4} follows from $\sum_{x\in \mathcal{X}}R(x)=1=\sum_{x\in \mathcal{X}}Q(x)$. 
\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:cc-linear2}]
We will first prove~(a). 
Let $\hat{q}\coloneqq \exp((\alpha-1)I_\alpha^{\downarrow\downarrow}(X:Y)_P)$ 
and $q_n\coloneqq \exp((\alpha-1)x_n)$ for all $n\in \mathbb{N}$. 
Let $R_Y^{(n)},Q_X^{(n+1)}$ be given by Definition~\ref{def:am-classical} for all $n\in \mathbb{N}$. 

\emph{Case 1: $\alpha>1$.} 
For all $n\in \mathbb{N}$
\begin{align}
q_n-\hat{q}
&=\sum_{\substack{x\in \supp (P_X), \\ y\in \supp(P_Y)}}
P_{XY}(x,y)^\alpha \left((Q_X^{(n)}(x)R_Y^{(n)}(y) )^{1-\alpha}-(\hat{Q}_X(x)\hat{R}_Y(y) )^{1-\alpha}\right)
\\
&=\sum_{\substack{x\in \supp (P_X), \\ y\in \supp(P_Y)}}
P_{XY}(x,y)^\alpha (\hat{Q}_X(x) \hat{R}_Y(y) )^{1-\alpha} 
\left(\frac{(Q_X^{(n)}(x)R_Y^{(n)}(y) )^{1-\alpha}}{(\hat{Q}_X(x)\hat{R}_Y(y) )^{1-\alpha}}
-1\right)
\\
&\leq \hat{q} \left(
M((Q_X^{(n)} R_Y^{(n)})^{1-\alpha} / (\hat{Q}_X \hat{R}_Y)^{1-\alpha}) 
-1\right).
\label{eq:cc-2}
\end{align}

For all $n\in \mathbb{N}$
\begin{align}
\frac{q_n}{\hat{q}}
&\leq M( (Q_X^{(n)}R_Y^{(n)} )^{1-\alpha} / (\hat{Q}_X\hat{R}_Y )^{1-\alpha} )
\label{eq:cc-21}\\
&\leq M( (Q_X^{(n)}R_Y^{(n)} )^{1-\alpha} / (\hat{Q}_X\hat{R}_Y )^{1-\alpha} )
M( (\hat{Q}_X\hat{R}_Y )^{1-\alpha} / (Q_X^{(n)}R_Y^{(n)} )^{1-\alpha})
\label{eq:cc-22}
\\
&= \exp\left(
d_H( (Q_X^{(n)} R_Y^{(n)})^{1-\alpha}, (\hat{Q}_X \hat{R}_Y)^{1-\alpha} ) 
\right)
\label{eq:cc-23}\\
&\leq \exp\left(
\lvert 1-\alpha\rvert d_H( Q_X^{(n)} R_Y^{(n)}, \hat{Q}_X \hat{R}_Y ) 
\right)
\label{eq:cc-24}\\
&= \exp\left(
\lvert 1-\alpha\rvert (d_H( Q_X^{(n)}, \hat{Q}_X ) 
+d_H(R_Y^{(n)}, \hat{R}_Y ) )
\right)
\label{eq:cc-3}\\
&\leq \exp\left(\lvert 1-\alpha\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right).
\label{eq:cc-4}
\end{align}
\eqref{eq:cc-4} follows from Theorem~\ref{thm:cc-linear}. 
\eqref{eq:cc-21} follows from~\eqref{eq:cc2} because $\hat{q}=\exp((\alpha-1)I_\alpha^{\downarrow\downarrow}(X:Y)_P)>0$. 
\eqref{eq:cc-22} follows from Lemma~\ref{lem:cc-m1}.
\eqref{eq:cc-3} follows from the additivity of Hilbert’s projective metric with respect to the product of PMFs. 
\eqref{eq:cc-4} follows from Corollary~\ref{cor:cc-linear1}~(a). 
We conclude that for all $n\in \mathbb{N}$
\begin{align}
0\leq x_{n}-I_\alpha^{\downarrow\downarrow}(X:Y)_P 
&=\frac{1}{\alpha-1}\log\left(1+\frac{q_n}{\hat{q}}-1\right)
\\
&\leq \frac{1}{\alpha-1} \left(\frac{q_n}{\hat{q}}-1\right)
\label{eq:cc-6}\\
&\leq \frac{1}{\alpha-1 } \left(
\exp\left(\lvert\alpha-1\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right)
-1\right)
\label{eq:cc-7}
\\
&= \frac{1}{\lvert\alpha-1 \rvert} \left(
\exp\left(\lvert\alpha-1\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right)
-1\right).
\label{eq:cc-8}
\end{align}
\eqref{eq:cc-6} holds because 
$(q_n)_{n\in \mathbb{N}}$ is monotonically decreasing
and $\log(1+t)\leq t$ for all $t\in [0,\infty)$. 
\eqref{eq:cc-7} follows from~\eqref{eq:cc-4}. 
\eqref{eq:cc-8} holds since $\alpha>1$. 

\emph{Case 2: $\alpha<1$.} 
For all $n\in \mathbb{N}$
\begin{align}
\hat{q}-q_n
&=\sum_{\substack{x\in \supp (P_X), \\ y\in \supp(P_Y)}}
P_{XY}(x,y)^\alpha \left((\hat{Q}_X(x)\hat{R}_Y(y) )^{1-\alpha}-(Q_X^{(n)}(x)R_Y^{(n)}(y) )^{1-\alpha}\right)
\\
&=\sum_{\substack{x\in \supp (P_X), \\ y\in \supp(P_Y)}}
P_{XY}(x,y)^\alpha (Q_X^{(n)}(x)R_Y^{(n)}(y) )^{1-\alpha} 
\left(\frac{(\hat{Q}_X(x)\hat{R}_Y(y) )^{1-\alpha}}{(Q_X^{(n)}(x)R_Y^{(n)}(y) )^{1-\alpha}}-1\right)
\\
&\leq q_n \left(
M((\hat{Q}_X \hat{R}_Y)^{1-\alpha}/(Q_X^{(n)} R_Y^{(n)})^{1-\alpha}) 
-1\right).
\label{eq:cc2}
\end{align}

For all $n\in \mathbb{N}$
\begin{align}
\frac{\hat{q}}{q_n}
&\leq M((\hat{Q}_X \hat{R}_Y)^{1-\alpha}/(Q_X^{(n)} R_Y^{(n)})^{1-\alpha}) 
\label{eq:cc21}\\
&\leq M((\hat{Q}_X \hat{R}_Y)^{1-\alpha}/(Q_X^{(n)} R_Y^{(n)})^{1-\alpha}) 
M((Q_X^{(n)} R_Y^{(n)})^{1-\alpha}/(\hat{Q}_X \hat{R}_Y)^{1-\alpha}) 
\label{eq:cc22}\\
&= \exp\left(
d_H( (Q_X^{(n)} R_Y^{(n)})^{1-\alpha}, (\hat{Q}_X \hat{R}_Y)^{1-\alpha} ) 
\right)
\label{eq:cc23}\\
&\leq \exp\left( \lvert 1-\alpha\rvert 
d_H( Q_X^{(n)} R_Y^{(n)}, \hat{Q}_X \hat{R}_Y) 
\right)
\label{eq:cc24}\\
&=\exp\left( \lvert 1-\alpha\rvert
( d_H( Q_X^{(n)}, \hat{Q}_X) 
+ d_H( R_Y^{(n)}, \hat{R}_Y)  )
\right)
\label{eq:cc3}\\
&\leq \exp\left(\lvert 1-\alpha\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right).
\label{eq:cc4}
\end{align}
\eqref{eq:cc21} follows from~\eqref{eq:cc2} because $\hat{q}=\exp((\alpha-1)I_\alpha^{\downarrow\downarrow}(X:Y)_P)>0$. 
\eqref{eq:cc22} follows from Lemma~\ref{lem:cc-m1}.
\eqref{eq:cc3} follows from the additivity of Hilbert’s projective metric with respect to the product of PMFs. 
\eqref{eq:cc4} follows from Theorem~\ref{thm:cc-linear}. 
We conclude that for all $n\in \mathbb{N}$
\begin{align}
0\leq x_{n}-I_\alpha^{\downarrow\downarrow}(X:Y)_P 
&=\frac{1}{1-\alpha}\log\left(1+\frac{\hat{q}}{q_{n}}-1\right)
\\
&\leq \frac{1}{1-\alpha} \left(\frac{\hat{q}}{q_{n}}-1\right)
\label{eq:cc6}\\
&\leq \frac{1}{1-\alpha} \left(
\exp\left(\lvert 1-\alpha\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right)
-1\right)
\label{eq:cc7}
\\
&= \frac{1}{\lvert\alpha-1\rvert } \left(
\exp\left(\lvert\alpha-1\rvert (1+\gamma)\gamma^{2n} d_H(Q_X^{(0)},\hat{Q}_X) \right)
-1\right).
\label{eq:cc8}
\end{align}
\eqref{eq:cc6} holds because 
$(q_n)_{n\in \mathbb{N}}$ is monotonically increasing 
and $\log(1+t)\leq t$ for all $t\in [0,\infty)$. 
\eqref{eq:cc7} follows from~\eqref{eq:cc4}. 
\eqref{eq:cc8} holds since $\alpha<1$.
This completes the proof of~(a).

(b) can be proven analogously by applying Corollary~\ref{cor:cc-linear1}~(b) in place of Corollary~\ref{cor:cc-linear1}~(a). 
\end{proof}






\section{Properties of Hilbert's projective metric}\label{app:hilbert}
Let $V,W$ be real vector spaces and let $C\subseteq V,K\subseteq W$ be cones. 
A map $f:C\rightarrow K$ is \emph{order-preserving} 
if $x\leq_C y$ implies $f(x)\leq_K f(y)$ for all $x,y\in C$. 
A map $f:C\rightarrow K$ is \emph{order-reversing} 
if $x\leq_C y$ implies $f(y)\leq_K f(x)$ for all $x,y\in C$. 
A map $f:C\rightarrow K$ is \emph{homogeneous of degree $r\in \mathbb{R}$} 
if $f(\alpha x)=\alpha^rf(x)$ for all $x\in C,\alpha \in (0,\infty)$.

Hilbert's projective metric has the following properties.~\cite{lemmens2012nonlinear,lemmens2013birkhoffs}
\begin{enumerate}[label=(\alph*)]
\item \emph{Non-negativity:} 
$d_H(x,y)\in [0,\infty]$ for all $x,y\in C$.
\item \emph{Symmetry:} 
$d_H(x,y)=d_H(y,x)$ for all $x,y\in C$.
\item \emph{Scale invariance:} 
$d_H(\alpha x,\beta y)=d_H(x,y)$ for all $\alpha,\beta \in (0,\infty),x,y\in C$.
\item \emph{Projective definiteness:} If $C$ is a closed cone in a Banach space $(V,\lVert\cdot \rVert)$, then for all $x,y\in C$: $d_H(x,y)=0$ iff there exists $\alpha\in (0,\infty)$ such that $x=\alpha y$.
\item \emph{Homogeneous, order-preserving maps:}~\cite[Corollary~2.1.4]{lemmens2012nonlinear} 
Suppose $C\subseteq V$ and $K\subseteq W$ are closed cones.  
Let $f:C\rightarrow K$ be a map that is homogeneous of degree $r\in (0,\infty)$ and order-preserving. Then,  
\begin{align}
d_H(f(x),f(y))\leq r d_H(x,y)
\end{align}
for all $x,y\in C$ such that $x\sim_C y$.
\item \emph{Homogeneous, order-reversing maps:}~\cite[Corollary~2.1.5]{lemmens2012nonlinear} 
Suppose $C\subseteq V$ and $K\subseteq W$ are closed cones.  
Let $f:C\rightarrow K$ be a map that is homogeneous of degree $r\in (-\infty,0)$ and order-reversing. Then, 
\begin{align}
d_H(f(x),f(y))\leq \lvert r\rvert d_H(x,y)
\end{align} 
for all $x,y\in C$ such that $x\sim_C y$.
\item \emph{Birkhoff-Hopf theorem:}~\cite{birkhoff1957extensions,hopf1963inequality,lemmens2012nonlinear,lemmens2013birkhoffs} 
Let $L:V\rightarrow W$ be a linear map such that $L(C)\subseteq K$. 
The \emph{Birkhoff contraction ratio of $L$} is defined as 
\begin{align}
\kappa (L)\coloneqq \inf \{\alpha\in [0,\infty): d_H(L(x),L(y))\leq \alpha d_H(x,y) \text{ for all } x,y\in C \text{ such that }x\sim_C y\},
\end{align}
and the \emph{projective diameter of $L$} is defined as
\begin{align}
\delta (L)\coloneqq \sup \{d_H(L(x),L(y)):x,y\in C \text{ such that }L(x)\sim_K L(y) \}.
\end{align}

The Birkhoff-Hopf theorem then asserts that 
\begin{align}
\kappa (L)=\tanh \left(\frac{\delta (L)}{4}\right)
\end{align}
where $\tanh(\infty)= 1$.
\end{enumerate}








\section{Proofs for Section~\ref{ssec:linear}}
\subsection{Proof of Theorem~\ref{thm:linear}}\label{app:linear}
\begin{lem}\label{lem:quantum-r}
All of the following hold.
\begin{enumerate}[label=(\alph*)]
\item Let $r\in [-1,1]$. 
Then, for all positive semidefinite $X,Y\in \mathcal{L}(A)$ such that $X\sim Y$
\begin{align}
d_H(X^r,Y^r)\leq \lvert r\rvert d_H(X,Y).
\end{align}
\item Let $Z_{AB}\in \mathcal{L}(AB)$ be positive semidefinite. 
Let $L:\{X_A\in \mathcal{L}(A):X_A^\dagger=X_A\}\rightarrow \{Y_B\in \mathcal{L}(B):Y_B^\dagger=Y_B\},X_A\mapsto \tr_A[Z_{AB}X_A]$. 
Then, for all positive semidefinite $X_A,Y_A\in \mathcal{L}(A)$ such that $X_A\sim Y_A$
\begin{align}\label{eq:lem-z}
d_H(L(X_A),L(Y_A))\leq \kappa (L) d_H(X_A,Y_A).
\end{align}
Moreover, 
\begin{align}\label{eq:delta-l-sup}
\delta (L)
&=\sup_{\substack{\ket{\phi},\ket{\psi}\in A:\\ \brak{\phi}=1,\brak{\psi}=1}} 
d_H(L(\proj{\phi}),L(\proj{\psi})).
\end{align}
\end{enumerate}
\end{lem}

\begin{proof}[Proof of (a)]
Let $f(X)\coloneqq X^r$ for all positive semidefinite $X\in \mathcal{L}(A)$. 
$f$ is homogeneous of degree $r$.

\emph{Case 1: $r\in (0,1]$.} 
Then $f$ is operator monotone (i.e., order-preserving). 
The assertion then follows from Appendix~\ref{app:hilbert}~(e).

\emph{Case 2: $r\in [-1,0)$.} 
Then $f$ is operator anti-monotone (i.e., order-reversing). 
The assertion then follows from Appendix~\ref{app:hilbert}~(f).

\emph{Case 3: $r=0$.} 
Then $X^r=Y^r$ because $X\sim Y$. Hence, $d_H(X^r,Y^r)=d_H(X^r,X^r)=0$ by the projective definiteness of Hilbert's projective metric, see Appendix~\ref{app:hilbert}~(d).
\end{proof}
\begin{proof}[Proof of (b)]

$L$ is an $\mathbb{R}$-linear map (i.e., homogeneous of degree $1$) on the vector space of self-adjoint operators on $A$, 
and $L$ is operator monotone (i.e., order-preserving) on the cone of positive semidefinite operators on $A$. 
The assertion in~\eqref{eq:lem-z} then follows from Appendix~\ref{app:hilbert}~(g).

It remains to prove~\eqref{eq:delta-l-sup}. 
Let $S\coloneqq \{\proj{\phi}: \ket{\phi}\in A,\brak{\phi}=1\}$. Then,
\begin{align}
\delta (L)
&=\sup_{\substack{X,Y\in \mathcal{L}(A)\setminus \{0\}: \\ X\geq 0,Y\geq 0}} d_H(L(X),L(Y))
\label{eq:proof-lem-1}\\
&=\sup_{X,Y\in \mathcal{S}(A)} d_H(L(X),L(Y))
\label{eq:proof-lem-2}\\
&=\sup_{X,Y\in S} d_H(L(X),L(Y))
\label{eq:proof-lem-3}\\
&=\sup_{\substack{\ket{\phi},\ket{\psi}\in A:\\ \brak{\phi}=1,\brak{\psi}=1}} 
d_H(L(\proj{\phi}),L(\proj{\psi})).
\end{align}
\eqref{eq:proof-lem-2} follows from the scale invariance of Hilbert's projective metric, see Appendix~\ref{app:hilbert}~(c). 
\eqref{eq:proof-lem-3} holds because the convex hull of $S$ is $\mathcal{S}(A)$~\cite[Lemma~A.3.4]{lemmens2012nonlinear}.
\end{proof}


\begin{proof}[Proof of Theorem~\ref{thm:linear}]
Let $\sigma_A,\tilde{\sigma}_A\in \mathcal{S}_{\sim\rho_A}(A)$. 
Let us define the linear map 
$L:\{X_A\in \mathcal{L}(A):X_A^\dagger=X_A\}\rightarrow \{Y_B\in \mathcal{L}(B):Y_B^\dagger=Y_B\},X_A\mapsto \tr_A[\rho_{AB}^\alpha X_A]$. 
\begin{align}
d_H(\mathcal{N}_{A\rightarrow B}(\sigma_A), \mathcal{N}_{A\rightarrow B}(\tilde{\sigma}_A))
&=d_H((\tr_A[\rho_{AB}^\alpha \sigma_A^{1-\alpha}])^{\frac{1}{\alpha}},(\tr_A[\rho_{AB}^\alpha \tilde{\sigma}_A^{1-\alpha}])^{\frac{1}{\alpha}} )
\label{eq:proof-thml1}\\
&\leq \frac{1}{\alpha} d_H(\tr_A[\rho_{AB}^\alpha \sigma_A^{1-\alpha}],\tr_A[\rho_{AB}^\alpha \tilde{\sigma}_A^{1-\alpha}])
\label{eq:proof-thml2}
\\
&= \frac{1}{\alpha} d_H(L(\sigma_A^{1-\alpha}),L(\tilde{\sigma}_A^{1-\alpha}))
\\
&\leq \frac{1}{\alpha} \kappa (L) d_H(\sigma_A^{1-\alpha},\tilde{\sigma}_A^{1-\alpha})
\label{eq:proof-thml3}
\\
&\leq \frac{\lvert 1-\alpha\rvert}{\alpha}\kappa (L) d_H(\sigma_A,\tilde{\sigma}_A)
=\gamma \kappa (L) d_H(\sigma_A,\tilde{\sigma}_A)
\label{eq:proof-thml4}
\\
&\leq \gamma d_H(\sigma_A,\tilde{\sigma}_A)
\label{eq:proof-thml5}
\end{align}
\eqref{eq:proof-thml1} follows from Definition~\ref{def:am-quantum} and the scale invariance of Hilbert's projective metric, see Appendix~\ref{app:hilbert}~(c). 
\eqref{eq:proof-thml2} follows from Lemma~\ref{lem:quantum-r}~(a) because $\alpha\in (1,2]\subseteq [1,\infty)$ and $\rho_A\ll \sigma_A$, $\rho_A\ll \tilde{\sigma}_A$. 
\eqref{eq:proof-thml3} follows from Lemma~\ref{lem:quantum-r}~(b) because $\sigma_A\sim \tilde{\sigma}_A$. 
The inequality in~\eqref{eq:proof-thml4} follows from Lemma~\ref{lem:quantum-r}~(a) because $\alpha\in (1,2]\subseteq [0,2]$. 
\eqref{eq:proof-thml4} holds because $\kappa(L)\in [0,1]$, see Appendix~\ref{app:hilbert}~(g). 
This completes the proof of~\eqref{eq:thm-linear-sigma1}. 
The proof of~\eqref{eq:thm-linear-tau1} is analogous.
This completes the proof of~(a).

The assertion in~(b) follows from the proof of~(a), see~\eqref{eq:proof-thml4}, and Lemma~\ref{lem:quantum-r}~(b), see~\eqref{eq:delta-l-sup}.
\end{proof}


\subsection{Proof of Corollary~\ref{cor:linear1}}\label{app:linear1}
\begin{proof}
By the fixed-point property of minimizers for the doubly minimized PRMI~\cite{burri2024properties}, 
\begin{align}
\hat{\sigma}_A&=\mathcal{N}_{B\rightarrow A}\circ \mathcal{N}_{A\rightarrow B}(\hat{\sigma}_A)
\in \mathcal{S}_{\ll \rho_A}(A),
\label{eq:fixed-sigma}\\
\hat{\tau}_B&=\mathcal{N}_{A\rightarrow B}(\hat{\sigma}_A)
\in \mathcal{S}_{\ll \rho_B}(B).
\label{eq:fixed-tau}
\end{align}
Since $\alpha\geq 1$, $\hat{\sigma}_A\in \mathcal{S}_{\rho_A\ll}(A)$ and $\hat{\tau}_B\in \mathcal{S}_{\rho_B\ll}(B)$~\cite{burri2024properties}. 
We conclude that $\hat{\sigma}_A\sim \rho_A$ and $\hat{\tau}_B\sim \rho_B$.

For all $n\in \mathbb{N}$,
\begin{align}
d_H(\sigma_A^{(n+1)},\hat{\sigma}_A) 
&=d_H(\mathcal{N}_{B\rightarrow A}\circ \mathcal{N}_{A\rightarrow B}(\sigma_A^{(n)}),\mathcal{N}_{B\rightarrow A}\circ \mathcal{N}_{A\rightarrow B}(\hat{\sigma}_A))
\label{eq:proof-cor-1}\\
&\leq \gamma d_H(\mathcal{N}_{A\rightarrow B}(\sigma_A^{(n)}), \mathcal{N}_{A\rightarrow B}(\hat{\sigma}_A))
\label{eq:proof-cor-2}\\
&\leq \gamma^2 d_H(\sigma_A^{(n)},\hat{\sigma}_A).
\label{eq:proof-cor-3}
\end{align}
\eqref{eq:proof-cor-1} follows from Definition~\ref{def:am-quantum} and~\eqref{eq:fixed-sigma}.
\eqref{eq:proof-cor-2} and~\eqref{eq:proof-cor-3} follow from Theorem~\ref{thm:linear}~(a).

By recursion, we conclude that for all $n\in \mathbb{N}$
\begin{align}
d_H(\sigma_A^{(n)},\hat{\sigma}_A) \leq \gamma^{2n} d_H(\sigma_A^{(0)},\hat{\sigma}_A).
\label{eq:proof-cor-31}
\end{align}

For all $n\in \mathbb{N}$,
\begin{align}
d_H(\tau_B^{(n)},\hat{\tau}_B) 
&=d_H(\mathcal{N}_{A\rightarrow B}(\sigma_A^{(n)}),\mathcal{N}_{A\rightarrow B}(\hat{\sigma}_A))
\label{eq:proof-cor-4}\\
&\leq \gamma d_H(\sigma_A^{(n)},\hat{\sigma}_A)
\label{eq:proof-cor-5}\\
&\leq \gamma^{2n+1} d_H(\sigma_A^{(0)},\hat{\sigma}_A) .
\label{eq:proof-cor-6}
\end{align}
\eqref{eq:proof-cor-4} follows from Definition~\ref{def:am-quantum} and~\eqref{eq:fixed-tau}. 
\eqref{eq:proof-cor-5} follows from Theorem~\ref{thm:linear}~(a).
\eqref{eq:proof-cor-6} follows from~\eqref{eq:proof-cor-31}.
This completes the proof of~(a). 

(b) can be proven analogously by applying Theorem~\ref{thm:linear}~(b) in place of Theorem~\ref{thm:linear}~(a).
\end{proof}

\subsection{Proof of Corollary~\ref{cor:linear2}}\label{app:linear2}
\begin{lem}\label{lem:m1}
Let $\alpha\in (1,\infty)$ and let $\sigma,\tau\in \mathcal{S}(A)$ be such that $\sigma\sim \tau$. 
Then, $M(\sigma^{1-\alpha}/\tau^{1-\alpha})\geq 1$.
\end{lem}
\begin{proof}
\begin{align}
M(\sigma^{1-\alpha}/\tau^{1-\alpha})
&=\lVert \tau^{\frac{\alpha-1}{2}}\sigma^{1-\alpha} \tau^{\frac{\alpha-1}{2}}\rVert_\infty
\label{eq:proof-m1}\\
&=\max_{\ket{\phi}\in A: \brak{\phi}=1} 
\tr[\tau^{\frac{\alpha-1}{2}}\sigma^{1-\alpha} \tau^{\frac{\alpha-1}{2}} \proj{\phi}]
\\
&=\max_{\rho\in \mathcal{S}(A)} 
\tr[\tau^{\frac{\alpha-1}{2}}\sigma^{1-\alpha} \tau^{\frac{\alpha-1}{2}} \rho]
\\
&\geq 
\tr[\tau^{\frac{\alpha-1}{2}}\sigma^{1-\alpha} \tau^{\frac{\alpha-1}{2}} \tau]
=\tr[\tau^{\alpha}\sigma^{1-\alpha}]
\\
&\geq \lVert \tau^\alpha \rVert_{1/\alpha} \cdot \lVert \sigma^{\alpha-1}\rVert_{1/(\alpha -1)}^{-1}
\label{eq:proof-m3}\\
&=\tr[\tau]^\alpha \cdot (\tr[\sigma]^{\alpha-1})^{-1}
=1
\label{eq:proof-m4}
\end{align}
\eqref{eq:proof-m1} follows from~\eqref{eq:m-xy-quantum}. 
\eqref{eq:proof-m3} follows from the reverse H\"older inequality~\cite[Lemma~3.1]{tomamichel2016quantum}.
The last equality in~\eqref{eq:proof-m4} follows from $\tr[\tau]=1=\tr[\sigma]$.
\end{proof}


\begin{proof}[Proof of Corollary~\ref{cor:linear2}]
Let $\hat{q}\coloneqq Q_\alpha (\rho_{AB}\| \hat{\sigma}_A\otimes \hat{\tau}_B)$. 
Let $\tau_B^{(n)},\sigma_A^{(n+1)}$ be given by Definition~\ref{def:am-quantum} for all $n\in \mathbb{N}$. 
Let $q_n\coloneqq Q_\alpha (\rho_{AB}\| \sigma_A^{(n)}\otimes \tau_B^{(n)})$ for all $n\in \mathbb{N}$. 

For all $n\in \mathbb{N}$
\begin{align}
q_n-\hat{q}
&= \tr[\rho_{AB}^\alpha ( (\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} - (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha} )]
\\
&=\tr[(\hat{\sigma}_A\otimes \hat{\tau}_B)^{\frac{1-\alpha}{2}}\rho_{AB}^\alpha 
(\hat{\sigma}_A\otimes \hat{\tau}_B)^{\frac{1-\alpha}{2}} 
\nonumber\\
&\qquad \left( (\hat{\sigma}_A\otimes \hat{\tau}_B)^{-\frac{1}{2}(1-\alpha)} 
(\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} 
(\hat{\sigma}_A\otimes \hat{\tau}_B)^{-\frac{1}{2}(1-\alpha)} 
-1\right)]
\label{eq:q1}\\
&\leq \tr[\rho_{AB}^\alpha 
(\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha} ]
\left(M((\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} / (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha}) -1 \right)
\label{eq:q2}\\
&= \hat{q} \left(M((\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} / (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha}) -1 \right).
\label{eq:q3}
\end{align}
\eqref{eq:q1} holds because $\sigma_A^{(n)}\sim \rho_A\sim \hat{\sigma}_A$ and $\tau_B^{(n)}\sim \rho_B\sim \hat{\tau}_B$. 
\eqref{eq:q2} follows from~\eqref{eq:m-xy-quantum}. 

For all $n\in \mathbb{N}$
\begin{align}
\frac{q_n}{\hat{q}}
&\leq M((\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} / (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha})
\label{eq:q30}\\
&\leq M((\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} / (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha})
M( (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha} / (\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} )
\label{eq:q4}\\
&= \exp \left(d_H( 
(\sigma_A^{(n)}\otimes \tau_B^{(n)})^{1-\alpha} , (\hat{\sigma}_A\otimes \hat{\tau}_B)^{1-\alpha}
)\right)
\\
&\leq \exp \left(\lvert 1-\alpha\rvert
d_H(\sigma_A^{(n)}\otimes \tau_B^{(n)},\hat{\sigma}_A\otimes \hat{\tau}_B) \right)
\label{eq:q40}\\
&= \exp \left(\lvert 1-\alpha\rvert
(d_H(\sigma_A^{(n)},\hat{\sigma}_A)
+d_H(\tau_B^{(n)},\hat{\tau}_B))\right)
\label{eq:q41}\\
&\leq \exp \left(\lvert 1-\alpha\rvert
(1+\gamma)\gamma^{2n}d_H(\sigma_A^{(0)},\hat{\sigma}_A) \right).
\label{eq:q42}
\end{align}
\eqref{eq:q30} follows from~\eqref{eq:q3} because $\hat{q}=\exp((\alpha-1)I_\alpha^{\downarrow\downarrow}(A:B)_\rho)>0$. 
\eqref{eq:q4} follows from Lemma~\ref{lem:m1}. 
\eqref{eq:q40} follows from Lemma~\ref{lem:quantum-r}~(a) because $\alpha\in [1,2]\subseteq [0,2]$. 
\eqref{eq:q41} follows from the additivity of Hilbert's projective metric with respect to the tensor product~\cite{reeb2011hilbert}. 
\eqref{eq:q42} follows from Corollary~\ref{cor:linear1}~(a). 
We conclude that for all $n\in \mathbb{N}$
\begin{align}
0\leq x_{n}-I_\alpha^{\downarrow\downarrow}(A:B)_\rho 
&=\frac{1}{\alpha-1}\log\left(1+\frac{q_n}{\hat{q}}-1\right)
\\
&\leq \frac{1}{\alpha-1} \left(\frac{q_n}{\hat{q}}-1\right)
\label{eq:q6}\\
&\leq \frac{1}{\alpha-1 } \left(
\exp\left(\lvert 1-\alpha\rvert (1+\gamma)\gamma^{2n} d_H(\sigma_A^{(0)},\hat{\sigma}_A) \right)
-1\right)
\label{eq:q7}
\\
&= \frac{1}{\lvert \alpha-1 \rvert} \left(
\exp\left(\lvert \alpha-1\rvert (1+\gamma)\gamma^{2n} d_H(\sigma_A^{(0)},\hat{\sigma}_A) \right)
-1\right).
\label{eq:q8}
\end{align}
\eqref{eq:q6} holds because 
$(q_n)_{n\in \mathbb{N}}$ is monotonically decreasing
and $\log(1+t)\leq t$ for all $t\in [0,\infty)$. 
\eqref{eq:q7} follows from~\eqref{eq:q42}. 
\eqref{eq:q8} holds since $\alpha>1$. 
This completes the proof of~(a).

(b) can be proven analogously by applying Corollary~\ref{cor:linear1}~(b) in place of Corollary~\ref{cor:linear1}~(a). 
\end{proof}


\subsection{Proposition for Remark~\ref{rem:dh-sigma}}\label{app:dh-sigma}
\begin{lem}[Upper bound on Hilbert's metric for states]\label{lem:dh-minspec}
Let $\sigma,\tau\in \mathcal{S}(A)$ be such that $\sigma\sim \tau$. Then,
\begin{align}
d_H(\sigma,\tau)
\leq -2\log \min\{\min (\spec(\sigma)\setminus \{0\}),\min(\spec(\tau)\setminus \{0\})\}.
\end{align}
\end{lem}
\begin{proof}
\begin{align}
M(\sigma/\tau) &=\lVert \tau^{-\frac{1}{2}}\sigma\tau^{-\frac{1}{2}}\rVert_\infty 
\leq \lVert \tau^{-1}\rVert_\infty = \frac{1}{\min (\spec(\tau)\setminus \{0\})}
\\
M(\tau/\sigma) &=\lVert \sigma^{-\frac{1}{2}}\tau\sigma^{-\frac{1}{2}}\rVert_\infty 
\leq \lVert \sigma^{-1}\rVert_\infty = \frac{1}{\min (\spec(\sigma)\setminus \{0\})}
\end{align}
Therefore,
\begin{align}
d_H(\sigma,\tau)
\leq 2 \log \max\{M(\sigma/\tau),M(\tau/\sigma)\}
&\leq -2\log \min\{\min (\spec(\sigma)\setminus \{0\}),\min(\spec(\tau)\setminus \{0\})\}.
\end{align}
\end{proof}

\begin{lem}[Lower bound on spectrum of states from alternating minimization]\label{lem:spectrum-geq1}
Let $\alpha\in (1,\infty)$, 
$\rho_{AB}\in \mathcal{S}(AB)$, 
$\sigma_A^{(0)}\in \mathcal{S}_{\sim \rho_A}(A)$. 
Let $\tau_B^{(n)}$, $\sigma_A^{(n+1)}$ for $n\in \mathbb{N}$ be given by Definition~\ref{def:am-quantum}. 
Let us define the following real numbers. 
\begin{align}
\lambda_A&\coloneqq \min(\spec(\tr_B[\rho_{AB}^\alpha])\setminus\{0\})
\\
\lambda_B&\coloneqq \min(\spec(\tr_A[\rho_{AB}^\alpha])\setminus\{0\})
\\
\lambda_{A,n}
&\coloneqq \min (\spec(\sigma_A^{(n)})\setminus \{0\})
&&\forall n\in \mathbb{N}
\\
\lambda_{B,n}
&\coloneqq \min (\spec(\tau_B^{(n)})\setminus \{0\}) 
&&\forall n\in \mathbb{N}
\\
q_0 
&\coloneqq Q_\alpha(\rho_{AB}\| \sigma_A^{(0)}\otimes \tau_B^{(0)})
\\
c_A
&\coloneqq (\lambda_A/q_0)^{\frac{1}{\alpha}}
\\
c_B
&\coloneqq (\lambda_B/q_0)^{\frac{1}{\alpha}}
\end{align}
Then 
$\lambda_{A,n+1}\geq c_{A}>0$ and 
$\lambda_{B,n}\geq c_{B}>0$
for all $n\in \mathbb{N}$.
\end{lem}
\begin{proof}
For all $n \in \mathbb{N}$, let
\begin{subequations}\label{eq:def-12}
\begin{align}
x_{n}&\coloneqq D_\alpha (\rho_{AB}\| \sigma_A^{(n)}\otimes \tau_B^{(n)}), \qquad 
q_n\coloneqq Q_\alpha (\rho_{AB}\| \sigma_A^{(n)}\otimes \tau_B^{(n)}),
\\
x_{n+1/2}&\coloneqq D_\alpha (\rho_{AB}\| \sigma_A^{(n+1)}\otimes \tau_B^{(n)}), \qquad 
q_{n+1/2}\coloneqq Q_\alpha (\rho_{AB}\| \sigma_A^{(n+1)}\otimes \tau_B^{(n)}).
\end{align}
\end{subequations}
The sequence $(x_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically decreasing by construction, see~\eqref{eq:tau-optimal} and~\eqref{eq:inf-tau}. 
$x_n\in [0,\infty)$ for all $n\in \frac{1}{2}\mathbb{N}$ due to the non-negativity of the Petz divergence. 
Hence, $q_n=\exp((\alpha-1)x_n)\in [1,\infty)$ for all $n\in \frac{1}{2}\mathbb{N}$, and 
$(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically decreasing. 

Let $\mathcal{N}_{A\rightarrow B}$, $\mathcal{N}_{B\rightarrow A}$ be defined as in~\eqref{eq:def-N}.
By~\eqref{eq:inf-tau}, we have for all $n\in \mathbb{N}$ 
\begin{align}
q_n&=\exp\left((\alpha-1)D_\alpha (\rho_{AB}\| \sigma_A^{(n)}\otimes \mathcal{N}_{A\rightarrow B}(\sigma_A^{(n)}))\right)
=\tr[(\tr_A[\rho_{AB}^\alpha \sigma_A^{(n)1-\alpha}])^{\frac{1}{\alpha}} ]^\alpha,
\label{eq:qn0}\\
q_{n+1/2}&=\exp\left((\alpha-1)D_\alpha (\rho_{AB}\| \mathcal{N}_{B\rightarrow A}(\tau_B^{(n)})\otimes \tau_B^{(n)} )\right)
=\tr[(\tr_B[\rho_{AB}^\alpha \tau_B^{(n)1-\alpha}])^{\frac{1}{\alpha}} ]^\alpha.
\label{eq:qn1}
\end{align} 

For all $n\in \mathbb{N}$
\begin{align}
q_0 \tau_B^{(n)\alpha}
&\geq q_n \tau_B^{(n)\alpha}
\label{eq:q0qn1}\\
&=q_{n}\left(\mathcal{N}_{A\rightarrow B}(\sigma_{A}^{(n)})\right)^\alpha
\stackrel{\eqref{eq:qn0}}{=} \tr_A[\rho_{AB}^\alpha \sigma_A^{(n)1-\alpha} ]
\\
&\geq \tr_A[\rho_{AB}^\alpha \sigma_A^{(n)0}] 
=\tr_A[\rho_{AB}^\alpha]
\geq \lambda_B\rho_B^0 =\lambda_B \tau_B^{(n)0}.
\end{align}
\eqref{eq:q0qn1} holds because $(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically decreasing. 
Therefore, for all $n\in \mathbb{N}$
\begin{align}
\lambda_{B,n}\geq \left(\frac{\lambda_B}{q_0}\right)^{\frac{1}{\alpha}}
=c_B.
\end{align}

For all $n\in \mathbb{N}$
\begin{align}
q_0 \sigma_A^{(n+1)\alpha}
&\geq q_{n+1/2} \sigma_A^{(n+1)\alpha}
\label{eq:q0qn2}\\
&=q_{n+1/2}\left(\mathcal{N}_{B\rightarrow A}(\tau_B^{(n)})\right)^\alpha
\stackrel{\eqref{eq:qn1}}{=} \tr_B[\rho_{AB}^\alpha \tau_B^{(n)1-\alpha} ]
\\
&\geq \tr_B[\rho_{AB}^\alpha \tau_B^{(n)0}] 
=\tr_B[\rho_{AB}^\alpha ]
\geq \lambda_A\rho_A^0 =\lambda_A \sigma_A^{(n+1)0}.
\end{align}
\eqref{eq:q0qn2} holds because $(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically decreasing. 
Therefore, for all $n\in \mathbb{N}$
\begin{align}
\lambda_{A,n+1}\geq \left(\frac{\lambda_A}{q_0}\right)^{\frac{1}{\alpha}}
=c_A.
\end{align}
\end{proof}


\begin{prop}[Upper bound independent of $\hat{\sigma}_A$]\label{prop:bound}
Let $\alpha\in (1,\infty)$, 
$\rho_{AB}\in \mathcal{S}(AB)$, 
$(\hat{\sigma}_A,\hat{\tau}_B)\in \argmin_{(\sigma_A,\tau_B)\in \mathcal{S}(A)\times \mathcal{S}(B)}D_\alpha (\rho_{AB}\| \sigma_A\otimes \tau_B)$. 
Let $\sigma_A^{(0)}\in \mathcal{S}_{\rho_A\ll}(A)$ 
and let $\mathcal{N}_{A\rightarrow B}$ be given by Definition~\ref{def:am-quantum}. 
Moreover, let us define the following objects.
\begin{subequations}\label{eq:def-linear-c0}
\begin{align}
\lambda_A&\coloneqq \min(\spec(\tr_B[\rho_{AB}^\alpha])\setminus\{0\})
\\
\tilde{\sigma}_A^{(0)}
&\coloneqq \frac{\rho_A^0 \sigma_A^{(0)} \rho_A^0}{\tr[\rho_A^0\sigma_A^{(0)}]}
\\
q_0 
&\coloneqq Q_\alpha(\rho_{AB}\| \tilde{\sigma}_A^{(0)}\otimes \mathcal{N}_{A\rightarrow B}(\tilde{\sigma}_A^{(0)}) )
\\
c_A
&\coloneqq (\lambda_A/q_0)^{\frac{1}{\alpha}}
\\
c_0
&\coloneqq -2\log \min\{\min ( \spec(\tilde{\sigma}_A^{(0)})\setminus \{0\} ),c_A\}
\end{align}
\end{subequations}
Then,
$d_H(\tilde{\sigma}_A^{(0)},\hat{\sigma}_A)
\leq c_0.$
\end{prop}
\begin{proof}
$\hat{\sigma}_A\in \mathcal{S}_{\sim \rho_A}(A)$ because $\alpha\in (1,\infty)$~\cite{burri2024properties}. 
Therefore, $\hat{\sigma}_A\sim \rho_A\sim \tilde{\sigma}_A^{(0)}$.
\begin{align}
d_H(\tilde{\sigma}_A^{(0)},\hat{\sigma}_A)
&\leq -2\log \min\{\min (\spec(\tilde{\sigma}_A^{(0)})\setminus \{0\}),\min(\spec(\hat{\sigma}_A)\setminus \{0\})\}
\label{eq:proof-prop1}\\
&\leq -2\log \min\{\min (\spec(\tilde{\sigma}_A^{(0)})\setminus \{0\}),c_A\} 
=c_0
\label{eq:proof-prop2}
\end{align}
\eqref{eq:proof-prop1} follows from Lemma~\ref{lem:dh-minspec}. 
\eqref{eq:proof-prop2} follows from Lemma~\ref{lem:spectrum-geq1}. 
\end{proof}


\section{Proofs for Section~\ref{ssec:sublinear}}\label{app:proof-frechet}
The proof of Theorem~\ref{thm:sublinear} invokes two lemmas established in advance.

\subsection{Lemmas for Theorem~\ref{thm:sublinear}}\label{app:lemmas}
\begin{lem}[Lower bound on spectrum of states from alternating minimization]\label{lem:spectrum-leq1}
Let $\alpha\in (\frac{1}{2},1)$, 
$\rho_{AB}\in \mathcal{S}(AB)$, 
$\sigma_A^{(0)}\in \mathcal{S}_{\sim \rho_A}(A)$. 
Let $\tau_B^{(n)}$, $\sigma_A^{(n+1)}$ for $n\in \mathbb{N}$ be given by Definition~\ref{def:am-quantum}. 
Let us define the following real numbers. 
\begin{align}
\lambda_A&\coloneqq \min(\spec(\tr_B[\rho_{AB}^\alpha])\setminus\{0\})
\\
\lambda_B&\coloneqq \min(\spec(\tr_A[\rho_{AB}^\alpha])\setminus\{0\})
\\
\lambda_{A,n}
&\coloneqq \min (\spec(\sigma_A^{(n)})\setminus \{0\})
&&\forall n\in \mathbb{N}
\label{eq:lambda-an}\\
\lambda_{B,n}
&\coloneqq \min (\spec(\tau_B^{(n)})\setminus \{0\}) 
&&\forall n\in \mathbb{N}
\label{eq:lambda-bn}\\
c_{A}&\coloneqq \min(1, \lambda_A^\frac{\alpha}{2\alpha-1} \lambda_B^{\frac{1-\alpha}{2\alpha-1}} ) \lambda_{A,0}
\\
c_{B}&\coloneqq \min(1, \lambda_A^\frac{1-\alpha}{2\alpha-1} \lambda_B^{\frac{(1-\alpha)^2}{(2\alpha-1)\alpha}} ) \lambda_B^{\frac{1}{\alpha}} \lambda_{A,0}^{\frac{1-\alpha}{\alpha}}
\label{eq:def-cb}
\end{align}
Then 
$\lambda_{A,n}\geq c_{A}>0$ and 
$\lambda_{B,n}\geq c_{B}>0$
for all $n\in \mathbb{N}$.
\end{lem}

\begin{proof}
For all $n \in \mathbb{N}$, let $(x_n)_{n\in \mathbb{N}},(q_n)_{n\in \mathbb{N}}$ be defined as in~\eqref{eq:def-12}. 
The sequence $(x_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically decreasing by construction, see~\eqref{eq:tau-optimal} and~\eqref{eq:inf-tau}. 
$x_n\in [0,\infty)$ for all $n\in \frac{1}{2}\mathbb{N}$ due to the non-negativity of the Petz divergence. 
Hence, $q_n=\exp(-(1-\alpha)x_n)\in (0,1]$ for all $n\in \frac{1}{2}\mathbb{N}$, and 
$(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically increasing. 

Let $\mathcal{N}_{A\rightarrow B}$, $\mathcal{N}_{B\rightarrow A}$ be defined as in~\eqref{eq:def-N}. 
For all $n\in \mathbb{N}$ 
\begin{align}
q_{n}\tau_{B}^{(n)\alpha}
=q_{n}\left(\mathcal{N}_{A\rightarrow B}(\sigma_{A}^{(n)})\right)^\alpha
&\stackrel{\eqref{eq:qn0}}{=} \tr_A[\rho_{AB}^\alpha \sigma_A^{(n)1-\alpha} ]
\label{eq:q-tau-alpha}\\
&\geq \lambda_{A,n}^{1-\alpha}\tr_A[\rho_{AB}^\alpha]
\geq \lambda_{A,n}^{1-\alpha}\lambda_B \rho_B^0
= \lambda_{A,n}^{1-\alpha}\lambda_B \tau_{B}^{(n)0},
\end{align}
which implies that 
\begin{equation}\label{eq:bn-an}
\lambda_{B,n}\geq \left(\frac{\lambda_B}{q_{n}}\right)^{\frac{1}{\alpha}} \lambda_{A,n}^{\frac{1-\alpha}{\alpha}}.
\end{equation}
For all $n\in \mathbb{N}$ 
\begin{align}
q_{n+1/2}\sigma_{A}^{(n+1)\alpha }
=q_{n+1/2}\left(\mathcal{N}_{B\rightarrow A}(\tau_{B}^{(n)})\right)^\alpha
&\stackrel{\eqref{eq:qn1}}{=} \tr_B[\rho_{AB}^\alpha \tau_B^{(n)1-\alpha} ]
\\
&\geq \lambda_{B,n}^{1-\alpha}\tr_B[\rho_{AB}^\alpha ]
\geq \lambda_{B,n}^{1-\alpha}\lambda_A \rho_A^0
=\lambda_{B,n}^{1-\alpha}\lambda_A \sigma_A^{(n+1)0}, 
\end{align}
which implies that 
\begin{equation}\label{eq:an-bn}
\lambda_{A,n+1}\geq \left(\frac{\lambda_A}{q_{n+1/2}}\right)^{\frac{1}{\alpha}} \lambda_{B,n}^{\frac{1-\alpha}{\alpha}}.
\end{equation}
We conclude that for all $n\in \mathbb{N}$
\begin{align}
\lambda_{A,n+1}&\stackrel{\substack{\eqref{eq:bn-an}\\ \eqref{eq:an-bn}}}{\geq} \left(\frac{\lambda_A}{q_{n+1/2}}\right)^{\frac{1}{\alpha}}
\left(\frac{\lambda_B}{q_{n}}\right)^{\frac{1-\alpha}{\alpha^2}} \lambda_{A,n}^{(\frac{1-\alpha}{\alpha})^2}
&\geq\left(\frac{\lambda_A^\alpha\lambda_B^{1-\alpha}}{q_{n+1/2}} \right)^{\frac{1}{\alpha^2}} \lambda_{A,n}^{(\frac{1-\alpha}{\alpha})^2}
\geq\left(\frac{\lambda_A^\alpha\lambda_B^{1-\alpha}}{q_{n+1}} \right)^{\frac{1}{\alpha^2}} \lambda_{A,n}^{(\frac{1-\alpha}{\alpha})^2}.
\label{eq:recursion-a}
\end{align}
The last two inequalities hold because $(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically increasing. 
\eqref{eq:recursion-a} is a recursion relation for $(\lambda_{A,n})_{n\in \mathbb{N}}$. 
Using again the monotonicity of $(q_n)_{n\in \frac{1}{2} \mathbb{N}}$, this recursion relation implies that for all $n\in \mathbb{N}$
\begin{align}\label{eq:lam-delta-a}
\lambda_{A,n}&\stackrel{\eqref{eq:recursion-a}}{\geq} \left(\frac{\lambda_A^\alpha \lambda_B^{1-\alpha}}{q_{n}} \right)^{\frac{1}{\alpha^2}\sum\limits_{k=0}^{n-1}(\frac{1-\alpha}{\alpha})^{2k}} 
\lambda_{A,0}^{(\frac{1-\alpha}{\alpha})^{2n}}
=\left(\frac{\lambda_A^\alpha \lambda_B^{1-\alpha}}{q_{n}} \right)^{\frac{1}{2\alpha-1}(1-(\frac{1-\alpha}{\alpha})^{2n})} 
\lambda_{A,0}^{(\frac{1-\alpha}{\alpha})^{2n}}
\eqqcolon c_{A,n}.
\end{align}
Combining~\eqref{eq:bn-an} with~\eqref{eq:lam-delta-a} implies that for all $n\in \mathbb{N}$
\begin{align}\label{eq:lam-delta-b}
\lambda_{B,n}
\geq \left(\frac{\lambda_B}{q_n}\right)^{\frac{1}{\alpha}} c_{A,n}^{\frac{1-\alpha}{\alpha}}
\eqqcolon c_{B,n}.
\end{align}

For all $n\in \mathbb{N}$
\begin{align}\label{eq:lam-an-a0}
\lambda_{A,n}
\stackrel{\eqref{eq:lam-delta-a}}{\geq} c_{A,n}
&\geq (\lambda_A^\alpha \lambda_B^{1-\alpha} )^{\frac{1}{2\alpha-1}(1-(\frac{1-\alpha}{\alpha})^{2n})} 
\lambda_{A,0}^{(\frac{1-\alpha}{\alpha})^{2n}}
\geq \min(1,(\lambda_A^\alpha \lambda_B^{1-\alpha} )^{\frac{1}{2\alpha-1}} ) 
\lambda_{A,0}
=c_{A}.
\end{align}
The second inequality holds because $q_n\in (0,1]$ for all $n\in \mathbb{N}$. 

For all $n\in \mathbb{N}$
\begin{align}
\lambda_{B,n}
\stackrel{\eqref{eq:lam-delta-b}}{\geq} c_{B,n}
&\geq \lambda_B^{\frac{1}{\alpha}}c_{A,n}^{\frac{1-\alpha}{\alpha}}
\stackrel{\eqref{eq:lam-an-a0}}{\geq} \lambda_B^{\frac{1}{\alpha}}c_{A}^{\frac{1-\alpha}{\alpha}}
=c_{B}.
\end{align}
The second inequality holds because $q_n\in (0,1]$ for all $n\in \mathbb{N}$. 
\end{proof}

The following lemma is a slightly modified variant of~\cite[Lemma~6.2]{beck2013convergence}. 

\begin{lem}[Sublinear convergence criterion]\label{lem:an}
Let $\gamma\in (0,\infty)$ and let $(A_n)_{n\in \mathbb{N}_{>0}}$ be a sequence of non-negative real numbers such that 
$\gamma A_{n+1}^2\leq A_n-A_{n+1}$ for all $n\in \mathbb{N}_{>0}$. 
Let $c\in [\frac{3}{2},\infty)$ be such that $A_n\leq \frac{c}{\gamma n}$ for all $n\in \{1,2\}$. 
Then, for all $n\in \mathbb{N}_{>0}$
\begin{align}\label{eq:an-induction}
A_{n}\leq \frac{c}{\gamma n}.
\end{align}
\end{lem}
\begin{proof}
We will prove the claim by induction over $n$. 

Base case: By assumption,~\eqref{eq:an-induction} is true for $n\in \{1,2\}$.

Induction step: Suppose~\eqref{eq:an-induction} holds for some $n\in \mathbb{N}_{\geq 2}$. Then,
\begin{align}
\gamma A_{n+1}^2+A_{n+1}
&\leq A_n\leq \frac{c}{\gamma n},
\label{eq:conv1}
\end{align}
where the last inequality follows from the induction hypothesis. 
Therefore, 
\begin{align}
A_{n+1}&\leq \frac{-1+\sqrt{1+4\frac{c}{n}}}{2\gamma}
\leq \frac{c}{\gamma (n+1)}.
\label{eq:conv2}
\end{align}
The first inequality in~\eqref{eq:conv2} follows from~\eqref{eq:conv1} and the fact that $c,\gamma\in (0,\infty)$.
The second inequality in~\eqref{eq:conv2} holds because $n\geq 2$ and $c\geq \frac{3}{2}$.
\end{proof}
\begin{rem}[Existence of constant $c$]\label{rem:def-c}
Lemma~\ref{lem:an} presupposes the existence of a suitable constant $c$. 
Such a constant generally exists because one may define 
$c\coloneqq \max(\frac{3}{2},\gamma A_1,2\gamma A_2)$.
\end{rem}

\subsection{Proof of Theorem~\ref{thm:sublinear}}\label{app:proof-thm}
\emph{Notation.} 
Before presenting the proof, we first clarify our notation for Fr\'echet derivatives. 
Consider $\mathcal{B}_A\coloneqq \{X_A\in \mathcal{L}(A):X_A^\dagger =X_A\}$ with the Schatten $\infty$-norm as a Banach space over $\mathbb{R}$. 
Similarly, consider $\mathcal{B}_B\coloneqq \{Y_B\in \mathcal{L}(B):Y_B^\dagger =Y_B\}$ with the Schatten $\infty$-norm as a Banach space over $\mathbb{R}$. 
If $U\subseteq \mathcal{B}_A$ is an open set and $f:U\rightarrow\mathcal{B}_B$ is a Fr\'echet differentiable function, then the Fr\'echet derivative of $f$ at $X_A\in U$ is denoted by 
$Df(X_A)\in \mathcal{L}(\mathcal{B}_A,\mathcal{B}_B)$. 


\begin{proof}
Without loss of generality, suppose $\sigma_A^{(0)}\in \mathcal{S}_{\sim \rho_A}(A)$, see Remark~\ref{rem:restriction}.

In addition to the definitions in Theorem~\ref{thm:sublinear}, 
we define $\tau_B^{(n)},\sigma_A^{(n+1)}$ for all $n\in \mathbb{N}$ as in Definition~\ref{def:am-quantum}, 
and we define 
$(\lambda_{B,n})_{n\in \mathbb{N}}$ and $c_B$ as in Lemma~\ref{lem:spectrum-leq1}. 
Moreover, we define 
$(x_{n})_{n\in \frac{1}{2}\mathbb{N}}$ and $(q_{n})_{n\in \frac{1}{2}\mathbb{N}}$ as in~\eqref{eq:def-12}. 

We will first prove~\eqref{eq:thm-n1}. 
As explained in the proof of Lemma~\ref{lem:spectrum-leq1}, the sequence $(x_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically decreasing and $x_n\in [0,\infty)$ for all $n\in \frac{1}{2}\mathbb{N}$, and 
$(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically increasing and $q_n\in (0,1]$ for all $n\in \frac{1}{2}\mathbb{N}$. 

For all $n\in \mathbb{N}$
\begin{align}
x_{n+1/2}-x_{n+1}
&=D_\alpha (\rho_{AB}\| \sigma_A^{(n+1)}\otimes \tau_B^{(n)})
-D_\alpha (\rho_{AB}\| \sigma_A^{(n+1)}\otimes \tau_B^{(n+1)})
=D_\alpha (\tau_B^{(n+1)}\| \tau_B^{(n)}).
\label{eq:xn-dn}
\end{align}
The last equality follows from the quantum Sibson identity~\eqref{eq:sibson}. 
Since $q_n=\exp((\alpha-1)x_n)$ for all $n\in \frac{1}{2}\mathbb{N}$, it follows from~\eqref{eq:xn-dn} that for all $n\in \mathbb{N}$
\begin{align}
\frac{q_{n+1/2}}{q_{n+1}}
&=Q_\alpha(\tau_B^{(n+1)}\| \tau_B^{(n)}).
\label{eq:q-frac-tau}
\end{align}

Without loss of generality, suppose $\rho_A>0$ and $\rho_B>0$. 
(If this does not hold, the same proof works if one restricts the Hilbert spaces $A$ and $B$ to the support of $\rho_A$ and the support of $\rho_B$, respectively.) 
Let us define the function
\begin{align}\label{eq:def-f}
f:\mathcal{S}_{>0}(A)\times \mathcal{S}_{>0}(B)\rightarrow\mathbb{R}, 
(\sigma_A,\tau_B)\mapsto -Q_\alpha(\rho_{AB}\| \sigma_A\otimes \tau_B)
=-\tr[\rho_{AB}^\alpha (\sigma_A\otimes \tau_B)^{1-\alpha}].
\end{align}
We will now examine the Fr\'echet derivative of $f$. 
Let $g:\mathcal{S}_{>0}(B)\rightarrow\mathcal{L}(B),\tau_B\mapsto \tau_B^{1-\alpha}$. 
The Fr\'echet derivative of $g$ at $\tau_B\in \mathcal{S}_{>0}(B)$ is 
$Dg(\tau_B)(Y_B)=g^{[1]}(\tau_B)\odot Y_B$ for all self-adjoint $Y_B\in \mathcal{L}(B)$, 
where $\odot$ denotes the Hadamard product taken in an eigenbasis of $\tau_B$, 
and $g^{[1]}$ denotes the first-order divided difference of $g$~\cite{bhatia2007positive}. 
Therefore, the partial Fr\'echet derivative with respect to the second argument of $f$ at 
$(\sigma_A,\tau_B)\in \mathcal{S}_{>0}(A)\times \mathcal{S}_{>0}(B)$ is
\begin{align}
D_2f (\sigma_A,\tau_B)(Y_B)
&=-\tr[ \tr_A[\rho_{AB}^\alpha \sigma_A^{1-\alpha}]  Dg(\tau_B)(Y_B) ]
\label{eq:nabla1f}
\end{align}
for all self-adjoint $Y_B\in \mathcal{L}(B)$. 
Similarly, let $\tilde{g}:\mathcal{S}_{>0}(A)\rightarrow\mathcal{L}(A),\sigma_A\mapsto \sigma_A^{1-\alpha}$. 
The Fr\'echet derivative of $\tilde{g}$ at $\sigma_A\in \mathcal{S}_{>0}(A)$ is 
$D\tilde{g}(\sigma_A)(X_A)=\tilde{g}^{[1]}(\sigma_A)\tilde{\odot} X_A$ for all self-adjoint $X_A\in \mathcal{L}(A)$, 
where $\tilde{\odot}$ denotes the Hadamard product taken in an eigenbasis of $\sigma_A$, 
and $\tilde{g}^{[1]}$ denotes the first-order divided difference of $\tilde{g}$~\cite{bhatia2007positive}. 
Therefore, the partial Fr\'echet derivative with respect to the first argument of $f$ at 
$(\sigma_A,\tau_B)\in\mathcal{S}_{>0}(A)\times \mathcal{S}_{>0}(B)$ is
\begin{align}\label{eq:D1f}
D_1f (\sigma_A,\tau_B)(X_A)
&=-\tr[ \tr_B[\rho_{AB}^\alpha \tau_B^{1-\alpha}] D\tilde{g}(\sigma_A)(X_A) ]
\end{align}
for all self-adjoint $X_A\in \mathcal{L}(A)$.
The partial Fr\'echet derivatives are continuous, i.e., 
$(\sigma_A,\tau_B)\mapsto D_if(\sigma_A,\tau_B)$ is continuous on $\mathcal{S}_{>0}(A)\times \mathcal{S}_{>0}(B)$ for any $i\in \{1,2\}$. 
Therefore, $f$ is Fr\'echet differentiable and the Fr\'echet derivative of $f$ is determined by its partial derivatives as
\begin{equation}\label{eq:frechet-partial}
Df(\sigma_A,\tau_B)(X_A,Y_B)
=D_1f(\sigma_A,\tau_B)(X_A)+D_2f(\sigma_A,\tau_B)(Y_B)
\end{equation}
for all self-adjoint $X_A\in \mathcal{L}(A),Y_B\in \mathcal{L}(B)$.

We have
\begin{align}
\argmin_{(\sigma_A,\tau_B)\in \mathcal{S}_{>0}(A)\times \mathcal{S}_{>0}(B)} 
f(\sigma_A,\tau_B)
&=\argmax_{(\sigma_A,\tau_B)\in \mathcal{S}_{>0}(A)\times \mathcal{S}_{>0}(B)} 
Q_\alpha(\rho_{AB}\| \sigma_A\otimes \tau_B)
\\
&=\argmin_{(\sigma_A,\tau_B)\in \mathcal{S}(A)\times \mathcal{S}(B)} 
D_\alpha(\rho_{AB}\| \sigma_A\otimes \tau_B)
\label{eq:argmin-f}
\end{align}
where~\eqref{eq:argmin-f} holds due to~\eqref{eq:unique}. 
Let $(\hat{\sigma}_A,\hat{\tau}_B)$ be the unique element in this set, see~\eqref{eq:unique}. 
Let 
\begin{align}
\hat{q}&\coloneqq Q_\alpha(\rho_{AB}\| \hat{\sigma}_A\otimes\hat{\tau}_B)
= -f(\hat{\sigma}_A,\hat{\tau}_B)
=\exp((\alpha-1)I_\alpha^{\downarrow\downarrow}(A:B)_\rho).
\end{align}

For all $n\in \mathbb{N}$
\begin{align}
0&\leq \hat{q}-q_{n+1}
\leq \hat{q}-q_{n+1/2}
\label{eq:am0}\\
&=f(\sigma_A^{(n+1)},\tau_B^{(n)})-f(\hat{\sigma}_A,\hat{\tau}_B)
\label{eq:am1}\\
&\leq Df(\sigma_A^{(n+1)},\tau_B^{(n)}) (\sigma_A^{(n+1)}-\hat{\sigma}_A,\tau_B^{(n)}-\hat{\tau}_B)
\label{eq:am12}\\
&= D_1 f(\sigma_A^{(n+1)},\tau_B^{(n)}) (\sigma_A^{(n+1)}-\hat{\sigma}_A) 
+ D_2 f(\sigma_A^{(n+1)},\tau_B^{(n)}) (\tau_B^{(n)}-\hat{\tau}_B)
\label{eq:am2}\\
&=D_2 f(\sigma_A^{(n+1)},\tau_B^{(n)}) (\tau_B^{(n)}-\hat{\tau}_B)
\label{eq:am3}\\
&= D_2 f(\sigma_A^{(n+1)},\tau_B^{(n)})(\tau_B^{(n)}-\hat{\tau}_B)
- D_2 f (\sigma_A^{(n)},\tau_B^{(n)})(\tau_B^{(n)}-\hat{\tau}_B)
\label{eq:am5}
\\
&=\tr[(\tr_A[\rho_{AB}^\alpha \sigma_A^{(n)1-\alpha}]
-\tr_A[\rho_{AB}^\alpha \sigma_A^{(n+1)1-\alpha}])
Dg(\tau_B^{(n)})(\tau_B^{(n)}-\hat{\tau}_B)]
\label{eq:am6}
\\
&=\tr[(q_{n} \tau_B^{(n)\alpha}- q_{n+1} \tau_B^{(n+1)\alpha} ) 
Dg(\tau_B^{(n)}) (\tau_B^{(n)}-\hat{\tau}_B) ]
\label{eq:am7}\\
&\leq \lVert q_{n} \tau_B^{(n)\alpha}- q_{n+1} \tau_B^{(n+1)\alpha} \rVert_2 \cdot 
\lVert Dg(\tau_B^{(n)}) (\tau_B^{(n)}-\hat{\tau}_B)
\rVert_2.
\label{eq:am8}
\end{align}
\eqref{eq:am0} holds because $(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically increasing. 
\eqref{eq:am12} follows from the joint convexity of $f$~\cite{burri2024properties}. 
\eqref{eq:am2} follows from~\eqref{eq:frechet-partial}.
\eqref{eq:am3} holds because according to~\eqref{eq:tau-optimal}, 
$\sigma_A^{(n+1)}$ is the unique global minimizer of $f(\cdot,\tau_B^{(n)})$.
\eqref{eq:am5} holds because according to~\eqref{eq:tau-optimal}, 
$\tau_B^{(n)}$ is the unique global minimizer of $f(\sigma_A^{(n)},\cdot )$. 
\eqref{eq:am6} follows from~\eqref{eq:nabla1f}. 
\eqref{eq:am7} follows from~\eqref{eq:q-tau-alpha}. 
\eqref{eq:am8} follows from the Cauchy-Schwarz inequality for the Hilbert-Schmidt inner product.

The first factor in~\eqref{eq:am8} can be bounded from above as follows.
\begin{align}
\big\lVert q_{n} \tau_B^{(n)\alpha}- q_{n+1} \tau_B^{(n+1)\alpha} \big\rVert_2
&=\big\lVert q_{n}(\tau_B^{(n)\alpha}-\tau_B^{(n+1)\alpha})-(q_{n+1}-q_{n})\tau_B^{(n+1)\alpha} \big\rVert_2
\\
&\leq q_{n}\big\lVert \tau_B^{(n)\alpha}- \tau_B^{(n+1)\alpha} \big\rVert_2
+(q_{n+1}-q_{n})\lVert \tau_B^{(n+1)\alpha}\rVert_2
\label{eq:first-1}\\
&\leq q_{n}\big\lVert \tau_B^{(n)\alpha}- \tau_B^{(n+1)\alpha} \big\rVert_{1/\alpha}
+(q_{n+1}-q_{n})\lVert \tau_B^{(n+1)\alpha}\rVert_{1/\alpha}
\label{eq:first-2}\\
&\leq q_{n}\sqrt{\frac{4\alpha}{1-\alpha}\left(1-Q_\alpha (\tau_B^{(n+1)}\| \tau_B^{(n)}) \right) }
+q_{n+1}-q_{n}
\label{eq:first-3}\\
&=q_{n}\sqrt{\frac{4\alpha}{1-\alpha}\left(1-\frac{q_{n+1/2}}{q_{n+1}} \right) }
+q_{n+1}-q_{n}
\label{eq:first-4}\\
&\leq q_{n+1}\left(\sqrt{\frac{4\alpha}{1-\alpha}\left(1-\frac{q_n}{q_{n+1}}\right)} +\left(1-\frac{q_n}{q_{n+1}}\right) \right)
\label{eq:first-5}\\
&\leq q_{n+1}\left(\sqrt{\frac{4\alpha}{1-\alpha}}+1\right) \sqrt{1-\frac{q_n}{q_{n+1}}} 
\label{eq:first-6}\\
&= \left(\sqrt{\frac{4\alpha}{1-\alpha}}+1\right) \sqrt{q_{n+1}(q_{n+1}-q_n)} 
\label{eq:first-7}
\end{align}
\eqref{eq:first-1} follows from the subadditivity of norms. 
\eqref{eq:first-2} holds due to the monotonicity of the Schatten norms. 
\eqref{eq:first-3} follows from the R\'enyi Pinsker inequality~\eqref{eq:pinsker}.
\eqref{eq:first-4} follows from~\eqref{eq:q-frac-tau}.
\eqref{eq:first-5} holds because $(q_n)_{n\in \frac{1}{2}\mathbb{N}}$ is monotonically increasing. 
\eqref{eq:first-6} holds because $t\leq \sqrt{t}$ for all $t\in [0,1]$.

The second factor in~\eqref{eq:am8} can be bounded from above as follows.
\begin{align}
\lVert Dg(\tau_B^{(n)}) (\tau_B^{(n)}-\hat{\tau}_B) \rVert_2
&\leq \lVert Dg(\tau_B^{(n)}) (\tau_B^{(n)}) \rVert_{2}+
\lVert Dg(\tau_B^{(n)}) (\hat{\tau}_B) \rVert_{2}
\label{eq:dtau0}\\
&\leq 2\sup_{Y_B\in \mathcal{S}(B)} 
\lVert Dg(\tau_B^{(n)}) (Y_B) \rVert_{2}
=2\sup_{\substack{Y_B\in \mathcal{L}(B): \\ Y_B\geq 0, \lVert Y_B\rVert_1 =1}} 
\lVert Dg(\tau_B^{(n)}) (Y_B) \rVert_{2}
\label{eq:dtau11}\\
&\leq 2\sup_{\substack{Y_B\in \mathcal{L}(B):\\ Y_B\geq 0, \lVert Y_B\rVert_2\leq 1 }}
\lVert Dg(\tau_B^{(n)}) (Y_B) \rVert_{2}
\label{eq:dtau2}\\
&\leq 2\sup_{\substack{Y_B\in \mathcal{L}(B):\\ Y_B^\dagger =Y_B, \lVert Y_B\rVert_2\leq 1 }}
\lVert Dg(\tau_B^{(n)}) (Y_B) \rVert_{2}
\label{eq:dtau21}\\
&\leq 2 \lVert (1-\alpha)\tau_B^{(n)-\alpha} \rVert_{\infty}
\label{eq:dtau4}\\
&=\frac{2}{\lambda_{B,n}^{\alpha}} (1-\alpha)
\label{eq:dtau5}
\end{align}
\eqref{eq:dtau0} follows from the subadditivity of norms. 
\eqref{eq:dtau2} holds due to the monotonicity of the Schatten norms. 
\eqref{eq:dtau4} holds because the Schatten 2-norm is unitarily invariant and $g(\tau_B)=\tau_B^{1-\alpha}$ is operator monotone \cite{bhatia1996matrix,bhatia2007positive}.
\eqref{eq:dtau5} is trivially true by the definition of $\lambda_{B,n}$ in~\eqref{eq:lambda-bn}.

Substituting these bounds for the first and the second factor into~\eqref{eq:am8} implies that for all $n\in \mathbb{N}$
\begin{align}
0\leq \hat{q}-q_{n+1}
&\leq \frac{2}{\lambda_{B,n}^{\alpha}} \sqrt{(1-\alpha)q_{n+1}\left(q_{n+1}-q_n\right)} 
\left(\sqrt{4\alpha}+\sqrt{1-\alpha}\right)
\\
&\leq \frac{2\sqrt{5}}{\lambda_{B,n}^{\alpha}} \sqrt{(1-\alpha)q_{n+1}\left(q_{n+1}-q_n\right)}.
\label{eq:alpha-term}
\end{align}
\eqref{eq:alpha-term} holds because 
$\sqrt{4t}+\sqrt{1-t}\leq \sqrt{5}$ for all $t\in [\frac{1}{2},1]$. 
The division of~\eqref{eq:alpha-term} by $q_{n+1}$ implies that for all $n\in \mathbb{N}$
\begin{align}\label{eq:q-qn1}
0\leq \frac{\hat{q}}{q_{n+1}}-1
\leq \frac{2\sqrt{5}}{\lambda_{B,n}^{\alpha}} \sqrt{(1-\alpha)\left(1-\frac{q_n}{q_{n+1}}\right)}.
\end{align} 

For all $n\in \mathbb{N}$
\begin{align}\label{eq:xn-xn1}
x_n-x_{n+1}
=-\frac{1}{1-\alpha}\log \left(1+\frac{q_n}{q_{n+1}}-1 \right)
\geq -\frac{1}{1-\alpha}\left(\frac{q_n}{q_{n+1}}-1 \right)
=\frac{1}{1-\alpha}\left(1-\frac{q_n}{q_{n+1}} \right).
\end{align}
For the inequality in~\eqref{eq:xn-xn1}, we have used that $\log(1+t)\leq t$ for all $t\in (-1,0]$ and that $\frac{q_n}{q_{n+1}}\in (0,1]$ since $(q_n)_{n\in \mathbb{N}}$ is monotonically increasing. 
For all $n\in \mathbb{N}$
\begin{align}
0\leq x_{n+1}-I_\alpha^{\downarrow\downarrow}(A:B)_\rho
&=\frac{1}{1-\alpha}\log\left(1+\frac{\hat{q}}{q_{n+1}}-1\right)
\\
&\leq \frac{1}{1-\alpha}\left(\frac{\hat{q}}{q_{n+1}}-1\right)
\label{eq:xn-x-1}\\
&\leq \frac{2\sqrt{5}}{\lambda_{B,n}^{\alpha}} \sqrt{\frac{1}{1-\alpha}\left(1-\frac{q_n}{q_{n+1}}\right)}
\label{eq:xn-x-12}
\\
&\leq \frac{2\sqrt{5}}{\lambda_{B,n}^{\alpha}} \sqrt{x_n-x_{n+1}}
\label{eq:xn-x-2}
\\
&\leq \frac{2\sqrt{5}}{c_{B}^{\alpha}} \sqrt{x_n-x_{n+1}} 
=c_0\sqrt{x_n-x_{n+1}}.
\label{eq:xn-x-3}
\end{align}
\eqref{eq:xn-x-1} holds because $\log(1+t)\leq t$ for all $t\in [0,\infty)$. 
\eqref{eq:xn-x-12} follows from~\eqref{eq:q-qn1}.
\eqref{eq:xn-x-2} follows from~\eqref{eq:xn-xn1}. 
The inequality in~\eqref{eq:xn-x-3} follows from Lemma~\ref{lem:spectrum-leq1}. 
The equality in~\eqref{eq:xn-x-3} follows from~\eqref{eq:def-sublinear-c0} and~\eqref{eq:def-cb}.
This proves~\eqref{eq:thm-n1}.

We will now prove~\eqref{eq:thm-n2}. 
Let $A_n\coloneqq x_n-I_\alpha^{\downarrow\downarrow}(A:B)_\rho$ for all $n\in \mathbb{N}$. 
Let $\gamma\coloneqq c_0^{-2}$. 
By~\eqref{eq:thm-n1}, 
$\gamma A_{n+1}^2\leq A_n-A_{n+1}$ for all $n\in \mathbb{N}$. 
Let $c\coloneqq \max(\frac{3}{2},2\gamma A_0)$. 
Since the sequence $(A_n)_{n\in \mathbb{N}}$ is monotonically decreasing and non-negative, 
\begin{align}\label{eq:proof-c}
c=\max\left(\frac{3}{2},2\gamma A_0,2\gamma A_1,2\gamma A_2\right)
\geq \max\left(\frac{3}{2},\gamma A_1,2\gamma A_2\right).
\end{align} 

We conclude that for all $n\in \mathbb{N}_{>0}$
\begin{align}
\lvert x_{n}-I_\alpha^{\downarrow\downarrow}(A:B)_\rho \rvert
=A_n
\leq \frac{c}{\gamma n}
&=\max\left(\frac{3}{2} c_0^{2},2(x_0-I_\alpha^{\downarrow\downarrow}(A:B)_\rho)\right) \frac{1}{n}
\label{eq:proof-xn-an1}
\\
&\leq \max\left(\frac{3}{2} c_0^{2},2x_0\right) \frac{1}{n}.
\label{eq:proof-xn-an2}
\end{align}
The inequality in~\eqref{eq:proof-xn-an1} follows from Lemma~\ref{lem:an} and~\eqref{eq:proof-c}. 
\eqref{eq:proof-xn-an2} follows from the non-negativity of the doubly minimized PRMI~\cite{burri2024properties}.
\end{proof}












