\end{figure}

\end{ex1}

The following conclusion can be drawn from Theorem \ref{th1} on the $iid$ case.
\begin{c1}\label{cor}
Let us consider \( X_i \sim \bar{F}_i(x) = \bar{F}(x) \) and \( Y_i \sim \bar{G}_i(x) = \bar{G}(x) \) for \( i = 1, 2, \ldots, n \). It can be easily concluded that for all $x\geq0,$ if $\frac{F_{1:n}(x)}{G_{1:n}(x)} = \left( \frac{F(x)}{G(x)} \right)^n$ is increasing in $n\in\mathcal{N}^+$, then $X_{1:n}\leq_{rh} Y_{1:n}$ implies $X_{1:N}\leq_{rh} Y_{1:N}.$ Hence, $rh$ ordering between minimum order statistics is preserved.
\end{c1}

\begin{r1}\label{rem}
 For $i=1,2,\ldots,n$, if $X_i\sim  \bar F_i(x)=\bar F(x)$ and  $Y_i\sim  \bar G_i(x)=\bar G(x)$ are two sets of $n$ number of $iid$ random variables, then the condition in Theorem $3.1$ of Kundu \emph{et al.}~\cite{ku} that $\frac{\bar{F}_{1:n}(x)}{\bar{G}_{1:n}(x)}$ is increasing in $n$ contradicts the fact that \( X_{1:n} \leq_{hr} Y_{1:n} \) for all \( n \). In fact, since for all n, \( X_{1:n} \leq_{hr} Y_{1:n} \) implies $\bar{F}(x)\leq\bar{G}(x)$ for all $x\geq 0$, it follows that $\frac{\bar{F}_{1:n}(x)}{\bar{G}_{1:n}(x)}$ must be decreasing in $n.$ Therefore, by Case II of Counterexample~\ref{le1} in Kundu \emph{et al.}~\cite{ku}, it can be concluded that, no definitive conclusion can be drawn regarding the preservation of $hr$ ordering between $X_{1:N}$ and $Y_{1:N}.$\\
\end{r1}

Using similar reasoning as in Corollary \ref{cor}, it can be shown that the following theorems are applicable to their respective $iid$ cases. However, based on the arguments presented in Remark \ref{rem}, Theorems \ref{th2}~-~\ref{th4} of Kundu \emph{et al.}~\cite{ku}, which pertain to the non-identical cases, do not apply to the identical cases.

\begin{t1}\label{th2}
	Suppose $X_{1:n}\sim  F_{1:n}(x)$ and  $Y_{1:n}\sim G_{1:n}(x).$ Also let the support of a positive integer valued random variable $N$ having pmf $p(n)$ be $\mathcal{N}^+$. Now, for all $ x\geq l$, if $\frac{{F}_{1:n}(x)}{{G}_{1:n}(x)}$ is decreasing in $n\in\mathcal{N}^+$, then $X_{1:n}\geq_{rh} Y_{1:n}$ implies $X_{1:N}\geq_{rh} Y_{1:N}.$
\end{t1}	
{\bf Proof}: The theorem can be proved using Proposition \ref{le2}, Theorem \ref{theo11} and following the proof of Theorem \ref{th1}.\\

 \begin{t1}\label{th3}
 	Suppose $X_{n:n}\sim \bar F_{n:n}(x)$ and  $Y_{n:n}\sim \bar G_{n:n}(x).$  Also let the support of a positive integer valued random variable $N$ having pmf $p(n)$ be $\mathcal{N}^+$. Now, for all $x\leq u$, if $r_{Y_{n:n}}(x)$, the hazard rate function of $Y_{n:n}$ is decreasing in $n\in\mathcal{N}^+$ and $\frac{\bar F_{n:n}(x)}{\bar G_{n:n}(x)}$ is decreasing in $n\in\mathcal{N}^+$, then $X_{n:n}\leq_{hr} Y_{n:n}$ implies $X_{N:N}\leq_{hr} Y_{N:N}.$
 \end{t1}	
 {\bf Proof}: If $s_{n:n}(x)$ is decreasing in $n$, then for any two positive integers $n_1\leq n_2$ and for all $x\leq u$ it can be written that $r_{Y_{n_1:n_1}}(x)\geq r_{Y_{n_2:n_2}}(x)$, which equivalently concluded that $\frac{\bar G_{n_1:n_1}(x)}{\bar G_{n_2:n_2}(x)}$ is decreasing in $x\leq u$. Thus, the theorem can be proved using Proposition~$\ref{le3}$ and following the line of the proof of Theorem \ref{th4}.\\

\begin{t1}\label{th4}
 	Suppose $X_{n:n}\sim \bar F_{n:n}(x)$ and  $Y_{n:n}\sim \bar G_{n:n}(x).$ Also let the support of a nonnegative integer valued random variable $N$ having pmf $p(n)$ be $\mathcal{N}^+$. Now, for all $x\leq u$, if $r_{Y_{n:n}}(x)$, the hazard rate function of $Y_{n:n}$ is decreasing in $n\in\mathcal{N}^+$ and $\frac{\bar F_{n:n}(x)}{\bar G_{n:n}(x)}$ is increasing in $n\in\mathcal{N}^+$, then $X_{n:n}\geq_{hr} Y_{n:n}$ implies $X_{N:N}\geq_{hr} Y_{N:N}.$
 	 \end{t1}
 {\bf Proof}: The theorem can be proved using Proposition~\ref{le4} and following the proof of Theorem \ref{th3}.\\

The example, given below, illustrates Theorem~\ref{th4}.
 	 \begin{ex1}\label{exam2}
 	Let, $X\sim F(x)$ be a random variable having reversed hazard rate function $\bar r(x)$. Also let, for $n\in\mathcal{N}^+$, $X_i\sim F^{\lambda_i}\left(x\right)$ and $Y_i\sim F^{\mu_i}\left(x\right),~i=1,2,...,n$ be two sequences of $inid$ random variables where $\lambda_i\geq\mu_i$. Then, the distribution and hazard rate functions of $X_{n:n}$ and $Y_{n:n}$ are obtained as  
 		\begin{equation}\label{eq4a}
 			F_{n:n}(x)=\prod_{i=1}^n F^{\lambda_i}\left(x\right)= F^{\lambda}\left(x\right),\ G_{n:n}(x)=F^{\mu}\left(x\right),
 		\end{equation}
 		and 
 		\begin{equation}\label{eq5a}
 			r_{n:n}(x)=\frac{\lambda \bar r(x) }{F^{-\lambda}\left(x\right)-1}\ \text{and}\ s_{n:n}(x)=\frac{\mu \bar r(x) }{F^{-\mu}\left(x\right)-1}
 		\end{equation}
 		respectively, where $\lambda=\sum_{i=1}^n\lambda_i$ and $\mu=\sum_{i=1}^n\mu_i$. \\
 		Since, $\lambda_i\geq\mu_i$ and thus $\lambda\geq\mu$, using Lemma \ref{lemma12} it can be written  from (\ref{eq5a}) that $r_{n:n}(x)\leq s_{n:n}(x),$
 		proving that $X_{n:n}\geq_{hr}Y_{n:n}$.\\
 		Now, let us assume that $X$ follows exponential distribution with distribution function $F(x)=1-e^{-x}, x\geq 0.$ Also let, for $i=1,2\ldots, 5$, suppose $X_i\sim F^{\lambda_i}\left(x\right)$ and $Y_i\sim F^{\mu_i}\left(x\right)$ where each $\lambda_i$ and $\mu_i$	are same as of Example~\ref{exam1}. Now, taking the same values of $p(n)$ for the same selections of $X_is$ ($Y_is$) as that of Example \ref{exam1}, it can be seen from Figure~\ref{figure2.1a} that $\frac{\bar F_{n:n}(x)}{\bar G_{n:n(x)}}$ is increasing in $n$ and $x$. Also Figure~\ref{figure2.1b} ensures that $s_{n:n}(x)$ is decreasing in $n$. So all conditions of Theorem~\ref{th4} are satisfied. Figure~\ref{figure2.1c} shows that $\frac{\bar F_{N:N}(x)}{\bar G_{N:N}(x)}$ is increasing in $x$, proving the result of Theorem~\ref{th4}. Here also substitution $x=-\ln y$ is used to capture whole real line.

 \end{ex1}
