\section{Preliminaries}\label{sect2}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we briefly review some relevant theories and notation about free probability theory and free easy quantum groups. 
We refer to \cite{bk1} for more on free probability and to \cite{ref6} for additional information on quantum groups.

For $m\in \mathbb N$, we denote by $[m]$ the set $\{1,2,\dots,m\}$.
We call $\pi$ a \textbf{partition of} ${[m]}$ if $\pi=\{V_i\}_{i\in I}$ is a collection of subsets of $[m]$, such that $\bigcup_{i\in I} V_i=[m]$ and $V_i\cap V_j=\varnothing$ for $i\neq j$. We call $V_i$ $(i\in I)$ the \textbf{blocks} of $\pi$ and we denote by $\# \pi$ the number of blocks in $\pi$.  If there do not exist integers $1\leq i<j<k<l\leq m$ and blocks $U,V\in\pi$ such that $U\neq V$, $i,k\in U$ and $ j,l\in V$, then  $\pi$ is said to be \textbf{non-crossing}.  We denote by $P(m)$ all partitions of $[m]$ and by $\operatorname{NC}(m)$ all non-crossing partitions of $[m]$. For $\pi,\sigma\in P(m)$, we write $\pi\leq \sigma$ if each block of $\pi$ is contained in some block of $\sigma$. Given a sequence of integers  $\bm{i}=(i_1,\ldots,i_m)$,  we denote $\pi|_V=\{U\cap V: U\in \pi \}$ and $\bm{i}|_V=(i_{j_1},\ldots,i_{j_l})$ for $V=( j_1,\ldots,j_l)\subset [m]$. We consider $\bm{i}$ as a function from $[m]$ to $[n]$. Let $R(\bm{i})$ be the range of $\bm{i}$, and let $V_{a}=\bm{i}^{-1}(a)$ for all $a\in [n]$.
We denote by $\ker(\bm{i})$ the partition $\{V_a:a\in R(\bm{i})\}$. %Throughout this paper, we always denote by $\bm{i}$ the index set $(i_1,\ldots,i_m)$ for some $m>0$. 

Let $A$ be a $\ast$-algebra and let $\varphi$ be a state on $A$, namely, $\varphi$ is a positive linear functional on $A$ with $\varphi(\bm{1})=1$. Then we call $(A,\varphi)$ a $\bm{\ast}$\textbf{-probability space}. The elements in $A$ are called \textbf{non-commutative random variables}.  We denote by $\kappa_m:A^m \rightarrow \mathbb C$ the \textbf{free cumulant}, which is a multi-linear functional determined by the {moment-cumulant formula} (see, e.g., \cite[Chapter 2]{bk1}):
\begin{equation}
	\label{Emc}
	\varphi(x_{i_1}\cdots x_{i_{m}})=\sum\limits_{\pi\in \operatorname{NC}(m)}\kappa_\pi(x_{i_1},\dots, x_{i_{m}}),
\end{equation}
where $\kappa_\pi : A^m\rightarrow \mathbb C$ is a multi-linear functional defined as
\begin{equation}\label{Emc2}
	\kappa_\pi(x_{i_1}\cdots x_{i_{m}})=\prod_{\substack{V\in\pi\\ V=(j_1,\ldots,j_l)}}\kappa_{l}(x_{i_{j_1}},\ldots,x_{i_{j_l}}).
\end{equation}
We will also use frequently the following fact for Möbius functions (see e.g. \cite[Proposition 10.11]{bk4}).
Let $\mathcal P$ be a finite poset, and let $\mu_{\mathcal P}$ be the Möbius function on $\mathcal P$. For two functions $f,g:\mathcal P\rightarrow\mathbb C$, the relation 
\begin{equation}\label{eqi1}
	f(\pi)=\sum_{\sigma\in \mathcal P,\sigma\leq\pi}g(\sigma),\ \forall \pi\in \mathcal P
\end{equation} is equivalent to
\begin{equation}\label{eqi2}
	g(\pi)=\sum_{\sigma\in \mathcal P,\sigma\leq\pi}f(\sigma)\mu_{\mathcal P}(\sigma,\pi).
\end{equation}

By the equivalence between \eqref{eqi1} and \eqref{eqi2}, we obtain the cumulant-moment formula
\begin{equation}
	\label{Ecm}
	\kappa_m(x_{i_1},\dots, x_{i_{m}})=\sum\limits_{\pi\in \operatorname{NC}(m)}\varphi_\pi(x_{i_1},\dots, x_{i_{m}})\mu_{P(m)}(\pi,1_m),
\end{equation}
where $1_m:=\{\{1,\dots, m\}\}\in P(m)$, $\mu_{P(m)}$ is the Möbius function on $P(m)$ and $\varphi_\pi : A^m\rightarrow \mathbb C$ is a multi-linear functional defined as
\begin{equation*}
	\varphi_\pi(x_{i_1},\dots ,x_{i_{m}})=\prod_{\substack{V\in\pi\\ V=(j_1,\ldots,j_l)}}\varphi(x_{i_{j_1}}\cdots x_{i_{j_l}}).
\end{equation*}
We recall below some basic notions of free easy quantum groups which can be found in \cite[Definiton 1.1, Definiton 3.5]{ref2} and \cite[Section 1]{ref13}.
For $n>0$, let $A_n$ be a unital $C^*$-algebra generated by $n^2$ self-adjoint elements $u_{ij}$ $(1\leq i,j\leq n)$. The pair  $(A_n,u)$ is called  a \textbf{quantum orthogonal group} if for all $1\leq i,j\leq n$,
$$\sum_{k=1}^{n}u_{ik}u_{jk}=\delta_{ij}=\sum_{k=1}^nu_{ki}u_{kj}.$$
We denote $G_n=(A_n,u)$ and $A_n=C(G_n)$.
Let $\Delta: A_n \rightarrow A_n\otimes A_n$ denote the unital $\ast$-algebra homomorphism  defined by 
$$
\Delta(u_{ij})=\sum_{k=1}^n u_{ik}\otimes u_{kj}.
$$
It can be shown that
$(\Delta\otimes \operatorname{id})\circ\Delta= (\operatorname{id}\otimes\Delta )\circ\Delta$. We call $\Delta$ a \textbf{comultiplication} of $G_n$.

Recall that, by Woronowicz's Tannakain duality theorem \cite{ref12}, a quantum orthogonal group $G_n$ can be reconstructed from the intertwiner space $C_{G_n}$, where
$$C_{G_n}(k,l)=\qty{T: (\mathbb C^n)^{\otimes k}\rightarrow (\mathbb C^n)^{\otimes l}: T \text{ is linear and } Tu^{\otimes k}= u^{\otimes l}T },$$
where $u$ is the fundamental representation of $A_n$, namely $u$ is the $n\times n$-matrix with entries $u_{ij}$ ($1\leq i,j\leq n$). 
We denote by $P$ the category of all partitions.  For each $k,l>0$, we draw $k$ points in an upper row and $l$ points in a lower row, and we denote by $P(k,l)$ the set consists of all possible line matchings between these points. Let $\bm{i}\in [n]^k$ and $\bm{j}\in [n]^l$ be two sequences of indices associated with  the upper and lower points, respectively. For $p\in P(k,l)$, we set $\delta_{p}(\bm{i},\bm{j})=1$ if whenever two points are connected by $p$,  the indices with respect to the points are equal. Otherwise, we set $\delta_{p}(\bm{i},\bm{j})=0$.  
Let $e_i$, $1\leq i\leq n$, be the canonical basis of $\mathbb C^n$. We denote by $T_p$ the linear map from $\qty(\mathbb C^n)^{\otimes k}$ to $\qty(\mathbb C^n)^{\otimes l}$ defined by
\begin{equation}\label{EqTP}
	T_p(e_{i_1}\otimes\cdots\otimes e_{i_k})=\sum_{j_1,\ldots,j_l=1}^n\delta_p(\bm{i},\bm{j})e_{j_1}\otimes\cdots\otimes e_{j_l}.
\end{equation}
Let $G_n$ be a
 quantum orthogonal group. We call $G_n$ an \textbf{easy quantum group} if its intertwiner space is of the form 
$$C_{G_n}=\operatorname{span}\qty{T_p: p\in P_{G_n} \text{, where } P_{G_n}\subset P \text{ is a category of partitions}}.$$
And $G_n$ is called \textbf{free} if $P_{G_n}$ is a category consisting of some non-crossing partitions. Such categories and free easy quantum groups have been fully classified in \cite{ref13}. These quantum groups are commonly denoted by $O_n^+$, $H_n^+$, $B_n^+$, $S_n^+$, $S_n^{\prime+}$, $ B_n^{\prime+}$ and $B_n^{\#}$.  %We refer the reader to \cite{ref13} for details.
 In the remainder of the paper,  the quantum group $G_n$ will always refer to a free easy quantum group and we denote by $\mathcal C$ the category of non-crossing partitions associated with $G_n$. Furthermore, for $m>0$, we set $\mathcal C(m)=\mathcal C(m,0)$.

Let $(A,\varphi)$ be a $\ast$-probability space generated by $n$ self-adjoint elements $(x_1, \ldots, x_n)$.  
We denote by $\alpha_n: A\rightarrow  A\otimes  C(G_n)$ the unique unital homomorphism  defined as
\begin{equation*}\label{eqac}
	\alpha_n(x_i)=\sum_{j=1}^n x_j\otimes u_{ji},
\end{equation*}
for $1\leq i\leq n$.
%$x_i\in A$  and $u_{ji}\in C(G_n)$ $(1\leq i,j\leq n)$.
Then $\alpha_n$ is a {coaction} of $G_n$. And we say that \textbf{the distribution
	${\varphi}$ is invariant under ${G_n}$}, or that the sequence
$(x_1, . . ., x_n)$ is \textbf{$G_n$-invariant}, if $\varphi$ is invariant under the coaction $\alpha_n$, namely, for each $x\in A$,
$$(\varphi\otimes \text{id})\circ \alpha_n(x)=\varphi(x) \bm{1}_{C(G_n)}.$$
We refer the reader to \cite{ref5} for more information.

The Haar state $h_n$ with respect to $G_n$ is the unique state on $C(G_n)$ such that for any $a\in C(G_n)$, $$(h_n\otimes \operatorname{id})\circ \Delta(a)=(\operatorname{id}\otimes h_n)\circ\Delta (a)=h_n(a)\bm{1}_{C(G_n)}.$$ 
The law of the Haar state can be computed using the Weingarten formula. 
For $m\in \mathbb N$ , let $G_{m,n}^{\mathcal C}$ be the Gram matrix with entries indexed by the non-crossing partitions in $\mathcal C(m)$ defined by 
\begin{equation*}\label{eq12}
	G_{m,n}^{\mathcal C}(\pi,\sigma)=n^{\#({\pi\vee\sigma})} ,
\end{equation*}
where $\pi\vee\sigma$ is the smallest partition such that $\pi\leq \pi\vee\sigma$ and $\sigma\leq \pi\vee\sigma$ with respect to the
usual partial order in the lattice of partitions  $P(m)$. The Weingarten matrix $\operatorname{Wg}^{\mathcal C}_{m,n}$, if it exists, is defined as its inverse. The Haar state $h_n$ on $G_n$ is determined by the Weingarten formula:
\begin{equation}
	\label{Ewg}
	h_n(u_{i_1j_1}\cdots u_{i_mj_m})=
	\sum\limits_{\pi,\sigma\in{\mathcal C}(m)} \delta_{\pi}(\bm{i})\delta_{\sigma}(\bm{j})\text{Wg}^{\mathcal C}_{m,n}(\pi,\sigma).
\end{equation}
Banica and Collins proved that for $n\geq 2$, the Gram matrix with respect to $O_n^+$ is invertible. Furthermore, for $n\geq4$, the Gram matrix with respect to any categories of non-crossing partitions is invertible. We refer the reader to \cite{ref14, bk3} for more information.

