\section{Finite de Finetti theorem for easy quantum groups}\label{sect3}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we present our finite de Finetti theorem for free easy quantum groups.
Our argument is motivated by the following observations:  
Let $A$ be a $\ast$-probability space, and let $ B$ be a unital $\ast$-subalgebra of $A$ with a $\varphi$-preserving conditional expectation $E$ onto $B$. The triple $(A,E,B)$ is called an \textbf{operator-valued non-commutative probability space}. We refer to \cite[Chapter 9]{bk1} for details.
The operator-valued free cumulant $\kappa_m^E:A^{m}\rightarrow {B}$ is determined by the operator-valued moment-cumulant formula :
\begin{equation}\label{Eopmc}
	E(b_0x_{i_1}b_1\cdots x_{i_m}b_m)=\sum_{\pi\in \operatorname{NC}(m)}\kappa^E_\pi(b_0x_{i_1}b_1,\cdots,x_{i_m}b_m).
\end{equation}

It is well known that the non-commutative random variables $(x_1,x_2,\dots,x_n)$ is a free semi-circular family with amalgamation over $B$  if and only if for all $m>0 $, $\pi\in\operatorname{NC}(m)$ and $b_i\in B$, $i=0,1,\ldots,m$,
$$\kappa^E_{\pi}[b_0x_{i_1}b_1,\ldots,x_{i_m}b_m]=0$$
except when $\pi\leq\ker{\bm{i}}$ and $\pi\in \operatorname{NC}_2(m)$  (the set of all non-crossing pairings of $[m]$). We denote $\operatorname{NC}_{2,\leq}(\bm{i})=\{\pi\in \operatorname{NC}_{2}(m): \pi\leq \ker(\bm{i})\}$.
Then by the operator-valued moment-cumulant formula (\ref{Eopmc}), we obtain 
\begin{equation}\label{eq10}
	\begin{aligned}
		E\left[x_{i_1}\cdots x_{j_m}\right]&=\sum_{\pi\in\operatorname{NC}_{2,\leq}(\bm{i})}\kappa^E_{\pi}(x_{i_1},\dots,x_{i_m})\\
		&=\sum_{\pi\in\operatorname{NC}_{2,\leq}(\bm{i})}\kappa^E_{\pi}(x_{1},\dots,x_{1}).
	\end{aligned}
\end{equation}
 Applying $\varphi$ to both sides of Eq. (\ref{eq10}), it follows that
\begin{equation*}
	\label{eq6}
	\varphi(x_{i_1}\cdots x_{i_m})=
	\sum\limits_{\pi\in\operatorname{NC}_{2,\leq}(\bm{i})}\varphi\left(\kappa^E_{\pi}(x_{1},\dots,x_{1})\right).
\end{equation*}
%Observe that the moments of $(x_1,\ldots,x_n)$ can be written as a sum of constants which are independent of $\bm{i}$
Then we have the following expression:
\begin{equation}
	\label{eq9}
	\varphi(x_{i_1}\cdots x_{i_m})=
	\sum\limits_{\pi\in\operatorname{NC}_{2,\leq}(\bm{i})}c^{(m)}_\pi,
\end{equation}
where $c^{(m)}_\pi=\varphi(\kappa^E_{\pi}(x_{1},\dots,x_{1}))$. Similar observations hold for operator-valued free independence with respect to other free easy quantum groups studied in \cite{ref5}. For $\bm{i}\in[n]^m$, we denote the set $\mathcal C_\leq(\bm{i}):=\{\pi\in \mathcal C(m): \pi\leq \ker(\bm{i})\}$.
The relations such as (\ref{eq9}) effect a much weaker independence than the freeness, and we will show that these exactly characterize the $G_n$-invariance. We may investigate further descriptions in terms of cumulants, inspired by the approach taken in \cite{ref4}.
More precisely, the following is our finite de Finetti theorem for free easy quantum groups.
\begin{thm}
	\label{th1}
	Given $n\geq 4$, let $(x_1, . . . , x_n)$ be a family of random variables in a $\ast$-probability space $(A, \varphi)$. Let $G_n$ be a free easy quantum group with the associated category of non-crossing partitions $\mathcal C$.
	Then the following are equivalent:
	\begin{enumerate}[\rm(i)]
		\item \label{th1-As1}The sequence $(x_1, . . ., x_n)$ is $G_n$-invariant. 
		\item \label{th1-As2}
		There exists a unital subalgebra $B$ of $A$ and a $\varphi$-preserving conditional expectation $E:A\rightarrow B$  such that, for any $m>0$,
		there is a family $(b_\pi)_{\pi\in \mathcal C(m)}\subset B$ satisfying, for all $\bm{i}\in [n]^m$,
		\begin{equation*}
			\label{eq5}
			E(x_{i_1}\ldots x_{i_m})=
			\sum\limits_{\pi\in\mathcal C_\leq(\bm{i})}b_\pi^{(m)} .
		\end{equation*}
		In particular, $E(x_{i_1}\cdots x_{i_m})$ is zero except
		$\mathcal C_{\leq}(\bm{i})\neq \varnothing$ and that $E(x_{i_1}\ldots x_{i_m})=E(x_{j_1}\cdots x_{j_m})$ as soon as $\ker(\bm{i})=\ker(\bm{j})$.
		\item \label{th1-As3} For any $m> 0$, there are scalars $(c_\pi^{(m)})_{\pi\in \mathcal C(m)}\subset\mathbb C$ such that, for all $\bm{i}\in [n]^m$,
		\begin{equation*}
			\label{eq1}
			\varphi(x_{i_1}\cdots x_{i_m})=
			\sum\limits_{\pi\in\mathcal C_\leq(\bm{i})}c_\pi^{(m)} .
		\end{equation*}
		In particular, the moments $\varphi(x_{i_1}\ldots x_{i_m})$ are zero except
		$\mathcal C_{\leq}(\bm{i})\neq \varnothing$ and 
		$$\varphi(x_{i_1}\cdots x_{i_m})=\varphi(x_{j_1}\cdots x_{j_m})$$ as soon as $\ker(\bm{i})=\ker(\bm{j})$.
		\item \label{th1-As4} For any $m>0$, there are scalars $(C_\pi^{(m)})_{\pi\in \mathcal C(m)}\subset\mathbb C$ such that, for all $\bm{i}\in [n]^m$,
		\begin{equation}\label{eq7}
			\kappa_{m}(x_{i_1},\ldots ,x_{i_m})=
			\sum\limits_{\pi\in\mathcal C_\leq(\bm{i})}C_\pi^{(m)}.
		\end{equation}
		In particular, the cumulants $\kappa_{m}(x_{i_1},\ldots ,x_{i_m})$ are zero except
		$\mathcal C_{\leq}(\bm{i})\neq \varnothing$ and $$\kappa_m(x_{i_1},\ldots ,x_{i_m})=\kappa_m(x_{j_1},\ldots, x_{j_m})$$ as soon as $\ker(\bm{i})=\ker(\bm{j})$.
	\end{enumerate}
\end{thm}
\begin{proof} 
	`(\ref*{th1-As1}) $\Rightarrow$ (\ref*{th1-As2})': 
Let $\mathcal P_{\bm{x}}^{\alpha_n}$ be the fixed point algebra of the coaction $\alpha_n$, namely, $$\mathcal P_{\bm{x}}^{\alpha_n}=\{x\in A:\alpha_n(x)=x\otimes \bm{1}_{C(G_n)}\}.$$  It is easy to check that
\begin{equation}\label{fix-point-alg}
	\mathcal P_{\bm{x}}^{\alpha_n}=\mathbb C\left\langle \sum_{\bm{i}\in [n]^{m}} \delta_{\pi}(\bm{i})x_{i_1}\cdots x_{i_{m}}: m\in\mathbb N, \pi\in\mathcal C(m)\right\rangle.
\end{equation}
Let $E: A\rightarrow\mathcal \mathcal P_{\bm{x}}^{\alpha_n}$ be a linear map defined by 
$E=(\operatorname{id}\otimes h)\circ\alpha_n.$
Then $E$ becomes a projection onto $\mathcal P_{\bm{x}}^{\alpha_n}$. If $(x_1,\ldots,x_n)$ is $G_n$-invariant, then $E$ is the $\varphi$-preserving conditional expectation onto $\mathcal P_{\bm{x}}^{\alpha_n}$. 
{For $\bm{i}=(i_1,\ldots,i_m)\in[n]^m$, applying the Weingarten formula (\ref{Ewg}), we have}
$$ \begin{aligned}
	E\left(x_{i_1}\cdots x_{i_{m}}\right)&=
	(\operatorname{id}\otimes h)\circ\alpha_n\left(x_{i_1}\cdots x_{i_{m}}\right)\\
	&=\sum_{\bm{j}\in[n]^m}x_{j_1}\cdots x_{j_{m}} h(u_{j_1i_1}\cdots u_{j_{m}i_{m}})\\
	&=\sum_{\bm{j}\in[n]^m}x_{j_1}\cdots x_{j_{m}}\sum_{\pi,\sigma\in\mathcal C(m)}\delta_{\pi}(\bm{i})\delta_{\sigma}(\bm{j})\operatorname{Wg}^{\mathcal C}_{m,n}(\pi,\sigma)\\ 
	&= \sum_{\pi\in\mathcal C(m)}\delta_{\pi}(\bm{i})b_{\pi}
\end{aligned}$$
where 
$$b_\pi=\sum_{\sigma\in\mathcal C(m)}\operatorname{Wg}^{\mathcal C}_{m,n}(\pi,\sigma) \sum_{\bm{j}\in[n]^m}\delta_{\sigma}(\bm{j})x_{j_1}\cdots x_{j_{m}},$$
which implies Assertion (\ref*{th1-As2}).

`(\ref*{th1-As2}) $\Rightarrow$ (\ref*{th1-As3})': For $\bm{i}\in[n]^m$, we have
$$\varphi(x_{i_1}\cdots x_{i_m})=\varphi\left(E(x_{i_1}\cdots x_{i_m})\right)
=
\sum\limits_{\pi\in\mathcal C_\leq(\bm{i})}\varphi\left(b_\pi\right).$$

	`(\ref*{th1-As3}) $\Rightarrow$ (\ref*{th1-As1})':
	For all $\pi \in \mathcal C(m)$, using Eq. (\ref{EqTP}), we have  
	$$\sum_{\bm{j}\in[n]^{m}}\delta_{\pi}(\bm{j})u_{j_1i_1}\cdots u_{j_{m}i_{m}}=\delta_{\pi}(\bm{i})\bm{1}_{C(G_n)}.$$
	Thus
	$$\begin{aligned}
		(\varphi\otimes \operatorname{id})\circ\alpha_n(x_{i_1}\cdots x_{i_m})&=\sum_{\bm{j}\in [n]^m}\varphi (x_{j_1}\cdots x_{j_m})u_{j_1i_1}\cdots u_{j_{m}i_{m}}\\
		&=\sum_{\bm{j}\in [n]^m}\sum_{\pi\in\mathcal C(m)} c_\pi^{(m)} \delta_\pi(\bm{j})u_{j_1i_1}\cdots u_{j_{m}i_{m}}\\
		&=\sum_{\pi\in\mathcal C(m)} c_\pi^{(m)} \delta_\pi(\bm{i}) \bm{1}_{C(G_n)}\\
		&=\varphi(x_{i_1}\cdots x_{i_m})\bm{1}_{C(G_n)}.
	\end{aligned}$$

	`(\ref*{th1-As4}) $\Rightarrow$ (\ref*{th1-As3})': Fix $\bm{i}\in[n]^m$. 
	For all $V=( k_1,\ldots,k_l)\subset [n]$, the value of
	  $\kappa_{l}(x_{i_{k_1}},\ldots,x_{i_{k_l}})$ only depends on $\ker(\bm{i}|_V)$. It is straightforward to verify that $\ker(\bm{i}|_V)=\ker(\bm{i})|_V$. 
	Therefore, by the moment-cumulant formula (\ref{Emc}) and Eq. (\ref{eq7}), for $\bm{j}\in [n]^m$, we have 
	$$\begin{aligned}
		\varphi(x_{j_1} \cdots x_{j_m})=\varphi(x_{i_1} \cdots x_{i_m})
		,
	\end{aligned}$$
	whenever $\ker(\bm{j})=\ker(\bm{i})$.
	Given $\pi\in \operatorname{NC}(m)$ and $\tau\in P(m)$, for each $\sigma\in\mathcal C(m)$ with $\sigma\leq \pi$, we have $\sigma|_{V}\in\mathcal C(|V|)$  for all $V\in \pi$, where $|V|$ is the number of elements in $V$. In addition, if $\sigma\leq\tau$, we have $\sigma|_{V}\leq \tau|_{V}$. Conversely, for all $V\in\pi$, if there exist  $\sigma|_V\in \mathcal C(|V|)$ with $\sigma|_V\leq \tau|_V$, then $\sigma=\bigcup_V \sigma|_V\leq \tau$. By the definition of the category of partitions (see e.g. \cite[Definition 1.3]{ref13}), if $\sigma_1\in \mathcal C(m_1)$ and $\sigma_2\in \mathcal C(m_2)$, then $\sigma_1\cup \sigma_2\in \mathcal C(m_1+m_2)$. It follows that $\sigma\in\mathcal C(m)$. Hence 
	$$ 	\prod\limits_{V\in\pi}
	\sum\limits_{\substack{\sigma\in \mathcal C(\abs{V})\\ \sigma\leq\tau|_{V}}}C_{\sigma}^{(m)}=\sum_{\substack{\sigma\leq\tau,\sigma\leq\pi\\ \sigma\in \mathcal C(m)}} \prod_{V\in\pi}C_{\sigma|_V}^{(m)}.$$
	For $\bm{i}\in [n]^m$, we denote $\tau=\ker(\bm{i})$. By Eq. (\ref{Emc}) and Eq. (\ref{Emc2}), we have
	$$\begin{aligned}
		\varphi\qty(x_{i_1}\cdots x_{i_m})
		&=\sum\limits_{\pi\in \operatorname{NC}(m)} \prod_{\substack{V\in\pi\\ V=(j_1,\ldots,j_l)}}\kappa_{l}(x_{i_{j_1}},\ldots,x_{i_{j_l}})\\
		&=\sum\limits_{\pi\in \operatorname{NC}(m)}
		\prod\limits_{V\in\pi}
		\sum\limits_{\substack{\sigma\in \mathcal C(\abs{V})\\ \sigma\leq\tau|_{V}}}C_{\sigma}^{(m)}\\
		&=\sum_{\pi\in\operatorname{NC}(m)}\sum_{\substack{\sigma\leq\tau,\sigma\leq\pi\\ \sigma\in \mathcal C(m)}} \prod_{V\in\pi}C_{\sigma|_V}^{(m)}\\
		&=\sum_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq\tau}}\sum_{\substack{\pi\in\operatorname{NC}(m)\\\pi\geq\sigma}} \prod_{V\in\pi}C_{\sigma|_V}^{(m)}.
	\end{aligned}$$
	For $\sigma\in\mathcal C(m)$, we denote
	$$c_\sigma^{(m)}=\sum_{\substack{\pi\in\operatorname{NC}(m)\\\pi\geq\sigma}} \prod_{V\in\pi}C_{\sigma|_V}^{(m)},$$
	which yields Assertion (ii).

	`(\ref*{th1-As3}) $\Rightarrow$ (\ref*{th1-As4})': Applying the  cumulant-moment formula \eqref{Ecm} to $\kappa_m$,  it follows that
	$$\kappa_m(x_{i_1}, \ldots, x_{i_{m}})=\sum\limits_{\pi\in \operatorname{NC}(m)}\mu_{P(m)}(\pi,1_m)\prod_{\substack{V\in\pi\\ V=(j_1,\ldots,j_l)}}\varphi(x_{i_{j_1}}\cdots x_{i_{j_l}}).$$
	%where $\mu_{P(m)}$ is the Möbius function on $P(m)$.
	As explained previously in `(\ref*{th1-As4}) $\Rightarrow$ (\ref*{th1-As3})', we have 
	$$ 	\prod\limits_{V\in\pi}
	\sum\limits_{\substack{\sigma\in \mathcal C(\abs{V})\\ \sigma\leq\tau|_{V}}}c_{\sigma}^{(m)}=\sum_{\substack{\sigma\leq\tau,\sigma\leq\pi\\ \sigma\in \mathcal C(m)}} \prod_{V\in\pi}c_{\sigma|_V}^{(m)}.$$
	It follows that
	$$\begin{aligned}
		\kappa_m(x_{i_1}, \ldots, x_{i_{m}})&=\sum\limits_{\pi\in \operatorname{NC}(m)}\mu_{P(m)}(\pi,1_m)\prod_{\substack{V\in\pi\\ V=(j_1,\ldots,j_l)}}\varphi(x_{i_{j_1}}\cdots x_{i_{j_l}})\\
		&=\sum_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq\tau}}\sum_{\substack{\pi\in\operatorname{NC}(m)\\\pi\geq\sigma}} \mu_{P(m)}(\pi,1_m) \prod_{V\in\pi}c_{\sigma|_V}^{(m)}.
	\end{aligned}$$
	Then we obtain
	$$C_\sigma^{(m)}=\sum_{\substack{\pi\in\operatorname{NC}(m)\\\pi\geq\sigma}}\mu_{P(m)}(\pi,\bm{1}_m) \prod_{V\in\pi}c_{\sigma|_V}^{(m)},$$
	which yields Assertion (iii).
\end{proof}

\begin{rk}\label{rk1}
	%\begin{enumerate}[\rm(i)]\item
		 (i) {From the arguments `(\ref*{th1-As3}) $\Leftrightarrow$ (\ref*{th1-As4})'}, if the assertions of Theorem \ref{th1} hold, then there are relations between the distinguished scalars $c_\sigma^{(m)}$ and $C_\sigma^{(m)}$ as follows:
		\begin{equation*}
			c_\sigma^{(m)}=\sum_{\substack{\pi\in\operatorname{NC}(m)\\\pi\geq\sigma}} \prod_{V\in\pi}C_{\sigma|_V}^{(m)}\text{ and } C_\sigma^{(m)}=\sum_{\substack{\pi\in\operatorname{NC}(m)\\\pi\geq\sigma}}\mu_{P(m)}(\pi,{1}_m) \prod_{V\in\pi}c_{\sigma|_V}^{(m)}.
		\end{equation*}

		(ii)  Let $(x_1,\ldots,x_n)$ be $G_n$-invariant. we denote $$D_n(m)=\{\pi\in P(m): \exists\bm{i}\in [n]^m \text{ such that } \ker{\bm{i}}=\pi\}.$$ 
		 Note that, by Theorem \ref{th1} (\ref*{th1-As3}), we have $\varphi(x_{i_1}\cdots x_{i_m})=\varphi(x_{j_1}\cdots x_{j_m})$ if $\ker(\bm{i})=\ker(\bm{j})$. So we may well define a map $\widetilde{\varphi}_m: D_n(m)\rightarrow \mathbb C$ given by
		$$\widetilde{\varphi}_m(\pi)=\varphi(x_{j_1}\ldots x_{j_m}),$$
		where  $(j_1,\ldots,j_m)\in [n]^m$ is any arbitrary  sequence such that $\ker(\bm{j})=\pi$. Assume that $m\leq n$, then we claim that the constants $c_{\sigma}^{(m)}$'s are uniquely determined, and for $\bm{i}\in [n]^m$, we have
		\begin{equation}\label{eq2}
			\varphi(x_{i_1}\cdots x_{i_m})=
			\sum\limits_{\pi\in \mathcal C_{\leq}(\bm{i})}\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\varphi_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)},
		\end{equation}
		where $\mu_{\mathcal C(m)}(\sigma,\pi)$ is the Möbius function on $\mathcal C(m)$. In fact,  
		if $m\leq n$, then $D_n(m)=P(m)$. Restricting $\widetilde\varphi_m$ to $\mathcal C(m)$, by Theorem \ref{th1} (\ref*{th1-As3}), we obtain that
		\begin{equation*}
			\label{eq4}
			\widetilde\varphi_m(\pi)=\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}} c_{\sigma}^{(m)},
		\end{equation*} 
		for all $\pi\in \mathcal C(m)$.
	From the equivalence between Eq. (\ref{eqi1}) and Eq. (\ref{eqi2}), we deduce that
		\begin{equation*}
			c_\pi^{(m)}=\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\varphi_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)},
		\end{equation*}
		which yields Eq. (\ref{eq2}). Similarly, let $\widetilde\kappa_m:D_n(m)\rightarrow \mathbb{R}$ be the map defined as 
		$$\widetilde{\kappa}_m(\pi)=\kappa_m(x_{j_1},\ldots, x_{j_m}),$$
		for an arbitrary  sequence $\bm{j}\in [n]^m$ such that $\ker(\bm{j})=\pi$.
		Then for all $m\leq n$ and $\bm{i}\in [n]^m$, we have
		\begin{equation}\label{eq3}
			\kappa_{m}(x_{i_1},\ldots ,x_{i_m})=
			\sum\limits_{\pi\in \mathcal C_{\leq}(\bm{i})}\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\kappa_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)}.
		\end{equation}
		In particular, let $(x_1,\ldots,x_n)$ be $O_n^+$-invariant. The category of non-crossing partitions associated with $O_n^+$ is $\operatorname{NC}_2$, where for any $\pi,\sigma\in \operatorname{NC}_2(m)$, the order relation $\pi\leq \sigma$ holds if and only if $\pi=\sigma$. Consequently,  {for all $m\leq 2n$ and $\bm{i}\in [n]^m$,} we have the inclusion $\operatorname{NC}_2(m)\subset D_n(m)$. By the previous analysis, it follows that,
		\begin{equation}\label{m-On-inv}
			\varphi(x_{i_1}\cdots x_{i_m})=
		\sum\limits_{\pi\in \operatorname{NC}_{2,\leq}(\bm{i})}{\widetilde\varphi_m(\pi)}
		\end{equation}
		and
		\begin{equation}\label{c-On-inv}
		\kappa_{m}(x_{i_1},\ldots ,x_{i_m})=
		\sum\limits_{\pi\in \operatorname{NC}_{2,\leq}(\bm{i})}{\widetilde\kappa_m(\pi)}.
		\end{equation}
	%\end{enumerate}
\end{rk}

In the following, we discuss the asymptotic behaviors of the $G_n$-invariant random variables as $n\to\infty$. Note that a quantitative comparison with the operator-valued free distributions has been established in \cite[Theorem 4.8]{ref5}. Below, based on the techniques introduced in the main theorem, we will give alternative equivalent descriptions of (scalar-valued) asymptotic freeness for $S_n^+$ and $O_n^+$-invariant sequences. It is well known that a sequence  $(x_1^{(n)}, \ldots, x^{(n)}_n)$ is asymptotically free if and only if its mixed cumulants converge to zero as $n \rightarrow \infty$. The following simple corollaries illustrate that it suffices to focus on moments or cumulants associated with non-crossing partitions for some  $S_n^+$ and $O_n^+$-invariant sequences. Recall that the category $\mathcal C$ of partitions associated with $S_n^+$ (respectively, $O_n^+$) is $\operatorname{NC}$ (respectively, $\operatorname{NC}_2$).

\begin{cor}
	Let $n>0$ and let $(x_i^{(n)})_{i\in \mathbb N}$ be a sequence of self-adjoint elements in a $\ast$-probability space $(A_n,\varphi_n)$. For any $n\geq 4$, suppose $(x_1^{(n)},\ldots,x^{(n)}_n)$ is $S_n^+$-invariant. Then the following are equivalent:
	\begin{enumerate}[\rm(i)]
		%\item\label{coro1-as1} $x_1^{(n)}$ and $x_2^{(n)}$ are asymptotically free as $n\rightarrow\infty$
		\item\label{coro1-as2} For any $p\geq 2$, $x_1^{(n)},\ldots,x_p^{(n)}$ are asymptotically free as $n\rightarrow\infty$.
		\item\label{coro1-as3}  For any $m>0$ and $\bm{i}\in \mathbb N^{m}$, if  $\ker(\bm{i})\in\operatorname{NC}(m)$ and $\#\ker(\bm{i})>1$ (namely, the number of blocks in $\ker(\bm{i})$ is greater {than} $1$), then $\kappa_{m}(x_{i_1}^{(n)},\ldots, x_{i_{m}}^{(n)})\rightarrow 0$ as $n\rightarrow\infty$.
	\end{enumerate}
\end{cor}
\begin{proof}
	  `(\ref*{coro1-as2})$\Rightarrow$(\ref*{coro1-as3})':  Fix $m>0$. For $\pi\in P(m)$, we have $\#\pi=1$ if and only if $\pi=1_m$.
	  In other words, Assertion (\ref*{coro1-as2}) holds if and only if $\kappa_{m}(x_{j_1}^{(n)},\ldots ,x_{j_m}^{(n)})\rightarrow0$ whenever $\ker(\bm{j})\neq 1_m$. Let $p\geq m$. Then for each $\bm{i}\in \mathbb N^m$, there exists $\bm{j}\in [p]^m$, such that $\ker(\bm{j})=\ker(\bm{i})$. 
	Let $n$ be large enough. By Theorem \ref{th1} (\ref*{th1-As4}), we obtain $\kappa_{m}(x_{i_1}^{(n)},\ldots ,x_{i_m}^{(n)})=\kappa_{m}(x_{j_1}^{(n)},\ldots ,x_{j_m}^{(n)})$. 
	Therefore, if $\ker(\bm{i})\in \operatorname{NC}(m)$ and $\#\ker(\bm{i})>1$, we have
	$$\lim_{n\rightarrow\infty}\kappa_{m}\qty(x_{i_1}^{(n)},\ldots ,x_{i_m}^{(n)})=\lim_{n\rightarrow\infty}\kappa_{m}\qty(x_{j_1}^{(n)},\ldots ,x_{j_m}^{(n)})=0,$$
	which proves Assertion (\ref*{coro1-as3}).

	 `(\ref*{coro1-as3})$\Rightarrow$(\ref*{coro1-as2})':
	For any $m>0$,  when 
	$n$ is sufficiently large, since the sequence $(x_1^{(n)},\ldots,x^{(n)}_n)$ is $S_n^+$-invariant, it follows from Eq. \eqref{eq3} in Remark \ref{rk1} (ii) that
	\begin{equation}\label{eq13}
		\kappa_{m}^{(n)}\qty(x_{i_1}^{(n)},\ldots ,x_{i_m}^{(n)})=
		\sum\limits_{\pi\in \operatorname{NC}_{\leq}(\bm{i})}\sum\limits_{\substack{\sigma\in \operatorname{NC}(m)\\ \sigma\leq \pi}}{\widetilde\kappa_m^{(n)}(\sigma)\mu_{\operatorname{NC}(m)}(\sigma,\pi)},
	\end{equation}
	where $\widetilde\kappa_m^{(n)} : P(m) \rightarrow \mathbb{C}$ is defined by
	$$\widetilde\kappa_m^{(n)}(\ker(\bm{i}))=\kappa_m\qty(x^{(n)}_{i_1},\dots,x^{(n)}_{i_m}).$$
	Here $\widetilde\kappa_m^{(n)}$ is well-defined since for any $\sigma\in \operatorname{NC}(m)$, there exists $\bm{i}\in \N^m$ such that $\ker(\bm{i})=\sigma$. 
	Then by Assertion (\ref*{coro1-as3}) and Theorem \ref{th1} (\ref*{th1-As4}),
	we conclude that $\widetilde\kappa_m^{(n)}(\sigma)=\kappa_m(x^{(n)}_{i_1},\dots,x^{(n)}_{i_m})\rightarrow0$ for all $\sigma\in\operatorname{NC}(m)$ with $\sigma\neq 1_m$.
 	Note that $\#\sigma\geq\#\pi$ whenever $\sigma\leq \pi$. %It follows that, for $\ker(\bm{i})\neq 1_m$, we have $\#\sigma>1$ if $\sigma\leq \ker(\bm{i})$. 
 	Therefore, from Eq. (\ref{eq13}) and the transitivity of the partial order `$\leq$', it follows that for any $p\geq 2$ and  $\bm{i}\in [p]^m$, 
 	$$\kappa_{m}^{(n)}\qty(x_{i_1}^{(n)},\ldots ,x_{i_m}^{(n)})\rightarrow 0,\text{  as } n\rightarrow \infty,$$  whenever $\ker(\bm{i})\neq 1_m$,
	which implies Assertion (i).
\end{proof}


\begin{cor}\label{coro1}
	Let $n>0$ and let $(x_i^{(n)})_{i\in \mathbb N}$ be a sequence of self-adjoint elements in a $\ast$-probability space $(A_n,\varphi_n)$ with variance $1$. For any $n\geq 2$, suppose $(x_1^{(n)},\ldots,x^{(n)}_n)$ is $O_n^+$-invariant. Then the following are equivalent:
	\begin{enumerate}[\rm(i)]
		\item For any $p\geq 2$, $$x_1^{(n)},\ldots,x_p^{(n)}\xrightarrow{distr.}s_1,\ldots,s_p, \text{ as }n\rightarrow\infty,$$ where $(s_1,\ldots,s_p)$ forms a semi-circular system in $(A,\varphi)$, namely, each $s_i$ ($1\leq i\leq p$) is a standard semicircular random variable and the variables are free with respect to $\varphi$ (see e.g. \cite[Definition 7.11]{bk4}).
		\item  For any $k\geq 2$ and $\bm{i}\in \N^{2k}$ such that $\ker(\bm{i})\in\operatorname{NC}_2(2k)$, $$\kappa_{2k}\left(x_{i_1}^{(n)},\ldots ,x_{i_{2k}}^{(n)}\right)\rightarrow 0, \text{ as } n\rightarrow\infty.$$
		\item For any  $k> 0$ and  $\bm{i}\in \N^{2k}$ such that $\ker(\bm{i})\in\operatorname{NC}_2(2k)$, $$\varphi_{n}\left(x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)}\right)\rightarrow 1, \text{ as } n\rightarrow\infty.$$
		\item For all $k> 0$ and $\pi\in \operatorname{NC}_2(2k)$, 
		$$\varphi_n\qty(\frac{1}{n^k}\sum_{\bm{i}\in [n]^{2k}} \delta_{\pi}(\bm{i})x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)})\rightarrow 1, \text{ as }n\rightarrow \infty.$$
	\end{enumerate}
\end{cor}
\begin{proof} 
	`(i) $\Rightarrow$ (ii)': 
	For any $k\geq 2$, we set $p\geq 2k$. If Assertion (i) holds, then for any $\bm{j}\in [p]^{2k}$, we have
	$$\lim_{n\rightarrow\infty}\kappa_{2k}\left(x_{j_1}^{(n)},\ldots ,x_{j_{2k}}^{(n)}\right)=\kappa_{2k}\left(s_{j_1},\ldots ,s_{j_{2k}}\right).$$
	Recall that the mixed cumulants of $s_1,\ldots,s_p$ are given by:
	\begin{equation}\label{sc-cumulant}
		\kappa_{2k}(s_{j_1},\ldots,s_{j_{2k}})=\left\{\begin{matrix}
			1, & \text{if } k=1\text{ and } j_1=j_2;\\
			0, & \text{otherwise}.
		\end{matrix}\right.
	\end{equation} 
	(see e.g. \cite[Examples 11.21]{bk4}).

	Given any $\bm{i}\in \N^{2k}$, there exists $\bm{j}\in [p]^{2k}$ such that $\ker(\bm{j})=\ker(\bm{i})$. By Theorem \ref{th1} (\ref*{th1-As4}) and Eq. \eqref{sc-cumulant}, 
	if  $\ker(\bm{i})\in \operatorname{NC}_2(2k)$, we have
	$$\lim_{n\rightarrow\infty}\kappa_{2k}\left(x_{i_1}^{(n)},\ldots ,x_{i_{2k}}^{(n)}\right)=\lim_{n\rightarrow\infty}\kappa_{2k}\left(x_{j_1}^{(n)},\ldots ,x_{j_{2k}}^{(n)}\right)=0,$$
	which implies Assertion (ii).

	`(ii) $\Rightarrow$ (iii)': 
	For any  $m\in \mathbb N$, let $n$ be sufficiently large. Since the sequence $(x_1^{(n)},\ldots,x^{(n)}_n)$ is $O_n^+$-invariant, it follows from Eq. (\ref{c-On-inv})  that the $m$-th order cumulant $\kappa_m(x_{i_1}^{(n)}\cdots x_{i_{m}}^{(n)})$ is given by  
	$$\kappa_m\qty(x_{i_1}^{(n)},\dots, x_{i_{m}}^{(n)})=\sum_{\pi\in \operatorname{NC}_{2,\leq}(\bm{i})} {\widetilde\kappa_m^{(n)}(\pi)}, $$
	where $\widetilde\kappa_m^{(n)}(\pi)=\kappa_m^{(n)}(x_{j_1}^{(n)},\dots, x_{j_{m}}^{(n)})$ for arbitrary sequence $\bm{j}\subset [n]^m$ such that $\ker(\bm{j})=\pi$.
	 In particular, $\kappa_m(x_{j_1}^{(n)}\cdots x_{j_{m}}^{(n)})=0$ whenever $m$ is odd. 
	 Together with Assertion (ii), it follows that, for all $m\neq 2$ and all  $\bm{j}\in \N^{m}$, 
	 $$\kappa_{m}\qty(x_{j_1}^{(n)}\cdots x_{j_{m}}^{(n)})\rightarrow 0,\text{ as }n\rightarrow \infty.$$ 
	  When $m=2$, It follows that
	$$\kappa_2\qty(x_{j_1}^{(n)},x_{j_2}^{(n)})=\begin{cases}
		\operatorname{Var}({x_1^{(n)}}), &\text{ if } j_1=j_2;\\
		0, &\text{ if } j_1\neq j_2.
	\end{cases}$$

	For any $k>0$ and $\bm{i}\in \N^{2k}$, there exists $\bm{j}\in \N^{2k}$ such that $\ker(\bm{j})= \ker(\bm{i})$.
	If $\ker(\bm{i})\in \operatorname{NC}_2(2k)$, then by Theorem \ref{th1} (\ref*{th1-As3}) and the moment-cumulant formula (\ref{Emc}), we obtain
	\begin{equation*}
		\begin{aligned} \lim_{n\rightarrow\infty}\varphi_n\left(x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)}\right)
			&=\lim_{n\rightarrow\infty}\varphi_n\left(x_{j_1}^{(n)}\cdots x_{j_{2k}}^{(n)}\right)\\
			&=
			\lim_{n\rightarrow\infty}\sum_{\pi\in \operatorname{NC}(2k)}\kappa_\pi\left(x_{j_1}^{(n)},\ldots, x_{j_{2k}}^{(n)}\right)\\
			&=\lim_{n\rightarrow\infty}\sum_{\pi\in \operatorname{NC}_2(2k)}\kappa_\pi\left(x_{j_1}^{(n)},\ldots, x_{j_{2k}}^{(n)}\right)\\
			&=\lim_{n\rightarrow\infty}\kappa_{\ker(\bm{i})}\left(x_{j_1}^{(n)},\ldots, x_{j_{2k}}^{(n)}\right)\\
			&=\qty(\kappa_2\qty(s_{1},s_{1}))^k=1.
		\end{aligned}
	\end{equation*}	

	`(iii) $\Rightarrow$ (iv)': Given any  $m>0$, we assume $n$ is large enough. According to Remark \ref{rk1} (ii), we denote $\widetilde\varphi_m^{(n)}(\pi): P(m)\rightarrow \mathbb C$ defined as $\widetilde\varphi_m^{(n)}(\pi)=\varphi_n(x_{i_1}^{(n)}\cdots x_{i_{m}}^{(n)})$, where $\bm{i}$ is an arbitrary sequence in $[n]^m$ such that $\ker(\bm{i})=\pi$. 
	 For any $\pi\in P(m)$, there exists $\bm{j}\in \N^{m}$ such that $\ker(\bm{j})=\pi$. By Theorem \ref{th1} (\ref*{th1-As3}), we obtain 
	 $$\widetilde\varphi_m^{(n)}(\pi)=\varphi_n\qty(x_{j_1}^{(n)}\cdots x_{j_{m}}^{(n)}).$$
	  Moreover, if $m=2k$ ($k>0$) and
	$\pi\in\operatorname{NC}_2(2k)$, then by  Assertion (iii), we have 
	\begin{equation*}
		\widetilde\varphi_{2k}^{(n)}(\ker(\bm{i}))=\varphi_n\left(x_{j_1}^{(n)}\cdots x_{j_{2k}}^{(n)}\right)=1+o(1).
	\end{equation*}
	By Eq. (\ref{m-On-inv}), {it follows that}
	$$\begin{aligned}
		\varphi_n\qty(\frac{1}{n^k}\sum_{\bm{i}\in [n]^{2k}} \delta_{\pi}(\bm{i})x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)})&=\frac{1}{n^k}\sum_{\bm{i}\in [n]^{2k}} \delta_{\pi}(\bm{i})\varphi_n\left(x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)}\right)\\
		&=\frac{1}{n^k}\sum_{\bm{i}\in [n]^{2k}} \delta_{\pi}(\bm{i})\sum_{\sigma\in \operatorname{NC}_2(2k)}\delta_{\sigma}(\bm{i})\widetilde\varphi_{2k}^{(n)}(\sigma)\\
		&=\frac{1}{n^k}\sum_{\sigma\in \operatorname{NC}_2(2k)}\widetilde\varphi_{2k}^{(n)}(\sigma)\sum_{\bm{i}\in [n]^{2k}} \delta_{\pi}(\bm{i})\delta_{\sigma}(\bm{i})\\
		&=\frac{1}{n^k}\sum_{\sigma\in \operatorname{NC}_2(2k)}n^{\#(\pi\vee\sigma)}\left(1+o(1)\right).
	\end{aligned}$$
	For $\sigma,\pi\in \operatorname{NC}_2(2k)$, we have $\#(\pi\vee\sigma)\leq k$ and the equation holds if and only if $\pi=\sigma$. Therefore, we obtain
	$$\frac{n^{\#(\pi\vee\sigma)}}{n^k}\left(1+O(n^{-1})\right)\rightarrow\left\{
	\begin{matrix}
		1, & \pi=\sigma;\\
		0, & \text{otherwise},
	\end{matrix}
	\right.\quad\text{as } n\rightarrow \infty,$$ 
	which yields Assertion (iv).
	%	For partitions $\pi_1\in P(\{1,\ldots,m_1\})$ and $\pi_2\in P(\{m_1+1,\ldots,m_1+m_2\})$, then $\pi\coloneq\pi_1\cup\pi_2$ is a partition in $P(m_1+m_2)$ such that $\pi|_{\{1,\ldots m_1\}}=\pi_1$ and $\pi|_{\{m_1+1,\ldots,m_1+m_2\}}=\pi_2$.  
	%	Assume $n$ is sufficiently large. For $l=1,\ldots,m$, let $k_0=0$ and $k_l$ be even integers. 
	%	Note that $P(m_2)\cong P(\{m_1+1,\ldots,m_1+m_2\})$. There exists a one-to-one map $\iota_{m_1} : P(m_2)\rightarrow P(\{m_1+1,\ldots,m_1+m_2\})$ such that $\iota_{m_1}(\pi)\leq \iota_{m_1}(\sigma)$ if $\pi\leq \sigma$ for all $\pi,\sigma\in P(m)$. 
	%	Then for $\pi_l\in\operatorname{NC}_2(k_{l}), l=1,\ldots,m $, there exists $\widetilde\pi_l\in\operatorname{NC}_2(\{k_1+\ldots+k_{l-1}+1,\ldots,k_1+\ldots+k_{l}\})$ such that $\widetilde\pi_l=\iota_{m_1+\ldots+m_{l-1}}(\pi_l)$. 
	%	Let $\pi=\bigcup_{l=1}^m\iota(\pi_{l})$. It is easy to see that $\pi\in\operatorname{NC}_2(2(k_1+\ldots k_l))$ and  $y_{\pi}^{(n)}=y_{\pi_1}^{(n)}\ldots y_{\pi_m}^{(n)}$. 
	%	Thus we have $\varphi\left(y_{\pi_1}^{(n)}\ldots y_{\pi_m}^{(n)}\right)$$\rightarrow 1$.

	% `(v) $\Rightarrow$ (iv)' is obvious.

	`(iv) $\Rightarrow$ (i)': 
		For each $m\in \mathbb N$, by Remark \ref{rk1} (ii), the moment $\varphi_n(x_{i_1}^{(n)}\cdots x_{i_{m}}^{(n)})$ is of the form given by Eq. (\ref{m-On-inv}), namely, 
	\begin{equation*}
		\varphi_n\qty(x_{i_1}^{(n)}\cdots x_{i_m}^{(n)})=
		\sum\limits_{\pi\in \operatorname{NC}_{2,\leq}(\bm{i})}{\widetilde\varphi_m^{(n)}(\pi)}.
	\end{equation*}
	In particular, $\varphi_n(x_{i_1}^{(n)}\cdots x_{i_{m}}^{(n)})=0$ whenever $m$ is odd. Assume $m=2k$ (k>0), then for all $p\geq 2$ and $\bm{i}\in [p]^{2k}$, we obtain
	$$ \begin{aligned}
		\varphi_n\left(x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)}\right)
		&=(\varphi_n\otimes h)\circ\alpha_n\left(x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)}\right)\\
		&=\sum_{\bm{j}\in[n]^{2k}}\varphi_n\left(x_{j_1}^{(n)}\cdots x_{j_{2k}}^{(n)}\right) h\qty(u_{j_1i_1}\cdots u_{j_{2k}i_{2k}})\\
		&=\sum_{\bm{j}\in[n]^{2k}}\varphi_n\left(x_{j_1}^{(n)}\cdots x_{j_{2k}}^{(n)}\right)\sum_{\pi,\sigma\in\operatorname{NC}_2(2k)} \delta_{\pi}(\bm{i}) \delta_{\sigma}(\bm{j})\operatorname{Wg}^{O_n^+}_{2k,n}(\pi,\sigma)\\
		&= \sum_{\pi,\sigma\in\operatorname{NC}_2(2k)} \delta_{\pi}(\bm{i}) \operatorname{Wg}^{O_n^+}_{2k,n}(\pi,\sigma)n^k \varphi_n\left(\frac{1}{n^k}\sum_{\bm{j}\in[n]^{2k}}\delta_{\sigma}(\bm{j})x_{j_1}^{(n)}\cdots x_{j_{2k}}^{(n)}\right).
	\end{aligned}$$
	%Then $\varphi_n(x_{i_1}^{(n)}\cdots x_{i_{2k}}^{(n)})\rightarrow 1$ since, 
	By \cite[Propotion 7.2]{ref14} and Assertion (iv),  we obtain
	$$\operatorname{Wg}^{O_n^+}_{2k,n}(\pi,\sigma)n^k\rightarrow\left\{\begin{matrix}
		1 & \pi=\sigma\\
		0 & \text{otherwise}
	\end{matrix}\right. \quad \text{and} \quad  \varphi_n\left(\frac{1}{n^k}\sum_{\bm{j}\in[n]^{2k}}\delta_{\sigma}(\bm{j})x_{j_1}^{(n)}\cdots x_{j_{2k}}^{(n)}\right)\rightarrow 1.$$
	It follows that, for each $m\in \mathbb N$ and $\bm{i}\in [p]^m$, we have
	$$\lim_{n\rightarrow\infty}\varphi_n\left(x_{i_1}^{(n)}\cdots x_{i_{m}}^{(n)}\right)=\sum_{\pi\in\operatorname{NC}_{2,\leq}(\bm{i})}1.$$
	In addition, applying the moment-cumulant formula (\ref{Emc}) together with the values of mixed cumulants  for  free semicicular random variables (\ref{sc-cumulant}), we obtain
	$$\varphi\left(s_{i_1}\cdots s_{i_{m}}\right)=\sum_{\pi\in\operatorname{NC}(m)}\kappa_{m}(s_{i_1},\ldots,s_{i_m})=\sum_{\pi\in\operatorname{NC}_{2,\leq}(\bm{i})}1.$$
	Thus, Assertion (i) follows.
\end{proof}


