\section{Infinite de Finetti theorem for  easy quantum groups}\label{sect4}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this section, we refine the previous arguments to obtain an infinite de Finetti theorem for free easy quantum groups. 
Let $(A,\varphi)$ be a $\ast$-probability space generated by a sequence of self-adjoint elements $(x_i)_{i\in\mathbb N}$. 
For a category of non-crossing partitions $\mathcal C$, we denote by $G_n(\mathcal C)$ (or simply $G_n$ if no confusion arises) the associated free easy quantum group acting on $n$ variables. 
We call $(x_i)_{i\in\mathbb N}$ \textbf{${G}$-invariant} if $(x_1,\ldots,x_n)$ is $G_n$-invariant for all $n\in\mathbb N$. %In this section, we abuse the notations of functions $\widetilde{\varphi}_m$ and $\widetilde{\kappa}_m$ given in  Remark \ref{rk1} (ii). 

In the infinite setting,  let $(x_i)_{i\in\mathbb N}$ be a $G$-invariant sequence in the $\ast$-probability space $(A,\varphi)$. For each $\pi\in P(m)$, there exists $\bm{i}=(i_1,\ldots,i_m)\in \nat^m$, such that $\ker{(\bm{i})}=\pi$. 
Extending the notation from the  Remark \ref{rk1}  (ii), we define the map $\widetilde{\varphi}_m: P(m)\rightarrow\mathbb C$ by $\widetilde{\varphi}_m(\pi)=\varphi(x_{i_1}\cdots x_{i_m})$, where $(i_1,\ldots,i_m)$ is any arbitrary  sequence in $\mathbb N^m$ satisfying $\ker(\bm{i})=\pi$. $\widetilde{\varphi}_m$ is well defined  follows from Theorem \ref{th1} which guarantees that $\varphi(x_{i_1}\cdots x_{i_m})=\varphi(x_{j_1}\cdots x_{j_m})$ whenever $\ker(\bm{i})=\ker(\bm{j})$.
 An analogous result holds for the cumulant function $\widetilde{\kappa}_m$. With these definitions in place, we now state the following theorem.
\begin{thm}
	\label{th2}
	Let $(x_i)_{i\in \mathbb N}$ be a family of self-adjoint random variables in the $\ast$-probability space $(A, \varphi)$.  Let $G_n$ and $\mathcal C$ be as above. Then
	the following are equivalent:
	\begin{itemize}
		\item	
		[(i)] The sequence $(x_i)_{i\in \mathbb N}$ is $G$-invariant. 
		\item
		[(ii)] For any $m>0$ and $\bm{i}\in \nat^m$, 
		\begin{equation}\label{eqp}
			\varphi(x_{i_1}\cdots x_{i_m})=
			\sum\limits_{\pi\in \mathcal C_{\leq}(\bm{i})}\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\varphi_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)},
		\end{equation}
		%where $\mu_{\mathcal C}(\sigma,\pi)$ is the Möbius function relative to $\mathcal C(m)$. 
		In particular, $\varphi(x_{i_1}\cdots x_{i_m})$ is zero except  
		$\mathcal C_{\leq}(\bm{i})\neq \varnothing$.
		\item[(iii)] For any $m>0$ and $\bm{i}\in \nat^m$, 
		\begin{equation}\label{eqc1}
			\kappa_{m}(x_{i_1},\ldots ,x_{i_m})=
			\sum\limits_{\pi\in \mathcal C_{\leq}(\bm{i})}\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\kappa_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)}.
		\end{equation}
		In particular, $\kappa_{m}(x_{i_1},\ldots ,x_{i_m})$ is zero except  
		$\mathcal C_{\leq}(\bm{i})\neq \varnothing$.
	\end{itemize}
\end{thm}
\begin{proof}

	If $(x_i)_{i\in \mathbb N}$ is $G$-invariant, then for each $n>0$, the tuple $(x_1,\ldots,x_n)$ is $G_n$-invariant. Let $A_n$ denote the subalgebra of $A$ generated by $(x_1,\ldots,x_n)$ and define $\varphi^{(n)}=\varphi|_{A_n}$. For $m,n\in \mathbb N$,
we retain the notation $D_n(m)$ from Remark \ref{rk1} and similarly define $\wt\varphi^{(n)}_m :D_n(m)\rightarrow \mathbb C$ as the functional determined by $\varphi^{(n)}$.
 If $n\geq 2m$, then $D_n(m)=P(m)$.
	By Theorem \ref{th1}, there exist scalars $c_\pi^{(n,m)}$ and $C_\pi^{(n,m)}$ ($\pi\in \mathcal C(m)$) such that, for any $\sigma\in \mathcal C(m)$,
	\begin{equation}\label{eq11}
		\widetilde\varphi^{(n)}_m(\sigma)=
		\sum\limits_{\substack{\pi\in\mathcal C(m)\\ \pi\leq \sigma}}c_\pi^{(n,m)}
		\quad \text{and}\quad \widetilde\kappa_{m}^{(n)}(\sigma)=
		\sum\limits_{\substack{\pi\in\mathcal C(m)\\ \pi\leq \sigma}}C_\pi^{(n,m)}.
	\end{equation}
	Thus, if $n\geq2m$, by the equivalence between Eq. (\ref{eqi1}) and Eq. (\ref{eqi2}), we have \begin{equation}\label{eq14}
		c_\pi^{(n,m)}=\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\varphi_m^{(n)}(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)}
		\quad \text{and} \quad
		C_\pi^{(n,m)}=\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\kappa_m^{(n)}(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)}.
	\end{equation} 
	%Let $n'$ be a integer greater that $n$, then we have $D_n(m)\subset D_{n'}(m)$. 
	The definition of the functionals $\widetilde\varphi^{(n)}_m$ and $\widetilde\varphi_m$ immediately implies that, for any $\pi\in D_n(m)$,
	 $\widetilde\varphi^{(n)}_m(\pi)=\wt\varphi_m(\pi)$.	
	Together with Eq. (\ref{eq14}), we obtain Eq. (\ref{eqp}) and Eq. (\ref{eqc1}), 
	{which yield Assertions (ii) and (iii).}

	Conversely, if the Assertion (ii) (respectively, Assertion (iii)) holds, then for each $m,n>0$, the moments (respectively, the cumulants) of $(x_1,\ldots,x_n)$ is of the form Eq. (\ref{eq11}),
	where 
	$$ c_\pi^{(m)}=\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\varphi_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)}\quad \text{and}\quad C_\pi^{(m)}=\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\kappa_m(\sigma)\mu_{\mathcal C(m)}(\sigma,\pi)}.$$
	Thus by Theorem \ref{th1}, the sequence $(x_1, \ldots, x_n)$ is $G_n$-invariant.
\end{proof}


%Let $(\pi_n,L^2 (G_n^\times))$ be the GNS representation of $C(G_n^\times)$ with respect to the Haar state $h_n$. The Hopf von Neumann algebra $L^\infty (G_n^\times)$ is defined as the weak closure of $\pi_n\left(C(G_n^\times)\right)$. Repeating the preceding argument, we can obtain the GNS representation $\pi_\varphi$ of $A$ and the von Neumann algebra $L^\infty(A)$. In  \cite{ref11}, Curran proved that there is a right coaction $\widetilde{\alpha}_n: L^\infty(A)\mapsto L^\infty(A)\otimes L^\infty (G_n^\times)$, determined by $\widetilde{\alpha}_n(\pi_\varphi x)=(\pi_\varphi\otimes \pi_n)\otimes \alpha_n(x)$ for $x\in(A,\varphi)$.  Then we have a free easy quantum group action on $(L^\infty(A),\varphi)$. It follows that $\varphi\otimes h_n(\widetilde{\alpha}_n(\pi_\varphi x))=\varphi\otimes h_n({\alpha}_n x)$ for $x\in A$.

For $\times\in\{o,b,s,h\}$, we denote by $G_n^{\times}$ the free easy quantum groups $O_n^+$, $B_n^+$, $S_n^+$ and $H_n^+$, respectively, and by $\mathcal C^\times$ the category of non-crossing partitions associated with $G_n^\times$. Let $(\mathcal M,\varphi)$ be a $W^*$-probability space, namely, $\mathcal M$ is a von Neumann algebra and $\varphi$ is a faithful normal state ($\varphi$ is not necessarily a trace.) Let $(x_i)_{i \in \mathbb{N}}$ be a sequence of self-adjoint elements in $\mathcal M$.
It is shown in \cite[Theorem 1]{ref5} that, for $\times\in\{o,b,s,h\}$, there exists a von Neumann subalgebra $\mathcal B$ of $\mathcal M$, such that the  $G^{\times}$-invariance of $(x_i)_{i \in \mathbb{N}}$ can be characterized by its operator-valued freeness:
\begin{itemize}
	\item [(a)] If $\times=o$, $(x_i)_{i \in \mathbb{N}}$ is a  $\mathcal B$-valued free semi-circular family with  mean zero and common variance.
	\item [(b)] If $\times=h$, $x_i$, ${i \in \mathbb{N}}$, have even and identical distributions and are free with amalgamation over $\mathcal B$.
	\item [(c)] If $\times=b$, $(x_i)_{i \in \mathbb{N}}$ is a  $\mathcal B$-valued free semi-circular family with common mean and variance.
	\item [(d)] If $\times=s$, $x_i$, ${i \in \mathbb{N}}$, have identical distributions and are free with amalgamation over $\mathcal B$.
\end{itemize}
For convenience,  we will say that $(x_i)_{i \in \mathbb{N}}$ has the $\times$-distribution with respect to $\mathcal B$.
Combining Theorem \ref{th2} with \cite[Theorem 1]{ref5}, we can derive the following equivalent conditions for operator-valued freeness, bypassing the quantum group invariance. 

\begin{cor}\label{coro3}
	Consider the $W^*$-probability space $(\mathcal M, \varphi)$, which is endowed with a faithful state, generated by an infinite sequence of self-adjoint random variables $(x_i)_{i\in \mathbb N}$. Then, for $\times\in\{o,b,s,h\}$, the following are equivalent:
	\begin{itemize}
		\item [(i)] For any $m>0$ and $\bm{i}\in \nat^m$, 
		\begin{equation*}\label{eqc}
			\kappa_{m}(x_{i_1},\ldots ,x_{i_m})=
			\sum\limits_{\pi\in \mathcal C_{\leq}^\times(\bm{i})}\sum\limits_{\substack{\sigma\in \mathcal C(m)\\ \sigma\leq \pi}}{\widetilde\kappa_m(\sigma)\mu_{\mathcal C^\times(m)}(\sigma,\pi)}.
		\end{equation*}
		In particular, $\kappa_{m}(x_{i_1},\ldots ,x_{i_m})$ is zero except  
		$\mathcal C_{\leq}^\times(\bm{i})\neq \varnothing$.
		\item[(ii)] 
		There is a von Nuemann subalgebra $1\subset \mathcal B\subset \mathcal M$ and a $\varphi$-preserving conditional expectation $E:\mathcal M\rightarrow\mathcal  B$ such that 
		$(x_i)_{i \in \mathbb{N}}$ has the $\times$-distribution with respect to $\mathcal B$.
		\item [(iii)] 
		There is a von Nuemann subalgebra $1\subset \mathcal B\subset \mathcal M$ and a $\varphi$-preserving conditional expectation $E:\mathcal M\rightarrow\mathcal  B$ 
		such that, for any $m>0$,
		there is a family $(b_\pi)_{\pi\in \mathcal C(m)}\subset \mathcal B$ satisfying, for all $\bm{i}\in \nat^m$,
		\begin{equation}\label{eq8}
			E\left[x_{i_1}\cdots x_{i_m}\right]=
			\sum\limits_{\pi\in\mathcal C^\times_{\leq}(\bm{i})}b_\pi. 
		\end{equation}
		In particular, $E(x_{i_1}\cdots x_{i_m})$ are zero except
		$\mathcal C_{\leq}^\times(\bm{i})\neq \varnothing$ and $E(x_{i_1}\cdots x_{i_m})=E(x_{j_1}\cdots x_{j_m})$ as soon as $\ker(\bm{i})=\ker(\bm{j})$.
	\end{itemize}
\end{cor}
\begin{proof}
	 `(i)$\Leftrightarrow$(ii)': By Theorem \ref{th2} and \cite[Theorem 1]{ref5}, we have Assertions (i) and  (ii) are both equivalent to the $G^\times$-invariance of $(x_i)_{i\in \mathbb N}$.

	`(ii)$\Rightarrow$(iii)': 
	It is well known that Assertion (ii) holds if and only if, 
	for all $m>0 $, $\pi\in\C^\times(m)$ and $b_i\in B$, $i=0,1,\ldots,m$,
	$$\kappa^E_{\pi}[b_0x_{i_1}b_1,\ldots,x_{i_m}b_m]=0$$
	except when $\pi\in \C_\leq^\times(\bm{i})$. 
	Then it follows from the operator-valued moment-cumulant formula \eqref{Eopmc} that
 $$\begin{aligned}
		E\left[x_{i_1}\cdots x_{i_m}\right]&=
	\sum\limits_{\pi\in\mathcal C^\times_{\leq}(\bm{i})}\kappa^{E}_\pi(x_{i_1},\cdots,x_{i_m})\\
	&=\sum\limits_{\pi\in\mathcal C^\times_{\leq}(\bm{i})}\kappa^{E}_\pi(x_{1},\cdots,x_{1}),
	\end{aligned}$$ 
	where the second equality holds because the $\mathcal B$-valued distribution of $x_i$ ($i\in \N$) are identical.
	Since each $\kappa^{E}_\pi(x_{1},\cdots,x_1)$ lies in $\mathcal B$,
	we may define 
	$b_\pi=\kappa^{E}_\pi(x_{1},\cdots,x_1)$,
	 which  implies Assertion (iii).

	`(iii)$\Rightarrow$(i)': Applying $\varphi$ to both sides of (\ref{eq8}), 
	we have 
	$$
	\varphi(x_{i_1}\ldots x_{i_m})=
	\sum\limits_{\pi\in\mathcal C^\times_\leq(\bm{i})}\varphi(b_\pi).
	$$
	By Remark \ref{rk1}, we have that $\varphi(x_{i_1}\ldots x_{i_m})$ is of the form (\ref{eqp}),
	namely, 
	\begin{equation*}%\label{eq:p2}
		\varphi(x_{i_1}\cdots x_{i_m})=
		\sum\limits_{\pi\in \mathcal C_{\leq}^\times(\bm{i})}\sum\limits_{\substack{\sigma\in \mathcal C^\times(m)\\ \sigma\leq \pi}}{\widetilde\varphi_m(\sigma)\mu_{\mathcal C^\times(m)}(\sigma,\pi)}.
	\end{equation*}
	Thus Assertion (i) follows immediately from Theorem \ref{th2}.
\end{proof}

\begin{rk}\label{rk3}
	Let $n$ be an integer and let $A_u(n)$ denote the universal $C^*$-algebra generated by $n^2$ elements $(v_{ij})_{1\leq i,j\leq n}$ such that 
	both $v$ and $v^t$ are unitary. The pair $(A_u(n),v)$ is known as the  quantum unitary group and is commonly denoted by $U_n^+$. We refer to \cite{ref8} for details. The quantum unitary group $U_n^+$ can be associated with the category of non-crossing pair coloured partitions, denoted by $\operatorname{NC}_2^{\circ\bullet}$. We refer the reader to  \cite{bk3} to further more about coloured partition, to \cite{ref15} for the coaction of $U_n^+$ on $\ast$-algebra and to \cite{ref14} for the Haar state with respect to $U_n^+$.
	Theorems \ref{th1} and Theorem \ref{th2} can be extended verbatim to a unitary version by simply replacing $G_n$ with $U_n^+$ and $\operatorname{NC}_\times(m)$ with $\operatorname{NC}_2^{\circ\bullet}$.
\end{rk} 

