\date{\today}
\begin{abstract}
Given  a radial doubling  weight $\mu$ on the unit disc $\mathbb{D}$ of the complex plane and its odd moments  $\mu_{2n+1}=\int_0^1 s^{2n+1}\mu(s)\, ds$, we consider the fractional derivative
	$$
	D^\mu(f)(z)=\sum_{n=0}^{\infty} \frac{\widehat{f}(n)}{\mu_{2n+1}}z^n, %\quad z\in \D,
	$$
 of  a function $ f(z)=\sum_{n=0}^{\infty}\widehat{f}(n)z^n$ analytic in $\mathbb{D}$.

 We  also  consider the fractional integral operator
	$
	I^\mu(f)(z)=\sum_{n=0}^{\infty} \mu_{2n+1}\widehat{f}(n)z^n, %\, z\in\D,
	$ 
and the fractional  Volterra-type operator 
%  define the  extension of the  Volterra-type operator $V_g$,  for any fixed $g\in\H(\D)$ and a radial weight $\mu$  
	$$
	V_{\mu,g}(f)(z)= I^\mu(f\cdot D^\mu(g))(z),\quad f\in\H(\D),%,\quad z\in \D.
	$$
 for any fixed $g\in\H(\D)$.
We prove that $V_{\mu,g}$ is bounded (compact) on a Hardy space $H^p$, $0<p<\infty$, if and only  if $g$  belongs to $\BMOA$ ($\VMOA$).  Moreover, if 
$\int_0^1 \frac{\left(\int_r^1 \mu(s)\, ds\right)^p}{(1-r)^2}\,dr=+\infty$, we prove that  $V_{\mu,g}$ belongs to the Schatten class $S_p(H^2)$ if and only if $g=0$. On 
the  other hand,  if $\frac{\left(\int_r^1 \mu(s)\, ds\right)^p}{(1-r)^2}$ is a radial doubling weight it is proved that $V_{\mu,g} \in S_p(H^2)$ if and only if 
$g$ belongs to the  Besov space $B_p$.  En route, we obtain descriptions of $H^p$, $\BMOA$, $\VMOA$ and $B_p$ in terms of the fractional derivative $D^\mu$.



\end{abstract}
	\maketitle
	\section{Introduction}
Let $\H(\D)$ denote the space of analytic functions in the unit disc $\D=\{z\in\C:|z|<1\}$
and for a fixed function $g\in\H(\D)$ we consider the integral operator given by $$V_g(f)(z)=\int_0^z f(\z)g'(\z)\,d\z, \quad f\in \H(\D).$$
 % and $\A(\D)=\H(\D)\bigcap C(\overline{\D})$ the disk algebra.
%One of the operators which have attracted more attention
The Volterra-type operator $V_g$ is  prominent  in the study of   operator theory on spaces of analytic functions during the last decades.
 It probably has its origin in the bilinear operator $\left(f,g\right)\rightarrow \int f\,g'$  introduced by  A. Calder\'on in harmonic analysis in the $60$'s for his research on commutators of singular integral operators \cite{Calderon65}.
Pommerenke was  one of the first authors of the complex function theory community to consider the operator $V_g$ \cite{Pom}, and after the seminal works of Aleman, Cima and Siskakis \cite{AC,AS, ASBergman}, the study of the operator $V_ g$ on several spaces of analytic functions
has attracted a lot of attention in recent years  \cite{Aleman:Cascante:Fabrega:Pascuas:Pelaez,GLQ,MPPW,PR} in different contexts. Recently, different generalizations of $V_g$  defined in terms of  the $n$th derivative of the symbol $g$ and  iterated integrals have been considered in  \cite{ChaPAMS2020, DuLiQu2022}.

In this manuscript we are interested in proving that the classical results obtained in \cite{AC,AS, ASBergman},  on the boundedness, compactness and membership to Schatten classes of the  Volterra-type operator $V_g$ acting on Hardy and weighted Bergman spaces,
and the related recent ones obtained in \cite{ChaPAMS2020, ChaNik2025,DuLiQu2022},
 are examples of a general phenomenon  rather than  particular cases.  With this aim let us recall several concepts and introduce the required definitions. 

The extension 
$\mu(z)=\mu(|z|)$,\, $z\in\D$, of a non-negative function $\mu\in L^1([0,1))$  such that $\mug(r)=\int_{r}^1 \mu(s)\,ds>0$ for any $r\in(0,1)$, is called a radial weight. The 
 fractional derivative, induced by radial weight $\mu$, of  a function $ f(z)=\sum_{n=0}^{\infty}\widehat{f}(n)z^n \in \H(\D)$ is given by
	$$
	D^\mu(f)(z)=\sum_{n=0}^{\infty} \frac{\widehat{f}(n)}{\mu_{2n+1}}z^n, %\quad z\in \D,
	$$
where $\mu_{x}=\int_0^1 s^{x}\mu(s)\, ds$, $x\ge 0$ are the moments of  $\mu$.
%A calculation shows that $D^\mu$ is well-defined on $\H(\D)$ \cite{MorenoPelRosa}. 
 We will also  consider the fractional integral operator
	$
	I^\mu(f)(z)=\sum_{n=0}^{\infty} \mu_{2n+1}\widehat{f}(n)z^n, %\, z\in\D,
	$ 
and the operator
%  define the  extension of the  Volterra-type operator $V_g$,  for any fixed $g\in\H(\D)$ and a radial weight $\mu$  
	$$
	V_{\mu,g}(f)(z)= I^\mu(f\cdot D^\mu(g))(z),\quad f\in\H(\D),%,\quad z\in \D.
	$$
 for any fixed $g\in\H(\D)$ and a radial weight $\mu$.
%\medskip

It is worth mentioning  that the fractional derivative $D^\mu$ was introduced in  \cite{MorenoPelRosa,PelRosa} and  if $\mu$ is a standard weight $\mu(z)=\beta(1-|z|^2)^{\beta-1}$, $\b >0$, then
$$D^{\mu}(f)(z)=D^{\beta}(f)(z)=\frac{2}{\G(\beta+1)}\sum\limits_{n=1}^{\infty} \frac{\G (n+\beta+1)}{\G(n+1)} \widehat{f}(n) z^n, %\quad z\in\D,
$$
which basically coincides with the fractional derivative of order $\b>0$  introduced by Hardy and Littlewood in \cite[p. 409]{HLMathZ}. 


 The Hardy space $H^p$ consists of $f\in\H(\D)$ for which
$
    \|f\|_{H^p}=\sup_{0<r<1}M_p(r,f)<\infty$,
where
    $$
    M_p(r,f)=\left (\frac{1}{2\pi}\int_0^{2\pi}
    |f(re^{i\theta})|^p\,d\theta\right )^{\frac{1}{p}},\quad 0<p<\infty,
    $$
and 
    $$
    M_\infty(r,f)=\max_{0\le\theta\le2\pi}|f(re^{i\theta})|.
    $$ 
It was  proved in \cite{AC,AS} that the classical Volterra-type operator $V_g$
is bounded on $H^p$, $0<p<\infty$, if and only if $g\in\BMOA$. 
The space $BMOA$ consists  of $f\in H^1$ such that the function of its boundary values $f(e^{i\theta})$ belongs to $\text{BMO}(\T)$.  The space $\BMOA$ can be equipped with different norms, we will write
\begin{equation}\label{eq:normaBMOA}
\nm{f}_{\BMOA}^2= \abs{f(0)}^2 + \sup_{a\in\D} \frac{\int_{S(a)}\abs{f'(z)}^2 (1-|z|^2)\,dA(z)}{1-\abs{a}}
\end{equation}
where  $dA(z)=\frac{dx\,dy}{\pi}$ is the normalized Lebesgue area measure on $\D$ and
  $$S(a)=\set{z\in\D: \abs{\arg{a}-\arg{z}}\leq \frac{1-\abs{a}}{2}, 1-\abs{z}\leq 1-\abs{a}},\quad  a\in \D\setminus\{0\},\quad  S(0)=\D,$$
is called the Carleson square induced by $a$. We recall the reader that a positive Borel measure $\mu$ on $\D$ is called a classical Carleson measure  if 
$\sup_{a\in\D}  \frac{\mu(S(a))}{1-\abs{a}}<\infty$, therefore $f\in \BMOA$ if and only if $|f'(z)|^2(1-|z|^2)\,dA(z)$ is a  classical Carleson measure.
Moreover, for any radial weight $\mu$ we consider the space $\BMOA_\mu$ of $g\in \H(\D)$ such that
 $$\|g\|^2_{\BMOA_\mu}=\sup_{a\in\D}\frac{\int_{S(a)}\abs{D^\mu(g)(z)}^2\frac{\mug(z)^2}{1-\abs{z}}dA(z)}{1-\abs{a}}<\infty.$$

\medskip It is clear that essential features of the fractional derivative operator $D^\mu$ are strongly affected  by the asymptotic behaviour of the moments of $\mu$, which is not well-understood for a general radial weight $\mu$
\cite{BonetLuskyTaskinen,DostanicIbero,PR19}. For this reason we will assume in many of our results that $\mu$ is a radial doubling weight. 
A radial weight $\mu$ belongs to $\DD$ if there exists $C=C(\mu)>0$ such that 
	$$
	\mug(r)\le C\mug\left(\frac{1+r}{2}\right),\quad 0\le r<1,
	$$
and $\mu\in\Dd$ if
	$$
	\mug(r)\ge C\mug\left(1-\frac{1-r}{K}\right),\quad 0\le r<1,
	$$ 
for some   $K=K(\mu)>1$ and $C=C(\mu)>1$.
Write $\mathcal{D}=\DD\cap\Dd$, and simply say that $\mu$ is a radial doubling weight if $\mu\in\DDD$.
%From now on we write $\mu_x=\int_0^1r^x\mu(r)\,dr$,  $x\ge0$, to denote the moments induced by a radial weight $\mu$. 
The class $\DDD$ contains the standard radial weights and  $\mu\in \DDD$ if and only if for any (or some) $\beta>0$, 
$$\mu_x \asymp x^\beta  \left(\mu_{[\beta]} \right)_{x}, \quad x\ge 1,$$
where $\mu_{[\beta]}(s)=(1-s)^\beta \mu(s)$, see $(1.2)$ $(1.3)$ and Theorem~$3$ of \cite{PR19}. The class $\DDD$
 appear in a natural way in many questions on operator theory. For instance, the Bergman projection $P_\mu$ acts as a bounded and onto operator from the space $L^\infty$ of bounded complex-valued functions to the Bloch space $\mathcal{B}=\{ f \in \H(\D): \|f\|_{\B}=|f(0)|+ \sup_{z\in \D}(1-|z|^2)|f'(z)|<\infty\}$ if and only if $\mu\in\DDD$, and the Littlewood-Paley formula
	\begin{equation*}\label{LP}
	 \int_\D|f(z)|^p \mu(z)\,dA(z)\asymp \int_\D|f'(z)|^p(1-|z|)^p\mu(z)\,dA(z)+|f(0)|^p,\quad f\in \H(\D),
	\end{equation*}
is equivalent to $\mu\in\DDD$ \cite{PR19}.  For basic properties of the aforementioned classes of radial weights, concrete nontrivial
examples and more, see \cite{PelProcedings,PR,PR19} and the relevant references therein.


\begin{theorem}\label{th:Vmubounded}
Let  $0<p<\infty$, $\mu\in\DDD$ and $g\in\H(\D)$. Then,  the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $V_{\mu,g}$ is bounded on $H^p$; 
\item[\rm(ii)] $g\in \BMOA_\mu$;
 \item[\rm(iii)] $g\in \BMOA$.
\end{enumerate}
Moreover,
\begin{equation*}\label{eq:normVmug}
\| V_{\mu,g}\|_{H^p\to H^p}\asymp \|g\|_{\BMOA_\mu}\asymp \nm{g}_{\BMOA}.
\end{equation*}
\end{theorem}

We will also obtain a description of  the symbols $g\in \H(\D)$ such that  $V_{\mu,g}$ is compact on $H^p$.
Let us recall that a classical Carleson measure $\mu$ on $\D$ is a vanishing Carleson measure if  $\lim_{|a|\to 1^-}\frac{\mu(S(a))}{1-|a|}=0$. A function $g\in \H(\D)$ belongs to $\VMOA$ if  
 $|g'(z)|^2(1-|z|^2)\,dA(z)$ is a  vanishing  Carleson measure
and $g\in\VMOA_\mu$ if  $d \nu_g(z)=\abs{D^\mu(g)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\, dA(z)$ is a vanishing Carleson measure.
\begin{theorem}\label{th:Vmucompact}
Let  $0<p<\infty$, $\mu\in\DDD$ and $g\in\H(\D)$. Then,  the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $V_{\mu,g}$ is compact on $H^p$; 
\item[\rm(ii)] $g\in \VMOA_\mu$;
 \item[\rm(iii)] $g\in \VMOA$.
\end{enumerate}
\end{theorem}




\medskip
The proofs of Theorems~\ref{th:Vmubounded} and \ref{th:Vmucompact} will be built on an ad hoc equivalent norm of  $H^p$ spaces in terms of the fractional derivative $D^\mu$, so that we can get rid of the fractional integral operator $  I^\mu$ which appears in the definition of $V_{\mu,g}$,  in the study of its boundedness and compactness.


It is well-known \cite{AhernBruna1988,FefSt} that for every $n\in\N$ and $0<p<\infty$ the Hardy space $H^p$ can be described in terms of the following Calderon's formula 
	\begin{equation}\label{eq: norma calderon}
		\nm{f}_{H^p}^p \asymp \sum_{j=0}^{n-1}\abs{f^{(j)}(0)}^p + \int_{\T} \left (\int_{\Gamma(\z)} \abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}\,dA(z) \right )^{\frac{p}{2}} \abs{d\z}
	\end{equation}
where
	$
	\Gamma(\xi)=\left\{z\in\D:|\arg z-\arg\xi|<(1-|z|)\right\}
	$
is the non-tangential approach region (cone), with vertex at $\xi\in\T=\partial\D$.
We obtain the following extension of \eqref{eq: norma calderon}.
\begin{theorem}\label{th:main}
Let $\mu$ be a radial weight and $0<p<\infty$. Then, the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $\mu\in\DDD$;  
\item[\rm(ii)] $$
		\nm{f}^p_{H^p} \asymp \int_\T \left [ \int_{\Gamma(\xi)} \abs{D^\mu(f)(z)}^2 \left (\frac{\mug(z)}{1-\abs{z}}\right )^2 dA(z) \right ]^{\frac{p}{2}}\abs{d\xi},\quad f\in \H(\D);
		$$
\item[\rm(iii)] $$
		 \int_\T \left [ \int_{\Gamma(\xi)} \abs{D^\mu(f)(z)}^2 \left (\frac{\mug(z)}{1-\abs{z}}\right )^2 dA(z) \right ]^{\frac{p}{2}}\abs{d\xi}
 \lesssim \nm{f}^p_{H^p}, \quad f\in \H(\D).
		$$
\end{enumerate}
\end{theorem}

Theorem~\ref{th:main} follows from Theorem~\ref{th: norma equivalente <} and Theorem~\ref{th: norma equivalente >} below. In particular, the inequality
$$\nm{f}^p_{H^p} \lesssim \int_\T \left [ \int_{\Gamma(\xi)} \abs{D^\mu(f)(z)}^2 \left (\frac{\mug(z)}{1-\abs{z}}\right )^2 dA(z) \right ]^{\frac{p}{2}}\abs{d\xi},\quad f\in \H(\D),$$ holds for any radial weight $\mu$.
It is  worth mentioning that the main ideas in the proof of Theorem~\ref{th:main} comes from \cite{DuanRattyaWang2025}.


We will also obtain a description of $\BMOA$ in terms of the fractional derivative $D^\mu$.
\begin{theorem}\label{th: caracterizacion BMOAmain}
	Let $\mu$ be a radial weight. Then, the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $\mu\in\DDD$;  
\item[\rm(ii)] $$
	 \|g\|_{\BMOA_\mu} \asymp \nm{g}_{\BMOA},\quad g\in\H(\D);
	$$
\item[\rm(iii)] $$
	 \|g\|_{\BMOA_\mu} \lesssim \nm{g}_{\BMOA},\quad g \in\H(\D);
	$$
\item[\rm(iv)] $\VMOA_\mu= \VMOA$ and $$
	 \|g\|_{\BMOA_\mu} \asymp \nm{g}_{\BMOA},\quad g\in\VMOA;
	$$
\item[\rm(iv)] $\VMOA_\mu\subset \VMOA$ and $$
	 \|g\|_{\BMOA_\mu} \lesssim \nm{g}_{\BMOA},\quad g\in\VMOA.
	$$
\end{enumerate}
\end{theorem}
Theorem~\ref{th: caracterizacion BMOAmain} follows from Theorem~\ref{th: caracterizacion BMOA <} and  Theorem~\ref{th: caracterizacion BMOA >}. Especially, the quantitative embedding
$$ \nm{g}_{\BMOA}\lesssim \|g\|_{\BMOA_\mu}, \quad g\in\H(\D),$$
holds for any radial weight $\mu$. In the proofs of Theorem~\ref{th:main} and Theorem~\ref{th: caracterizacion BMOAmain} we will merge classical techniques employed on Hardy spaces with recent skills introduced in the context of Bergman spaces induced by radial weights. Let us recall that for $0<p<\infty$ and  a radial weight $\omega$, the Bergman  space $A^p_\om$ consists of functions $f\in \H(\D)$  such that
    $$
    \|f\|_{A^p_\omega}^p=\int_\D|f(z)|^p\omega(z)\,dA(z)<\infty.
    $$
In particular, it will be proved a  useful   identity 
which relates $D^\mu(f)$ with the $n$-th-derivative of $f$ (see  subsection~\ref{subse:22} below), which can be written either using the Taylor coefficient of $f$ or in terms of an integral on $\D$.   It will also be used
 precise Bergman norm estimates of the modified 
reproducing kernels $(1-\overline{z}\z)^NB^\om_z(\z)$ recently obtained in \cite[Lemma~5]{PelRatBMO}. Here  $B^\om_z$ is the   Bergman reproducing kernel  induced by a radial weight $\om$
at the point $z$. Theorem~\ref{th:main}, Theorem~\ref{th: caracterizacion BMOAmain} and a description of the positive Borel measures $\mu$ on $\D$
 such that the Hardy space is embedded in a tent space induced by $\mu$ (see Theorem~\ref{th:cohn} below) are the main ingredients in the proofs of  Theorem~\ref{th:Vmubounded} 
and Theorem~\ref{th:Vmucompact}. 

\medskip
Later on\textcolor{red}{,} we will prove the analogues to Theorem~\ref{th:Vmubounded} and Theorem~\ref{th:Vmucompact} on standard Bergman spaces $A^p_\alpha$, that is on $A^p_\om$ with
$\omega(z)=(\alpha+1)(1-|z|^2)^\alpha$, $\alpha>-1$. These results are (essentially) known due to the results in \cite{MorenoPelRosa, PelRosa} and we include them for the sake of completeness. 
 Therefore, let us recall that the little Bloch space
$\B_0$ consists of $g\in \B$ such that 
$\lim\limits_{\abs{z}\to 1^-}(1-\abs{z}^2)\abs{g'(z)} = 0$. Moreover, if $\mu$ is a radial weight we consider,
 the space $
    \mathcal{B}^\mu$ of $g\in\H(\D)$ such that $\nm{g}_{\mathcal{B}^\mu}=\sup_{z\in \D} \widehat{\mu}(z)\abs{D^\mu(g)(z)}<\infty$
and
$
\B_0^\mu = \set{f\in  \mathcal{B}^\mu : \lim\limits_{\abs{z}\to 1^-}\mug(z)\abs{D^{\mu}(f)(z)} = 0}.
$


\begin{theorem}\label{th:bergmanVmuboundedcompact}
	Let $\mu\in\DDD$, $0<p<\infty$, $\a>-1$ and $g\in\H(\D)$. Then,
	\begin{enumerate}
		\item[\rm(a)] The following conditions hold if and only if $V_{\mu,g}$ is bounded on $A^p_\a$;
\begin{enumerate}
\item[\rm(ai)]  $g\in\B^\mu$;
\item[\rm(aii)] $g\in\B$.
\end{enumerate}
Moreover, $$\| V_{\mu,g}\|_{A^p_\alpha\to A^p_\alpha}\asymp \|g\|_{\B^\mu}\asymp \nm{g}_{\B}.$$

\item[\rm(b)]  The following conditions hold if and only if $V_{\mu,g}$ is compact on $A^p_\a$;
\begin{enumerate}
\item[\rm(bi)]  $g\in\B_0^\mu$;
\item[\rm(bii)] $g\in\B_0$.
\end{enumerate}
\end{enumerate}
\end{theorem}

Our last main result concerns a description of the symbols $g\in \H(\D)$ such that  $V_{\mu,g}$, acting either on $H^2$ or on $A^2_\alpha$  ($\alpha>-1$), belongs to a
 Schatten  class. Therefore, we remind the reader that
for a compact operator $T$ on separable Hilbert space $\mm{H}$, there exists a decreasing sequence of positive numbers $\{\lambda_n(T)\}_n$ and orthonormal sets $\{e_n\}_n,\{\sigma_n\}_n\subset \mm{H}$ such that
$$T(x)=\sum_{n=1}^{+\infty}\lambda_n(T)\langle x,e_n\rangle \sigma_n\qquad x\in\mm{H}\,.$$
%The sequence $\{\lambda_n(T)\}_n$ consists of the eigenvalues of $|T|=(T^*T)^{\frac{1}{2}}$, repeated according to their multiplicity, and $\{e_n\}_n$ are the corresponding eigenvectors. 
The sequence of numbers $\{\lambda_n(T)\}_n$ is called the  singular value sequence of $T$.
\par For $0<p<\infty$, the Schatten-von Neumann ideal of $\mm{H}$, denoted by $S_p(\mm{H})$, is the space of all compact operators $T$ acting on $\mm{H}$, such that the singular value sequence of $T$ belongs to $\ell^p$. Let
\begin{equation*}\label{norm of Schatten}
\|T\|_{S_p(\H)}=\left(\sum_{n=1}^{+\infty}\lambda_n(T)^p\right)^{\frac{1}{p}}\,.
\end{equation*}
%For $1\leq p<\infty$, $(S_p(\mm{H}),\|\cdot \|_{S_p(\H)})$ becomes a Banach space, while for $0<p<1$, $\|\cdot \|_{S_p(\H)}^p$ defines a metric and $S_p(\mm{H})$ is a complete topological %space.
On the other hand, for $0<p<\infty$ and $n_p$ the minimum $n\in \N$ such that $np>1$,  the classical Besov space $B_p$ consists of $f\in \H(\D)$ such that 
$$\| f\|^p_{B_p}=\sum_{j=0}^{n_p-1}|f(0)|^p+\int_{\D} |f^{(n_p)}(z)|^p(1-|z|^2)^{n_pp-2}\,dA(z)<\infty.$$
For $0<p<\infty$ and $\mu$ a radial weight such that $\frac{\mug(r)^p}{(1-r^2)^2}$ is a weight we introduce the fractional derivative Besov space $B_{p,\mu}$ of $f\in \H(\D)$ such that 
$$\| f\|^p_{B_{p,\mu}}=\int_{\D} | D^{\mu}(f)(z)|^p \frac{\mug(z)^p}{(1-|z|^2)^2}  \,dA(z)<\infty.$$
Here and  on the following we denote $A^2_{-1}=H^2$.
%In \cite{AS,ASBergman} the symbols $g\in\H(\D)$ such that the classical Volterra-type operator $V_g\in S_p(A^2_\a)$, $\a\geq-1$ are characterized in terms of the space $B_p$. 

\begin{theorem}\label{th:schattendugintro}
Let $\mu\in \DDD$, $\alpha\ge -1$, $0<p<\infty$ and $g\in \H(\D)$. Then,
\begin{enumerate}
\item[\rm(a)] If $\int_0^1 \frac{\mug(r)^p}{(1-r)^2}\,dr=+\infty$, then $V_{\mu,g}\in S_p(A^2_\alpha)$ if and only if $g=0$.
 \item[\rm(b)] If $\frac{\mug(r)^p}{(1-r)^2}$ is a radial weight, then the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $V_{\mu,g}\in S_p(A^2_\alpha)$;
\item[\rm(ii)]  $g\in B_{p,\mu}$;
\end{enumerate} 
and  $$\| V_{\mu,g}\|_{S_p(A^2_\alpha)}\asymp \|g\|_{B_{p,\mu}}.$$ 

Moreover, if $\frac{\mug(r)^p}{(1-r)^2}\in \Dd$, (i) and (ii) are equivalent to the condition $g\in B_p$ and 
 $$\| V_{\mu,g}\|_{S_p(A^2_\alpha)}\asymp \|g\|_{B_{p,\mu}}\asymp \|g\|_{B_p}.$$ 

\end{enumerate}
\end{theorem}
It is worth mentioning that for any $1<p<\infty$,  the classical Volterra-type operator $V_g\in S_p(A^2_\a)$, $\a\geq-1$, if and only if $g\in \B_p$. In the case $0<p\le 1$,
 $V_g\in S_p(A^2_\a)$ if and only if $g$ is constant \cite{AS,ASBergman}. Going further,  we  consider the operator 
$$I^n(f)(z)=\int_0^z I_{n-1}(f)(z)\, dz,\quad I_0(f)(z)=z, \quad n\in \N,$$
and the operator  $V_{n,g}(f)(z) = I^n(f \cdot g^{(n)})(z)$. It was shown in \cite[Corollary~1, p.27]{DuLiQu2022} that for
any $\frac{1}{n}<p<\infty$,   $V_{n,g}\in S_p(A^2_\a)$, $\a>-1$, if and only if $g\in \B_p$. In the case $0<p\le \frac{1}{n}$,
 $V_g\in S_p(A^2_\a)$ if and only if $g^{(n-1)}$ is constant. Consequently, in view of all the previous results,  it is not surprising that Theorem~\ref{th:schattendugintro} states 
that  the cut-off for which there exist non-trivial operators $V_{\mu,g} \in S_p(A^2_\alpha)$ depends  on the condition  $\int_0^1 \frac{\mug(r)^p}{(1-r)^2}\,dr<+\infty$. 
 Indeed in  our framework, the analogue of the $n$-th derivative corresponds to the fractional derivative induced by the standard weight $\mu(r) = n(1 - r^2)^{n-1}$. In this case, $\frac{\widehat{\mu}(r)^p}{(1 - r)^2}$ is not a weight if and only if $p \leq \frac{1}{n}$. Therefore,  we rediscover in Theorem~\ref{th:schattendugintro}
 (as  particular cases and in certain sense) some of the results in \cite{AS,ASBergman,DuLiQu2022}.    
We also observe
that fixed $\mu \in \DDD$ and $p$ sufficiently large, Lemma~\ref{lemma: caract dcheck}~(ii) (below) ensures that there always exist non-trivial symbols $g$ such that $V_{\mu,g} \in S_p(A^2_\alpha)$.

Theorem~\ref{th:schattendugintro} follows from Theorem~\ref{th:schattendug} and Theorem~\ref{th:BpmuD} below. In Theorem~\ref{th:schattendug} it is proved that 
(i) and (ii) of  Theorem~\ref{th:schattendugintro} are equivalent. In fact, it is used  
the min-max theorem of eigenvalues for positive operators to connect the  singular value sequence of $ V_{\mu,g}$  with the  singular value sequence of a Toeplitz operator, and later on
a classical result due to H. Luecking \cite{Lu87} is employed to prove that (i) is equivalent to a discrete quantity equivalent to the $\| g\|^p_{ B_{p,\mu}}$. On the other hand, 
 Theorem~\ref{th:BpmuD} says that for any radial weight and $1<p<\infty$,
$B_p=B_{p,\mu}$ if and only $\frac{\mug(r)^p}{(1-r)^2}\in \DDD$, and the result remains true if  $0<p\le 1$ and $\mu\in \DD$. The proof Theorem~\ref{th:BpmuD} follows ideas from the proofs of  Theorem~\ref{th:main} and Theorem~\ref{th: caracterizacion BMOAmain} but a good number of extra obstacles have to be solved. In particular, different approaches are needed to deal with the cases $1<p<\infty$ and $0<p\le 1$. 




The rest of the paper is organized as follows. Section~\ref{s2} is devoted to prove some technical results on radial weights  and useful representation formulas for the fractional derivative. Theorem~\ref{th:main} is proved in Section~\ref{s3} and Theorem~\ref{th: caracterizacion BMOAmain} is proved in Section~\ref{s4}. 
Section~\ref{s5} contains  proofs of Theorem~\ref{th:Vmubounded} and  Theorem~\ref{th:Vmucompact}. A proof of Theorem~\ref{th:bergmanVmuboundedcompact} is given in 
Section~\ref{s6}. Section~\ref{s7} contains results about embeddings between the spaces   $B_p$ and $B_{p,\mu}$. Finally,   Theorem~\ref{th:schattendugintro} is proved in Section~\ref{s8}.

To this end a couple of words about the notation used. The letter $C=C(\cdot)$ will denote an absolute constant whose value depends on the parameters indicated in the parenthesis, and may change from one occurrence to another.
We will use the notation $a\lesssim b$ if there exists a constant
$C=C(\cdot)>0$ such that $a\le Cb$, and $a\gtrsim b$ is understood
in an analogous manner. In particular, if $a\lesssim b$ and
$a\gtrsim b$, then we write $a\asymp b$ and say that $a$ and $b$ are comparable.

	\section{Previous results}\label{s2}
\subsection{Background on radial weights}
	Throughout the manuscript we will employ different descriptions of the classes of radial weights
	$\DD$ and $\Dd$. The next result gathers several characterizations of $\DD$ proved in \cite[Lemma 2.1]{PelProcedings}. 
%We denote $\om_x=\int_0^1 s^x \omega(s)\,ds$, $x\ge 0$.
	\begin{letterlemma}\label{lemma: caract Dgorro}
		Let $\om$ be a radial weight. Then, the following statements are equivalent:
		\begin{itemize}
			\item[(i)] $\om\in\DD$;
			\item[(ii)] There exists a constant $C=C(\om)>0$ such that
			$$
			\om_x \leq C\omg\left (1-\frac{1}{x} \right),\quad x\geq 1;
			$$
			\item[(iii)] There exists a constant $C=C(\om)>0$ such that
			$$
			\om_x\leq C\om_{2x},\quad x\geq1.
			$$
		\end{itemize}
	\end{letterlemma}
	We will also use a couple of descriptions of the class $\Dd$.
% which are known for experts. 
%We include a proof for the sake of completeness.
	\begin{letterlemma}\label{lemma: caract dcheck}
		Let $\om$ be a radial weight. Then, the following statements are equivalent: 
		\begin{itemize}
			\item[(i)] $\om\in\Dd$;
			\item[(ii)] There exists $C=C(\om)>0$ and $\b=\b(\om)>0$ such that
			$$
			\omg(s)\leq C \left ( \frac{1-s}{1-t} \right )^\b \omg(t),\quad 0\leq t \leq s <1;
			$$
\item[(iii)] For each (equivalently for some) $\gamma>0$ there is $\eta_0=\eta_0(\gamma)< 1$ such that for any  $\eta_0<\eta\leq 1$ there is $C=C(\om,\gamma, \eta)>0$ such that
			$$
			\int_0^r \frac{ds}{\omg(s)^\gamma(1-s)^\eta} \leq \frac{C}{\omg(r)^\gamma(1-r)^{\eta-1}},\quad 0\leq r < 1.
			$$  
		\end{itemize}
	\end{letterlemma}
	\begin{proof}
		The equivalence between (i) and (ii) is proved in \cite[Lemma B]{PelRosa}.
  Let us prove that (ii)$\Rightarrow$(iii). Take $\g>0$ and choose $\eta_0=1-\b\gamma$. Then,  if $\eta_0<\eta\leq 1$
		$$
		\int_0^r\frac{ds}{\omg(s)^\gamma(1-s)^\eta} \leq C^\gamma \frac{(1-r)^{\gamma\b}}{\omg(r)^\gamma}\int_0^r\frac{ds}{(1-s)^{\eta+\gamma\b}} \leq \frac{C^\gamma}{\eta+\gamma\b-1}\frac{1}{\omg(r)^\gamma(1-r)^{\eta-1}},\quad 0\leq r < 1,
		$$
so (iii) holds with $C(\om,\gamma, \eta)=\frac{C^\gamma}{\eta+\gamma\b-1}$.

		Conversely assume that (iii) holds for some $\gamma>0$. Then,  
		$$
		\frac{C}{\omg(t)^\gamma} \geq \int_0^t \frac{ds}{\omg(s)^\gamma (1-s)} \geq \int_r^t \frac{ds}{\omg(s)^\gamma(1-s)} \geq \frac{1}{\omg(r)^\gamma}\log\frac{1-r}{1-t},\, 0\leq r<t <1,
		$$
where  $C=C(\om,\gamma, 1)=C(\om,\gamma)$.
		Take  $K>1$ and $t=1-\frac{1-r}{K}$, then it follows  that 
		$$
		\frac{C}{\omg\left( 1-\frac{1-r}{K}\right)^\gamma}\geq \frac{1}{\omg(r)^\gamma} \log K,$$
that is $$\omg(r)\ge \left(\frac{\log K}{C} \right)^{1/\gamma}\omg\left( 1-\frac{1-r}{K}\right), \quad 0\le r<1.$$
So, choosing $K>e^C$ we deduce that $\om\in\Dd$. This finishes the proof.

	\end{proof}
	\subsection{Reproducing formulas and useful identities}\label{subse:22}
The   Bergman reproducing kernel  induced by a radial weight $\om$, can be written as 
 $$B^\om_z(\z)=\sum \overline{e_n(z)}e_n(\z),\quad z,\z\in\D,$$   for any orthonormal basis $\{e_n\}$ of $A^2_\om$. Therefore 
 using the basis
 induced by the normalized monomials
\begin{equation}\label{eq:B}
B^\om_z(\z)=\sum_{n=0}^\infty\frac{\left(\overline{z}\z\right)^n}{2\om_{2n+1}}, \quad z,\z\in \D.
\end{equation}

Now let us consider an integral-derivative fractional operator which includes the fractional derivative $D^\mu$ as a particular case. Indeed, 
	for a pair of radial weights $\om$ and $\nu$ the  integral-derivative fractional operator
	$$
	R^{\om,\nu}(f)(z)=\sum_{n=0}^{\infty}\frac{\om_{2n+1}}{\nu_{2n+1}}\widehat{f}(n)z^n,\quad f\in\H(\D),
	$$
	was first introduced in \cite{PeralaFraccionaria}, and  a calculation shows (see \cite{PeralaFraccionaria,PeralaRattyaFraccionaria}) that
\begin{equation}\label{eq:mu+}
   D^\mu(f)(z) = R^{1,\mu_+}(f)(z),\quad f\in\H(\D),\quad z\in\D,
\end{equation}
where  $\mu_+(z)=\int_{\abs{z}}^1\frac{\mu(s)}{s}ds,\, z\in\D\setminus\{0\}$. Now, we recall the reader
the following integral representation of $R^{\om,\nu}$  \cite[(3.3)]{PeralaFraccionaria}.
	\begin{lettertheorem}\label{th:perala}
		Let $\om$ and $\nu$ be radial weights.  Then,
		$$
		R^{\om,\nu}(f)(z) = \int_{\D} f(\z)\overline{B^{\nu}_{z}(\z)}\om(\z)dA(\z),\quad f\in A^1_\om,\quad z\in\D.
		$$
	\end{lettertheorem}
	From the above integral representation we can obtain an alternative formula for $R^{\om,\nu}$ in terms of the $n$th-derivative of the function.  In order to obtain that expression we introduce the following concepts.
	For a radial weight $\nu$ we consider the iterated radial weights 
	$$
	V_{\nu,n}(z)= 2\int_{\abs{z}}^1 rV_{\nu,n-1}(r)dr,\quad z\in \D,\, n\in\N\quad \text{and} \quad V_{\nu,0}(z)=\nu(z),
	$$
	and for a radial weight $\om$ we consider
	$\om^\ast(z)=\int_{\abs{z}}^1s\om(s)\log\frac{s}{\abs{z}}ds$ for $z\in\D\setminus\{0\}$ and its iterations
	$$
	\om^{\ast,n}(z)=\int_{\abs{z}}^1s\om^{\ast,n-1}(s)\log\frac{s}{\abs{z}}ds,\quad z\in \D\setminus\{0\},n\in \N \quad \text{and} \quad \om^{\ast,0}(z)=\om(z).
	$$ 
	\begin{proposition}\label{prop: expresión derivada fraccionaria general}
		Let  be $\om$ and $\nu$ be radial weights. Then, 
		\begin{itemize}
		\item[(i)] If $x>0$ and $n\in\N$ then $(V_{\nu,n})_x = \frac{2(V_{\nu,n-1})_{x+2}}{x+1}$ and $(B^{\nu}_z)^{(n)}(\z) = \overline{z}^n B_z^{V_{\nu,n}}(\z)$ for every $z,\z\in\D$;
		\item[(ii)] If $x>0$ and $n\in \N$ then $(\om^{\ast,n})_x = \frac{(\om_{\ast,n-1})_{x+2}}{(x+1)^2}$;
		\item[(iii)] Let $f\in A^1_\om$  and $n\in\N$,  then
		\begin{equation*}
			\begin{split}
				R^{\om,\nu}(f)(z) &= 
%\frac{\om_1}{\nu_1}\widehat{f}(0) + 4\int_\D f'(\z)\overline{(B^\nu_z)'(\z)}\om^\ast(\z)dA(\z) \\
	%			&= \frac{\om_1}{\nu_1}\widehat{f}(0) + 4z\int_\D f'(\z)\overline{B^{V_\nu,1}_z(\z)}\om^{\ast,1}(\z)dA(\z) \\
%				&=
 \sum_{j=0}^{n-1}\frac{\om_{2j+1}}{\nu_{2j+1}}\widehat{f}(j)z^j + 4^nz^n\int_\D f^{(n)}(\z)\overline{B^{V_{\nu,n}}_z(\z)}\om^{\ast,n}(\z)dA(\z) \\
				&= \sum_{j=0}^{n-1}\frac{\om_{2j+1}}{\nu_{2j+1}}\widehat{f}(j)z^j + 4^nz^n R^{\om^{\ast,n},V_{\nu,n}}(f^{(n)})(z), \quad z\in\D.
			\end{split}
		\end{equation*}
		\end{itemize}
	\end{proposition}
	\begin{proof}
		The first equality  of (i) and (ii) can be obtained using  Fubini's theorem. To prove the second identity in (i), from the equality $(V_{\nu,n+1})_{2k+1}=\frac{(V_{\nu,n})_{2k+3}}{k+1}$ for every  $n,k\in \N\cup\{0\}$ we get
		$$
		(B^{V_{\nu,n}}_z)'(\z)=\overline{z} \sum_{k=0}^{\infty}\frac{(k+1)(\overline{z}\z)^k}{2(V_{\nu,n})_{2k+3}} = \overline{z}\sum_{k=0}^\infty \frac{(\overline{z}\z)^k}{2(V_{\nu,n+1})_{2k+1}}=\overline{z}B^{V_{\nu,n+1}}_z(\z),\quad z,\z\in\D,\quad n\in \N\cup\{0\}.
		$$
		From this identity we can prove the statement by induction. The case $n=1$ follows straightforward from the above identity with $n=0$. Next assume that $(B^{\nu}_z)^{(n)}(\z) = \overline{z}^n B^{V_{\nu,n}}_z(\z)$, for $n\in \N$. Then, 
		$$
		(B^\nu_z)^{(n+1)}(\z) = ((B^\nu_z)^{(n)})'(\z) = \overline{z}^n (B^{V_{\nu,n}}_z)'(\z) = \overline{z}^{n+1}B^{V_{\nu,n+1}}(\z),\quad z,\z\in\D.
		$$
Let us prove (iii).  Arguing as in the proof of \cite[(4.3)]{PR} for any $f,g\in \H(\D)$ such that $f\overline{g}\in L^1_\om$, we get
\begin{equation}\begin{split}\label{eq:j1}
\langle f,g \rangle_{A^2_\om} & =\int_{\D} f(\z)\overline{g(\z)}\, \om(\z)\,dA(\z)=\int_{\D} f(\z)\overline{g(\z)}\, \om^{\ast,0}(\z)\,dA(\z)
\\ & = \widehat{f}(0)\overline{\widehat{g}(0)}(\om^{\ast,0})_1+4\int_{\D} f'(\z)\overline{g'(\z)}\, \om^{\ast,1}(\z)\,dA(\z)
\\ & = \sum_{j=0}^{n-1} 4^j\widehat{f^{(j)}}(0)\overline{\widehat{g^{(j)}}(0)}(\om^{\ast,j})_1+4^n\int_{\D} f^{(n)}(\z)\overline{g^{(n)}(\z)}\, \om^{\ast,n}(\z)\,dA(\z).
\end{split}\end{equation}
So, taking $g=B^{\nu}_z$ and $f\in A^1_\om$, Theorem~\ref{th:perala}, the above identity and part (i) yield
\begin{equation}\begin{split}\label{eq:j2}
R^{\om,\nu}(f)(z) &= \langle f, B^{\nu}_z\rangle_{A^2_\om}
\\ & = \sum_{j=0}^{n-1} 4^j\widehat{f^{(j)}}(0)\overline{\widehat{(B^{\nu}_z)^{(j)}}(0)}(\om^{\ast,j})_1+4^n\int_{\D} f^{(n)}(\z)\overline{(B^{\nu}_z)^{(n)}(\z)}\, \om^{\ast,n}(\z)\,dA(\z)
\\ & =  \sum_{j=0}^{n-1} 4^j\widehat{f^{(j)}}(0)\overline{\widehat{(B^{\nu}_z)^{(j)}}(0)}(\om^{\ast,j})_1
 +4^nz^n R^{\om^{\ast,n},V_{\nu,n}}(f^{(n)})(z), \quad z\in\D.
\end{split}\end{equation}
Next, bearing in mind part (i)-(ii) it follows that
\begin{equation}\begin{split}\label{eq:j3}
\widehat{f^{(j)}}(0) &=j! \widehat{f}(j)
\\ (V_{\nu,j})_1 &=\frac{\nu_{2j+1}}{j!}
\\ \widehat{(B^{\nu}_z)^{(j)}}(0) & =\overline{z}^j\widehat{B^{V_{\nu,j}}_z}=\frac{\overline{z}^j}{ (V_{\nu,j})_1}=\frac{j! \overline{z}^j}{ \nu_{2j+1}}
\\ (\om^{\ast,j})_1 & = \frac{\om_{2j+1}}{4^j (j!)^2}.
\end{split}\end{equation}
Therefore, joining \eqref{eq:j2} and  \eqref{eq:j3} we prove (iii). This finishes the proof.

	%	Lastly, (iii) can be obtained by working in the same way as \cite[Proposition 6]{MorenoPelRosa} and applying the identities from (i) and (ii).
	\end{proof}


