		\section{Fractional derivative characterization of Hardy space}\label{s3}
We begin this section by proving the following inequality.

		\begin{theorem}\label{th: norma equivalente <}
	Let  $\mu$ be a radial weight and $0<p<\infty$. Then,
			\begin{equation}\label{eq: th1 enunciado}
				\nm{f}_{H^p}^p \lesssim \int_\T \left [ \int_{\Gamma(\xi)} \abs{D^\mu(f)(z)}^2 \left (\frac{\mug(z)}{1-\abs{z}}\right )^2 dA(z) \right ]^{\frac{p}{2}}\abs{d\xi},\quad f\in \H(\D).
			\end{equation}
		\end{theorem}
We will use the following three lemmas in the proof of Theorem~\ref{th: norma equivalente <}.

\begin{lemma}\label{le:a}
Let $0<p<\infty$, $n\in\N$ and $a>0$. Then, 
$$\nm{f}_{H^p}^p \asymp \sum_{j=0}^{n-1}\abs{f^{(j)}(0)}^p + \int_{\T} \left (\int_{\Gamma(\z)} |z|^{2a}\abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}dA(z) \right )^{\frac{p}{2}} \abs{d\z}, \quad  f\in\H(\D).$$
\end{lemma}
\begin{proof}
Since $M_p(r,g)$  is an increasing function of $r$ for any $g\in \H(\D)$, for any radial weight $\omega$
\begin{equation}\label{eq:j4}
\|g\|_{A^p_\om}\asymp \||z|^a g\|^p_{L^p_\om}, \quad  g\in\H(\D).
\end{equation}  
On the other hand, by 
\cite[Lemma~4]{arsenovic} %(see also \cite[Lemma~C]{PelPAMS2016}) 
there is $\lambda(p)=\lambda>0$ such that
\begin{equation*}\begin{split}
 & \int_{\T} \left (\int_{\Gamma(\z)} |z|^{2a}\abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}dA(z) \right )^{\frac{p}{2}} \abs{d\z}
\\ & \asymp \int_{\T} \left (\int_{\D} \left(\frac{1-|z|}{|1-\overline{\z}z|} \right)^{\lambda} |z|^{2a}\abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}\,dA(z) \right )^{\frac{p}{2}} \abs{d\z}, \quad  f\in\H(\D).
\end{split}\end{equation*}
So, by \eqref{eq:j4} with $g_\z(z)=\frac{f^{(n)}(z)}{(1-\overline{\z}z)^\lambda}$ and the radial weight $(1-\abs{z})^{2n-2+\lambda}$, and another application of  \cite[Lemma~4]{arsenovic} it follows that
\begin{equation*}\begin{split}
 & \int_{\T} \left (\int_{\Gamma(\z)} |z|^{2a}\abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}dA(z) \right )^{\frac{p}{2}} \abs{d\z}
\\ & \asymp \int_{\T} \left (\int_{\D} \left(\frac{1-|z|}{|1-\overline{\z}z|} \right)^{\lambda} |z|^{2a}\abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}\,dA(z) \right )^{\frac{p}{2}} \abs{d\z}
\\ & \asymp \int_{\T} \left (\int_{\D} \left(\frac{1-|z|}{|1-\overline{\z}z|} \right)^{\lambda} \abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}\,dA(z) \right )^{\frac{p}{2}} \abs{d\z}
\\ & \asymp \int_{\T} \left (\int_{\Gamma(\z)} \abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-2}dA(z) \right )^{\frac{p}{2}} \abs{d\z}, \quad  f\in\H(\D).
\end{split}\end{equation*}
This together with \eqref{eq: norma calderon} finishes the proof.
\end{proof}

Let us recall that, for any $0<p,q<\infty$ and $\nu$ a radial weight, the tent space $T_p^q(\nu)$ consists of complex-valued measurable functions $f$ on $\D$ such that 
	$$
	\|f\|_{T_{p}^{q}(\nu)}
	=  \left(\int_{\T}\left(\int_{\Gamma(\xi)}|f(z)|^p \nu(z)\frac{dA(z)}{1-|z|}\right)^{\frac{q}{p}}\,|d\xi|\right)^{\frac1q}<\infty.
$$
The next result follows from \cite[Lemma 3.1]{AguiMasPelRat}.
\begin{letterlemma}\label{le:b}
Let  $\om$ be a radial weight, $0<p<\infty$ and $n\in\N\cup\{0\}$. Then, 
 for any $0<r<1$  there is $C=C(n,p,\om,r)$ such that
\begin{equation}\label{eq:UC:ATp}
\sup_{|z|\le r}|f^{(n)}(z)|
\le C\|f\|_{AT^p_2(\om)},
\qquad f\in\H(\D).
\end{equation}
As a consequence, the convergence in $AT^p_2(\om)$ implies the uniform convergence on compacts subsets, and so $AT^p_2(\om)$ is a complete space.
\end{letterlemma}

Now, let us prove  following inequality which is a direct byproduct of  \cite[Lemma 2.5]{OrtegaFabrega}. 

\begin{letterlemma}\label{le:OAcase1}
Let $s>-1$, $r, t\ge 0$ such that $r+t-s> 2$. If $r-s<2$ and $t-s<2$, then  
$$\int_{\D}\frac{(1-|\z|)^s}{|1-\overline{\z}a|^r |1-\overline{\z}\xi|^t}\,dA(\z)\lesssim \frac{1}{ |1-\overline{a}\xi|^{t+r-s-2}}, \quad a\in \D, \xi\in \T.$$
\end{letterlemma}
\begin{proof}
By \cite[Lemma 2.5]{OrtegaFabrega} the above inequality is true whenever $a,\xi\in \D$. Therefore,
\begin{align*}
\int_{\D}\frac{(1-|\z|)^s}{|1-\overline{\z}a|^r |1-\overline{\z}\xi|^t}\,dA(\z) & = \int_{\D} \liminf_{\r\to 1^-}\frac{(1-|\z|)^s}{|1-\overline{\z}a|^r |1-\overline{\z}\r\xi|^t}\,dA(\z) 
\\ & \le \liminf_{\r\to 1^-}  \int_{\D} \frac{(1-|\z|)^s}{|1-\overline{\z}a|^r |1-\overline{\z}\textcolor{red}{\r}\xi|^t}\,dA(\z) 
\\ & \lesssim \liminf_{\r\to 1^-}\frac{1}{ |1-\overline{a}\r\xi|^{t+r-s-2}}=\frac{1}{ |1-\overline{a}\xi|^{t+r-s-2}},   \quad a\in \D, \xi\in \T.
\end{align*}
This finishes the proof.
\end{proof}


