If $x\geq1$ take $n\in \N$ such that $2n+1\leq x < 2n+3$.  Then,
	$$
	\int_0^1 \frac{\mug(r)^2}{1-r}r^xdr \leq \int_0^1 \frac{\mug(r)^2}{1-r}r^{2n+1}dr \lesssim \mu_{2n+1}^2 \lesssim \mu_{2n+3}^2\leq \mu_x^2,
	$$
where in the second to last inequality we have used that  there exists a constant $C(\mu)>0$ such that $\mu_x\leq C(\mu)\mu_{x+2}$ for every $x>0$. 
	Therefore,
	\begin{equation}\label{eq: th2 necesidad continuo}
		\int_0^1 \frac{\mug(r)^2}{1-r}r^xdr \lesssim \mu_x^2,\quad x\geq 1.
	\end{equation}
	So,  an integration by parts,  Hölder's inequality and \eqref{eq: th2 necesidad continuo} imply that
	\begin{equation*}
		\begin{split}
			\mu_{\frac{3x}{4}+1}^2 &\asymp x^2 \left (\int_0^1 \mug(r)r^{\frac{3x}{4}}dr\right )^2 
%= x^2 \left (\int_0^1 \mug(r)\frac{r^{\frac{x}{2}}}{(1-r)^{\frac{1}{2}}}(1-r)^{\frac{1}{2}}r^{\frac{x}{4}}dr\right )^2 \\
			\leq x^2 \left (\int_0^1\frac{\mug(r)^2}{1-r}r^xdr \right ) \left (\int_{0}^1 (1-r)r^{\frac{x}{2}}dr \right ) 
\\ & \asymp \int_0^1 \frac{\mug(r)^2}{1-r}r^xdr \lesssim \mu_x^2, \quad x\geq1.
		\end{split}
	\end{equation*}
	Consequently,
	%$$
	%\mu_x \lesssim \mu_{\frac{4x}{3}-\frac{4}{3}},\quad x\geq \frac{7}{4},
	%$$
%	and in fact to
	$
	\mu_x\lesssim \mu_{\frac{4x}{3}},\,x\geq,  \frac{7}{4}.
	$
	Next, three iterations of this inequality yield
	$$
	\mu_x \lesssim \mu_{\frac{4x}{3}} \lesssim \mu_{\frac{16x}{9}} \lesssim \mu_{\frac{64x}{27}} \leq \mu_{2x},\quad x\geq \frac{7}{4},
	$$
	so by Lemma~\ref{lemma: caract Dgorro} (iii) $\mu\in\DD$. \\
	Let us prove  that $\mu\in \Dd$. If $K>1$, 
	\begin{equation*}\begin{split}
			\int_0^1 r^{x} \frac{\widehat{\mu}(r)^2}{1-r}\,dr  \ge \int_{1-\frac{1}{x}}^{1-\frac{1}{Kx}} r^{x} \frac{\widehat{\mu}(r)^2}{1-r}\,dr
			 \ge C_1  \widehat{\mu}\left(1-\frac{1}{Kx}\right)^2\log K, \quad x\ge 2,
	\end{split}\end{equation*}
	where $C_1=\inf_{x\ge 2}\left( 1-\frac{1}{x}\right)^x>0$.
	The above inequality, together with \eqref{eq: th2 necesidad continuo}, the fact that $\mu\in \DD$ and Lemma~\ref{lemma: caract Dgorro}, implies that there is $C_2=C_2(\mu)>0$ such that
	\begin{equation*}\begin{split}
			C_1  \widehat{\mu}\left(1-\frac{1}{Kx}\right)^2\log K \le  \int_0^1 r^{x} \frac{\widehat{\mu}(r)^2}{1-r}\,dr 
			\le C_2 \widehat{\mu}\left(1-\frac{1}{x} \right) ^2, \quad x\ge 2.
	\end{split}\end{equation*}
	That is,
	$$\widehat{\mu}(r)\ge \left( \frac{C_1\log K}{C_2}\right)^{1/2}\widehat{\mu}\left(1 - \frac{1-r}{K}\right), \quad \frac{1}{2}\le r<1.$$
	So, choosing $\log K>\frac{C_2}{C_1}$, it follows that $\mu\in \Dd$, and consequently $\mu\in\DDD$.
	\end{proof}

