 As a byproduct of Fubini's theorem, Theorem~\ref{th: norma equivalente <} and Theorem~\ref{th: norma equivalente >} we obtain the following 
 Littlewood-Paley type inequalities for the Hardy space $H^2$.  
	\begin{corollary}\label{coro: H2}
		Let $\mu$ be a radial weight, then
$$
		\nm{f}_{H^2}^2 \lesssim \int_\D \abs{D^\mu(f)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\,dA(z),\quad f\in\H(\D).
		$$
Moreover, the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $\mu\in\DDD$;
\item[\rm(ii)] $$
		\nm{f}_{H^2}^2 \asymp \int_\D \abs{D^\mu(f)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\,dA(z),\quad f\in\H(\D);
		$$
\item[\rm(iii)]
		$$
		 \int_\D \abs{D^\mu(f)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\,dA(z)\lesssim \nm{f}_{H^2}^2,\quad f\in\H(\D).
		$$
\end{enumerate}
	\end{corollary}




\section{Fractional derivative characterization of BMOA and VMOA}\label{s4}

We will use some  well-known results. The first one follows from \cite[Lemmas 2.4 and 3.3]{BlascoJarchow} (see also \cite[Lemma~3.3 p. 231]{Garnett1981}).
\begin{letterlemma}\label{lemma: carleson nucleo}
	Let $\mu$ be a positive  Borel measure on $\D$. Then
\begin{enumerate}
\item[\rm(i)] For each
  $\lambda>0$, there exists positive constants $C_1=C_1(\lambda), C_2=C_2(\lambda)>0$ such that
	$$
	C_1\sup_{a\in\D} \frac{\mu(S(a))}{1-\abs{a}} \leq \sup_{a\in\D}\int_{\D} \frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}d\mu(z) \leq C_2 \sup_{a\in\D} \frac{\mu(S(a))}{1-\abs{a}};
	$$
\item[\rm(ii)] For each
  $\lambda>0$, $ \lim_{|a|\to 1^-} \int_{\D} \frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}d\mu(z)=0
	$ if and only if $$ \lim_{|a|\to 1^-} \frac{\mu(S(a))}{1-\abs{a}}=0.
	$$
\end{enumerate}
\end{letterlemma}


The second result is a particular case ($p=1$) of 
 \cite[Theorem 5]{AulaskariNowakZhao}.
\begin{lettertheorem}\label{th: derivada n-esima bmoa}
	Let $n\in\N$. 
\begin{enumerate}
\item[\rm(i)] 
 $f\in\BMOA$ if and only if $d\mu_{f,n}(z) = \abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-1}dA(z)$ is a classical Carleson measure. Moreover,
	$$
	\nm{f}_{\BMOA}^2\asymp \sum_{k=0}^{n-1} \abs{f^{(k)}(0)}^2 + \sup_{a\in\D} \frac{\int_{S(a)}\abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-1}dA(z)}{1-\abs{a}};
	$$
\item[\rm(ii)] 
 $f\in\VMOA$ if and only if $d\mu_{f,n}(z) = \abs{f^{(n)}(z)}^2(1-\abs{z})^{2n-1}dA(z)$ is a vanishing Carleson measure.
\end{enumerate}
\end{lettertheorem}

We are ready to prove the first main result of this section.


\begin{theorem}\label{th: caracterizacion BMOA <}
	Let $\mu$ be a radial weight. Then, 
	$$
	\nm{f}_{\BMOA} \lesssim \|f\|_{\BMOA_\mu},\quad f\in\H(\D).
	$$
Moreover,  $ \VMOA_\mu \subset \VMOA$.
\end{theorem}

\begin{proof}
	Let $f\in\H(\D)$ such that $d\mu_f(z)=\abs{D^\mu(f)(z)}^2\frac{\mug(z)^2}{1-\abs{z}}\,dA(z)$ is a classical Carleson measure.  
Then, by Lemma~\ref{lemma: carleson nucleo}  and Corollary~\ref{coro: H2} 
\begin{equation}\label{eq:A1}
\infty>\|f\|^2_{\BMOA_\mu}\gtrsim \int_\D \abs{D^\mu(f)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\,dA(z)\gtrsim \|f\|^2_{H^2}.
\end{equation}
 So, by Corollary~ \ref{prop: expresión derivada fraccionaria}
$$
	4^n z^n f^{(n)}(z) = R^{V_{\mu^+,n},W^n}(g)(z) - \sum_{j=0}^{n-1}\frac{(V_{\mu^+,n})_{2j+1}}{(W^n)_{2j+1}\mu_{2j+1}}\widehat{f}(j)z^j, \quad n\in\N,
	$$
where $g=D^\mu(f)$. Therefore, by Lemma~\ref{lemma: carleson nucleo} and Theorem~\ref{th: derivada n-esima bmoa}, for each $n\in\N$ and $\lambda>0$


	\begin{equation}\label{eq: desig lambda 1}
		\begin{split}
			\nm{f}_{\BMOA}^2 %&\asymp \sum_{k=0}^{n-1}\abs{f^{(k)}(0)}^2 + \sup_{a\in\D} \int_\D \abs{f^{(n)}(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z)\\
			&\asymp \sum_{k=0}^{n-1}\abs{f^{(k)}(0)}^2 + \sup_{a\in\D} \int_\D \abs{z^nf^{(n)}(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z)
\\ &\lesssim   \|f\|^2_{\BMOA_\mu} + \sup_{a\in\D} \int_\D \abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z) \\
			&+ \sup_{a\in\D} \int_\D \abs{\sum_{j=0}^{n-1}\frac{(V_{\mu^+,n})_{2j+1}}{(W^n)_{2j+1}\mu_{2j+1}}\widehat{f}(j)z^j}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z) \\
			&\lesssim \|f\|^2_{\BMOA_\mu} + \sup_{a\in\D} \int_\D \abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z).
		\end{split}
	\end{equation}
	Then, by Lemma~\ref{lemma: carleson nucleo} and Theorem~\ref{th: derivada n-esima bmoa} we just need to prove that  
	$$
	\sup_{a\in\D} \int_\D \abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z) \lesssim  \sup_{a\in\D}\int_{\D}\abs{g(z)}^2\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}\frac{\mug(z)^2}{1-\abs{z}}dA(z),
	$$
 for some $n\in\N$ and $\lambda>0$.
	Take now $n,N\in\N$ such that $1<N<2n+\frac{3}{2}$ and 
\begin{equation}\label{eq:parametersBMOA1}
	\e\in (-1,2n+1)\cap(2n +2-2N,4n+2-2N).
	\end{equation}
Observe that by Lemma~\ref{lema pesos tec} and \eqref{eq:A1}
\begin{equation*}\begin{split}
\|g\| _{A^1_{V_{\mu^+,n}}} &\lesssim \int_{\D} |g(z)| \mug(z)(1-|z|)^n\,dA(z)
\\ &
\lesssim \left(\int_\D \abs{D^\mu(f)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\,dA(z) \right)^{1/2}\left(\int_{\D} (1-\abs{z})^{2n+1}\,dA(z) \right)^{1/2}
\\ &\lesssim \left(\int_\D \abs{D^\mu(f)(z)}^2 \frac{\mug(z)^2}{1-\abs{z}}\,dA(z) \right)^{1/2}<\infty.
\end{split}\end{equation*}
So, we can apply Theorem~\ref{th:perala} and
	argue as in the proof of Theorem~\ref{th: norma equivalente <} to obtain \eqref{eq:A2}. That is, 
	$$
	\abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2 \lesssim \left (\int_\D\frac{\abs{g(\z)}^2}{\abs{1-\overline{z}\z}^{2N}}\mug(\z)^2dA_{2n-\e} \right )\frac{1}{(1-\abs{z})^{4n+2-2N-\e}},\quad z\in\D.
	$$
	Then if $0<\lambda<2N-2n+\e-2$, by Fubini's theorem,  \cite[Lemma 2.5]{OrtegaFabrega}, \eqref{eq:parametersBMOA1} and Lemma~\ref{lemma: carleson nucleo}
	\begin{equation}\label{eq: desig lambda 2}
		\begin{split}
			&\int_\D \abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z) \\
			&\lesssim \int_\D \frac{(1-\abs{z})^{2N+\e-2n-3}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}\left (\int_\D\frac{\abs{g(\z)}^2}{\abs{1-\overline{z}\z}^{2N}}\mug(\z)^2dA_{2n-\e}(\z) \right )dA(z) \\
			&= \int_\D \abs{g(\z)}^2 \mug(\z)^2(1-\abs{\z})^{2n-\e}(1-\abs{a})^\lambda \left (\int_\D\frac{(1-\abs{z})^{2N+\e-2n-3}}{\abs{1-\overline{a}z}^{\lambda+1}\abs{1-\overline{z}\z}^{2N}} dA(z)\right )dA(\z) \\
			&\lesssim 
%\int_\D \abs{g(\z)}^2 \mug(\z)^2(1-\abs{\z})^{2n-\e}(1-\abs{a})^\lambda \cdot \frac{1}{(1-\abs{\z})^{2n-\e+1}\abs{1-\overline{a}\z}^{\lambda+1}}dA(\z) \\
	%		&= 
\int_{\D}\abs{g(\z)}^2\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}\z}^{\lambda+1}}\frac{\mug(\z)^2}{1-\abs{\z}}dA(\z) \lesssim \|f\|^2_{\BMOA_\mu}, \quad a\in\D.
		\end{split}
	\end{equation}
	This finishes the proof of the first part of the theorem.
\par Now assume that $f\in \VMOA_\mu$, and in particular  $f\in \BMOA_\mu$.
% and consequently by first part of the theorem $f\in BMOA$. 
On the rest of the proof we keep the notation, the choice of the paremeters   and the estimates obtained in the first part of the proof.
 Therefore, 

\begin{equation}\begin{split}\label{eq:vmoa1}
& \int_\D \abs{f^{(n)}(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z)
\\ & \lesssim  \int_\D \abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z) 
\\ &			+  \int_\D \abs{\sum_{j=0}^{n-1}\frac{(V_{\mu^+,n})_{2j+1}}{(W^n)_{2j+1}\mu_{2j+1}}\widehat{f}(j)z^j}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z), \quad a\in \D. 
\end{split}\end{equation}
Moreover, on the one hand
\begin{equation}\begin{split}\label{eq:vmoa2}
& \lim_{|a|\to 1^-}\int_\D \abs{\sum_{j=0}^{n-1}\frac{(V_{\mu^+,n})_{2j+1}}{(W^n)_{2j+1}\mu_{2j+1}}\widehat{f}(j)z^j}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z)
\\ & \lesssim  \lim_{|a|\to 1^-} \|f\|^2_{\BMOA,\mu} \int_\D \frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z)=0.
\end{split}\end{equation}
On the other hand, bearing in mind Lemma~\ref{lemma: carleson nucleo}(ii)
\begin{equation}\begin{split}\label{eq:vmoa3}
& \lim_{|a|\to 1^-} \int_\D \abs{R^{V_{\mu^+,n},W^n}(g)(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z) 
\\ & \lesssim  \lim_{|a|\to 1^-} \int_{\D}\abs{g(\z)}^2\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}\z}^{\lambda+1}}\frac{\mug(\z)^2}{1-\abs{\z}}dA(\z) =0.
\end{split}\end{equation}
Consequently, joining \eqref{eq:vmoa1},  \eqref{eq:vmoa2} and \eqref{eq:vmoa3} it follows that
$$   \lim_{|a|\to 1^-} \int_\D \abs{f^{(n)}(z)}^2\frac{(1-\abs{z})^{2n-1}(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}dA(z)=0.$$
So, by  Theorem~\ref{th: derivada n-esima bmoa}(ii), $f\in \VMOA$. This finishes the proof.
\end{proof}

\begin{theorem}\label{th: caracterizacion BMOA >}
	Let $\mu$ be a radial weight. Then, the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $\mu\in\DDD$;
\item[\rm(ii)] $\BMOA\subset  {\BMOA_\mu}$ and
	\begin{equation}\label{eq:BMOA >}
	\|f\|_{\BMOA_\mu}\lesssim \nm{f}_{\BMOA},\quad f\in\H(\D);
	\end{equation}
\item[\rm(iii)] $\VMOA\subset  {\VMOA_\mu}$ and
	\begin{equation}\label{eq:VMOA >}
	\|f\|_{\BMOA_\mu}\lesssim \nm{f}_{\BMOA},\quad f\in VMOA.
	\end{equation}
\end{enumerate}
\end{theorem}
\begin{proof}
	Assume that $\mu\in\DDD$ and $f\in\BMOA$. Then,  Corollary~\ref{prop: expresión derivada fraccionaria}  and the argument  in the proof of Theorem~\ref{th: norma equivalente >} imply that 
	$$
	\abs{D^\mu(f)(z)}^2 \lesssim \nm{f}_{\BMOA}^2 + \left (\int_\D \abs{f^{(n)}(\z)}\abs{B^{V_{\mu_+,n}}_z(\z)}(1-\abs{\z})^{2n}dA(\z) \right )^2,\quad n\in\N,  z\in\D.
	$$
	Take $n\in\N\setminus\{1\},N\in\N$  such that $$n+\frac{1}{2}<N<n+\frac{3}{2}+\frac{1}{2}\min\{2\b,1-\eta\},$$ where $\b>0$ comes from Lemma~\ref{lemma: caract dcheck} (ii) and  $\eta<1$ from Lemma~\ref{lemma: caract dcheck} (iii) with $\gamma=2$.
	Next, choose $\e$ such that
	\begin{equation}\label{eq:parametersBMOA2}
		\e\in \left(0, 2n+1 \right)\bigcap \left(2N -2 -\min\{2\b,1-\eta\}, 2N-2 \right).
	\end{equation}
	Then,    following  the proof of Theorem~\ref{th: norma equivalente >} we get \eqref{eq:A3}. Therefore, 
	\begin{equation}
	\abs{D^\mu(f)(z)}^2\lesssim \nm{f}_{\BMOA}^2 + \left (\int_\D \frac{\abs{f^{(n)}(\z)}^2}{\abs{1-\overline{z}\z}^{2N}}dA_{2n+\e}(\z) \right)\cdot\frac{1}{\mug(z)^2(1-\abs{z})^{2-2N+\e}},\quad z\in\D.
	\end{equation}
	 Then for any $a\in\D$ and $\lambda>0$ 
	\begin{equation*}
		\begin{split}
			&\int_\D\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}\abs{D^\mu(f)(z)}^2\frac{\mug(z)^2}{1-\abs{z}}dA(z) 
\lesssim \nm{f}_{\BMOA}^2 \int_\D \frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}\frac{\mug(z)^2}{1-\abs{z}}dA(z) \\
			&+ \int_\D \frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}(1-\abs{z})^{3-2N+\e}}\left (\int_\D \frac{\abs{f^{(n)}(\z)}^2}{\abs{1-\overline{z}\z}^{2N}}dA_{2n+\e}(\z) \right)dA(z) = I(f,a) + II(f,a).
		\end{split}
	\end{equation*}
	By Lemma~\ref{lemma: caract dcheck} (ii) 
	\begin{equation*}
			\int_\D \frac{\mug(z)^2}{1-\abs{z}}\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}{z}}^{\lambda+1}}dA(z) \lesssim  \int_0^1 \frac{\mug(s)^2}{1-s}\frac{(1-\overline{a})^\lambda}{(1-\abs{a}s)^\lambda}ds \leq  \int_0^1 \frac{\mug(s)^2}{1-s}ds <\infty,
	\end{equation*}
	so $\sup_{a\in \D}I(f,a)\lesssim \nm{f}_{\BMOA}^2$. 
	Now take $0<\lambda<2N-2-\e$. Then by Fubini's Theorem, \cite[Lemma 2.5]{OrtegaFabrega}, \eqref{eq:parametersBMOA2}, Lemma~\ref{lemma: carleson nucleo} and Theorem~\ref{th: derivada n-esima bmoa}
	\begin{equation*}
		\begin{split}
			II(f,a) &= (1-\abs{a})^\lambda\int_\D \abs{f^{(n)}(\z)}^2(1-\abs{\z})^{2n+\e}\left (\int_\D \frac{(1-\abs{z})^{2N-3-\e}}{\abs{1-\overline{z}\z}^{2N}\abs{1-\overline{a}z}^{\lambda+1}}dA(z) \right)dA(\z) \\
			&\asymp 
%\int_\D \abs{f^{(n)}(\z)}^2 \frac{(1-\abs{a})^{\lambda}(1-\abs{\z})^{2n+\e}}{\abs{1-\overline{a}\z}^{\lambda+1}(1-\abs{\z})^{\e+1}}dA(\z) \\
%			&=
 \int_\D \abs{f^{(n)}(\z)}^2 (1-\abs{\z})^{2n-1}\frac{(1-\abs{a})^{\lambda}}{\abs{1-\overline{a}\z}^{\lambda+1}}dA(\z) \lesssim \nm{f}_{\BMOA}^2.
		\end{split}
	\end{equation*}
	Then, by Lemma~\ref{lemma: carleson nucleo}(i), statement (ii) holds.



Now assume that  $\mu\in\DDD$ and $f\in\VMOA$. Then arguing as in the proof of (i)$\Rightarrow$(ii),  keeping the notation and the choice of the paremeters, it follows that
\begin{equation*}
		\begin{split}
			\int_\D\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}\abs{D^\mu(f)(z)}^2\frac{\mug(z)^2}{1-\abs{z}}dA(z) \lesssim  I(f,a) + II(f,a), \quad a\in \D. 
\end{split}
	\end{equation*}
Now, since $\frac{\mug(z)^2}{1-\abs{z}}$ is radial weight,   $\frac{\mug(z)^2}{1-\abs{z}}\, dA(z)$ is a vanishing Carleson measure. So bearing in mind Lemma~\ref{lemma: carleson nucleo}(ii), 
$  \lim_{|a|\to 1^-}I(f,a)=0.$
Moreover,  by Lemma~\ref{th: derivada n-esima bmoa}(ii)
$$ \lim_{|a|\to 1^-}II(f,a)\lesssim  \lim_{|a|\to 1^-} \int_\D \abs{f^{(n)}(\z)}^2 (1-\abs{\z})^{2n-1}\frac{(1-\abs{a})^{\lambda}}{\abs{1-\overline{a}\z}^{\lambda+1}}dA(\z) = 0.$$
So, $ \lim_{|a|\to 1^-} \int_\D\frac{(1-\abs{a})^\lambda}{\abs{1-\overline{a}z}^{\lambda+1}}\abs{D^\mu(f)(z)}^2\frac{\mug(z)^2}{1-\abs{z}}dA(z)=0$, and  by Lemma~\ref{lemma: carleson nucleo}(ii), statement (iii) holds.

Reciprocally, assume  that \eqref{eq:BMOA >} holds and let us prove that $\mu\in\DDD$.
	By chosing  $f(z)=z^n$ in  \eqref{eq:BMOA >} we get
	 the inequality
	$$
	\int_\D \frac{\abs{z^{2n}}}{\mu_{2n+1}^2}\frac{\mug(z)^2}{1-\abs{z}}\,dA(z) \lesssim \nm{z^n}_{\BMOA}^2= 1,\quad n\in\N .
	$$
	Therefore, we obtain the inequality \eqref{eq: th2 necesidad discreto} which implies $\mu\in\DDD$ by the proof of Theorem~\ref{th: norma equivalente >}. Consequently (i)$\Leftrightarrow$(ii). 
