\section{Fractional Volterra-type operator acting on classical  Bergman space.}\label{s6}
In order to prove the main results of the next sections we recall some elementary facts from the hyperbolic geometry of the unit disc. Let 
$\rho(z,w) %=|\varphi_z(w)|
=\left|\frac{z-w}{1-\overline{z}w}\right|,\, z,w\in\D,$ be 
 the  pseudohyperbolic metric of $\D$, and
$$\beta(z,w)=\frac{1}{2}\log\frac{1+\rho(z,w)}{1-\rho(z,w)},\qquad z,w\in\D,$$
 the hyperbolic metric of $\D$. We denote
 $\displaystyle{D(z,r)= \{w\in\D:  \beta(z,w)<r\}}$,   $z\in \D$, $r>0$. It is  well known, see \cite[Proposition 4.5]{Zhu}, that for any $z\in \D$ and $r>0$, there exist constants $C_1,C_2,C_3$, depending on $r$, such that
\begin{align}
	\frac{1}{C_1}|1-\overline{w}a|&\leq |1-\overline{w}z|\leq C_1|1-\overline{w}a|\,,\qquad w\in \D,\,a\in D(z,r),\nonumber\\
	\frac{1}{C_2}(1-|w|^2)&\leq 1-|z|^2\leq C_2(1-|w|^2)\,,\qquad w\in D(z,r),\label{geometric hyperbolic estimates}\\
	C_3|D(z,r)|&\leq (1-|z|^2)^2\leq C_3|D(z,r)|,\nonumber
\end{align}
where $|D(z,r)|$ denotes the Lebesgue area of the set $D(z,r)$. The estimates of the form \eqref{geometric hyperbolic estimates} will be used repeatedly in the the proofs of the next results and
will be called hyperbolic estimates. The next result can be found in
%Lastly, we recover the following characterization of the Carleson measures for $A^p_\a$ 
\cite[Theorem 7.4 and 7.7]{Zhu}.
% see \cite{hastings},\cite{PRS}.

\begin{lettertheorem}\label{th: carleson standard}
	Let $0<p<\infty$, $\a>-1$ and $\mu$ be a positive Borel measure on $\D$. Then,
	\begin{enumerate}
		\item[\rm(i)]
		$I: A^p_\a\to  L^p(\mu)$ is bounded 
		if and only if for all (some) $0<r<1$
		$$
		\sup_{a\in\D} \frac{\mu\left (D(a,r) \right )}{(1-\abs{a})^{2+\a}} <\infty.
		$$
		Moreover, $$\|I\|^p_{A^p_\a\to L^p(\mu) }\asymp \sup_{a\in\D} \frac{\mu\left (D(a,r) \right )}{(1-\abs{a})^{2+\a}};$$
		\item[\rm(ii)]
		$I: A^p_\a\to  L^p(\mu)$ is compact 
		if and only if for all (some) $0<r<1$
		$$
		\lim_{\abs{a}\to 1^-} \frac{\mu\left (D(a,r) \right )}{(1-\abs{a})^{2+\a}}=0.
		$$ 
	\end{enumerate}
\end{lettertheorem}
\begin{proposition}\label{propo: bloch fraccionaria}
