	$$\sup_{a\in\D}\frac{\int_{D(a,r)}\abs{D^\mu g(z)}^p\mug(z)^p(1-\abs{z})^{\a}dA(z)}{(1-\abs{a})^{\a+2}}<\infty,$$
Moreover, $$\| g\|^p_{\B}\asymp \sup_{a\in\D}\frac{\int_{D(a,r)}\abs{D^\mu g(z)}^p\mug(z)^p(1-\abs{z})^{\a}dA(z)}{(1-\abs{a})^{\a+2}}.$$
