	$$\lim_{\abs{a}\to1^-}\frac{\int_{D(a,r)}\abs{D^\mu g(z)}^p\mug(z)^p(1-\abs{z})^{\a}dA(z)}{(1-\abs{a})^{\a+2}}=0.$$
	\end{itemize}
\end{proposition}
