\section{Fractional derivative description of Besov spaces.} \label{s7}

Aiming to prove Theorem~\ref{th:schattendugintro} we will obtain fractional derivative description of classical Besov spaces which are  of its own interest. Despite the fact that the proof uses ideas previously employed to show Theorems \ref{th:main} and \ref{th: caracterizacion BMOAmain},
it contains a good number of technicalities due to the nature of $B_p$ spaces $0<p<\infty$.
%In order to prove the main results of this section we prove the following lemma. \\

\begin{lemma}\label{le:qp}
Let $\eta$ be a radial weight  and $0<p\le q<\infty$. Then,
$$ \|f\|_{A^q_{\nu(q,p)}}\lesssim \|f\|_{A^p_\eta}, \quad f \in \H(\D),$$
where $\nu(q,p)(|z|)=\eta(|z|)\left( \widehat{\eta}\left(\frac{1+|z|}{2}\right)(1-|z|)\right)^{\frac{q-p}{p}}.$
\end{lemma}
\begin{proof}
Joining the inequality $M_p(r,f)\le \frac{\|f\|_{A^p_\eta}}{\widehat{\eta}(r)^\frac{1}{p}}, 0\le r<1$, with the inequality
$$M_\infty(r,f)\le C_p \frac{M_p(s,f)}{(s-r)^{ \frac{1}{p}}}, \quad 0\le r<s<1,$$
it follows that
\begin{equation*}\begin{split}
M_\infty(r,f)\le C_p \frac{M_p\left(\frac{1+r}{2},f \right)}{(1-r)^{ \frac{1}{p}}}\le C_p 
\frac{\|f\|_{A^p_\eta}}{ \left( (1-r)\widehat{\eta}\left( \frac{1+r}{2} \right)\right)^\frac{1}{p} },
%\lesssim \frac{\|f\|_{A^p_\eta}}{\left( (1-r) \widehat{\eta}(r) \right)^\frac{1}{p} }, 
\quad 0\le r<1.
\end{split}\end{equation*}
Therefore,
\begin{equation*}\begin{split}
\|f\|^q_{A^q_{\nu(q,p)}} &=\int_{\D} |f(z)|^p |f(z)|^{q-p} \eta(|z|)\left( \widehat{\eta}\left(\frac{1+|z|}{2}\right)(1-|z|)\right)^{\frac{q-p}{p}}\, dA(z)
\\ & \lesssim \|f\|^{q-p}_{A^p_{\eta}}\int_{\D} |f(z)|^p \eta(z) \, dA(z)=\|f\|^q_{A^p_\eta}, \quad f \in \H(\D).
\end{split}\end{equation*}
This finishes the proof.
\end{proof}

