 \| f\|^p_{B_p} & \lesssim  \| f\|^p_{B_{p,\mu}} + 
 \int_{\D}\left| R^{V_{\mu^+,n},W^n}(g)(u) \right|^p(1-|u|)^{pn-2} \,dA(u).
\\ & \lesssim  \| f\|^p_{B_{p,\mu}} + 
 \int_{\D}\left (\int_\D \abs{g(\z)}\abs{B^{W^n}_u(\z)}\mug(\z)(1-\abs{\z})^{n}dA(\z) \right )^p (1-|u|)^{pn-2} \,dA(u).
\end{split}\end{equation}
If $p=1$, using  that $\widehat{W^n}(r)\asymp (1-r)^{2n+1}$ by Lemma~\ref{lema pesos tec},  $W^n, (1-|u|)^{pn-2}\in \DDD$,  and  \cite[Theorem~1]{PR2016/1}, it follows that
\begin{equation*}\begin{split}
 \| f\|_{B_1}
& \lesssim \| f\|_{B_{1,\mu}}+ \int_\D \abs{g(\z)}\mug(\z)(1-\abs{\z})^{n}\int_{\D} \abs{B^{W^n}_u(\z)} (1-|u|)^{n-2} \,dA(u) \, dA(\z)  
\\ & \asymp \| f\|_{B_{1,\mu}}+\int_\D \abs{g(\z)}\mug(\z)(1-\abs{\z})^{n} \left(1+\int_0^{|\z|} \frac{dt}{(1-t)^{n+3}} \right) \, dA(\z)  
\\ & \asymp \| f\|_{B_{1,\mu}}, \quad f \in \H(\D).
\end{split}\end{equation*}
Next if $0<p<1$ and $\mu\in \DD$,  take $\eta(s)=\mug(s)^p(1-s)^{(n+2)p-2}$. Then $\eta \in \DDD$ and  
\begin{equation*}\begin{split}
\eta(|\z|)\left( \widehat{\eta}\left(\frac{1+|\z|}{2}\right)(1-|\z|)\right)^{\frac{1-p}{p}}
& \asymp 
\eta(|\z|)\left( \widehat{\eta}\left(|\z|\right)(1-|\z|)\right)^{\frac{1-p}{p}}
\\ & \asymp \mug(\z)(1-\abs{\z})^{n}, \z\in \D.
\end{split}\end{equation*}
So by \eqref{eq:bpmurad1},  Lemma~\ref{le:qp}  and \cite[Theorem~1]{PR2016/1},  and bearing in mind that $np>2-2p$
\begin{equation*}\begin{split}
 \| f\|^p_{B_p} & \lesssim  \| f\|^p_{B_{p,\mu}} + 
 \int_{\D} \int_\D \abs{g(\z)}^p\abs{B^{W^n}_u(\z)}^p\mug(\z)^p(1-\abs{\z})^{np+2p-2} \,dA(\z)  (1-|u|)^{pn-2} \,dA(u)
\\ & =   \| f\|^p_{B_{p,\mu}} +  \int_\D \abs{g(\z)}^p\mug(\z)^p (1-\abs{\z})^{np+2p-2}\int_{\D} \abs{B^{W^n}_u(\z)}^p (1-|u|)^{pn-2} \,dA(u) \, dA(\z) 
\\ & \asymp \| f\|^p_{B_{p,\mu}} +  \int_\D \abs{g(\z)}^p\mug(\z)^p (1-\abs{\z})^{np+2p-2} 
\left(1+\int_0^{|\z|} \frac{dt}{(1-t)^{np+2p+1}} \right) \, dA(\z) 
\\ & \asymp \| f\|^p_{B_{p,\mu}},  \quad f \in \H(\D).
\end{split}\end{equation*}
This finishes the proof.
\end{proof}

\begin{theorem}\label{th:BpmuD}
 Let  $1\le p<\infty$ and $\mu$ be  a radial weight. Then, the following conditions are equivalent:
\begin{enumerate}
\item[\rm(i)] $\frac{\widehat{\mu}(z)^p}{(1-|z|)^2} \in \mathcal{D}$;  
\item[\rm(ii)] \begin{equation}\label{eq:bpmuds}
	 \|g\|_{B_{p,\mu}} \asymp \|g\|_{B_p},\quad g \in\mathcal{H}(\mathbb{D}).
	\end{equation}
\item[\rm(iii)] $$
	 \|g\|_{B_{p,\mu}} \lesssim \|{g}\|_{B_p},\quad g\in\mathcal{H}(\mathbb{D});
	$$
\end{enumerate}
Moreover, if $0<p\le 1$ and $\mu\in \DD$, the previous three conditions are also equivalent.
\end{theorem}
It is also worth mentioning that the proof of Theorem~\ref{th:BpmuD} reveals that   (i) implies (ii) for any radial weight and $0<p\le 1$. 


\begin{proof}


Assume that (i) holds. In order to prove (ii) we will split the proof in several steps.

{\bf{First step.}} Let us prove that $\mu\in \DD$. 

The class $\DDD$ is closed under multiplication by weights of the form $(1-s)^\beta$, $\beta>0$. Therefore choosing $\beta=2$ it follows that $\widehat{\mu}^p\in \DDD$, and in particular 
$\widehat{\mu}^p\in \DD$. Now bearing in mind the identity $\om_x=x(\omg)_{x-1}, x\ge 1$, and  Lemma~\ref{lemma: caract Dgorro},  it follows  that a radial weight $\om\in\DD$ if and only if $\omg\in\DD$.
Therefore, the radial weight $ p\mu(z)\widehat{\mu}(z)^{p-1}\in \DD$, which is equivalent to the fact that $\mu\in \DD$.

{\bf{Second step.}} Let us prove that 
\begin{equation}\label{eq:bpmud1}
\int_{r}^1 \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds \asymp \frac{\widehat{\mu}(r)^p}{1-r}, \quad 0\le r<1.
\end{equation} 
Since $\mu\in\DD$, 
$$  \int_{r}^1 \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds\ge \int_{r}^{\frac{1+r}2} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds
%\ge %\frac{\widehat{\mu}\left(\frac{1+r}{2}\right)^p}{1-r}
\gtrsim  \frac{\widehat{\mu}(r)^p}{1-r}, \quad 0\le r<1.
$$
On the other hand since $\frac{\widehat{\mu}(z)^p}{(1-|z|)^2} \in \Dd$, by \cite[Lemma B]{PelRosa} there is $K>1$ and $C>0$ such that
\begin{equation*}\begin{split}
C \int_{r}^1 \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds \le \int_{r}^{1-\frac{1-r}{K}} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds\le  (K-1)\frac{\widehat{\mu}(r)^p}{1-r},
\end{split}\end{equation*}
and therefore \eqref{eq:bpmud1} holds.

{\bf{Third step.}} Let us prove that  $\mu\in \Dd$. 

By Lemma~\ref{lemma: caract dcheck} (ii) and \eqref{eq:bpmud1}
 there is $\b>0$ and $C>0$ such that
$$ \frac{\widehat{\mu}(s)^p}{(1-s)^{1+\beta}}\le C \frac{\widehat{\mu}(t)^p}{(1-t)^{1+\beta}}, \quad 0\le t\le s<1.$$
Therefore
$$ \int_0^s \frac{dt}{\widehat{\mu}(t)^p(1-t)}\le C \frac{(1-s)^{1+\beta}}{\widehat{\mu}(s)^p} \int_0^s \frac{dt}{(1-t)^{2+\beta}}\lesssim \frac{1}{\widehat{\mu}(s)^p}, \quad 0\le s<1, $$
which together with  a new application of Lemma~\ref{lemma: caract dcheck}  implies that $\mu\in \Dd$.


{\bf{Fourth step.}} Let us prove the identity \eqref{eq:bpmuds}. Fix $n\in\N$ such that $np>1$. Since $\mu$, $(1-|z|)^{np-2}$ and $\frac{\widehat{\mu}(z)^p}{(1-|z|)^2}$ are radial doubling weights, by \cite[Theorem~1]{PelRosa}, \cite[Theorem~5]{PR19} and
the indentity 
\begin{equation}\label{eq:F}
D^\mu(F_n)(z)=z^n(D^\mu(f))^{(n)}(z), \quad  F_n(\zeta)=\zeta^n f^{(n)}(\z),\, z, \z\in \D,\quad n\in \N,
\end{equation}
it follows that
%\begin{equation*}\begin{split}
%\|f\|_{B_p}^p  &\asymp |f(0)|^p+ \int_{\D} |F_1(z)|^p(1-|z|)^{p-2}\,dA(z)
%\\ & \asymp |f(0)|^p + \int_{\D} |D^\mu(F_1)(z)|^p \widehat{\mu}^p(z) (1-|z|)^{p-2}\,dA(z)
%\\ & = |f(0)|^p+ \int_{\D} |z|^p |(D^\mu(f))'(z)|^p \widehat{\mu}^p(z) (1-|z|)^{p-2}\,dA(z)
%\\ & \asymp |f(0)|^p+ \int_{\D}  |(D^\mu(f))'(z)|^p \widehat{\mu}^p(z) (1-|z|)^{p-2}\,dA(z)
%\\ & \asymp  \|f\|_{B_{p,\mu}}^p
%\end{split}\end{equation*}
\begin{equation*}\begin{split}
\|f\|_{B_p}^p  &\asymp \sum_{j=0}^{n-1}|f^{(j)}(0)|^p+ \int_{\D} |F_n(z)|^p(1-|z|)^{np-2}\,dA(z)
\\ & \asymp \sum_{j=0}^{n-1}|f^{(j)}(0)|^p + \int_{\D} |D^\mu(F_n)(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & = \sum_{j=0}^{n-1}|f^{(j)}(0)|^p+ \int_{\D} |z|^{np} |(D^\mu(f))^{(n)}(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & \asymp \sum_{j=0}^{n-1}|f^{(j)}(0)|^p + \int_{\D}  |(D^\mu(f))^{(n)}(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & \asymp  \|f\|_{B_{p,\mu}}^p.
\end{split}\end{equation*}

Now let us prove (ii)$\Rightarrow(i)$. 


{\bf{First step.}} Let us prove that $\mu\in \DD$ if $1<p<\infty$.

By choosing $f(z)=z^n$ in \eqref{eq:bpmuds}, it follows that 
$$ \int_0^1 s^{np+1} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds \lesssim n (\mu_{2n+1})^p, \quad n\in \N\cup\{0\},$$
and therefore
\begin{equation}\label{eq:bpmud4}
\int_0^1 s^{x} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds \lesssim x (\mu_{\frac{2x}{p}})^p, \quad x\ge 1.
\end{equation}
So for any $t\in (0,1)$ 
\begin{equation*}\begin{split}
(\mu_x)^p & \asymp x^p (\widehat{\mu}_x)^p
\\ & \le   x^p \int_0^1 s^{tpx} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds \left(  \int_0^1 s^{(1-t)p'x} (1-s)^{\frac{2p'}{p}}\,ds \right)^{\frac{p}{p'}}
\\ & \asymp x^{-1} \int_0^1 s^{tpx} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds
\lesssim (\mu_{2tx})^p,\quad  x\ge 1.
\end{split}\end{equation*}
Therefore, taking $t=3/4$ and iterating the obtained inequality
$$\mu_x\lesssim \mu_{\frac{3x}{2}}\lesssim  \mu_{\frac{9x}{4}}\le \mu_{2x}, \quad  x\ge 1,$$
so $\mu\in \DD$ by Lemma~\ref{lemma: caract Dgorro}.

{\bf{Second step.}} Let us prove that $\mu\in \Dd$. If $K>1$, 
\begin{equation*}\begin{split}
\int_0^1 s^{x} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds & \ge \int_{1-\frac{1}{x}}^{1-\frac{1}{Kx}} s^{x} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds
 \ge C_1  \widehat{\mu}\left(1-\frac{1}{Kx}\right)^p(K-1)x, \quad x\ge 2,
\end{split}\end{equation*}
where $C_1=\inf_{x\ge 2}\left( 1-\frac{1}{x}\right)^x>0$.
The above inequality, together with \eqref{eq:bpmud4}, the fact that $\mu\in \DD$ and Lemma~\ref{lemma: caract Dgorro}, implies that there is $C_2=C_2(\mu)>0$ such that
\begin{equation*}\begin{split}
C_1  \widehat{\mu}\left(1-\frac{1}{Kx}\right)^p(K-1)x &\le  \int_0^1 s^{x} \frac{\widehat{\mu}(s)^p}{(1-s)^2}\,ds 
 \le C_2 x \widehat{\mu}\left(1-\frac{1}{x} \right) ^p, \quad x\ge 2.
\end{split}\end{equation*}
That is,
$$\widehat{\mu}(s)\ge \left( \frac{(K-1)C_1}{C_2}\right)^{1/p}\widehat{\mu}\left(1 - \frac{1-s}{K}\right), \quad \frac{1}{2}\le s<1.$$
So, choosing $K>\frac{C_2}{C_1}+1$, it follows that $\mu\in \Dd$.

{\bf{Third step.}} Let us prove that  $\frac{\widehat{\mu}(z)^p}{(1-|z|)^2}\in \DDD$. 

Fix $n\in \N$ such that $np>1$.  Since $\mu$ and $(1-|z|)^{np-2}$ are radial doubling weights, by \eqref{eq:F},  \cite[Theorem~1]{PelRosa} and  \eqref{eq:bpmuds}
\begin{equation*}\begin{split}
&\sum_{j=0}^{n-1}|(D^\mu(f))^{(j)}(0)|^p+ \int_{\D}  |(D^\mu(f))^{(n)}(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & \asymp  \sum_{j=0}^{n-1}|f^{(j)}(0)|^p+ \int_{\D} |z|^{np} |(D^\mu(f))^{(n)}(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & = \sum_{j=0}^{n-1}|f^{(j)}(0)|^p + \int_{\D} |D^\mu(F_n)(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & \asymp \sum_{j=0}^{n-1}|f^{(j)}(0)|^p+ \int_{\D} |F_n(z)|^p(1-|z|)^{np-2}\,dA(z)
\\ & \asymp \|f\|_{B_p}^p 
 \asymp \int_{\D}  |D^\mu(f)(z)|^p \widehat{\mu}^p(z) (1-|z|)^{-2}\,dA(z),\quad f\in \H(\D).
\end{split}\end{equation*}
That is, 
\begin{equation*}\begin{split}
& \sum_{j=0}^{n-1}|g^{(j)}(0)|^p+ \int_{\D}  |g^{(n)}(z)|^p \widehat{\mu}^p(z) (1-|z|)^{np-2}\,dA(z)
\\ & \asymp
 \int_{\D}  |g(z)|^p \widehat{\mu}^p(z) (1-|z|)^{-2}\,dA(z),\quad g\in \H(\D).
\end{split}\end{equation*}
So, by \cite[Theorem~5]{PR19} $\frac{\widehat{\mu}(z)^p}{(1-|z|)^2}\in \DDD$. 

