\section{Schatten p-classes of Fractional Volterra-type operator.}\label{s8}
Throughout this section we shall use the notation $A^2_{-1}=H^2$ and $dA_{-1}(z)=\frac{dA(z)}{1-|z|^2}$.
We recall that a  sequence $\{z_\lambda\}_\lambda\subset \D$ is called $r$-hyperbolically  separated if there exists  a constant $r>0$ such that $\beta(z_k,z_\lambda)\geq r $ for $k\neq\lambda$, while is said to be an $r$-lattice in the hyperbolic distance, if it is $r/2$-separated and  
$$\mathbb{D} = \bigcup_k D(z_k, r).$$
 Now let us recall some results on singular values and  Schatten classes which will be used in the proofs of our 
results. In fact, 
a characterization of the singular values is given by the Rayleigh's equation. Let $n\in\N$, and $\lambda_n(T)$ be the $n$-th singular value of the positive operator $T$. Then,
\begin{equation}\label{Min-Max Theorem}
    \lambda_{n+1}=\min_{x_1,\dots,x_n}\max\{\langle Tx,x\rangle\colon \|x\|=1, x\perp x_i, 1\leq i\leq n\}\,. 
\end{equation}
A proof of this result can be found in \cite[Ch. X.4.3]{DS}.
On the other hand, the Spectral Mapping theorem imply that the condition $T\in S^p(\mm{H})$ is equivalent to $T^*T\in S^{\frac{p}{2}}(\mm{H})$ and
\begin{equation}\label{equation T*T norm}
    \|T\|_p^p=\|T^*T\|_{S^{p/2}}^{p/2}\,
\end{equation}
see \cite[Theorem~1.26]{Zhu}.




\begin{theorem}\label{th:schattendug}
Let $\mu\in \DDD$, $\alpha\ge -1$, $0<p<\infty$ and $g\in \H(\D)$. Then,
\begin{enumerate}
\item[\rm(i)] If $\int_0^1 \frac{\mug(r)^p}{(1-r)^2}\,dr=+\infty$, then $V_{\mu,g}\in S_p(A^2_\alpha)$ if and only if $g=0$.
 \item[\rm(ii)] If $\frac{\mug(r)^p}{(1-r)^2}$ is a radial weight, then $V_{\mu,g}\in S_p(A^2_\alpha)$ if and only if $g\in B_{p,\mu}$, and
$$\| V_{\mu,g}\|_{S_p(A^2_\alpha)}\asymp \|g\|_{B_{p,\mu}}.$$
\end{enumerate}
\end{theorem}
\begin{proof} 
If $g\in B_{p,\mu}$, 
by Theorem~\ref{th:BpmuD} $g\in B_{p}$ and therefore  $g\in \VMOA$ \cite[Lemma 10.13]{Zhu} and by Theorem~\ref{th: caracterizacion BMOAmain} if $\a=-1$, Proposition~\ref{propo: bloch fraccionaria} if $\a>-1$,  $|D^\mu(g)(z)|^2 \widehat{\mu}(z)^2 dA_\alpha(z)$ is a Carleson measure for $A^2_\alpha$. On the other hand,
if $V_{\mu,g}\in S_p(A^2_\alpha)$, then $V_{\mu,g}$ is bounded on $A^2_\alpha$  and by Theorem~\ref{th:Vmubounded} if $\a=-1$, Theorem~\ref{th:bergmanVmuboundedcompact} if $\a>-1$, $|D^\mu(g)(z)|^2 \widehat{\mu}(z)^2 dA_\alpha(z)$ is a Carleson measure for $A^2_\alpha$.
\par So,  we may assume that $|D^\mu(g)(z)|^2 \widehat{\mu}(z)^2 dA_\alpha(z)$ is a Carleson measure for $A^2_\alpha$. Let $\{z_j\}_j\subset \D$ be an $r$-lattice on $\D$. We wiil prove that
\begin{equation}\label{eq 1}
 %   V_{\mu,g}\in S^p(A^2_\alpha) &\iff \sum_{\lambda=1}^{\infty}\left(\frac{1}{(1-|z_\lambda|^2)^2}\int_{D(z_\lambda,r)}|D^\mu(g)(z)|^2\widehat{\mu}(z)^2dA(z)%\right)^{p/2}<\infty, \quad \text{and}
\| V_{\mu,g}\|^p_{S_p(A^2_\alpha)}\asymp \sum_{\lambda=1}^{\infty}\left(\frac{1}{(1-|z_\lambda|^2)^2}\int_{D(z_\lambda,r)}|D^\mu(g)(z)|^2\widehat{\mu}(z)^2dA(z)\right)^{p/2}.
\end{equation}
First of all, we define the  sesquilinear form
$$\mathcal{V}_g(f,h):=\int_{\D}f(z)\overline{h(z)}|D^\mu(g)(z)|^2 \widehat{\mu}(z)^2 dA_\alpha(z).$$

Since $|D^\mu(g)(z)|^2 \widehat{\mu}(z)^2 dA_\alpha(z)$ is a Carleson measure for $A^2_\alpha$, 
\begin{align*}
    |\mathcal{V}_g(f,h)|^2&=\left|\int_{\D}f(z)D^\mu(g)(z)\overline{h(z)D^\mu(g)(z)}\widehat{\mu}(z)^2 dA_\alpha(z)\right|^2\\
    &\leq \int_{\D}|f(z)|^2|D^\mu(g)(z)|^2\widehat{\mu}(z)^2 dA_\alpha(z) \int_{\D}|h(z)|^2|D^\mu(g)(z)|^2\widehat{\mu}(z)^2 dA_\alpha(z)\\
    &\lesssim \|f\|_{A^2_\alpha}^2\|h\|_{A^2_\alpha}^2\,, \quad f,h\in A^2_\alpha.
\end{align*}
That is $\mathcal{V}_g$ is a bounded sesquilinear form on $A^2_\alpha\times A^2_\alpha$.
By  Riesz representation theorem  there exists an operator $\mathcal{V}_g\colon A^2_\alpha\to A^2_\alpha$, (we denote it as the sesquilinear form) such that
$$\langle \mathcal{V}_g(f),h\rangle_{A^2_\alpha} =\mathcal{V}_g(f,h)\qquad f,h\in A^2_\alpha\,.$$
Based on the definition, it is easy to see that $\mathcal{V}_g(f,f)\geq 0$ and consequently, $ \mathcal{V}_g$ is a positive operator. Moreover by Theorem~\ref{th:main} if $\a=-1$, \cite[Theorem 1]{PelRosa} if $\a>-1$, for every $f\in A^2_\alpha$, we have that
\begin{align*}
    \langle \mathcal{V}_g(f),f\rangle_{A^2_\alpha} &=\int_{\D}|f(z)|^2 |D^\mu(g)(z)|^2\widehat{\mu}(z)^2 dA_\alpha(z) \asymp \|V_{\mu,g}(f)\|_{A^2_\alpha}^2=\langle (V_{\mu,g})^*V_{\mu,g}(f),f\rangle_{A^2_\alpha} .
\end{align*}
Thus, there exist two constants $C_1,C_2$ depending on $\mu$, such that
$$C_1\langle (V_{\mu,g})^*V_{\mu,g}(f),f\rangle_{A^2_\alpha} \leq \langle \mathcal{V}_g(f),f\rangle_{A^2_\alpha} \leq C_2\langle (V_{\mu,g})^*V_{\mu,g}(f),f\rangle_{A^2_\alpha} 
\qquad f\in A^2_\alpha \,.$$
An application of min-max theorem of eigenvalues of positive operators and the fact that $\|V_{\mu,g}\|_{S^p}^p=\| (V_{\mu,g})^*V_{\mu,g}\|_{S^{p/2}}^{p/2}$ imply that
$$V_{\mu,g}\in S^p(A^2_\alpha)\iff \mathcal{V}_g\in S^{p/2}(A^2_\alpha)$$
and the corresponding Schatten norms are comparable with constants depending only on $\mu$.

%\par  We verify that $V_g$ is a Toeplitz type operator, see Luecking \cite{LUECKINGtraceidealcriteriatoeplitz}, with measure $\mu_g(z)=|D^\mu(g)(z)|^2\frac{\widehat{\mu}%(z)^2}{(1-|z|)}dA(z)$. In fact,
Next, let is observe that if $B^\alpha_z$ is the reproducing kernel of $A^2_\alpha$, we have that
\begin{align*}
    \mathcal{V}_g(f)(z)&=\langle \mathcal{V}_g(f), B^\alpha_z\rangle_{A^2_\alpha}\\
    &= \mathcal{V}_g(f,B^\alpha_z)\\
    &= \int_{\D}f(w)|D^\mu(g)(w)|^2\overline{ B^\alpha_z(w)}\widehat{\mu}(z)^2 dA_\alpha(z)\\
    &=\int_{\D}f(w)\frac{1}{(1-\overline{w}z)^{2+\alpha}}d\mu_g(z)\\
    &= T_{\mu_g}(f)(z)\,,
\end{align*}
that is $ \mathcal{V}_g$ is nothing else but the Toeplitz operator induced by the measure  $d\mu_{g,\alpha}(z)=|D^\mu(g)(z)|^2 \widehat{\mu}(z)^2 dA_\alpha(z) $. Therefore, by \cite[Theorem p. 347]{Lu87} and the finite overlapping property of the hyperbolic discs $D(z_j,r)$ of a $r$-lattice $\{z_j\}_{j=1}^\infty$ (see \cite[Lemma~4.7]{Zhu}) it follows that
%$$V_g\in S^{p/2}(H^2)\iff \sum_{j=1}^{\infty}\left(\frac{\mu_{g,\alpha}(D(z_j,r))}{(1-|z_j|^{2+\alpha})}\right)^{p/2}<\infty\,,$$
$$\|\mathcal{V}_g\|^{p/2}_{S^{p/2}(A^2_\alpha)}\asymp  \sum_{j=1}^{\infty}\left(\frac{\mu_{g,\alpha}(D(z_j,r))}{(1-|z_j|^{2+\alpha}}\right)^{p/2}$$
for any $r$-lattice $\{z_j\}_{j=1}^\infty$ .
Since
