\section{Declipping and unlimited sampling for general distributions}\label{sec:general-results}

In this section, we shall prove the first four main results of this manuscript, dealing mainly with the questions of \emph{general} conditions such that random vectors satisfy stable recovery in the contexts of declipping and unlimited sampling. 

\subsection{Declipping for general distributions} We start the discussion of this section with a proof of our first main result for general distributions.

\begin{proof}[Proof of Theorem \ref{General distributions}] We divide our proof into two main cases: 

\vspace{1mm}

\noindent\textbf{Case 1:} Suppose that 
\begin{equation}\label{eq:prob-strips} 
\inf_{u,v \in \S^{n-1}} \mathbb{P}(|\langle X,u\rangle| \le \lambda, |\langle X,v\rangle| \le \lambda) \ge c'(\lambda). 
\end{equation} 
That is, the unclipped vectors are ``non-negligible''. Let then $$\mathcal{E}^1(u,v) = \left\{ |\langle X,u \rangle| \le \lambda \, \cap \, |\langle X,v\rangle| \le \lambda \right\} \cap \left\{ \left| \left\langle X, \frac{u-v}{\|u-v\|}\right\rangle \right| \ge \theta \right\}.$$ Notice that 
\begin{equation*}
\begin{split}
&\inf_{u,v \in\S^{n-1}}\frac{1}{m}\sum_{j=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_j,u\rangle) - \Phi_{\lambda}(\langle X_j,v\rangle)\right|^2 \\
&\ge \theta^2 \inf_{u,v \in\S^{n-1}}\mathbb{P}(\mathcal{E}^1(u,v)) - \theta^2 \sup_{u,v\in\S^{n-1}}\left(\mathbb{P}(\mathcal{E}^1(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j^1(u,v))\right).
\end{split}
\end{equation*}
Since we assume that $X$ satisfies a small ball condition such as \eqref{eq:small-ball-og}, we can guarantee that, by making $\theta > 0$ sufficiently small, we have, for any $u,v \in \B_{\R^n}$,
\[
\mathbb{P}(\mathcal{E}^1(u,v)) \ge \frac{1}{2}\mathbb{P}\left(|\langle X,u\rangle| \le \lambda, |\langle X,v\rangle| \le \lambda \right).
\]
It then suffices to note that the class 
\[
\mathcal{F}_{\lambda,\theta} = \left\{ \mathds{1}\left( |\langle x,u\rangle| \le \lambda \, \cap |\langle x, v \rangle| \le \lambda \, \cap |\langle x,w \rangle| \ge \theta\right), \, \, u,v \in \B_{\R^n}, \, w \in \S^{n-1} \right\}
\]
has VC-dimension $vc(\mathcal{F}_{\lambda,\theta}) \lesssim n$, as a consequence of Proposition \ref{prop:intersection} applied twice. It then follows from Proposition \ref{prop:bounded-differences} that 
\begin{align*} 
 & \sup_{u,v\in\S^{n-1}}\left(\mathbb{P}(\mathcal{E}^1(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j^1(u,v))\right)  \cr 
\le & \, \mathbb{E} \sup_{u,v\in\S^{n-1}}\left(\mathbb{P}(\mathcal{E}^1(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j^1(u,v))\right) + t 
\end{align*} 
with probability at least $1 - e^{-2t^2 m}$. By Lemma \ref{lem:VC_half-spaces}, we have that 
\[
\mathbb{E} \sup_{u,v\in\S^{n-1}}\left(\mathbb{P}(\mathcal{E}^1(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j^1(u,v))\right) \lesssim \sqrt{\frac{n}{m}}.
\]
By choosing $t \sim_{\lambda} \sqrt{\frac{n}{m}}$ and $m \ge \tilde{c}(\lambda) n,$ where $\tilde{c}(\lambda)$ depends only on \eqref{eq:prob-strips}, we get that
\[
\inf_{u,v \in\S^{n-1}}\frac{1}{m}\sum_{j=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_j,u\rangle) - \Phi_{\lambda}(\langle X_j,v\rangle)\right|^2 \ge c'(\lambda)^2,
\]
with probability at least $1 - e^{- \frac{m}{\tilde{c}(\lambda)}},$ as desired. 

\vspace{2mm}

\noindent \textbf{Case 2:} Suppose now, on the other hand, that \eqref{eq:prob-strips} does not admit a uniform lower bound and fix a  $\delta > 0.$ Consider the following events
\[
\mathcal{E}^3(u,v) = \left( |\langle X,u\rangle| \le \delta, |\langle X,v\rangle| > \lambda\right),
\]
\[
\mathcal{E}^4(u,v) = \left( |\langle X,u\rangle| \le \delta, |\langle X,v\rangle| \le \lambda\right),
\]
which satisfy that
$$\mathbb{P}(\mathcal{E}^3(u,v) \cup \mathcal{E}^4(u,v)) = \mathbb{P}(|\langle X,u\rangle| \le \delta).$$
Fix now $\delta = \frac{\lambda}{2}.$ Under the hypothesis of \eqref{eq:reverse-small-ball}, we conclude that there is $\tilde{c}(\lambda)$ such that 
\[
\inf_{u \in \S^{n-1}} \mathbb{P}(|\langle X,u\rangle| \le \lambda/2) \ge \tilde{c}(\lambda).
\]
We then divide into cases once more. 

\vspace{2mm}

\noindent \textit{Case 2.1:} $(u,v) \in \left\{ (u_0,v_0) \colon \mathbb{P}(\mathcal{E}^4(u_0,v_0)) \ge \frac{\tilde{c}(\lambda)}{2}\right\}.$ \medskip

In this case, we simply note that the exact same strategy as devised above for \textbf{Case 1} may be applied verbatim, and hence we need not deal with this case in particular. 

\vspace{2mm}

\noindent\textit{Case 2.2:} $(u,v) \in \left\{ (u_0,v_0) \colon \mathbb{P}(\mathcal{E}^4(u_0,v_0)) \le \frac{\tilde{c}(\lambda)}{2}\right\}.$ \medskip

Since $\mathcal{E}^3(u,v)$ and $\mathcal{E}^4(u,v)$ are disjoint, if the probability of, say, $\mathcal{E}^4(u,v)$ is less than $\tilde{c}(\lambda)/2,$ then 
\[
\mathbb{P}(\mathcal{E}^3(u,v)) \ge \frac{\tilde{c}(\lambda)}{2}. 
\]
In this case, instead of restricting to the set of unclipped samples, we simply restrict to the set where one of the measurements is clipped and the other one is far from being clipped. Indeed, we have
\begin{equation*}
\begin{split}
&\frac{1}{m}\sum_{j=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)\right|^2 \\
&\ge \frac{1}{\|u-v\|_2^2} \frac{\lambda^2}{4m} \sum_{j=1}^m \mathds{1}\left(|\langle X_i,u\rangle| > \lambda \cap |\langle X_i,v\rangle|\le \lambda/2 \right) \\ 
& \ge \frac{\lambda^2}{16m} \sum_{j=1}^m \mathds{1}\left(|\langle X_i,u\rangle| > \lambda \cap |\langle X_i,v\rangle|\le \lambda/2 \right). 
\end{split}
\end{equation*}
We then employ Lemma \ref{lem:VC_half-spaces} once more. This yields that the difference between the empirical process above and its expected value -- which is $\mathbb{P}(\mathcal{E}^3(u,v)) \ge \frac{\tilde{c}(\lambda)}{2}$ -- is at most $O(\sqrt{n/m})$ with probability $1 - e^{-c n}$, and we conclude the result also in this case. 
\end{proof}

\begin{remark}

Condition \eqref{eq:reverse-small-ball} states, as previously implied, a ``reverse'' small ball property: while the probability that $|\langle X,u\rangle|$ is not very small gets (uniformly) progressively closer to $1$, it also stays uniformly away from $1$. In other words, this is a sort of assertion on the roundness of the probability distribution of the vector $X$. 

While this, at first, seems to be an overly restrictive assumption, it is not hard to believe that such a condition should be in some sense \emph{necessary} in case declipping does hold. Indeed, if not, then \eqref{eq:reverse-small-ball} states that, for some specific vectors, most measurement will end up being clipped, and as such too much information should be lost. We refer the reader to Remark \ref{rmk:rsb-needed} below for a formal proof of the fact that \eqref{eq:reverse-small-ball} is indeed \emph{necessary} for stable declipping. We also refer the reader to Remark \ref{rmk:ssb-sharp?} for a discussion on the condition \eqref{eq:small-ball-og}. 
\end{remark} 

\subsection{Exact characterization of declipping for some \texorpdfstring{$\lambda$}{}} We move now to the proof of Theorem \ref{thm:general-some-lambda}. 

\begin{proof}[Proof of Theorem \ref{thm:general-some-lambda}]
Suppose first that assertion (I) in Theorem \ref{thm:general-some-lambda} holds. By \cite[Theorem 2.1]{Stablephaseretrieval} we have a dichotomy: Either  $E$ contains an almost disjoint normalized sequence, or the $L^1$ and $L^p$ norms are equivalent on $E$. Hence, if assertion (II) fails, we can find a sequence $(f_n)\subseteq S_E$ together with a sequence $\{d_n\}_n$ of pairwise disjointly supported functions such that $\|f_n-d_n\|_{L^p(\mu)}\to 0.$ In particular, as $\mu(\text{supp}(d_n)) \to 0$, it follows that $f_n$ converges to zero in measure. This implies that for each $\lambda>0$, $\|\Phi_{\lambda}(f_n)\|_{L^p}\to 0$, contradicting (I).
\medskip

Now, suppose that assertion (II) in Theorem \ref{thm:general-some-lambda} holds, but assertion (I) of Theorem \ref{thm:general-some-lambda} fails. Then for each $n\in \mathbb{N}$ we may find $f_{n}, g_{n}\in B_E$ with
\begin{equation}\label{fails clip for all n}
\|f_{n}-g_{n}\|_{L^p}>n \|\Phi_n(f)-\Phi_n(g)\|_{L^p}.
\end{equation}
Let $\Omega_n$ be the event where $\{|f_n|\  \text{and} \ |g_n|<n\}$. Since $f_n,g_n\in B_E$, we have $\mu(\Omega_n)\geq 1-\frac{2}{n^p}.$
On the other hand, by \eqref{fails clip for all n}, we have 
\begin{equation*}
\|f_n|_{\Omega_n}-g_n|_{\Omega_n}\|_{L^p}<\frac{\|f_n-g_n\|_{L^p}}{n}.
\end{equation*}
Hence,
\begin{equation*}
\|f_n-g_n\|^p_{L^p}\left(1-\frac{1}{n^p}\right)\leq \|(f_n-g_n)|_{\Omega_n^c}\|_{L^p}^p.
\end{equation*}
This shows that $f_n-g_n$ accumulates most of its mass on a set of very small measure. In particular,
$$\|f_n-g_n\|_{L^1}=\int_{\Omega_n} |\Phi_n(f)-\Phi_n(g)|+\int_{\Omega_n^c} |f_n-g_n|$$

$$< \frac{\|f_n-g_n\|_{L^p}}{n}+\|f_n-g_n\|_{L^p}\mu(\Omega_n^c)^{1/p'}$$

$$\leq \left(\frac{1}{n}+\left(\frac{2}{n^p}\right)^{\frac{1}{p'}}\right)\|f_n-g_n\|_{L^p}.$$
This shows that assertion (II) fails, a contradiction which concludes the proof. 
\end{proof}

\begin{remark}\label{rmk:ssb-sharp?} We have characterized exactly when a distribution $\mu$ satisfies declipping for \emph{some} $\lambda >0.$ However, we note that the strong small ball condition \eqref{eq:small-ball-og} is \emph{not} necessary in order for declipping to hold in the continuous setting for \emph{all} $\lambda>0$: take, for instance, $\mu$ to be a probability distribution that gives $1/2$ weight to a single fixed point $p_0$ in the sphere $\sqrt{n} \S^{n-1}$, and the other half to the rest of the sphere, attributed in a uniform way. Take $X$ to be a random variable distributed according to this distribution. This random vector clearly does not satisfy \eqref{eq:small-ball-og}, but since a random vector $Y$ which is uniformly distributed on the sphere $\sqrt{n} \S^{n-1}$ satisfies that, for all $u,v \in \B_{\R^n}$,
\begin{equation}\label{eq:continuous-dec}
    \mathbb{E} \left( \Phi_\lambda(\langle Y,u \rangle) - \Phi_\lambda (\langle Y,v\rangle)\right)^2 \ge c(\lambda)\|u-v\|_2^2,
\end{equation}
for some constant $c(\lambda)>0,$ then $X$ must satisfy the same kind of inequality, showing the asserted fact that \eqref{eq:small-ball-og} is not needed in order for declipping to hold. 

One may wonder, however, if a weaker version is needed in order for declipping to hold: namely, does it hold that if a probability measure $\mu$ is such that any random vector $X$  distributed according to $\mu$ satisfies \eqref{eq:continuous-dec}, then we may write $\mu = \mu_1 + \mu_2$, where $\mu_1$ and $\mu_2$ have disjoint supports, and at least one of them satisfies \eqref{eq:small-ball-og}?

Perhaps surprisingly, the next result shows that even this weaker form is \emph{not} needed in order for \eqref{eq:continuous-dec} to hold:
\begin{proposition}\label{prop:double-sphere-ex} Let $\S^{n-2}_i:=\S^{n-1}\cap \{x_i =0\}$. Take $\mu = \frac{c_n}{2} \left( \mathcal{H}^{n-2}|_{\sqrt{n}\S^{n-2}_1} +  \mathcal{H}^{n-2}|_{\sqrt{n}\S^{n-2}_2} \right),$ where the constant $c_n>0$ is chosen so that $\mu$ is a probability measure. If $X$ is a random vector distributed according to $\mu,$ then it satisfies \eqref{eq:continuous-dec}, although $X$ does not satisfy \eqref{eq:small-ball-og}. 
\end{proposition}

\begin{proof} Let $u,v \in \B_{\R^n}$ be fixed. Let then $u_i,v_i$ denote the respective projections of $u,v$ onto the planes $\{x_i = 0\}, i=1,2.$ We first note that, directly by the way we have defined the spaces we are working on, it follows that 
\[
\|u_1 - v_1 \|_2^2 + \|u_2 - v_2 \|_2^2 \ge \| u-v\|_2^2. 
\]
Now, let $Y_1,Y_2$ denote random variables, each distributed uniformly on $\sqrt{n}\S^{n-1}_i$, respectively. Since 
\[
\langle Y_i,u\rangle =\langle Y_i, u_i\rangle, \quad \langle Y_i,v\rangle =\langle Y_i,v_i\rangle,
\]
it follows that 
\[
\mathbb{E} \left( \Phi_\lambda(\langle Y_i,u \rangle) - \Phi_\lambda (\langle Y_i,v\rangle)\right)^2 \ge c(\lambda)\|u_i-v_i\|_2^2,
\]
where we used the fact that the uniform distribution on the sphere of radius $\sqrt{n}$ satisfies \eqref{eq:continuous-dec}. Now, since we may write 
$$X = \varepsilon_0 \cdot Y_1 + (1-\varepsilon_0)\cdot Y_2,$$ 
where $\varepsilon_0$ is a Bernoulli $1/2$-random variable independent of $Y_i,i=1,2,$ 
it follows that 
\begin{align*}
\mathbb{E} \left( \Phi_\lambda(\langle X,u \rangle) - \Phi_\lambda (\langle X,v\rangle)\right)^2 & = \frac{1}{2} \left(\mathbb{E} \left( \Phi_\lambda(\langle Y_1,u \rangle) - \Phi_\lambda (\langle Y_1,v\rangle)\right)^2 + \mathbb{E} \left( \Phi_\lambda(\langle Y_2,u \rangle) - \Phi_\lambda (\langle Y_2,v\rangle)\right)^2 \right) \cr
& \ge \frac{c(\lambda)}{2} \left( \|u_1 - v_1 \|_2^2 + \|u_2 - v_2 \|_2^2 \right) \ge \frac{c(\lambda)}{2} \|u-v\|_2^2.
\end{align*}
Since it is easy to see that $X$ does not satisfy \eqref{eq:small-ball-og}, this finishes the proof of the proposition. 
\end{proof}

The question of what condition characterizes doing stable $\lambda$-declipping for all $\lambda$ seems to be an interesting one. On the one hand, the reverse small ball condition \eqref{eq:reverse-small-ball} is necessary, and Theorem \ref{thm:general-some-lambda} implies that the weak small ball (rewritten in the statement of that result as the equivalence of $L^1$ and $L^2$ norms) is also necessary. On the other hand, by virtue of the examples above, a complete characterization seems to be more elusive than the current techniques, being a problem we wish to investigate further in future work. 
\end{remark}

%Natural questions: What is the relation between stable $\lambda$-declipping in $L^1$ versus in $L^p$?  Can we get discrete analogues of this result in $\ell^2$ or $\mathbb{R}^n$?

\subsection{General declipping in the sparse context} 


\begin{proof}[Proof of Theorem \ref{thm:sparse-gen-dist}]

We follow exactly the same method of proof as in Theorem \ref{General distributions}. Indeed, by repeating the first few steps, we obtain in the exact same manner that

\begin{equation*}
\begin{split}
&\inf_{u,v \in T_s}\frac{1}{m}\sum_{j=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_j,u\rangle) - \Phi_{\lambda}(\langle X_j,v\rangle)\right|^2 \\
&\ge L^2 \inf_{u,v \in T_s}\mathbb{P}(\mathcal{E}(u,v)) - L^2 \sup_{u,v\in T_s}\left(\mathbb{P}(\mathcal{E}(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j(u,v))\right),
\end{split}
\end{equation*}
where the event $\mathcal{E}(u,v)$ is defined in \eqref{eq:event-E(u,v)}. Since we have already proved a lower bound on the probability of that event for arbitrary $u,v \in \B_{\R^n}$, we only need to estimate the term 
\[
\sup_{u,v\in T_s}\left(\mathbb{P}(\mathcal{E}(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j(u,v))\right).
\]
We again repeat the overarching structure of the proof of Theorem \ref{General distributions}: again by Proposition \ref{prop:bounded-differences}, we obtain for all $t>0$ with probability at least $1-e^{-2t^2m}$ that
\begin{equation*}
\begin{split}
&\sup_{u,v\in T_s}\left(\mathbb{P}(\mathcal{E}(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j(u,v))\right) \\
&\le \mathbb{E} \sup_{u,v\in T_s}\left(\mathbb{P}(\mathcal{E}(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j(u,v))\right) + t.\\
\end{split}
\end{equation*}
Our main divergence point is the usage of Proposition \ref{prop:union-vc}: indeed, by using that result, we get that any family of the form 
\[
\F_\lessgtr = \left\{ \mathds{1}\left(|\langle x,u\rangle| \lessgtr \theta \right) \colon u \in T_s \right\}
\]
satisfies $vc(\F_\lessgtr) \lesssim s \log(e \cdot n/s).$ This follows, for instance, by combining Proposition \ref{prop:union-vc} with the fact that $T_s$ is the union of ${n \choose s}$ Euclidean balls of dimension $s$. By using Proposition \ref{prop:intersection} twice, we obtain that the VC-dimension of the class 
\[
\tilde{\F}_{\lambda,\theta}\coloneqq\left\{ \mathds{1}\left( |\langle x,u\rangle| \le \lambda \, \cap |\langle x, v \rangle| \le \lambda \, \cap |\langle x,w \rangle| \ge \theta\right), \, \, u,v \in \B_{\R^n}\cap T_s, \, w \in \S^{n-1}\cap T_s \right\},
\]
satisfies $vc(\tilde{\F}_{\lambda,\theta}) \lesssim s \log(e \cdot n/s).$ Applying now Proposition \ref{prop:vc-quantif-lln}, we have 
\[
\mathbb{E} \sup_{u,v\in T_s}\left(\mathbb{P}(\mathcal{E}(u,v))-\frac{1}{m}\sum_{j=1}^m\mathds{1}(\mathcal{E}_j(u,v))\right) \lesssim \sqrt{\frac{s \log\left( \frac{e \cdot n}{s}\right)}{m}}.
\]
Now, the remainder of the proof of Theorem \ref{General distributions} can be applied verbatim to conclude the argument.
\end{proof}


\subsection{Unlimited sampling for general distributions} We now proceed to prove Theorem \ref{thm:mod-sharp-try}.

\begin{proof}[Proof of Theorem \ref{thm:mod-sharp-try}] We split the proof of the desired result into cases. \medskip

\noindent\textbf{Case 1:} $\|u-v\|_2 \le \lambda. $ In this case, we simply note that, if $s,t$ are such that $|s-t|\le \lambda$, then $|\mathcal{M}_\lambda(s) - \mathcal{M}_\lambda(t)| \ge |s-t|.$ Restricting to the event 
$$\left\{ a \|u-v\|_2 \le \left|\left\langle X,u-v\right\rangle\right| \le \|u-v\|_2 \right\},$$
we have 
\begin{align*}
\frac{1}{m} \sum_{i=1}^m \frac{|\mathcal{M}_\lambda(\langle X_i,u\rangle) - \mathcal{M}_\lambda(\langle X_i,v\rangle)|^2}{\|u-v\|_2^2} & \ge \frac{a^2}{m} \sum_{i=1}^m \mathds{1}\left( a \le \left| \left\langle X_i, \frac{u-v}{\|u-v\|_2} \right\rangle \right| \le 1 \right).
\end{align*}
Now, note that, by condition \eqref{eq:small-strip}, there is $a>0$ such that 
\[
\mathbb{P} \left( a \le |\langle X,w\rangle\right| \le 1) \ge c > 0. 
\]
Since, in addition, the class of Boolean functions 
\[
\F = \left\{ \mathds{1}(a \le |\langle x,w\rangle| \le 1) \colon w \in \S^{n-1}\right\}
\]
has, by virtue of Proposition \ref{prop:intersection}, VC-dimension bounded by $n$, it follows from Proposition \ref{prop:vc-quantif-lln} that 
\[
\mathbb{E} \sup_{u,v \in \B_{\R^n}} \left[ \frac{1}{m} \sum_{i=1}^m \mathds{1}\left( a \le \left| \left\langle X_i, \frac{u-v}{\|u-v\|_2} \right\rangle \right| \le 1 \right) - \mathbb{P}\left( a \le \left| \left\langle X,\frac{u-v}{\|u-v\|_2}\right\rangle \right| \le 1\right) \right] \le C \sqrt{\frac{n}{m}}.  
\]
Arguing again with Proposition \ref{prop:bounded-differences}, as in the proof of Theorem \ref{General distributions}, we have that 
\[ 
\frac{1}{m} \sum_{i=1}^m \mathds{1}\left( a \le \left| \left\langle X_i, \frac{u-v}{\|u-v\|_2} \right\rangle \right| \le 1 \right) \ge c - C\sqrt{\frac{n}{m}},
\]
with probability at least $1 - e^{-c t^2 m}.$ Setting $m \ge C n$ for $C$ an absolute, sufficiently large, constant  finishes the proof in this case. \medskip

\noindent\textbf{Case 2:} $\|u-v\|_2 \ge \lambda.$ We now simply note that, for the sets $\Omega_a(\delta)$ as defined in the statement of Theorem \ref{thm:mod-sharp-try}, we have that $|\mathcal{M}_{\lambda}(s) - \mathcal{M}_\lambda(t)| \ge a\lambda$ holds if $s-t \in \Omega_a(\lambda).$ Hence, translating this as a lower bound, we have 
\begin{equation}\label{eq:lower-bound-mod} 
\frac{1}{m} \sum_{i=1}^m \frac{|\mathcal{M}_\lambda(\langle X_i,u\rangle) - \mathcal{M}_\lambda(\langle X_i,v\rangle)|^2}{\|u-v\|_2^2} \ge \frac{(a\lambda)^2}{\|u-v\|_2^2} \frac{1}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i, u-v\rangle \in \Omega_a(\lambda)\right).
\end{equation} 
Now, note that 
\[
\langle X,u-v \rangle \in \Omega_a(\lambda) \, \text{ follows if }\, \langle X, (u-v)/\|u-v\|_2\rangle \in \Omega_a(\lambda/\|u-v\|_2).
\]
From condition \eqref{eq:mod-cond}, we obtain that 
\[
\inf_{u,v \in \S^{n-1}} \mathbb{P} \left( \langle X,u-v\rangle \in \Omega_a(\lambda)\right) \ge \inf_{\delta \ge \lambda/4} \tilde{c}(\delta) =: \theta(\lambda)> 0.
\]
Let now $C_\lambda > 0$ be such that we have 
\[
\mathbb{P}(|\langle X,u-v\rangle| \ge C_\lambda) \le \frac{\theta(\lambda)}{2},
\]
for all $u,v \in \B_{\R^n}$ such that $\|u-v\|_2 \ge \lambda.$ It follows that 
\[
\mathbb{P}\left( \langle X,u-v\rangle \, \in \, \Omega_a(\lambda) \cap [-C_\lambda,C_\lambda]\right) \ge \frac{\theta(\lambda)}{2}.
\]
On the other hand, it follows from Proposition \ref{prop:intersection} that the family 
\[
\F_{a,\lambda} \coloneqq \left\{ \mathds{1}\left( \langle X,u-v\rangle \in \Omega_a(\lambda) \cap [-C_\lambda,C_\lambda]\right)\colon u,v \in \B_{\R^n}\right\},
\]
being composed of indicator functions of a finite, fixed number of classes, each of which having VC-dimension bounded by $n$, satisfies $vc(\F_{a,\lambda}) \le C(\lambda)n.$ Hence, 
\[
\mathbb{E} \sup_{u,v \in \B_{\R^n}} \left[ \frac{1}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i, u-v \rangle \in \Omega_a(\lambda) \cap [-C_\lambda,C_\lambda] \right) - \mathbb{P}\left( \langle X,u-v\rangle \, \in \, \Omega_a(\lambda) \cap [-C_\lambda,C_\lambda]\right)\right] \]
\[
\le C(\lambda) \sqrt{\frac{n}{m}}. 
\]
Again, employing the usual device of Proposition \ref{prop:bounded-differences}, we conclude that 
\begin{align*}
\frac{1}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i,u-v\rangle \in \Omega_a(\lambda)\right) & \ge \frac{1}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i,u-v\rangle \in \Omega_a(\lambda) \cap [-C_\lambda,C_\lambda]\right) \cr 
    & \ge \mathbb{P} \left( \langle X,u-v\rangle \in \Omega_a(\lambda) \cap [-C_\lambda,C_\lambda]\right) - C(\lambda) \sqrt{\frac{n}{m}}-t,
\end{align*}
with probability at least $1 - e^{-ct^2 m}.$ By taking $t$ to be a small constant depending on $\lambda$ and $m \ge C(\lambda)n$ for some $C(\lambda)> 0$, we conclude that the right-hand side of \eqref{eq:lower-bound-mod} is bounded from below by $c(\lambda) > 0$ with probability at least $1- e^{-c(\lambda)m}$, as long as $m \ge C(\lambda) n.$ This concludes the proof. 
\end{proof}

\section{Sharp declipping and unlimited sampling for specific distributions}\label{sec:declipping}

In this section, our focus will be mostly on results dealing with \emph{sharp} asymptotic lower bounds for both declipping and unlimited sampling in specific cases -- such as when the random vector under consideration satisfies additional geometric constraints, like being uniformly distributed on a certain sphere.

\subsection{Sharp declipping for uniformly spherically distributed vectors} We start with the proof of Theorem \ref{thm:main-vc}. In order to do so, we need the following auxiliary result: 

\begin{lemma}\label{L:Clam}
    Let $\lambda,L\in\R$ be positive numbers with $4L\le \lambda \le 1$. If $u,v\in \B_{\R^n}$ and $x\in\R^n$ satisfy 
$$
    |\langle x,u\rangle|\le \frac{\lambda}{2} \hspace{.2cm}\textrm{ and }\hspace{.2cm} \left|\left\langle x,u-v\right\rangle\right| \ge L \|u-v\|_2,
$$
then
$$
\left|\Phi_{\lambda}(\langle x,u\rangle) - \Phi_{\lambda}(\langle x,v\rangle)\right| \ge L\|u-v\|_{2}.
 $$   
\end{lemma}

\begin{proof}
We first consider the case when $|\langle x,v\rangle|\leq \lambda$. It follows that
$$
\left|\Phi_{\lambda}(\langle x,u\rangle) - \Phi_{\lambda}(\langle x,v\rangle)\right|=|\langle x,u-v\rangle|\geq L \|u-v\|.
$$
We now assume that $|\langle x,v\rangle|> \lambda$.  Then,
\begin{align*}
\left|\Phi_{\lambda}(\langle x,u\rangle) - \Phi_{\lambda}(\langle x,v\rangle)\right|&\geq \lambda-\lambda/2 \\
&\geq L\|u-v\|\hspace{.5cm}\textrm{ as $\|u-v\|\leq 2$ and  $L\leq \lambda/4$,}
\end{align*}
which finishes the proof.
\end{proof}


We are now ready to prove Theorem \ref{thm:main-vc}. 

\begin{proof}[Proof of Theorem \ref{thm:main-vc}]
We consider $0<\lambda\le 1/2$ and
fix a constant $L>0$ with $\lambda>4L$ to be defined later. By Lemma \ref{L:Clam}, we have that
\begin{align}\label{eq:lower-decl-sharp}
\frac{1}{m}\sum_{i=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)\right|^2 \ge \frac{L^2}{m} \sum_{i=1}^m \mathds{1}\left(|\langle X_i,u\rangle|\le \frac{\lambda}{2} \cap \left|\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right| \ge L\right).
\end{align}
We define $\mathcal{E}(u,v)$ to be the event  
\begin{equation}\label{eq:event-E(u,v)}
\mathcal{E}(u,v) \coloneqq \left\{|\langle X,u\rangle|\leq \frac{\lambda}{2} \cap \left|\left\langle X,\frac{u-v}{\|u-v\|_2}\right\rangle\right|\ge L\right\},
\end{equation} 
and let the events $\mathcal{E}_i(u,v)$ (corresponding to $X_i$) be defined analogously. \medskip

We start with the (uniform) small ball probability. To this end, note that as $\|u\|\leq 1$ and $X$ is isotropic, we have by Markov's inequality that $\mathbb{P}(|\langle X,u\rangle|\leq \sqrt{2})\geq 1/2$.  As $X$ is uniformly distributed on a sphere, for each $\alpha>0$, $\mathbb{P}(|\langle X,u\rangle|\le \alpha)$ corresponds to the surface area of a central strip of width $2\alpha$ on an $(n-1)$-sphere.  As the area of a strip divided by its width is comparable to the surface area of an $(n-2)$-sphere, 
 there exists universal constants $c_1>c_0>0$ so that 
$$c_1\alpha \mathbb{P}\big(|\langle X,u\rangle|\le \sqrt{2}\big)\geq\mathbb{P}\big(|\langle X,u\rangle|\le \alpha\big)\geq 2c_0 \alpha  \mathbb{P}\big(|\langle X,u\rangle|\le \sqrt{2}\big).
$$
Thus, we have that 
\begin{equation}\label{E:proportional}    
c_1\alpha \geq\mathbb{P}(|\langle X,u\rangle|\le \alpha)\geq c_0 \alpha.  
\end{equation}
As \eqref{E:proportional} applies as well if $u$ is replaced with $(u-v)/\|u-v\|$, we have that

\begin{align*}
\mathbb{P}(\mathcal{E}(u,v))&\ge \mathbb{P}(\left|\langle X,u\rangle\right|\le \lambda/2)-\mathbb{P}\left(\left|\left\langle X,\frac{u-v}{\|u-v\|}\right\rangle\right|< L\right)\\
&\ge c_0\lambda-c_1 L.
\end{align*}

Let now $\mathcal{N} \coloneqq\{w_i\}_{i \in I}$ denote a $\lambda^2$-net of the unit ball $\B_{\R^n}.$ It follows that
$|\mathcal{N}| \le \left( \frac{C}{\lambda^2}\right)^{n}.$ Now, we need a statement that bounds the right-hand side of \eqref{eq:lower-decl-sharp} by its expected value for each element of our net with high probability. One possible way to do this would be through the usage of Proposition \ref{prop:bounded-differences}, which would imply that, for each $w_i \in \mathcal{N},$ with probability at least $1 - e^{- c \lambda^2 m}$, we have 
\begin{equation}\label{eq:lower-prob-high-each}
\frac{1}{m} \sum_{i=1}^m \mathds{1}(\mathcal{E}_i(u,v)) \ge \frac{1}{2} \cdot \mathbb{P} (\mathcal{E}(u,v)). 
\end{equation} 
This bound is, however, rather \emph{crude}: the specific Bernoulli structure of our random variables allows us to use the better-tailored \emph{Chernoff bound} for Bernoulli random variables in order to bound the probability of the event where 
\[
\left\{\frac{1}{m} \sum_{i=1}^m \mathds{1}(\mathcal{E}_i(u,v)) \le \frac{1}{2} \cdot \mathbb{P} (\mathcal{E}(u,v))\right\}
\]
by at most $e^{-c \lambda m}$. Hence, we finally conclude that, for each $w_i \in \mathcal{N},$ we have \eqref{eq:lower-prob-high-each} with probability at least $1 - e^{-c \lambda \cdot m}$.

\vspace{2mm}

Now, in order to further bound \eqref{eq:lower-decl-sharp} from below, we note that the intersection of the event 
\[
\mathcal{A}(u_k,w_j) \coloneqq\left\{ |\langle X,u_k\rangle| \le \frac{\lambda}{4} \, \cap \left| \langle X,w_j \rangle \right| > 2L \right\}
\]
with the event 
\[
\mathcal{B}(u,u_k,w,w_j) \coloneqq\left\{ |\langle X, u_k-u\rangle| \le \frac{\lambda}{10} \, \cap |\langle X, w_j-w\rangle| \le \frac{\lambda}{10}\right\}
\]
is contained in $\mathcal{E}(u,v)$, for $w = \frac{u-v}{\|u-v\|_2}$. Hence, by picking $u_k$ to be an element of $\mathcal{N}$ such that $\|u_k - u\|_2 \le c \lambda^2$ and $w_j \in \mathcal{N}$ such that $\|w_j - w\|_2 \le c \lambda^2$, we obtain 
\begin{align}\label{eq:second-lower-declp-sharp}
\frac{1}{m} \sum_{i=1}^m \mathds{1}(\mathcal{E}_i(u,v)) & \ge \frac{1}{m} \sum_{i=1}^m \mathds{1} \left(\mathcal{A}_i(u_k,w_j) \, \cap \mathcal{B}_i(u,u_k,w,w_j)\right) \cr 
 & \ge \frac{1}{m} \left( \sum_{i=1}^m \mathds{1}\left( \mathcal{A}_i(u_k,w_j)\right) - \sum_{i=1}^m \mathds{1}\left(\mathcal{B}_i^{c} (u,u_k,w,w_j)\right) \right). 
\end{align}
We then use a simple union bound: with probability at least 
$$
1 - |\mathcal{N}|^2 e^{-c \lambda m} \ge 1 - e^{c \left( n \log\left( \frac{1}{\lambda}\right) - \lambda m\right)},
$$
the first summand on the right-hand side of \eqref{eq:second-lower-declp-sharp} is bounded from below by $ c \cdot \lambda,$ for some universal, positive constant $c > 0$. On the other hand, for the second term, it suffices to notice that 
\begin{align}\label{eq:upper-bound-B}
\sum_{i=1}^m \mathds{1}\left(\mathcal{B}_i^{c} (u,u_k,w,w_j)\right) & \le \sum_{i=1}^m \mathds{1}\left( |\langle X_i, u_k - u \rangle| \ge \frac{\lambda}{10} \right) + \sum_{i=1}^m \mathds{1} \left( |\langle X_i, w_j - w\rangle| \ge \frac{\lambda}{10} \right) \cr 
                    & \le 100 \left( \sum_{i=1}^m \frac{|\langle X_i, u_k-u\rangle|^2}{\lambda^2} + \sum_{i=1}^m \frac{|\langle X_i,w_j-w\rangle|^2}{\lambda^2} \right).
\end{align}
We now invoke Proposition \ref{prop:vershynin-subgauss}. This, together with \eqref{eq:second-lower-declp-sharp} and \eqref{eq:upper-bound-B} implies that, with probability at least $1 - e^{-c \lambda m}$, we have 
\begin{align}
\frac{1}{m} \sum_{i=1}^m \mathds{1}(\mathcal{E}_i(u,v)) & \ge c \lambda - \frac{C}{\lambda^2}\left(\|u_k-u\|_2^2 + \|w_j-w\|_2^2\right) \cr 
    & \ge c \lambda - C \lambda^2 \ge \frac{c}{2} \lambda,
\end{align} 
for $\lambda > 0$ sufficiently small. This, together with \eqref{eq:lower-decl-sharp}, implies that 
\[
\frac{1}{m}\sum_{i=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)\right|^2 \ge c \cdot\lambda^3
\]
with probability at least $1 - e^{- c \lambda m},$ as long as we have $m \gtrsim \lambda^{-1} n \log\left( \frac{1}{\lambda}\right),$ as desired. 
\end{proof}

\begin{remark} We note that, in general, a bound of the form $m \ge c \lambda^{-1} n$ is unavoidable if we wish for the general results in this manuscript to hold with probability at least $1-e^{-cn}$. Indeed, suppose that, with probability at least $1-e^{-cn}$, we have 
\[
\frac{1}{m}\sum_{j=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)\right|^2 \ge c(\lambda),
\]
for some constant $c(\lambda) >0$ and all $u,v \in \B_{\R^n},$ where we assume the basic framework of Theorem \ref{General distributions}. Then, letting $v = (1-\varepsilon)u$ and making $\varepsilon \to 0$ as in the proof of Theorem \ref{thm:best-lam}, we should have that 
\begin{align*} 
\lambda^2 \frac{1}{m} \sum_{j=1}^m \mathds{1}_{\{|\langle X_i, u\rangle| \le \lambda\}} & \ge \frac{1}{m}\sum_{j=1}^m |\langle X_i, u\rangle|^2 \mathds{1}_{\{|\langle X_i,u\rangle| \le \lambda\} } \cr 
& \ge c(\lambda),
\end{align*}
that is, 
\begin{equation}\label{eq:Bernoulli-lower} 
\frac{1}{m} \sum_{j=1}^m \mathds{1}_{\{|\langle X_i, u\rangle| \le \lambda\}} \ge \frac{c(\lambda)}{\lambda^2}.
\end{equation} 
Now, since the variables $\left\{ \mathds{1}_{\{ |\langle X_i,u\rangle| \le \lambda\}} \right\}_{i=1}^m$ are actually i.i.d.~Bernoulli$(p)$ variables, where $p$ is of the order of $\lambda$, the probability that the left-hand side of \eqref{eq:Bernoulli-lower} is non-zero is at most $1-(1 - \lambda)^m.$ Hence, putting everything together, we obtain that 
\[
1-(1-\lambda)^m \ge 1 - e^{-cn},
\]
which, upon rearranging and using that $(1-\lambda)^m$ is of the order of $e^{-\lambda m}$ for $\lambda$ small, yields that $\lambda m \ge c n$, which is the claimed bound. 
\end{remark}

We now show that, in general, the bound achieved by Theorem \ref{thm:main-vc} is \emph{sharp}: 

{ 
\begin{proof}[Proof of Theorem \ref{thm:best-lam}]
Let $(x_j)_{j=1}^m$ be any fixed collection of vectors in $\sqrt{n}\S^{n-1}$.  For each $u\in \S^{n-1}$ we have that 
\begin{equation*}
\lim_{\varepsilon\rightarrow0}\frac{1}{m}\sum_{i=1}^m \frac{1}{\|u-(1-\varepsilon)u\|_{2}^2}\left|\Phi_{\lambda}(\langle u,x_j\rangle) - \Phi_{\lambda}(\langle (1-\varepsilon)u,x_j\rangle)\right|^2= \frac{1}{m}\sum_{|\langle u,x_j\rangle|\leq\lambda} \left|\langle u,x_j\rangle\right|^2.\end{equation*}
Thus, in order to prove Theorem \ref{thm:best-lam} it is sufficient to prove that there exists a universal constant $\beta>0$ so that there exists $u\in \S^{n-1}$ such that $\frac{1}{m}\sum_{|\langle u,x_j\rangle|\leq\lambda} \left|\langle u,x_j\rangle\right|^2<\beta \lambda^{3}$.  
This will be done by proving the claim that if $c_1$ is the constant given in Theorem \ref{thm:main-vc} and if $U$ is a random vector which is uniformly distributed in $\S^{n-1}$ then  
\begin{equation}\label{E:smaller}
\E \frac{1}{m}\sum_{|\langle U,x_j\rangle|\leq\lambda}|\langle U,x_j\rangle|^2\leq c_1\lambda^{3}. 
\end{equation}
Let 
 $U$ be a random vector which is uniformly distributed in $\S^{n-1}$ and let $x$ be a fixed vector in $\sqrt{n}\S^{n-1}$.  This scaling keeps \eqref{E:proportional} invariant, and thus we have for the same universal constants $c_1> c_0$ in the proof of Theorem \ref{thm:main-vc} that
 \begin{equation*}\label{E:proportional2}    
c_1\lambda \geq\mathbb{P}(|\langle U,x\rangle|\le \lambda)\geq c_0 \lambda.  
\end{equation*}
We now have that
\begin{align*}
    \E \frac{1}{m}\sum_{|\langle U,x_j\rangle|\leq\lambda}|\langle U,x_j\rangle|^2
    &\leq \E \frac{1}{m}\sum_{|\langle U,x_j\rangle|\leq\lambda} \lambda^2\\
&\leq \mathbb{P}\,(|\langle U,x\rangle|\leq\lambda) \cdot \lambda^2 \leq (c_1 \lambda)\lambda^2.
\end{align*}
This proves our claim that \eqref{E:smaller} holds and finishes the proof.
\end{proof}



}

\begin{remark}\label{rmk:rsb-needed} Note that the proof above, when applied in the \emph{continuous setting}, shows that the reverse small ball property \eqref{eq:reverse-small-ball} is actually \emph{necessary} for declipping to hold stably for all $\lambda > 0$. 
Indeed, by repeating the proof above, we get that 
\begin{equation}\label{eq:limit-expect} 
\lim_{\varepsilon \to 0} \mathbb{E} \left( \frac{|\Phi_\lambda(\langle X_i,u\rangle) - \Phi_\lambda(\langle X_i,(1-\varepsilon)u \rangle)|^2}{\|\varepsilon u\|_2^2}\right) = \mathbb{E} |\langle X,u\rangle|^2\mathds{1}_{\{|\langle X,u\rangle| \le \lambda\}},
\end{equation} 
and hence if the left-hand side of \eqref{eq:limit-expect} is bounded from below by $c(\lambda),$ then we have that 
\[
\mathbb{P} \left(|\langle X,u\rangle| \le \lambda\right) \ge \frac{c(\lambda)}{\lambda^2},
\]
for each $u \in \S^{n-1}.$ This is \emph{exactly} the content of \eqref{eq:reverse-small-ball}, as desired. 

In a similar spirit, one readily sees that, in order for the lower bound stated in Theorem \ref{thm:main-vc} to hold, it must be the case that the lower bound in \eqref{E:proportional} holds as well. On the other hand, it is not a difficult task to check that, if one assumes that both inequalities in \eqref{E:proportional} hold, then the proof of Theorem \ref{thm:main-vc} above may be repeated almost verbatim, which shows that our proof actually applies to a wider class of distributions - a fact to which we alluded in the introduction. 

A completely characterization of all distributions such that the result of Theorem \ref{thm:main-vc} holds seems to be elusive: the examples provided by Remark \ref{rmk:ssb-sharp?} show that the upper bound in \eqref{E:proportional} is \emph{not} necessary in order for a conclusion similar to that of Theorem \ref{thm:main-vc} to hold. 

Furthermore, it is possible to show that the constant $c(\lambda)$ given by Proposition \ref{prop:double-sphere-ex} can be taken to be $c(\lambda) \sim \lambda^3$. This shows that a reasonable degree of \emph{singularity} of the distributions of the random vectors considered can be allowed so that a continuous version of Theorem \ref{thm:main-vc} still holds. The question of under which minimal conditions we may infer such a bound is an interesting one, which we wish to address in future work. 
\end{remark}

\subsection{Sharp unlimited sampling for uniformly spherically distributed vectors} We now deal with the results pertaining to sharp stable unlimited sampling.

{
\begin{proof}[Proof of Theorem \ref{T:folding}]
 Suppose that $X$ is a random vector which is uniformly distributed on the sphere $\sqrt{n}\S^{n-1}$ and $\lambda>0$. 
  We will consider separately the case that $u,v\in \B_{\R^n}$ with $\|u-v\|_2\leq \lambda$ and the case that $u,v\in \B_{\R^n}$ with $\|u-v\|_2\geq \lambda$. \medskip

\noindent \textbf{Case 1}:  $u,v\in \B_{\R^n}$ with $0<\|u-v\|_2\leq \lambda$. \medskip


We claim first that there exist constants  $C,c_1 > 0$ so that the following holds: If $m\ge C n$ and $(X_j)_{j=1}^m$ are uniformly distributed in $\sqrt{n}\S^{n-1}$ then with probability at least $1-e^{-c_1m}$, we have  that 
\begin{equation}\label{E:12}
  |\{j:1/2\|w\|_2\leq |\langle X_j,w\rangle|\leq\|w\|_2\}|\geq Cm\hspace{1cm}\textrm{ for all }w\in\R^n.  
\end{equation}
A way to see this is by considering, once more, the class $\mathcal{F} = \{\mathds{1}\left( 1/2 \le |\langle X_i,w\rangle| \le 2 \right) \colon w \in \S^{n-1}\}.$ Since elements in this class may be represented as unions of up to four hyperplanes, it follows that $vc(\mathcal{F}) \lesssim n.$ Hence, by applying Proposition \ref{prop:vc-quantif-lln} to this class, the assertion follows. We may therefore assume that \eqref{E:12} holds from now on.

A key difference between clipping and folding is that the operation $\mathcal{M}_\lambda$ satisfies that for any $s,t\in\R$ for which $|s-t|\leq \lambda$,  $|\mathcal{M}_\lambda(s)-\mathcal{M}_\lambda(t)|\geq |s-t|$. In particular, as $0<\|u-v\|_2\leq\lambda$ we have that
\begin{align*}
\frac{1}{m}\sum_{i=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\mathcal{M}_{\lambda}(\langle X_i,u\rangle) - \mathcal{M}_{\lambda}(\langle X_i,v\rangle)\right|^2 &\ge \frac{1}{4m} \sum_{i=1}^m \mathds{1}\left(2^{-1}\le \left|\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right|\le1\right)\\
&\ge \frac{C}{4} \hspace{1cm}\textrm{ by \eqref{E:12}.}
\end{align*}
This completes the proof in the case that $\|u-v\|_2\leq \lambda$. \medskip

\noindent \textbf{Case 2:}  $u,v\in \B_{\R^n}$ satisfy $\lambda\leq\|u-v\|_2$. \medskip

Note that this case implicitly assumes that $0<\lambda\leq 2$.
We now fix $1/4>a>0$ to be decided later.
Let $\Omega_a\subseteq\R$ be given by $\Omega_a=\cup_{m\in\Z}[(a+2m)\lambda,(1-a+2m)\lambda]$.  
Note that if $\langle X,u-v\rangle\in\Omega_a$ then
$\left|\mathcal{M}_{\lambda}(\langle X_i,u\rangle) - \mathcal{M}_{\lambda}(\langle X_i,v\rangle)\right|\geq a\lambda$.  Thus, we have that
\begin{equation}\label{E:fold_far}
\frac{1}{m}\sum_{i=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\mathcal{M}_{\lambda}(\langle X_i,u\rangle) - \mathcal{M}_{\lambda}(\langle X_i,v\rangle)\right|^2 \ge \frac{(a\lambda)^2}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i,u-v\rangle\in\Omega_a\right).
\end{equation}
Notice that the right-hand side of \eqref{E:fold_far} only depends on $u-v$ and not on $u,v$ separately.  Thus, by substituting $w=u-v$, we may consider just the single vector $w\in 2\B_{\R^n}\setminus\lambda \B_{\R^n}$.  

For a subset $\Omega\subseteq\R$ we denote $|\Omega|$ to be the Lebesgue measure of $\Omega$.  Note that for every interval $I\subseteq\R$ with $|I|\geq\lambda$, we have that $|\Omega_a\cap I|\geq (1-2a)|I|$.  As $X$ is uniformly distributed in $\sqrt{n}\S^{n-1}$,  there exists a universal constant $c>0$ so that
 \begin{equation*}\label{E:mod_in}
 \mathbb{P}(\langle X,w\rangle\in\Omega_a)\geq 1-c\cdot a
\hspace{.5cm}\textrm{ for all $w\in2\R^n\setminus\lambda\R^n$.} 
\end{equation*}
Hence,
 \begin{equation*}\label{E:expected}
 \mathbb{E}\frac{1}{m}\sum_{i=1}^m \mathds{1}\left( \langle X_i,w\rangle\in\Omega_a\right)\geq 1-c \cdot a
\hspace{.5cm}\textrm{ for all $w\in2\R^n\setminus\lambda\R^n$.} 
\end{equation*}

By Proposition \ref{prop:bounded-differences} with $t=c\cdot a$,  for all $w\in 2\B_{\R^n}\setminus\lambda \B_{\R^n}$ we have with probability at least $1-e^{-Ca^2m}$ that 
\begin{equation}\label{E:big_p}
    \frac{1}{m}\sum_{i=1}^m \mathds{1}\left( \langle X_i,w\rangle\in\Omega_{2a}\right)\geq 1-c \cdot a.
\end{equation}

Let $\mathcal{N} = \{w_j\}_j$ be an $\vp$-net in  $2\B_{\R^n}$ with $|\mathcal{N}|\leq (6/\vp)^n$, where we set $\vp = c \cdot \lambda$ for some sufficiently small absolute constant $c > 0$. Then, we have with probability at least $1-e^{(c-\log(\lambda))n-C a^2m}$ that \eqref{E:big_p} holds for all $w \in \mathcal{N}.$ 

We now consider the task of extending this to all of $2\B_{\R^n}\setminus\lambda \B_{\R^n}$. In order to do so, we need to invoke once more Proposition \ref{prop:vershynin-subgauss} which guarantees that, with high probability, $(\frac{1}{\sqrt{m}}X_i)_{i=1}^m$ has upper frame bound $2$, or, in other words, \eqref{eq:upper-frame-bound} holds.  

This gives that there are uniform constants $c,C>0$ so that if $m\geq C\log(1/\lambda)n$ then with probability at least $1-e^{-cm}$, \eqref{eq:upper-frame-bound} and  \eqref{E:big_p} hold for all $w \in \mathcal{N}.$ We may hence assume that this is the case.

Let $w\in 2\B_{\R^n}\setminus\lambda\B_{\R^n}$ and choose $w_j \in \mathcal{N}$ such that $\|w-w_j\|_2\leq\vp$.  We have, in a similar way to the proof of Theorem \ref{thm:main-vc}, 
\begin{align*}
 \frac{1}{m}\sum_{i=1}^m \mathds{1}\left( \langle X_i,w\rangle\in\Omega_{a}\right)&\ge  \frac{1}{m}\sum_{i=1}^m \mathds{1}\left( \langle X_i,w_j\rangle\in\Omega_{2a}\textrm{ and }|\langle X_i,w-w_j\rangle|\leq a\lambda\right)\\
 &\ge  \frac{1}{m}\sum_{i=1}^m \mathds{1}\left( \langle X_i,w_j\rangle\in\Omega_{2a})\right)- \frac{1}{m}\sum_{i=1}^m \mathds{1}\left(|\langle X_i,w-w_j\rangle|> a\lambda\right)\\
  &\ge  (1-c\cdot a)- (a\lambda)^{-2}\frac{1}{m}\sum_{i=1}^m |\langle X_i,w-w_j\rangle|^2\\
    &\ge  (1-c\cdot a)- (a\lambda)^{-2} 2\|w-w_i\|_2^2  \ge c.
\end{align*}

By \eqref{E:fold_far}, this gives for all $u,v\in \B_{\R^n}$ with $\|u-v\|_2\geq\lambda$ that 
\begin{align*}
\frac{1}{m}\sum_{i=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\mathcal{M}_{\lambda}(\langle X_i,u\rangle) - \mathcal{M}_{\lambda}(\langle X_i,v\rangle)\right|^2 &\ge \frac{(a\lambda)^2}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i,u-v\rangle\in\Omega_a\right)  
\geq c \cdot \lambda^2.
\end{align*}
This finishes the proof. 
\end{proof}

}

{  

\begin{remark} From the proof above, one may be tempted to conjecture that there should actually be \emph{no} dependence on $\lambda$ \emph{at all} in the number of samples: indeed, we may, instead of the proof above, use the lower bound
