\section{Sharp declipping for spherical vectors and one-bit compressed sensing}\label{sec:one-bit}

We start with a couple of lemmas, the first of which shows that, whenever two vectors on the unit sphere are at least separated by a bit, we can get a good lower bound on the probability that one of the vectors gets clipped above a certain threshold and the other below.

\begin{lemma}\label{lemma:estimates-sets} There is an absolute constant $C>0$ for which the following assertion holds: Let $\lambda >0$ and $u,v \in \S^{n-1}$ satisfy that $\|u-v\|_2 \ge C \lambda.$ Then there is an absolute constant $c>0$ such that 
\[
\mathbb{P} \left( \langle X,u\rangle \le -\lambda, \, \langle X, v \rangle \ge \lambda \right) \ge c \cdot \|u-v\|_2.
\]
\end{lemma}
\begin{proof} We start by noting that we may write 
\[
X = \sqrt{n} \frac{Y}{\|Y\|_2} \, , 
\]
where $Y \distas{d} \mathcal{N}(0,I_{n \times n})$. Hence, for each $C'>0$,
\[
\mathbb{P} \left( \langle X,u\rangle \le -\lambda, \, \langle X, v \rangle \ge \lambda \right)  = \mathbb{P} \left( \langle Y,u\rangle \le - \lambda \frac{\|Y\|_2}{\sqrt{n}}, \, \langle Y, v \rangle \ge \lambda \frac{\|Y\|_2}{\sqrt{n}}\right)  
\]
\[
\ge \mathbb{P} \left( \langle Y,u\rangle \le - \lambda \frac{\|Y\|_2}{\sqrt{n}}, \, \langle Y, v \rangle \ge \lambda \frac{\|Y\|_2}{\sqrt{n}}, \, \frac{1}{C'} \sqrt{n} \le \|Y\|_2 \le C' \sqrt{n}\right)  
\]
\[
\ge \mathbb{P} \left( \langle Y,u\rangle \le -C' \lambda, \langle Y,v\rangle \ge C' \lambda, \frac{1}{C'} \sqrt{n} \le \|Y\|_2 \le C' \sqrt{n}\right)  
\]
\begin{equation}\label{eq:two-probs}
\ge \mathbb{P}\left(  \langle Y,u\rangle \le -C' \lambda, \langle Y,v\rangle \ge C' \lambda\right) - \mathbb{P}\left( \langle Y,u\rangle \le 0, \, \langle Y,v \rangle \ge 0, \, \frac{1}{C'} \sqrt{n} > \|Y\|_2 \text{ or } \|Y\|_2 > C' \sqrt{n}\right).
\end{equation}
We need to find a suitable lower bound for the first term and an upper bound for the second one. Let us thus start with the latter. Since $Y$ is invariant under rotations and since the event 
$$\{ \langle Y,u \rangle \le 0, \langle Y,v \rangle \ge 0\}$$
denotes an angle in $\R^n$ with opening of the order of $\|u-v\|_2$, we have that the latter probability is at most 
\[
\|u-v\|_2 \cdot \mathbb{P}\left( \|Y\|_2 \ge C' \sqrt{n} \text{ or } \|Y\|_2 \le \frac{1}{C'} \sqrt{n}\right) \le \|u-v\|_2 \cdot e^{-(C')^2}.
\]
We now seek a lower bound on the other probability. Since the vector $Y$ is rotation-invariant, we may write the probability we wish to estimate explicitly as 
\[
\int_{C'\lambda}^{\infty} \int_{-\infty}^{-C'\lambda} \frac{1}{2\pi\sqrt{1-\rho^2}} \exp\left\{ - \frac{1}{2(1-\rho^2)} (x^2 + y^2 - 2\rho xy)\right\}  \, dx \, dy,
\]
where we let 
$$\rho = 1 - \frac{\|u-v\|_2^2}{2}.$$
Changing variables $x = \|u-v\|_2 \cdot x', \, y = -\|u-v\|_2\cdot y',$ we see that the integral above is bounded from below by 
\begin{align}\label{eq:gaussian-two-d}
\|u-v\|_2 \cdot & \int_{C' \frac{\lambda}{\|u-v\|_2}}^{\infty} \int_{C' \frac{\lambda}{\|u-v\|_2}}^{\infty}  \exp\left\{ - \left( (x')^2 + (y')^2 + 2\rho x' y'\right)\right\} \, d x' \, dy' \cr 
 & \ge \|u-v\|_2 \int_{C'/100}^{\infty} \int_{C'/100}^{\infty} \exp(-2((x')^2 + (y')^2)) \, dx' \, dy'.
\end{align}
Now, since 
\[
\int_x^{\infty} e^{-2t^2} \, dt = \frac{1}{\sqrt{2}} \int_{\sqrt{2}x}^{\infty} e^{-s^2} \, ds \ge \frac{1}{4x} e^{-2x^2},
\] 
we have that 
\[
\int_{C'/100}^{\infty} e^{-2 (x')^2} \, dx' \ge \frac{1}{C'} e^{-\frac{(C')^2}{5000}}.
\]
It follows that the right-hand side of \eqref{eq:gaussian-two-d} is bounded from below by 
$$e^{- \frac{(C')^2}{1000}} \|u-v\|_2,$$ 
as long as $\|u-v\|_2 > 100 \lambda,$ which shows that the first probability in \eqref{eq:two-probs} above is larger than two times the second, finishing our proof, as long as we take $C \ge 100$ in the statement of the lemma. 
\end{proof}

The next result complements the previous one, showing that, on the other hand, even if both vectors are close by, then the probability of both of them \emph{not} getting clipped is non-trivial. 

\begin{lemma} For any $C>0$ there is $c>0$ such that the following holds. Let $u,v \in \S^{n-1}$ be such that $\|u-v\|_2 \le C \lambda.$ Then, for $\theta > 0$ a sufficiently small absolute constant, we have
\[
\mathbb{P}\left( \left| \left\langle X,\frac{u-v}{\|u-v\|_2}\right\rangle \right| \ge \theta \, \cap |\langle X,u\rangle| \le \lambda \, \cap |\langle X,v \rangle| \le \lambda\right) \ge c \cdot \lambda. 
\]
\end{lemma}

\begin{proof} We do the same as in the previous lemma: we have that 
\begin{align*} 
& \mathbb{P}\left( \left| \left\langle X,\frac{u-v}{\|u-v\|_2}\right\rangle \right| \ge \theta,|\langle X,u\rangle| \le \lambda, |\langle X,v \rangle| \le \lambda\right) \cr 
& \ge \mathbb{P} \left( \left| \left\langle Y,\frac{u-v}{\|u-v\|_2}\right\rangle \right| \ge C'\theta,|\langle Y,u\rangle| \le \frac{\lambda}{C'}, |\langle Y,v\rangle| \le \frac{\lambda}{C'}, \, \frac{1}{C'} \sqrt{n} \le \|Y\|_2 \le C' \sqrt{n}\right). 
\end{align*} 
Now note that, by rotation-invariance of $Y$ once more, we may assume that $u = e_1$ and $v = \alpha e_1 + \beta e_2$, where $\{e_j\}_{j=1}^n$ denotes the canonical basis in $\R^n$. Since we have $\|u-v\|_2 \le C \lambda$, it follows that 
\[
(1-\alpha)^2 + \beta^2 \le C^2 \lambda^2. 
\]
In particular, an elementary calculation shows that, under the conditions of the lemma, we have that belonging to the event 
\[
\left\{ |Y_1| \le \frac{\lambda}{\tilde{C}}, 2C'\theta \le |Y_2|\le \frac{1}{\tilde{C}},\frac{\sqrt{n}}{C'} \le Y_3^2 + \cdots + Y_n^2 \le C'\sqrt{n} - 2 \right\}
\]
implies belonging to the event
\[
\left\{ \left| \left\langle Y,\frac{u-v}{\|u-v\|_2}\right\rangle \right| \ge C'\theta,|\langle Y,u\rangle| \le \frac{\lambda}{C'}, |\langle Y,v\rangle| \le \frac{\lambda}{C'}, \, \frac{1}{C'} \sqrt{n} \le \|Y\|_2 \le C' \sqrt{n}\right\}.
\]
Here, note that the absolute constant $\tilde{C}$ depends only on the constant $C>0.$ Hence, we have 
\[
\mathbb{P} \left( \left| \left\langle Y,\frac{u-v}{\|u-v\|_2}\right\rangle \right| \ge C'\theta,|\langle Y,u\rangle| \le \frac{\lambda}{C'}, |\langle Y,v\rangle| \le \frac{\lambda}{C'}, \, \frac{1}{C'} \sqrt{n} \le \|Y\|_2 \le C' \sqrt{n}\right) 
\]
\[
\ge \mathbb{P}\left( |Y_1| \le \frac{\lambda}{20C'}\right) \cdot \mathbb{P}\left( 2C'\theta \le |Y_2| \le \frac{1}{20}\right) \cdot \mathbb{P}\left(\frac{\sqrt{n}}{C'} \le Y_3^2 + \cdots + Y_n^2 \le C'\sqrt{n} - 2 \right),
\]
by independence of the entries of $Y$. Since the two events
\[
\left\{ \frac{\sqrt{n}}{C'} \le Y_3^2 + \cdots + Y_n^2 \le C'\sqrt{n} - 2 \right\}, \quad \left\{ 2C'\theta \le |Y_2| \le \frac{1}{20}\right\}
\]
have probability bounded from below by an absolute constant as long as we take $\theta$ to be a sufficiently small absolute constant and since 
\[
\mathbb{P}\left( |Y_1| \le \frac{\lambda}{20C'}\right) \ge c \cdot \lambda, 
\]
for some small absolute constant $c>0,$ we have that 
\[
\mathbb{P}\left( \left| \left\langle X, \frac{u-v}{\|u-v\|_2} \right\rangle \right| > \theta,|\langle X,u\rangle| \le \lambda, |\langle X,v \rangle| \le \lambda\right) \ge c \cdot \lambda,
\]
for some possibly different absolute constant $c>0,$ as desired. 
\end{proof} 

We now move to the proof of Theorem \ref{thm:spherical}. 
\begin{proof}[Proof of Theorem \ref{thm:spherical}] We divide our task once more into two cases. \medskip

\noindent\textbf{Case 1: $\|u-v\|_2 \ge C\lambda$.} In this case, we bound 
\[
\frac{1}{m} \sum_{i=1}^m \frac{|\Phi_\lambda(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)|^2}{\|u-v\|_2^2} \ge \frac{4\lambda^2}{\|u-v\|_2^2} \frac{1}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i,u\rangle \le - \lambda, \langle X_i, v \rangle \ge \lambda \right).  
\]
Now, take $\mathcal{N}'$ to be a $c\lambda^2$-net on $\B_{\R^n}$. Let $u_0,v_0$ denote the closest elements of $\mathcal{N}'$ to $u,v$, respectively. We then bound 
\begin{align*}
\frac{1}{m} & \sum_{i=1}^m \mathds{1}( \langle X_i,u\rangle \le -\lambda, \langle X_i,v\rangle \ge \lambda) \cr 
&\ge \frac{1}{m} \sum_{i=1}^m \mathds{1}( \langle X_i,u_0\rangle \le -2\lambda, \langle X_i,v_0\rangle \ge 2\lambda, |\langle X_i,u-u_0\rangle| \le \lambda,|\langle X_i,v-v_0\rangle|\le \lambda) \cr 
& \ge \frac{1}{m} \left( \sum_{i=1}^m \mathds{1}( \langle X_i,u_0\rangle \le -2\lambda, \langle X_i,v_0\rangle \ge 2\lambda) - \sum_{i=1}^m \mathds{1}(|\langle X_i,u-u_0\rangle| \ge \lambda \cup |\langle X_i,v-v_0\rangle|\ge \lambda)\right).
\end{align*}
Since we know that, for each individual pair $(u_0,v_0)\in \mathcal{N}' \times \mathcal{N}'$ such that $\|u_0 - v_0\| \ge \frac{C}{2}\lambda,$ we have with probability at least $1 - e^{-c \lambda m}$ that 
\[
\frac{1}{m} \sum_{i=1}^m \mathds{1}( \langle X_i,u_0\rangle \le -2\lambda, \langle X_i,v_0\rangle \ge 2\lambda) \ge \frac{c}{2} \|u_0-v_0\|_2.
\]
We next note that
\begin{align*} 
\frac{1}{m}&\sum_{i=1}^m \mathds{1}(|\langle X_i,u-u_0\rangle| \ge \lambda \cup |\langle X_i,v-v_0\rangle|\ge \lambda) \cr 
& \le \frac{1}{m} \sum_{i=1}^m \mathds{1}(|\langle X_i,u-u_0\rangle| \ge \lambda ) + \frac{1}{m} \sum_{i=1}^m \mathds{1}(|\langle X_i,v-v_0\rangle|\ge \lambda) \cr 
& \le \frac{1}{m\lambda^2} \sum_{i=1}^m \left( |\langle X_i,u-u_0\rangle|^2 + |\langle X_i,v-v_0\rangle|^2\right) \cr 
& \le C\lambda^2,
\end{align*} 
where the last line follows from Proposition \ref{prop:vershynin-subgauss}, and it holds with probability at least $1- e^{-cm}.$ Thus, with probability at least $1-|\mathcal{N}'|^2e^{-c \lambda m} \ge 1 - e^{C n \log(1/\lambda) - c \lambda m}$, we have that 
\[
\frac{1}{m} \sum_{i=1}^m \mathds{1}(\langle X_i,u\rangle \le -\lambda, \langle X_i,v\rangle \ge \lambda) \ge \frac{c}{3} \|u-v\|_2,
\]
which concludes the claim in this case, since $2 \ge \|u-v\|_2 \ge C\lambda$ and $m \gtrsim \lambda^{-1} \log(1/\lambda)n.$ \medskip

\noindent\textbf{Case 2: $\|u-v\|_2 \le C\lambda$.} In this case, one cannot do better than restricting matters to the clipped vectors. Indeed, we use the bound 
\[
\frac{1}{m} \sum_{i=1}^m \frac{|\Phi_\lambda(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)|^2}{\|u-v\|_2^2} \ge \frac{1}{m} \sum_{i=1}^m \left| \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right|^2 \mathds{1}\left(|\langle X_i,u\rangle| \le \lambda, |\langle X_i,v\rangle| \le \lambda\right)
\]
\[
\ge \frac{\theta^2}{m} \sum_{i=1}^m \mathds{1} \left( \left| \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right| > \theta, |\langle X_i,u\rangle| \le \lambda, |\langle X_i,v\rangle| \le \lambda\right).
\]
By arguing as in the previous case, we are able to conclude that, with probability at least $1 - e^{-c \lambda m}$, we have 
\[
\frac{1}{m} \sum_{i=1}^m \mathds{1} \left( \left| \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right| > \theta, |\langle X_i,u\rangle| \le \lambda, |\langle X_i,v\rangle| \le \lambda\right) \ge \frac{c}{3} \lambda, \, \forall \, u,v\in\S^{n-1}. 
\]
This finishes the proof. 
\end{proof}



\begin{proof}[Proof of Corollary \ref{cor:sparse-rec}] The proof of Corollary \ref{cor:sparse-rec} may be achieved by simply combining the proof of Theorem \ref{thm:spherical} with the proof of Theorem \ref{thm:main-sparse} sketched above. We omit the details. 
\end{proof}

\begin{remark}\label{remark on samples} Note that, in the statement of Theorem \ref{cor:sparse-rec}, the minimal asserted number of samples required for the second part of the result to hold depends at least like $\lambda^{-3} \log\left( \frac{1}{\lambda}\right)$ times the square of the Gaussian width of the set $\Sigma_s$ of effectively sparse vectors. We note that, in an analogous manner, it has been conjectured in \cite{plan-vershynin-2} that a dependence of $\delta^{-2}$ times the square of the Gaussian width should be necessary -- and sufficient -- in order for a random hyperplane tesselation on the set to approximate the distance between two points up to confidence $\delta$ with high probability. 

In that regard, we highlight \cite{jacques2013robust}, where in the case of the \emph{exactly} sparse vectors a similar result has been obtained as Corollary \ref{cor:one-bit-cs}, and the work of S.~Dirksen and S.~Mendelson \cite{dirksen2021non} which showed that, under the effect of adding noise before quantization -- the so-called process of \emph{dithering} -- one may actually recover effectively sparse vectors from the whole unit \emph{ball} with relatively few samples. In this context, a natural step would be to consider a suitable dithering version of the problems above, which we shall delegate to future work.
\end{remark}
Finally, we present a proof of Corollary \ref{cor:one-bit-cs}.  
\begin{proof}[Proof of Corollary \ref{cor:one-bit-cs}] 
We focus on the first assertion of Corollary \ref{cor:one-bit-cs}. Note that the proof of \textbf{Case 1} of Theorem \ref{thm:spherical} applies with the modifications highlighted for Corollary \ref{cor:sparse-rec} above if we only suppose that $\|u-v\|_2 \ge \delta$ and we redo the argument accordingly. In more specific words, we can bound
\[
\frac{1}{m} \sum_{i=1}^m \frac{|\Phi_\lambda(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)|^2}{\|u-v\|_2^2} \ge \frac{4\lambda^2}{\|u-v\|_2^2} \frac{1}{m} \sum_{i=1}^m \mathds{1}\left( \langle X_i,u\rangle \le - \lambda, \langle X_i, v \rangle \ge \lambda \right).  
\]
We may still estimate accordingly in this case by 
\begin{align*}
\frac{1}{m} & \sum_{i=1}^m \mathds{1}( \langle X_i,u\rangle \le -\lambda, \langle X_i,v\rangle \ge \lambda) \cr 
&\ge \frac{1}{m} \sum_{i=1}^m \mathds{1}( \langle X_i,u_0\rangle \le -\lambda-\delta, \langle X_i,v_0\rangle \ge \lambda + \delta, |\langle X_i,u-u_0\rangle| \le \delta,|\langle X_i,v-v_0\rangle|\le \delta) \cr 
& \ge  \left( \frac{1}{m}\sum_{i=1}^m \mathds{1}( \langle X_i,u_0\rangle \le -\lambda-\delta, \langle X_i,v_0\rangle \ge \lambda+\delta) \right. \cr 
& \left. - \frac{1}{m}\sum_{i=1}^m \mathds{1}(|\langle X_i,u-u_0\rangle| \ge \delta \cup |\langle X_i,v-v_0\rangle|\ge \delta)\right).
\end{align*}
As long as we take $\lambda < \delta,$ the first sum is bounded from below by 
\[
\frac{1}{m} \sum_{i=1}^m \mathds{1}( \langle X_i,u_0\rangle \le -2\delta, \langle X_i,v_0\rangle \ge 2\delta),
\]
which like in the proof of Theorem \ref{thm:spherical}, is bounded from below by $c \|u-v\|_2$ in an event of probability at least $1 - |\mathcal{N}|^2 e^{- c\delta m}$, while the second sum is bounded from above by $c \cdot \delta$ with probability at least $1 - e^{-c \delta^2 m}$. By choosing $\mathcal{N}$ to be a $c\frac{\delta}{\sqrt{\log\left(\frac{1}{\delta}\right)}}$-net of $\Sigma_s \cap \S^{n-1}$, we obtain that, with probability at least $1 - e^{-c \delta^2 m}$, we have that for all $u, v \in \Sigma_s \cap \S^{n-1}$with $\|u-v\|_2 \ge C \delta,$ 
\[
\frac{1}{m} \sum_{i=1}^m \frac{|\Phi_\lambda(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)|^2}{\|u-v\|_2^2} \ge c \cdot \lambda^2,
\]
whenever $m \ge C \delta^{-3} \log\left( \frac{1}{\delta}\right) s \log\left( \frac{en}{s}\right).$ A quick analysis of the proof above shows that the events above can be seen to be \emph{independent} of $\lambda < \delta$. This concludes the first assertion of Corollary \ref{cor:one-bit-cs}. 

\vspace{2mm}

In order to prove the second assertion of Corollary \ref{cor:one-bit-cs}, let $(u_{\delta},v_{\delta}) \in (\Sigma_s\cap\S^{n-1})^2$ be such that $\|u_\delta - v_\delta\|_2 \ge \delta$ and 
\[
\inf_{\substack{{u,v \in \Sigma_s \cap \S^{n-1}} \\ {\|u-v\|_2 \ge \delta}}} \frac{1}{m\|u-v\|_2^2} \sum_{i=1}^m |\text{sign}(\langle X_i, u \rangle) - \text{sign}(\langle X_i,v\rangle)|^2 \]
\[
\ge \frac{1}{2} \frac{1}{m\|u_\delta-v_\delta\|_2^2} \sum_{i=1}^m |\text{sign}(\langle X_i, u_\delta \rangle) - \text{sign}(\langle X_i,v_\delta\rangle)|^2
\]
\[
= \frac{1}{2m\|u_\delta - v_\delta\|_2^2} \lim_{\lambda \to 0} \sum_{i=1}^m \frac{|\Phi_\lambda(\langle X_i,u_\delta\rangle) - \Phi_\lambda(\langle X_i,v_{\delta}\rangle)|^2}{\lambda^2}.
\]
By the first assertion, this last right-hand side is bounded from below by an absolute constant with probability at least $1 - e^{-c\delta^2 m}$, which concludes the proof of the second assertion, and hence also that of Corollary \ref{cor:one-bit-cs}. 
\end{proof}

