\section{A comparison of declipping and phase retrieval for frames in infinite dimensions}
Let $H$ be an infinite dimensional Hilbert space. Recall that a \emph{frame} for $H$ is a sequence of vectors $(\phi_j)_{j\in J}$ in $H$ so that there exists universal constants $A, B$ with 
\begin{equation}\label{frame}
    A\|x\|_H^2\leq \sum_{j\in J}|\langle x,\phi_j\rangle|^2\leq B\|x\|^2_H \hspace{5mm} \text{for all}\ x\in H.
\end{equation}
Note that \eqref{frame} simply states that the \emph{analysis operator} $T:H\to \ell^2(J)$ defined by $Tx=(\langle x,\phi_j\rangle)_{j\in J}$ is an isomorphic embedding, so that we may identify $H$ with the subspace $T(H)\subseteq \ell^2(J)$. 
\medskip

Recall that a subspace $E$ of $L^2(\mu)$ does \emph{stable phase retrieval} if there exists a constant $C$ so that for all $f,g\in E$ we have 
\begin{equation*}
    \inf_{|\lambda|=1}\|f-\lambda g\|\leq C\||f|-|g|\|.
\end{equation*}
A frame is said to do stable phase retrieval if the subspace $T(H)$ does stable phase retrieval in $\ell^2(J).$  Although it is common for infinite dimensional subspaces $E$ of $L^2(\mathbb{R})$ to do stable phase retrieval, it is \emph{impossible} for a frame of an infinite dimensional Hilbert space to do \emph{stable} phase retrieval. Although this is well-known, we present a simple argument in order to compare phase retrieval with declipping.
\begin{proposition}
    Let $E$ be an infinite-dimensional subspace of $\ell^2.$ Then $E$ fails to do stable phase retrieval.
\end{proposition}
\begin{proof}
    Take $x\in E$ with $\|x\|=1$. Write $x=(a_1,a_2,\ldots)$. Since $x\in \ell^2$, for any $\epsilon>0$ we may find $N$ so that 
    \begin{equation*}
        x\approx_\epsilon(0,\ldots,0,a_N,a_{N+1},\ldots).
    \end{equation*}
    Consider the linear map $T: E\to \mathbb{F}^N$ defined by sending $(b_j)_{j=1}^\infty$ to $(b_j)_{j=1}^N$. Since $E$ is infinite dimensional, $T$ has a kernel, so there exists an element $y$ in $E$ with $\|y\|=1$ of the form
    \begin{equation*}
        y=(0,\ldots,b_{N+1},\ldots).
    \end{equation*}
    We now simply notice that $|x+y|\approx_\epsilon |x-y|$ but $x+y, x-y\in E$ are far from being multiples of each other.
\end{proof}
The above proof is known as the ``gliding hump argument", as it allows one to push bumps to infinity. 
\medskip

To define declipping for frames, or even for general subspaces of $L^p$-spaces, one needs a distinguished element $e$ which you ``clip" by. By the above argument, if $E$ is an infinite dimensional subspace of $\ell^2$ and you clip by an element $e\in \ell^2$, then stable declipping is bound to fail, as the bumps being sent to infinity will be almost entirely clipped. However, if one clips instead by the constant function $\bold{1}=(1,1,\dots)\not\in \ell^2$ one can build a normalized frame of an infinite dimensional Hilbert space doing stable $\lambda$-declipping for all $\lambda>0$ simultaneously. This is a consequence of our finite dimensional results and an appropriate gluing argument; it answers the other open question raised by by the second author at the \emph{ETH Zurich Colloquium in Applied and Computational Mathematics} in Fall 2023.
\begin{proposition}\label{Prop infinite frame}
    There exists a normalized frame $(\phi_j)_{j=1}^\infty$ of an infinite dimensional Hilbert space $H$ that does stable $\lambda$-declipping for all $\lambda>0$ in the sense that for all $\lambda>0$ there exists a constant $C_\lambda$ so that for all $x,y\in B_H$ we have 
    \begin{equation*}
        \|x-\lambda y\|_H\leq C_\lambda \left(\sum_{j=1}^\infty |\Phi_\lambda( \langle x,\phi_j\rangle)-\Phi_\lambda(\langle y,\phi_j\rangle) |^2\right)^{\frac{1}{2}}.
    \end{equation*}
    Here, $\Phi_\lambda( (a_j)_{j=1}^\infty)=( -\lambda \vee a_j\wedge \lambda)_{j=1}^\infty.$
\end{proposition}
We remark that in \cite{Stablephaseretrieval}, stable phase retrieval was studied in general subspaces of Banach lattices. The above two results suggest that the natural setting to study declipping in infinite dimensions would be in truncated Banach lattices, which are simply Banach lattices $X$ equipped with an appropriate (Lipschitz) truncation operator. It is well-known (I'll add) that each truncation in a vector lattice arises simply by taking infimum with an element of $X^u$, the universal completion of $X$, as we did in  Proposition~\ref{Prop infinite frame}. We note that the universal completion of $\ell^2$ is $\mathbb{R}^{\mathbb{N}}$ and the universal completion of $L^2(\mu)$ for a $\sigma$-finite measure $\mu$ is $L^0(\mu)$, which both come canonically equipped with the constant function $\textbf{1}$.







\begin{remark}  We now provide, as promised, an alternative proof of Theorem \ref{thm:sparse-gen-dist}, in which we have the additional feature of \emph{not} depending on the VC-dimension tools developed above. As we shall see below, this has the added advantage of not relying on the specific structure of $T_s$. 


\begin{proof}[Alternative Proof of Theorem \ref{thm:sparse-gen-dist}] Let $T$ be the subset of the unit (Euclidean) ball consisting of all $s$-sparse vectors and consider the following (random) quantity
\begin{equation*}
    \inf_{(u,v) \in T\times T}\frac{1}{m\|u-v\|_2^2}\sum_{i=1}^m \left|\Phi_{\lambda}(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)\right|^2.
\end{equation*}
Following the same steps as before, it suffices to estimate from below the following quantity
\begin{equation*}
\inf_{(u,v) \in T\times T} \frac{L^2}{m} \sum_{i=1}^m \mathds{1}\left(|\langle X_i,u\rangle|\le \frac{\lambda}{2} \cap \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\ge L\right).
\end{equation*}
Let $Q(u,v)$ denote the event
\begin{equation*}
    Q(u,v) = \left(|\langle X,u\rangle|\le \frac{\lambda}{2} \cap  \left\langle X,\frac{u-v}{\|u-v\|_2}\right\rangle\ge 2L\right), 
\end{equation*}
and let $Q'(u) = \left(|\langle X,u\rangle|\le \frac{\lambda}{2}\right)$.

Using the same arguments as in the previous section (just replacing $L$ by $2L$), we have that 
$$\inf_{(u,v)\in T\times T}\mathbb{P}(Q(u,v)) \ge c_0 \lambda - c_1 L,$$ 
thus we have that
\begin{equation*}
\begin{split}
& \inf_{(u,v) \in T\times T} \frac{L^2}{m} \sum_{i=1}^m \mathds{1}\left(|\langle X_i,u\rangle|\le \frac{\lambda}{2} \cap  \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\ge L\right)\\
& \ge L^2\left(c_0 \lambda - c_1 L- D_m\right),\\
\end{split}
\end{equation*}
where we let 
\[
D_m \coloneqq \frac{1}{m}\sup_{(u,v) \in T\times T}\sum_{i=1}^m \mathbb{P}(Q(u,v))- \mathds{1}\left(|\langle X_i,u\rangle|\le \frac{\lambda}{2} \cap \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\ge L\right).
\]
All that remains is to provide an upper bound for $D_m$ which is the supremum of an empirical process. To this end, notice that by the bounded difference inequality (Proposition \ref{prop:bounded-differences}, as employed above), it suffices to estimate the expected value of such supremum, namely
\begin{equation*}
\frac{1}{m}\mathbb{E}\sup_{(u,v) \in T\times T}\sum_{i=1}^m \mathbb{P}(Q(u,v))- \mathds{1}\left(|\langle X_i,u\rangle|\le \frac{\lambda}{2} \cap  \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\ge L\right).
\end{equation*}
Let $\psi_L(x)$ be the ``soft'' indicator function: that is, a function satisfying $\mathds{1}_{\{|x|\ge 2L\}} \le \psi_L(x)\le \mathds{1}_{\{|x|\ge L\}}$ for all $x\in \mathbb{R}$, with $L\psi_L(x)$ a $1$-Lipschitz function vanishing at the origin. Thus, by the Gin\'e-Zinn symmetrization (Proposition \ref{prop:symmetrization}):
\begin{equation*}
\begin{split}
&\frac{1}{m}\mathbb{E}\sup_{(u,v) \in T\times T}\sum_{i=1}^m \mathbb{P}(Q(u,v))- \mathds{1}\left(|\langle X_i,u\rangle|\le \frac{\lambda}{2} \cap \left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\ge L\right)\\
&\le \frac{1}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \mathbb{E}\left(\mathds{1}(Q'(u))\psi_L\left(\left\langle X,\frac{u-v}{\|u-v\|_2}\right\rangle\right)\right) - \mathds{1}Q_i'(u)\psi_L\left(\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right)
\end{split}
\end{equation*}
\[\le \frac{2}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i \mathds{1}(Q_i'(u))\psi_L\left(\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right).
\]
We now work conditionally on the randomness of $X_1,\ldots,X_m$, which we shall denote by $x_1,\ldots, x_m$. More accurately, let $J$ be the (random) index set for which $Q_i'(u)$ occurs, and apply Jensen's inequality to obtain that
\begin{equation*}
\begin{split}
&\frac{2}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i \mathds{1}(Q_i'(u))\psi_L\left(\left\langle x_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right)\\
& =  \frac{2}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \left(\sum_{i\in J} \varepsilon_i \psi_L\left(\left\langle x_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right) + \mathbb{E}\sum_{i\notin J}\varepsilon_i \psi_L\left(\left\langle x_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right) \right) \\
&\le \frac{2}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i \psi_L\left(\left\langle x_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right).
\end{split}
\end{equation*}
By iterated law of expectation the estimate above holds for the expectation with respect to the joint law of $X_i's$ and $\varepsilon_i's$, thus all that remains is to control 
\begin{equation*}
\frac{2}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i \psi_L\left(\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right). 
\end{equation*}
Recall that $L\psi_L(\cdot)$ is a $1$-Lipschitz function that passes through the origin. Thus, by Proposition \ref{prop:contraction} we obtain that
\begin{equation*}
\frac{2}{m} \mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i \psi_L\left(\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle\right) \le \frac{2}{L m}\mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle.
\end{equation*}
Since $u,v$ are $s$-sparse, $u-v$ is $2s$-sparse. Notice that $\frac{u-v}{\|u-v\|_2}$ is a $2s$-sparse vector in the Euclidean sphere. Moreover, any $2s$-sparse (unit) vector is contained in the intersection of $B_2^n \cap \sqrt{2s}B_1^n$, by H\"older's inequality. Thus, setting $T':=B_2^n \cap \sqrt{2s}B_1^n$, we have 
\begin{equation*}
\frac{2}{Lm}\mathbb{E}\sup_{(u,v) \in T\times T} \sum_{i=1}^m \varepsilon_i\left\langle X_i,\frac{u-v}{\|u-v\|_2}\right\rangle \le \frac{2}{L m}\mathbb{E}\sup_{t\in T'} \sum_{i=1}^m \varepsilon_i\langle X_i,t\rangle.
\end{equation*}
We invoke Talagrand's comparison inequality: indeed, since $\langle m^{-1/2}\sum_{i=1}^n\varepsilon_i X_i,t\rangle$ is clearly a mean-zero, sub-gaussian process with bounded variance, the hypothesis in Proposition \ref{prop:talagrand-comparison} is satisfied, allowing us hence to obtain that
\begin{equation*}
\frac{2}{L \sqrt{m}}\mathbb{E}\sup_{t\in T'} \sum_{i=1}^m \frac{1}{\sqrt{m}}\varepsilon_i\langle X_i,t\rangle \lesssim \frac{1}{L\sqrt{m}} \mathbb{E}\sup_{t\in T'}\langle g,t\rangle \lesssim\frac{1}{L}\sqrt{\frac{s\log(en/s)}{m}},
\end{equation*}
where we used in the last step that the gaussian width of the set of $2s-$sparse vectors is at most $ C \sqrt{s \log (en/s)}.$ 

We now take, just like in the proof of Theorem \ref{thm:main-vc}, $L = \frac{c_0}{4c_1}\lambda.$ When $m\gtrsim \lambda^{-4} \cdot s\log(en/s)$, it follows from the considerations above that $D_m$ is small with probability at least $1 - e^{-c n},$ and the proof is completed in the same way as in the end of the proof of Theorem \ref{thm:main-vc}. 

\end{proof}

It is important to note that the proof above works for every set $T$ that is a cone, meaning that $t \in T$ implies $k\cdot t \in T$, for any $k >0$ positive constant. In the aforementioned case of a sub-gaussian vector $X$, the convergence rate is given by the Gaussian width of the set $T$, 
\[
w(T) \coloneqq \mathbb{E} \sup_{t \in T} \langle g,t \rangle,
\]
divided by $\sqrt{m}$. The Gaussian width is a well-known quantity that often dictates the convergence rate of recovery problems. For example, in the realm of recovery via convex programs, the authors in \cite{amelunxen2014living} proved that when $m \ll w^2(T),$ recovery is in general \emph{not} possible.

Thanks to Talagrand's comparison inequality (see Proposition \ref{prop:talagrand-comparison}), since $u,v \in T$ implies that $u-v \in T-T$, the vector $\frac{u-v}{\|u-v\|_2}$ belongs to the intersection of $T-T$ with the (Euclidean) unit ball, and one can check that the Gaussian width of $T-T$ is at most twice the Gaussian width of $T$.

In more effective terms, one example of a consequence of the alternative proof above is the following result: 

\begin{corollary} Let $X$ be a random vector in $\R^n$ satisfying \eqref{eq:small-ball-og} and \eqref{eq:reverse-small-ball}. Then there are $C(\lambda),c(\lambda)>0$ and $c_{11}>0$ such that, with probability at least $1 - e^{-c_{11} n},$ we have that, whenever $m \ge C(\lambda) \cdot s \cdot \log \left( \frac{e \cdot n}{s}\right),$ and $u,v \in \Sigma_s \cap \B_{\R^n},$
\[\frac{1}{m}\sum_{j=1}^m \frac{1}{\|u-v\|_{2}^2}\left|\Phi_{\lambda}(\langle X_i,u\rangle) - \Phi_{\lambda}(\langle X_i,v\rangle)\right|^2 \ge c(\lambda),\]
where $X_i$ are i.i.d.~copies of the vector $X$.
\end{corollary}



\end{remark}

\begin{proposition}[Gin\'e-Zinn symmetrization; Lemma~2.3.1~in~\cite{vanderVaartWellner}]\label{prop:symmetrization} Let $\mathcal{F}$ denote a class of measurable functions, and let $X_1,\dots,X_m$ denote i.i.d.~random variables. Then we have that 
\[
\mathbb{E} \sup_{f \in \mathcal{F}} \left| \frac{1}{m} \sum_{i=1}^m f(X_i) -  \mathbb{E}f(X)\right| \le 2 \cdot \mathbb{E} \sup_{f \in \mathcal{F}} \left| \frac{1}{m} \sum_{i=1}^m \varepsilon_i f(X_i)\right|,
\]
where $\varepsilon_i$ denote i.i.d.~symmetric Bernoulli random variables. 
\end{proposition}

\begin{proposition}[Talagrand's Contraction Principle; Corollary~3.17~in~\cite{Ledoux-Talagrand}]\label{prop:contraction} Let $T \subset \R^n$ be a bounded subset, and let $\varepsilon_1,\dots,\varepsilon_n$ be independent symmetric Bernoulli variables. Let $\phi:\R \to \R$ be a Lipschitz function on the real line satisfying $\phi(0)=0$. Then we have that 
\[
\mathbb{E} \sup_{t \in T} \sum_{i=1}^n \varepsilon_i \phi(t_i) \le \|\phi\|_{\text{Lip}} \cdot \, \mathbb{E} \sup_{t \in T} \sum_{i=1}^n \varepsilon_i t_i. 
\]
\end{proposition}

\begin{proposition}[Talagrand's comparison inequality; Corollary~8.6.2~in~\cite{vershynin2018high}]\label{prop:talagrand-comparison} Let $\{X_t\}_{t\in T}$ be a mean zero random process on a set $T$, and let $\{Y_t\}_{t \in T}$ be a mean zero Gaussian process on the same set. Assume that there is a constant $K>0$  such that for all $s,t \in T$ we have 
\[
\|X_s - X_t\|_{\psi_2} \le K \cdot \|Y_s - Y_t\|_2,
\]
then 
\[
\mathbb{E} \sup_{t \in T} X_t \le C \cdot K \cdot \mathbb{E} \sup_{t\in T} Y_t.
\]
\end{proposition}

