\title{On the rigidity of $k$-step nilpotent \\ graph Lie algebras}
\author{Josefina Barrionuevo $\dag$ and Paulo Tirao $\dag$ 
$\ddag$}


\address{$\dag$ CIEM-FaMAF, CONICET-Universidad Nacional de Córdoba \\
