\subsection{Criteria for 2-step nilpotent Lie algebras}

Let $\n$ be a $k$-step nilpotent Lie algebra of dimension $n$ with bracket $\mu$.
The $k$-rigidity of $\mu$ follows from the vanishing of an adequate cohomolgy group, $H^2_{k\text{-nil}}(\mu,\mu)$ \cite{BTS}.

For $k=2$ it is defined as 
\begin{equation}\label{eqn:H2-nil}
	H^2_{2\text{-nil}}(\mu,\mu)= \frac{\ker(\delta^2)\cap\ker(\eta_2)}{\Im(\delta^1)} = \frac{\ker(\eta_2)}{\Im(\delta^1)},
\end{equation}
where $\delta^1: \Lambda^1 ({\K^n}^*) \to \Lambda^2 ({\K^n}^*)$ and  $\delta^2: \Lambda^2 ({\K^n}^*) \to \Lambda^3 ({\K^n}^*)$
are the differentials of the Chevalley-Eilenberg complex of $\mu$, and $\eta_2: \Lambda^2 ({\K^n}^*) \to \Lambda^3 ({\K^n}^*)$
is defined by
\[ \eta_2(\sigma)(x,y,z)=\mu(\sigma(x,y),z)+\sigma(\mu(x,y),z). \]


\begin{theorem}[\cite{BTS}]
	Let $\mu\in\N_{n,2}$. If $H^2_{2\operatorname{-nil}}(\mu,\mu)=0$, then $\mu$ is $2$-rigid. 
\end{theorem}


To prove non-2-rigidity for 2-step graph Lie algebras, Theorem \ref{thm:non-rigidity-k2} below suffices. 
To prove it we use a preliminary result that can be found in \cite{A}.

Recall that if $\n$ is 2-step nilpotent, then it can be decomposed as $\n=\v\oplus\z$ 
with $\z$ the center of $\n$ and $\v$ any direct complement of it.
If $\n=\g(2,G)$ for a graph $G=(V,E)$ and $\n$ has no abelian factor, then its center is $\z=\langle E \rangle$
and a direct complement is $\v=\langle V \rangle$, so $\g(2,G)=\langle V \rangle \oplus \langle E \rangle$.

\begin{lemma}[Alvarez]
	Let $\n=\v\oplus\z$ be a 2-rigid 2-step nilpotent Lie algebra. 
	Then $\Lambda^2\v^*\otimes\z\subseteq \Im(\delta^1)$. 
\end{lemma}

\begin{proof}
	If $\varphi \in \Lambda^2\v^*\otimes\z$, then 
	$\mu_t=\mu+t\varphi$ is a $2$-step analytic deformation and then is equivalent to the trivial deformation of $\mu$ \cite[Theorem 7.1]{Mm}.
	[In characteristic zero, analytic and geometric rigidity are equivalent.] 
	This implies that $\varphi\in \Im(\delta^1)$. 
\end{proof}

\begin{remark} In \cite{A} there is also the proof of the converse of the previous lemma (that is not necessary in this paper).
\end{remark}

\begin{theorem}\label{thm:non-rigidity-k2}
	Let $\mu\in\N_{n,2}$, with $\n=\v\oplus\z$. 
	If there exist $v,w\in\v$ linearly independent such that, $[v,w]=0$ and $\langle [v,\n]\cup [w,\n]\rangle \subsetneq \z$, then $\mu$ is not $2$-rigid.
\end{theorem}

\begin{proof}
	Choose $z\in \z-\langle [v,\n]\cup [w,\n]\rangle$ and consider
	$\varphi=v^*\wedge w^*\otimes z$.
	On the one hand
	$\varphi\in \Lambda^2\v\otimes \z$. 
	On the other hand $\varphi\notin \Im(\delta^1)$.
	In fact, if $\varphi=\delta^1(f)$ for a linear map $f:\n\rightarrow\n$,
	then
	\begin{eqnarray*}
		(v^*\wedge w^*\otimes z)(v,w) &=& \delta^1f(v,w) \\
		z &=& [f(v),w]+[v,f(w)]-f([v,w]) \\
		z &=& [f(v),w]+[v,f(w)]
	\end{eqnarray*}
	and hence $z\in \langle [v,\n]\cup [w,\n]\rangle$, which is an absurd since we started this proof choosing $z\in \z-\langle [v,\n]\cup [w,\n]\rangle$. 

	Therefore $\Lambda^2\v\otimes\z\not\subseteq \Im(\delta^1)$ and because of the previous lemma $\mu$ is not $2$-rigid.  
\end{proof}






