\section{The rigidity problem for $k$-step nilpotent \\ graph Lie algebras, for $k\ge 3$}


In this section we prove that for $k\ge 3$, the $k$-step nilpotent graph Lie algebras are not $k$-rigid with the only exceptions of
those associated with the complete graphs, the free $k$-step nilpotent Lie algebras.

The following theorem, which provides sufficient conditions to ensure $\g(k,G)$ is not $k$-rigid,
applies to a wider class of naturally graded nilpotent Lie algebras.


\begin{theorem}\label{thm:graded}
	Let $\g=V_1\oplus\dots\oplus V_k$ be a $k$-step nilpotent naturally graded Lie algebra with $k\geq 3$. 
	If there exist two independent commuting elements $a_1, a_2\in V_1$ and $y\in V_k$ such that 
	$y\not\in [\g^1,\g^1]+[a_1,\g^1]+[a_2,\g^1]$, then $\g$ is not $k$-rigid.
\end{theorem}
\begin{proof}
Let $\h$ be the subalgebra $V_1'\oplus V_2\oplus\dots\oplus V_k$, where $V_1'$ is a direct complement of $\langle a_1,a_2\rangle$ in $V_1$.
The elements $a_1,a_2$ and $y$ satisfy the conditions of Theorem \ref{thm:bts}.
So that, if $\mu$ is the bracket of $\g$, we may consider the linear deformation of $\mu$ given by
\[ \mu_t=\mu+t \sigma^{a_1,a_2}_y. \]
It is straightforward that $\mu_t$ is $k$-step nilpotent, for all $t\in\C$.

We prove now that $\mu_t$ is not naturally graded  for all $t\neq 0$ and hence $\g$ is not $k$-rigid.

\medskip

	Supose that $(\g,[\ ,\ ]_t)$ is naturally graded, then there exits a linear decomposition $\g=W_1\oplus\ldots\oplus W_k$ such that  $[W_i,W_j]_t\subseteq W_{i+j}$. Observe the following facts:
	\begin{enumerate}
		\item The central descendent series of $[\ ,\ ]$ and $[\ ,\ ]_t$ are the same, then, $V_j\oplus\ldots\oplus V_k=W_j\oplus\ldots\oplus W_k$,  for all $1\leq j\leq k$.
		\item $a_1, a_2\in V_1$, so  $\a_1, a_2\notin[\g,\g]=[\g,\g]_t=W_2\oplus\ldots\oplus W_k$. Then, the descompositions of $a_1$ and $a_2$ in the direct sum $W_1\oplus\ldots\oplus W_k$ are
		$$
		\begin{aligned}
			a_1&=w_1+w_2+\ldots+w_k=w_1+b\\ 
			a_2&=w_1'+w_2'+\ldots+w_k'=w_1'+c,\\
		\end{aligned}
		$$ 
		with $w_1, w_1'\in W_1$ linear independent and $b, c \in[\g,\g]_t=[\g,\g]$.
		\item Since $b, c\in V_2\oplus\ldots\oplus V_k$, then $[b,v]_t=[b,v]$ and $[c,v]_t=[c,v]$, for all $v\in\g$. 
	\end{enumerate}

	Now, bracketing $a_1$ and $a_2$, we have
	$$
	\begin{aligned}
		ty&=[a_1,a_2]_t\\
		&=[w_1+b,w_1'+c]_t\\
		&=\underbrace{[w_1,w_1']_t}_{\in W_2}+\underbrace{[w_1,c]_t+[b,w_1']_t+[b,c]_t}_{\in W_3\oplus\ldots\oplus W_k}\\
	\end{aligned}
	$$
	Since $ty\in V_k=W_k$ and $k\geq3$, then $[w_1,w_1']_t=0$ and 
	$$
	\begin{aligned}
		ty&=[w_1,c]_t+[b,w_1']_t+[b,c]_t\\
		&=[a_1-b,c]_t+[b,a_2-c]_t+[b,c]_t\\
		&=[a_1,c]_t-[b,c]_t+[b,a_2]_t-[b,c]_t+[b,c]_t\\
		&=[a_1,c]_t-[b,c]_t+[b,a_2]_t\\
		&=[a_1,c]-[b,c]+[b,a_2]\,.\\
	\end{aligned}
	$$
	From this, we have $ty\in\g^{(2)}+[a_1,\g^1]+[a_2,\g^1]$ and then $t=0$.
\end{proof}

From the previous theorem, for the particular case $k=3$, we have the following corollary. 

\begin{corollary}
 Let $\g=V_1\oplus V_2\oplus V_3$ be a $3$-step nilpotent naturally graded Lie algebra, if there exist linear independent elements  $a_1, a_2\in V_1$
 such that $[a_1,a_2]=0$, and  $y\in V_3$ such that $y$ is not an element of the vector space $[a_1,V_2]+[a_2,V_2]$, then $\g$ is not $3$-rigid.
\end{corollary}		


The main result of this section is now straightforward.

\begin{theorem}\label{thm:k3}
	Let $G=(V,E)$ be a simple graph with $|V|\ge 3$ which is not a complete graph and let $k\ge 3$.
	Then the $k$-step nilpotent Lie algebra $\g=\g(k,G)$ is not $k$-rigid.
\end{theorem}

\begin{proof}
We may assume that $G$ has at least one edge, otherwise $\g$ is abelian and not $k$-rigid.
 Since $|V|\ge 3$ and $G$ is not the complete graph, there are vertices $v_1,v_2,v_3$ such that $\{v_1,v_2\}$ is an edge and
 $\{v_2,v_3\}$ is not an edge of $G$.

By declaring $v_1<v_2<v_3$ and considering the basis given in Subsection \ref{subsec:hall}, we have that
$y=[v_1,[v_1,[\dots,[v_1,v_2]\dots]]]$ with multidegree $d(y)=(k-1,1,0,\dots,0)$ is a basis element in $V_k$.
Observe that it follows from \eqref{eqn:multidegree} that $y\not\in [\g^1,\g^1]+[v_2,\g^1]+[v_3,\g^1]$. 
Hence, by Theorem \ref{thm:graded}, $\g=\g(k,G)$ is not $k$-rigid.
\end{proof}



