\smallskip

\textbf{Case 2.} Suppose that $p+1\leq 3a\leq 2p$. Since $p\geq 11$ we observe that $a\geq 4$. 
In this case we have that $\mathcal{B}_n(r+(a-3)p)=\mathcal{B}_n(n-3p)\subseteq\mathcal{B}_n(ap-3a)$. This shows that if $\lambda\in\Delta$ then $N_p(\lambda)\geq a-2$. In particular $N_p(\lambda)\in\{a-2, a-1,a\}$ and $\Delta\subseteq \Delta_{a-2}\cup\Delta_{a-1}\cup\Delta_a$. 
Since $a\geq 4$, from Lemma \ref{lem: sizeDelta} we know that $|\Delta_{a-1}\cup\Delta_a|=2p^2+2p$. 

\smallskip


\noindent\textbf{- Subcase (2.1)} We first assume that $a\geq 6$. 
From Lemma \ref{lem: sizeDelta} we have that 
$$|\Delta_{a-2}|=p^3+3p^2.$$
Moreover, for any $\lambda\in\Delta_{a-2}$ we claim that $$\chi^\lambda(1)\geq \frac{1}{2}ap(ap-3)\cdot\chi^\gamma(1).$$ To see this, notice first that
$\Delta_{a-2}\subseteq\mathcal{B}_n(r+(a-2)p)=\mathcal{B}_n(n-2p)$ by Proposition \ref{prop: decisiva}. 
Since $\mathcal{B}_n(n-2p)=\mathcal{B}_n(ap-(2p-r))$ we deduce that there exists $\mu\in\mathcal{B}_{ap}(ap-(2p-r))\subseteq \mathcal{B}_{ap}(ap-p)$ such that $\mathrm{LR}(\lambda; \gamma, \mu)\neq 0$. From Lemma \ref{lem: Rasala2} we have that $\chi^\mu(1)\geq \frac{1}{2}ap(ap-3)$ and therefore that $\chi^\lambda(1)\geq \frac{1}{2}ap(ap-3)\cdot\chi^\gamma(1)$, as claimed. 

We now consider the following subsets of $\mathrm{Irr}_{p'}(N_{ap})$. We let $X(1)$ and $Y(1)$ be defined exactly as in Case 1 above, and we further consider: 
$$W=\{(\mathcal{X}(\phi; \chi^\nu)\times\eta_1\times\eta_2)^{N_{ap}}\ |\ \phi,\eta_1,\eta_2\in\mathrm{Lin}(N_{p}),\ \nu\in\{(a-2), (a-3,1)\}^{\circ}\},$$
$$V=\{(\mathcal{X}(\phi; \chi^\nu)\times\mathcal{X}(\eta; \chi^\rho))^{N_{ap}}\ |\ \phi,\eta\in\mathrm{Lin}(N_{p}),\ \nu\in\{(a-2), (a-3,1)\}^{\circ},\  \rho\in\{(2)\}^{\circ}\}.$$
As usual, or any $Z\subseteq \mathrm{Irr}_{p'}(N_{ap})$ we denote by $\overline{Z}$ the subset of $\mathrm{Irr}_{p'}(N_{n}\ |\ \gamma)$ defined by 
$$\overline{Z}=\{\theta\times\chi^\gamma\ |\ \theta\in Z\}.$$
Clearly $|Z|=|\overline{Z}|$, for every $Z\subseteq\mathrm{Irr}_{p'}(N_{ap})$. 

\smallskip

We collect a few observations concerning $W$ and $V$. 

\smallskip

\noindent\textbf{(a)} In the definition of the set $W$ the linear characters $\phi$, $\eta_1$ and $\eta_2$ are chosen to be pairwise distinct, so that $\mathcal{X}(\phi; \chi^\nu)\times\eta_1\times\eta_2$ is an irreducible character of $N_{(a-2)p}\times N_p\times N_{p}\leq N_{ap}$ that induces irreducibly to $N_{ap}$. 
In particular we have that $\theta(1)\leq a(a-1)(a-3)$, for every $\theta\in W$.

\smallskip

\noindent\textbf{(b)} In the definition of the set $V$ the linear characters $\phi$ and $\eta$ are chosen to be distinct, so that $\mathcal{X}(\phi; \chi^\nu)\times\mathcal{X}(\eta; \chi^\rho)$ is an irreducible character of $N_{(a-2)p}\times N_{2p}\leq N_{ap}$ that induces irreducibly to $N_{ap}$. 
In particular we have that $\theta(1)\leq \frac{1}{2}a(a-1)(a-3)$, for every $\theta\in V$.

\smallskip

\noindent\textbf{(c)} From $(a), (b)$ we conclude that $\theta(1)\leq a(a-1)(a-3)\leq \frac{1}{2}ap(ap-3)$, for every $\theta\in W\cup V$. In particular, for every $\zeta\in\overline{W}\cup\overline{V}$ we have that 
$$\zeta(1)\leq \frac{1}{2}ap(ap-3)\cdot\chi^\gamma(1)\leq \chi^\lambda(1),\ \ \text{for all}\ \lambda\in\Delta_{a-2}.$$

\smallskip

Using Corollary \ref{cor: linN} and recalling that $a\geq 6$ it is easy to see that
$$|W|=4(p-1){p-2\choose 2}=2p^3-12p^2+22p-12,\ |V|=4\cdot2\cdot(p-1)(p-2)=8p^2-24p+16.$$
Since $p\geq 11$, a straightforward calculation shows that $|\overline{W}\cup\overline{V}|\geq |\Delta_{a-2}|$.

Arguing exactly as in Case 1, all the observations above allow us to deduce that
there exists an injective map $$\varphi: \Delta_a\cup\Delta_{a-1}\cup\Delta_{a-2}\rightarrow \overline{X(1)}\cup\overline{Y(1)}\cup\overline{W}\cup\overline{V}\subseteq\mathrm{Irr}_{p'}(N_n\ |\ \gamma),$$
such that $\varphi(\Delta_a\cup\Delta_{a-1})\subseteq  \overline{X(1)}\cup\overline{Y(1)}$, $\varphi(\Delta_{a-2})\subseteq  \overline{W}\cup\overline{V}$, and such that $\varphi(\lambda)(1)\leq \chi^\lambda(1)$ for every $\lambda\in\Delta_a\cup\Delta_{a-1}\cup\Delta_{a-2}$.


\smallskip


\noindent\textbf{- Subcase (2.2)} We now consider the case \( 4 \leq a \leq 5 \). Here, \( p \in \{11,13\} \), and the argument closely parallels that of Subcase~(2.1), with only minor adjustments required. It follows that there exists an injective map \( \varphi: \Delta \rightarrow \mathrm{Irr}_{p'}(N_n\ |\ \gamma) \) such that \( \varphi(\lambda)(1) \leq \chi^\lambda(1) \) for every \( \lambda \in \Delta \). We therefore omit the technical details.

\smallskip

\textbf{Case 3.} Suppose that $2p+1\leq 3a< 3p$. Since $p\geq 11$ we observe that $a\geq 8$. 
In this case we have that $\mathcal{B}_n(r+(a-4)p)=\mathcal{B}_n(n-4p)\subseteq\mathcal{B}_n(ap-3a)$. This shows that if $\lambda\in\Delta$ then $N_p(\lambda)\geq a-3$, by Proposition \ref{prop: decisiva}. In particular $N_p(\lambda)\in\{a-3,a-2, a-1,a\}$ and $\Delta\subseteq \Delta_{a-3}\cup\Gamma$, where $\Gamma=\Delta_{a-2}\cup\Delta_{a-1}\cup\Delta_a$. Recycling the notation and the arguments used in Cases 1 and 2, we consider the subsets 
$\overline{X(1)}, \overline{Y(1)}, \overline{W}, \overline{V}\subseteq\mathrm{Irr}_{p'}(N_n\ |\ \gamma)$ and we observe that there exists an injective map $$\varphi: \Delta_a\cup\Delta_{a-1}\cup\Delta_{a-2}\rightarrow \overline{X(1)}\cup\overline{Y(1)}\cup\overline{W}\cup\overline{V}\subseteq\mathrm{Irr}_{p'}(N_n\ |\ \gamma),$$
such that $\varphi(\Delta_a\cup\Delta_{a-1})\subseteq  \overline{X(1)}\cup\overline{Y(1)}$, $\varphi(\Delta_{a-2})\subseteq  \overline{W}\cup\overline{V}$, and such that $\varphi(\lambda)(1)\leq \chi^\lambda(1)$ for every $\lambda\in\Delta_a\cup\Delta_{a-1}\cup\Delta_{a-2}$. Let $A=\overline{X(1)}\cup\overline{Y(1)}\cup\overline{W}\cup\overline{V}$, to conclude the proof we just need to find a second injective map $f:\Delta_{a-3}\rightarrow\mathrm{Irr}_{p'}(N_n\ |\ \gamma)\smallsetminus A$ such that $f(\lambda)(1)\leq \chi^\lambda(1)$ for every $\lambda\in\Delta_{a-3}$. 
To this end, we consider the subset $Z\subseteq\mathrm{Irr}_{p'}(N_{ap})$ defined by
$$Z=\{(\mathcal{X}(\phi; \chi^\nu)\times\mathcal{X}(\eta; \chi^\rho)\times\eta_1\times\eta_2)^{N_{ap}}\ |\ \phi,\eta,\eta_1,\eta_2\in\mathrm{Lin}(N_{p}),\ \nu\in\{(a-4)\}^{\circ},\  \rho\in\{(2)\}^{\circ}\}.$$
As usual, we denote by $\overline{Z}$ the subset of $\mathrm{Irr}_{p'}(N_{n}\ |\ \gamma)$ defined by 
$$\overline{Z}=\{\theta\times\chi^\gamma\ |\ \theta\in Z\}.$$
Clearly $|Z|=|\overline{Z}|$, and $\overline{Z}\subseteq\mathrm{Irr}_{p'}(N_n\ |\ \gamma)\smallsetminus A$. 

We collect a few observations on the sets $Z$ and $\Delta_{a-3}$.

\smallskip

\noindent\textbf{(a)} In the definition of the set $Z$ the linear characters $\phi$, $\eta$, $\eta_1$ and $\eta_2$ are chosen to be pairwise distinct, so that $\mathcal{X}(\phi; \chi^\nu)\times\mathcal{X}(\eta; \chi^\rho)\times\eta_1\times\eta_2$ is an irreducible character of $N_{(a-4)p}\times N_{2p}\times N_{p}\times N_p\leq N_{ap}$ that induces irreducibly to $N_{ap}$. 
In particular we have $$\theta(1)\leq \frac{1}{2}a(a-1)(a-2)(a-3),\ \text{for every}\ \theta\in Z.$$

\smallskip

\noindent\textbf{(b)} By Proposition \ref{prop: decisiva} we have that $\Delta_{a-3}\subseteq \mathcal{B}_n(r+(a-3)p)\subseteq\mathcal{B}_n(ap-2p)$. Hence, using Lemma \ref{lem: Rasala2} and arguing exactly as in Case 2 above, we deduce that $$\chi^\lambda(1)\geq\frac{1}{2}ap(ap-3)\chi^\gamma(1),\ \text{for every}\ \lambda\in \Delta_{a-3}.$$ 

\smallskip

\noindent\textbf{(c)} Recalling that $a\geq 8$, from observations (a) and (b) we deduce that $$\theta(1)\leq\chi^\lambda(1)\ \text{for every}\ \theta\in\overline{Z}\ \text{and every}\ \lambda\in\Delta_{a-3}.$$ 

\smallskip

\noindent\textbf{(d)} Arguing exactly as in the proof of Lemma \ref{lem: sizeDelta} by counting the number of possible different $p$-quotients $Q_p(\lambda)$ of total size $a$ such that $N_p(\lambda)=a-3$, we deduce that 
$$|\Delta_{a-3}|=p^2(\frac{1}{3}p^2+3p+\frac{8}{3}).$$

\smallskip

\noindent\textbf{(e)} On the other hand, it is easy to see that $$|\overline{Z}|=|Z|=2(p-1)(p-2)(p-3)(p-4)=2p^4-20p^3+70p^2-100p+48.$$

Since $p\geq 11$, using observations (d) and (e), it is routine to check that $|\overline{Z}|\geq \Delta_{a-3}$. Therefore, using observation $(c)$ as well, we deduce that there exists an injective map $$f:\Delta_{a-3}\rightarrow \overline{Z}\subseteq\mathrm{Irr}_{p'}(N_n\ |\ \gamma)\smallsetminus A,$$ such that $f(\lambda)(1)\leq \chi^\lambda(1)$ for every $\lambda\in\Delta_{a-3}$. This concludes the proof. 
\end{proof}

\section{Appendix}\label{sec: 6}

This section is devoted to collecting a few elementary analytic observations used to justify some of the inequalities appearing in the article. We have chosen to present these results separately in an appendix in order to make the main body of the paper easier to read.

\begin{lem}\label{lem: analisi1}
Let $a,p,k\in\mathbb{R}$ be such that $k\geq 2$, $p\geq 5$ and $a\in [1,p-1]$. Then $$ap\6{k-1}\geq ak+(a-1)+(p-2).$$
\end{lem}
\begin{proof}
If $k=2$ then consider $f(a,p)=ap-3a-p+3$. It is easy to see that $f(a,p)=a(p-3)-(p-3)\geq 0$, for all $p\geq 5$ and all $a\in [1,p-1]$. Hence the statement holds in this case. 

Let us now assume that $k\geq 3$. Since $a\leq p-1$ we have that $$ak+(a-1)+(p-2)\leq (p-1)(k+2)-2\leq p(k+2).$$ On the other hand, $ap\6{k-1}\geq p\6{k-1}$. Let $h(k,p)=p\6{k-2}-(k+2)$ and let
 $$g(k,p)=p\6{k-1}-p(k+2)=p(p\6{k-2}-(k+2))=p\cdot h(k,p),$$
be defined on $D=\{(k,p)\ |\ k\geq 3, p\geq 5\}\subseteq \mathbb{R}\6{2}$. It is easy to see that $\frac{d}{dp}h(k,p)=(k-2)p\6{k-3}\geq 0$ for all $(k,p)\in D$. Similarly $\frac{d}{dk}h(k,p)=p\6{k-2}\mathrm{log}(p)-1\geq 0$ for all $(k,p)\in D$. It follows that for any $(k,p)\in D$ we have that $g(k,p)\geq g(3,5)=0$. We conclude that 
$$ap\6{k-1}\geq p\6{k-1}\geq  p(k+2)\geq (p-1)(k+2)-2\geq ak+(a-1)+(p-2),$$
as desired.
\end{proof}

\begin{lem}\label{lem: Pediconi}
Let $f(p,k)$ be the function of two real variables defined by $$f(p,k)=(p-1)\6{3k}+3(p-1)\6{k}-2p\6{2k}-2p\6{k}.$$
Then $f(p,k)\geq 0$ for all $p,k\in\mathbb{R}$ such that $k\geq 2$ and $p\geq 5$. 
\end{lem}
\begin{proof}
Since $2p\6{2k}+2p\6{k}\leq 4p^{2k}$ we have that $$f(p,k)\geq (p-1)\6{3k}-4p^{2k}=p^{2k}\big(\frac{(p-1)^{3k}}{p^{2k}}-4\big).$$
Let us consider the function $$h(x,y)=\frac{x^{3y}}{(x+1)^{2y}}-4,\ \text{on the domain}\ D=\{(x,y)\in\mathbb{R}^2\ |\ x\geq 4, y\geq 2\}.$$
Notice that $h(x,y)=e^{yg(x)}-4$, where $g(x)=3\mathrm{log}(x)-2\mathrm{log}(x+1)$.
Since $$g'(x)=\frac{3}{x}-\frac{2}{x+1}=\frac{x+3}{x(x+1)}>0,\ \text{for all}\ x\geq 4,$$
we deduce that the function $h(x,y)$ is increasing in both $x$ and $y$. Since $h(4,2)>0$ we deduce that $h(x,y)>0$ for every $(x,y)\in D$. We conclude that 
$$f(p,k)\geq p^{2k}\cdot h(p-1,k)\geq 0,\ \text{for every}\ k\geq 2\ \text{and every}\ p\geq 5.$$
\end{proof}

\begin{lem}\label{lem: Pediconi3}
Let $f(p,k)$ be the function of two real variables defined by $$f(p,k)=\frac{1}{6}(p-1)\6{3k}+\frac{3}{2}(p-1)\6{2k}+\frac{4}{3}(p-1)^k-2p\6{2k}-p\6{k}.$$
Then $f(p,k)\geq 0$ for all $p,k\in\mathbb{R}$ such that $k\geq 2$ and $p\geq 7$. Moreover, $f(5,k)\geq 0$, for all $k\geq 3$.
\end{lem}
\begin{proof}
Observe that $f(p,k)\geq \frac{1}{6}(p-1)^{3k}-2p^{2k}=\frac{1}{6}p^{2k}\big(\frac{(p-1)^{3k}}{p^{2k}}-12\big)$. Considering the function $h(x,y)=\frac{x^{3y}}{(x+1)^{2y}}-12$ on the domain $D=\{(x,y)\in\mathbb{R}^2\ |\ x\geq 4, y\geq 2\}$, observing that $h(4,3)\geq 0$ and that $h(6,2)\geq 0$, and arguing exactly as in the proof of Lemma \ref{lem: Pediconi} we conclude the proof. 
\end{proof}

