\section{Preliminaries}
\label{sec:Preliminaries}
In this section, we formulate the high frequency trading task mathematically.
High-frequency trading utilizes automated algorithms for order execution at extremely high speeds, often operating within millisecond or nanosecond timescales. The objective is to continuously place buy (bid) and sell (ask) limit orders for a specific financial instrument, while aiming to profit from the bid-ask spread.

We can model the HFT market making task as a stochastic control process \cite{avellaneda2008high, gueant2013dealing} defined over a set of discrete time steps $\mathbb{T}=\{0, 1, \dots, T\}$. The \textbf{observation state space} $\mathcal{O}$ captures relevant information at time $t \in \mathbb{T}$. An observation state $O_t \in \mathcal{O}$ typically includes observable market information $L_t$ (often derived from the Limit Order Book, LOB, including stock prices and bid-ask spread) and the agent's information $Z_t$, including balance, current inventory level , along with the time $t$ itself, such that $\mathcal{O} \subseteq \mathcal{L} \times \mathbb{Z} \times \mathbb{T}$, where $\mathcal{L}$, $\mathbb{Z}$ is the space of market information and agent information, respectively. We generally assume the state $S_t$ satisfies the Markov property.

Within this framework, the market maker chooses an \textbf{action} $A_t$ from the \textbf{action space} $\mathcal{A}$. A common action involves setting the agent's bid and ask quotes, often parameterized by spreads $(\delta^b_t, \delta^a_t)$ relative to a reference price $p^{ref}_t$ derived from the market state $L_t$. The system's evolution is governed by stochastic transition probabilities $P(O_{t+1} | O_t, A_t)$, defining the likelihood of moving to the next observation state $O_{t+1}=(L_{t+1}, I_{t+1}, t+1)$ given the current state and action. This transition reflects changes in both market conditions $L_{t+1}$ and the agent's inventory $I_{t+1}$ due to order executions and market activity. The agent seeks an optimal \textbf{policy} $\pi: \mathcal{O} \to \mathcal{A}$, a rule mapping states to actions ($A_t = \pi(O_t)$), that maximizes a defined \textbf{objective function}, $J(\pi)$. A standard objective is to maximize the expected final value, often combining terminal cash wealth $W_T$ with a penalty $\phi(I_T)$ for inventory risk at the horizon $T$. The optimization problem is thus:
\begin{equation} \label{eq:mm_objective}
\max_{\pi} J(\pi) = \max_{\pi} \mathbb{E}^{\pi} \left[ W_T - \phi(I_T) \mid O_0 \right]
\end{equation}
Where, $\mathbb{E}^{\pi}[\cdot]$ denotes the expectation under policy $\pi$ starting from the initial observation state $O_0 = (L_0, I_0, 0)$. Solving for the optimal policy $\pi^* = \arg\max_{\pi} J(\pi)$ requires dynamically balancing profitability against inventory and adverse selection risks in a complex, stochastic environment.




\section{Architecture of FlowHFT}
\label{sec:Architecture of FlowHFT}







\subsection{Backbone of FlowHFT: Flow Matching Policy}
\label{sec:flow_matching_policy}

\begin{figure}[htp]
\caption{This figure illustrates the training of a flow matching policy. The inputs are various market situations. For each situation, the best expert is chosen from a pool of models. These optimal market-expert pairings are then used to train the flow matching policy, which operates as a vector field. This field maps the distribution of market conditions to a corresponding optimal action distribution.}
\label{}
\centering
\includegraphics[width=1\textwidth]{figures/trainingillustration.pdf}
\end{figure}

The core of FlowHFT is a conditional flow matching policy \cite{lipman2022flow}, denoted $\pi_{\theta}(A_{t+1}\mid O_t)$, which learns to map sequences of market observations $O_t$ to trading actions $A_{t+1}$. This policy is trained via imitation learning from expert demonstrations. We draw inspiration from recent successes of flow matching in domains like robotics, where these models effectively learn complex, continuous control policies from expert data by mapping high-dimensional inputs to sophisticated, sequential actions.

Our objective is to train a neural network $v_{\theta}(a, t \mid O_t)$ to parameterize a conditional vector field. This vector field defines a probability flow that transports samples from a simple prior distribution $p_{\mathrm{prior}}(a_0)$ (e.g., Gaussian noise) to the distribution of expert trading action sequences $p_{\mathrm{expert}}(a_E \mid O_t)$, conditioned on the observed market state $O_t$. Following seminal work on flow matching, we define a time-dependent probability path $p_t(a \mid a_0, a_E, O_t)$ that interpolates between an initial random action sequence $a_0$ and an expert action sequence $a_E$. A simple linear interpolation is given by:
$
a_t = (1 - t)\,a_0 + t\,a_E,
    \quad
    u_t(a_t \mid a_0, a_E) = a_E - a_0
$.
% \begin{equation}
%     a_t = (1 - t)\,a_0 + t\,a_E,
%     \quad
%     u_t(a_t \mid a_0, a_E) = a_E - a_0.
% \end{equation}
The training procedure (Algorithm~\ref{alg:fm_training}) minimizes the discrepancy between the network's predicted vector field $v_{\theta}(a_t, t \mid O_t)$ and the target vector field $u_t(a_t \mid a_0, a_E)$. Specifically, given a market state $O_t$, the model samples a random initial action sequence $a_0 \sim p_{\mathrm{prior}}$ and a corresponding expert action sequence $a_E \sim p_{\mathrm{expert}}(\cdot \mid O_t)$. It then samples a time $t \sim \mathcal{U}(0,1)$ and forms an interpolated action sequence $a_t$ using the defined path. The network is trained by minimizing the following Flow Matching (FM) loss:

\begin{equation}
\mathcal{L}_{\mathrm{FM}}(\theta) = \mathbb{E}_{t, O_t, a_0, a_E, a_t \sim p_t(a\mid a_0,a_E,O_t)} \left[ \| v_{\theta}(a_t, t \mid O_t) - u_t(a_t \mid a_0, a_E) \|^2 \right].
\label{eq:fm_loss}
\end{equation}

This objective effectively teaches the network $v_{\theta}$ to generate the flow that transforms noise into expert-like HFT action sequences conditioned on the market state.




\begin{equation}
    a_{k+1} = a_k + \frac{1}{N} \; v_{\theta}(a_k, t_k \mid O_t),
    \quad
    t_k = k/N,
    \; k = 0, \dots, N-1.
\label{eq:fm_inference}
\end{equation}



\begin{algorithm}[htbp]
\SetKwInput{KwData}{Input}
\SetKwInput{KwParam}{Parameters}
\SetKwRepeat{Do}{do}{until}
\caption{Flow Matching Policy Training }
\label{alg:fm_training}
\KwParam{Neural network $v_{\theta}(a, t | O_t)$ with parameters $\theta$, learning rate $\eta$}
\KwData{Expert demonstration data $D_{\text{expert}}$ containing pairs of $(O_t, a_E(O_t))$} % Or access to p_expert

\Do{not converged}{
    Sample a market observation $O_t$ and corresponding expert action sequence $a_E \sim p_{\text{expert}}(\cdot | O_t)$ from $D_{\text{expert}}$ (or generate via simulation/expert)\;
    Sample an initial action sequence $a_0 \sim p_{\text{prior}}(\cdot)$ (e.g., $a_0 \sim \mathcal{N}(0, I)$)\;
    Sample a time $t_{\text{sample}} \sim \mathcal{U}(0,1)$\;

    % \tcp{Construct the interpolated action sequence and target vector field}
    $a_{t_{\text{sample}}} \leftarrow (1 - t_{\text{sample}})a_0 + t_{\text{sample}}a_E$\;
    $u_{t_{\text{sample}}} \leftarrow a_E - a_0$\;

    % \tcp{Compute predicted vector field and loss}
    $\hat{v}_{t_{\text{sample}}} \leftarrow v_{\theta}(a_{t_{\text{sample}}}, t_{\text{sample}} | O_t)$\;
    $\mathcal{L} \leftarrow \| \hat{v}_{t_{\text{sample}}} - u_{t_{\text{sample}}} \|^2$ 
    % \tcp*[r]{Corresponds to the expectation in Eq.~\eqref{eq:fm_loss}}

    % \tcp{Update policy parameters}
    $\theta \leftarrow \theta - \eta \nabla_{\theta} \mathcal{L}$\;
}
\end{algorithm}



At inference (Algorithm~\ref{alg:fm_sampling}), to generate an action sequence conditioned on a live market observation $O_t$, the policy starts with an action sequence $a_0 \sim p_{\mathrm{prior}}$. It then iteratively refines this sequence by solving the ordinary differential equation:
$
\frac{da}{dt} = v_{\theta}(a, t \mid O_t),
$
from $t=0$ to $t=1$. This is typically achieved using a numerical ODE solver (e.g., Euler or Heun method) over a small number of discretization steps $N$. This process transforms the initial noise sequence into a coherent, market-aware sequence of high-frequency trading actions.


\begin{algorithm}[htbp]
\SetKwInput{KwData}{Input}
% \SetKwOutput{KwOut}{Output}
\SetKwInput{KwParam}{Parameters}
\caption{Flow Matching Policy Inference}
\label{alg:fm_sampling}
\KwParam{Trained policy network $v_{\theta}(a, t | O_t)$, Number of discretization steps $N$}
\KwData{Current market observation $O_t^{\text{current}}$}
$a \sim p_{\text{prior}}(\cdot)$ (e.g., $a \sim \mathcal{N}(0, I)$) \\
% \tcp*[r]{Initialize action sequence from prior}
$t_{\text{current}} \leftarrow 0$\;
$\Delta t_{\text{step}} \leftarrow 1/N$\;

\For{$k \leftarrow 0$ \KwTo $N-1$}{
    $v_k \leftarrow v_{\theta}(a, t_{\text{current}} | O_t^{\text{current}})$  \\
    % \tcp*[r]{Query the learned vector field}
    $a \leftarrow a + v_k \cdot \Delta t_{\text{step}}$\\
    % \tcp*[r]{Update action sequence as in Eq.~\eqref{eq:fm_inference}}
    $t_{\text{current}} \leftarrow t_{\text{current}} + \Delta t_{\text{step}}$\;
}

\KwOut{$a$} 
% \tcp*[r]{Generated action sequence}
\end{algorithm}



