\subsection{IMO 2020 P2}
\begin{minted}[fontsize=\small, breaklines, linenos, bgcolor=gray!10]{lean}
-- Solution to IMO 2020 P2 by DRP-IMO

import Mathlib
import Aesop

set_option maxHeartbeats 0

open BigOperators Real Nat Topology Rat 

/--Consider four real numbers \( a, b, c, \) and \( d \) such that \( 0 < d \leq c \leq b \leq a \) and their sum is equal to 1, i.e., \( a + b + c + d = 1 \). Prove that the product of the weighted sum \( a + 2b + 3c + 4d \) and the sum of their squares \( a^2 + b^2 + c^2 + d^2 \) is less than 1.-/
theorem weighted_sum_times_sum_sq_lt_one (a b c d : ℝ) (hd_pos : 0 < d) (hdc : d ≤ c) (hcb : c ≤ b) (hba : b ≤ a) (h_sum_eq_1 : a + b + c + d = 1) :
  (a + 2*b + 3*c + 4*d) * (a^2 + b^2 + c^2 + d^2) < 1 := by
  have h_a_lt_one : a < 1 := by
    have h₁ : a + b + c + d = 1 := h_sum_eq_1
    have h₂ : 0 < b := by linarith
    have h₃ : 0 < c := by linarith
    have h₄ : 0 < d := hd_pos
    nlinarith

  have h_b_lt_one : b < 1 := by
    have h₁ : a ≥ b := by linarith
    have h₂ : a < 1 := h_a_lt_one
    nlinarith

  have h_c_lt_one : c < 1 := by
    have h₁ : b ≥ c := by linarith
    have h₂ : b < 1 := h_b_lt_one
    nlinarith

  have h_d_lt_one : d < 1 := by
    have h₁ : c ≥ d := by linarith
    have h₂ : c < 1 := h_c_lt_one
    nlinarith

  have h_a2_lt_a : a^2 < a := by
    have h₁ : a < 1 := h_a_lt_one
    have h₂ : a > 0 := by linarith
    nlinarith [sq_pos_of_pos h₂]
    <;> nlinarith

  have h_b2_lt_b : b^2 < b := by
    have h₁ : b < 1 := h_b_lt_one
    have h₂ : b > 0 := by linarith
    nlinarith [sq_pos_of_pos h₂]
    <;> nlinarith

  have h_c2_lt_c : c^2 < c := by
    have h₁ : c < 1 := h_c_lt_one
    have h₂ : c > 0 := by linarith
    nlinarith [sq_pos_of_pos h₂]
    <;> nlinarith

  have h_d2_lt_d : d^2 < d := by
    have h₁ : d < 1 := h_d_lt_one
    have h₂ : d > 0 := hd_pos
    nlinarith [sq_pos_of_pos h₂]
    <;> nlinarith

  have h_sum_sq_lt_one : a^2 + b^2 + c^2 + d^2 < 1 := by
    nlinarith [h_a2_lt_a, h_b2_lt_b, h_c2_lt_c, h_d2_lt_d]
    <;> linarith

  have h_main : (a + 2*b + 3*c + 4*d) * (a^2 + b^2 + c^2 + d^2) < 1 := by
    have h₁ : 0 < a + 2 * b + 3 * c + 4 * d := by
      nlinarith [hd_pos, hcb, hba, hdc, h_sum_eq_1]
    have h₂ : a ^ 2 + b ^ 2 + c ^ 2 + d ^ 2 < 1 := h_sum_sq_lt_one
    nlinarith [h₁, h₂]
    <;> nlinarith

  exact h_main


theorem vars_are_in_0_1 (a b c d : ℝ) (hd0 : 0 < d) (hdc : d ≤ c) (hcb : c ≤ b) (hba : b ≤ a) (h1 : a + b + c + d = 1) :
  (0 < a ∧ a < 1) ∧ (0 < b ∧ b < 1) ∧ (0 < c ∧ c < 1) ∧ (0 < d ∧ d < 1) := by
  have h_a_pos : 0 < a := by
    nlinarith [hdc, hcb, hba, hd0, h1]
    <;> nlinarith

  have h_a_lt_1 : a < 1 := by
    have h2 : a < 1 := by
      nlinarith [h1, h_a_pos, hba, hcb, hdc, hd0]
    exact h2

  have h_b_pos : 0 < b := by
    nlinarith [hdc, hcb, hba, hd0, h1]

  have h_b_lt_1 : b < 1 := by
    have h2 : b < 1 := by
      nlinarith [h1, h_a_pos, h_a_lt_1, hba, hcb, hdc, hd0]
    exact h2

  have h_c_pos : 0 < c := by
    nlinarith [hdc, hcb, hba, hd0, h1]

  have h_c_lt_1 : c < 1 := by
    have h2 : c < 1 := by
      nlinarith [h1, h_a_pos, h_a_lt_1, h_b_pos, h_b_lt_1, hba, hcb, hdc, hd0]
    exact h2

  have h_d_pos : 0 < d := by
    exact hd0

  have h_d_lt_1 : d < 1 := by
    have h2 : d < 1 := by
      nlinarith [h1, h_a_pos, h_a_lt_1, h_b_pos, h_b_lt_1, h_c_pos, h_c_lt_1, hdc, hcb, hba, hd0]
    exact h2

  refine' ⟨⟨h_a_pos, h_a_lt_1⟩, ⟨h_b_pos, h_b_lt_1⟩, ⟨h_c_pos, h_c_lt_1⟩, ⟨h_d_pos, h_d_lt_1⟩⟩


theorem imo2020_q2 (a b c d : ℝ) (hd0 : 0 < d) (hdc : d ≤ c) (hcb : c ≤ b) (hba : b ≤ a) (h1 : a + b + c + d = 1) :
    (a + 2 * b + 3 * c + 4 * d) * (a ^ a * b ^ b * c ^ c * d ^ d) < 1 := by
  -- strategy:
  -- 1. apply weighted AM-GM inequality to prove a^a * b^b * c^c * d^d ≤ a^2 + b^2 + c^2 + d^2
  -- 2. ues subgoal 'weighted_sum_times_sum_sq_lt_one' to get (a + 2*b + ...) * (a^2 + b^2 + ...) < 1
  -- 3. combine both results to reach final conclusion

  -- define S
  let S := a^2 + b^2 + c^2 + d^2

  -- step 1: apply weighted AM-GM inequality
  -- we need to prove a^a * b^b * c^c * d^d ≤ S
  have h_geom_mean_le_sum_sq : a ^ a * b ^ b * c ^ c * d ^ d ≤ S := by
    -- in order to use the subgoal 'geom_mean_le_arith_mean_weighted', we use Fin 4 as an index type
    let w : Fin 4 → ℝ := ![a, b, c, d]
    let z : Fin 4 → ℝ := ![a, b, c, d]

    -- check AM-GM prerequisite
    have h_pos_conds : (0 < a) ∧ (0 < b) ∧ (0 < c) ∧ (0 < d) := by
      have h_all := vars_are_in_0_1 a b c d hd0 hdc hcb hba h1
      exact ⟨h_all.1.1, h_all.2.1.1, h_all.2.2.1.1, h_all.2.2.2.1⟩

    -- 1. non-negative weights
    have h_weights_nonneg : ∀ i, 0 ≤ w i := by
      intro i; fin_cases i <;> simp [w] <;> linarith [h_pos_conds.1, h_pos_conds.2.1, h_pos_conds.2.2.1, h_pos_conds.2.2.2]

    -- 2. weights sum-up to 1
    have h_weights_sum_1 : ∑ i, w i = 1 := by
      simp [w, Fin.sum_univ_four, h1]

    -- 3. non-negative values
    have h_values_nonneg : ∀ i, 0 ≤ z i := by
      intro i; fin_cases i <;> simp [z] <;> linarith [h_pos_conds.1, h_pos_conds.2.1, h_pos_conds.2.2.1, h_pos_conds.2.2.2]

    -- use the subgoal based on AM-GM
    have h_am_gm := geom_mean_le_arith_mean_weighted (Finset.univ) w z (fun i _ ↦ h_weights_nonneg i) h_weights_sum_1 (fun i _ ↦ h_values_nonneg i)

    -- transform AM-GM results to the form we want
    -- `simp` will handle a*a -> a^2
    simp only [Fin.prod_univ_four, Fin.sum_univ_four, w, z, ← pow_two] at h_am_gm

    -- it will replace 'S' to 'a^2 + b^2 + c^2 + d^2'
    unfold S
    -- now the target fully matchs 'h_am_gm'
    exact h_am_gm

  -- step 2: get results from key lemmas
  have h_main_ineq : (a + 2 * b + 3 * c + 4 * d) * S < 1 := by
    exact weighted_sum_times_sum_sq_lt_one a b c d hd0 hdc hcb hba h1

  -- step 3 & 4 & 5: assumble final proof
  calc
    (a + 2*b + 3*c + 4*d) * (a^a * b^b * c^c * d^d)
    -- first, use the results from step 1, we need to prove (a + 2*b + ...) is positive
    -- lemma 'vars_are_in_0_1' guarantees a,b,c,d > 0, thus their weighted sum also > 0
    _ ≤ (a + 2*b + 3*c + 4*d) * S := by
        apply mul_le_mul_of_nonneg_left h_geom_mean_le_sum_sq
        have h_pos_conds := vars_are_in_0_1 a b c d hd0 hdc hcb hba h1
        linarith [h_pos_conds.1.1, h_pos_conds.2.1.1, h_pos_conds.2.2.1.1, h_pos_conds.2.2.2.1]
    -- then, use the results from step 2 to finish proving
    _ < 1 := h_main_ineq
\end{minted}

