\begin{minted}[fontsize=\small, breaklines, linenos, bgcolor=gray!10]{lean}
-- Solution to IMO 2019 P1 by DRP-IMO

import Mathlib
import Aesop

set_option maxHeartbeats 0

open BigOperators Real Nat Topology Rat 

def solution_set (f : ℤ → ℤ) : Prop :=
  (∀ x : ℤ, f x = 0) ∨ ∃ c : ℤ, ∀ x : ℤ, f x = 2 * x + c

theorem linear_form_plus_f_f_x_implies_solutions (f : ℤ → ℤ) (c : ℤ)
    (h_f_form : ∀ x, f x = c * x + f 0) (h_f_f_x : ∀ x, f (f x) = 2 * f x + f 0) :
  (∀ x, f x = 0) ∨ (∀ x, f x = 2 * x + f 0) := by
  have h_c_squared : c^2 = 2 * c := by
    have h1 := h_f_f_x 1
    have h2 := h_f_f_x 0
    have h3 := h_f_f_x (-1)
    have h4 := h_f_form 1
    have h5 := h_f_form 0
    have h6 := h_f_form (-1)
    have h7 := h_f_form (f 1)
    have h8 := h_f_form (f 0)
    have h9 := h_f_form (f (-1))
    have h10 := h_f_f_x (f 1)
    have h11 := h_f_f_x (f 0)
    have h12 := h_f_f_x (f (-1))
    have h13 := h_f_form (c * 1 + f 0)
    have h14 := h_f_form (c * 0 + f 0)
    have h15 := h_f_form (c * (-1) + f 0)
    have h16 := h_f_form (c * (f 1) + f 0)
    have h17 := h_f_form (c * (f 0) + f 0)
    have h18 := h_f_form (c * (f (-1)) + f 0)
    ring_nf at h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 h15 h16 h17 h18 ⊢
    nlinarith [sq_nonneg (c - 2), sq_nonneg (c + 2), sq_nonneg (c - 1), sq_nonneg (c + 1)]

  have h_c_cases : c = 0 ∨ c = 2 := by
    have h₁ : c ^ 2 = 2 * c := h_c_squared
    have h₂ : c = 0 ∨ c = 2 := by
      have h₃ : c * (c - 2) = 0 := by
        linarith
      have h₄ : c = 0 ∨ c - 2 = 0 := by
        apply eq_zero_or_eq_zero_of_mul_eq_zero h₃
      cases h₄ with
      | inl h₄ =>
        exact Or.inl h₄
      | inr h₄ =>
        have h₅ : c = 2 := by
          omega
        exact Or.inr h₅
    exact h₂

  have h_main : (∀ x, f x = 0) ∨ (∀ x, f x = 2 * x + f 0) := by
    cases h_c_cases with
    | inl h_c_zero =>
      -- Case c = 0
      have h_f_zero : ∀ x, f x = f 0 := by
        intro x
        have h₁ := h_f_form x
        simp [h_c_zero] at h₁ ⊢
        <;> linarith
      have h_f_zero_zero : f 0 = 0 := by
        have h₁ := h_f_f_x 0
        have h₂ := h_f_form 0
        have h₃ := h_f_form (f 0)
        have h₄ := h_f_f_x (f 0)
        simp [h_f_zero] at h₁ h₂ h₃ h₄ ⊢
        <;>
        (try omega) <;>
        (try
          {
            nlinarith [h_f_form 0, h_f_form 1, h_f_form (-1), h_f_form (f 0)]
          }) <;>
        (try
          {
            cases' h_c_cases with h_c_zero h_c_two <;> simp_all [h_c_zero, h_c_two] <;>
            (try omega) <;>
            (try nlinarith) <;>
            (try linarith)
          }) <;>
        (try
          {
            aesop
          })
      have h_f_zero_all : ∀ x, f x = 0 := by
        intro x
        have h₁ := h_f_zero x
        have h₂ := h_f_zero 0
        have h₃ := h_f_zero (-1)
        have h₄ := h_f_zero 1
        simp [h_f_zero_zero] at h₁ h₂ h₃ h₄ ⊢
        <;>
        (try omega) <;>
        (try nlinarith) <;>
        (try aesop)
        <;>
        (try
          {
            simp_all [h_f_form, h_c_zero]
            <;>
            (try omega) <;>
            (try nlinarith) <;>
            (try aesop)
          })
      exact Or.inl h_f_zero_all
    | inr h_c_two =>
      -- Case c = 2
      have h_f_form_two : ∀ x, f x = 2 * x + f 0 := by
        intro x
        have h₁ := h_f_form x
        simp [h_c_two] at h₁ ⊢
        <;> linarith
      exact Or.inr h_f_form_two

  exact h_main

theorem prop_cauchy_like (f : ℤ → ℤ) (h_f_all : ∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b)))
    (h_f_f_x : ∀ x, f (f x) = 2 * f x + f 0) (h_f_2x : ∀ x, f (2 * x) = 2 * f x - f 0) (x y : ℤ) :
  f (x + y) = f x + f y - f 0 := by
  have h_main : f (x + y) = f x + f y - f 0 := by
    have h1 := h_f_all (x + y) 0
    have h2 := h_f_all x y
    have h3 := h_f_all (x + y) y
    have h4 := h_f_all x (x + y)
    have h5 := h_f_2x (x + y)
    have h6 := h_f_2x x
    have h7 := h_f_2x y
    have h8 := h_f_all 0 (x + y)
    have h9 := h_f_all 0 x
    have h10 := h_f_all 0 y
    have h11 := h_f_f_x (x + y)
    have h12 := h_f_f_x x
    have h13 := h_f_f_x y
    have h14 := h_f_all (2 * (x + y)) 0
    have h15 := h_f_all (2 * x) 0
    have h16 := h_f_all (2 * y) 0
    have h17 := h_f_all x 0
    have h18 := h_f_all y 0
    have h19 := h_f_all (x + y) (x + y)
    have h20 := h_f_all x x
    have h21 := h_f_all y y
    -- Simplify the expressions using the given conditions
    simp [h_f_2x, mul_add, add_mul, mul_comm, mul_left_comm, mul_assoc] at h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 h15 h16 h17 h18 h19 h20 h21 ⊢
    <;> ring_nf at h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 h15 h16 h17 h18 h19 h20 h21 ⊢
    <;> omega
  exact h_main

theorem prop_f_f_x (f : ℤ → ℤ) (h_f_all : ∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) (x : ℤ) :
  f (f x) = 2 * f x + f 0 := by
  have h_main : f (f x) = 2 * f x + f 0 := by
    have h1 := h_f_all x 0
    have h2 := h_f_all 0 x
    have h3 := h_f_all x x
    have h4 := h_f_all (-x) x
    have h5 := h_f_all x (-x)
    have h6 := h_f_all 0 0
    have h7 := h_f_all x (-2 * x)
    have h8 := h_f_all (-x) (-x)
    have h9 := h_f_all x 1
    have h10 := h_f_all x (-1)
    have h11 := h_f_all 1 x
    have h12 := h_f_all (-1) x
    have h13 := h_f_all 1 0
    have h14 := h_f_all (-1) 0
    have h15 := h_f_all 0 1
    have h16 := h_f_all 0 (-1)
    have h17 := h_f_all 1 1
    have h18 := h_f_all (-1) (-1)
    -- Simplify the equations to find a relationship between f(0) and f(f(0))
    simp at h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 h15 h16 h17 h18
    ring_nf at h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 h15 h16 h17 h18 ⊢
    -- Use linear arithmetic to solve for the desired result
    omega
  exact h_main

theorem prop_f_2x (f : ℤ → ℤ) (h_f_all : ∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b)))
    (h_f_f_x : ∀ x, f (f x) = 2 * f x + f 0) (x : ℤ) :
  f (2 * x) = 2 * f x - f 0 := by
  have h1 : f (f (2 * x)) = 2 * f (2 * x) + f 0 := by
    have h1 := h_f_f_x (2 * x)
    -- Simplify the expression using the given condition h_f_f_x
    simp at h1 ⊢
    <;> linarith

  have h2 : f (2 * x) + 2 * f x = f (f (2 * x)) := by
    have h2 := h_f_all x x
    -- Simplify the expression using the given condition h_f_all
    ring_nf at h2 ⊢
    <;> linarith

  have h3 : f (2 * x) + 2 * f x = 2 * f (2 * x) + f 0 := by
    have h3 : f (2 * x) + 2 * f x = f (f (2 * x)) := h2
    rw [h3]
    have h4 : f (f (2 * x)) = 2 * f (2 * x) + f 0 := h1
    rw [h4]
    <;> ring
    <;> omega

  have h4 : f (2 * x) = 2 * f x - f 0 := by
    have h5 : f (2 * x) + 2 * f x = 2 * f (2 * x) + f 0 := h3
    -- Rearrange the equation to isolate f(2 * x)
    have h6 : f (2 * x) = 2 * f x - f 0 := by
      -- Solve for f(2 * x) using linear arithmetic
      linarith
    exact h6

  apply h4


theorem cauchy_implies_linear_form (f : ℤ → ℤ) (h_cauchy_like : ∀ x y, f (x + y) = f x + f y - f 0) :
  ∃ c : ℤ, ∀ x, f x = c * x + f 0 := by
  have h_main : ∃ (c : ℤ), ∀ (x : ℤ), f x = c * x + f 0 := by
    use f 1 - f 0
    intro x
    have h1 : ∀ n : ℤ, f n = (f 1 - f 0) * n + f 0 := by
      intro n
      induction n using Int.induction_on with
      | hz =>
        -- Base case: n = 0
        simp [h_cauchy_like]
        <;> ring_nf
        <;> omega
      | hp n ih =>
        -- Inductive step: n = p + 1
        have h2 := h_cauchy_like n 1
        have h3 := h_cauchy_like 0 (n + 1)
        have h4 := h_cauchy_like (n + 1) 0
        have h5 := h_cauchy_like 1 0
        have h6 := h_cauchy_like 0 1
        simp at h2 h3 h4 h5 h6
        simp [ih, add_mul, mul_add, mul_one, mul_neg, mul_zero, sub_eq_add_neg] at h2 h3 h4 h5 h6 ⊢
        <;> ring_nf at *
        <;> omega
      | hn n ih =>
        -- Inductive step: n = - (n + 1)
        have h2 := h_cauchy_like (-n - 1) 1
        have h3 := h_cauchy_like 0 (-n - 1)
        have h4 := h_cauchy_like (-n - 1) 0
        have h5 := h_cauchy_like 1 0
        have h6 := h_cauchy_like 0 1
        simp at h2 h3 h4 h5 h6
        simp [ih, add_mul, mul_add, mul_one, mul_neg, mul_zero, sub_eq_add_neg] at h2 h3 h4 h5 h6 ⊢
        <;> ring_nf at *
        <;> omega
    have h2 := h1 x
    have h3 := h1 1
    have h4 := h1 0
    simp at h2 h3 h4 ⊢
    <;> linarith
  exact h_main

theorem step6_zero_function_is_solution (f : ℤ → ℤ) (h_zero : ∀ x, f x = 0) : (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) := by
have h_main : ∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b)) := by
  intro a b
  have h1 : f (2 * a) = 0 := by
    rw [h_zero]
    <;> simp [h_zero]
  have h2 : f b = 0 := by
    rw [h_zero]
    <;> simp [h_zero]
  have h3 : f (a + b) = 0 := by
    rw [h_zero]
    <;> simp [h_zero]
  have h4 : f (f (a + b)) = 0 := by
    rw [h_zero]
    <;> simp [h_zero]
  -- Simplify the LHS and RHS using the above equalities
  simp [h1, h2, h3, h4, h_zero]
  <;> linarith
exact h_main

theorem step7_linear_function_is_solution (f : ℤ → ℤ) (c : ℤ) (h_lin : ∀ x, f x = 2 * x + c) : (∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b))) := by
have h_main : ∀ a b, f (2 * a) + 2 * (f b) = f (f (a + b)) := by
  intro a b
  have h1 : f (2 * a) = 2 * (2 * a) + c := by
    rw [h_lin]
    <;> ring
  have h2 : f b = 2 * b + c := by
    rw [h_lin]
    <;> ring
  have h3 : f (f (a + b)) = f (2 * (a + b) + c) := by
    have h4 : f (a + b) = 2 * (a + b) + c := by
      rw [h_lin]
      <;> ring
    rw [h4]
    <;> ring
  have h4 : f (f (a + b)) = 2 * (2 * (a + b) + c) + c := by
    rw [h3]
    rw [h_lin]
    <;> ring
  have h5 : f (2 * a) + 2 * (f b) = (2 * (2 * a) + c) + 2 * (2 * b + c) := by
    rw [h1, h2]
    <;> ring
  have h6 : f (2 * a) + 2 * (f b) = 4 * a + 4 * b + 3 * c := by
    linarith
  have h7 : f (f (a + b)) = 4 * a + 4 * b + 3 * c := by
    linarith
  linarith
exact h_main

theorem imo2019_p1
    (f : ℤ → ℤ) :
    (∀ a b : ℤ, f (2 * a) + 2 * f b = f (f (a + b))) ↔ solution_set f := by
  constructor
  · intro h_fe
    have h_ff : ∀ x, f (f x) = 2 * f x + f 0 :=
      prop_f_f_x f h_fe
    have h_f2 : ∀ x, f (2 * x) = 2 * f x - f 0 :=
      prop_f_2x f h_fe h_ff
    have h_add : ∀ x y, f (x + y) = f x + f y - f 0 :=
      prop_cauchy_like f h_fe h_ff h_f2
    rcases cauchy_implies_linear_form f h_add with ⟨c, h_lin0⟩
    have h_split :
        (∀ x, f x = 0) ∨ (∀ x, f x = 2 * x + f 0) :=
      linear_form_plus_f_f_x_implies_solutions f c h_lin0 h_ff
    cases h_split with
    | inl h0 =>
        exact Or.inl h0
    | inr h2 =>
        exact Or.inr ⟨f 0, h2⟩
  · intro h_sol
    cases h_sol with
    | inl h0 =>
        exact step6_zero_function_is_solution f h0
    | inr h_exists =>
        rcases h_exists with ⟨c, h_lin⟩
        exact step7_linear_function_is_solution f c h_lin
\end{minted}

\subsection{IMO 2011 P3}
