  have h₈ := hf (f x) (-f x)
  have h₉ := hf (f x) 0
  have h₁₀ := hf 0 (-f x)
  have h₁₁ := hf x (2 * x)
  have h₁₂ := hf x (-2 * x)
  have h₁₃ := hf (2 * x) (-x)
  have h₁₄ := hf (2 * x) x
  have h₁₅ := hf (-2 * x) x
  have h₁₆ := hf (-2 * x) (-x)
  have h₁₇ := hf (f x) x
  have h₁₈ := hf (f x) (-x)
  have h₁₉ := hf x (f x)
  have h₂₀ := hf (-x) (f x)
  have h₂₁ := hf x (-f x)
  have h₂₂ := hf (-x) (-f x)
  have h₂₃ := hf (2 * f x) (-f x)
  have h₂₄ := hf (-2 * f x) (-f x)
  have h₂₅ := hf (2 * f x) (f x)
  have h₂₆ := hf (-2 * f x) (f x)
  have h₂₇ := hf (f x) (2 * f x)
  have h₂₈ := hf (f x) (-2 * f x)
  have h₂₉ := hf x (x)
  have h₃₀ := hf x (-x)
  have h₃₁ := hf 0 (2 * f x)
  have h₃₂ := hf 0 (-2 * f x)
