theorem lemma_final_implication (f : ℝ → ℝ) (hf : ∀ x y, f (x + y) ≤ y * f x + f (f x))
  (h_f_at_0_is_0 : f 0 = 0) (h_f_non_positive : ∀ x, f x ≤ 0) : ∀ x ≤ 0, f x = 0 := by
  have h_main : ∀ (x : ℝ), x ≤ 0 → f x = 0 := by
    intro x hx
