theorem imo2005_p3 (x y z : ℝ) (hx : x > 0) (hy : y > 0) (hz : z > 0) (h_prod_ge_1 : x * y * z ≥ 1) :
  (x ^ 5 - x ^ 2) / (x ^ 5 + y ^ 2 + z ^ 2) + (y ^ 5 - y ^ 2) / (y ^ 5 + z ^ 2 + x ^ 2) + (z ^ 5 - z ^ 2) / (z ^ 5 + x ^ 2 + y ^ 2) ≥ 0 := by
  -- Define S_part1 (LHS of inequality_part1_nonnegative)
  let S_part1 := (x^2 - 1/x + y^2 - 1/y + z^2 - 1/z) / (x^2 + y^2 + z^2)

  -- Define S_part2 (LHS of inequality_part2_nonnegative)
  let S_part2 :=
    ((x^5 - x^2)/(x^5 + y^2 + z^2) - (x^2 - 1/x)/(x^2 + y^2 + z^2)) +
    ((y^5 - y^2)/(y^5 + z^2 + x^2) - (y^2 - 1/y)/(y^2 + z^2 + x^2)) +
    ((z^5 - z^2)/(z^5 + x^2 + y^2) - (z^2 - 1/z)/(z^2 + x^2 + y^2))

  -- Prove S_part1 ≥ 0 using inequality_part1_nonnegative
  have h_S_part1_nonneg : S_part1 ≥ 0 := by
    apply inequality_part1_nonnegative <;> assumption

  -- Prove S_part2 ≥ 0 using inequality_part2_nonnegative
  have h_S_part2_nonneg : S_part2 ≥ 0 := by
    apply inequality_part2_nonnegative <;> assumption

  -- Prove that the original LHS is equal to S_part1 + S_part2
  -- We'll prove it as a separate fact (have) and then use it.
  have h_LHS_eq_sum :
    (x^5 - x^2)/(x^5 + y^2 + z^2) + (y^5 - y^2)/(y^5 + z^2 + x^2) + (z^5 - z^2)/(z^5 + x^2 + y^2) =
    S_part2 + S_part1 := by
    -- Expand the definitions of S_part1 and S_part2
    unfold S_part1 S_part2
    -- Normalize denominators which are permutations of each other
    have h_denom_y : y^2 + z^2 + x^2 = x^2 + y^2 + z^2 := by ac_rfl
    have h_denom_z : z^2 + x^2 + y^2 = x^2 + y^2 + z^2 := by ac_rfl
    rw [h_denom_y, h_denom_z]
    -- The rest is a pure algebraic identity, which `ring` can solve.
    -- It correctly rearranges terms like (a-b)+(c-d)+(e-f) + (b+d+f)/k = a+c+e
    -- after combining the fractions for S_part1
    ring

  -- Rewrite the goal using the equality we just proved
  rw [h_LHS_eq_sum]

  -- The goal is now S_part2 + S_part1 ≥ 0, which follows from the two parts being non-negative.
  exact add_nonneg h_S_part2_nonneg h_S_part1_nonneg
\end{minted}

\subsection{IMO 2000 P2}
\begin{minted}[fontsize=\small, breaklines, linenos, bgcolor=gray!10]{lean}
-- Solution to IMO 2000 P2 by DRP-IMO

import Mathlib
import Aesop

set_option maxHeartbeats 0

open BigOperators Real Nat Topology Rat 

/--Given positive real numbers \( a \), \( b \), and \( c \) such that \( a \times b \times c = 1 \), prove that there exist positive real numbers \( x
 \), \( y \), and \( z \) such that \( a = \frac{x}{y} \), \( b = \frac{y}{z} \), and \( c = \frac{z}{x} \).-/
theorem imo2000_p2_existence_of_xyz (a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (habc : a * b * c = 1) :
  ∃ x y z : ℝ, 0 < x ∧ 0 < y ∧ 0 < z ∧ a = x/y ∧ b = y/z ∧ c = z/x := by
  have h_main : ∃ (x y z : ℝ), 0 < x ∧ 0 < y ∧ 0 < z ∧ a = x/y ∧ b = y/z ∧ c = z/x := by
    refine' ⟨a, 1, 1 / b, _, _, _, _, _, _⟩
    · -- Prove that a > 0
      linarith
    · -- Prove that 1 > 0
      norm_num
    · -- Prove that 1 / b > 0
      exact div_pos zero_lt_one hb
    · -- Prove that a = a / 1
      field_simp
    · -- Prove that b = 1 / (1 / b)
      field_simp
      <;>
      nlinarith
    · -- Prove that c = (1 / b) / a
      have h₁ : c = 1 / (a * b) := by
        have h₂ : a * b * c = 1 := habc
        have h₃ : c = 1 / (a * b) := by
          have h₄ : a * b ≠ 0 := by positivity
          field_simp [h₄] at h₂ ⊢
          nlinarith
        exact h₃
      have h₂ : (1 / b : ℝ) / a = 1 / (a * b) := by
        field_simp
        <;> ring
        <;> field_simp [ha.ne', hb.ne']
        <;> nlinarith
      rw [h₁] at *
      <;> linarith
  exact h_main

/--Consider three positive real numbers \( x \), \( y \), and \( z \) such that \( x > 0 \), \( y > 0 \), and \( z > 0 \). Prove that the product of th
e expressions \( (x - y + z) \), \( (y - z + x) \), and \( (z - x + y) \) is less than or equal to the product \( x \cdot y \cdot z \).-/
theorem schur_like_ineq (x y z : ℝ) (hx : 0 < x) (hy : 0 < y) (hz : 0 < z) :
  (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by
  have h_main : (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by
    nlinarith [sq_nonneg (x - y), sq_nonneg (y - z), sq_nonneg (z - x),
      mul_nonneg hx.le hy.le, mul_nonneg hy.le hz.le, mul_nonneg hz.le hx.le,
      mul_nonneg (sq_nonneg (x - y)) (sq_nonneg (y - z)),
      mul_nonneg (sq_nonneg (y - z)) (sq_nonneg (z - x)),
      mul_nonneg (sq_nonneg (z - x)) (sq_nonneg (x - y)),
      mul_nonneg (sq_nonneg (x - y + z)) (sq_nonneg (y - z + x)),
      mul_nonneg (sq_nonneg (y - z + x)) (sq_nonneg (z - x + y)),
      mul_nonneg (sq_nonneg (z - x + y)) (sq_nonneg (x - y + z)),
      mul_nonneg (sq_nonneg (x + y - z)) (sq_nonneg (y + z - x)),
      mul_nonneg (sq_nonneg (y + z - x)) (sq_nonneg (z + x - y)),
      mul_nonneg (sq_nonneg (z + x - y)) (sq_nonneg (x + y - z))]
  exact h_main

/--Consider positive real numbers \( a, b, c, x, y, z \) such that \( a \cdot b \cdot c = 1 \) and \( a = \frac{x}{y} \), \( b = \frac{y}{z} \), \( c =
 \frac{z}{x} \). Prove that the inequality \((a - 1 + \frac{1}{b}) \cdot (b - 1 + \frac{1}{c}) \cdot (c - 1 + \frac{1}{a}) \leq 1\) is equivalent to th
e inequality \((x - y + z) \cdot (y - z + x) \cdot (z - x + y) \leq x \cdot y \cdot z\).-/
theorem inequality_equivalence_under_parametrization (a b c x y z : ℝ)
  (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (habc : a * b * c = 1)
  (hx : 0 < x) (hy : 0 < y) (hz : 0 < z)
  (hax : a = x / y) (hby : b = y / z) (hcz : c = z / x) :
  (a - 1 + 1 / b) * (b - 1 + 1 / c) * (c - 1 + 1 / a) ≤ 1 ↔
  (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by
  have h_main : (a - 1 + 1 / b) * (b - 1 + 1 / c) * (c - 1 + 1 / a) = ((x + z - y) / y) * ((x + y - z) / z) * ((y + z - x) / x) := by
    have h₁ : a - 1 + 1 / b = (x + z - y) / y := by
      have h₁ : a = x / y := by linarith
      have h₂ : b = y / z := by linarith
      rw [h₁, h₂]
      field_simp [ha.ne', hb.ne', hx.ne', hy.ne', hz.ne']
      <;> ring_nf
      <;> field_simp [ha.ne', hb.ne', hx.ne', hy.ne', hz.ne']
      <;> nlinarith
    have h₂ : b - 1 + 1 / c = (x + y - z) / z := by
      have h₁ : b = y / z := by linarith
      have h₂ : c = z / x := by linarith
      rw [h₁, h₂]
      field_simp [ha.ne', hb.ne', hc.ne', hx.ne', hy.ne', hz.ne']
      <;> ring_nf
      <;> field_simp [ha.ne', hb.ne', hc.ne', hx.ne', hy.ne', hz.ne']
      <;> nlinarith
    have h₃ : c - 1 + 1 / a = (y + z - x) / x := by
      have h₁ : c = z / x := by linarith
      have h₂ : a = x / y := by linarith
      rw [h₁, h₂]
      field_simp [ha.ne', hb.ne', hc.ne', hx.ne', hy.ne', hz.ne']
      <;> ring_nf
      <;> field_simp [ha.ne', hb.ne', hc.ne', hx.ne', hy.ne', hz.ne']
      <;> nlinarith
    rw [h₁, h₂, h₃]
    <;> field_simp [ha.ne', hb.ne', hc.ne', hx.ne', hy.ne', hz.ne']
    <;> ring_nf
    <;> field_simp [ha.ne', hb.ne', hc.ne', hx.ne', hy.ne', hz.ne']
    <;> nlinarith

  have h_equiv : ((x + z - y) / y) * ((x + y - z) / z) * ((y + z - x) / x) ≤ 1 ↔ (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by
    have h₁ : 0 < x * y := by positivity
    have h₂ : 0 < y * z := by positivity
    have h₃ : 0 < z * x := by positivity
    have h₄ : 0 < x * y * z := by positivity
    constructor
    · intro h
      have h₅ : ((x + z - y) / y) * ((x + y - z) / z) * ((y + z - x) / x) ≤ 1 := by linarith
      have h₆ : (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by
        field_simp at h₅
        rw [div_le_one (by positivity)] at h₅
        nlinarith [sq_nonneg (x - y), sq_nonneg (y - z), sq_nonneg (z - x),
          mul_nonneg hx.le hy.le, mul_nonneg hy.le hz.le, mul_nonneg hz.le hx.le,
          mul_nonneg (sq_nonneg (x - y)) hz.le, mul_nonneg (sq_nonneg (y - z)) hx.le,
          mul_nonneg (sq_nonneg (z - x)) hy.le]
      linarith
    · intro h
      have h₅ : (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by linarith
      have h₆ : ((x + z - y) / y) * ((x + y - z) / z) * ((y + z - x) / x) ≤ 1 := by
        field_simp
        rw [div_le_one (by positivity)]
        nlinarith [sq_nonneg (x - y), sq_nonneg (y - z), sq_nonneg (z - x),
          mul_nonneg hx.le hy.le, mul_nonneg hy.le hz.le, mul_nonneg hz.le hx.le,
          mul_nonneg (sq_nonneg (x - y)) hz.le, mul_nonneg (sq_nonneg (y - z)) hx.le,
          mul_nonneg (sq_nonneg (z - x)) hy.le]
      linarith

  have h_final : (a - 1 + 1 / b) * (b - 1 + 1 / c) * (c - 1 + 1 / a) ≤ 1 ↔ (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z := by
    rw [h_main]
    rw [h_equiv]
    <;>
    simp_all
    <;>
    field_simp
    <;>
    ring_nf
    <;>
    nlinarith

  exact h_final

theorem imo2000_p2
    (a b c : ℝ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c)
    (habc : a * b * c = 1) :
    (a - 1 + 1 / b) * (b - 1 + 1 / c) * (c - 1 + 1 / a) ≤ 1 := by
  -- 1. Parametrize x y z using positive numbers
  obtain ⟨x, y, z, hx, hy, hz, ha_eq, hb_eq, hc_eq⟩ :=
    imo2000_p2_existence_of_xyz a b c ha hb hc habc
  -- 2. Use an equivalent lemma to transform the goal into the form involving x y z
  have h_equiv :=
    (inequality_equivalence_under_parametrization
        (a := a) (b := b) (c := c) (x := x) (y := y) (z := z)
        ha hb hc habc hx hy hz ha_eq hb_eq hc_eq)
  -- 3. The Schur-type inequality yields the conclusion on the right-hand side.
  have hxyz : (x - y + z) * (y - z + x) * (z - x + y) ≤ x * y * z :=
    schur_like_ineq x y z hx hy hz
  -- 4. Derive the original conclusion by reversing the equivalent proposition.
  exact h_equiv.mpr hxyz
