\section{Characterization of CA with a unique active transition} 

In general, the idempotence of a cellular automaton $\tau : A^\Z \to A^\Z$ with finite neighborhood $S \subset \Z$ may be checked by obtaining the local function of $\tau \circ \tau : A^\Z \to A^\Z$, which has finite neighborhood $S + S := \{ s+ t : s,t \in S \}$ (see \cite[Prop. 1.4.9]{CSC10}), and comparing it with the local function of $\tau$ (which may be extended to the domain $A^{S+S}$ in order to be compared). In the next results we shall see that there is a quicker and simpler method to decide the idempotence of a CA with a unique active transition.  

\begin{lemma}\label{cor-idem}
Let $\tau : A^\mathbb{Z} \to A^{\mathbb{Z}}$ be a cellular automaton with a unique active transition $p \in A^S$. Then, $\tau$ is not idempotent if and only if there exists $x \in A^\Z$ such that $p$ appears as a subpattern in $\tau(x) \in A^\Z$. 
\end{lemma}
\begin{proof}
In general, it holds that a transformation $\tau : A^\Z \to A^\Z$ is idempotent if and only if $\Fix(\tau) = \im(\tau)$, so by Lemma \ref{le-b} (2), this is equivalent to $X_p = \im(\tau)$. Therefore, $\tau$ is not idempotent if and only if $X_p$ is a proper subset of $\im(\tau)$, which is equivalent to the statement of this lemma. 
\end{proof}

\begin{lemma}\label{le-2}
Let $\tau : A^\mathbb{Z} \to A^{\mathbb{Z}}$ be a cellular automaton with a unique active transition $p \in A^S$. Let $\mu : A^S \to A$ be the corresponding local defining function of $\tau$. Then, $\tau$ is not idempotent if and only if there exists $x \in A^\Z$ such that 
\begin{equation} \label{eq-x}
\mu( (s \cdot x) \vert_S  ) = p(s), \quad \forall s \in S. 
\end{equation}
Furthermore, if such $x \in A^\Z$ exists, it must also satisfy the following:
\begin{enumerate}
\item $x \vert_S \neq p$,
\item $x(0) = p(0)$. 
\item $(t \cdot x) \vert_S  = p$ for some $t \in S \setminus \{0\}$. 
\end{enumerate}
\end{lemma}
\begin{proof}
By Corollary \ref{cor-idem}, $\tau$ is not idempotent if and only if there exists $x \in A^\Z$ such that $p$ appears as a subpattern in $\tau(x)$. Since $\im(\tau)$ is invariant under the shift action, we may assume that $p$ appears in $S$, i.e.
\[ \tau(x)(s) = p(s), \quad \forall s \in S. \]
Hence, in terms of the local defining function
\[ \mu((s \cdot x) \vert_S) = \tau(x)(s) = p(s), \quad \forall s \in S.  \]
We must have $x \vert_S \neq p$, since $\mu(p) \neq p(0)$, and so $p(0) = \mu(x \vert_S) = x(0)$. Finally, suppose that $(s \cdot x) \vert_S \neq p$ for all $s \in S$. Then, $p(s) = \mu((s \cdot x) \vert_S) = x(s)$ for all $s \in S$, contradicting that $x \vert_S  \neq p$. Thus, there must exists $t \in S \setminus \{0\}$ with $(t \cdot x) \vert_S  = p$. 
\end{proof}

\begin{remark}
The subpatterns $(s \cdot x) \vert_S$ for $s \in S$ are completely determined by $x \vert_{S+S}$. Hence, Lemma \ref{le-2} also gives a quick algorithm for deciding when a cellular automaton generated by a pattern is idempotent, which consists on checking if there exists a pattern $q \in A^{S+S}$ such that $\mu(q_s ) = p(s)$ for all $s \in S$, where $q_s \in A^S$ is the pattern defined by $q_s(t) := q(s+t)$, $\forall t \in S$.   
\end{remark}

\begin{example}
For $S = \{-1,0,1\}$, a cellular automaton with unique active transition $p = 001 \in A^S$ is not idempotent because there exists $q = 00001 \in A^{S+S}$ such that 
\[ \mu(q_{-1}) \mu(q_0) \mu(q_1) = \mu(000) \mu(000) \mu(001) = 001 = p.  \]
\end{example}

\begin{example}\label{counter}
Unlike some constructions and results in symbolic dynamics, the idempotence of a CA with a unique active transition depends on both the pattern $p \in A^S$ and the local neighborhood $S \subset \Z$. For example, the CA with unique active transition $p_1=0010 \in A^{S_1}$ with $S_1 := [-1,2]$ is idempotent, while the CA with unique active transition $p_2 = 0010 \in A^{S_2}$ with $S_2 := [0,3]$ is not idempotent.   
\end{example}

\begin{corollary}\label{cor-1}
With the notation of the previous lemma,
 \[ p(t)= \mu(p) \neq p(e). \]
\end{corollary}
\begin{proof}
Since $(t \cdot x) \vert_S = p$ for $t \in S \setminus \{0\}$, then 
\[ p(t) = \mu( (t \cdot x) \vert_S ) = \mu(p).   \]
It is clear that $\mu(p) \neq p(0)$, because $p$ is an active transition of $\mu$. 
\end{proof}

The previous results easily generalize to cellular automata $\tau : A^G \to A^G$, where $G$ is any abstract group. However, henceforth, our proofs will rely on specific properties of the group of integers $\Z$.  

Our next goal is to show that there is a \emph{unique} $t \in S \setminus \{0\}$ such that $(t \cdot x) \vert_S  = p$, where $x \in A^\Z$ satisfies the condition (\ref{eq-x}) of Lemma \ref{le-2}. The uniqueness of $t$ shall be crucial in the proof of Theorem \ref{intro-main}, but first we show a couple of technical results that hold in the case when $S$ is an interval of $\Z$ containing $0$. 

\begin{lemma}\label{rk-int}
Let $S \subset \Z$ be an interval with $0 \in S$, and let $t,r \in S$, $t < r$. For each $i \in (t,r)$, either $i-t \in S$ or $i-r \in S$. 
\end{lemma}
\begin{proof}
Suppose that $i-r \not \in S$. Since $ i-r <0$, we must have that $i - r < t$. But now, $0 < i-t < r $, implies that $i - r \in S$, since $0, r \in S$ and $S$ is an interval. 
\end{proof}


\begin{lemma}\label{le-seq}
Let $S \subset \mathbb{Z}$ be an interval such that $0 \in S$. Let $x \in A^\Z$ and $p \in A^S$. Suppose that there exist $t,r \in S$, $t < r$, satisfying that $(t \cdot x) \vert_S  = (r \cdot x) \vert_S  = p$, and
\begin{equation}\label{hyp-seq}
\forall s \in (t,r), \ \epsilon \in \{r,t\},  \quad   ( s - \epsilon \in S)  \ \Rightarrow  \ p(s) = p(s-\epsilon).  
\end{equation}
Then, $p(0) = p(t)$. 
\end{lemma}
\begin{proof}
Define $m := r-t \in \mathbb{Z}_+$. We first show that since $(t \cdot x) \vert_S  = (r \cdot x) \vert_S  = p$, then $p : S \to A$ must be constant on the classes modulo $m$ that intersect $S$. Denote by $[s]_m$ the equivalence class modulo $m$ of $s \in \mathbb{Z}$. 

\begin{claim}\label{lemma-mod}
If $s_1, s_2 \in S$ and $[s_1]_m = [s_2]_m$, then $p(s_1) = p(s_2)$.
\end{claim}
\begin{proof}
Observe that for all $s \in S$ such that $s+m \in S$, we have 
\[ p(s) = (r \cdot x)(s) = x(s+ r) = (t \cdot x)(s +r - t) = p(s + m). \]
If $s \in S$ and $s + km \in S$, for $k \in \mathbb{Z}_+$, then $s+m, s+2m, \dots, s+(k-1)m \in S$, as $S$ is an interval. It follows that $p(s) = p(s+km)$. 
On the other hand, if $s \in S$ and $s-m \in S$, then
\[ p(s) = (t \cdot x)(s) = x(s + t) = (r\cdot x) (s - m) = p(s-m). \]
It follows that if $s \in S$ and $s+km \in S$, for $k \in \mathbb{Z}_-$, then $p(s) = p(s+km)$. 
\end{proof}

If $[t]_m = [0]_m$, then Claim \ref{lemma-mod} implies that $p(t) = p(0)$, and the result follows. Hence, assume that $[ t]_m \neq [0]_m$. 

Let $n$ be the group-theoretic order of $[t]_m$ in $\mathbb{Z}_m$; this is, $n$ is the smallest positive integer such that $n[t]_m = 0$. Let $I := [t,r) \subset S$. Since $\vert I \vert = m$ and $I$ consists of consecutive integers, then $I$ contains representatives of all classes modulo $m$.  Let $s_1, s_2, s_3, \dots, s_{n} \in I$ be such that 
\[ [s_j]_m = j [t]_m , \quad \forall j \in [1,n].  \]
By Lemma \ref{rk-int}, for each $j \in [2,n]$, there exists $\epsilon_j$ such that $s_j - \epsilon_j \in S$, with $\epsilon_j \in \{t,r\}$, and by hypothesis (\ref{hyp-seq})
\[  p(s_j) = p(s_j - \epsilon_j), \quad \forall j \in [2,n].  \]  
Observe that, for all $j \in [2,n]$, we have $[\epsilon_j]_m = [t]_m$, so
\[ [s_j - \epsilon_j]_m = [s_j]_m - [\epsilon_j]_m = j[t]_m - [t]_m = (j-1)[t]_m = [s_{j-1}]_m.  \]
Therefore,
\[  p(s_j - \epsilon_j) = p(s_{j-1}), \quad \forall j \in [2,n].  \]
This shows that $p(s_n) = p(s_1)$. However, $s_1 = t$ and $[s_n] = n[t] = [0]$, so by Claim \ref{lemma-mod},
\[ p(0) = p(s_n) = p(s_1) = p(t).     \] 
The result follows. 
\end{proof}

\begin{theorem}\label{uniqueness}
Let $S \subset \mathbb{Z}$ be an interval such that $0 \in S$. Let $\tau : A^\mathbb{Z} \to A^{\mathbb{Z}}$ be a cellular automaton with a unique active transition $p \in A^S$ and with corresponding local defining function $\mu : A^S \to A$. Then, for every $x \in A^\Z$ satisfying $\mu((s \cdot x)\vert_S) = p(s)$, $\forall s \in S$, there exists a unique $t \in S \setminus \{0\}$ such that $(t \cdot x)\vert_S = p$.
\end{theorem}
\begin{proof}
The existence of such $t \in S \setminus \{0\}$ is given by Lemma \ref{le-2}, part (3). In order to prove the uniqueness, suppose there are $t, r \in S \setminus \{0\}$ such that $(t \cdot x)\vert_S = (r \cdot x)\vert_S = p$. Without loss, assume that $t< r$. We may also assume that 
\begin{equation}\label{eqhyp}
 (s \cdot x)\vert_S \neq p, \quad \forall s \in (t,r) \subset S.    
\end{equation}
This implies that for each $s \in (t,r)$ and $\epsilon \in \{t,r\}$ such that $s - \epsilon \in S$, then 
\[ p(s) = \mu((s \cdot x)\vert_S) = (s \cdot x)(0) = x(s) = (\epsilon \cdot x)( s -  \epsilon) = p(s - \epsilon), \] 
where the last equality holds since $ (\epsilon \cdot x) \vert_S =p$. 

The above shows that the hypothesis (\ref{hyp-seq}) of Lemma \ref{le-seq} is satisfied, so $p(0) = p(t)$. However, by Corollary \ref{cor-1}, $p(t) = \mu(p)$, which contradicts that $\mu(p) \neq p(0)$. The result follows. 
\end{proof}

\begin{example}\label{counter}
Theorem \ref{uniqueness} fails when $S \subset \mathbb{Z}$ is not an interval. For example, consider $S:= \{-1, 0 , 3\}$ and the pattern $p \in A^S$ defined by
\[ p =\left( \begin{tabular}{ccc}
$-1$ & $0$ & $3$ \\
$0$ & $1$ & $0$ 
\end{tabular} \right).   \]
Then, the cellular automaton $\tau : A^\Z \to A^\Z$ with a unique active transition $p$ is not idempotent; an $x \in A^\Z$ that satisfies the condition of Lemma \ref{le-2} is given by
\[ x = \dots 011010 \dots \]
However, we see that there exist two $s \in S$ such that $(s \cdot x)\vert_S = p$; namely, $s=-1$ and $s=3$.  
\end{example}


 \begin{theorem}\label{th-main}
 Let $S := [k, \ell] \subset \mathbb{Z}$ be such that $k \leq 0 \leq l$. Let $\tau : A^{\mathbb{Z}} \to A^{\mathbb{Z}}$ be the cellular automaton with a unique active transition $p \in A^S$, with corresponding local function $\mu : A^S \to A$. Then, $\tau$ is not idempotent if and only if there exists $t \in S_+$ such that 
\[ p(t) = \mu(p) \quad \text{ and } \quad p(i) = p(i-t), \  \forall i \in [k+t, \ell] \setminus \{ t \}, \]  
or there exists $t \in S_-$ such that
\[ p(t) = \mu(p) \quad \text{ and } \quad p(i) = p(i-t), \ \forall i \in [k, \ell + t] \setminus \{ t \}.  \]  
 \end{theorem}
 \begin{proof}
 Let $a := \mu(p) \neq p(0)$. Suppose that $\tau$ is not idempotent. By Lemma \ref{le-2}, there exists $x \in A^\Z$ such that $\mu((s\cdot x)\vert_S) = p(s)$ for all $s \in S$, and $t \in S \setminus \{0\}$ such that $(t \cdot x) \vert_S = p$. By Theorem \ref{uniqueness}, this $t \in S \setminus \{0\}$ is unique. Suppose that $t \in S_+$. By Corollary \ref{cor-1}, $p(t) = a$. Fix $i \in [k+t,t)$. By uniqueness of $t$, we have $(i \cdot x)\vert_S \neq p$, and since $i-t \in [k,0) \subset S$, it follows that
\[ p(i) = \mu((i \cdot x)\vert_S) = (i \cdot x)(0) = x(i) = (t \cdot x) (i-t) = p(i-t), \quad \forall i \in [k + t, t). \]
Now fix $j \in (t, \ell]$. By uniqueness of $t$, we have $(j \cdot x)\vert_S \neq p$, and since $j-t \in (0, \ell-t] \subset S$, it follows that  
\[ p(j) = \mu((j \cdot x)\vert_S) = (j \cdot x) (0) = x(j) = (t \cdot x)(j -t ) = p(j - t), \quad \forall j \in (t, \ell].  \]
The result follows analogously when $t \in S_-$, or may be shown by applying the well-known reflection automorphism of the monoid $\CA(\Z,A)$ (e.g, see \cite[Sec. 3]{CRG}).  

Suppose now that $p \in A^S$ satisfies that there exist $t \in S_+$ such that 
\begin{equation}\label{hyp}
 p(t) = a \quad \text{ and } \quad p(i) = p(i-t), \  \forall i \in [k+t, \ell] \setminus \{ t \}. 
\end{equation}

Define $x \in A^\Z$ as follows: for all $j \in \mathbb{Z}$,
\[ x(j) := \begin{cases}
p(j + nt) & \text{if } \exists n \geq 0 \text{ s. t. } j - nt \in [k , k + t) \\
p(j - t) & \text{if } j \in [k + t, \ell + t] \\
p(j - nt) & \text{if } \exists n \geq 2 \text{ s. t. } j-nt \in (\ell-t, \ell].
\end{cases} \]
As a bi-infinite sequence, we see that 
\[ x = (p\vert_{[k,k+t)})^\infty \ p \ (p \vert_{(\ell-t, \ell]})^\infty, \text{ where } x(t) = p(0),   \]
where the notation $q^\infty$ means that a pattern $q$ is repeated periodically infinitely many times. 

\begin{claim} \label{claim-x}
Observe that $x$ satisfies 
\[ x(j) = x( j -t), \ \forall j > t \]
% \quad \text{and} \quad x(j) = x(j + t), \ \forall j < t. \]
\end{claim}
\begin{proof}
This follows by construction of $x$, and since,
\[  x(j) = p(j - t) = p(j) = x(j+t), \quad \forall j \in (t , \ell - t], \]
%For the second part. We have two cases. Suppose that $k+t \geq 0$. Then for all $j \in [k + t, t)$, we have $j - t \in [k, 0) \subset [k, k + t)$, so 
%\[ x(j-t) = p(j-t) = x(j). \]
%Suppose now that $k+t < 0$. Then, for all $j \in [k+t,0)$, we have $j-t \in [k,k+t)$ or $j-t \in [k+t,0)$. The first case follows as before, while for the second we have
%\[ x(j-t) = p(j - 2t) = p(j - t) = x(j). \]
\end{proof}

 \begin{claim}\label{uniqueness2}
 With the above construction, $(t \cdot x) \vert_S = p$ and $(r \cdot x) \vert_S \neq p$, $\forall r \in S \setminus \{t\}$. 
 \end{claim}
\begin{proof}
It is clear by definition that $(t \cdot x) \vert_S = p$. Suppose that $(r \cdot x) \vert_S = p$ for $r \neq t$. Then
\[ p(0)= (r \cdot x)(0)=x(r) \quad \text{and} \quad p(t) =(r \cdot x)(t) = x(r+t).   \]
If $r \in (t , \ell]$, by Claim \ref{claim-x}, $x(r+t) = x(r)$, so $p(t) = p(0)$, which is a contradiction. 

Suppose that $r \in [k, t)$. We will show that for $i \in (r,t)$ and $\epsilon \in \{ r,t\}$ such that $i- \epsilon \in S=[k, \ell]$, then $p(i) = p(i- \epsilon)$. If $i-t \in S$, then $p(i) = p(i-t)$ by hypothesis (\ref{hyp}). Suppose that $i - r \in [k, \ell]$ and $i - t \not\in [k,\ell]$. The latter condition implies $i - t < k$, so $i \in (r, k + t) \subset [k, k+t)$. Then, by the construction of $x$: 
\[ p(i) = x(i) = (r \cdot x)(i-r) = p(i-r). \]
The above shows that the hypothesis (\ref{hyp-seq}) of Lemma \ref{le-seq} is satisfied, so $p(0) = p(t)$, which is a contradiction. The result of the claim follows.  
\end{proof}

Now we prove that $\mu(q_s) = p(s)$ for all $s \in S$. For $s = t$, $q_t = p$ implies that
\[ p(t) =  a  = \mu(p) =  \mu((t \cdot x) \vert_S).  \]
For all $s \in S \setminus \{t\}$, Claim \ref{uniqueness2} shows that $(s \cdot x) \vert_S \neq p$, so
\[ \mu((s \cdot x) \vert_S) = (s \cdot x)(0) = x(s). \]
So the result would follow if we show that $x(s) = p(s)$ for all $s \in S \setminus \{t\}$. If $s \in [k,k+t)$, it is clear from the construction of $x$ that $x(s) = p(s)$. If $s \in [k+t,\ell] \setminus \{ t \}$, the construction of $x$ and hypothesis (\ref{hyp}) imply
\[ x(s) = p(s-t) = p(s).   \] 
The result follows. 
\end{proof}

\begin{example}
For $S=[-2,2]$, Theorem \ref{th-main} shows that a one-dimensional cellular automaton with a unique active transition $p=01010$ is idempotent, while one with a unique active transition $p=00101$ is not idempotent (in this case $t=-2$). 
\end{example}

\begin{example}\label{ex-not}
Theorem \ref{th-main} fails when $S$ is not an interval. For example, the cellular automaton with a unique active transition $p \in A^S$ given in Example \ref{counter} is not idempotent but does not satisfy the conditions of Theorem \ref{th-main}.  
\end{example}

\begin{proposition}\label{cor-x}
Let $S \subset \mathbb{Z}$ be an interval such that $0 \in S$. Let $\tau : A^{\mathbb{Z}} \to A^{\mathbb{Z}}$ be the cellular automaton with a unique active transition $p \in A^S$. If $\tau$ is not idempotent, then there exists $x \in A^{\mathbb{Z}}$ such that 
\[ \tau^n(x) \neq \tau^m(x), \quad \forall n,m \in \mathbb{Z}_+, \ n \neq m. \] 
\end{proposition}
\begin{proof}
 Let $S = [k, \ell] \subset \mathbb{Z}$ be such that $k \leq 0 \leq \ell$. Let $\mu : A^S \to A$ be the local rule generated by the pattern $p$. Let $a := \mu(p) \in A \setminus \{ p(e) \}$.
By Theorem \ref{th-main},  there exist $t \in S_+$ such that 
\[  p(t) = a \quad \text{ and } \quad p(i) = p(i-t), \  \forall i \in [k+t, \ell] \setminus \{ t \}. \]
This implies that $p \vert_{[k,0)}=p \vert_{[k+t,t)}$ and $p \vert_{(0, \ell - t]} = p \vert_{(t, \ell]}$.

We consider $x \in A^{\mathbb{Z}}$ as defined in the proof of Theorem \ref{th-main}:
 \[ x = (p\vert_{[k,k+t)})^\infty \ p \ (p \vert_{(\ell-t, \ell]})^\infty, \text{ where } x(t) = p(0). \]
We will show that $p$ only appears once as a subpattern in $x$. 
 \begin{claim}\label{uniqueness3}
  With the above construction, $(r \cdot x) \vert_S \neq p$, $\forall r \in \Z \setminus \{t\}$. 
 \end{claim}
 \begin{proof}
By Claim \ref{uniqueness2}, $(r \cdot x) \vert_S \neq p$, $\forall r \in [k, \ell] \setminus \{t\}$, so suppose that there exists $r > \ell$ or $r < k$ such that $(r \cdot x) \vert_S = p$. Then,
\[  (r \cdot x)(0)= x(r) = p(0) \quad \text{and} \quad (r \cdot x)(t)= x(r + t) = p(t).  \]
Recall that the construction of $x$ satisfies that $x(i) = x(i - nt)$ for all $i < k+t$, $n \in \mathbb{Z}_+$ and $x(i) = x(i+nt )$ for all $i > \ell - t$, $n \in \mathbb{Z}_+$. 

If $r < k$, then $r + t < k + t$, so 
\[ p(t) = x(r + t) = x(r + t - t) = x(r) =p(0),  \]
which is a contradiction. If $r > \ell$, then $r > \ell - t$, so
\[ p(0) = x(r) = x(r + t) = p(t), \]
which is also a contradiction. The result follows. 
 \end{proof}

The previous claim implies that all the terms in $\tau(x) \in A^\Z$ are the same as in $x \in A^\Z$ except that $x(t) = p(0)$ and $\tau(x)(t) = a$. Therefore,
\begin{align*}
 \tau(x) & = (p\vert_{[k,k+t)})^\infty \ p\vert_{[k,0)} \ a \ p \vert_{(0,\ell]} \ (p \vert_{(\ell-t, \ell]})^\infty  \\
 & = (p\vert_{[k,k+t)})^\infty \ p \vert_{[k+t,t)} \ p(t) \ p\vert_{(0, \ell - t]} \ p \vert_{(\ell-t, \ell]} (p \vert_{(\ell-t, \ell]})^\infty \\
 & = (p\vert_{[k,k+t)})^\infty \ p\vert_{[k,k+t)}\ p \vert_{[k+t,t)} \ p(t) \ p \vert_{(t, \ell]} \ (p \vert_{(\ell-t, \ell]})^\infty \\
& = (p\vert_{[k,k+t)})^\infty \ p \ (p \vert_{(\ell-t, \ell]})^\infty
\end{align*}
where $\tau(x)(0) = p(0)$. This shows that
\[ \tau(x) =  (-t) \cdot x. \]
Iterating, we see that
\[ \tau^n(x) = (-nt) \cdot x, \quad \forall n \in \mathbb{Z}_+.  \]
As $x$ is aperiodic (since $p$ appears only once as a subpattern), the result follows. 
\end{proof}

\begin{remark}
The proof of Theorem \ref{th-main} follows easily if we define
\[ x =  (a_k)^\infty \ (p\vert_{[k,k+t)}) \ p \ (a_\ell)^\infty, \text{ where } x(t) = p(0),   \]
and $a_k, a_\ell \in A$ are fixed symbols such that $a_k \neq p(k)$ and $a_\ell \neq p(\ell)$. However, the $x \in A^\Z$ that was actually chosen in the proof allows us to directly deduce Proposition \ref{cor-x}. 
\end{remark}


The \emph{space-time diagram} of a cellular automaton $\tau : A^\Z \to A^\Z$ with initial configuration $x \in A^\Z$ is a function $z : \mathbb{Z} \times \mathbb{N} \to A$ defined by $z(i,n) := \tau^n(x)(i)$, for all $n \in \mathbb{N}$ and $i \in \mathbb{Z}$. In the function $z$, we consider the input $n$ as the time and we allow $n=0$. When $A=\{0,1\}$, we shall depict a space-time diagram as a two-dimensional regular grid whose cells $(i,n)$ are colored in black when $z(i,n)=1$ and in white when $z(i,n) = 0$.  

\begin{example}
For $S=[-3,3]$ and $A=\{0,1\}$, the cellular automaton $\tau : A^\Z \to A^\Z$ with unique active transition $p=1101100 \in A^S$ is not idempotent as it satisfies condition of Theorem \ref{th-main} with $t = 3$. Figure \ref{fig1} shows the space-time diagram of $\tau$ with initial configuration $x \in A^\Z$ as given in the proof of Proposition \ref{cor-x}.
