\subsection*{Appendix: Python implementation}

The script below reproduces Fig.~1c. For a fast run, moderate values are chosen for the number of $E$-points for evaluation of the analytic curve and the dimension and number of samples for the random matrices. These can be increased for higher-quality output. The script can be adapted straightforwardly for other cases treated in the main text.

\begin{verbatim}
import numpy as np
import scipy as sp
import matplotlib.pyplot as plt

W=0.5
C=1
M=21
L=1000
sample=100

E=np.linspace(-3.5,3.5,100)
rho=np.zeros((len(E)))

fac=np.zeros((M))
fac[0]=1.0
fac[1]=1.0
for n in range(2,M):
 fac[n]=fac[n-1]*n

for i in range(len(E)):
 #precomputing the integrals in (31) and (33)
 hh=[sp.integrate.quad(lambda x: x**n*np.exp(1j*E[i]*x-C*x-(W*x)**2/2), 0, 20.0/C, limit=500,\
     complex_func=True)[0] for n in range(2*M)]
 hhh=[sp.integrate.quad(lambda x: x**n*np.exp(1j*E[i]*x-2*C*x-(W*x)**2/2), 0, 20.0/C, limit=500,\
     complex_func=True)[0] for n in range(2*M)]
 #precomputing the coefficients of the linear system (30) with beta0 set to 1
 A=np.zeros((M-1,M-1),dtype='complex_') #indices 0,1... correspond to beta1, beta2,...
 b=np.zeros((M-1),dtype='complex_')
 for n in range(M-1):
  A[n,n]=-1
  b[n]=-C**(n+1)*(1+np.sum([fac[n+1]*hh[m-1]/((-C)**m*fac[m]*fac[n+1-m]*fac[m-1])\
                             for m in range(1,n+2)]))/fac[n+1]
  for k in range(M-1):
   A[n,k]+=C**(n+1)*np.sum([fac[n+1]*hh[m+k]/((-C)**m*fac[m]*fac[n+1-m]*fac[m-1])\
                             for m in range(1,n+2)])/fac[n+1]
 x=np.linalg.solve(A,b)
 beta=np.zeros((M),dtype='complex_')
 beta[0]=1
 for n in range(1,M):
  beta[n]=x[n-1]
 #applying (33)
 rho[i]=np.real(np.sum([beta[k]*np.sum([beta[m]*hhh[m+k] for m in range(M)])\
                        for k in range(M)]))/np.pi

#sampling random matrices
eiglist=[]
for rept in range(sample):
 H=np.zeros((L,L))
 for i in range(L):
  H[i,i]=W*np.random.normal()
  if i<L-1:
   H[i,i+1]=1
   H[i+1,i]=1
 eiglist+=np.linalg.eigvalsh(H).tolist()

plt.hist(eiglist,bins=50,density=True,color='0.8')
plt.plot(E,rho,'k')
plt.xlim(-3.5,3.5)
plt.ylim(0,0.32)
plt.show()
\end{verbatim}\vspace{-5mm}

