&&-768(3242s^{5}-1755s^{4}+1832s^{3}+810s^{2}-4642s+81)u^{3} \\
&&384(8682s^{5}+11880s^{4}-16004s^{3}-9639s^{2}+5108s+837)u^{2} \\
&&-768(870s^{5}+1755s^{4}-7492s^{3}-810s^{2}+6912s-81)u \\
&&+384s(1192s^{4}-7695s^{3}-1728s^{2}+4617s+864) \\
&=&0\text{,}
\end{eqnarray*}%
and 
\begin{eqnarray*}
\frac{\partial h_{1}}{\partial u} &=&642816(s+1)^{2}(s-1)^{2}s(s-2)u^{3} \\
&&+768(1-s^{2})(1621s^{4}-1053s^{3}+2995s^{2}-243s-3968)u^{2} \\
&&+768s(1-s^{2})(1447s^{3}+2376s^{2}-2554s-837)u \\
&&+768(1-s^{2}))(145s^{4}+351s^{3}-1728s^{2}+81s+1728) \\
&=&0\text{.}
\end{eqnarray*}%
We have the following solutions 
\begin{eqnarray*}
&&\left\{ 
\begin{array}{c}
s_{1}\approx 1.43410, \\ 
u_{1}\approx 1.05959,%
\end{array}%
\right. \ \ \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{2}\approx 1.00000, \\ 
u_{2}\approx 1.69156,%
\end{array}%
\right. \ \ \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{3}\approx 0.08804, \\ 
u_{3}\approx 0.66270,%
\end{array}%
\right. \ \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{4}\approx 7.18284, \\ 
u_{4}\approx 0.10233,%
\end{array}%
\right. \\
&&\left\{ 
\begin{array}{c}
s_{5}\approx -0.57007, \\ 
u_{5}\approx 1.026200,%
\end{array}%
\right. \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{6}\approx -1.00000, \\ 
u_{6}\approx 0.767320,%
\end{array}%
\right. \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{7}\approx -2.29022, \\ 
u_{7}\approx 1.935860,%
\end{array}%
\right. \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{8}\approx -1.14653, \\ 
u_{8}\approx 5.513580,%
\end{array}%
\right. \\
&&\left\{ 
\begin{array}{c}
s_{9}\approx -1.00000, \\ 
u_{9}\approx -0.89449,%
\end{array}%
\right. \ \ \ \ \ \left\{ 
\begin{array}{c}
s_{10}\approx -1.02196, \\ 
u_{10}\approx -1.25556,%
\end{array}%
\right. \ \ \ \ \left\{ 
\begin{array}{c}
s_{11}\approx -1.00000, \\ 
u_{11}\approx -1.91450,%
\end{array}%
\right. \ \ \ \left\{ 
\begin{array}{c}
s_{12}\approx -0.01501, \\ 
u_{12}\approx -0.66009,%
\end{array}%
\right. \\
&&\left\{ 
\begin{array}{c}
s_{13}\approx 0.891700, \\ 
u_{13}\approx -0.67707,%
\end{array}%
\right. \ \ \ \ \left\{ 
\begin{array}{c}
s_{14}\approx 1.002780, \\ 
u_{14}\approx -1.37766,%
\end{array}%
\right.
\end{eqnarray*}%
The only point in $\left( 0,1\right) \times \left( 0,1\right) $ is $\left(
s_{3},u_{3}\right) $ and we see that $h_{1}(s_{3},u_{3})=588255.0757.$ All
cases have been dealt with, $\left( \ref{H3.0}\right) $ holds. \medskip

To see that $\left( \ref{H3.0}\right) $ is sharp, consider $f_{\ast }:%
\mathbb{D}\rightarrow 
%TCIMACRO{\U{2102} }%
%BeginExpansion
\mathbb{C}
%EndExpansion
$ given by 
\begin{equation*}
\left( zf_{\ast }^{\prime }\left( z\right) \right) ^{\prime }=\frac{1+z^{3}}{%
1-z^{3}}.
\end{equation*}%
Then $f_{\ast }\left( z\right) =z+\frac{1}{8}z^{4}+\frac{2}{49}z^{7}+\cdots $
with $a_{2}=a_{3}=0$ and $a_{4}=\dfrac{1}{8},\ a_{5}=0$ which from $\left( %
\ref{in3}\right) -\left( \ref{in4}\right) $ gives $A_{2}=A_{3}=0$ and $%
A_{4}=-\dfrac{1}{8},\ A_{5}=0.$ Now from $\left( \ref{h31}\right) ,$ we have 
$|H_{3}(1)\left( f_{\ast }^{-1}\right) |=\frac{1}{64}.$ This completes the
proof of the theorem.
\end{proof}

