\section{Filtrations and Hierarchical Depth on Surfaces}
\label{Sec:Hierar}
\subsection{Definition and properties of hierarchical depth}

\begin{defn}\label{Def:hierar}
Let $S$ be a smooth projective surface over a field $\F$, and let $L$ be a line bundle on 
$S$. A \textit{hierarchical filtration} of $L$ is a nested sequence of line bundles
$$\O_S=\L_0\subset\L_1\subset\ldots\subset\L_h=L,$$
with inclusions of coherent subsheaves, such that for each $i=1,\dots,h$, the quotient
$\L_i / \L_{i-1}$
is a torsion sheaf supported on an effective Cartier divisor, i.e., there exists a nonzero section
$$s_i\in H^0(S,\L_i\otimes\L^{-1}_{i-1})$$
whose vanishing locus defines an effective divisor. 

The maximal length of all finite hierarchical filtrations of $L$ is defined as \textit{hierarchical depth} of $L$ and denoted by $h(L)$.
\end{defn}


Note that $\L_{i-1}\subset\L_i$ is interpreted as inclusion of coherent sheaves or line subbundles. Meanwhile, the filtration provides a discrete, layered way of analyzing how sections of line bundles build up via effective divisors. It encodes geometric information into an algebraic length invariant.

\begin{defn}
For a divisor $D$ on a smooth projective variety $S$, the hierarchical depth $h(D)$ is defined $h(D):=h(\O_S(D))$.
\end{defn}

Given the hierarchical filtration of line bundles
$$\L_0\subset\L_1\subset\ldots\subset L_h=\O(D),$$
each step satisfies
$$\L_i=\L_{i-1}\otimes\O(E_i)$$
where $E_i$ is a divisor such that $\O(E_i)$ has a nonzero section, meaning that $E_i$ is effective. Taking $D_i=D_{i-1}+E_i$, we write $D_{i-1}\prec D_i$ and, moreover, we obtain a sequence
$$D_0\prec D_1\prec\dots\prec D_h = D,$$
which each step satisfies $D_i-D_{i-1}=E_i$ which is effective.

\begin{defn}  
(\cite{Ha, La}) Let $X$ be a projective variety over a field $\F$, and let $\L$ be a line bundle on $X$. The \emph{base locus} of $\L$, denoted $\mathrm{Bs}(\L)$, is defined as
$$\mathrm{Bs}(\L):= \bigcap_{s \in H^0(X, \L)}\{x \in X\mid s(x)=0\},$$
that is, the common zero locus of all global sections of $\L$. Equivalently, the base locus of a line bundle is the closed subset of points where all global sections of the line bundle vanish.

A line bundle is considered \textit{base-point free} if its base locus is empty.

\end{defn}

The following lemma guarantees the stability of positivity properties (such as nefness, bigness or ampleness) under the construction of nested effective divisors leading up to a given big or ample divisor $D$. It is easy to prove and we leave it unproven. For more details refer to \cite{Ha, La}.

\begin{lem}\label{lem:nef.big}
Let $S$ be a smooth projective surface, and let $D$ be a divisor on $S$ with the nested sequence 
$$\S_D:D_0\prec D_1\prec\ldots\prec D_h=D$$
where $E_i=D_i-D_{i-1}$ is effective. If $D$ satisfies at least one of the following conditions:
\begin{enumerate}[(i)]
\item $D$ is ample or
\item  $D$ is big and base-point free (and so nef);
\end{enumerate}
then $D_i$'s remain nef and/or big.
\end{lem}


The following expression for the hierarchical depth of a line bundle on a smooth projective surface is well known in the literature, appearing in standard references on intersection theory and the Riemann–Roch theorem. It can be found, for instance, in \cite[App. A.]{Ha}, \cite[Ch. 15]{Fu}, and \cite[Ch. II.8]{Be}, where it is derived using the Grothendieck–Riemann–Roch theorem for surfaces and basic properties of Chern classes. 

For a surface $S$ and a line bundle on it, we set $\h^i(L):=\dim H^i(S,L)$.

\begin{thm}
Let $S$ be a smooth projective surface and let $L$ be a line bundle on $S$ which is 1) ample or 2) big and base-point free. Then the hierarchical depth $h(L)$ equals the dimension of global sections
$$h(L)=\h^0(L)=\frac{1}{2}(c_1(L)^2-c_1(L)\cdot c_1(K_S))+\chi(\O_S).$$
\end{thm}
\begin{proof}
Let $L=\O_S(D)$ for an effective divisor $D$, and let $\L_i=\O_S(D_i)$ be the longest filtration of subline bundles such that
$$\L_0\subset\L_1 \subset\cdots\subset\L_h =\O_S(D),$$
where for each $i$, $D_i-D_{i-1}$ is effective and $ H^0(S,\O_S(D_i)/\O_S(D_{i-1}))\neq 0$.

Consider the short exact sequence
$$0\rightarrow\O_S(D_{i-1})\rightarrow \O_S(D_i)\rightarrow\O_{D_i-D_{i-1}}(D_i)\rightarrow 0.$$
\textbf{Step 1.} Since $D_i$ is big and nef (by assumption), Lemma \ref{lem:nef.big} and Kodaira or Kawamata-Viehweg vanishing (see \cite[Section 4.2.]{La}) implies
$$H^1(S,\O_S(D_{i-1}))=H^1(S,\O_S(D_i))=0,\quad H^2(S,\O_S(D_i))=0.$$
Thus, taking global sections gives
$$\h^0(D_i)=\h^0(D_{i-1})+\h^0(D_i-D_{i-1}).$$
Inductively, we find:
$$\h^0(D)=\sum_{i=1}^h\h^0(D_i-D_{i-1}).$$

By construction, each summand on the right is nonzero, and their total equals $\h^0(L)$. Therefore, the hierarchical depth, defined as the number of successive nonzero global sections contributed in the filtration, satisfies
$$h(L)=\h^0(L).$$

\textbf{Step 2.} For $h=1$, $D=D_1$, and Riemann–Roch for surfaces gives
$$\h^0(D_1)=\chi(\O_S(D_1))=\frac{1}{2}(D_1^2-D_1\cdot K_S)+\chi(\O_S),$$
since $H^1(S,\O_S(D_1))=H^2(S,\O_S(D_1))=0$ by vanishing.

\textbf{Step 3.} Suppose the formula holds for $D_{h-1}$, i.e.,
$$h(D_{h-1})=\frac{1}{2}(D_{h-1}^2-D_{h-1}\cdot K_S)+\chi(\O_S).$$
Let $D=D_h=D_{h-1}+E$ for some effective divisor $E$. Then
$$\h^0(D)=\h^0(D_{h-1})+\h^0(E,\O_E(D)).$$
By Riemann–Roch on the curve $ E $, and using the adjunction formula $2g_E-2=E\cdot (E+K_S)$ \cite[Ch. V, Proposition 1.5.]{Ha}, we compute
$$g_E=1+\frac{1}{2}(E^2+E\cdot K_S)$$
and 
$$\deg(D|_E)=D\cdot E=D_{h-1} \cdot E+E^2.$$
Therefore
$$\h^0(E, \O_E(D))=\deg(D|_E)-g_E+1=D_{h-1}\cdot E+\frac{1}{2}E^2-\frac{1}{2}E\cdot K_S.$$

Now we have
$$
\begin{aligned}
h(D) &= h(D_{h-1}) + \h^0(E, \O_E(D)) \\
&= \left[\frac{1}{2}(D_{h-1}^2 - D_{h-1} \cdot K_S) + \chi(\O_S)\right] + \left[D_{h-1} \cdot E + \frac{1}{2}E^2 - \frac{1}{2}E \cdot K_S\right].
\end{aligned}
$$
Since that
$$D^2=D_{h-1}^2+2 D_{h-1}\cdot E+E^2\ \text{and}\ 
D\cdot K_S=D_{h-1}\cdot K_S+E\cdot K_S,$$
an by induction, we obtain
$$h(L)=\h^0(S,L)=\frac{1}{2}(D^2-D\cdot K_S)+\chi(\O_S),$$
\end{proof}

\begin{exam}
Let $S=\P^2$, the complex projective plane. The canonical bundle of $\P^2$ is given by $K_{\P^2}=\O_{\P^2}(-3)$, and the Picard group is generated by the hyperplane class $H=\O_{\P^2}(1)$.

Let $L=\O_{\P^2}(d)$ be a line bundle corresponding to the divisor $D=dH$, with $d=2$. This corresponds to the sheaf of quadratic forms on $\P^2$, and we aim to compute the hierarchical depth $h(L)$.


\textbf{Step 1.} We compute Chern classes and intersection numbers:

Since $H^2=1$ we have
$$c_1(L)^2=(dH)^2=d^2 H^2=d^2$$
and
$$c_1(L)\cdot c_1(K_S)=dH\cdot (-3H)=-3d.$$

\textbf{Step 2.} We use the Riemann-Roch formula on surfaces. 

On $\P^2$, we have $\chi(\O_{\P^2})=1$, so the theorem gives
$$\h^0(\O_{\P^2}(d))=\frac{1}{2}(d^2+3d)+1.$$

When $d=2$, this yields
$$\h^0(\O_{\P^2}(2))= 6.$$

\textbf{Step 3.} Interpretation as a filtration:

The global sections of $ \O_{\P^2}(2) $ are quadratic homogeneous polynomials in $ x, y, z $, so the basis of $H^0(\P^2,\O(2))$ is
$$\{x^2, xy, xz, y^2, yz, z^2\},$$
corresponding to $h(L)=6$, which matches the number of linearly independent layers in a filtration built by vanishing loci of these monomials. Hence, we obtain a geometric realization of the filtration 
$$\L_0=\O_{\P^2}\subset\langle x^2\rangle\subset\langle x^2,xy\rangle\subset\langle x^2,xy,xz\rangle\subset\ldots\subset\langle x^2, xy, xz, y^2, yz, z^2\rangle=L.$$
where each successive quotient corresponds to a vanishing divisor defined by one of the basis elements above.

This confirms the theoretical result numerically and demonstrates the construction of depth filtrations in a concrete setting.
\end{exam}

\subsection{Dual depth}

Having understood the depth of a bundle $L$, it is natural to ask how its dual $L^{-1}$ behaves.  We establish vanishing conditions under which $h(L^{-1})$ collapses to zero, and we compare $h(L)$ and $h(L^{-1})$ in settings where the canonical divisor is trivial or $L$ is (anti-)canonical.


The dual of a divisor $D$ is denoted by $D^{-1}$.

\begin{thm}
Let $S$ be a smooth projective surface.
\begin{enumerate}
\item Suppose that
\begin{itemize}
\item $D$ is a nef and big divisor on $S$,
\item the canonical divisor $K_S$ is nef and semi-ample (e.g. the abundance conjecture holds for $S$).
\end{itemize}
Then $h(D^{-1})=0$.
\item Suppose that $K_S\sim 0$  (e.g., $S$ is a K3 surface or an abelian surface) and for a divisor $D\in\textrm{Pic}(S)$ such that
\begin{itemize}
\item $D.K_S=0$,
\item $D^2=0$,
\item $D$ is nef.
Then $$h(D)\approx h(D^{-1}).$$
\end{itemize}
\end{enumerate}
\end{thm}

\begin{proof}
\begin{enumerate}
\item By Serre duality (see \cite[III.7.6]{Ha}), we have:
$$H^0(S,\O_S(-D))\cong H^2(S,\O_S(K_S + D))^\vee.$$
Since $D$ is nef and big, and $K_S$ is nef and semi-ample, the Kawamata–Viehweg vanishing theorem implies:
$$H^1(S,\O_S(K_S+D))=H^2(S,\O_S(K_S+D))=0.$$
Therefore, by Serre duality,
$$H^0(S,\O_S(-D))=0,$$
which means there are no global sections of the dual line bundle $\O_S(-D)$. Thus,
$$h(D^{-1})=0.$$

\item When $K_S \sim 0$, Serre duality simplifies to:
$$H^0(S,\O_S(-D)) \cong H^2(S,\O_S(D))^\vee.$$
Since $D$ is nef and satisfies $D^2 = 0$, Riemann--Roch gives:
$$\chi(\O_S(D))=\frac{1}{2}(D^2-D\cdot K_S)+\chi(\O_S)=\chi(\O_S),$$
and since $K_S\sim 0$, the Euler characteristics of $\O_S(D)$ and $\O_S(-D)$ are equal. Moreover, since $D$ and $-D$ behave symmetrically under duality, and under the assumption of nefness, the cohomology groups $H^0(S, \O_S(D))$ and $H^0(S,\O_S(-D))$ have similar behavior. Hence, the number of non-zero vanishing sections and thus the hierarchical depth are approximately symmetric
$$h(D) \approx h(D^{-1}).$$

\end{enumerate}
\end{proof}

\begin{rem}
Let $S$ be a smooth projective surface and let $L$ be a line bundle on $S$ which is 1) ample or 2) big and base-point free. Let $L^{-1}$ be the dual of $L$. Since $c_1(L^{-1})=-c_1(L)$ we have
$$h(L^{-1})=\frac{1}{2}(c_1(L)^2+c_1(L)\cdot c_1(K_S))+\chi(\O_S).$$
In particular, when $L$ is self-dual, $L\cong L^{-1}$, then $c_1(L)=0$ and so $h(L)=h(L^{-1})=\chi(\O_S)$.
\end{rem}

\subsection{Functorial restriction to curves}

Curves inside a surface provide a bridge between two-dimensional geometry and more classical AG–code constructions. We define a functorial restriction of hierarchical filtrations to an embedded curve $C\subset S$ and prove that depth can only drop under this specialization. When the base locus is disjoint from $C$, depth is preserved, yielding a powerful tool to transfer surface-level filtrations into chain structured curve bundles.

Let $S$ be a smooth projective surface on a finite field $\F$. Let $C\subset S$ be a smooth curve on $S$ (or an effective Cartier divisor). For a line bundle $L$ on $S$, define
\begin{center}
$\HFil(S,L):=$ the category of hierarchical filtrations of $L$ on $S$
\end{center}
and $\HFil(C,L|_C)$ the analogous category on the curve $C$.

We define a functor
$$\Res_C:\HFil(S,L)\rightarrow\HFil(C,L|_C).$$

Let $\FF_S:=\{\L_i\}_{i=1}^h \in \HFil(S,\L)$ be a hierarchical filtration of line bundles on a smooth surface $S$, and let $C\subset S$ be a smooth curve satisfying the base locus condition. Define the restricted filtration:
$$
\Res_C(\FF_S):=\{\L_i|_C\}_{i=1}^h,
$$
which is a hierarchical filtration on $C$.

Each successive quotient $\L_i|_C\otimes (\L_{i-1}|_C)^{-1}$ defines an effective divisor on $C$, and hence contributes to the depth.

Moreover, if $\FF_S \to \FF'_S$ is a morphism (i.e., refinement of filtrations) with $\L_i \subset \L'_i$ for all $i$, then it follows that
$\L_i|_C \subset \L'_i|_C$ 
and so 
$\Res_C(\FF_S) \to \Res_C(\FF'_S)$
is a morphism in $\HFil(C,\L|_C)$. Thus, the restriction functor $\Res_C$ preserves the partial ordering.

\begin{thm}\label{restrict_h(L)}
Let $S$ be a smooth projective surface and $L$ a line bundle on $S$. For effective divisor (curve) $C$ on $S$ we have $h(L|_C)\leq h(L)$.

Moreover, the equality is preserved if the \emph{base locus condition} 
$$\text{for all } i, \quad C \nsubseteq \mathrm{Bs}(\L_i \otimes \L_{i-1}^{-1})$$
holds.
\end{thm}
\begin{proof}
We define the hierarchical depth $h(L)$ as the length of the longest filtration
$$0=\L_0\subset\L_1\subset\ldots\subset\L_h=L$$
where each successive quotient has nonzero sections $H^0(S,\L_i\otimes\L^{-1}_{i-1})\neq 0$. Now, for each such quotient, restricting to the curve gives
$$(\L_i\otimes\L^{-1}_{i-1})|_C=\L_i|_C\otimes(\L_{i-1}|_C)^{-1}.$$
There is a natural restriction map
$$H^0(S,\L_i\otimes\L^{-1}_{i-1})\rightarrow H^0(C,\L_i|_C\otimes(\L_{i-1}|_C)^{-1}).$$
However, this map may fail to be injective or surjective depending on whether the base locus of the line bundle includes the curve $C$. That is, if $C\subseteq Bs(\L_i\otimes\L^{-1}_{i-1})$, then all sections vanish along $C$, and the image of the restriction map is zero.

Hence, in general, some stages of the filtration may vanish upon restriction. So the length of the filtration on the curve may drop and $h(L|_C)\leq h(L)$. 

The base locus condition ensures that the restricted sections
$$s_i|_C\in H^0\left(C,\L_i|_C\otimes (\L_{i-1}|_C)^{-1}\right)$$
are nonzero, so each successive quotient restricts to an effective divisor on $C$. In particular, this implies that the hierarchical depth is preserved under restriction:
$$
h(\L|_C)\geq h(\L).
$$
It follows that when the base locus condition holds, the depth is preserved, we have 
$h(\L)=h(\L|_C) $.
\end{proof}

\section{AG Codes from hierarchical filtrations}
\label{AG codes}

Hierarchical filtrations on curves give rise directly to nested sequences of evaluation codes. In this section, we show how the depth-induced code chain leads to explicit rate-distance trade-offs and optimal middle layers.

\begin{defn}
\cite{Au, Li}
(AG codes on surfaces)
Let $S$ be a smooth projective surface defined over a finite field $\F_q$, and let $\L$ be a line bundle (or equivalently, a divisor class) on $S$. Let $\Gamma = \{P_1, \dots, P_n\} \subset S(\F_q)$ be a set of $\F_q$-rational points disjoint from the base locus of $\L$.

The \emph{algebraic geometry code} $C_L(\Gamma,\L)$ associated to $(S,\L,\Gamma)$ is defined as the image of the evaluation map
$$\ev_\Gamma \colon H^0(S,\L)\longrightarrow \F_q^n, \qquad f \mapsto(f(P_1),\dots,f(P_n)).$$
That is,
$$C_L(\Gamma,\L):=\ev_\Gamma(H^0(S,\L))\subseteq \F_q^n.$$
\end{defn}

Assume
$$\L_0\subset\L_1\subset\ldots\subset\L_h=L$$
is a hierarchical filtration (i.e., each $\L_i$ has $H^0(S,\L_i\otimes\L^{-1}_{i-1})\neq 0).$ Set $$V_i:=H^0(C,\L_i)\subset H^0(C,L).$$

Each $V_i$ induces a subcode
$$\C_i=\ev_\Gamma(V_i)\subset \C_\Gamma(D)$$
yielding a filtered chain of codes
$$\C_0\subset\C_1\subset\ldots\subset\C_h=\C_\Gamma(D).$$
This filtration reflects the hierarchical depth and geometrically stratifies the space of codewords.

It is clear that 
$$\dim\C_1\leq\dim\C_2\leq\ldots\leq\dim\C_h$$
which follows that code rate $R_i=(\dim\C_i)/n$ and efficiency are non-decreasing.

For a nonzero global section $s\in H^0(X,\L_i)$ the notation $\dv(s)$ denotes the divisor of zeros of the section $s$:
$$\dv(s)=\sum_{P\in S}\ord_P(s).P,$$
where $\ord_P(s)$ to be the order of vanishing of $s$ at $P$. 
Balancing rate and distance is a major open problem in coding theory. We introduce a product-utility $Q=(k/n)d$ and prove that, on elliptic and higher genus curves, there is a unique filtration index $i^*$ that maximizes $Q$.  This identifies a single ``best'' code in the entire nested family.

In coding theory, particularly analyzing the trade-off between code rate $R$ and minimum distance $d$ is instrumental and helps identify optimal codes that balance these two conflicting objectives.

A code is called \textit{dominant} when it is at least as good as another code in terms of speed and distance, and is significantly better than it in at least one of these measures.

To turn $(R,d)$ into a single number, we choose a utility function. For a code $\C$ with code rate $R(\C)$ and minimum distance $D(\C)$ define the product score $$Q(\C)=R(\C).D(\C)=\frac{k}{n}d.$$
A higher $Q$ means a better balance of rate and protection.

\begin{lem}
\label{lem:base-point-free-distance}
Let $X/\F_q$ be a smooth projective curve, let $\L$ be a line bundle on $X$, and let $\Gamma =\{P_1,\ldots,P_n\}\subset X(\F_q)$ be a set of distinct rational points disjoint from the base locus of $\L$. Suppose $\L$ is base-point free, i.e., for all $P \in X$, there exists $s \in H^0(X, \L)$ with $s(P) \neq 0$. Then the evaluation code
$$\C=\ev_\Gamma(H^0(X, \L))\subset\F_q^n$$
satisfies
$$d=\min_{s\neq 0} \#\{i:s(P_i)\neq 0\}=n-\deg(\L).$$
In particular, this holds generically for randomly chosen $\Gamma$ (i.e., when $\Gamma$ avoids vanishing sets of nonzero global sections).
\end{lem}

\begin{proof}
Since $\L$ is base-point free, every nonzero section $s\in H^0(X,\L)$ vanishes at most on a divisor of degree $\deg(\L)$, and this zero locus does not include all of $\Gamma$ (since $\Gamma$ is disjoint from the base locus). Thus, for any $s\neq 0$, the number of evaluation points $P_i\in\Gamma$ where $s(P_i)=0$ is at most $\deg(\L)$, so the number of nonzero coordinates in the codeword is at least $n-\deg(\L)$. Since equality is achieved when the zeros of $s$ lie entirely inside $\Gamma$, we have $d=n-\deg(\L)$ generically.
\end{proof}

\begin{prop}
\label{prop:middle-layer}
Let $X/\F_q$ be a smooth projective curve of genus $g$, and let
$$\L_0\subset\L_1\subset\cdots\subset\L_m$$
be a degree-filtration of line bundles on $X$, where each step
$\L_i=\O_X(D_i)$ satisfies $\deg D_i=i$. Suppose further that:
\begin{itemize}
  \item each $\L_i$ is base-point free, and
  \item the evaluation set $\Gamma\subset X(\F_q)$ is disjoint from $\Supp(D_m)$.
\end{itemize}
For each $0\leq i\leq m$, write
$$k_i=\dim H^0(X,\L_i),\quad Q_i=\frac{k_i}{n} d_i.$$
Then, for $i\ge 2g-1$, the quantity $Q_i$ is maximized at
$$i^*=\min\left(m,\left\lfloor \frac{n+g-1}{2} \right\rfloor \right).$$
\end{prop}

\begin{proof}
For $i\geq 2g-1$, the Riemann–Roch theorem on the curve $X$ gives
$$k_i=\dim H^0\bigl(X,\L_i\bigr)=\deg(D_i)-g+1=i+1-g,$$
since $\deg D_i=i$ and $H^1(X,\L_i)=0$. By the Goppa (or designed-distance) bound,
$$d_i\geq n-\deg D_i=n-i$$
and by Lemma \ref{lem:base-point-free-distance} we assume $d_i=n-i$. Hence for $i\ge 2g-1$ we have
$$Q_i=\frac{k_i}{n} d_i=\frac{i+1-g}{n} (n - i).$$

\medskip\noindent
\textbf{Step 1.}
Consider the real function
$$
f(i)=(i+1-g)(n-i)=-(i+1-g)i+(i+1-g)n.
$$
Its second derivative with respect to $i$ is
$$
f''(i)
=\frac{d^2}{di^2}\bigl[-i^2 + (n+1-g)i + (n(g-1))\bigr]
=-2 < 0.
$$

\medskip\noindent
\textbf{Step 2.}
Differentiating,
$$f'(i)=\frac{d}{di}\bigl[(i+1-g)(n-i)\bigr]=(n-i)-(i+1-g)= n-2i-1+g.$$
Setting $f'(i)=0$ yields
$$n-2i-1+g=0\quad\Longrightarrow\quad
i = \frac{n + g - 1}{2}.
$$
By strict concavity, this critical point is the unique global maximum of $f$ on $\R$.

\medskip\noindent
\textbf{Step 3.}
Since $i$ must be an integer $0\leq i\leq m$, the maximum of $Q_i=f(i)/n$ occurs at
$$
i^*
=\min\Bigl(m,\;\bigl\lfloor\tfrac{n+g-1}{2}\bigr\rfloor\Bigr),
$$
or, if $\bigl\lceil(n+g-1)/2\bigr\rceil\le m$ and is closer to $(n+g-1)/2$, one may choose that integer instead. In either case, $i^*$ is the integer in $[0,m]$ nearest to $\tfrac{n+g-1}{2}$. Thus $Q_i$ is maximized exactly at $i=i^*$, establishing the theorem.
\end{proof}

The following lemma can be found in \cite{ArCoGrHa, EiHa, Ha} and leads to a corollary of Proposition \ref{prop:middle-layer} on elliptic curves.

\begin{lem}
\label{lem:elliptic-bpf-fq}
Let $E/\F_q$ be a smooth projective elliptic curve over a finite field $\F_q$, and let $\L\cong\O_E(D)$ be a line bundle of degree $\deg D\geq 1$. Then $\L$ is base-point free over $\F_q$, and in particular, every rational point $Q\in E(\F_q)$ is not a base point of $\L$.
\end{lem}

\begin{proof}
Let $D$ be a divisor of degree $d\geq 1$ on $E$. Since $E$ has genus $g=1$, the Riemann–Roch theorem gives
$$\dim H^0(E,\O_E(D))=d.$$
Let $Q\in E(\F_q)$. To show that $Q$ is not a base point, we must show that there exists a section $s\in H^0(E,\O_E(D))$ such that $s(Q)\neq 0$. Equivalently, the evaluation map at $Q$,
$$\ev_Q: H^0(E, \O_E(D))\to\F_q,\quad s\mapsto s(Q),$$
is not identically zero. But if all global sections vanished at $Q$, then they would factor through $\O_E(D-Q)$, which has degree $d-1$. Hence,
$$\dim H^0(E,\O_E(D-Q))=d-1,$$
so the kernel of $\ev_Q$ has codimension one in $H^0(E,\O_E(D))$, and therefore $\ev_Q$ is nontrivial. This proves that there exists a section not vanishing at $Q$, so $Q$ is not a base point.

Since $Q\in E(\F_q)$ was arbitrary, $\L$ is base-point free at all $\F_q$-rational points.
\end{proof}


\begin{cor}
Let $E(\F_q)$ be an elliptic curve, and let $\Gamma=\{P_1,\ldots,P_n\}\subset E(\F_q)$ be a set of $n$ disjoint rational points in $E(\F_q)$. Let $D=mP$ for some point $P\in E(\F_q)$ with $\Gamma\cap Supp(D)=\emptyset$ and $m<n$.
$$\L_0\subset\L_1\subset\ldots\subset\L_h=L=\O(D)$$
be a nested sequence of line bundles with $\L_i=\O(iP)$. Set $\C_i$ the evaluation code from $\O(iP)$. Then its rate-distance trade-off
$Q_i=(k_i/n)\,d_i$ is maximized at
$$i^*=\min\{m,\lfloor\frac{n}{2}\rfloor\}.$$

In particular, all codes appeared in filtration are dominated by $\C_{i^*}$.
\end{cor}
\begin{proof}
The assertion follows from combining Lemma \ref{lem:elliptic-bpf-fq}, Lemma \ref{lem:base-point-free-distance} and Proposition \ref{prop:middle-layer}.
\end{proof}

\section{Vanishing Orders Along Arcs}
\label{Vanishing}
\subsection{On the formal arcs}
The study of \emph{formal arcs} provides a geometric lens to understand higher-order contact of divisors on algebraic varieties. In this section, we relate the combinatorial structure of maximal filtrations of line bundles to the geometric behavior of divisors under pullback along arcs. This connection links our invariant of filtration depth to the modern theory of arc spaces and jet schemes.

Let $X$ be a smooth algebraic variety over a field $\F$ (typically a curve or surface), and let $D$ be an effective divisor on $X$ (that is, a formal finite sum of codimension-1 integral subvarieties with non-negative coefficients). A \emph{formal arc} is a scheme-theoretic map
$$\gamma: \Spec(\F[[t]])\to X,$$
which may be viewed as a formal germ of a curve on $X$ or as an infinitesimal path into $X$. The collection of all such arcs forms the \emph{arc space} $X_\infty$ of $X$, introduced systematically by Nash and developed extensively in the study of motivic integration and singularities (see \cite{DeLo}, \cite{EiMu}, \cite{Is14}).

Given a line bundle $\L\cong \O_X(D)$ and a global section $s \in H^0(X,\L)$, the pullback $\gamma^*s \in \F[[t]]$ is a power series whose order of vanishing defines a key invariant
$$\ord_\gamma(s):=\ord_t (\gamma^*s),$$
where $\ord_t$ denotes the $t$-adic valuation. This quantity measures the order of contact between the arc $\gamma$ and the divisor $D = \dv(s)$ (cf. \cite[Section 4]{EiMu} and \cite[Chapter 9]{La}).

We now formalize the connection between arc vanishing orders and maximal filtrations of line bundles on curves.

\begin{thm}
\label{thm:contact-filtration}
Let $X/\F_q$ be a smooth projective curve of genus $g$, and let
$$\L_0\subset\L_1\subset\cdots\subset\L_h$$
be a maximal chain of line bundles such that for each $i$, there exists a closed point $P_i \in X$ with
$$\L_i\cong\L_{i-1}(P_i),$$
i.e., each successive bundle is obtained by twisting by an effective divisor of degree one. Let $D_i=P_i$ denote these degree-1 effective divisors. Then
$$h=\max_{\gamma\in X_\infty}\#\{i :\ord_\gamma(D_i)\geq 1\}.$$
\end{thm}

\begin{proof}
We prove the two inequalities separately.

``$\geq$'': Each condition $\ord_\gamma(D_i) \geq 1$ imposes a linear constraint on the first jet of the arc $\gamma$ at the corresponding point $P_i$. Because the filtration is maximal, any further twisting by a new point would produce a line bundle not contained in the chain, violating maximality. Therefore, no arc can simultaneously satisfy more than $h$ such vanishing conditions
$$h\geq \max_{\gamma \in X_\infty}\#\{i :\ord_\gamma(D_i)\geq 1\}.$$


``$\leq$'': Let $P_1,\dots,P_h$ be the (not necessarily distinct) points determining the filtration. Choose one point, say $P:=P_h$. Then the completed local ring at $P$ is $\widehat{\O}_{X,P} \cong \F_q[[t]]$, and the inclusion $\Spec(\F_q[[t]])\hookrightarrow X$ defines an arc
$$\gamma: \Spec(\F_q[[t]])\to X$$
whose image lies entirely at $P$. For any $D_i=P_i=P$, the pullback $\gamma^*s_i$ of a local section $s_i$ defining $D_i$ vanishes to order at least $1$ in $\F_q[[t]]$. Thus,
$$\#\{i :\ord_\gamma(D_i)\geq 1\} = h,$$
and therefore
$$h \leq \max_{\gamma \in X_\infty} \#\{i : \ord_\gamma(D_i) \geq 1\}.$$

Combining both directions proves the theorem.
\end{proof}

This result reveals a precise link between the algebraic structure of filtered line bundles and the geometry of arc spaces. In particular, the depth of a hierarchical code construction is governed by the number of divisors that an arc can simultaneously contact to first order. Similar techniques appear in the study of log canonical thresholds and jet schemes; see \cite{DeLo}, \cite{EiMu}, \cite{Mus} for general treatments.

\subsection{On the combinatorial arcs}

A \textit{$k$-arc} of points in $\P^{n}/\F_q$ is a set $A$ of points with the property that no $n+1$ points of $A$ lie in a hyperplane; equivalently, if every subset of $k$ (distinct) points of $A$ is projectively independent.

A $k$-dimensional linear code of length $n$ and minimum distance $d$ is a $k$-dimensional subspace of $\F^n_q$ in which every non-zero vector has weight at least $d$. Such a code is called an \textit{$\F_q$-linear $[n,k,d]-$code}, where $n$, $k$, and $d$ are often referred to as the parameters of the code (see \cite{HuPl} for related notions and more details on linear codes).

A $k$-dimensional linear \textit{maximum distance separable (MDS)} code $\C$ of length $n$ is a $k$-dimensional subspace of $\F^n_q$ in which every non-zero vector has weight at least $n-k+1$. 

It is well known \cite{BrThBl} that the linear code $\C$ generated by the matrix $G$, whose columns are the coordinate vectors of the points of an arc is a linear MDS code, and vice versa, the set of columns of a generator matrix of an MDS code considered as a set of points of the projective space, is an arc. The interplay between the MDS property and arc configurations is well documented in the literature; see for example \cite{BaLa, BaWe} for comprehensive treatments of these notions.

\begin{prop}
Let $\L_i$ be a vector space of dimension $\dim\L_i=i+1$, and let $\D=\{P_1,\ldots,P_n\}$ be a set of rational points on a projective variety. Define the evaluation map
$$\ev_i:\L_i\to\F^n_q,\ s\mapsto (s(P_1),\ldots,s(P_n)),$$
and let $\A_i\subset\P^i/\F_q$ be
$$\A_i:=\{[s(P_j)]_{P_j\in\D}\in\P^{n-1}:s\in\L_i\backslash\{0\}\}.$$ Then, if the evaluations at distinct points are linearly independent (i.e., form an $(i+1)$-arc), we must have $$|\A_i|\leq q+i.$$
\end{prop}
\begin{proof}
Since $\dim\L_i=i+1$, the image of the evaluation map (up to projectivization) lies in a projective space of dimension $i$, i.e., $\P^i/\F_q$. It follows from Proposition 2.5.3 of \cite{BaWe} that a $(i+1)$-arc in $\P^i/\F_q$ can have at most $q+i$ points. Therefore, the set $\A_i$ formed from evaluations of $\L_i$ over $\D$ can have at most $q+i$ elements if the evaluation points are in general position (i.e., span the whole space). This completes the proposition.
\end{proof}

Let $X/\F_q$ be a smooth projective curve of genus $g$, and let $\D=\{P_1,\dots,P_n\} \subset X(\F_q)$ be a set of $n$ distinct rational points. Suppose
$$\L_0\subset\L_1\subset\cdots\subset\L_r$$
is a filtration of line bundles on $X$ satisfying
\begin{equation}
\label{eq:dimH0}
\dim H^0(X,\L_i)=i+1\quad\text{for all }i=0,1,\dots,r.
\end{equation}
Let $\C_i$ denote the evaluation code associated to $\L_i$. For an arbitrary $i \in \{0,1,\dots,r\}$, by Riemann--Roch, we have
$$\dim H^0(X, \L_i)-\dim H^1(X,\L_i)=\deg\L_i-g+1.$$
Using the assumption \eqref{eq:dimH0}, we have
$$i+1-\dim H^1(X,\L_i)=\deg\L_i-g+1.$$
Rearranging, we find
$$\deg\L_i=i+g+\dim H^1(X,\L_i).$$
So in particular
\begin{equation}
\label{eq:degL}
\deg\L_i\geq i+g,
\end{equation}
with equality if and only if $H^1(X,\L_i)=0$.

Now consider the Goppa bound for the minimum distance $d(\C_i)$ of the code $\C_i$:
$$d(\C_i)\geq n-\deg\L_i.$$
On the other hand, the Singleton bound says that
$$d(\C_i)\leq n-k+1=n-(i+1)+1=n-i.$$
Thus for $\C_i$ to be MDS (i.e., for both bounds to be equalities), we require
$$n-i=d(\C_i)=n-\deg\L_i,$$
which implies $\deg\L_i=i.$
But from \eqref{eq:degL}, we have $\deg\L_i\geq i+g$. Hence the only possibility for $\deg \L_i=i$ is if $g=0$ and $H^1(X,\L_i)=0$. 

Now, define
$$d_{\MDS}:=\max\{i\in\{0,1,\dots,r\}:\deg\L_i=i+g\}.$$
Then for each $i\leq d_{\MDS}$, we have
$$\deg \L_i=i+g\ \text{and}\ H^1(X,\L_i)=0$$
and hence the Goppa bound becomes $d(\C_i)\geq n-\deg\L_i=n-i-g$ and the Singleton bound is $d(\C_i)\leq n-i$.

Combining, we get
$$\C_i\text{ is MDS}\quad\Longleftrightarrow \quad g=0,$$

Hence, we interpret the index $d_{\MDS}$ as the maximal depth up to which the filtration has the best-possible Goppa behavior, and for $g=0$, this coincides with being MDS.

These results lead us to the following theorem:

\begin{thm}
\label{thm:mds-depth}
Let $X/\F_q$ be a smooth projective curve of genus $g$, and let $\D=\{P_1,\dots,P_n\} \subset X(\F_q)$ be a set of $n$ distinct rational points. Suppose
$$\L_0 \subset \L_1 \subset \cdots \subset \L_r$$
Denote by $\C_i$ the evaluation code associated to $\L_i$. Let 
$$\dim\C_i=i+1\quad \text{for all }i=0,1,\dots,r.$$
Set $$d_{\MDS}:=\max\{i\in\{0,1,\dots,r\}:\deg\L_i=i+g\}.$$
Then for $i\leq d_{\MDS}$,
$$\C_i\text{ is MDS}\quad\Longleftrightarrow\quad g=0.$$

In particular, when $g=0$ (i.e. $X =\P^1$), the filtration yields MDS codes precisely up to depth $d_{\MDS}=n-1$ and when $g>0$ then $d_{\MDS}=0$. 

\end{thm}

Let $X/\F_q$ be an irreducible smooth projective curve. Let $\Gamma=\{P_1,\ldots,P_n\}$ be a set of rational points on $X$ and $D=P_1+P_2+\ldots+P_n$ a divisor. Furthermore $G$ is some other divisor that has support disjoint from $D$. Then algebraic geometric code $C_L(\Gamma,\O_X(G))$ is defined as the image of the evaluation map
$$\ev_\Gamma \colon H^0(X,\O_X(G)) \longrightarrow \F_q^n, \qquad f \mapsto \left(f(P_1), \dots, f(P_n)\right).$$
is called \textit{geometric Reed-Solomon} code. It is a known result in coding theory that Reed-Solomon codes are MDS.

The linear codes $\C_1$ and $C_2$ are \textit{monomially equivalent} if one can be transformed into another one through a combination of coordinate permutations and scalar multiplications of the codeword elements (see \cite{HuPl} for more details).

\begin{thm}
\label{thm:non-rs-mds}
Let $X/\F_q$ be a smooth projective curve of genus $g \geq 1$, and let $\D=\{P_1,\dots,P_n\} \subseteq X(\F_q)$ be a set of $n$ distinct rational points.

Let 
$$0\prec D_1\prec D_2\prec\cdots\prec D_k\prec D_{k+1}\prec\cdots$$
be a nested filtration of divisors on $X$ with $\deg D_k=k$ for each $k$, and suppose $H^1(X,\O_X(D_k))=0$. Denote by $\C_i$ the evaluation code associated to $D_i$.

Then
\begin{enumerate}
\item For each $k$ with $1\leq k\leq q$, any MDS $[n,k]$-code over $\F_q$ is monomially equivalent to a Reed–Solomon code.
\item If $k>q$ and $\C_k$ is MDS, then $\C_k$ cannot be monomially equivalent to any Reed–Solomon code over $\F_q$ because Reed–Solomon codes have dimension at most $q$.
\end{enumerate}
In particular, maximal or optimal curves with many rational points can yield families of MDS codes with dimension $k>q$, which are necessarily non–Reed–Solomon.
\end{thm}
\begin{proof}  
By the classical theory of MDS codes, any linear MDS $[n,k]$-code over $\F_q$ with $k\leq q$ and length $n\leq q+1$ must be monomially equivalent to a generalized Reed–Solomon (GRS) code. This follows from the well-known characterization of MDS codes of length at most $q+1$ (see \cite[Theorem 5.3.4]{HuPl} or \cite{MaSl}). Thus, (1) and (2) are resulted.

If $X$ is a curve with many rational points (for example, an elliptic curve with $N_q>q+1$ or a maximal curve over $\F_{q^2}$) then one may construct codes $\C_k$ with dimension $k>q$ and still satisfy the MDS property if the divisor and point set yield an arc in the corresponding projective space.  
Such MDS codes therefore form families of non–Reed–Solomon MDS codes.
\end{proof}

\begin{exam}
Consider the elliptic curve 
$$X/\F_5:y^2=x^3+x+1.$$
This curve is nonsingular and has genus $g=1$.

A simple point-count (or refer to \cite{Web}) shows that $\# X(\F_5)=9.$
In particular, $N_5=9>q+1=6$.

Fix the rational point set $\D=X(\F_5)\setminus\{[\infty]\}$.
For any $k$ with $2\leq k\leq 8$, define the divisor $D_k:=(k-1)[\infty].$ Then $\deg D_k=k-1$. Also, $H^1(X,\O_X(D_k))=0$ and $\dim H^0(X,\O_X(D_k))=k-1$ for $k>1$.

For $2\leq k\leq 8$ we obtain a sequence
$$D_2\prec D_3\prec\dots\prec D_8$$
of divisors and the corresponding evaluation codes $\C_2,\C_3,\ldots,\C_8$.

By the standard embedding of $X$ via $|D_k|$, the image of $\D_k$ forms a $k$-arc in $\P^{k-1}(\F_5)$ when no $k$ points lie on a hyperplane. In this classical elliptic curve setting, it is known that the rational points do not lie on a line or hyperplane in general position for small $k$. Hence, the resulting evaluation code
$\C_k$ has dimension $k-1$. The Singleton and Goppa bounds imply that $\C_k$'s are MDS. Moreover, because $N_5>q+1$, none of $\C_k$'s cannot be monomialy equivalent to a Reed-Solomon code.

\end{exam}

\begin{rem}
\label{rem:RS-vs-nonRS-filtration}
Let $X/\F_q$ be a smooth projective curve with $N_q=\#X(\F_q)$ rational points. Fix a set $\D\subset X(\F_q)$ of $n$ distinct rational points and build a filtration of divisors
$$0\prec D_1\prec D_2\prec\cdots\prec D_r$$
with $\deg D_k = k-1$, $H^1(X,\O_X(D_k))=0$. Then the evaluation codes
$\C_k$ with $\dim\C_k=k-1$ are MDS.

By the classical theory of MDS codes (implied in above proof), if the length satisfies $n\leq q+1$ and $k\leq q$, then any MDS $[n,k-1]$-code over $\F_q$ is monomially equivalent to a Reed–Solomon code. If $n > q+1$, then no MDS $[n,k-1]$-code is equivalent to a Reed–Solomon code, regardless of $k$.

Therefore, it is impossible to construct a filtration of $\C_k$'s with the same evaluation set $\D$ such that
$$
\underbrace{\C_1 \subseteq \cdots \subseteq \C_{t}}_{\text{RS}}
\subseteq
\underbrace{\C_{t+1} \subseteq \cdots \subseteq \C_r}_{\text{non-RS}}.
$$
If we want to combine both Reed–Solomon and genuinely non–Reed–Solomon MDS codes in a single family, we must vary the evaluation set (for example, by puncturing) so that the shorter codes use a subset $\D'\subseteq\D$ of size $\leq q+1$.
\end{rem}

\begin{exam}
\label{exam:RS-nonRS-numerical}
Consider the elliptic curve
$$X/\F_5:y^2=x^3+x+1.$$
Let $\D=X(\F_5)\setminus\{[\infty]\}$.

\textbf{Step 1: RS part.}
Choose a subset
$$
\D'\subset\D\quad \text{with }\#\D'=6.$$
So $n'=6=q+1$.
Then for $2\leq k\leq 6$, the codes
$$\C'_k=\ev_{\D'}(H^0(X,\O_X(D_k))),\quad D_k=(k-1)[\infty],\quad\dim \C'_k=k-1,$$
are MDS with Singleton bound $d(\C'_k)=7-k$.  
Because $n'=6=q+1$, these are monomially equivalent to Reed–Solomon codes.

\textbf{Step 2: Non–RS part.}
Now use the full point set $\D$ with $n=8$.  
For $7\leq k\leq 8$ define:
$$\C_k:=\ev_{\D}(H^0(X,\O_X(D_k))),\quad D_k=(k-1)[\infty].$$
These codes have $\dim \C_k=k-1$, $d(\C_k)=9-k$. Since $n=8>q+1=6$, they are MDS but cannot be Reed–Solomon.

Therefore, the sequence
$$
\underbrace{\C'_2,\C'_2,\dots,\C'_6}_{\text{MDS, RS}},
\underbrace{\C_7,\C_8}_{\text{MDS, non-RS}}
$$
gives an explicit filtration producing both Reed–Solomon and non–Reed–Solomon MDS codes from the same curve.
\end{exam}


