\title{Equivariant KK-theory and model categories}
\author{\scalebox{1.1}{Anupam Datta \thanks{Universität Bonn, anupamd@math.uni-bonn.de}, Michael Joachim\thanks{Universität Münster, joachim@uni-muenster.de}}}

\date{}
