\begin{defi}\label{defi: hom eq c*}
    Let $A,B$ be $G$-C*-algebras. We denote by $\operatorname{Hom}(A,B)$ the set of $G$-equivariant $*$-homomorphisms from $A$ to $B$, equipped with the compact-open topology. Two $G$-equivariant $*$-homomorphisms $\varphi_0, \varphi_1 : A \rightarrow B$ are said to be $G$-homotopic (denoted $\varphi_0 \sim_G \varphi_1$)if there exists a $G$-equivariant $*$-homomorphism $\Phi: A \rightarrow C([0,1],B)$ such that $\varphi_i=\operatorname{ev}_i \circ \Phi$.
\end{defi}
\begin{rem}\label{rem: fav adj}
    It is well known (see \cite[Proposition 2.4]{UUY}, \cite[Lemma 3.3]{MJ}) that we have a natural homeomorphism of spaces
    \[
    \operatorname{Map}(X,\operatorname{Hom}(A,B)) \cong \operatorname{Hom}(A,\mathcal{C}(X,B)) ~\text{where}~ X \in \operatorname{Cpt}, A,B \in G\text{-}C^*.
    \]
    Thus, we get that two $G$-equivariant $*$-homomorphisms $A \rightarrow B$ are $G$-homotopic iff they are path connected in $\operatorname{Hom}(A,B)$.
\end{rem}
\begin{defi}
    Two $G\text{-}C^*$-algebras are said to be $G$-homotopy equivalent if there exists $G$-equivariant $*$-homomorphisms $\varphi: A \rightarrow B$, $\psi: B \rightarrow A$ such that $\varphi \circ \psi \sim_G 1_B$, $\psi \circ \varphi \sim_G 1_A$.
\end{defi}
\begin{defi}
    A morphism $p:E \rightarrow B$ of $G$-C*-algebras is called a $G$-Schochet fibration if for all $G$-C*-algebras $D$, the induced map
    \[
    \operatorname{Hom}(D,E) \rightarrow \operatorname{Hom}(D,B)
    \]
    is a Serre fibration.
\end{defi}
We now state our first theorem:
\begin{thm}
    The category of $G$-C*-algebras is a pointed category of fibrant objects with weak equivalences the $G$-homotopy equivalences, and fibrations the $G$-Schochet fibrations, whose homotopy category is the ordinary homotopy category.
\end{thm}
