\begin{rem} \label{rem: Hausdorff nu completion}
    In the sequel, we will refer to the functor
    \[
    (\nu-\operatorname{completion}) \circ (\operatorname{Haus. quotient}): G\text{-}\!\operatorname{lmc}\!C^*\operatorname{-alg} \rightarrow \GA
    \]
    as the Hausdorff $\nu$-completion.
\end{rem}
The following result is the equivariant analogue of the Arens-Michael decomposition theorem, compare \cite[Theorem 2.6]{MJ} and the references therein. The proof in the non-equivariant case carries over verbatim here:
\begin{lem} \label{lem: G-AM light}
    Let $A$ be a Hausdorff lmc. $G\text{-}C^*$-algebra. Then, there is a natural inclusion 
    \[
    A \subseteq \varprojlim\limits_{p \in \mathcal{S}(A)} A_p.
    \]
    Conversely, any $G$-invariant subalgebra of an inverse limit (in $G\text{-}\!\operatorname{Top*-Alg}$) of $G\text{-}C^*$-algebras is a Hausdorff lmc $G\text{-}C^*$-algebra
\end{lem}
\begin{cor}
    The group action on a Hausdorff lmc $G\text{-}C^*$-algebra $A$ is jointly continuous, that is, the map
    \begin{align*}
        G \times A &\rightarrow A\\
        (g,a) &\mapsto g.a
    \end{align*}
    is continuous.
\end{cor}
\begin{proof}
    In light of \cref{lem: G-AM light}, it suffices to show the assertion for an inverse limit of $G\text{-}C^*$-algebras (in $G\text{-}\!\operatorname{Top*-alg}$). But this is clear from the universal properties of inverse limits in $\operatorname{Top}$ (cf. \cref{rem: lim top non-eq}), and the fact that pointwise continuous group action on a $C^*$-algebra is in fact jointly continuous (since $C^*$-algebra (auto)morphisms are contractive, one can use \cite[Lemma 2.19]{D}).
\end{proof}
\subsection{Tensor products and function algebras}
We now discuss tensor products in the setting of lmc $G$-$C^*$-algebras.
\begin{defi}\label{defi: equi tensor prod}
    Let $A,B$ be lmc $G$-$C^*$-algebras. Let $A \odot B$ denote the algebraic tensor product of $A$ and $B$, together with the diagonal $G$-action. We equip $A \odot B$ with the initial topology given by the map
    \[
    A\odot B  \longrightarrow \varprojlim_{p \in \mathcal{S}(A), q \in \mathcal{S}(B)} {A_p} \otimes_G {B_q},
    \]
    where $A_p \otimes_G B_q$ denotes the \textit{maximal}\footnote{the choice of the tensor product is not very crucial at this juncture. But we decided to work with the maximal tensor product throughout because it has better functorial properties.} tensor product of the $G$-$C^*$-algebras $A_p$ and $B_q$ equipped with the diagonal $G$-action.

    Then, $A \otimes_G B$ denotes $A \odot B$ with the aforeprescribed topology.
\end{defi}
\begin{rem}
    Clearly, \cref{defi: equi tensor prod} is well-defined upon restricting to cofinal subsets of $\mathcal{S}(A)$ and $\mathcal{S}(B)$.
\end{rem}
That the tensor product of two continuous $*$-homomorphisms is again a continuous $*$-homomorphism follows from \cref{cor: factor}, whence we conclude:
\begin{cor}\label{cor: ten pro}
    The tensor product as defined above is functorial, i.e., we have a functor
    \[
    G\text{-}\!\operatorname{lmc C*-alg} \times G\text{-}\!\operatorname{lmc C*-alg} \xrightarrow{-\otimes_G-} G\text{-}\!\operatorname{lmc C*-alg}.
    \]
\end{cor}
Since $G$-equivariant continuous seminorms are cofinal in the set of all continuous seminorms on a lmc $G\text{-}C^*$-algebra, we conclude
\begin{cor}\label{cor: forget tensor}
    The following square commutes\footnote{the non-equivariant tensor product can be defined by taking $G$ to be the trivial group in \cref{defi: equi tensor prod}}:
    \[
    % https://q.uiver.app/#
\begin{tikzcd}
	{G\text{-}\!\operatorname{lmc C*-alg} \times G\text{-}\!\operatorname{lmc C*-alg}} && {G\text{-}\!\operatorname{lmc C*-alg}} \\
	{\operatorname{lmc C*-alg} \times \operatorname{lmc C*-alg}} && {\operatorname{lmc C*-alg}}
	\arrow["{-\otimes_G-}", from=1-1, to=1-3]
	\arrow["{\operatorname{forget} \times \operatorname{forget}}"', from=1-1, to=2-1]
	\arrow["{\operatorname{forget}}", from=1-3, to=2-3]
	\arrow["{-\otimes-}", from=2-1, to=2-3]
\end{tikzcd}
    \]
    Thus, the equivariant tensor product of lmc $G\text{-}C^*$-algebras is (uniquely) determined by the tensor product of the underlying lmc $C^*$-algebras, with the diagonal $G$-action.
\end{cor}
In light of the preceeding corollary, we will henceforth denote the tensor product in the equivariant setting also by $-\otimes-$.
\begin{defi}
    Let $A,B \in \GA$. Then, the tensor product of $A$ and $B$ (in $\GA$) is defined to be the Hausdorff $\nu$-completion of $A \otimes B$ from \cref{defi: equi tensor prod}. We will abuse notation and also denote the tensor product in $\GA$ by $- \otimes -$.
\end{defi}
We end this section with a discussion on function algebras in $\GA$. These will be ubiquitous for us while discussing the relation of homotopy in the next section. We first recapitulate the definition of the topology of uniform convergence in the generality of locally convex spaces. See \cite[Section 3.3]{TVS2} for more details and proofs.
\begin{defi}
    Let $X$ be a compact Hausdorff space, and $A \in G\text{-}\mathbb{A}$. The topology of uniform convergence on $\mathcal{C}(X,A)$ is the unique translation invariant topology on the set of continuous functions from $X$ to $A$, such that the collection of sets 
    \begin{equation}\label{eqn: nbhd base}
    \mathcal{U}_{\varepsilon,p_1,p_2,...,p_k}:=\{g \in \mathcal{C}(X,A) \mid p_i^X(g)< \varepsilon ~\forall~1 \leq i \leq k\}
    \end{equation}
    forms a neighbourhood base of $0$, where $\varepsilon > 0, k \in \N$, and $p_1,p_2,...,p_k \in \mathcal{S}(A)$, and for any $p \in \mathcal{S}(A)$, we let
    \[
    p^X(f):=\underset{x \in X}{\operatorname{sup}}~p(f(x)).
    \] 
\end{defi}

\begin{prop} \label{prop: CXB}
    Let $X$ be a compact Hausdorff space. If $B \in G\text{-}\mathbb{A}$, then $\mathcal{C}(X,B) \in G\text{-}\mathbb{A}$. If $B \in \GA$, then $\mathcal{C}(X,B) \in G\text{-}\A$. When $X$ is furthermore metrizable, $\C(X) \otimes B \cong \C(X,B)$.
\end{prop}  
\begin{proof}
    That $\mathcal{C}(X,B)$ is a locally multiplicative convex $C^*$-algebra with the collection $\{p^X \mid p \in \mathcal{S}(B)\}$ being a defining family of seminorms follows from \cite[Section 3.3]{TVS2}.  Note that $\C(X,B)$ carries a continuous $G$-action from \cref{lem: G-AM light}, and the fact that $\C(X,B)_{p^X} \cong \C(X,B_p)$ are $G$-$C^*$-algebras. The $\nu$-completeness of $\C(X,B)$ will follow from the $\nu$-completeness of $B$.

    To show the statement about tensor products, we will use some well known facts from general topology, for which we refer to \cite{MUN}. We first show that $\C(X) \odot B$ is dense in $\C(X,B)$. Let
    \[
    U_{g,\varepsilon,p_1,p_2,...,p_k}:=\{\tilde{g} \in \C(X,B) \mid p_i^X(g-\tilde{g})< \varepsilon ~\forall~1 \leq i \leq n \}.
    \]
    be an arbitrary (but fixed) basic open set in $\C(X,B)$. We want to show that it contains some element of $\C(X) \odot B$. Consider $g(X) \subseteq B$. From the compactness of $X$, we conclude that 
    \[
    g(X) \subseteq \bigcup_{i=1}^{n}U_{g(x_i),\varepsilon,p_1,p_2,...,p_k}, ~\text{where $x_1,x_2,...,x_n$ are points in X}.
    \]
    Set 
    \begin{equation}\label{eqn: open set}
        U_i:=g^{-1}U_{g(x_i),\varepsilon,p_1,p_2,...,p_k},
    \end{equation}
    and note that $X=\bigcup_{i=1}^nU_i$. Choose a partition of unity $\{h_i\}_{i=1}^{n}$ subordinate to this cover, such that $\operatorname{supp}(h_i) \subseteq U_i$. Then, for any $x \in X$, and for any $l \in \{1,...,k\}$, we calculate:
    \begin{align*}
        p_l(g(x)-\sum_{i=1}^{n}h_j(x)g(x_j))
        =p_l(\sum_{i=1}^{n}h_j(x)g(x)-\sum_{i=1}^{n}h_j(x)g(x_j)) 
        \leq \sum_{i=1}^{n}h_j(x)p_l(g(x)-g(x_j)) <\sum_{j=1}^{n}h_j(x)\varepsilon
        =\varepsilon,
    \end{align*}
where the last inequality follows from the definition of $U_i$ in \cref{eqn: open set}. Thus, the function
\begin{equation}\label{eqn: C(X).B}
    x \mapsto \sum_{i=1}^{n}h_j(x)g(x_j).
\end{equation}
lies in $U_{g,\varepsilon,p_1,p_2,...,p_k}$, showing that $\C(X) \odot B$ is dense in $\C(X,B)$.

    We now show that, when $X$ is metrizable, given $g \in \C(X,B),$ there exists a $\nu$-Cauchy sequence in $\C(X) \odot B$ converging to $g$. To that end, it suffices to show that there is a $\nu$-Cauchy sequence in $\C(X) \odot \langle \operatorname{im} g \rangle$ converging to $g$ in $\C(X,\langle \operatorname{im}g \rangle) \hookrightarrow \C(X,B)$, where $\langle \operatorname{im} g \rangle$ denotes the $*$-subalgebra of $B$ generated by $\operatorname{im}g$, equipped with the subspace topology. Note that, 
\begin{align*}
    \lvert \operatorname{im} g \rvert \leq \lvert X \rvert \leq \lvert \R \rvert 
    \implies \lvert \mathcal{S}(\langle \operatorname{im} g \rangle) \rvert \leq \lvert \R \rvert^{\lvert \R \rvert }=2^{2^{\lvert \N \rvert}},
\end{align*} 
which shows, in light of \cref{eqn: nbhd base}, that $\C(X,\langle \operatorname{im}g \rangle)$ has a neighborhood base of $g$ of cardinality less than or equal to $2^{2^{\lvert \N \rvert}}$. From the proof of the first part of this proposition, especially \cref{eqn: C(X).B}, we conclude that there exists a $\nu$-Cauchy sequence in $\C(X) \odot \langle \operatorname{im}g \rangle$ which converges to $g$.
\end{proof}
\begin{rem}
    We have an analogous result to \cref{prop: CXB} in the setting of pointed spaces, which we don't spell out here. That can be obtained by focusing on the ideal of functions vanishing at the base point.
\end{rem}
We end this section by a technical lemma, which will come handy in the next section.
\begin{lem}\label{lem: pushout to pullback}
    For each $B$ in $\GA$, the functor $\C(-,B)$ sends a pushout square of closed inclusions of compact Hausdorff spaces to a pullback square in $\GA$.
\end{lem}
\begin{proof}
    Let $X_{11}=X_{01}\coprod_{X_{00}}X_{10}$ be a pushout in compact Hausdorff spaces as mentioned in the statement. Then, by the universal property of colimits, we get a pullback of \textit{sets}
    \begin{equation}\label{eqn: pullback}
         \C(X_{11},B) \cong \C(X_{01},B) \times_{\C(X_{00},B)}\C(X_{10},B).
    \end{equation}
    By the explicit description of pullbacks in sets, we conclude that the pullback in \cref{eqn: pullback} is a pullback of \textit{$*$-algebras}. We next note that it is also a pullback in \textit{topological spaces}. Indeed, we have a natural continuous bijection 
    \[
    \C(X_{11},B) \xrightarrow{} \C(X_{01},B) \times^{\operatorname{Top}}_{\C(X_{00},B)}\C(X_{10},B).
    \]
    That its a homeomorphism follows by the explicit definition of convergence of a net in the uniform topology. This shows that \cref{eqn: pullback} is a pullback in $\operatorname{Top}\!*\operatorname{-alg}$, see \cite[Lemma III.2.1]{MAL}. That its in fact a pullback in $\GA$ follows from \cref{cor: forget preserve lim/colim} and \cref{cor: eq bicom}.   
\end{proof}
