\begin{tikzcd}
	B & B \\
	D & 0
	\arrow["{=}", from=1-1, to=1-2]
	\arrow["g"', from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow["r"{description}, dashed, from=2-1, to=1-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd},
    \]
