\begin{abstract}
This paper aims to study the periodicity of a transcendental entire function of hyper-order less than one. For a transcendental entire function of hyper order less than one and a non-zero complex constant $c$, $\mathfrak{f} (z) \equiv \mathfrak{f} (z + c)$ if they share a certain set with weight two.
\end{abstract}

\section{Introduction}
The main tool we used to prove our main results is value distribution  theory \cite{05}.\\
Let $E$ denote any set of positive real numbers with finite Lebesgue measure, where $E$ may vary in each occurrence. We use $M(\mathbb{C})$ to denote the field of all meromorphic functions defined in $\mathbb{C}$. Let $\mathfrak{f}\in M(\mathbb{C})$ and $ S\subset \mathbb{C} \cup \{\infty\} $ be a non-empty set with distinct elements. We set
$$ E_{\mathfrak{f}}(S) = \bigcup_{a \in S} \{z:\mathfrak{f}(z)-a=0\},$$ where a zero of $\mathfrak{f}-a$ with multiplicity $m$ counts $m$ times in $ E_{\mathfrak{f}}(S)$. Let $ \overline{E}_{\mathfrak{f}}(S)$ denote the collection of distinct elements in $ E_{\mathfrak{f}}(S)$.\\
Let $\mathfrak{g}\in M(\mathbb{C})$. We say that two function $\mathfrak{f}$ and $\mathfrak{g}$ share the set $S$ CM (res. IM) if $ E_{\mathfrak{f}}(S)=  E_{\mathfrak{g}}(S)$ (resp., $ \overline{E}_{\mathfrak{f}}(S) =  \overline{E}_{\mathfrak{g}}(S)$).\\
The order and the hyper-order of $\mathfrak{f}$, respectively denoted by $\rho(\mathfrak{f})$ and $\rho_2(\mathfrak{f})$, are defined as
$$\rho_(\mathfrak{f}):=\limsup_{r\to\infty}\frac{\log T(r,f)}{\log r},~~\text{and}~~\rho_{2}(\mathfrak{f}):=\limsup_{r\to\infty}\frac{\log \log T(r,f)}{\log r}.$$
For any non-constant meromorphic function $\mathfrak{f}$, we denote by $S(r,\mathfrak{f})$, any quantity satisfying $$ S(r,\mathfrak{f})=o(T(r,\mathfrak{f}))~~~\text{as}~~ r \rightarrow \infty, r \notin E. $$
By \emph{shift} of $\mathfrak{f}(z)$, we mean $\mathfrak{f}(z+c)$, where $c$ is a non-zero complex constant. Now, we recall some well-known definitions from the literature.
\begin{defi} (\cite{14})
Let $ a\in \mathbb{C} \cup \{\infty\}$. For a positive integer $k$, we define
\begin{enumerate}
\item[(i)] $N_{k)}(r,a; \mathfrak{f})$ as the counting function of $a$- points of $\mathfrak{f}$ with multiplicity $\leq k$,\\
\item[(ii)] $N_{(k}(r,a; \mathfrak{f})$ as the counting function of $a$- points of $\mathfrak{f}$ with multiplicity $\geq k$.
\end{enumerate}
\end{defi}
Similarly, the reduced counting function $\overline{N}_{k)}(r,a; \mathfrak{f})$ and $\overline{N}_{(k}(r,a; \mathfrak{f})$ are defined.
\begin{defi}(\cite{08})
Let $k\in \mathbb{N}$. We define $N_{k}(r,0; \mathfrak{f})$ as the counting function of zeros of $\mathfrak{f}$, where a zero of $\mathfrak{f}$ with multiplicity $q$ is counted $q$ times if $ q\leq k$, and is counted $k$ times if $q>k$.
\end{defi}
\begin{defi} (\cite{04})
A non-constant monic polynomial $P(z)$ is said to be a strong uniqueness polynomial for meromorphic function, if $P(\mathfrak{f})\equiv \alpha P(\mathfrak{g})$ implies $\mathfrak{f} \equiv \mathfrak{g}$ for any two non-constant meromorphic functions $\mathfrak{f}$ and $\mathfrak{g}$ and $\alpha$ is a non-zero constant.
\end{defi}
In 1977, Rubel and Yang \cite{17} first investigated the uniqueness of an entire function concerning its first derivatives and proved the following result:
\begin{theoA}
Let $\mathfrak{f}$ be a non-constant entire function and $a$, $b$ be two distinct finite complex values. If $ \mathfrak{f}(z)$ and $ \mathfrak{f'}(z)$ share $a$, $b$ CM, then $\mathfrak{f}(z) \equiv \mathfrak{f'}(z)$.
\end{theoA}
In 1979, Mues and Steinmetz \cite{12} improved Theorem A by replacing CM sharing by IM sharing.
\begin{theoB}
Let $\mathfrak{f}$ be a non-constant entire function and $a$, $b$ be two distinct finite complex values. If $ \mathfrak{f}(z)$ and $ \mathfrak{f'}(z)$ share $a$, $b$ IM, then $\mathfrak{f}(z) \equiv \mathfrak{f'}(z)$.
\end{theoB}
In 2011, Heittokanges et al. \cite{07} proved a similar analogue of Theorem A concerning their shifts.
\begin{theoC}
Let $\mathfrak{f}$ be a non-constant entire function of finite order, let $c$ be a nonzero finite complex value, and let $a$, $b$ be two distinct finite complex values. If $ \mathfrak{f}(z)$ and $ \mathfrak{f}(z+c)$ share $a$, $b$ CM, then $\mathfrak{f}(z) \equiv \mathfrak{f}(z+c)$.
\end{theoC}
In the same year, Qi \cite{13} further improved the Theorem C.
\begin{theoD}
Let $\mathfrak{f}$ be a non-constant entire function of finite order, let $c$ be a nonzero finite complex value, and let $a$, $b$ be two distinct finite complex values. If $ \mathfrak{f}(z)$ and $ \mathfrak{f}(z+c)$ share $a$, $b$ IM, then  $\mathfrak{f}(z) \equiv \mathfrak{f}(z+c)$.
\end{theoD}
In 2010, Zhang \cite{18, 19} considered the uniqueness between $\mathfrak{f}(z)$ and its shift $\mathfrak{f}(z+c)$ when they share two sets and obtain the following result:
\begin{theoE} \cite{18}
Let $c \in \mathbb{C}$, $S_1=\{1,\omega,\omega^2,\ldots \omega^{n-1}\}$ and $ S_2=\{\infty\}$. Suppose $\mathfrak{f}(z)$ is a non-constant meromorphic function of finite order such that $E_{\mathfrak{f}(z)}(S_j, \infty)=E_{\mathfrak{f}(z+c)}(S_j, \infty)$ for $j=1,2$ with $n\geq 4$. Then $\mathfrak{f}(z)\equiv t \mathfrak{f}(z+c)$, where $t^{n}=1$.
\end{theoE}

