-0.000 & \phantom{-}1.000 & \phantom{-}0.000 \\
-0.000 & \phantom{-}0.000 & \phantom{-}0.982 \\
-0.000 & -0.000 & \phantom{-}0.188
\end{bmatrix}
\approx \mathbf{A}_{\text{gt}}, \quad
\widetilde{\mathbf{O}}^\top \, \widetilde{\mathbf{\Theta}}_{\text{out}} \, \widetilde{\mathbf{O}}
\approx
\begin{bmatrix}
