    \smallskip



\noindent{\bf Inductive step.} In the inductive step, suppose that $C_{2k-1}$ and $C_{2k}$ have been chosen.  For each square $Q_k$ in $C_{2k}$, we subdivide $Q_k$ into $2^{4n_{2k+1}}$ many squares and choose $2^{3n_{k+1}}$ of them. We will require 

\smallskip

\begin{enumerate}
    \item [${\bf (*)}_k$] For all $Q_k$ in $C_{2k}$, and for each column of width $4^{-(n_1+\cdots+n_{2k+1})}$ of the subdivision of $Q_k$,  exactly $2^{n_{k+1}}$ squares from each column are chosen.
\end{enumerate}
\smallskip

\noindent Denote the collection of all of these squares obtained from all $Q_k$ by $C_{2k+1}$.

We now further subdivide each square in $C_{2k+1}$ into $2^{4n_{2k+2}}$ many subsquares and choose $2^{n_{2k+2}}$ many squares satisfying the following conditions:
\smallskip

\begin{enumerate}
    \item [${\bf (*~*)}_k$] In each column of width $4^{-(n_1+\cdots+n_{2k+2})}$ in each $Q_k$ from $C_{2k}$, at least one square is chosen.
    \item [${\bf (***)}_k$] For both the $45^{\circ}$ and $-45^{\circ}$ orthogonal projections, there exist at least two squares whose projections overlap exactly.
\end{enumerate}
\smallskip



By a similar argument as Lemma \ref{lemma1}, provided that $n_{2k+1}\ge n_{2k+2}$, ${\bf (*~*)}_k$ can always be satisfied. We let $C_{2k+2}$ be the collection of chosen squares at scale $4^{-(n_1+\cdots+n_{2k+2})}$.   This completes the inductive step. Our Cantor set is
$$
C = \bigcap_{k=1}^{\infty} C_{k},
$$
and we will say that $C$ is a Cantor set generated by the sequence $\{n_k\}_{k=1}^{\infty}$. We notice that the construction of squares in $C_{2k+2}$ may be completely independent in each $Q_k$ from $C_{2k}$, so we will also consider the following additional condition:

\smallskip

$({\mathsf M}):$ The patterns of squares at scale $4^{-(n_1+\cdots +n_{2k+2})}$ in $Q_k$ are the same for all  $Q_k$ in $C_{2k}$.

\smallskip

\noindent This will make $C$ a {\it Moran fractal cube}, which is a commonly used name in the literature.

First, $C$ satisfies condition (1) of Proposition \ref{prop-K}:

\begin{proposition}\label{prop_proj}
    $\pi_0(C) = [0,1]$.  
\end{proposition}

\begin{proof}
    For all $x_0\in[0,1]$, the line $x=x_0$ always passes through some square $Q_2$ from $C_2$, by $({\bf *})_1$ and $({\bf *~*})_1$. By induction with $({\bf *})_k$ and $({\bf *~*})_{k}$, we can find a nested sequence of cubes $Q_2\supset Q_4\supset\cdots$, where $Q_{2k}$ is drawn from $C_{2k}$, such that the line $x=x_0$ intersects all $Q_{2k}$. Hence, the line $x=x_0$ intersects $C$.
\end{proof}

\subsection{Hausdorff and packing dimension.} The following is our main result about the dimensions of the Cantor set $C$, which when combined with Proposition \ref{prop_proj}, gives a compact set satisfying all the conditions of Proposition \ref{prop-K}.

\begin{proposition}\label{prop3.3}
    There exists a sequence $\{n_k\}_{k=1}^{\infty}$ with $n_{2k-1}\ge n_{2k}$ for all $k$ such that the Cantor set $C$ it generates satisfies
    \begin{enumerate}
    \item $0<{\mathcal H}^1(C)<\infty$, i.e., $\hdim C = 1$;
    \item $\pdim(C) >1$; 
    \item $m^{1} (\pi_{\pm} (C)) = 0$,
    \end{enumerate}
    where $\pi_{\pm}$ are, respectively, the orthogonal projections onto $y=\pm x$. 
\end{proposition}

\begin{proof} It suffices to choose $n_{2k-1} = n_{2k}$, for all $k\ge 1$. We remark that a more general proof is possible, but we do not pursue it here.  Proceeding inductively  on pairs of indices, we first pick $n_1=n_2 = 1$, and we repeat $m_1$ times the construction with the pair $(n_1,n_2)$, so that 
\begin{equation}\label{eq_m-1-condition}
\left(1-\frac{1}{4^{n_1+n_2}}\right)^{m_1}<\frac12.
\end{equation}
Assuming that the construction has been repeated $m_k$ times on the pair $(n_{2k-1}, n_{2k})$, so that
\begin{equation}\label{eq_m-k-condition}
\left(1-\frac{1}{4^{n_{2k-1}+n_{2k}}}\right)^{m_k}<\frac{1}{2^{k}},
\end{equation}
we choose $(n_{2k+1}, n_{2k+2})$ satisfying 
\begin{equation}\label{eq_n-k-condition}
\frac{\sum_{j=1}^{k}m_j(3n_{2j-1}+n_{2j})}{n_{2k+1}}< \frac{1}{100} \hspace{10pt} \mbox{and} \hspace{10pt}  \frac{\sum_{j=1}^{k}m_j(2n_{2j-1}+2n_{2j})}{n_{2k+1}}< \frac{1}{100}
\end{equation}
and repeat $m_{k+1}$ times the construction on the pair $(n_{2k+1},n_{2k+2})$, so that 
\begin{equation}\label{eq_m-{k+1}-condition}
\left(1-\frac{1}{4^{n_{2k+1}+n_{2k+2}}}\right)^{m_{k+1}}<\frac{1}{2^{k+1}}.
\end{equation}
The resulting Cantor set $C$ is generated by the sequence
$$
(\underbrace{(n_1,n_2),\cdots, (n_1,n_2)}_{m_1 \ \text{times}}, \cdots, \underbrace{(n_{2k-1},n_{2k}),\cdots, (n_{2k-1},n_{2k})}_{m_k \ \text{times}}, \cdots),
$$
so that $(\ast)_k$, $(\ast~\ast)_k$, and $(\ast\ast\ast)_k$ are satisfied, for all $k\ge 1$.

\medskip

We next verify each of the conditions:

\noindent (1).    Let $\delta_k = 4^{-[m_1(n_1+n_2)\cdots+ m_k(n_{2k-1}+n_{2k})]}$ and $\delta_k' = \delta_k\cdot 4^{-n_{2k+1}}$. Denote by  $M_k$ and $M_k'$ the total number of squares of side lengths $\delta_k$ and $\delta_k'$, respectively. By our construction,  $M_{k} = 2^{m_1(3n_1+n_2)+m_2(3n_3+n_4)+\cdots+m_k(3n_{2k-1}+n_{2k})}$. Note that the squares of side length $\delta_k$ have diameter $\sqrt{2} \delta_{k}$ and form a covering of the set $C$, so 
 \begin{equation}\label{eq_hdim}
    \begin{aligned}
    {\mathcal H}^1(C)\le & \sqrt{2} \cdot  \liminf_{k\to\infty} (M_{k}\cdot \delta_{k})\\
    % = &\sqrt{2} \liminf_{k\to\infty} e^{\log (M_{2k}\cdot\delta_k)} \\
      = & \sqrt{2} \liminf_{k\to\infty} 2^{(m_1(n_1-n_2)+\cdots+m_k(n_{2k-1}-n_{2k}))}  = \sqrt{2}<\infty,
   \end{aligned}
    \end{equation}
since we have chosen $n_{2k-1} = n_{2k}$, for all $k\ge 1$. On the other hand, ${\mathcal H}^1(C) \geq {\mathcal H}^1(\pi_0(C))$, so by Proposition \ref{prop_proj}, ${\mathcal H}^1(C)>0$.

\smallskip

\noindent(2). Using Proposition \ref{prop-fractal-cube} for $C$, which is a special case of fractal cubes, the packing dimension of $C$ is 
$$
\begin{aligned}
\pdim(C)\ge& \limsup_{k\to\infty} \frac{\log M_{k}' }{-\log \delta_{k}'}\\
=& \limsup_{k\to\infty} \frac{\log 2^{[m_1(3n_1+n_2)+\cdots+m_k(n_{2k-1}+ n_{2k})]+3n_{2k+1}}}{\log 2^{2[m_1(n_1+n_2)\cdots +m_k(n_{2k-1}+n_{2k})+n_{2k+1}]}}\\
%=&\limsup_{k\to\infty} \frac{3n_1+n_2+\cdots 3n_{2k-3}+n_{2k-2} +3n_{2k-1}}{2n_1+\cdots+2n_{2k-2}+2n_{2k-1}}\\
= & \limsup_{k\to\infty} \frac{\frac{\sum_{j=1}^{k}m_j(3n_{2j-1}+n_{2j})}{n_{2k+1}} +3}{\frac{\sum_{j=1}^{k}m_j(2n_{2j-1}+2n_{2j})}{n_{2k+1}}+2}>1,
\end{aligned}
$$
where we used (\ref{eq_n-k-condition}) in the last line.

\smallskip


\noindent (3). To establish (3), we will require $C$ to satisfy $({\mathsf M})$.  We notice that the Cantor set $C$ is contained in $2^{3n_1+n_2}$ squares of side length $4^{-(n_1+n_2)}$. By ${\bf (***)}_1$,  there is at least one pair of squares that overlap exactly when $C$ is projected to $45^{\circ}$, so $\pi_{+}(C)$ is contained in at most $4^{n_1+n_2}-1$ many intervals of length $\sqrt{2}\cdot4^{-(n_1+n_2)}$. Hence, 
$$
m^1(\pi_+(C)) \le \sqrt{2} \cdot \left(1-\frac1{4^{n_1+n_2}}\right).
$$
Note that for each square of side length $4^{-(n_1+n_2)}$ in the first iteration of the construction, there are $2^{3n_1+n_2}$ squares of side length $4^{-2(n_1+n_2)}$ in the second stage (using indices $(n_1,n_2)$ still). Since at least one pair of such squares overlaps exactly when projected to $45^{\circ}$ and the Cantor set satisfies $({\mathsf M})$,  there are at most $(4^{n_1+n_2}-1)^2$ different intervals of length $\sqrt{2}\cdot 4^{-2(n_1+n_2)}$ after the projection. They cover $\pi_+(C)$, so 
$$
m^1(\pi_+(C)) \le \sqrt{2} \cdot \left(1-\frac1{4^{n_1+n_2}}\right)^2.
$$
Proceeding inductively, using ${\bf (***)}_k$, we find that 
$$
m^1(\pi_{+}C) \le \sqrt{2}\cdot \prod_{j=1}^{\infty}\left(1-\frac{1}{4^{n_{2j-1}+n_{2j}}}\right)^{m_j} \le \sqrt{2}\cdot\prod_{j=1}^{\infty} \frac{1}{2^j} = 0,
$$
by (\ref{eq_m-k-condition}). The same argument also works for $\pi_-(C)$. 
\end{proof}
