\section{Non-Trivial Constructions of Higher-Dimensional Kakeya sets}\label{section4}

In this section, we provide simple constructions of measure zero sticky and non-sticky Kakeya sets on $\R^d$ that are {\it not} given by a Cartesian product of a two-dimensional Kakeya set with $\R^{d-2}$. This appears to be unknown in the literature.  We also prove that both sets has Hausdorff dimension $d$.

\subsection{A Sticky Kakeya set on $\R^d$.} Instead of using the point-line duality presentation (\ref{eqL_va}), we construct the sticky Kakeya set by drawing lines between two Cantor sets as in \cite{Stein-real}, so that readers can visualize the construction easily (see Figure \ref{Fig-2}). Let $C_0$ be the self-similar Cantor set on $\R^1$ consisting of points whose $4$-adic expansions have digits $0,3$ only, i.e.,
$$
C_0 = \left\{\sum_{j=1}^{\infty}4^{-j}\varepsilon_j: \varepsilon_j\in\{0,3\}\right\}.
$$
On $\R^{d-1}$, let $C_{d-1} = C_0\times \cdots \times C_0$ ($d-1$ times).
 A crucial observation to proving our main theorem is that for all $t\in\R$, the Minkowski sum
    $$
    C_{d-1}+tC_{d-1} = (C_0+tC_0)\times\cdots\times (C_0+tC_0).
    $$

\begin{lem}\label{lemma4.1} The set $C_{d-1}+tC_{d-1}$ has the following properties:
      \begin{enumerate}
        \item  When $t = -1/2$, $C_0+tC_0 =[-\frac12,1]$ and  $C_{d-1}+tC_{d-1} = [-\frac12,1]^{d-1}$.
        \item $m^{d-1}(C_{d-1}+tC_{d-1}) = 0$, for almost all $t\in\R$. 
        \item $\hdim (C_{d-1}+tC_{d-1}) = d-1$, for almost all $t\in\R$. 
    \end{enumerate}
\end{lem}


\begin{proof}
    Property (1) follows from a direct calculation. For (2), it is known that $m^1(C_0+tC_0) = 0$, for almost all $t\in \R$ (see, e.g., \cite{Stein-real} or \cite{Mattila_2015}). By Fubini's theorem,   $m^{d-1}(C_{d-1}+tC_{d-1}) = 0$ follows.

    To see (3), it is well-known that $C_0+tC_0$ is the image of the orthogonal projection of the Cantor set $C_0\times C_0$ in $\R^2$ onto the subspace $y = tx$. By Marstrand's projection theorem (see, e.g., \cite[Section 2.3]{BKS2024}), for almost all $t\in \R$,  $\hdim(C_0+tC_0) = \hdim (C_0\times C_0) = 1$. Since $\pdim(C_0+tC_0)$ is bounded below by $\hdim(C_0+tC_0)$, we have $\pdim(C_0+tC_0) = 1$, as well. Hence, the product inequality for Hausdorff dimension \eqref{hdimeq1} implies $\hdim(C_{d-1}+tC_{d-1}) = d-1$, for almost all $t\in\R$.
\end{proof}


Let $C = \frac12C_{d-1}\times \{0\}$ and $C' = C_{d-1}\times \{1\}$, and for each $a,b\in \R^d$, let $\ell(a,b)$ denote the line joining $a,b$. Define
$$
{\mathbb B} = \bigcup_{(a,b)\in C\times C'} \ell(a,b).
$$
\begin{theorem}
   A finite union of rotated copies of ${\mathbb B}$ is a compact Kakeya set. This Kakeya set is sticky, has Lebesgue measure zero, and has Hausdorff dimension $d$. 
\end{theorem}


\begin{proof}
The set of all directions in ${\mathbb B}$ is exactly equal to 
$$
C'-C = \left(C_{d-1}-\frac12 C_{d-1} \right)\times \{1\}.
 $$   
By Lemma \ref{lemma4.1} (1), the direction set covers a region in $\R^{d-1}\times \{1\}$ with non-empty interior, so the projection of this set onto the unit sphere $S^{d-1}$ has non-empty interior. Thus, a finite union of rotations of ${\mathbb B}$ will have its directions cover $S^{d-1}$, hence the union is a Kakeya set. 

To verify the set is sticky, we compute ${\mathcal A}_{\mathbb B}$ as 
$$
{\mathcal A}_{\mathbb B} = \bigcup_{a\in \frac{1}{2}C_{d-1}}  \left(C_{d-1}-a\right)\times \{a\}.
$$
This set is bi-Lipschitz equivalent to $C_{d-1}\times C_{d-1}$ via the bi-Lipschitz map $(x,y)\mapsto (y-2x,2x)$, and it has Hausdorff dimension $d-1$, since $\pdim(C_0) = \hdim(C_0) = 1/2$.



