To show that the Kakeya set has Lebesgue measure zero and Hausdorff dimension $d$, we compute the slice ${\mathbb B}\cap \{x_d = \lambda\}$ for $\lambda\in(0,1)$. Indeed, 
$$
{\mathbb B}\cap \{x_d = \lambda\} = \left\{((1-\lambda)a+\lambda b,\lambda): (a,b)\in C\times C'\right\}.
$$
Letting $t = \frac{1-\lambda}{\lambda}$ and factoring out $\lambda$, the slice is a rescaling of $C_{d-1}+tC_{d-1}$. By Lemma \ref{lemma4.1} (2) and (3), the slice has Lebesgue measure zero and Hausdorff dimension $d-1$, for almost all $t\in\R$ and hence $\lambda\in(0,1)$. By Fubini's theorem, ${\mathbb B}$ has measure zero. Finally, by Marstrand's slicing theorem (see, e.g., \cite[Section 2.4]{BKS2024}), 
$$
\hdim({\mathbb B}) \ge 1+ \hdim({\mathbb B}\cap \{x_d = \lambda\}) = 1+(d-1) = d,
$$
for almost all $\lambda$.
\end{proof}



\subsection{Non-sticky Kakeya sets on $\R^d$.} We now provide a construction of a non-trivial non-sticky Kakeya set in $\R^{d}$. Let $C$ be the Cantor set on $\R^2$ from Proposition \ref{prop3.3} that leads to the non-sticky Kakeya set in $\R^2$. Unlike the sticky construction above, $C$ cannot be decomposed as the Cartesian product of two identical Cantor sets. Modifying our technique, we use $C$ as the basic set and consider the Cartesian product $C^{d-1} \subset \R^{2d-2}$ in the parameter space of lines. This time we view
$$
({\bf v}, {\bf a}) = (v_1,a_1) \times \cdots \times (v_{d_1}, a_{d-1}) \in C^{d-1}.
$$
\begin{theorem}
A finite union of rotated copies of
$$
\mathbb{K}_0 = \bigcup_{({\bf v}, {\bf a})\in C^{d-1}} L_{{\bf v}, {\bf a}}
$$
is a non-sticky Kakeya set of Lebesgue measure zero and Haudorff dimension $d$.
\end{theorem}


\begin{proof}
By Proposition \ref{prop_proj}, $\pi_0(C)$ has non-empty interior in $\R^1$, so under the projection
$$
\widetilde{\pi}_0(v_1,a_1, \dots, v_{d-1},a_{d-1}) = (v_1, \dots, v_{d-1}),
$$
the interior
$$
[\widetilde{\pi}_0(C^{d-1})]^{\mathrm{o}} = \pi_0(C)^{\mathrm{o}}\times\cdots\times \pi_0(C)^{\mathrm{o}} \neq \varnothing.
$$
By Proposition \ref{prop0}, modified to use $\Tilde{\pi}_0$ in place of $\pi_0$, a finite union of rotated copies of $\mathbb{K}_0$ is a Kakeya set in $\R^{d}$. By the product inequality for packing dimension \eqref{hdimeq2} and Proposition \ref{prop3.3} (2),
$$d - 1 < 1 + (d-2)\cdot\pdim(C) \le \pdim(C^{d-1}) \leq (d-1)\cdot\pdim(C),$$
so since $\mathcal{A}_{\mathbb{K}_0} = C^{d-1}$,
the Kakeya set is non-sticky.

For $i= 1, \dots, d-1$, define $e_i = (0, \dots, 0, t, 1, 0, \dots, 0)$, where $t$ appears in the $(2i-2)^{\mathrm{nd}}$ entry and 1 appears in the $(2i-1)^{\mathrm{st}}$ entry.  Note that 
$$
 L_{{\bf v}, {\bf a}} = \{(tv_1+a_1,\cdots, tv_{d-1}+a_{d-1},t): t\in[0,1]\}
$$Then the slice of $\mathbb{K}_0$ at $z = t$ is exactly the following $d-1$ product:
$$
W_t = \pi_t(C)\times\cdots\times \pi_t(C).
$$
Since $m^1(\pi_t(C)) = 0$, for almost all $t \in \R$, by Fubini's theorem, $W_t$ has $(d-1)$-dimensional Lebesgue measure zero,
for almost all $t \in \R$. Then by Fubini's theorem again, $\mathbb{K}_0$ has measure zero, so the Kakeya set also has measure zero.

Finally, we show that this Kakeya set has full Hausdorff dimension. As $\hdim C = 1$, $\hdim(\pi_t (C)) = 1$, for almost every $t$, by Marstrand's projection theorem.   By the product inequality for Hausdorff dimension (\ref{hdimeq1}), $\hdim W_t\ge d-1$. By Marstrand's slicing theorem, $\hdim({\mathbb K}_0) = d$, so the Kakeya set has Hausdorff dimension $d$.
\end{proof}

We remark that we can always produce a Kakeya set in $\R^d$ using the above procedure when we can construct $C$ in $\R^2$ satisfying Proposition \ref{prop-K} with (1), (3) and (4). It will be non-sticky if we also have (2). 

